      { "bt7274_say_follow_1", "Copy that, Pilot.", 1.60 },
      { "bt7274_say_follow_2", "Copy that, Pilot.", 1.24 },
    } },
    hold = { every = 0.0, lines = {
      { "bt7274_say_hold_1", "I will remain here.", 1.52 },
    } },
    wait = { every = 0.0, lines = {
      { "bt7274_say_wait_1", "Noted.", 0.68 },
    } },
    call = { every = 0.0, lines = {
      { "bt7274_say_call_1", "Trust me.", 0.92 },
      { "bt7274_say_call_2", "Yes. Trust me.", 1.80 },
      { "bt7274_say_call_3", "Protocol 3.", 1.28 },
      { "bt7274_say_call_4", "Protocol three: Protect the Pilot.", 2.96 },
      { "bt7274_say_call_5", "Pilot, I am tracking your location.", 2.05 },
      { "bt7274_say_call_6", "Marking your HUD.", 1.16 },
      { "bt7274_say_call_7", "Ready to proceed.", 1.32 },
      { "bt7274_say_call_8", "I will support you in the pursuit of valid mission objectives. Ready to proceed.", 5.00 },
    } },
    callFight = { every = 0.0, lines = {
      { "bt7274_say_callFight_1", "Your fear is justified, but I will do my best to protect you.", 3.56 },
      { "bt7274_say_callFight_2", "Given our dire circumstances, this is a risk worth taking.", 3.92 },
      { "bt7274_say_callFight_3", "Trust me. I have done the math.", 4.20 },
    } },
    fall = { every = 0.0, lines = {
      { "bt7274_say_fall_1", "Adjusting for wind resistance... Calculating...", 3.20 },
      { "bt7274_say_fall_2", "Brace for impact.", 1.28 },
      { "bt7274_say_fall_3", "Calculating...", 1.96, skip = true },
      { "bt7274_say_fall_4", "There is a 68 percent chance of success.", 2.56 },
      { "bt7274_say_fall_5", "Wind: 3 knots, heading 274. Range: 95 meters.", 4.80 },
    } },
    landed = { every = 0.0, lines = {
      { "bt7274_say_landed_1", "New chassis. Same data core. BT-7274 good to go.", 5.44 },
      { "bt7274_say_landed_2", "BT-7274 online and ready for combat.", 3.78 },
      { "bt7274_say_landed_3", "Embark when ready.", 1.44 },
      { "bt7274_say_landed_4", "It is good to see you too, Pilot.", 1.84 },
      { "bt7274_say_landed_5", "Visual contact reestablished with Pilot. Commencing supporting fire. Danger close.", 4.88 },
      { "bt7274_say_landed_6", "It is time to complete our mission.", 2.20 },
      { "bt7274_say_landed_7", "It is good to see you as well.", 1.96 },
      { "bt7274_say_landed_8", "Prepare yourself, Pilot.", 1.53 },
      { "bt7274_say_landed_9", "Down here.", 0.96 },
    } },
    refuse = { every = 0.0, lines = {
      { "bt7274_say_refuse_1", "Analysis - low clearance.", 2.32 },
      { "bt7274_say_refuse_2", "I would accompany you but unfortunately my chassis will not fit through the door.", 4.36 },
      { "bt7274_say_refuse_3", "Pilot, I am tracking your location. Recommend you seek an exit.", 3.88 },
      { "bt7274_say_refuse_4", "Negative.", 0.70 },
      { "bt7274_say_refuse_5", "That would be in violation of Protocol 3.", 2.66 },
      { "bt7274_say_refuse_6", "Unlikely, Pilot.", 1.06 },
      { "bt7274_say_refuse_7", "You must find another way out.", 1.76 },
    } },
    away = { every = 0.0, lines = {
      { "bt7274_say_away_1", "I am still working on it, Pilot.", 1.72 },
      { "bt7274_say_away_2", "Core is recharging.", 1.56 },
      { "bt7274_say_away_3", "Re-initializing critical systems...", 2.24 },
      { "bt7274_say_away_4", "My systems are rebooting...", 1.76 },
    } },
    gone = { every = 0.0, lines = {
      { "bt7274_say_gone_1", "Power low. Insufficient power.", 3.36 },
      { "bt7274_say_gone_2", "Pilot, recommend you disembark.", 2.16 },
      { "bt7274_say_gone_3", "Recommend you disembark.", 1.56 },
    } },
    throw = { every = 0.0, lines = {
      { "bt7274_say_throw_1", "I will not lose another Pilot.", 2.12 },
      { "bt7274_say_throw_2", "Trust me.", 0.92 },
    } },
    leave = { every = 0.0, lines = {
      { "bt7274_say_leave_1", "Good luck, Pilot.", 2.12 },
      { "bt7274_say_leave_2", "Good luck, Pilot.", 1.08 },
      { "bt7274_say_leave_3", "I will meet you on the other side.", 2.02 },
      { "bt7274_say_leave_4", "I will continue repairing myself to the extent I am capable.", 3.45 },
    } },
    home = { every = 0.0, lines = {
      { "bt7274_say_home_1", "Standing by, Pilot.", 1.17 },
      { "bt7274_say_home_2", "Understood.", 0.89 },
      { "bt7274_say_home_3", "For now. Yes.", 1.60 },
      { "bt7274_say_home_4", "Agreed. Titans were not built for stealth.", 2.76 },
    } },
    bye = { every = 0.0, lines = {
      { "bt7274_say_bye_1", "Be careful, Pilot.", 1.16 },
      { "bt7274_say_bye_2", "Exercise caution, Pilot.", 1.64 },
      { "bt7274_say_bye_3", "Good luck over there.", 1.46 },
      { "bt7274_say_bye_4", "The channel is open if you need assistance.", 2.31 },
      { "bt7274_say_bye_5", "I will assist you through your helmet radio when possible.", 3.03 },
    } },
    byeWon = { every = 0.0, lines = {
      { "bt7274_say_byeWon_1", "Well done, Pilot.", 1.24 },
      { "bt7274_say_byeWon_2", "You fought well out there, Pilot.", 1.86 },
    } },
  } },
