function FPF.sceneSounds(key)
  if not P.sceneSounds then return end
  local list = FPC.sceneSounds[key]
  if not list then return end
  local played = 0
  for _, name in ipairs(list) do
    if FPF.tf(name) then played = played + 1 end
  end
  PS.sceneSnd = (PS.sceneSnd or 0) + 1
  if PS.sceneSnd <= 6 or played < #list then
    log(string.format("%s: Titanfall's own sounds for it - %d of %d played (%s)", (key == "dismount") and "DISMOUNT" or "EMBARK", played, #list, table.concat(list, ", ")))
  end
end

FPC.list = { every = 0.5, keep = 1.5, crowd = 0, lines = 16 }
P.listMore = true

function FPF.listShape(ent)
  local shape = false
  pcall(function()
    if ent:GetNPCType() == gamedataNPCType.Mech then shape = FPC.big.mech end
  end)
  pcall(function()
    if ent:GetNPCType() == gamedataNPCType.Drone then
      shape = FPF.droneShape(ent)
      local known = PS.droneLiftOf and PS.droneLiftOf[shape.name]
      if known and not shape.body then shape[3] = known end
    end
  end)
  pcall(function()
    if TDBID.ToStringDEBUG(ent:GetRecordID()) == UNITS.bt.record then shape = FPC.big.titan end
  end)
  pcall(function()
    local own = FPF.recordShape(TDBID.ToStringDEBUG(ent:GetRecordID()))
    if own then shape = own end
  end)
  return shape
end

function FPF.listMore(list, shapes, seen)
  local K = FPC.list
  PS.listStat = PS.listStat or { asked = 0, empty = 0, secondary = 0, threat = 0, decoy = 0, look = 0, kept = 0 }
  local L = PS.listStat
  local own, parts = #list, PS.listParts or -1
  L.asked = L.asked + 1
  if parts <= 0 then L.empty = L.empty + 1 end
  PS.npcKeep = PS.npcKeep or {}
  local player = Game.GetPlayer()
  local function take(ent, how, field)
    if not ent or not IsDefined(ent) then return end
    local key = nil
    pcall(function() key = tostring(ent:GetEntityID()) end)
    if key == nil or seen[key] then return end
    local npc = false
    pcall(function() npc = ent:IsNPC() == true end)
    if not npc then return end
    seen[key] = true
    local out = false
    pcall(function() out = ent:IsDead() or GameObject.IsFriendlyTowardsPlayer(ent) end)
    if PS.decoy and PS.decoy.hash and key == PS.decoy.hash then out = true end
    if out then return end
    list[#list + 1] = ent
    shapes[#list] = FPF.listShape(ent)
    L[field] = L[field] + 1
    local name = "?"
    pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
    if not S.seen["listmore" .. field .. name] and (PS.listLines or 0) < K.lines then
      PS.listLines = (PS.listLines or 0) + 1
      local far = -1.0
      pcall(function()
        local p = ent:GetWorldPosition()
        far = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2)
      end)
      once("listmore" .. field .. name, string.format("PEOPLE %s, %.0f m from BT, is not in what the game's targeting search gave (%d parts, %d people) - taken into the list as %s: BT's rounds, fist and missiles can meet it",
        name, far, parts, own, how))
    end
  end
  if S.clock >= (PS.listMoreAt or 0.0) then
    PS.listMoreAt = S.clock + K.every
    if own < K.crowd then
      pcall(function()
        local q = Game["TSQ_NPC;"]()
        q.maxDistance = XO16.range + 60.0
        q.testedSet = TargetingSet.Complete
        q.includeSecondaryTargets = true
        local found, more = Game.GetTargetingSystem():GetTargetParts(player, q)
        if not found or not more then return end
        for _, part in ipairs(more) do
          local ent = nil
          pcall(function() ent = TS_TargetPartInfo.GetComponent(part):GetEntity() end)
          take(ent, "one of the search's secondary targets", "secondary")
        end
      end)
    end
    local function threats(of, how, field)
      pcall(function()
        local tracker = of:GetTargetTrackerComponent()
        if not tracker then return end
        for _, tl in ipairs(tracker:GetHostileThreats(false) or {}) do
          local ent = nil
          pcall(function() ent = tl.entity end)
          take(ent, how, field)
        end
      end)
    end
    threats(player, "a hostile threat of V's", "threat")
    if PS.decoy and PS.decoy.ent and IsDefined(PS.decoy.ent) then
      threats(PS.decoy.ent, "a hostile threat of BT's stand-in", "decoy")
    end
    pcall(function()
      take(Game.GetTargetingSystem():GetLookAtObject(player, false, false), "what V's own crosshair is on", "look")
    end)
  end
  for key, kept in pairs(PS.npcKeep) do
    if S.clock - kept.at > K.keep or not IsDefined(kept.ent) then
      PS.npcKeep[key] = nil
    elseif not seen[key] then
      local gone = false
      pcall(function() gone = kept.ent:IsDead() or GameObject.IsFriendlyTowardsPlayer(kept.ent) end)
      if gone then
        PS.npcKeep[key] = nil
      else
        seen[key] = true
        list[#list + 1] = kept.ent
        shapes[#list] = kept.shape
        kept.held = true
        L.kept = L.kept + 1
      end
    end
  end
  for i, ent in ipairs(list) do
    local key = nil
    pcall(function() key = tostring(ent:GetEntityID()) end)
    if key then
      local kept = PS.npcKeep[key]
      if kept and kept.held then
        kept.held = nil
      else
        PS.npcKeep[key] = { ent = ent, shape = shapes[i], at = S.clock }
      end
    end
  end
end

function FPF.listReport()
  local L = PS.listStat
  if not L or L.asked == 0 then return end
  PS.listStat = nil
  log(string.format("PEOPLE for BT's rounds in this drive: the game's targeting search was asked %d times (it gave nobody %d times); taken into the list beside it - its secondary targets %d, hostile threats of V's %d, of BT's stand-in %d, under V's own crosshair %d; kept from the list before %d times",
    L.asked, L.empty, L.secondary, L.threat, L.decoy, L.look, L.kept))
end

