FPC.vStep, FPC.vCalm = 0.25, 2.0
FPC.out = { up = 0.7, down = 1.6, room = 0.45, far = 5.3, side = 5.0, near = 3.4, chest = 3.0, step = 1.5 }
FPC.dev = { every = 1.0, range = 90.0, r = 0.7, h = 1.4, skin = 0.5, share = 12.0, missile = 60.0, bare = { 0.8, 2.3, -1.0 }, checks = 8 }
FPC.burn2 = { worse = 0.2, overlap = 0.5, layers = {
