    slots = { "vent_l", "vent_r" }, life = 20.0 },
  { name = "burning electronics at its front vents and on its back", path = [[ep1\fx\enviroment\fire\e_fire_small_electronics_002.effect]],
    slots = { "vent_lf", "vent_rf", "rodeo" }, life = 14.5 },
