function FPF.isWreck(veh)
  local gone = false
  pcall(function() gone = veh:IsDestroyed() == true end)
  return gone
end

function FPF.boomBusy(veh)
  local key = FPF.vehKey(veh)
  if PS.doomed and PS.doomed[key] then return true end
  local at = PS.exploded[key]
  return at ~= nil and S.clock - at < FPC.boom.calm
end

function FPF.doomFrame()
  if not PS.doomed then return end
  for key, D in pairs(PS.doomed) do
    if S.clock >= D.at then
      PS.doomed[key] = nil
      if IsDefined(D.veh) then
        if FPF.isWreck(D.veh) then
          PS.boomSkips = (PS.boomSkips or 0) + 1
          once("boomself", "a vehicle whose health this script took to nothing had blown up by the game's own hand a moment later - no second death event for it (since t48)")
        else
          PS.exploded[key] = S.clock
          local veh = D.veh
          local ok, err = pcall(function()
            local evt = gameDeathEvent.new()
            evt.instigator = Game.GetPlayer()
            veh:QueueEvent(evt)
          end)
          PS.explosions = (PS.explosions or 0) + 1
          if PS.explosions <= 8 then
            log(string.format("a vehicle blows up (%s; %s): %s", FPF.vehicleText(veh), tostring(D.why),
              ok and "the game took its death event" or ("its death event could NOT be sent: " .. tostring(err))))
          end
        end
      end
    end
  end
end

function FPF.clear(x1, y1, z1, x2, y2, z2)
  local free = true
  for _, group in ipairs({ "Static", "Terrain", "Vehicle" }) do
    pcall(function()
      if FPF.sqs():SyncRaycastByCollisionGroup(Vector4.new(x1, y1, z1, 1.0), Vector4.new(x2, y2, z2, 1.0), group, nil, false, false) then
        free = false
      end
    end)
  end
  return free
end

function FPF.standable(x, y)
  local K = FPC.out
  local g = groundZ(x, y, PS.z)
  if not g then return nil, "no ground is found there" end
  if g > PS.z + K.up then return nil, string.format("something %.1f m high stands there", g - PS.z) end
  if g < PS.z - K.down then return nil, string.format("the ground is %.1f m lower there", PS.z - g) end
  local cz = PS.z + K.chest
  if not FPF.clear(PS.x, PS.y, cz, x, y, g + 1.0) or not FPF.clear(PS.x, PS.y, cz, x, y, g + 1.7) then
    return nil, "something is between BT and it"
  end
  for _, d in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
    if not FPF.clear(x, y, g + 0.9, x + d[1] * K.room, y + d[2] * K.room, g + 0.9) then return nil, "there is no room for V there" end
  end
  return g
end

function FPF.outPlan(F)
  local K = FPC.out
  local r = math.rad(PS.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local h = math.max(F.z - (PS.z + EYE_HEIGHT), 0.0)
  local t = (F.vz + math.sqrt(F.vz * F.vz + 2.0 * FALL * h)) / FALL
  local nx, ny = F.x + F.vx * t, F.y + F.vy * t
  local g, why = FPF.standable(nx, ny)
  if g then
    F.plan = g
    return
  end
  for _, c in ipairs({ { -K.step, 0.0, "to the left of" }, { K.step, 0.0, "to the right of" }, { 0.0, -K.step, "short of" } }) do
    local x, y = nx + fy * c[1] + fx * c[2], ny - fx * c[1] + fy * c[2]
    local at = FPF.standable(x, y)
    if at then
      local h2 = math.max(F.z - (at + EYE_HEIGHT), 0.0)
      local t2 = math.max((F.vz + math.sqrt(F.vz * F.vz + 2.0 * FALL * h2)) / FALL, 0.05)
      F.vx, F.vy, F.plan = (x - F.x) / t2, (y - F.y) / t2, at
      PS.outMoves = (PS.outMoves or 0) + 1
      log(string.format("DISMOUNT: where the drop out of the hatch would end is not free (%s) - V comes down %.1f m %s it", tostring(why), K.step, c[3]))
      return
    end
  end
  local function set(x, y, at, where)
    F.x, F.y, F.z, F.landed, F.ground, F.at, F.where = x, y, at + EYE_HEIGHT, true, at, PS.scene and PS.scene.t or 0.0, where
    F.vx, F.vy, F.vz, F.pitch = 0.0, 0.0, 0.0, 0.0
    PS.outMoves = (PS.outMoves or 0) + 1
  end
  for _, c in ipairs({ { 0.0, -K.far, "behind BT" }, { -K.side, 0.0, "to BT's left" }, { K.side, 0.0, "to BT's right" },
      { -K.side * 0.7, -K.side * 0.7, "behind BT, to its left" }, { K.side * 0.7, -K.side * 0.7, "behind BT, to its right" },
      { 0.0, K.near, "close in front of BT" } }) do
    local x, y = PS.x + fy * c[1] + fx * c[2], PS.y - fx * c[1] + fy * c[2]
    local at = FPF.standable(x, y)
    if at then
      set(x, y, at, c[3])
      log(string.format("DISMOUNT: the place in front of BT is not free (%s) - V is set down %s instead", tostring(why), c[3]))
      return
    end
  end
  set(PS.x, PS.y, PS.z, "at BT's feet")
  log(string.format("DISMOUNT: the place in front of BT is not free (%s) and none round it is - V is set down at BT's feet", tostring(why)))
end

function FPF.devRefresh()
  if S.clock < (PS.devAt or 0.0) then return end
  if not FPF.heavyTurn("turrets and cameras") then return end
  local K = FPC.dev
  PS.devAt = S.clock + K.every
  PS.devs, PS.devKeys = PS.devs or {}, PS.devKeys or {}
  local sums = {}
  local function take(ent, part)
    if not ent or not IsDefined(ent) then return end
    local sensor = false
    pcall(function() sensor = ent:IsSensor() == true end)
    if not sensor then return end
    local key = nil
    pcall(function() key = tostring(ent:GetEntityID()) end)
    if not key then return end
    local D = PS.devKeys[key]
    if not D then
      local p = nil
      pcall(function() p = ent:GetWorldPosition() end)
      if not p then return end
      D = { ent = ent, key = key, x = p.x, y = p.y, z = p.z + K.bare[3], r = K.bare[1], h = K.bare[2], name = "a device" }
      pcall(function()
        local c = ent:GetClassName()
        local v = c and c.value
        if type(v) ~= "string" or v == "" then v = Game.NameToString(c) end
        if type(v) == "string" and v ~= "" then D.name = v end
      end)
      PS.devKeys[key] = D
      PS.devs[#PS.devs + 1] = D
      PS.devSeen = (PS.devSeen or 0) + 1
      once("dev" .. D.name, string.format("a turret or camera is in reach of BT's rounds (%s, %.0f m from BT): the crosshair goes red on it, a round takes %.0f %% of its health, a missile's blast %.0f %%",
        D.name, math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2), K.share, K.missile))
    end
    if part then
      pcall(function()
        local at = TS_TargetPartInfo.GetComponent(part):GetLocalToWorld().W
        local A = sums[key] or { x = 0.0, y = 0.0, z = 0.0, n = 0 }
        A.x, A.y, A.z, A.n = A.x + at.x, A.y + at.y, A.z + at.z, A.n + 1
        sums[key] = A
      end)
    end
  end
  pcall(function()
    local q = Game["TSQ_ALL;"]()
    q.maxDistance = K.range
    q.testedSet = TargetingSet.Complete
    local found, parts = Game.GetTargetingSystem():GetTargetParts(Game.GetPlayer(), q)
    if not found or not parts then return end
    for _, part in ipairs(parts) do
      local ent = nil
      pcall(function() ent = TS_TargetPartInfo.GetComponent(part):GetEntity() end)
      take(ent, part)
    end
  end)
  pcall(function()
    local tracker = Game.GetPlayer():GetTargetTrackerComponent()
    if not tracker then return end
    for _, tl in ipairs(tracker:GetHostileThreats(false) or {}) do
      local ent = nil
      pcall(function() ent = tl.entity end)
      take(ent, nil)
    end
  end)
  for key, A in pairs(sums) do
    local D = PS.devKeys[key]
    if D and A.n > 0 then D.x, D.y, D.z, D.r, D.h = A.x / A.n, A.y / A.n, A.z / A.n - K.h * 0.5, K.r, K.h end
  end
  for i = #PS.devs, 1, -1 do
    local D = PS.devs[i]
    if not IsDefined(D.ent) then
      PS.devKeys[D.key] = nil
      table.remove(PS.devs, i)
    else
      local known, broken = pcall(function() return D.ent:GetDevicePS():IsBroken() == true end)
      local out = (known and broken) or D.killed == true
      if not D.follow and P.devAggro then
        local ent = D.ent
        pcall(function()
          local ps = ent:GetDevicePS()
          if ps:IsInFollowMode() then
            local there = Game.FindEntityByID(ps:GetForcedTargetID())
            if not there or not IsDefined(there) then
              FPF.devFollow(D, nil, false)
              once("devstale", string.format("a turret (%s) was still following something that is not there any more - the order is taken back", D.name))
            end
          end
        end)
      end
      if not out then pcall(function() out = GameObject.IsFriendlyTowardsPlayer(D.ent) == true end) end
      if not out and not known then
        local v = healthOf(D.ent)
        if type(v) == "number" and v <= 0.0 then out = true end
      end
      D.dead = out
    end
  end
end

function FPF.devHit(dev, record, x, y, z, dx, dy, dz, share, dist, by)
  local key = nil
  pcall(function() key = tostring(dev:GetEntityID()) end)
  local D = key and PS.devKeys and PS.devKeys[key] or nil
  local before = healthOf(dev)
  PS.loudHit = P.devNumbers
  FPF.hit(dev, record, x, y, z, dx, dy, dz)
  PS.loudHit = nil
  local ok, err = pcall(function()
    Game.GetStatPoolsSystem():RequestChangingStatPoolValue(dev:GetEntityID(), gamedataStatPoolType.Health, -share, Game.GetPlayer(), false, true)
  end)
  PS.devHits = (PS.devHits or 0) + 1
  if not ok then once("devpool" .. tostring(err), "a turret's or camera's health could NOT be changed directly: " .. tostring(err)) end
  if (PS.devChecked or 0) < FPC.dev.checks then
    PS.devChecked = (PS.devChecked or 0) + 1
    PS.checks[#PS.checks + 1] = { ent = dev, before = before, at = S.clock + 0.4, dist = dist or 0.0, what = D and D.name or "?", kind = "device",
      by = (by ~= "XO-16") and by or nil }
  end
  if D and not D.killAt and not D.killed and type(before) == "number" and before - share <= 0.5 then D.killAt = S.clock + 0.25 end
end

function FPF.devFrame()
  if not PS.devs then return end
  for _, D in ipairs(PS.devs) do
    if D.killAt and S.clock >= D.killAt then
      D.killAt, D.killed = nil, true
      if IsDefined(D.ent) then
        local known, broken = pcall(function() return D.ent:GetDevicePS():IsBroken() == true end)
        if known and not broken then
          local ent = D.ent
          local ok, err = pcall(function()
            local evt = gameDeathEvent.new()
            evt.instigator = Game.GetPlayer()
            ent:QueueEvent(evt)
          end)
          once("devdeath" .. tostring(ok), ok and string.format("a turret or camera (%s) whose health BT took to nothing had not broken a quarter of a second later - the game's death event is sent to it", D.name)
            or ("a turret's death event could NOT be sent: " .. tostring(err)))
        elseif known then
          once("devbroke", string.format("a turret or camera (%s) whose health BT took to nothing broke by itself", D.name))
        end
        D.dead = true
      end
    end
  end
end

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and "sparks at its rear vents, burning electronics at its front vents and on its back, and the big fire at its back"
          or ((stage == 1) and "sparks at its rear vents and burning electronics at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not PF.shown or L.fp == true)
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local p = slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key, rigid = L.rigid }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

FPC.hover = { up = 0.75, float = 0.70, coil = 0.30, high = 4.2, power = 1.9, bob = 0.13, bobHz = 1.15, bobFade = 1.2, sink = 0.5,
  accel = 62.0, ramp = 0.18, most = 120.0, yaw = 9.0, yawFrom = 0.2, yawOver = 1.2, back = 0.25, backOver = 1.2 }
FPC.devAggro = { every = 0.5, far = 45.0, tell = 1.0, lose = 70.0, lines = 10 }
P.homeHover, P.devAggro = true, true

function FPF.hoverFrame(A, D, dt)
  local H = FPC.hover
  local tt = A.t - D.lift
  local t1 = H.up + H.float
  local t2 = t1 + H.coil
  local base
  if tt < H.up then
    base = H.high * (1.0 - (1.0 - math.max(tt, 0.0) / H.up) ^ H.power)
  else
    base = H.high + H.bob * math.sin(2.0 * math.pi * H.bobHz * (tt - H.up)) * math.exp(-(tt - H.up) / H.bobFade)
  end
  base = base - H.sink * ease((tt - t1) / H.coil)
  if tt > t2 then
    if not A.done.burst then
      A.done.burst = true
      local roar = false
      if P.liftSound then
        roar = FPF.tf(FPC.throw.liftSound)
        FPF.tf(FPC.dash.tp[1])
      end
      log(string.format("BT BURSTS away %.2f s after its feet left the ground, %.1f m up: %.0f m/s faster every second; the roar of its jets %s",
        tt, base, H.accel, roar and "played" or "not played"))
    end
    A.vz = math.min(H.most, A.vz + H.accel * ease((tt - t2) / H.ramp) * dt)
    A.burstUp = (A.burstUp or 0.0) + A.vz * dt
  end
  A.up = base + (A.burstUp or 0.0)
  local back = H.back * ease(tt / H.backOver)
  local r = math.rad(A.yaw0)
  PS.x, PS.y = A.x0 + math.sin(r) * back, A.y0 - math.cos(r) * back
  PS.yaw = A.yaw0 + H.yaw * ease((tt - H.yawFrom) / H.yawOver)
end

function FPF.devFollow(D, target, on)
  local ent = D.ent
  return pcall(function()
    local ps = ent:GetDevicePS()
    local evt
    if on then
      evt = QuestFollowTarget.new()
      pcall(function() evt:SetUp(ps) end)
      evt:SetPropertiesFromScripts(target:GetEntityID())
    else
      evt = QuestStopFollowingTarget.new()
      pcall(function() evt:SetUp(ps) end)
      evt:SetProperties()
    end
    Game.GetPersistencySystem():QueuePSEvent(ps:GetID(), ps:GetClassName(), evt)
  end)
end

function FPF.devAggroFrame()
  local K = FPC.devAggro
  if not PS.devs or S.clock < (PS.devAggroAt or 0.0) then return end
  if #PS.devs > 0 and not FPF.heavyTurn("turrets that fire at BT") then return end
  PS.devAggroAt = S.clock + K.every
  local decoy = PS.decoy and PS.decoy.ent and IsDefined(PS.decoy.ent) and PS.decoy.ent or nil
  local key = decoy and PS.decoy.hash or nil
  local piloting = P.devices and P.devAggro and S.driving and S.pilot and PS.mode == "pilot" and decoy ~= nil
  local zone = 0
  if piloting then pcall(function() zone = FPF.zone() end) end
  local player = Game.GetPlayer()
  local bx, by, bz = PS.x, PS.y, PS.z + FPC.notice.chest
  for _, D in ipairs(PS.devs) do
    if IsDefined(D.ent) then
      local ent = D.ent
      local want, why = false, nil
      if piloting and not D.dead and (not D.follow or D.follow == key) then
        local far = math.sqrt((D.x - bx) ^ 2 + (D.y - by) ^ 2)
        if far <= (D.follow and K.lose or K.far) then
          local turret, on, would = false, false, false
          pcall(function() turret = ent:IsTurret() == true end)
          pcall(function() on = ent:GetDevicePS():IsON() == true end)
          if turret and on then
            pcall(function() would = ent:SetAsIntrestingTarget(player) == true end)
            if would then why = "it would fire at V" end
            if not would then
              pcall(function() would = EnumName("EAIAttitude", GameObject.GetAttitudeTowards(ent, player)):find("Hostile", 1, true) ~= nil end)
              if would then why = "it is hostile to V" end
            end
            if not would and zone >= 4 then would, why = true, "V is in a hostile area" end
            if would and (D.follow or FPF.buddyClear(D.x, D.y, D.z + D.h * 0.5, bx, by, bz)) then want = true end
          end
        end
      end
      if want and not D.follow then
        D.seen = (D.seen or 0.0) + K.every
        if D.seen >= K.tell then
          local ok, err = FPF.devFollow(D, decoy, true)
          D.follow, D.seen = ok and key or nil, 0.0
          PS.devAggros = (PS.devAggros or 0) + (ok and 1 or 0)
          if (PS.devAggroLines or 0) < K.lines then
            PS.devAggroLines = (PS.devAggroLines or 0) + 1
            log(ok and string.format("a turret (%s, %.0f m from BT) has had BT in sight for %.1f s and %s: it is given the game's order to follow BT's stand-in and fire at it",
                D.name, math.sqrt((D.x - bx) ^ 2 + (D.y - by) ^ 2), K.tell, tostring(why))
              or ("a turret could NOT be told to fire at BT: " .. tostring(err)))
          end
        end
      elseif not want then
        D.seen = 0.0
        if D.follow then
          local ok = FPF.devFollow(D, nil, false)
          D.follow = nil
          if (PS.devAggroLines or 0) < K.lines then
            PS.devAggroLines = (PS.devAggroLines or 0) + 1
            log(string.format("a turret (%s) is let go of BT's stand-in (%s): %s", D.name,
              (not piloting) and "V does not pilot BT any more" or (D.dead and "it is broken" or "BT is far away, or it would not fire at V any more"),
              ok and "the order is taken back" or "the order could NOT be taken back"))
          end
        end
      end
    end
  end
end

