P.fineHit, P.droneFull, P.burnLean, P.quietHits = true, true, true, true

function FPF.gridRay(shape, ent, p, ox, oy, oz, dx, dy, dz, len)
  local G = shape.grid
  local fx, fy = 0.0, 1.0
  pcall(function()
    local f = ent:GetWorldForward()
    local n = math.sqrt(f.x * f.x + f.y * f.y)
    if n > 0.01 then fx, fy = f.x / n, f.y / n end
  end)
  local cz = p.z + (shape[3] or 0.0) + shape[2] * 0.5
  local rx, ry = ox - p.x, oy - p.y
  local lx, ly, lz = rx * fy - ry * fx, rx * fx + ry * fy, oz - cz
  local ex, ey, ez = dx * fy - dy * fx, dx * fx + dy * fy, dz
  local hx, hy, hz = G.nx * G.cell * 0.5, G.ny * G.cell * 0.5, G.nz * G.cell * 0.5
  local t0, t1 = 0.0, len
  local function slab(o, d, h)
    if math.abs(d) < 1e-9 then return o >= -h and o <= h end
    local a, b = (-h - o) / d, (h - o) / d
    if a > b then a, b = b, a end
    if a > t0 then t0 = a end
    if b < t1 then t1 = b end
    return t0 <= t1
  end
  if not (slab(lx, ex, hx) and slab(ly, ey, hy) and slab(lz, ez, hz)) then return nil end
  local step = G.cell * 0.5
  local t = t0 + 1e-4
  while t <= t1 do
    local ix = math.floor((lx + ex * t + hx) / G.cell) + 1
    local iy = math.floor((ly + ey * t + hy) / G.cell) + 1
    local iz = math.floor((lz + ez * t + hz) / G.cell) + 1
    if ix >= 1 and ix <= G.nx and iy >= 1 and iy <= G.ny and iz >= 1 and iz <= G.nz then
      local row = G.rows[(iz - 1) * G.ny + iy]
      if row and row:byte(ix) == 49 then return t end
    end
    t = t + step
  end
  return nil
end

function FPF.isDrone(who)
  for i, ent in ipairs(PS.npcs) do
    if ent == who then
      local shape = PS.npcShape[i]
      return shape ~= nil and shape ~= false and shape.drone == true
    end
  end
  return false
end

function FPF.quietHit(hit)
  if not P.quietHits then return end
  local ok, err = pcall(function() hit.attackData:AddFlag(hitFlag.DontShowDamageFloater, CName.new("bt7274")) end)
  if PS.quietSaid ~= ok then
    PS.quietSaid = ok
    log(ok and "hits that carry no attack type are sent with the game's flag for no damage number"
      or ("a hit could NOT be given the flag for no damage number: " .. tostring(err)))
  end
end

