function FPF.burnLean(L, p)
  local K = FPC.burn2
  local dt = math.max(S.dt or 0.016, 0.001)
  if not L.px then
    L.vx, L.vy = PS.vx or 0.0, PS.vy or 0.0
  elseif dt < 0.2 then
    local q = math.min(1.0, dt * K.leanQuick)
    L.vx = (L.vx or 0.0) + ((p.x - L.px) / dt - (L.vx or 0.0)) * q
    L.vy = (L.vy or 0.0) + ((p.y - L.py) / dt - (L.vy or 0.0)) * q
  end
  local speed = math.sqrt(L.vx * L.vx + L.vy * L.vy)
  if speed > 0.3 then L.yaw = math.deg(math.atan2(-L.vx, L.vy)) end
  L.pitch = math.min(K.leanMost, math.deg(math.atan2(speed, K.leanRise)))
  L.px, L.py = p.x, p.y
end

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and "one segment left: sparks at its rear vents, burning electronics at its front vents and on its back, and the big fire at its back"
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not L.first or not worse) and (not PF.shown or L.fp == true)
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local p = slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key, rigid = L.rigid }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

