function FPF.quietHit(hit)
  if not P.quietHits or PS.loudHit then return end
  local ok, err = pcall(function() hit.attackData:AddFlag(hitFlag.DontShowDamageFloater, CName.new("bt7274")) end)
  if PS.quietSaid ~= ok then
    PS.quietSaid = ok
    log(ok and "hits that carry no attack type are sent with the game's flag for no damage number"
      or ("a hit could NOT be given the flag for no damage number: " .. tostring(err)))
  end
end

function FPF.droneStat()
  PS.droneStat = PS.droneStat or { box = 0, met = 0, near = 0 }
  return PS.droneStat
end

function FPF.droneBody(ent, shape)
  if not P.droneBody or PS.droneBodyOff or not shape.z0 then return false end
  local ok, err = pcall(function()
    local comp = ent:FindComponentByName(FPC.droneAim)
    if not comp then return end
    local w = comp:GetLocalToWorld().W
    local bx, by, bz = w.x - shape.x0, w.y - shape.y0, w.z - shape.z0
    if math.abs(bx) > 6.0 or math.abs(by) > 6.0 or bz < -3.0 or bz > 12.0 then return end
    shape.bx, shape.by, shape.bz = bx, by, bz
    shape.body, shape.how = true, "its body's own aim point"
    shape[3] = clamp(bz - shape[2] * 0.5, -shape[2], 12.0)
  end)
  if not ok then
    PS.droneBodyOff = true
    log("a drone's own aim point cannot be asked from its object (" .. tostring(err) .. ") - the highest of the aim points the targeting search gives is taken for its body")
  end
  return shape.body == true
end

function FPF.droneShape(ent)
  local name = "?"
  pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
  local kind = FPC.drones.any
  local low = string.lower(name)
  local grid = nil
  for _, K in ipairs(FPC.drones) do
    if low:find(K[1], 1, true) then
      kind = { K[2], K[3], K[4] }
      grid = FPC.droneGrid and FPC.droneGrid[K[1]] or nil
      break
    end
  end
  local shape = { kind[1], kind[2], kind[3], drone = true, name = name, grid = grid }
  pcall(function()
    local p = ent:GetWorldPosition()
    shape.x0, shape.y0, shape.z0 = p.x, p.y, p.z
  end)
  FPF.droneBody(ent, shape)
  return shape
end

FPF.droneLiftOld = FPF.droneLift
function FPF.droneLift(dr)
  if not P.droneBody then return FPF.droneLiftOld(dr) end
  local how = "no aim point of it could be read: taken as its kind says"
  local read = dr.n and dr.n > 0 and dr.z0
  if dr.body then
    how = dr.how
  elseif read and dr.top then
    dr.bx, dr.by, dr.bz = (dr.tx or dr.x0) - dr.x0, (dr.ty or dr.y0) - dr.y0, dr.top - dr.z0
    dr[3] = clamp(dr.bz - dr[2] * 0.5, -dr[2], 12.0)
    how = string.format("the highest of its %d aim points", dr.n)
  end
  if dr.body or read then
    PS.droneLiftOf = PS.droneLiftOf or {}
    PS.droneLiftOf[dr.name] = dr[3]
  end
  PS.droneSaid = PS.droneSaid or {}
  if not PS.droneSaid[dr.name] then
    PS.droneSaid[dr.name] = true
    local G = dr.grid
    log(string.format("a drone (%s) is %.1f m wide and %.1f m tall for BT's rounds, fist and missiles, its middle %.1f m above the place the game has it at (%s%s)%s",
      dr.name, dr[1] * 2.0, dr[2], dr[3] + dr[2] * 0.5, how,
      read and string.format("; the middle of the %d aim points the search gives is %.1f m above it - where its shape was up to t49", dr.n, dr.sum / dr.n - dr.z0) or "",
      G and string.format("; its body cell by cell: %d x %d x %d cells of %.2f m%s", G.nx, G.ny, G.nz, G.cell, P.droneFat and ", taken one cell fatter" or "") or ""))
  end
end

function FPF.gridFat(G)
  if G.fat then return G.fat end
  local function taken(ix, iy, iz)
    if ix < 1 or ix > G.nx or iy < 1 or iy > G.ny or iz < 1 or iz > G.nz then return false end
    local row = G.rows[(iz - 1) * G.ny + iy]
    return row ~= nil and row:byte(ix) == 49
  end
  local F = { cell = G.cell, nx = G.nx + 2, ny = G.ny + 2, nz = G.nz + 2, rows = {}, taken = 0 }
  for iz = 1, F.nz do
    for iy = 1, F.ny do
      local row = {}
      for ix = 1, F.nx do
        local x, y, z = ix - 1, iy - 1, iz - 1
        local on = taken(x, y, z) or taken(x - 1, y, z) or taken(x + 1, y, z) or taken(x, y - 1, z) or taken(x, y + 1, z)
          or taken(x, y, z - 1) or taken(x, y, z + 1)
        row[ix] = on and "1" or "0"
        if on then F.taken = F.taken + 1 end
      end
      F.rows[(iz - 1) * F.ny + iy] = table.concat(row)
    end
  end
  G.fat = F
  return F
end

function FPF.gridRay(shape, ent, p, ox, oy, oz, dx, dy, dz, len)
  local G = shape.grid
  if P.droneFat then G = FPF.gridFat(G) end
  local fx, fy = 0.0, 1.0
  pcall(function()
    local f = ent:GetWorldForward()
    local n = math.sqrt(f.x * f.x + f.y * f.y)
    if n > 0.01 then fx, fy = f.x / n, f.y / n end
  end)
  local cx, cy, cz = p.x, p.y, p.z + (shape[3] or 0.0) + shape[2] * 0.5
  if P.droneBody and shape.bz then cx, cy, cz = p.x + (shape.bx or 0.0), p.y + (shape.by or 0.0), p.z + shape.bz end
  local rx, ry = ox - cx, oy - cy
  local lx, ly, lz = rx * fy - ry * fx, rx * fx + ry * fy, oz - cz
  local ex, ey, ez = dx * fy - dy * fx, dx * fx + dy * fy, dz
  local hx, hy, hz = G.nx * G.cell * 0.5, G.ny * G.cell * 0.5, G.nz * G.cell * 0.5
  local t0, t1 = 0.0, len
  local function slab(o, d, h)
    if math.abs(d) < 1e-9 then return o >= -h and o <= h end
    local a, b = (-h - o) / d, (h - o) / d
    if a > b then a, b = b, a end
    if a > t0 then t0 = a end
    if b < t1 then t1 = b end
    return t0 <= t1
  end
  if not (slab(lx, ex, hx) and slab(ly, ey, hy) and slab(lz, ez, hz)) then return nil end
  local T = (PS.rayFor == "round") and FPF.droneStat() or nil
  if T then T.box = T.box + 1 end
  local step = G.cell * 0.5
  local t = t0 + 1e-4
  while t <= t1 do
    local ix = math.floor((lx + ex * t + hx) / G.cell) + 1
    local iy = math.floor((ly + ey * t + hy) / G.cell) + 1
    local iz = math.floor((lz + ez * t + hz) / G.cell) + 1
    if ix >= 1 and ix <= G.nx and iy >= 1 and iy <= G.ny and iz >= 1 and iz <= G.nz then
      local row = G.rows[(iz - 1) * G.ny + iy]
      if row and row:byte(ix) == 49 then
        if T then T.met = T.met + 1 end
        return t
      end
    end
    t = t + step
  end
  return nil
end

-- Open77: one sphere against the aim's line (the author's closure `look` in FPF.aimNear): how far the line passes from it and where
-- along the line, or nothing for a sphere before the line's least distance or past its end.
function FPF.aimLook(K, ox, oy, oz, dx, dy, dz, t, cx, cy, cz, rad)
  local along = (cx - ox) * dx + (cy - oy) * dy + (cz - oz) * dz
  if along < K.least or along >= t then return nil end
  local px, py, pz = ox + dx * along - cx, oy + dy * along - cy, oz + dz * along - cz
  return math.sqrt(px * px + py * py + pz * pz) - rad, along
end

function FPF.aimNear(A, ox, oy, oz, dx, dy, dz, t)
  local K = FPC.aimNear
  local best, bestT = K.reach, nil
  for i, ent in ipairs(PS.npcs or {}) do
    if PS.npcShape[i] and PS.npcShape[i].drone then
      local p = FPF.npcAt(i)
      if p then
        local shape = PS.npcShape[i]
        if shape and shape.drone then
          local off, along
          if shape.bz and P.droneBody then
            off, along = FPF.aimLook(K, ox, oy, oz, dx, dy, dz, t, p.x + (shape.bx or 0.0), p.y + (shape.by or 0.0), p.z + shape.bz, shape[1])
          else
            off, along = FPF.aimLook(K, ox, oy, oz, dx, dy, dz, t, p.x, p.y, p.z + (shape[3] or 0.0) + shape[2] * 0.5, shape[1])
          end
          if off and off < best then best, bestT = off, along end
        end
      end
    end
  end
  if P.devices and PS.devs then
    for _, D in ipairs(PS.devs) do
      if not D.dead and IsDefined(D.ent) then
        local off, along = FPF.aimLook(K, ox, oy, oz, dx, dy, dz, t, D.x, D.y, D.z + D.h * 0.5, D.r)
        if off and off < best then best, bestT = off, along end
      end
    end
  end
  if not bestT then return end
  A.x, A.y, A.z, A.near = ox + dx * bestT, oy + dy * bestT, oz + dz * bestT, true
  local T = FPF.droneStat()
  T.near = T.near + 1
  once("aimnear", string.format("XO-16 aim: the view's line is on no target (it ends %.0f m out) but passes a drone or a turret %.1f m from its shape - the rounds cross that line at that target's distance, %.0f m out",
    t, math.max(best, 0.0), bestT))
end

function FPF.droneReport()
  local T = PS.droneStat
  PS.droneStat = nil
  if not T or (T.box == 0 and T.near == 0) then return end
  log(string.format("DRONES in this drive: %d rounds went into a drone's box, %d of them met its body (%d went through between its parts); the view's line was on nothing next to a listed target in %d frames - the rounds crossed it at that target's distance",
    T.box, T.met, T.box - T.met, T.near))
end

FPF.burnLeanOld = FPF.burnLean
function FPF.burnLean(L, p)
  if L.rigid and P.burnRigid then
    L.yaw, L.pitch = PS.yaw, 0.0
    L.px, L.py = p.x, p.y
    once("burnrigid", "effects: the big fire at BT's back is kept as its hull is turned and is not tipped - its standing flames are born in a ring and in boxes round its place (0.45 - 0.8 m), which the lean of t49 swung about its slot; its smoke trails by itself")
    return
  end
  return FPF.burnLeanOld(L, p)
end

FPF.hoverFrameOld = FPF.hoverFrame
function FPF.hoverFrame(A, D, dt)
  FPF.hoverFrameOld(A, D, dt)
  local at = A.piloted and D.at or nil
  if not at then return end
  local H = FPC.hover
  local tt = A.t - D.lift
  local back = H.back * ease(tt / H.backOver)
  local turn = H.yaw * ease((tt - H.yawFrom) / H.yawOver)
  local r0, r1, rf = math.rad(A.yaw0), math.rad(A.yaw0 + turn), math.rad(A.yaw0 + at[3])
  local bx = A.x0 + at[1] * math.cos(r0) - at[2] * math.sin(r0) + math.sin(rf) * back
  local by = A.y0 + at[1] * math.sin(r0) + at[2] * math.cos(r0) - math.cos(rf) * back
  PS.x = bx - (at[1] * math.cos(r1) - at[2] * math.sin(r1))
  PS.y = by - (at[1] * math.sin(r1) + at[2] * math.cos(r1))
  PS.yaw = A.yaw0 + turn
end

