FPF.hullFrameOld = FPF.hullFrame
function FPF.hullFrame()
  local O = PS.outHeld
  if O and P.outHold then
    if S.driving or PS.act or PS.eject or not PS.ent then
      PS.outHeld = nil
    else
      local K = FPC.outHold
      if O.check and S.clock >= O.check then
        O.check = nil
        local own, off, text = nil, nil, "?"
        pcall(function()
          local p = Game.GetPlayer():GetWorldPosition()
          local r = math.rad(PS.yaw)
          local dx, dy = p.x - PS.x, p.y - PS.y
          own = math.sqrt(dx * dx + dy * dy)
          off = math.sqrt((p.x - O.x) ^ 2 + (p.y - O.y) ^ 2)
          text = string.format("%.1f m ahead of BT and %.1f m to its right", dx * -math.sin(r) + dy * math.cos(r), dx * math.cos(r) + dy * math.sin(r))
        end)
        local far = math.sqrt((O.x - PS.x) ^ 2 + (O.y - PS.y) ^ 2)
        if own and own < K.feet and far > K.feet + 0.6 and O.tries < K.tries then
          O.tries = O.tries + 1
          pcall(function() Game.GetTeleportationFacility():Teleport(Game.GetPlayer(), Vector4.new(O.x, O.y, O.z, 1.0), EulerAngles.new(0, 0, O.yaw)) end)
          O.till, O.check = S.clock + K.hold, S.clock + K.check
          log(string.format("DISMOUNT: %.1f s after V was set down V still stands at BT's feet (%s; %.1f m from the place) - set down there again (%d)",
            K.check, text, off or -1.0, O.tries))
        elseif (PS.outLines or 0) < K.lines then
          PS.outLines = (PS.outLines or 0) + 1
          log(string.format("DISMOUNT: %.1f s after V was set down V stands %s (%.1f m from the place it was set down at)", K.check, text, off or -1.0))
        end
      end
      if S.clock < O.till then return end
      if not O.check then PS.outHeld = nil end
    end
  end
  return FPF.hullFrameOld()
end

function FPF.clear(x1, y1, z1, x2, y2, z2)
  local free = true
  for _, group in ipairs({ "Static", "Terrain", "Vehicle" }) do
    pcall(function()
      local hit, res = FPF.sqs():SyncRaycastByCollisionGroup(Vector4.new(x1, y1, z1, 1.0), Vector4.new(x2, y2, z2, 1.0), group, nil, false, false)
      if hit then
        free = false
        local t = -1.0
        pcall(function() t = math.sqrt((res.position.x - x1) ^ 2 + (res.position.y - y1) ^ 2 + (res.position.z - z1) ^ 2) end)
        PS.clearHit = { group, t, math.sqrt((x2 - x1) ^ 2 + (y2 - y1) ^ 2 + (z2 - z1) ^ 2) }
      end
    end)
  end
  return free
end

FPF.standableOld = FPF.standable
function FPF.standable(x, y)
  PS.clearHit = nil
  local g, why = FPF.standableOld(x, y)
  if not g and PS.clearHit and (PS.clearLines or 0) < 12 then
    PS.clearLines = (PS.clearLines or 0) + 1
    local H = PS.clearHit
    local r = math.rad(PS.yaw)
    local dx, dy = x - PS.x, y - PS.y
    log(string.format("DISMOUNT: a place %.1f m ahead of BT and %.1f m to its right is refused (%s): the game's ray for %s met something %.1f m along a way of %.1f m",
      dx * -math.sin(r) + dy * math.cos(r), dx * math.cos(r) + dy * math.sin(r), tostring(why), H[1], H[2], H[3]))
  end
  return g, why
end

function FPF.rayInside(ox, oy, oz, dx, dy, dz, len, px, py, pz, rad, high)
  rad, high = rad or NPC_RADIUS, high or NPC_HEIGHT
  local hx, hy = ox - px, oy - py
  if hx * hx + hy * hy >= rad * rad then return nil end
  local a = dx * dx + dy * dy
  local t1 = len
  if a > 1e-9 then
    local b = hx * dx + hy * dy
    t1 = math.min(len, (-b + math.sqrt(math.max(b * b - a * (hx * hx + hy * hy - rad * rad), 0.0))) / a)
  end
  local t0 = 0.0
  if oz > pz + high then
    if dz >= -1e-6 then return nil end
    t0 = (pz + high - oz) / dz
  elseif oz < pz then
    if dz <= 1e-6 then return nil end
    t0 = (pz - oz) / dz
  end
  if t0 > t1 then return nil end
  return t0
end

function FPF.pointBlank(A, m)
  if not (A.kind == "person" or A.kind == "device") or not A.dx or not A.who then return false end
  local ahead = (A.x - m.x) * A.dx + (A.y - m.y) * A.dy + (A.z - m.z) * A.dz
  if ahead >= FPC.contact.least then return false end
  local what = "?"
  pcall(function() what = (A.kind == "device") and "a turret or camera" or TDBID.ToStringDEBUG(A.who:GetRecordID()) end)
  once("contact" .. what, string.format("XO-16 contact shot: what the crosshair is on (%s) is %.1f m %s the muzzle along the view's line - BT's gun is longer than the way to it; the rounds are let off into it",
    what, math.abs(ahead), ahead < 0 and "behind" or "ahead of"))
  return true
end

FPF.droneReportOld = FPF.droneReport
function FPF.droneReport()
  FPF.droneReportOld()
  local n, inside = PS.contacts or 0, PS.insides or 0
  PS.contacts, PS.insides = nil, nil
  if n > 0 or inside > 0 then
    log(string.format("XO-16 at arm's length in this drive: %d rounds were contact shots (their target nearer than the muzzle); the crosshair's line began inside a listed shape in %d frames",
      n, inside))
  end
end

function FPF.rowPoint(slot, where)
  local p = slotWorld(slot)
  if not p or where == nil or where == 0.0 then return p end
  local a, b = slotWorld("vent_l"), slotWorld("vent_r")
  if not a or not b then return p end
  if where == "mid" then return { x = (a.x + b.x) * 0.5, y = (a.y + b.y) * 0.5, z = (a.z + b.z) * 0.5 } end
  local ux, uy, uz = b.x - a.x, b.y - a.y, b.z - a.z
  local n = math.sqrt(ux * ux + uy * uy + uz * uz)
  if n < 0.05 then return p end
  return { x = p.x + ux / n * where, y = p.y + uy / n * where, z = p.z + uz / n * where }
end

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and ("one segment left: sparks at its rear vents, burning electronics at its front vents and on its back, and "
            .. (P.burnRow and "a row of four of those small fires across its back (each leans as BT moves)" or "the big fire at its back"))
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not L.first or not worse) and (not PF.shown or L.fp == true)
        and (not L.big or not P.burnRow) and (not L.row or P.burnRow)
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local where = L.row and L.row[si] or nil
          local p = (where ~= nil) and FPF.rowPoint(slot, where) or slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key,
                rigid = L.rigid, row = where }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

FPC.burn2.leanRise, FPC.burn2.leanQuick, FPC.burn2.leanMost = 2.2, 8.0, 78.0
FPC.burn2.layers[2].stay = { true, true, false }
FPC.burn2.layers[3].less = { false, false, true }
FPC.burn2.layers[5].less = { false, true, true, false }
FPC.pause = { still = 0.25, again = 1.0, fade = 0.12, lines = 10 }
FPC.pauseCheck = 0.2
