P.burnLess, P.pauseQuiet, P.pauseSim, P.fireCalm = true, true, true, true

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      local two = "one segment left: sparks at its rear vents, burning electronics at its front vents and on its back, and "
        .. (P.burnRow and "a row of four of those small fires across its back (each leans as BT moves)" or "the big fire at its back")
      if P.burnLess and P.burnRow then
        two = "one segment left: sparks at its rear vents, the small flames stay at its front vents, a fire of burning electronics on its back and two more across it (each leans as BT moves)"
      end
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and two
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  local less = P.burnLess and P.burnRow
  for li, L in ipairs(K.layers) do
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not PF.shown or L.fp == true)
        and (not L.big or not P.burnRow) and (not L.row or P.burnRow)
      if on and L.first and worse and not (less and L.stay and L.stay[si]) then on = false end
      if on and less and L.less and not L.less[si] then on = false end
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local where = L.row and L.row[si] or nil
          local p = (where ~= nil) and FPF.rowPoint(slot, where) or slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key,
                rigid = L.rigid, row = where }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

FPF.tfOld = FPF.tf
function FPF.tf(name, line)
  local ok, sub = FPF.tfOld(name, line)
  if ok and line then
    if not PS.lineLen then
      PS.lineLen = {}
      for _, Q in pairs(FPC.say.kinds) do
        for _, L in ipairs(Q.lines or {}) do PS.lineLen[L[1]] = L[3] end
      end
    end
    PS.lineNow = { name = name, from = S.clock, till = S.clock + (PS.lineLen[name] or 3.0), cut = nil }
  end
  return ok, sub
end

function FPF.paused()
  local t = OP77.now()
  if PS.pauseCheckAt ~= nil and t < PS.pauseCheckAt then return PS.pauseLast == true end
  PS.pauseCheckAt = t + FPC.pauseCheck
  PS.pauseLast = FPF.pausedSample()
  return PS.pauseLast
end

function FPF.pausedSample()
  local p = FPF.pausedOld()
  if p then
    PS.pauseBy = PS.pauseHow or "the game's pause state or an open menu"
    PS.sim = nil
    return true
  end
  PS.pauseBy = nil
  if not P.pauseStop or not P.pauseSim then return false end
  local now = nil
  pcall(function() now = EngineTime.ToFloat(Game.GetSimTime()) end)
  if type(now) ~= "number" then
    if PS.simSaid == nil then
      PS.simSaid = false
      log("the game's own simulation time cannot be read: a pause is seen by the game's pause state and its menus only")
    end
    return false
  end
  if PS.simSaid == nil then
    PS.simSaid = true
    log(string.format("the game's own simulation time can be read (%.1f s now): a game whose time stands still for %.2f s counts as paused, whatever stopped it",
      now, FPC.pause.still))
  end
  local Z = PS.sim
  if not Z or now ~= Z.t then
    PS.sim = { t = now, still = 0.0, at = OP77.now() }
    return false
  end
  Z.still = Z.still + math.min(OP77.now() - Z.at, 0.3)
  Z.at = OP77.now()
  if Z.still >= FPC.pause.still then
    PS.pauseBy = "the game's simulation time stands still"
    return true
  end
  return false
end

function FPF.pauseText()
  local H = PS.hp
  if not H then return "no BT's health is counted" end
  return string.format("BT's shield %.0f of %.0f, health %.0f of %.0f, nothing has hit it for %.1f s of its own time",
    H.shield, FPC.health.shield, H.health, FPC.health.segment * FPC.health.segments, S.clock - H.lastHit)
end

function FPF.pauseBegin()
  S.pauseFor = 0.0
  S.pauseSeen = (S.pauseSeen or 0) + 1
  if S.pauseSeen <= FPC.pause.lines then
    log(string.format("PAUSE %d begins (%s): %s", S.pauseSeen, tostring(PS.pauseBy), FPF.pauseText()))
  end
  local N = PS.lineNow
  if P.pauseQuiet and N and not N.cut and S.clock < N.till - 0.1 then
    local axl = FPF.axl()
    local ok, err = false, "AudioXL's class is not there"
    if axl then ok, err = pcall(function() axl:Stop(N.name, FPC.pause.fade) end) end
    N.cut = S.clock - N.from
    once("pausecut" .. tostring(ok), ok and string.format("PAUSE: the line BT was saying (%s, %.1f s of its %.1f s said) is stopped for the pause", N.name, N.cut, N.till - N.from)
      or ("PAUSE: the line BT was saying could NOT be stopped: " .. tostring(err)))
  end
end

function FPF.pauseEnd()
  if (S.pauseSeen or 0) <= FPC.pause.lines then
    log(string.format("PAUSE %d ends after %.1f s: %s", S.pauseSeen or 0, S.pauseFor or 0.0, FPF.pauseText()))
  end
  PS.sim = nil
  local N = PS.lineNow
  if N and N.cut then
    local left = (N.till - N.from) - N.cut
    PS.lineNow = nil
    if left > FPC.pause.again and P.talk and P.sounds then
      local ok = FPF.tf(N.name, true)
      if ok and PS.talk then PS.talk.quietTill = math.max(PS.talk.quietTill or 0.0, S.clock + (N.till - N.from) + FPC.say.gap) end
      once("pauseagain", string.format("PAUSE: the line that was cut (%s, %.1f s of it left) is said again from its beginning", N.name, left))
    end
  end
end

FPC.burn2.layers[2].stayHalf = { true, true, true }
FPC.burn2.layers[3].half = { false, false, false }
FPC.burn2.layers[5].half = { true, false, false, false }
