P.burnHalf = true

function FPF.healthSet(segments, by)
  local H, K = PS.hp, FPC.health
  if not H or not PS.ent or PS.act or PS.eject or PS.warm then
    log("BT's health cannot be set now: no BT stands there, or it is in a scene")
    return
  end
  H.health, H.shield, H.lastHit, H.mending = K.segment * segments, 0.0, S.clock + FPC.healthTest.hold, nil
  log(string.format("BT's health is set to %d of %d segments (%.0f of %.0f; the shield to nothing) by %s - nothing of it comes back for %.0f s, then it mends as after a hit",
    segments, K.segments, H.health, K.segment * K.segments, tostring(by), FPC.healthTest.hold))
end

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  local less = P.burnLess and P.burnRow
  local half = less and P.burnHalf
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      local two = "one segment left: sparks at its rear vents, burning electronics at its front vents and on its back, and "
        .. (P.burnRow and "a row of four of those small fires across its back (each leans as BT moves)" or "the big fire at its back")
      if half then
        two = "one segment left: sparks at its rear vents, the three small flames stay, and one fire of burning electronics burns at its main thruster (it leans as BT moves)"
      elseif less then
        two = "one segment left: sparks at its rear vents, the small flames stay at its front vents, a fire of burning electronics on its back and two more across it (each leans as BT moves)"
      end
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and two
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    local stay = (half and L.stayHalf) or L.stay
    local few = (half and L.half) or L.less
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not PF.shown or L.fp == true)
        and (not L.big or not P.burnRow) and (not L.row or P.burnRow)
      if on and L.first and worse and not (less and stay and stay[si]) then on = false end
      if on and less and few and not few[si] then on = false end
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local where = L.row and L.row[si] or nil
          local p = (where ~= nil) and FPF.rowPoint(slot, where) or slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key,
                rigid = L.rigid, row = where }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

FPC.airburst = { ring = 13.0, n = 18, up = 3.5, last = 0.24, keep = 6.0,
  waves = { { 3.0, 6, 0.0, 0.7 }, { 6.5, 10, 0.07, 0.7 }, { 10.0, 14, 0.15, 0.7 } },
  boom = [[base\fx\vehicles\av\av_panzer\weapons\v_panzer_rocket_explosion.effect]],
  puff = [[base\fx\environment\dust\characters\e_dust_cloud_impact.effect]] }
P.airburst = true

function FPF.airburst(A, D)
  local K = FPC.airburst
  if not P.fxOn then return end
  local x, y, z = PS.x, PS.y, PS.z + K.up
  local boom = FPF.fxAt(K.boom, x, y, z, PS.yaw, 0.0)
  PS.airburst = { x = x, y = y, z = z, at = S.clock, next = 1, puffs = 0 }
  log(string.format("BT's AIR BURST %.2f s into the fall, %.0f m above where it will stand (Titanfall's own moment for it): an explosion at it (%s); a ring of smoke spreads from it - %d circles in %.2f s, the last one, %d puffs %.0f m across, stays",
    A.t, PS.z - A.to.z, boom and "started" or "could NOT be started", #K.waves + 1, K.last, K.n, K.ring * 2.0))
  FPF.airburstFrame()
end

function FPF.airburstFrame()
  local B, K = PS.airburst, FPC.airburst
  if not B then return end
  local t = S.clock - B.at
  local function circle(r, n, life, turn)
    for i = 1, n do
      local a = ((i - 1) / n + turn) * 2.0 * math.pi
      local inst = FPF.fxAt(K.puff, B.x - math.sin(a) * r, B.y + math.cos(a) * r, B.z, math.deg(a), 0.0)
      if inst then
        B.puffs = B.puffs + 1
        PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + life, carry = false }
      end
    end
  end
  while B.next <= #K.waves and t >= K.waves[B.next][3] do
    local W = K.waves[B.next]
    circle(W[1], W[2], W[4], (B.next % 2) * 0.5 / W[2])
    B.next = B.next + 1
  end
  if B.next > #K.waves and t >= K.last then
    circle(K.ring, K.n, K.keep, 0.0)
    PS.airburst = nil
  end
end

function FPF.scanCheck(ent)
  local has, who, name = "cannot be asked", "cannot be read", "?"
  pcall(function()
    local comp = ent:FindComponentByName("scanning")
    if comp then has = tostring(comp:HasValidObjectDescription() == true) else has = "no scanning component found by that name" end
  end)
  pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
  pcall(function()
    local rec = TweakDBInterface.GetCharacterRecord(ent:GetRecordID())
    who = tostring(GetLocalizedTextByKey(rec:Affiliation():LocalizedName()))
  end)
  log(string.format("the game's scanner on BT (%s): a description is on it: %s; its affiliation reads \"%s\"", name, has, who))
end

