function FPF.airburst(A, D)
  local K = FPC.airburst
  if not P.fxOn then return end
  local x, y, z = PS.x, PS.y, PS.z + K.up
  local boom = FPF.fxAt(K.boom, x, y, z, PS.yaw, 0.0)
  PS.airburst = { x = x, y = y, z = z, at = S.clock, next = 1, puffs = 0, live = {}, ringOut = false }
  log(string.format("BT's AIR BURST %.2f s into the fall, %.0f m above where it will stand (Titanfall's own moment for it): an explosion at it (%s); a ring of smoke spreads from it - %d circles in %.2f s, the last one, %d clouds %.0f m across, stays for %.0f s",
    A.t, PS.z - A.to.z, boom and "started" or "could NOT be started", #K.waves + 1, K.last, K.n, K.ring * 2.0, K.keep))
  FPF.airburstFrame()
end

function FPF.airburstFrame()
  local B, K = PS.airburst, FPC.airburst
  if not B then return end
  local t = S.clock - B.at
  local function circle(r, n, breakAt, killAt, turn)
    for i = 1, n do
      local a = ((i - 1) / n + turn) * 2.0 * math.pi
      local inst = FPF.fxAt(K.puff, B.x - math.sin(a) * r, B.y + math.cos(a) * r, B.z, math.deg(a), 0.0)
      if inst then
        B.puffs = B.puffs + 1
        B.live[#B.live + 1] = { inst = inst, breakAt = breakAt, killAt = killAt }
      end
    end
  end
  while B.next <= #K.waves and t >= K.waves[B.next][3] do
    local W = K.waves[B.next]
    circle(W[1], W[2], nil, S.clock + W[4], (B.next % 2) * 0.5 / W[2])
    B.next = B.next + 1
  end
  if not B.ringOut and B.next > #K.waves and t >= K.last then
    B.ringOut = true
    circle(K.ring, K.n, S.clock + K.hold, B.at + K.last + K.keep, 0.0)
  end
  for i = #B.live, 1, -1 do
    local L = B.live[i]
    if L.breakAt and S.clock >= L.breakAt then
      L.breakAt = nil
      FPF.fxBreak152(L.inst)
    end
    if S.clock >= L.killAt then
      FPF.fxBreak152(L.inst)
      FPF.fxKill152(L.inst)
      table.remove(B.live, i)
    end
  end
  if B.ringOut and #B.live == 0 then
    PS.airburst = nil
    log(string.format("BT's air burst: its ring is gone (%d clouds of smoke in all)", B.puffs))
  end
end

FPF.fxFrameOld = FPF.fxFrame
function FPF.fxFrame()
  FPF.fxFrameOld()
  if PS.airburst then guard("the air burst's ring", FPF.airburstFrame) end
end

function FPF.fxAtAxes(path, x, y, z, ax, ay, az, ux, uy, uz)
  if not path then return nil end
  local inst = nil
  local ok, err = pcall(function()
    local rx, ry, rz = ay * uz - az * uy, az * ux - ax * uz, ax * uy - ay * ux
    local m00, m01, m02 = rx, ax, ux
    local m10, m11, m12 = ry, ay, uy
    local m20, m21, m22 = rz, az, uz
    local tr = m00 + m11 + m22
    local qi, qj, qk, qr
    if tr > 0.0 then
      local q = math.sqrt(tr + 1.0) * 2.0
      qr, qi, qj, qk = 0.25 * q, (m21 - m12) / q, (m02 - m20) / q, (m10 - m01) / q
    elseif m00 > m11 and m00 > m22 then
      local q = math.sqrt(1.0 + m00 - m11 - m22) * 2.0
      qr, qi, qj, qk = (m21 - m12) / q, 0.25 * q, (m01 + m10) / q, (m02 + m20) / q
    elseif m11 > m22 then
      local q = math.sqrt(1.0 + m11 - m00 - m22) * 2.0
      qr, qi, qj, qk = (m02 - m20) / q, (m01 + m10) / q, 0.25 * q, (m12 + m21) / q
    else
      local q = math.sqrt(1.0 + m22 - m00 - m11) * 2.0
      qr, qi, qj, qk = (m10 - m01) / q, (m02 + m20) / q, (m12 + m21) / q, 0.25 * q
    end
    local t = WorldTransform.new()
    WorldTransform.SetPosition(t, Vector4.new(x, y, z, 1.0))
    WorldTransform.SetOrientation(t, Quaternion.new(qi, qj, qk, qr))
    inst = OP77.spawnEffect(path, t, x, y, z, { i = qi, j = qj, k = qk, r = qr })
  end)
  local F = PS.fxStat
  if ok then
    F.ok = F.ok + 1
  else
    F.failed = F.failed + 1
    once("fxaxes" .. tostring(err), "an effect could not be started turned by its axes (" .. tostring(path) .. "): " .. tostring(err))
  end
  return inst
end

function FPF.punchDisc(x, y, z, fx, fy)
  local K = FPC.punchDisc
  local sx, sy = fy, -fx
  local n = 0
  for i = 1, K.n do
    local a = (i - 1) / K.n * 2.0 * math.pi
    local c, s = math.cos(a), math.sin(a)
    local ox, oy, oz = sx * c, sy * c, s
    if FPF.fxAtAxes(K.path, x + ox * K.r, y + oy * K.r, z + oz * K.r, ox, oy, oz, fx, fy, 0.0) then n = n + 1 end
  end
  PS.punchDiscs = (PS.punchDiscs or 0) + 1
  if PS.punchDiscs <= 3 then
    log(string.format("PUNCH the fist's effect: a disc of dust upright %.1f m above BT's ground, its wide face to BT (%d of %d started, %.1f m round the fist's place)",
      z - PS.z, n, K.n, K.r))
  end
end

