        two = "one segment left: sparks at its rear vents, the small flames stay at its front vents, a fire of burning electronics on its back and two more across it (each leans as BT moves)"
      end
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and two
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    local stay = (half and L.stayHalf) or L.stay
    local few = (half and L.half) or L.less
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not PF.shown or L.fp == true)
        and (not L.big or not P.burnRow) and (not L.row or P.burnRow or L.small) and (not L.small or small)
      if small then
        if L.mid or L.big then on = false end
      else
        if on and L.first and worse and not (less and stay and stay[si]) then on = false end
        if on and less and few and not few[si] then on = false end
      end
      local R = B[key]
      if on then
        if not R or S.clock >= R.next then
          local where = L.row and L.row[si] or nil
          local p = (where ~= nil) and FPF.rowPoint(slot, where) or slotWorld(slot)
          if p then
            local inst = FPF.fxAt(L.path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key,
                rigid = L.rigid, row = where }
              B[key] = { next = S.clock + L.life - K.overlap }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

FPF.q.api = 3

function FPF.questDrop(x, y, z, yaw, locked)
  if S.gone or not Game.GetPlayer() then return false, "no session" end
  if S.driving then return false, "V is in BT" end
  if PS.act and PS.act.kind == "leave" then return false, "BT is leaving" end
  yaw = yaw or 0.0
  local g = nil
  pcall(function() g = FPF.landingGround(x, y, z - 1.0) end)
  local mid = g or z
  local low, feet = mid, {}
  local r = math.rad(yaw)
  do
    local fx, fy = -math.sin(r), math.cos(r)
    for i, f in ipairs(FPF.q.feet) do
      local gz = nil
      pcall(function() gz = groundZ(x + fy * f[1] + fx * f[2], y - fx * f[1] + fy * f[2], mid - 1.0) end)
      feet[i] = gz and string.format("%.2f", gz) or "none"
      if gz and math.abs(gz - mid) <= FPF.q.uneven and gz < low then low = gz end
    end
  end
  local D, K = SCENES.drop, FPC.drop
  local a = D.path[1]
  local held = low + FPF.q.lift
  FPF.q.locked = locked == true
  spawnPilot({ x = x - math.sin(r) * a[1], y = y + math.cos(r) * a[1], z = held + a[2], yaw = yaw })
  if not PS.id then return false, "the game did not take the spawn" end
  PS.act = { kind = "drop", t = 0.0, wait = true, to = { x = x, y = y, z = held - K.lift }, done = {},
    quest = { x = x, y = y, z = low, yaw = yaw, lift = FPF.q.lift } }
  FPF.q.drops = (FPF.q.drops or 0) + 1
  log(string.format("BT is DROPPED from the sky onto (%.1f, %.1f, %.2f) facing %.0f for another script - it will stay down there, kneeling, %s (the height asked for %.2f; ground under its middle %s, under its feet %s / %s; it appears %.0f m up, %.0f m behind the place; the call's lock and the wait for a BT are not touched)",
    x, y, low, yaw, FPF.q.locked and "locked" or "open to board", z, g and string.format("%.2f", g) or "NOT found", feet[1] or "-", feet[2] or "-", a[2], -a[1]))
  return true
end

function FPF.questDown(A)
  local Q = A.quest
  local was = PS.z
  PS.kneel = { x = Q.x, y = Q.y, z = Q.z, yaw = Q.yaw, lift = Q.lift }
  PS.act = nil
  PS.near, PS.useDown = nil, false
  FPF.q.parks = FPF.q.parks + 1
  FPF.kneelFrame(0.0)
  log(string.format("BT that fell onto (%.1f, %.1f, %.2f) STAYS DOWN there, kneeling, %s (%.1f s after it began to fall; its height changes by %.3f m as the kneel takes over)",
    Q.x, Q.y, Q.z, FPF.q.locked and "locked" or "open to board", A.t, PS.z - was))
end

