FPF.questPark57, FPF.questDrop57 = FPF.questPark, FPF.questDrop
function FPF.questPark(x, y, z, yaw, locked)
  local ok, why = FPF.questPark57(x, y, z, yaw, locked)
  if ok then PS.questBt, FPF.q.guard, FPF.q.heldAs = true, false, nil end
  return ok, why
end
function FPF.questDrop(x, y, z, yaw, locked)
  local ok, why = FPF.questDrop57(x, y, z, yaw, locked)
  if ok then PS.questBt, FPF.q.guard, FPF.q.heldAs = true, false, nil end
  return ok, why
