function FPF.questHeld()
  if not PS.questBt or S.driving or PS.kneel or PS.mode ~= "wait" or not PS.ent or not IsDefined(PS.ent) then return nil end
  if FPF.q.guard then return "guard" end
  if FPF.q.locked then return "still" end
  return nil
end

function FPF.questSafe()
  return FPF.q.safe == true and PS.questBt == true and FPF.q.locked == true and not S.driving
end

function FPF.questRelease(why)
  local own = FPF.q.own
  if not own then return end
  FPF.q.own, FPF.q.heldAs = nil, nil
  P.buddy, P.hold, P.peace = own[1], own[2], own[3]
  log(string.format("the quest's hold on BT is over (%s): V's own order for it is back - %s", tostring(why), FPC.orders[FPF.order()].log))
end

function FPF.questGuard(on)
  if not PS.questBt then return false, "no BT of the quest's" end
  if S.driving then return false, "V is in BT" end
  on = on == true
  if FPF.q.guard ~= on then
    FPF.q.guard = on
    FPF.q.guards = (FPF.q.guards or 0) + (on and 1 or 0)
    log(string.format("the quest's BT %s (asked for by another script)%s", on and "GUARDS: it holds its place and fights by itself" or
      (FPF.q.locked and "stops guarding: it does nothing by itself while it is locked" or "stops guarding: V's own order for it counts again"),
      PS.kneel and " - it kneels: that counts once it stands" or ""))
  end
  return true
end

FPF.buddyRun57 = FPF.buddyRun
function FPF.buddyRun(dt)
  local held = FPF.questHeld()
  if not held then
    FPF.questRelease("it is free")
    return FPF.buddyRun57(dt)
  end
  if not FPF.q.own then
    FPF.q.own = { P.buddy, P.hold, P.peace }
    log(string.format("the quest holds its standing BT: V's own order for BT (%s) is put aside until the hold is over", FPC.orders[FPF.order()].log))
  end
  P.buddy, P.hold, P.peace = held == "guard", true, false
  if FPF.q.heldAs ~= held then
    FPF.q.heldAs = held
    log(held == "guard" and "the quest's BT stands and GUARDS: it holds its place and fights by itself"
      or "the quest's BT stands, locked: it does nothing by itself and cannot be boarded")
  end
  return FPF.buddyRun57(dt)
end

FPF.orderSet57 = FPF.orderSet
