  local held = FPF.questHeld()
  if held then
    log(string.format("BT's order is not taken (%s): the BT that stands there is a quest's and held by it (%s)", tostring(by),
      held == "guard" and "it guards" or "locked"))
    return
  end
  return FPF.orderSet57(n, by)
end

FPF.homeStart57 = FPF.homeStart
