  end
  return FPF.homeStart57(by)
end

FPF.decoyFrame57 = FPF.decoyFrame
function FPF.decoyFrame()
  if PS.questBt and S.driving and S.pilot then
    PS.questBt = nil
    if FPF.q.guard then log("V is in the quest's BT: its guard is over") end
    FPF.q.guard = false
    log("V has boarded the quest's BT - it is V's own from here on")
  end
  if FPF.q.own and not FPF.questHeld() then FPF.questRelease(PS.questBt and "it is free" or "that BT is gone or V's own now") end
  if FPF.questSafe() then
    local H = PS.hp
    if H then H.pend.a, H.pend.b, H.bigV = 0.0, 0.0, nil end
    if not FPF.q.safeSaid then
      FPF.q.safeSaid = true
      log("the quest keeps its BT safe: it is still shot at (its stand-in stays), what hits it is thrown away")
    end
  else
    FPF.q.safeSaid = nil
  end
  return FPF.decoyFrame57()
end

FPF.keepNow57 = FPF.keepNow
function FPF.keepNow()
  if PS.questBt and FPF.q.locked and not PS.kneel and not S.driving then return 0 end
  return FPF.keepNow57()
end

FPF.say57 = FPF.say
