function FPF.jumpAt(list, t)
  local x = clamp(t * FPC.jumpClip.fps, 0.0, #list - 1)
  local i = math.floor(x)
  local a, b = list[i + 1], list[math.min(i + 2, #list)]
  return a + (b - a) * (x - i)
end

function FPF.jumpCan()
  local J = PS.jump
  if not P.jump then return false, "the jump is switched off" end
  if J and not (J.out or (J.stage == "land" and J.free)) then return false, "it is in a jump" end
  if PS.punch then return false, "its fist is out" end
  if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then return false, "it is in a dash" end
  return true
end

function FPF.jumpStart()
  local was = PS.jump
  local n = (PS.jumps or 0) + 1
  PS.jump = { stage = "crouch", t = 0.0, air = 0.0, vz = 0.0, z0 = PS.z, floor = PS.z, top = 0.0, x0 = PS.x, y0 = PS.y,
    speed0 = PS.speed, done = {}, n = n, up = FPF.jumpUp() }
  PS.jumps, PS.jumpT = n, 0.0
  if not was then PS.jumpW, PS.landW, PS.landT = PS.jumpW or 0.0, 0.0, 0.0 end
  if n <= FPC.jump.lines then
    log(string.format("JUMP %d: the take-off begins at %.1f m/s%s - its feet leave the ground %.2f s from now", n, PS.speed,
      was and " (out of the landing of the jump before)" or "", FPC.jumpClip.lift / FPC.jumpClip.fps))
  end
end

function FPF.jumpKeys(jump, dash)
  if jump then
    local ok, why = FPF.jumpCan()
    if ok then
      FPF.jumpStart()
    elseif S.clock - (PS.jumpSaid or -10.0) > 1.0 and (PS.jumpRefused or 0) < 12 then
      PS.jumpSaid, PS.jumpRefused = S.clock, (PS.jumpRefused or 0) + 1
      log("PILOT jump refused: " .. tostring(why))
    end
  end
  local J = PS.jump
  if not J or J.out then return dash end
  if dash and J.stage == "land" and J.free then
    J.out, J.outWhy = FPC.jump.fadeOut, "a dash"
    return true
  end
  if dash and J.stage == "air" and P.airDash and FPF.perk("airdash") > 0 then return true end
  return false
end

function FPF.jumpWish(wish)
  local J = PS.jump
  if J.stage == "air" then return (wish < 0.01) and "keep" or nil end
  if J.stage == "land" and not J.free then return "stop" end
  return nil
end

function FPF.jumpRate(rate)
  local J = PS.jump
  if J.stage == "air" then return FPC.jump.steer end
  if J.stage == "land" and not J.free then return FPC.jump.brake end
  return rate
end

function FPF.jumpCeiling(x, y, z, rise)
  local K = FPC.jump
  local hit = false
  pcall(function()
    local from = Vector4.new(x, y, z + K.headFrom, 1.0)
    local to = Vector4.new(x, y, z + K.head + math.max(rise, 0.0) + 0.3, 1.0)
    for _, group in ipairs({ "Static", "Terrain" }) do
      if not hit and FPF.sqs():SyncRaycastByCollisionGroup(from, to, group, nil, false, false) then hit = true end
    end
  end)
  return hit
end

function FPF.jumpSound(kind)
  if not P.sounds then return end
  local K = FPC.jump
  local list = K.sounds[kind]
  PS.jumpSoundN = PS.jumpSoundN or {}
  PS.jumpSoundN[kind] = (PS.jumpSoundN[kind] or math.random(0, #list - 1)) % #list + 1
  local name = list[PS.jumpSoundN[kind]]
  local level = FPF.viewVolume() * (PF.shown and ((kind == "start") and P.fpSkills or K.landFp) or 1.0)
  local ok = FPF.ownSound(name, level)
  if not ok then ok = FPF.tf(name) end
  once("jumpsound" .. kind .. (PF.shown and "fp" or "tp") .. tostring(ok), string.format("PILOT the jump's sound (%s): %s (Titanfall's sample, %s, level %.2f)%s",
    kind, name, PF.shown and "in the cockpit" or "seen from outside", level, ok and "" or " - could NOT be played"))
end

function FPF.jumpJets(on)
  local J, K = PS.jump, FPC.jump
  if on then
    FPF.thruster(true, "a jump")
    FPF.jumpSound("start")
    local path = FPF.fxPath("dash")
    if path and not PF.shown and slotWorld(FPC.ports.ahead[1]) ~= nil then
      local T = FPC.jet
      FPF.fxTrain(path, FPC.ports.ahead, K.jetFor, T.every, T.life, PS.yaw + 180.0, K.jetPitch, true, T.gap)
    end
  else
    FPF.thruster(false, "a jump's landing")
    if J then J.done.jetsOff = true end
  end
end

function FPF.jumpTouch(J)
  local K = FPC.jump
  local path = FPF.fxPath("step")
  if path then
    local r = math.rad(PS.yaw)
    for _, side in ipairs({ -0.9, 0.9, 0.0 }) do
      FPF.fxAt(path, PS.x + math.cos(r) * side, PS.y + math.sin(r) * side, PS.z + 0.05, PS.yaw, 0.0)
    end
  end
  FPF.jumpSound("land")
  if PF.shown then PF.joltV = PF.joltV + 2.0 * math.pi * FPC.joltFreq / FPC.joltPeak * FP.jolt * P.jolt * K.jolt end
  local down, crushed = 0, 0
  if P.solid then
    PS.npcsAt = -10
    refreshNpcs()
    for i, ent in ipairs(PS.npcs) do
      if IsDefined(ent) and not PS.npcShape[i] then
        pcall(function()
          local p = ent:GetWorldPosition()
          local rx, ry = p.x - PS.x, p.y - PS.y
          local dist = math.sqrt(rx * rx + ry * ry)
          if dist < K.stomp and math.abs(p.z - PS.z) < 3.0 then
            local n = math.max(dist, 0.1)
            PS.bumped[tostring(ent:GetEntityID())] = S.clock
            FPF.knock(ent, p, rx / n, ry / n)
            down = down + 1
          end
        end)
      end
    end
    for _, veh in ipairs(FPF.vehicles()) do
      pcall(function()
        local p = veh:GetWorldPosition()
        local rx, ry = p.x - PS.x, p.y - PS.y
        if math.sqrt(rx * rx + ry * ry) < K.crush and math.abs(p.z - PS.z) < 2.5 then
          FPF.dent(veh, 1.0, true)
          FPF.wreck(veh, K.wreck)
          crushed = crushed + 1
        end
      end)
    end
  end
  if P.fear == 3 then FPF.stim("Terror", FPC.stims.walk * 2.0, 1.2) end
  J.down, J.crushed = down, crushed
end

function FPF.jumpFrame(dt, f, s)
  local J, K, C = PS.jump, FPC.jump, FPC.jumpClip
  if not J then return end
  local fps = C.fps
  J.t = J.t + dt
  if J.out then
    PS.jumpW = math.max(0.0, PS.jumpW - dt / J.out)
    if PS.jumpW <= 0.0 then
      FPF.jumpEnd(J.outWhy or "it stands")
      return
    end
  else
    PS.jumpW = math.min(1.0, PS.jumpW + dt / K.fadeIn)
  end
  if J.stage ~= "land" then PS.landW = math.max(0.0, PS.landW - dt / K.landIn) end
  if not J.done.jets and J.stage ~= "land" and J.t >= C.jets / fps then
    J.done.jets = true
    FPF.jumpJets(true)
  end
  if J.stage == "crouch" then
    PS.jumpT = math.min(J.t, C.start / fps)
    if J.t >= C.lift / fps then
      J.stage, J.air, J.vz, J.z0, J.floor, J.liftAt = "air", 0.0, 0.0, PS.z, PS.z, J.t
      local path = FPF.fxPath("step")
      if path then
        local r = math.rad(PS.yaw)
        for _, side in ipairs({ -0.9, 0.9 }) do
          FPF.fxAt(path, PS.x + math.cos(r) * side, PS.y + math.sin(r) * side, PS.z + 0.05, PS.yaw, 0.0)
        end
      end
    end
  end
  if J.stage == "air" then
    J.air = J.air + dt
    local tStart, tLoop = C.start / fps, C.loop / fps
    PS.jumpT = (J.t <= tStart) and J.t or (tStart + (J.t - tStart) % tLoop)
    local vz
    if not J.pushed then
      if J.air < K.ramp then
        vz = (J.up or K.speed) * J.air / K.ramp
      else
        J.pushed = true
        vz = (J.up or K.speed) - K.gravity * (J.air - K.ramp)
      end
    else
      vz = J.vz - K.gravity * dt
    end
    if vz < -K.fall then vz = -K.fall end
    vz = FPF.jetThrust(J, vz, dt)
    if J.pushed and vz < 0.0 and PS.dashT ~= nil and PS.dashT < TF.dodgeTime then vz = 0.0 end
    local z = PS.z + (J.vz + vz) * 0.5 * dt
    if z > PS.z and FPF.jumpCeiling(PS.x, PS.y, PS.z, z - PS.z) then
      z, vz, J.pushed = PS.z, 0.0, true
      J.bumps = (J.bumps or 0) + 1
    end
    J.vz = vz
    if vz <= 0.0 and z <= J.floor then
      J.stage, J.landed, J.vzDown, J.airTime = "land", 0.0, -vz, J.air
      if J.fall and (J.z0 + J.top) - J.floor < FPC.slam.from then J.light, J.free = true, true end
      if PS.z < J.floor - 0.02 then J.riseTo, z = J.floor, PS.z else z = J.floor end
      PS.z = z
      PS.landT = 0.0
      FPF.jumpJets(false)
    else
      PS.z = z
      if z - J.z0 > J.top then J.top = z - J.z0 end
    end
  elseif J.stage == "land" then
    J.landed = J.landed + dt
    if J.riseTo then
      PS.z = math.min(J.riseTo, PS.z + 14.0 * dt)
      if PS.z >= J.riseTo then J.riseTo = nil end
    end
    PS.landW = math.min(1.0, PS.landW + dt / K.landIn)
    local tLand = C.land / fps
    PS.landT = math.min(J.landed, tLand)
    if not J.done.touch and J.landed >= (C.down - 1) / fps then
      J.done.touch = true
      FPF.jumpTouch(J)
    end
    if not J.free and J.landed >= K.free then J.free = true end
    if J.free and not J.out then
      if math.abs(f) > 0.1 or math.abs(s) > 0.1 then
        J.out, J.outWhy = K.fadeOut, "it moves on"
      elseif PS.outAsked then
        J.out, J.outWhy = K.fadeOut, "V climbs out"
      elseif J.landed >= tLand - K.tail then
        J.out, J.outWhy = K.tail, "it stands"
      end
    end
  end
  do
    local want = (J.stage == "air" and PS.dashT ~= nil and PS.dashT < K.dashFor) and 1.0 or 0.0
    local w = PS.airDashW or 0.0
    PS.airDashW = (want > w) and math.min(want, w + dt / K.dashIn) or math.max(want, w - dt / K.dashOut)
  end
  local hip = FPF.jumpAt(C.hip, PS.jumpT)
  if PS.landW > 0 then hip = hip + (FPF.jumpAt(C.hipLand, PS.landT) - hip) * PS.landW end
  PS.jumpEye = (hip - C.ready) * PS.jumpW * K.eye
end

function FPF.jumpEnd(why, hard)
  local J = PS.jump
  if not J then return end
  PS.jump = nil
  if J.stage == "air" then PS.z = J.floor end
  if J.riseTo then PS.z = J.riseTo end
  if J.done.jets and not J.done.jetsOff then FPF.thruster(false, "the jump is over") end
  PS.jumpW, PS.landW, PS.jumpEye = 0.0, 0.0, 0.0
  if J.n <= FPC.jump.lines or hard then
    log(string.format("JUMP %d over (%s): its feet left the ground %.2f s after the key; %.2f s in the air, %.2f m up at its highest, carried %.1f m; it came down at %.1f m/s onto ground %+.2f m against where it left%s%s%s; %.2f s from the key to the end",
      J.n, tostring(why), J.liftAt or 0.0, J.airTime or J.air, J.top, math.sqrt((PS.x - J.x0) ^ 2 + (PS.y - J.y0) ^ 2), J.vzDown or 0.0,
      (J.stage == "crouch") and 0.0 or (J.floor - J.z0),
      (J.bumps or 0) > 0 and string.format("; a ceiling stopped the rise (%d frames)", J.bumps) or "",
      (J.down or 0) > 0 and string.format("; people thrown down: %d", J.down) or "",
      (J.crushed or 0) > 0 and string.format("; vehicles crushed: %d", J.crushed) or "", J.t))
  end
end

function FPF.jumpHolds(what)
  local J = PS.jump
  if not J then return false end
  if J.stage == "air" then
    if not J.heldSaid then
      J.heldSaid = true
      log(what .. ": BT is in the air - that waits until it has landed")
    end
    return true
  end
  FPF.jumpEnd(what, true)
  return false
end

FPF.trample58, FPF.pushFrame58, FPF.vUnder58 = FPF.trample, FPF.pushFrame, FPF.vUnder
function FPF.trample()
  if PS.jump and PS.jump.stage == "air" then return end
  return FPF.trample58()
end
function FPF.pushFrame()
  if PS.jump and PS.jump.stage == "air" then return end
  return FPF.pushFrame58()
end
function FPF.vUnder()
  local J = PS.jump
  if not (J and J.stage == "air") then return FPF.vUnder58() end
  local z = PS.z
  PS.z = J.floor
  local ok, err = pcall(FPF.vUnder58)
  PS.z = z
  if not ok then error(err, 0) end
end

FPF.throwStart58, FPF.ejectStart58 = FPF.throwStart, FPF.ejectStart
