FPF.q.api = 5
FPF.q.destroyed, FPF.q.harm = 0, 1.0
P.questDeath = true
FPC.pose = { sounds = { q_fall = "bt7274_q_fall", q_rise = "bt7274_q_rise", q_up = "bt7274_q_up" }, near = 25.0, far = 85.0, quiet = 0.15, lines = 12 }

function FPF.poseSound(key)
  local K = FPC.pose
  local name = K.sounds[key]
  if not P.sounds or not name then return end
  local level = 1.0
  pcall(function()
    local p = Game.GetPlayer():GetWorldPosition()
    local dist = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2)
    level = clamp(1.0 - (dist - K.near) / (K.far - K.near) * (1.0 - K.quiet), K.quiet, 1.0)
  end)
  local ok = FPF.ownSound(name, level)
  if not ok then ok = FPF.tf(name) end
  once("posesound" .. key .. tostring(ok), string.format("the quest's BT, its low poses: Titanfall's own sound of the scene (%s, level %.2f)%s", name, level,
    ok and "" or " - could NOT be played"))
end

function FPF.poseShift(Q, at, over)
  local r = math.rad(Q.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local nx, ny = Q.x + fy * at[1] + fx * at[2], Q.y - fx * at[1] + fy * at[2]
  local g = nil
  pcall(function() g = groundZ(nx, ny, Q.z) end)
  local z = (g and math.abs(g - Q.z) <= FPF.q.uneven * 2.0) and g or Q.z
  if over then Q.zFrom, Q.zOver = Q.z, over else Q.zFrom, Q.zOver = nil, nil end
  Q.x, Q.y, Q.z, Q.yaw = nx, ny, z, wrap180(Q.yaw + at[3])
end

function FPF.poseNext(Q)
  local want, now = Q.want, Q.pose or "kneel"
  if not want then return false end
  local kind = nil
  if want == "stand" then
    if now == "kneel" then
      local board = Q.board
      Q.want, Q.board = nil, nil
      FPF.kneelStand59(board ~= nil, board and board.demo)
      return false
    end
    kind = (now == "down") and "rise" or "up"
  elseif want == "down" then
    if now == "kneel" then kind = "getup" end
  elseif want == "guard" then
    if now == "kneel" then kind = "getup" elseif now == "down" then kind = "rise" end
  end
  if not kind then
    Q.want = nil
    return false
  end
  local D = (kind == "getup") and SCENES.getup or ((kind == "rise") and SCENES.q_rise or ((kind == "up") and SCENES.q_up or SCENES.q_fall))
  Q.move = { kind = kind, scene = D, t = 0.0 }
  Q.moves = (Q.moves or 0) + 1
  guard("animate always", FPF.animAll)
  if kind == "getup" then guard("Titanfall's sounds", FPF.tf, FPC.tf.getup) end
  if (FPF.q.poseLines or 0) < FPC.pose.lines then
    FPF.q.poseLines = (FPF.q.poseLines or 0) + 1
    log(string.format("the quest's BT (%s, asked to %s): %s", now, want,
      (kind == "getup") and "it gets to its feet first - then it collapses" or ((kind == "rise") and string.format("it stirs and settles into its crouch (%.1f s)", D.time)
        or string.format("it takes its gun off the ground and stands up (%.1f s)", D.time))))
  end
  return true
end

function FPF.poseStood(Q)
  PS.x, PS.y, PS.z, PS.yaw = Q.x, Q.y, Q.z + Q.lift, Q.yaw
  PS.kneel = nil
  PS.kneelBoard = Q.board
  PS.act = { kind = "getup", t = SCENES.getup.time, step = 0, to = { x = Q.x, y = Q.y, z = Q.z }, done = {}, fromKneel = true, lift = Q.lift }
  PS.near, PS.useDown = nil, false
  PS.sceneW, PS.pilotW, PS.sceneClip, PS.sceneTime = 1.0, 0.0, SCENES.getup.clip, SCENES.getup.time
  FPF.q.stands = FPF.q.stands + 1
  FPF.placeBt()
end

function FPF.poseArrived(Q, M)
  local K = M.kind
  Q.move = nil
  if K == "getup" and Q.want == "stand" then
    FPF.poseStood(Q)
    log(string.format("the quest's BT STANDS at (%.1f, %.1f, %.2f) - it was told to get up before it could collapse%s", Q.x, Q.y, Q.z, Q.board and "; V boards it now" or ""))
  elseif K == "getup" then
    local D = SCENES.q_fall
    FPF.poseShift(Q, D.at, D.time)
    Q.move = { kind = "fall", scene = D, t = 0.0 }
    log(string.format("the quest's BT stumbles and COLLAPSES onto its hands and knees (%.1f s): it comes down %.1f m from where it knelt - the object is put there now, at (%.1f, %.1f, %.2f) facing %.0f",
      D.time, math.sqrt(D.at[1] ^ 2 + D.at[2] ^ 2), Q.x, Q.y, Q.z, Q.yaw))
  elseif K == "fall" then
    Q.pose, Q.zFrom, Q.zOver = "down", nil, nil
    FPF.q.downs = (FPF.q.downs or 0) + 1
  elseif K == "rise" then
    Q.pose = "guard"
  elseif K == "up" then
    FPF.poseShift(Q, SCENES.q_up.at, nil)
    FPF.poseStood(Q)
    log(string.format("the quest's BT STANDS at (%.1f, %.1f, %.2f) facing %.0f, its gun in its hands%s", Q.x, Q.y, Q.z, Q.yaw, Q.board and " - V boards it now" or ""))
  end
end

function FPF.poseFrame(Q, dt)
  if not Q.move then FPF.poseNext(Q) end
  if not PS.kneel then return end
  local M = Q.move
  local clip, t = SCENES.getup.clip, 0.0
  if M then
    local D, was = M.scene, M.t
    M.t = M.t + dt
    local key = (M.kind == "fall") and "q_fall" or ((M.kind == "rise") and "q_rise" or ((M.kind == "up") and "q_up" or nil))
    if key and not M.sounded and M.t >= (D.sound or 0.0) then
      M.sounded = true
      FPF.poseSound(key)
    end
    for _, at in ipairs(D.steps) do
      if was < at and M.t >= at then
        FPF.stepSound(PS.ent)
        if P.fxOn then guard("effects of a step", FPF.fxStep) end
      end
    end
    if D.fall and was < D.fall and M.t >= D.fall and P.fxOn then
      local path = FPF.fxPath("step")
      local r = math.rad(Q.yaw)
      local fx, fy = -math.sin(r), math.cos(r)
      for _, pt in ipairs(D.dust or {}) do
        FPF.fxAt(path, Q.x + fy * pt[1] + fx * pt[2], Q.y - fx * pt[1] + fy * pt[2], Q.z + 0.05, Q.yaw, 0.0)
      end
    end
    clip, t = D.clip, (D.from or 0.0) + math.min(M.t, D.time)
    if M.t >= D.time then
      FPF.poseArrived(Q, M)
      if not PS.kneel then
        sendPose()
        return
      end
      if Q.move then clip, t = Q.move.scene.clip, (Q.move.scene.from or 0.0) end
    end
  elseif Q.pose == "down" then
    clip, t = SCENES.q_rise.clip, (SCENES.q_rise.from or 0.0)
  elseif Q.pose == "guard" then
    clip, t = SCENES.q_rise.clip, (SCENES.q_rise.from or 0.0) + SCENES.q_rise.time
  end
  PS.sceneW, PS.pilotW, PS.sceneClip, PS.sceneTime, PS.pods = 1.0, 0.0, clip, t, 0.0
  PS.vx, PS.vy, PS.speed = 0, 0, 0
  local z = Q.z
  if Q.zFrom and Q.move and Q.move.kind == "fall" then
    local k = clamp(Q.move.t / Q.zOver, 0.0, 1.0)
    z = Q.zFrom + (Q.z - Q.zFrom) * (k * k * (3.0 - 2.0 * k))
  end
  z = z + Q.lift
  if Q.move or PS.x ~= Q.x or PS.y ~= Q.y or PS.z ~= z or PS.yaw ~= Q.yaw or not Q.placed then
    PS.x, PS.y, PS.z, PS.yaw = Q.x, Q.y, z, Q.yaw
    Q.placed = true
    FPF.placeBt()
  end
  sendPose()
  if Q.move then guard("skeleton watch", FPF.still, clip, t, dt) end
end

FPF.kneelFrame59 = FPF.kneelFrame
function FPF.kneelFrame(dt)
  local Q = PS.kneel
  if (Q.pose or "kneel") == "kneel" and not Q.move and not Q.want then return FPF.kneelFrame59(dt) end
  return FPF.poseFrame(Q, dt)
end

FPF.kneelStand59 = FPF.kneelStand
function FPF.kneelStand(board, demo)
  local Q = PS.kneel
  if not Q or PS.act or PS.warm then return false end
  if (Q.pose or "kneel") == "kneel" and not Q.move then
    Q.want, Q.board = nil, nil
    return FPF.kneelStand59(board, demo)
  end
  Q.want, Q.board = "stand", board and { demo = demo } or nil
  PS.near, PS.useDown = nil, false
  log(string.format("the quest's BT is told to get up (%s%s)%s", Q.pose or "kneel", Q.move and ", on its way" or "", board and " - V boards it once it stands" or ""))
  return true
end

function FPF.questPose(name)
  local Q = PS.kneel
  if not Q or not PS.questBt or not PS.ent then return false, "no BT of the quest's kneels there" end
  if PS.warm or PS.act then return false, "it is not down yet" end
  if name ~= "down" and name ~= "guard" and name ~= "kneel" then return false, "no such pose" end
  if not (SCENES.q_fall and SCENES.q_rise and SCENES.q_up) then return false, "the clips for it are not there" end
  local now, heading = Q.pose or "kneel", Q.want
  if heading == "stand" then return false, "it is getting up" end
  local low = now ~= "kneel" or Q.move ~= nil or heading ~= nil
  if name == "kneel" then
    if not low or now == "guard" or heading == "guard" then return true end
    name = "guard"
  elseif name == "down" then
    if now == "guard" or heading == "guard" or (Q.move and Q.move.kind == "rise") then return false, "it is up in its crouch - there is no way back down" end
    if now == "down" then return true end
  elseif name == "guard" and now == "guard" then
    return true
  end
  if Q.want ~= name then
    Q.want = name
    if (FPF.q.poseLines or 0) < FPC.pose.lines then
      log(string.format("the quest's BT is asked to take the pose \"%s\" (it is in \"%s\"%s)", name, now, Q.move and ", moving" or ""))
    end
  end
  return true
end

FPF.leaveStart59 = FPF.leaveStart
function FPF.leaveStart(piloted, home)
  if P.questDeath and not piloted and not home and PS.questBt and not S.driving and PS.hp and PS.hp.gone then
    FPF.q.destroyed = FPF.q.destroyed + 1
    log(string.format("the quest's BT is shot to pieces with nobody in it: it is DESTROYED (%d so far) - it topples and blows up, it does not leave", FPF.q.destroyed))
    return FPF.deathStart()
  end
  return FPF.leaveStart59(piloted, home)
end

FPF.health59 = FPF.health
function FPF.health(dt, alone)
  local H, k = PS.hp, FPF.q.harm
  if H and alone and PS.questBt and type(k) == "number" and k ~= 1.0 and k >= 0.0 then
    H.pend.a, H.pend.b = H.pend.a * k, H.pend.b * k
    if H.bigV then H.bigV = H.bigV * k end
  end
  return FPF.health59(dt, alone)
end

