FPF.q.api = 6
FPC.guard = { missiles = 25.0, vortex = 20.0, first = 0.25, hitFor = 1.0, idle = 1.5, retry = 3.0, lines = 40 }
FPF.q.guardGun = false
FPF.q.guardSkills = { missiles = FPC.guard.missiles, vortex = FPC.guard.vortex }

function FPF.guardPlain()
  return FPF.q.guardGun ~= true and FPF.questHeld() == "guard"
end

function FPF.guardWants()
  local C, W = FPC.guard, FPF.q.guardSkills
  local m, v, n = C.missiles, C.vortex, nil
  if type(W) == "table" then
    if W.missiles == false then m = nil elseif type(W.missiles) == "number" and W.missiles > 0 then m = W.missiles end
    if W.vortex == false then v = nil elseif type(W.vortex) == "number" and W.vortex > 0 then v = W.vortex end
    if type(W.targets) == "number" and W.targets >= 1 then n = math.floor(W.targets) end
  end
  return m, v, n
end

function FPF.guardTargets()
  if not FPF.guardPlain() then return nil end
  local _, _, n = FPF.guardWants()
  return n
end

function FPF.guardState()
  local G, n = FPF.q.gs, FPF.q.guards or 0
  if not G or G.n ~= n then
    G = { n = n, since = S.clock, salvos = 0, shields = 0, none = 0, lines = 0, still = 0.0 }
    FPF.q.gs = G
    local m, v, most = FPF.guardWants()
    log(string.format("the quest's guarding BT keeps its gun and its fist still (FPF.q.guardGun is not true): of its own it uses %s and %s",
      m and string.format("its missiles (one salvo, %.0f s apart at least%s)", m, most and string.format(", %d foes painted at most", most) or "") or "no missiles",
      v and string.format("the vortex shield (%.0f s apart at least)", v) or "no vortex shield"))
  end
  return G
end

function FPF.guardSay(G, text)
  G.lines = G.lines + 1
  if G.lines <= FPC.guard.lines then log("the quest's guarding BT: " .. text) end
end

function FPF.guardRules(B, A, dt, T)
  local K, C = FPC.ai, FPC.guard
  local M, V = PS.mtms, PS.vortex
  local G = FPF.guardState()
  local gapM, gapV = FPF.guardWants()
  local now = S.clock
  local D = PS.decoy
  local pts = D and D.points or 0.0
  if G.points and pts > G.points then G.hitAt = now end
  G.points = pts
  if G.asked and not (M and M.held) then
    G.asked = nil
    if not (M and (M.fired > G.fired0 or #M.queue > 0)) then
      G.none, G.salvos, A.salvos = G.none + 1, G.salvos - 1, A.salvos - 1
      G.missileAt = now - (gapM or 0.0) + C.retry
      FPF.guardSay(G, string.format("nothing was painted for its missiles: none leaves - it looks again in %.0f s", C.retry))
    end
  end
  if not P.aiSkills or not T or B.off or PS.punch ~= nil or (V and V.on) or (M and M.held) then return end
  if gapM and M and #M.queue == 0 and FPF.mtmsCanGuard(M) and now >= (G.lookAt or 0.0)
      and now - (G.missileAt or (G.since - gapM * (1.0 - C.first))) >= gapM and T.dist >= K.salvoFrom and T.dist <= K.salvoTo
      and math.sqrt((B.vx - T.x) ^ 2 + (B.vy - T.y) ^ 2) >= K.salvoClear then
    G.lookAt = now + 0.2
    local seen = FPF.mtmsSeen()
    if #seen >= 1 then
      PS.keyN.missiles, PS.keyTill.missiles = PS.keyN.missiles + 1, now + K.salvoHold
      G.missileAt, G.asked, G.fired0, G.salvos, A.salvos = now, true, M.fired, G.salvos + 1, A.salvos + 1
      FPF.guardSay(G, string.format("it paints for its missiles (salvo %d of this guard, %.0f s after it met its first foe) - %d foes in view, the nearest of them %.0f m away",
        G.salvos, now - G.since, #seen, T.dist))
      return
    end
  end
  if gapV and V and V.frac <= 0.15 then
    local since = now - (G.vortexAt or (G.since - gapV * (1.0 - C.first)))
    local shot = now - (G.hitAt or -100.0) <= C.hitFor
    if since >= gapV and (shot or since >= gapV * C.idle) then
      PS.keyN.vortex, PS.keyTill.vortex = PS.keyN.vortex + 1, now + K.shieldHold
      G.vortexAt, G.shields, A.shieldAt, A.shields = now, G.shields + 1, now, A.shields + 1
      A.heat = 0.0
      FPF.guardSay(G, string.format("it raises the vortex shield (%d of this guard, %.0f s after it met its first foe) - %s", G.shields, now - G.since,
        shot and "it is being shot at" or "nobody has shot at it for a while: it raises it all the same"))
    end
  end
end

FPF.buddyEnd62 = FPF.buddyEnd
function FPF.buddyEnd(why)
  local G = FPF.q.gs
  if G and PS.buddy and PS.questBt and G.n == (FPF.q.guards or 0) then
    local sum = string.format("%d salvos of missiles (%d more times nothing was painted), the vortex shield raised %d times, its gun kept still for %.0f s in which it would have fired",
      G.salvos, G.none, G.shields, G.still or 0.0)
    if G.summed ~= sum and G.salvos + G.none + G.shields + (G.still or 0.0) > 0 then
      G.summed = sum
      log(string.format("the quest's guard without its gun, until %s: %s", tostring(why), sum))
    end
  end
  return FPF.buddyEnd62(why)
end

P.airDash, P.falls, P.slam, P.aiJump = true, true, true, true
FPC.jump.dashFor, FPC.jump.dashIn, FPC.jump.dashOut, FPC.jump.dashPose, FPC.jump.dashClip = 0.45, 0.10, 0.22, 1.0, 0.25
FPC.edge = { drop = 2.5, lines = 8 }
FPC.slam = { from = 4.0, least = 2.0, down = 4.0, reach = 6.0, power = 380.0, record = "Attacks.BT7274_MissileBlast",
  fallback = "Attacks.ExplosionSmall", wreck = 20.0, ring = 3.2, puffs = 10, fear = 20.0, lines = 10 }
FPC.aiJump = { every = 3.0, again = 20.0, from = 5.0, past = 4.0, ahead = { 1.0, 2.5, 4.0 }, clear = 1.0, deep = 6.0,
  step = 2.5, stuck = 2.5, far = 8.0, lines = 10 }

function FPF.fallStart(g)
  if not P.falls then return false end
  local C = FPC.jumpClip
  local t0 = C.start / C.fps
  local J = PS.jump
  if J and J.stage == "crouch" then
    J.stage, J.air, J.vz, J.z0, J.floor, J.liftAt, J.edge = "air", 0.0, 0.0, PS.z, g, J.t, true
    return true
  end
  PS.falls = (PS.falls or 0) + 1
  if J then
    J.stage, J.pushed, J.vz, J.air, J.z0, J.floor, J.top = "air", true, 0.0, 0.0, PS.z, g, 0.0
    J.t = math.max(J.t, t0)
    J.out, J.outWhy, J.free, J.landed, J.riseTo, J.fall, J.light = nil, nil, nil, nil, nil, true, nil
    J.done.touch = nil
  else
    PS.jump = { stage = "air", fall = true, pushed = true, t = t0, air = 0.0, vz = 0.0, z0 = PS.z, floor = g, top = 0.0,
      x0 = PS.x, y0 = PS.y, speed0 = PS.speed, done = { jets = true, jetsOff = true }, n = 0, fallN = PS.falls }
    PS.jumpT, PS.jumpW, PS.landW, PS.landT = t0, PS.jumpW or 0.0, 0.0, 0.0
  end
  if PS.falls <= FPC.edge.lines then
    log(string.format("FALL %d: the ground ahead is %.1f m under its feet (more than %.1f m): it falls from here, at %.1f m/s over the ground",
      PS.falls, PS.z - g, FPC.edge.drop, PS.speed))
  end
  return true
end

FPF.jumpEnd65 = FPF.jumpEnd
function FPF.jumpEnd(why, hard)
  local J = PS.jump
  PS.airDashW = 0.0
  if not (J and J.fall and J.n == 0) then return FPF.jumpEnd65(why, hard) end
  PS.jump = nil
  if J.stage == "air" then PS.z = J.floor end
  if J.riseTo then PS.z = J.riseTo end
  PS.jumpW, PS.landW, PS.jumpEye = 0.0, 0.0, 0.0
  if (J.fallN or 0) <= FPC.edge.lines or hard then
    log(string.format("FALL %d over (%s): %.2f s in the air, %.1f m down, carried %.1f m; it came down at %.1f m/s%s%s%s%s",
      J.fallN or 0, tostring(why), J.airTime or J.air, J.z0 - PS.z, math.sqrt((PS.x - J.x0) ^ 2 + (PS.y - J.y0) ^ 2), J.vzDown or 0.0,
      J.light and "; a short one: no knee bend to wait for" or "",
      (J.dashes or 0) > 0 and string.format("; dashes in the air: %d", J.dashes) or "",
      (J.down or 0) > 0 and string.format("; people thrown down: %d", J.down) or "",
      J.slam and string.format("; the landing's shock: %d thrown off their feet, %d foes hit, %d vehicles", J.slam.down, J.slam.hit, J.slam.shaken) or ""))
  end
end

function FPF.slamRecord()
  if PS.slamRec == nil then
    local K = FPC.slam
    local known = false
    pcall(function() known = TweakDB:GetRecord(K.record) ~= nil end)
    PS.slamRec = known and K.record or K.fallback
    once("slamrecord" .. PS.slamRec, known and ("the landing's shock: hits use the record " .. K.record) or
      ("the landing's shock: record " .. K.record .. " does not exist (TweakXL did not load r6/tweaks/bt7274/bt7274_weapon.yaml) - using " .. K.fallback))
  end
  return PS.slamRec
end

function FPF.slam(J)
  local K, JK = FPC.slam, FPC.jump
  local fell = (J.z0 + J.top) - PS.z
  local fall = J.fall == true
  if fell < (fall and K.from or K.least) then return false end
  local calm = PS.buddy ~= nil and not S.driving and not FPF.fightOn()
  local x, y, z = PS.x, PS.y, PS.z
  local shown = 0
  if P.fxOn then
    local path = FPF.fxPath("land")
    if path and FPF.fxAt(path, x, y, z + 0.05, PS.yaw, 0.0) then shown = shown + 1 end
    local dust = FPF.fxPath("step")
    if dust then
      for i = 1, K.puffs do
        local a = (i - 1) / K.puffs * 2.0 * math.pi
        if FPF.fxAt(dust, x + math.cos(a) * K.ring, y + math.sin(a) * K.ring, z + 0.05, math.deg(a), 0.0) then shown = shown + 1 end
      end
    end
  end
  local down, hit, shaken = 0, 0, 0
  local rec = FPF.slamRecord()
  PS.npcsAt = -10
  refreshNpcs()
  for i, ent in ipairs(PS.npcs) do
    if IsDefined(ent) then
      pcall(function()
        local p = ent:GetWorldPosition()
        local rx, ry = p.x - x, p.y - y
        local dist = math.sqrt(rx * rx + ry * ry)
        if dist >= K.reach or math.abs(p.z - z) >= 3.5 then return end
        local n = math.max(dist, 0.1)
        local ux, uy = rx / n, ry / n
        local big = PS.npcShape[i] and true or false
        local foe = false
        pcall(function() foe = OP77.targetHostile(ent) == true end)
        if dist >= JK.stomp and dist < K.down and not big and P.solid and (foe or not calm) then
          pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(FPC.solid.knock)) end)
          FPF.ragdoll(ent, p.x - ux * 0.5, p.y - uy * 0.5, p.z + 0.6, ux, uy, K.power * (1.0 - 0.5 * dist / K.down))
          PS.bumped[tostring(ent:GetEntityID())] = S.clock
          down = down + 1
        end
        if foe and P.damage and (dist >= JK.stomp or big) then
          local send = P.fullHits and FPF.hitFull or FPF.hit
          if send(ent, rec, p.x, p.y, p.z + 0.9, ux, uy, 0.0) == true then hit = hit + 1 end
        end
      end)
    end
  end
  if P.solid and not calm then
    PS.vehiclesAt = -10
    for _, veh in ipairs(FPF.vehicles()) do
      pcall(function()
        local p = veh:GetWorldPosition()
        local rx, ry = p.x - x, p.y - y
        local dist = math.sqrt(rx * rx + ry * ry)
        if dist >= JK.crush and dist < K.reach and math.abs(p.z - z) < 3.0 then
          FPF.dent(veh, 0.5, false)
          FPF.wreck(veh, K.wreck)
          shaken = shaken + 1
        end
      end)
    end
  end
  guard("people told", FPF.stim, "Explosion", K.fear, 1.0)
  J.slam = { fell = fell, down = down, hit = hit, shaken = shaken }
  PS.slams = (PS.slams or 0) + 1
  local met = down + hit + shaken > 0
  if met then PS.slamsMet = (PS.slamsMet or 0) + 1 end
  if PS.slams <= 3 or (met and PS.slamsMet <= K.lines) then
    log(string.format("LANDING SHOCK %d (%s, it came down %.1f m%s): people within %.1f m thrown off their feet: %d (within %.1f m the landing itself does it); foes within %.1f m hit (%s): %d; vehicles within %.1f m dented and worn by %.0f %%: %d; its effects started: %d",
      PS.slams, fall and "a fall" or "a jump", fell, calm and "; on its own and in no fight: foes only" or "", K.down, down, JK.stomp, K.reach, rec, hit, K.reach, K.wreck, shaken, shown))
  end
  return true
end

FPF.jumpTouch65 = FPF.jumpTouch
function FPF.jumpTouch(J)
  FPF.jumpTouch65(J)
  if not P.slam then return end
  local ok, err = pcall(FPF.slam, J)
  if not ok then once("slam" .. tostring(err), "ERROR the landing's shock: " .. tostring(err)) end
end

function FPF.aiFace(x, y, z, dx, dy, reach)
  local best = nil
  for _, h in ipairs({ 2.2, 4.4 }) do
    pcall(function()
      local from = Vector4.new(x, y, z + h, 1.0)
      local to = Vector4.new(x + dx * reach, y + dy * reach, z + h, 1.0)
      local hit, res = FPF.sqs():SyncRaycastByCollisionGroup(from, to, "Static", nil, false, false)
      if hit then
        local d = reach
        if res and res.position then d = math.sqrt((res.position.x - x) ^ 2 + (res.position.y - y) ^ 2) end
        if best == nil or d < best then best = d end
      end
    end)
  end
  return best
end

function FPF.aiLeapFits(hx, hy, face)
  local K, top = FPC.aiJump, FPC.jump.top
  if FPF.jumpCeiling(PS.x, PS.y, PS.z, top) then return false, "something is over its head" end
  local zTop = PS.z + top - K.clear
  local at = face or BODY_RADIUS
  if wallAhead(PS.x, PS.y, zTop - 1.9, hx, hy, at + K.past) then
    return false, string.format("it is higher than the %.1f m it clears", top - K.clear)
  end
  local last = nil
  for _, d in ipairs(K.ahead) do
    local g = groundZ(PS.x + hx * (at + d), PS.y + hy * (at + d), zTop - 3.0)
    if g == nil then return false, string.format("no ground %.1f m behind it", d) end
    if g < PS.z - K.deep then return false, string.format("the ground behind it is %.1f m down", PS.z - g) end
    last = g
  end
  return true, string.format("the ground behind it is %+.1f m against where it stands", last - PS.z)
end

function FPF.aiLeapPlan(B, hx, hy, reach, why)
  local K = FPC.aiJump
  if not P.aiJump or not P.jump or B.off or PS.jump or S.clock < (B.leapAt or 0.0) or S.clock < (B.leapNoAt or 0.0) then return nil end
  local face = FPF.aiFace(PS.x, PS.y, PS.z, hx, hy, reach)
  if face == nil then
    local g = groundZ(PS.x + hx * K.step, PS.y + hy * K.step, PS.z + 1.0)
    if g == nil or g - PS.z <= TF.step then return nil end
    why = string.format("a step of %.1f m is in its way", g - PS.z)
  end
  local fits, what = FPF.aiLeapFits(hx, hy, face)
  if not fits then B.leapNoAt = S.clock + 1.0 end
  if S.clock - (B.leapSaidAt or -10.0) > 1.5 and (B.leapLooks or 0) < K.lines * 2 then
    B.leapSaidAt, B.leapLooks = S.clock, (B.leapLooks or 0) + 1
    log(string.format("BT on its own: %s%s - %s", why, face and string.format(" (%.1f m ahead)", face) or "",
      fits and ("it jumps it: " .. tostring(what)) or ("no jump: " .. tostring(what))))
  end
  if not fits then return nil end
  return { x = hx, y = hy, face = face, why = why, till = S.clock + 0.6 }
end

function FPF.aiLeapAsk(B, hx, hy, reach, why)
  local ok, plan = pcall(FPF.aiLeapPlan, B, hx, hy, reach, why)
  if ok then return plan end
  P.aiJump = false
  once("aileapplan" .. tostring(plan), "BT on its own: whether to jump could NOT be looked at (" .. tostring(plan) .. ") - it goes on without")
  return nil
end

function FPF.aiLeap(B, dt, going)
  local K = FPC.aiJump
  local J = PS.jump
  local L = B.leap
  if L then
    if J and J.stage ~= "land" and not J.out then return L.x, L.y end
    B.leap = nil
    local along = (PS.x - L.x0) * L.x + (PS.y - L.y0) * L.y
    local past = along > (L.face or BODY_RADIUS) or PS.z - L.z0 > TF.step * 0.5
    B.leapAt = S.clock + (past and K.every or K.again)
    if (B.leaps or 0) <= K.lines then
      log(string.format("BT on its own: its jump (%s) took it %.1f m on and %+.1f m in height - %s", L.why, along, PS.z - L.z0,
        past and "it is past what was in its way" or string.format("it is NOT past what was in its way: no other jump for %.0f s", K.again)))
    end
    return nil
  end
  if not P.aiJump or not P.jump or B.off or J or not going then
    B.leapOn = nil
    return nil
  end
  local O = B.leapOn
  local stopped = B.blockedAt ~= nil and S.clock - B.blockedAt < 0.3
  if not O then
    if stopped and B.headX and S.clock - (B.headAt or -10.0) < 0.5 then
      O = FPF.aiLeapPlan(B, B.headX, B.headY, FPC.buddy.ahead, "it was stopped by what is ahead")
    elseif B.stuckT >= K.stuck then
      local vx, vy = B.vx - PS.x, B.vy - PS.y
      local n = math.sqrt(vx * vx + vy * vy)
      if n > K.far then O = FPF.aiLeapPlan(B, vx / n, vy / n, math.min(FPC.buddy.ahead, n), string.format("no getting on for %.1f s, and this is between it and V", B.stuckT)) end
    end
    B.leapOn = O
  end
  if not O then return nil end
  if S.clock > O.till then
    B.leapOn = nil
    return nil
  end
  local face = nil
  if O.face then
    face = FPF.aiFace(PS.x, PS.y, PS.z, O.x, O.y, FPC.buddy.ahead + 1.0)
    if face == nil then
      B.leapOn = nil
      return nil
    end
  end
  if face == nil or face <= K.from or stopped then
    if FPF.jumpCan() then
      FPF.jumpStart()
      B.leap = { x = O.x, y = O.y, x0 = PS.x, y0 = PS.y, z0 = PS.z, why = O.why, face = face }
      B.leaps, B.leapOn, B.detour = (B.leaps or 0) + 1, nil, nil
    end
  end
  return O.x, O.y
end

function FPF.jumpDrop(why)
