FPC.burn2.layers[6].row = { { -0.38, 0.15, -0.09 }, { 0.38, 0.15, -0.09 } }

function FPF.backPoint(across, up, out)
  local t, l, r = slotWorld("thrust"), slotWorld("vent_l"), slotWorld("vent_r")
  if not t or not l or not r then return nil end
  local ux, uy, uz = r.x - l.x, r.y - l.y, r.z - l.z
  local n = math.sqrt(ux * ux + uy * uy + uz * uz)
  if n < 0.05 then return nil end
  ux, uy, uz = ux / n, uy / n, uz / n
  local wx, wy, wz = t.x - (l.x + r.x) * 0.5, t.y - (l.y + r.y) * 0.5, t.z - (l.z + r.z) * 0.5
  local d = wx * ux + wy * uy + wz * uz
  wx, wy, wz = wx - d * ux, wy - d * uy, wz - d * uz
  local m = math.sqrt(wx * wx + wy * wy + wz * wz)
  if m < 0.05 then return nil end
  wx, wy, wz = wx / m, wy / m, wz / m
  local nx, ny, nz = uy * wz - uz * wy, uz * wx - ux * wz, ux * wy - uy * wx
  return { x = t.x + ux * across + wx * up + nx * out, y = t.y + uy * across + wy * up + ny * out, z = t.z + uz * across + wz * up + nz * out }
end

FPF.rowPoint66 = FPF.rowPoint
function FPF.rowPoint(slot, where)
  if type(where) ~= "table" then return FPF.rowPoint66(slot, where) end
  local p = FPF.backPoint(where[1], where[2], where[3])
  if p then
    once("backpoint", string.format("effects: the two small flames beside BT's main thruster are born on its hull - %.2f m to either side of the thruster, %.2f m up the back, %.2f m in from the thruster's plane (up to t66: 0.8 m to either side, in the air)",
      math.abs(where[1]), where[2], -where[3]))
    return p
  end
  once("backpointnone", "effects: a place on BT's back could NOT be worked out (the slots thrust / vent_l / vent_r) - the flame is born at its slot")
  return slotWorld(slot)
end

P.cockSparks = true
FPC.cockSparks = { fx = { [[titan\bt7274\fx\bt_cock_sparks_low.effect]], [[titan\bt7274\fx\bt_cock_sparks_high.effect]] },
  at = { { right = -0.797, up = 0.421, frame = 0.44 }, { right = 0.767, up = 0.266, frame = 0.46 } }, deep = 1.3,
  stage = { { gap = { 5.0, 9.0 }, most = 1, busy = 1.2 }, { gap = { 2.5, 5.0 }, most = 2, busy = 1.6 } },
  first = 0.5, life = 2.0, lines = 8 }

function FPF.cockSparksOff(why)
  local Q = PF.sparks
  if not Q then return end
  for _, L in ipairs(Q.live) do
    FPF.fxBreak152(L.inst)
    FPF.fxKill152(L.inst)
  end
  Q.live = {}
  if Q.stage ~= 0 or Q.bursts[1] + Q.bursts[2] > Q.said then
    Q.lines = Q.lines + 1
    if Q.lines <= FPC.cockSparks.lines then
      log(string.format("FIRST PERSON sparks at the view's edges: off (%s) - so far %d weaker bursts (two segments left) and %d stronger ones (one segment left)",
        tostring(why), Q.bursts[1], Q.bursts[2]))
    end
    Q.said = Q.bursts[1] + Q.bursts[2]
  end
  Q.stage = 0
end

function FPF.cockSparks(x, y, z, yaw, pitch, roll)
  local K = FPC.cockSparks
  local Q = PF.sparks
  if not Q then
    Q = { stage = 0, next = {}, live = {}, bursts = { 0, 0 }, lines = 0, said = 0 }
    PF.sparks = Q
  end
  Q.rodeAt = S.clock
  local H = PS.hp
  local stage = 0
  if P.cockSparks and P.burn and P.fxOn and H and S.driving and PS.mode == "pilot" and not PS.eject then
    local full = FPC.health.segment * FPC.health.segments
    local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
    local worse = H.doomed or (P.throwOut and H.health <= full * FPC.burn2.worse)
    stage = (low and worse) and 2 or (low and 1 or 0)
  end
  if stage ~= Q.stage then
    Q.stage = stage
    if stage > 0 then
      local a = (math.random() < 0.5) and 1 or 2
      Q.next[a] = S.clock + K.first
      Q.next[3 - a] = S.clock + K.first + 1.0 + math.random() * 1.5
    end
    Q.lines = Q.lines + 1
    if Q.lines <= K.lines then
      local T = K.stage[stage]
      log(string.format("FIRST PERSON sparks at the view's edges: BT's hull is at %.0f %% of its health - %s", H and (H.health / (FPC.health.segment * FPC.health.segments) * 100.0) or 0.0,
        (stage == 0) and "none" or string.format("%s: a burst of the %s sparks at a place every %.1f - %.1f s, %s (born %.1f m ahead behind the cockpit's frame, upper left and right)",
          (stage == 2) and "one segment left" or "two segments left", (stage == 2) and "stronger" or "weaker", T.gap[1], T.gap[2],
          (T.most == 1) and "one place at a time" or "both places may go at once", K.deep)))
    end
  end
  local R, F, U = FPF.axes(yaw, pitch, roll)
  local j = -PF.joltX
  local function place(A)
    local r, f, u = A.right * K.deep, K.deep, (A.up + j / A.frame) * K.deep
    return x + R[1] * r + F[1] * f + U[1] * u, y + R[2] * r + F[2] * f + U[2] * u, z + R[3] * r + F[3] * f + U[3] * u
  end
  if stage > 0 then
    local T = K.stage[stage]
    local busy = 0
    for _, L in ipairs(Q.live) do
      if S.clock - L.at < T.busy then busy = busy + 1 end
    end
    for i, A in ipairs(K.at) do
      if busy < T.most and S.clock >= (Q.next[i] or 0.0) then
        local px, py, pz = place(A)
        local inst = FPF.fxAt(K.fx[stage], px, py, pz, yaw, pitch)
        Q.next[i] = S.clock + T.gap[1] + math.random() * (T.gap[2] - T.gap[1])
        if inst then
          Q.live[#Q.live + 1] = { inst = inst, i = i, at = S.clock, till = S.clock + K.life, stage = stage }
          Q.bursts[stage] = Q.bursts[stage] + 1
          busy = busy + 1
          once("cocksparks" .. stage, string.format("FIRST PERSON sparks at the view's edges: the first %s burst (%s), %s of the view", (stage == 2) and "stronger" or "weaker",
            K.fx[stage], (i == 1) and "upper left" or "right"))
        end
      end
    end
  end
  for n = #Q.live, 1, -1 do
    local L = Q.live[n]
    if S.clock >= L.till then
      FPF.fxBreak152(L.inst)
      FPF.fxKill152(L.inst)
      table.remove(Q.live, n)
    else
      local px, py, pz = place(K.at[L.i])
      pcall(function()
        local tr = WorldTransform.new()
        WorldTransform.SetPosition(tr, Vector4.new(px, py, pz, 1.0))
        if not PS.fxNoTurn then WorldTransform.SetOrientation(tr, EulerAngles.ToQuat(EulerAngles.new(roll, pitch, yaw))) end
        if FPF.fxLive152(L.inst) then L.inst:UpdateTransform(tr) end
      end)
    end
  end
end

