P.fireLead = true

FPF.rowPoint67 = FPF.rowPoint
function FPF.rowPoint(slot, where)
  local p = FPF.rowPoint67(slot, where)
  if type(where) ~= "table" or not p or not P.fireLead then return p end
  local W = PS.leadWas
  if not W or S.clock - W.at > 0.25 then return p end
  local dx, dy, dz = PS.x - W.x, PS.y - W.y, PS.z - W.z
  if dx * dx + dy * dy + dz * dz > 1.0 then return p end
  if dx == 0.0 and dy == 0.0 and dz == 0.0 and PS.yaw == W.yaw then return p end
  local a = math.rad(wrap180(PS.yaw - W.yaw))
  local c, sn = math.cos(a), math.sin(a)
  local rx, ry = p.x - W.x, p.y - W.y
  if not PS.leadSaid then
    PS.leadSaid = true
    log(string.format("effects: the two small flames at BT's back are taken along by a frame's way of BT's (%.2f m in this frame): the slots are read where its skeleton was a frame ago",
      math.sqrt(dx * dx + dy * dy + dz * dz)))
  end
  return { x = PS.x + rx * c - ry * sn, y = PS.y + rx * sn + ry * c, z = p.z + dz }
end

FPF.fxFrame67 = FPF.fxFrame
function FPF.fxFrame()
  FPF.fxFrame67()
  local W = PS.leadWas
  if W then
    W.x, W.y, W.z, W.yaw, W.at = PS.x, PS.y, PS.z, PS.yaw, S.clock
  else
    PS.leadWas = { x = PS.x, y = PS.y, z = PS.z, yaw = PS.yaw, at = S.clock }
  end
end

FPC.cockSparks.at = { { right = -0.797, up = 0.375, frame = 0.45 }, { right = 0.767, up = 0.231, frame = 0.46 } }
FPC.cockSparks.stage[1].burst, FPC.cockSparks.stage[2].burst = 0.6, 1.1
FPC.cockSparks.particle = [[titan\bt7274\fx\bt_cock_sparks.particle]]

function FPF.cockSparksAsk()
  local K, Q = FPC.cockSparks, PF.sparks
  if Q.asked then
    if Q.askAt and S.clock >= Q.askAt then
      Q.askAt = nil
      Q.askN = (Q.askN or 0) + 1
      local out, waiting = {}, false
      for i, T in ipairs(Q.asked) do
        local text = "not asked"
        if T.tok then
          local ok, err = pcall(function()
            local loaded, failed = T.tok:IsLoaded(), T.tok:IsFailed()
            text = failed and "FAILED to load" or (loaded and "loaded" or "not loaded yet")
            if not loaded and not failed then waiting = true end
            if loaded and not failed then
              local res = T.tok:GetResource()
              if T.kind == "effect" then
                text = text .. string.format(" (length %.1f s, %d track items)", res.length, #res.events)
              else
                local n, loc = #res.emitters, 0
                for k = 1, n do
                  if res.emitters[k].keepSimulationLocal then loc = loc + 1 end
                end
                text = text .. string.format(" (%d emitters, %d of them keep their simulation local)", n, loc)
              end
            end
          end)
          if not ok then text = text .. " - could not be read (" .. tostring(err) .. ")" end
        else
          text = "could NOT be asked (" .. tostring(T.err) .. ")"
        end
        out[#out + 1] = T.path .. ": " .. text
      end
      log("FIRST PERSON sparks at the view's edges, what the game's depot has of them: " .. table.concat(out, "; "))
      if waiting and Q.askN < 3 then Q.askAt = S.clock + 4.0 end
    end
    return
  end
  Q.asked = {}
  for i, path in ipairs({ K.fx[1], K.fx[2], K.particle }) do
    local T = { path = path, kind = (i <= 2) and "effect" or "particles" }
    local ok, err = pcall(function() T.tok = Game.GetResourceDepot():LoadResource(path) end)
    if not ok then T.err = err end
    Q.asked[i] = T
  end
  Q.askAt = S.clock + 1.0
end

function FPF.cockSparks(x, y, z, yaw, pitch, roll)
  local K = FPC.cockSparks
  local Q = PF.sparks
  if not Q then
    Q = { stage = 0, next = {}, live = {}, bursts = { 0, 0 }, lines = 0, said = 0 }
    PF.sparks = Q
  end
  Q.rodeAt = S.clock
  local H = PS.hp
  local stage = 0
  if P.cockSparks and P.burn and P.fxOn and H and S.driving and PS.mode == "pilot" and not PS.eject then
    local full = FPC.health.segment * FPC.health.segments
    local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
    local worse = H.doomed or (P.throwOut and H.health <= full * FPC.burn2.worse)
    stage = (low and worse) and 2 or (low and 1 or 0)
  end
  if stage > 0 or Q.asked then pcall(FPF.cockSparksAsk) end
  if stage ~= Q.stage then
    Q.stage = stage
    if stage > 0 then
      local a = (math.random() < 0.5) and 1 or 2
      Q.next[a] = S.clock + K.first
      Q.next[3 - a] = S.clock + K.first + 1.0 + math.random() * 1.5
    end
    Q.lines = Q.lines + 1
    if Q.lines <= K.lines then
      local T = K.stage[stage]
      log(string.format("FIRST PERSON sparks at the view's edges: BT's hull is at %.0f %% of its health - %s", H and (H.health / (FPC.health.segment * FPC.health.segments) * 100.0) or 0.0,
        (stage == 0) and "none" or string.format("%s: a burst of the %s sparks for %.1f s at a place every %.1f - %.1f s, %s (born %.1f m ahead at the edge of the cockpit's frame, upper left and right)",
          (stage == 2) and "one segment left" or "two segments left", (stage == 2) and "stronger" or "weaker", T.burst, T.gap[1], T.gap[2],
          (T.most == 1) and "one place at a time" or "both places may go at once", K.deep)))
    end
  end
  local R, F, U = FPF.axes(yaw, pitch, roll)
  local j = -PF.joltX
  local function place(A)
    local r, f, u = A.right * K.deep, K.deep, (A.up + j / A.frame) * K.deep
    return x + R[1] * r + F[1] * f + U[1] * u, y + R[2] * r + F[2] * f + U[2] * u, z + R[3] * r + F[3] * f + U[3] * u
  end
  if stage > 0 then
    local T = K.stage[stage]
    local busy = 0
    for _, L in ipairs(Q.live) do
      if S.clock - L.at < T.busy then busy = busy + 1 end
    end
    for i, A in ipairs(K.at) do
      if busy < T.most and S.clock >= (Q.next[i] or 0.0) then
        local px, py, pz = place(A)
        local inst = FPF.fxAt(K.fx[stage], px, py, pz, yaw, pitch)
        Q.next[i] = S.clock + T.gap[1] + math.random() * (T.gap[2] - T.gap[1])
        if inst then
          Q.live[#Q.live + 1] = { inst = inst, i = i, at = S.clock, till = S.clock + T.burst, stage = stage }
          Q.bursts[stage] = Q.bursts[stage] + 1
          busy = busy + 1
          once("cocksparks68" .. stage, string.format("FIRST PERSON sparks at the view's edges: the first %s burst (%s), %s of the view - %.2f m to the right, %.2f m ahead, %.2f m above the camera",
            (stage == 2) and "stronger" or "weaker", K.fx[stage], (i == 1) and "upper left" or "right", A.right * K.deep, K.deep, (A.up + j / A.frame) * K.deep))
        end
      end
    end
  end
  for n = #Q.live, 1, -1 do
    local L = Q.live[n]
    if S.clock >= L.till then
      FPF.fxBreak152(L.inst)
      FPF.fxKill152(L.inst)
      table.remove(Q.live, n)
    else
      local px, py, pz = place(K.at[L.i])
      pcall(function()
        local tr = WorldTransform.new()
        WorldTransform.SetPosition(tr, Vector4.new(px, py, pz, 1.0))
        if not PS.fxNoTurn then WorldTransform.SetOrientation(tr, EulerAngles.ToQuat(EulerAngles.new(roll, pitch, yaw))) end
        if FPF.fxLive152(L.inst) then L.inst:UpdateTransform(tr) end
      end)
    end
  end
end

