P.fireBig, P.firePivot = true, true
FPC.burn2.big = [[titan\bt7274\fx\bt_fire_small_big.effect]]
FPC.burn2.flameUp = 0.15
FPC.burn2.layers[6].row = { { -0.38, 0.15, -0.13 }, { 0.38, 0.15, -0.13 } }

function FPF.fireBig()
  local K = FPC.burn2
  if not P.fireBig or not K.big then return nil end
  local T = PS.fireBigAsk
  if T == nil then
    T = { at = S.clock }
    local ok, err = pcall(function() T.tok = Game.GetResourceDepot():LoadResource(K.big) end)
    if not ok then T.err = tostring(err) end
    PS.fireBigAsk = T
  end
  if not T.tok then
    once("firebignodepot", "effects: the bigger small fire cannot be asked of the game's depot (" .. tostring(T.err) .. ") - it is used as it is in this mod's archive")
    return K.big
  end
  local state = "?"
  pcall(function() state = T.tok:IsFailed() and "it could NOT be loaded" or (T.tok:IsLoaded() and "loaded" or "not loaded yet") end)
  if state ~= T.state then
    T.state = state
    log(string.format("effects: the bigger small fire for one segment (%s) - the game's depot says: %s", K.big, state))
  end
  if state == "loaded" then return K.big end
  if state == "?" and S.clock - T.at > 2.0 then return K.big end
  return nil
end

FPF.rowPoint68 = FPF.rowPoint
function FPF.rowPoint(slot, where)
  local p = FPF.rowPoint68(slot, where)
  if type(where) ~= "table" or not p then return p end
  where.sx, where.sy = 0.0, 0.0
  local pitch = where.pitch or 0.0
  if not P.firePivot or pitch <= 0.5 then return p end
  local up = FPC.burn2.flameUp
  local t, y = math.rad(pitch), math.rad(where.yaw or 0.0)
  local sn, cs = math.sin(t), math.cos(t)
  where.sx, where.sy = up * sn * -math.sin(y), up * sn * math.cos(y)
  return { x = p.x + where.sx, y = p.y + where.sy, z = p.z + up * (1.0 - cs) }
end

FPF.burnLean68 = FPF.burnLean
function FPF.burnLean(L, p)
  local W = L.row
  if type(W) ~= "table" then return FPF.burnLean68(L, p) end
  FPF.burnLean68(L, { x = p.x - (W.sx or 0.0), y = p.y - (W.sy or 0.0), z = p.z })
  W.pitch, W.yaw = L.pitch, L.yaw
end

function FPF.burn2Frame()
  local H, K = PS.hp, FPC.burn2
  if not P.burn or not P.fxOn or not PS.ent or not H then return end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * K.worse)
  if PS.act and PS.act.kind == "drop" then low, worse = false, false end
  PS.burn2 = PS.burn2 or { stage = 0 }
  local B = PS.burn2
  local stage = (low and worse) and 2 or (low and 1 or 0)
  local less = P.burnLess and P.burnRow
  local half = less and P.burnHalf
  local small = P.burnSmall
  local big = (stage == 2 and small) and FPF.fireBig() or nil
  if stage ~= B.stage then
    B.stage = stage
    B.lines = (B.lines or 0) + 1
    if B.lines <= 12 then
      local two = "one segment left: sparks at its rear vents, burning electronics at its front vents and on its back, and "
        .. (P.burnRow and "a row of four of those small fires across its back (each leans as BT moves)" or "the big fire at its back")
      if small then
        two = "one segment left: sparks and a bigger electric failure at its rear vents, the three small flames and two more beside its main thruster (no bigger fire)"
          .. (big and "; the small flames are a quarter bigger" or "")
      elseif half then
        two = "one segment left: sparks at its rear vents, the three small flames stay, and one fire of burning electronics burns at its main thruster (it leans as BT moves)"
      elseif less then
        two = "one segment left: sparks at its rear vents, the small flames stay at its front vents, a fire of burning electronics on its back and two more across it (each leans as BT moves)"
      end
      log(string.format("effects: BT's hull is at %.0f %% of its health - %s", H.health / full * 100.0,
        (stage == 2) and two
          or ((stage == 1) and "sparks at its rear vents and small flames at its front vents and on its back" or "what burnt on it is put out")))
    end
  end
  for li, L in ipairs(K.layers) do
    local stay = (half and L.stayHalf) or L.stay
    local few = (half and L.half) or L.less
    local path = (big and L.path == K.layers[2].path) and big or L.path
    for si, slot in ipairs(L.slots) do
      local key = li * 10 + si
      local on = low and (not L.worse or worse) and (not PF.shown or L.fp == true)
        and (not L.big or not P.burnRow) and (not L.row or P.burnRow or L.small) and (not L.small or small)
      if small then
        if L.mid or L.big then on = false end
      else
        if on and L.first and worse and not (less and stay and stay[si]) then on = false end
        if on and less and few and not few[si] then on = false end
      end
      local R = B[key]
      if on and R and R.path ~= path then
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
        R = nil
      end
      if on then
        if not R or S.clock >= R.next then
          local where = L.row and L.row[si] or nil
          local p = (where ~= nil) and FPF.rowPoint(slot, where) or slotWorld(slot)
          if p then
            local inst = FPF.fxAt(path, p.x, p.y, p.z, PS.yaw, 0.0)
            if inst then
              PS.fxLive[#PS.fxLive + 1] = { inst = inst, slot = slot, till = S.clock + L.life, carry = true, yaw = PS.yaw, pitch = 0.0, burn = key,
                rigid = L.rigid, row = where }
              B[key] = { next = S.clock + L.life - K.overlap, path = path }
              PS.burns = (PS.burns or 0) + 1
            end
          end
        end
      elseif R then
        B[key] = nil
        for _, live in ipairs(PS.fxLive) do
          if live.burn == key and live.till > S.clock then live.till = S.clock end
        end
      end
    end
  end
end

P.cockFx = false
FPC.cockSparks.draw = { at = { { right = -0.811, up = 0.395, frame = 0.45 }, { right = 0.783, up = 0.248, frame = 0.46 } },
  rate = { 55.0, 110.0 }, life = { 0.22, 0.62 }, speed = { 0.06, 0.40 }, side = 0.09, fall = 1.05, drag = 1.2, len = 0.045,
  thick = { 2.0, 3.4 }, glow = { 3.0, 0.30 }, flash = { 0.012, 0.028, 5, 0.75 }, most = 260 }

function FPF.cockSparksAt(A, sw, sh)
  local fov = S.camFov * (1.0 - (1.0 - ZOOM.fov) * ease(PS.zoomW or 0.0))
  local ty = math.tan(math.rad(fov) * 0.5)
  local tx = ty * sw / sh
  return (0.5 + 0.5 * A.right / tx) * sw, (0.5 - 0.5 * (A.up - PF.joltX / A.frame) / ty) * sh
end

function FPF.cockSparksDraw(dl, sw, sh)
  local Q = PF.sparks
  if not Q or not PF.shown or not P.cockSparks or P.cockFx then return end
  local K, D = FPC.cockSparks, FPC.cockSparks.draw
  local now = S.clock
  local dt = clamp(now - (Q.drawAt or now), 0.0, 0.1)
  Q.drawAt = now
  Q.parts = Q.parts or {}
  local px = sh / 1440.0
  for _, L in ipairs(Q.live) do
    if not L.inst and now < L.till then
      local ex, ey = FPF.cockSparksAt(D.at[L.i], sw, sh)
      L.owed = (L.owed or 1.0) + D.rate[L.stage] * dt
      while L.owed >= 1.0 do
        L.owed = L.owed - 1.0
        if #Q.parts < D.most then
          local sp = (D.speed[1] + math.random() * (D.speed[2] - D.speed[1])) * sh
          Q.parts[#Q.parts + 1] = { x = ex + (math.random() - 0.5) * 8.0 * px, y = ey + (math.random() - 0.5) * 6.0 * px,
            vx = (math.random() - 0.5) * 2.0 * D.side * sh, vy = sp, t = 0.0, life = D.life[1] + math.random() * (D.life[2] - D.life[1]),
            w = D.thick[1] + math.random() * (D.thick[2] - D.thick[1]) }
          Q.drawn = (Q.drawn or 0) + 1
        end
      end
      if math.random() < D.flash[4] then
        for k = 1, D.flash[3] do
          local a = math.random() * 2.0 * math.pi
          local len = (D.flash[1] + math.random() * (D.flash[2] - D.flash[1])) * sh
          local c, sn = math.cos(a), math.sin(a)
          render.line(ex, ey, ex + c * len, ey + sn * len, GetColorU32(1.0, 0.72, 0.35, 0.30), 4.5 * px)
          render.line(ex, ey, ex + c * len, ey + sn * len, GetColorU32(0.86, 0.94, 1.0, 0.55 + 0.4 * math.random()), 1.6 * px)
        end
        render.line(ex - 2.5 * px, ey, ex + 2.5 * px, ey, GetColorU32(1.0, 0.97, 0.85, 0.9), 5.0 * px)
      end
    end
  end
  local keep = math.max(0.0, 1.0 - D.drag * dt)
  local least = 3.0 * px
  for n = #Q.parts, 1, -1 do
    local s = Q.parts[n]
    s.t = s.t + dt
    if s.t >= s.life then
      table.remove(Q.parts, n)
    else
      s.vx = s.vx * keep
      s.vy = s.vy * keep + D.fall * sh * dt
      s.x, s.y = s.x + s.vx * dt, s.y + s.vy * dt
      local u = s.t / s.life
      local a = (u < 0.6) and 1.0 or math.max(0.0, (1.0 - u) / 0.4)
      local g, b = 0.95 - 0.62 * u, math.max(0.0, 0.72 - 1.3 * u)
      local lx, ly = s.vx * D.len, s.vy * D.len
      local n2 = math.sqrt(lx * lx + ly * ly)
      if n2 < least then
        if n2 < 0.01 then lx, ly = 0.0, least else lx, ly = lx / n2 * least, ly / n2 * least end
      end
      render.line(s.x - lx, s.y - ly, s.x, s.y, GetColorU32(1.0, 0.5, 0.1, D.glow[2] * a), s.w * D.glow[1] * px)
      render.line(s.x - lx, s.y - ly, s.x, s.y, GetColorU32(1.0, g, b, a), s.w * px)
    end
  end
end

