function FPF.vLow()
  if PS.vLowLine == nil then
    PS.vLowLine = FPC.cockNoise.line
    pcall(function()
      local v = TweakDB:GetFlat("player.hitVFX.lowHealthThreshold")
      if type(v) == "number" and v > 0.0 then PS.vLowLine = v end
    end)
  end
  local pct = nil
  pcall(function()
    pct = Game.GetStatPoolsSystem():GetStatPoolValue(Game.GetPlayer():GetEntityID(), gamedataStatPoolType.Health, true)
  end)
  return type(pct) == "number" and pct <= PS.vLowLine
end

function FPF.cockNoiseSay(text)
  local Q = PF.noise
  if not Q then return end
  Q.lines = Q.lines + 1
  if Q.lines <= FPC.cockNoise.lines then log(text) end
end

function FPF.cockNoiseHull()
  local H = PS.hp
  return H and (H.health / (FPC.health.segment * FPC.health.segments) * 100.0) or 0.0
end

function FPF.cockNoiseOn()
  local K, Q = FPC.cockNoise, PF.noise
  if FPF.vLow() then
    Q.on, Q.mine, Q.lookAt = true, false, S.clock + K.look
    FPF.cockNoiseSay(string.format("COCKPIT NOISE: BT's hull is at %.0f %% of its health, and V's own health is under the game's line too - the game has its low-health picture on already: nothing is started",
      FPF.cockNoiseHull()))
    return true
  end
  local bb = nil
  local made, why = pcall(function()
    bb = worldEffectBlackboard.new()
    bb:SetValue(CName.new(K.key), K.state)
  end)
  local ok, err = false, nil
  if made and bb then
    ok, err = pcall(function() GameObjectEffectHelper.StartEffectEvent(Game.GetPlayer(), CName.new(K.name), false, bb) end)
  end
  if not ok and OP77.cutByTimeLimit(made and err or why) then return false end
  if not ok then
    local first = made and err or why
    ok, err = pcall(function() GameObjectEffectHelper.StartEffectEvent(Game.GetPlayer(), CName.new(K.name), false) end)
    if ok then
      bb = nil
      once("cocknoisebb" .. tostring(first), "COCKPIT NOISE: the effect's own value could NOT be given to it (" .. tostring(first) .. ") - the picture is started without it, as the game's photo mode does")
    end
  end
  if not ok and OP77.cutByTimeLimit(err) then return false end
  Q.bb = bb
  if not ok then
    P.cockNoise = false
    once("cocknoiseon" .. tostring(err), "COCKPIT NOISE: the game's low-health picture could NOT be started (" .. tostring(err) .. ") - switched off")
    return false
  end
  Q.on, Q.mine, Q.starts = true, true, Q.starts + 1
  FPF.cockNoiseSay(string.format("COCKPIT NOISE on: BT's hull is at %.0f %% of its health - the game's own low-health picture (its effect %s on V, %s %.2f) in the cockpit's view; started %d times so far",
    FPF.cockNoiseHull(), K.name, K.key, K.state, Q.starts))
  return true
end

function FPF.cockNoiseOff(why, soft)
  local K, Q = FPC.cockNoise, PF.noise
  if not Q or not Q.on then return end
  local mine = Q.mine
  Q.on, Q.mine, Q.bb = false, false, nil
  if not mine or FPF.vLow() then
    Q.holdTill = S.clock + K.again
    FPF.cockNoiseSay(string.format("COCKPIT NOISE off (%s): V's own health is under the game's line - that picture is the game's to end, nothing is stopped", tostring(why)))
    return
  end
  local ok, err = pcall(function()
    local p, name = Game.GetPlayer(), CName.new(K.name)
    if soft then GameObjectEffectHelper.BreakEffectLoopEvent(p, name) else GameObjectEffectHelper.StopEffectEvent(p, name) end
  end)
  Q.holdTill = S.clock + (soft and K.tail or K.again)
  if ok then
    FPF.cockNoiseSay(string.format("COCKPIT NOISE off (%s): %s", tostring(why), soft and "its loop is ended and it plays out" or "taken away at once"))
  else
    once("cocknoiseoff" .. tostring(err), "COCKPIT NOISE: the game's low-health picture could NOT be taken away (" .. tostring(err) .. ")")
  end
end

function FPF.cockNoiseFrame()
  local K, Q = FPC.cockNoise, PF.noise
  if not Q then
    if not P.cockNoise then return end
    Q = { on = false, mine = false, starts = 0, lines = 0, holdTill = 0.0, lookAt = 0.0 }
    PF.noise = Q
    if not FPF.vLow() then
      pcall(function() GameObjectEffectHelper.StopEffectEvent(Game.GetPlayer(), CName.new(K.name)) end)
    end
  end
  local H = PS.hp
  local held = PF.shown == true and S.driving == true and PS.mode == "pilot" and not PS.eject and S.clock - (PF.noiseRode or -10.0) < 0.3
  local low = false
  if H and P.burn and P.fxOn then
    low = (H.doomed or (P.throwOut and H.health <= FPC.health.segment * FPC.health.segments * P.smokeAt)) and true or false
  end
  local want = P.cockNoise and held and low
  if want and not Q.on then
    if S.clock >= Q.holdTill then FPF.cockNoiseOn() end
  elseif Q.on and not want then
    if not P.cockNoise then
      FPF.cockNoiseOff("switched off", false)
    elseif not held then
      FPF.cockNoiseOff("the cockpit's view is not held any more", false)
    else
      FPF.cockNoiseOff("BT's hull has more than two segments again", true)
    end
  elseif Q.on and not Q.mine and S.clock >= Q.lookAt then
    Q.lookAt = S.clock + K.look
    if not FPF.vLow() then
      Q.on, Q.holdTill = false, S.clock + K.tail
      FPF.cockNoiseSay(string.format("COCKPIT NOISE: V's own health is over the game's line again - the game ends its picture; BT's own is started in %.1f s", K.tail))
    end
  end
end

