function FPF.keyShown(raw)
  if type(raw) ~= "string" or raw == "" or raw == "?" or raw == "None" or raw:find("^Unknown") then return nil end
  local short = FPC.keyHints.names[raw]
  if short then return short end
  local n = raw:match("^NumPad(%d)$")
  if n then return "NUM " .. n end
  n = raw:match("^Mouse(%d)$")
  if n then return "MOUSE " .. n end
  return (raw:gsub("_", " ")):upper()
end

function FPF.keyHint(field)
  if not P.keyHints or not S.keysOk then return "" end
  local shown = FPF.keyShown(FPF.keyFor(field))
  return shown and (" (" .. shown .. ")") or ""
end

function FPF.lineH()
  local C = S.fontH
  if C and S.clock - C.at < 5.0 then return C.h end
  local h, asked = nil, false
  pcall(function()
    local _, y = render.textSize("BT")
    if type(y) == "number" and y > 4.0 then h, asked = y, true end
  end)
  if not h then
    local sw, sh = render.size()
    h = 18.0 * math.min(sw / 1920.0, sh / 1080.0)
  end
  S.fontH = { h = h, at = S.clock, asked = asked }
  return h
end

function FPF.textW(text)
  local C = S.textWs
  if not C or S.clock - C.at > 5.0 then
    C = { at = S.clock, w = {} }
    S.textWs = C
  end
  local w = C.w[text]
  if not w then
    pcall(function()
      local v = render.textSize(text)
      if type(v) == "number" and v > 0.0 then w = v end
    end)
    w = w or (#text * 0.46 * FPF.lineH())
    C.w[text] = w
  end
  return w
end

function FPF.skillNames(sx)
  local K = FPC.keyHints
  local N = { missiles = "MISSILES" .. FPF.keyHint("missileKey"), vortex = "VORTEX" .. FPF.keyHint("vortexKey"),
    smoke = "ELECTRIC SMOKE" .. FPF.keyHint("smokeKey") }
  local widest = math.max(FPF.textW(N.missiles), FPF.textW(N.vortex), FPF.textW(N.smoke))
  local nx = math.min(sx - K.column, sx - K.gap - widest)
  if P.keyHints and S.keysOk then
    local sig = N.missiles .. ", " .. N.vortex .. ", " .. N.smoke .. ", DASH" .. FPF.keyHint("dashKey")
    if sig ~= S.hintSig then
      S.hintSig, S.hintLines = sig, (S.hintLines or 0) + 1
      if S.hintLines <= K.lines then log("HUD keys (as bound in Mod Settings, Standby for > Keys): " .. sig) end
    end
  end
  local lh = FPF.lineH()
  if lh ~= S.fontSaid then
    S.fontSaid, S.fontLines = lh, (S.fontLines or 0) + 1
    if S.fontLines <= 4 then
      local sw, sh = render.size()
      log(string.format("HUD letters: a line is %.0f px tall (%s; the picture is %d x %d) - \"%s\" is %.0f px wide, the names' column begins %.0f px before the bars",
        lh, (S.fontH and S.fontH.asked) and "asked of the overlay" or "taken from the picture's height", sw, sh, N.smoke, FPF.textW(N.smoke), sx - nx))
    end
  end
  return N, nx
end

