P.noiseView = true
FPC.cockNoise.lines = 40
FPC.cockNoise.view = { ahead = 1.2, states = { 0.9, 0.8 }, files = {
  { [[titan\bt7274\fx\bt_view_low_health_1.effect]], [[titan\bt7274\fx\bt_view_glitch_1.effect]] },
  { [[titan\bt7274\fx\bt_view_low_health_2.effect]], [[titan\bt7274\fx\bt_view_glitch_2.effect]] } } }
FPC.keyHints.locksUp = 2

function FPF.noiseStage()
  local H = PS.hp
  if not (H and P.burn and P.fxOn) then return 0 end
  local full = FPC.health.segment * FPC.health.segments
  local low = H.doomed or (P.throwOut and H.health <= full * P.smokeAt)
  local worse = H.doomed or (P.throwOut and H.health <= full * FPC.burn2.worse)
  return (low and worse) and 2 or (low and 1 or 0)
end

function FPF.noiseViewHas(path)
  PS.noiseAsk = PS.noiseAsk or {}
  local T = PS.noiseAsk[path]
  if not T then
    T = { at = S.clock }
    local ok, err = pcall(function() T.tok = Game.GetResourceDepot():LoadResource(path) end)
    if not ok then T.err = tostring(err) end
    PS.noiseAsk[path] = T
  end
  if not T.tok then return true end
  local state = "?"
  pcall(function() state = T.tok:IsFailed() and "it could NOT be loaded" or (T.tok:IsLoaded() and "loaded" or "not loaded yet") end)
  if state ~= T.state then
    T.state = state
    FPF.cockNoiseSay(string.format("COCKPIT NOISE on the picture: %s - the game's depot says: %s", path, state))
  end
  if state == "loaded" then return true end
  return state == "?" and S.clock - T.at > 2.0
end

function FPF.noisePlace()
  local Q = PF.noise
  local C = Q and Q.cam
  if not C then return nil end
  local _, F = FPF.axes(C[4], C[5], C[6])
  local a = FPC.cockNoise.view.ahead
  return C[1] + F[1] * a, C[2] + F[2] * a, C[3] + F[3] * a
end

function FPF.noiseViewOff(soft, why)
  local K, Q = FPC.cockNoise, PF.noise
  local V = Q and Q.view
  if not V then return end
  Q.view = nil
  Q.dying = Q.dying or {}
  for _, L in ipairs(V.live) do
    local inst = L.inst
    FPF.fxBreak152(inst)
    if soft then
      Q.dying[#Q.dying + 1] = { inst = inst, at = S.clock + K.tail }
    else
      FPF.fxKill152(inst)
    end
  end
  FPF.cockNoiseSay(string.format("COCKPIT NOISE on the picture: off (%s) - its %d effects %s", tostring(why), #V.live,
    soft and string.format("play out for %.1f s", K.tail) or "are taken away at once"))
end

function FPF.noiseViewCarry()
  local Q = PF.noise
  if not Q or not Q.cam then return end
  local px, py, pz = FPF.noisePlace()
  local C = Q.cam
  local function put(inst)
    pcall(function()
      local tr = WorldTransform.new()
      WorldTransform.SetPosition(tr, Vector4.new(px, py, pz, 1.0))
      if not PS.fxNoTurn then WorldTransform.SetOrientation(tr, EulerAngles.ToQuat(EulerAngles.new(C[6], C[5], C[4]))) end
      if FPF.fxLive152(inst) then inst:UpdateTransform(tr) end
    end)
  end
  if Q.view then
    for _, L in ipairs(Q.view.live) do put(L.inst) end
  end
  for _, D in ipairs(Q.dying or {}) do put(D.inst) end
end

function FPF.noiseViewFrame()
  local K, Q = FPC.cockNoise, PF.noise
  if not Q then return end
  if Q.dying then
    for n = #Q.dying, 1, -1 do
      local D = Q.dying[n]
      if S.clock >= D.at then
        FPF.fxKill152(D.inst)
        table.remove(Q.dying, n)
      end
    end
  end
  local on = Q.on or (Q.viewKeep ~= nil and S.clock < Q.viewKeep)
  local held = PF.shown == true and S.driving == true and PS.mode == "pilot" and not PS.eject and S.clock - (PF.noiseRode or -10.0) < 0.3
  local stage = (on and held and P.noiseView and P.cockNoise and Q.cam) and FPF.noiseStage() or 0
  if stage > 0 and Q.on and Q.mine and Q.bb and (Q.stateOf ~= Q.bb or Q.state ~= K.view.states[stage]) then
    local bb, want = Q.bb, K.view.states[stage]
    local ok, err = pcall(function() bb:SetValue(CName.new(K.key), want) end)
    Q.stateOf, Q.state = bb, want
    FPF.cockNoiseSay(ok and string.format("COCKPIT NOISE: V's own effect is given %s %.2f (%s) - its own picture faintly, should the game draw it from where V rides", K.key, want,
      (stage == 2) and "one segment left" or "two segments left") or ("COCKPIT NOISE: V's own effect could NOT be given its value (" .. tostring(err) .. ")"))
  end
  local V = Q.view
  if V and V.stage ~= stage then
    FPF.noiseViewOff(false, (stage == 0) and "they are not wanted any more" or "the hull's state is another")
    V = nil
  end
  if stage == 0 or V then return end
  local files = K.view.files[stage]
  for _, path in ipairs(files) do
    if not FPF.noiseViewHas(path) then return end
  end
  local px, py, pz = FPF.noisePlace()
  V = { stage = stage, live = {} }
  for _, path in ipairs(files) do
    local inst = FPF.fxAt(path, px, py, pz, Q.cam[4], Q.cam[5])
    if inst then V.live[#V.live + 1] = { inst = inst, path = path } end
  end
  Q.view, Q.views = V, (Q.views or 0) + 1
  FPF.cockNoiseSay(string.format("COCKPIT NOISE on the picture (%s): %d of %d particle effects started %.1f m in front of the view, carried with it - the red vignette with its noise blocks, and the glitch that flashes across the picture; started %d times so far",
    (stage == 2) and "one segment left: the stronger pair" or "two segments left: the weaker pair", #V.live, #files, K.view.ahead, Q.views))
end

