FPC.ai.shieldIn, FPC.ai.shieldNeed, FPC.ai.shieldNeedLow, FPC.ai.shieldGap = 4.0, 0.01, 0.005, 12.0

FPF.aiSkillsRun72 = FPF.aiSkillsRun
function FPF.aiSkillsRun(B, A, dt, T)
  local n0 = A.shields
  FPF.aiSkillsRun72(B, A, dt, T)
  local K, H, V, M = FPC.ai, PS.hp, PS.vortex, PS.mtms
  if not H or FPF.guardPlain() then return end
  local X = A.shieldSeen
  if not X then
    X = { most = 0.0, over = 0.0, gap = 0.0, charge = 0.0, near = 0.0, noFoe = 0.0, busy = 0.0 }
    A.shieldSeen = X
  end
  if A.shields ~= n0 then return end
  local share = (A.heat or 0.0) / (FPC.health.segment * FPC.health.segments + FPC.health.shield)
  if share > X.most then X.most = share end
  local mark = (H.shield <= FPC.health.shield * K.shieldLow) and K.shieldNeedLow or K.shieldNeed
  if share < mark or (V and V.on) or not P.aiSkills then return end
  X.over = X.over + dt
  if not T then
    X.noFoe = X.noFoe + dt
  elseif T.dist <= FPF.aiPunchZone() then
    X.near = X.near + dt
  elseif S.clock - A.shieldAt < K.shieldGap then
    X.gap = X.gap + dt
  elseif not V or V.frac > 0.15 then
    X.charge = X.charge + dt
  else
    X.busy = X.busy + dt
  end
end

FPF.buddyEnd72 = FPF.buddyEnd
function FPF.buddyEnd(why)
  local B = PS.buddy
  local A = B and B.ai
  local X = A and A.shieldSeen
  if X and (A.shields > 0 or X.most >= 0.001) then
    local K = FPC.ai
    log(string.format("BT on its own, the vortex shield: raised %d times; the most taken off BT within moments, the shield not up: %.1f %% of its health and shield (the mark is %.1f %%, %.1f %% with its own shield nearly gone; it fades with %.1f s); wanted and not raised for %.1f s - %.1f s the last one was less than %.0f s ago, %.1f s its charge was not back, %.1f s a foe was within the fist's reach, %.1f s no foe was in its sight, %.1f s it was at something else (its missiles, a punch)",
      A.shields, X.most * 100.0, K.shieldNeed * 100.0, K.shieldNeedLow * 100.0, K.shieldIn, X.over, X.gap, K.shieldGap, X.charge, X.near, X.noFoe, X.busy))
  end
  return FPF.buddyEnd72(why)
end

FPC.gunOwn.midCurve = { { -1.0, 0.5 }, { 0.0, 0.5 }, { 20.0, 0.8 }, { 50.0, 0.8 }, { 90.0, 0.0 } }

P.gunDir = true
FPC.gunDir = { steps = 8, suffix = "_p%02d", near = 0.5, place = "bt7274_muzzle", placeFor = 4.0, lines = 4, every = 4.0,
  panned = {}, muzzle = { [FPC.gunOwn.tail] = true } }
for _, name in ipairs(FPC.gunOwn.mid) do FPC.gunDir.panned[name] = true end
for _, name in ipairs(FPC.gunOwn.far) do FPC.gunDir.panned[name] = true end
for _, name in ipairs(FPC.gunOwn.close) do FPC.gunDir.muzzle[name] = true end
for _, name in ipairs(FPC.gunOwn.reload) do FPC.gunDir.muzzle[name] = true end

function FPF.gunSide()
  if PS.sideAt == S.clock then return PS.side, PS.sideM end
  local side, m = nil, nil
  pcall(function() m = muzzleWorld() end)
  if m then
    pcall(function()
      local e = viewOfV()
      local dx, dy, dz = m.x - e.x, m.y - e.y, m.z - e.z
      local n = math.sqrt(dx * dx + dy * dy + dz * dz)
      PS.sideFar, PS.sideUp = n, dz
      if n < FPC.gunDir.near then
        side = 0.0
        return
      end
      local r = math.rad(e.yaw)
      side = clamp((dx * math.cos(r) + dy * math.sin(r)) / n, -1.0, 1.0)
    end)
  end
  PS.sideAt, PS.side, PS.sideM = S.clock, side, m
  return side, m
end

function FPF.gunSideSeen(side, row, took)
  local G = FPC.gunDir
  local X = PS.sideSeen or { n = 0, left = 0, mid = 0, right = 0, lines = 0 }
  PS.sideSeen, PS.sideNow = X, side
  X.n = X.n + 1
  if side < -0.25 then X.left = X.left + 1 elseif side > 0.25 then X.right = X.right + 1 else X.mid = X.mid + 1 end
  if X.lines < G.lines and (X.at == nil or S.clock - X.at >= G.every) then
    X.lines, X.at = X.lines + 1, S.clock
    log(string.format("BT's own gun, a round: its muzzle is %s for the view (side %+.2f; %.0f m from the view, %+.1f m above it) - the row %s%s",
      side < -0.25 and "to the left" or (side > 0.25 and "to the right" or "ahead or behind"), side, PS.sideFar or 0.0, PS.sideUp or 0.0, row,
      took == false and " could NOT be played" or ""))
  end
end

function FPF.muzzlePlace(axl)
  local G = FPC.gunDir
  local _, m = FPF.gunSide()
  if not m or PS.sunk then return false end
  local ok = axl:CreateEmitter(G.place, m.x, m.y, m.z) ~= false
  PS.muzzleAt = ok and S.clock or nil
  if PS.muzzleSaid ~= ok then
    PS.muzzleSaid = ok
    local r = math.rad(PS.yaw or 0.0)
    local fx, fy = -math.sin(r), math.cos(r)
    local dx, dy = m.x - PS.x, m.y - PS.y
    log(ok and string.format("BT's own gun: its close take, its tail and its reload are on a place of their own at the muzzle (%s) - %.1f m ahead of BT's feet, %.1f m to their right, %.1f m up; put there before each of them and moved with the muzzle",
        G.place, dx * fx + dy * fy, dx * fy - dy * fx, m.z - PS.z)
      or ("BT's own gun: a place at the muzzle (" .. G.place .. ") could NOT be made - its close take is on BT's own place, at its feet, as before"))
  end
  return ok
end

function FPF.muzzleFrame()
  if not P.gunDir or not PS.muzzleAt or S.clock - PS.muzzleAt > FPC.gunDir.placeFor then return end
  if S.driving or not PS.ent or not IsDefined(PS.ent) then return end
  local axl = FPF.axl()
  if not axl then return end
  pcall(function()
    local m = muzzleWorld()
    if axl:MoveEmitter(FPC.gunDir.place, m.x, m.y, m.z) == false then PS.muzzleAt = nil end
  end)
end

FPF.on75 = FPF.on
function FPF.on(axl, name, gain)
  local G = FPC.gunDir
  if P.gunDir and not S.driving then
    if G.panned[name] then
      if PS.sideHas == nil then
        local ahead = name .. string.format(G.suffix, G.steps)
        PS.sideHas = axl:Has(ahead) ~= false
        log(PS.sideHas and string.format("BT's own gun is heard from the side its muzzle is on: its middle and far takes have a row for each side (%d a take; %s is the one for ahead)", 2 * G.steps + 1, ahead)
          or ("BT's own gun: AudioXL does not know " .. ahead .. " (its folder sounds/BT7274 is an older build's) - the middle and far takes are heard from the middle of the head as before"))
      end
      local side = PS.sideHas and FPF.gunSide() or nil
      if side then
        local row = name .. string.format(G.suffix, math.floor(side * G.steps + 0.5) + G.steps)
        local took = FPF.on75(axl, row, gain)
        FPF.gunSideSeen(side, row, took)
        return took
      end
    elseif G.muzzle[name] and P.ownPlace and FPF.muzzlePlace(axl) then
      PS.muzzlePlays = (PS.muzzlePlays or 0) + 1
      return axl:PlayOn(G.place, name, gain)
    end
  end
  return FPF.on75(axl, name, gain)
end

FPF.placeFrame75 = FPF.placeFrame
function FPF.placeFrame()
  FPF.placeFrame75()
  FPF.muzzleFrame()
end

FPF.buddyEnd75 = FPF.buddyEnd
function FPF.buddyEnd(why)
  local X = PS.sideSeen
  if PS.buddy and ((X and X.n > 0) or (PS.muzzlePlays or 0) > 0) then
    log(string.format("BT on its own, where its gun was heard from: %d takes on a row for their side - %d to the left of the view, %d ahead or behind, %d to the right; its close take, tail and reload on the place at the muzzle %d times",
      X and X.n or 0, X and X.left or 0, X and X.mid or 0, X and X.right or 0, PS.muzzlePlays or 0))
    PS.sideSeen, PS.muzzlePlays = nil, nil
  end
  return FPF.buddyEnd75(why)
end

P.sideAll = true
FPC.side = { suffix = "_p%02d", near = 1.0, body = 4.2, probe = "bt7274_step_mid_1_p00", lines = 8, every = 2.0, rows = {} }
do
  local function add(list, k, at)
    for _, name in ipairs(list) do FPC.side.rows[name] = { k = k, at = at } end
  end
  add(FPC.steps.mid, 4, "feet")
  add(FPC.steps.far, 4, "feet")
  add(FPC.mtms.sounds.near, 2, "point")
  add(FPC.mtms.sounds.mid, 2, "point")
  add(FPC.mtms.sounds.far, 2, "point")
  add(FPC.mtms.sounds.fire, 2, "body")
  add(FPC.punchTf.swing, 2, "body")
  add(FPC.punchTf.hit, 2, "body")
  add(FPC.vortex.sounds.catch, 2, "body")
  add({ FPC.vortex.sounds.stop }, 2, "body")
  add({ FPC.vortex.sounds.throw, FPC.vortex.sounds.start, FPC.esmoke.sounds.deploy }, 1, "body")
  add(FPC.esmoke.sounds.hurt, 1, "body")
  add(FPC.dash.tp, 1, "body")
  add(FPC.jump.sounds.start, 1, "body")
  add(FPC.jump.sounds.land, 2, "body")
end

function FPF.sideView()
  if PS.sideViewAt == S.clock and PS.sideViewNow then return PS.sideViewNow end
  local v = nil
  if S.driving and S.camPos then
    v = { x = S.camPos.x, y = S.camPos.y, z = S.camPos.z, yaw = S.yaw or 0.0 }
  else
    local ok, e = pcall(viewOfV)
    if ok and e then v = { x = e.x, y = e.y, z = e.z, yaw = e.yaw } end
  end
  PS.sideViewAt, PS.sideViewNow = S.clock, v
  return v
end

function FPF.sideTo(x, y, z)
  local v = FPF.sideView()
  if not v then return nil end
  local dx, dy, dz = x - v.x, y - v.y, z - v.z
  local n = math.sqrt(dx * dx + dy * dy + dz * dz)
  if n < FPC.side.near then return 0.0, n end
  local r = math.rad(v.yaw)
  return clamp((dx * math.cos(r) + dy * math.sin(r)) / n, -1.0, 1.0), n
end

function FPF.sideName(name)
  local G = FPC.side
  local R = (P.sideAll and name) and G.rows[name] or nil
  if not R then return name end
  local D = PS.sideMemo
  if D and D.name == name and D.at == S.clock then return D.row end
  local at, x, y, z = PS.soundAt, nil, nil, nil
  if at then
    x, y, z = at.x, at.y, at.z
  elseif R.at == "point" or S.driving or not PS.ent or not PS.x then
    return name
  else
    x, y, z = PS.x, PS.y, PS.z + ((R.at == "body") and G.body or 0.0)
  end
  if PS.sideAllHas == nil then
    local axl = FPF.axl()
    if not axl then return name end
    local known = nil
    pcall(function() known = axl:Has(G.probe) end)
    PS.sideAllHas = known ~= false
    local n = 0
    for _ in pairs(G.rows) do n = n + 1 end
    log(PS.sideAllHas and string.format("BT's sounds heard from outside come from their side: %d of its plain rows have rows for a side each (footsteps further off, missiles, fist, shield, smoke, dash, jump)", n)
      or ("BT's sounds heard from outside: AudioXL does not know " .. G.probe .. " (its folder sounds/BT7274 is an older build's) - they are heard from the middle of the head as before"))
  end
  if not PS.sideAllHas then return name end
  local side, far = FPF.sideTo(x, y, z)
  if not side then return name end
  local i = math.floor(side * R.k + 0.5)
  local row = (i == 0) and name or (name .. string.format(G.suffix, i + R.k))
  PS.sideMemo = { name = name, at = S.clock, row = row }
  PS.sideLast = PS.sideLast or {}
  PS.sideLast[name] = (i ~= 0) and row or nil
  local X = PS.sideAllSeen or { n = 0, left = 0, mid = 0, right = 0, lines = 0 }
  PS.sideAllSeen, PS.sideAllNow = X, side
  X.n = X.n + 1
  if i < 0 then X.left = X.left + 1 elseif i > 0 then X.right = X.right + 1 else X.mid = X.mid + 1 end
  if X.lines < G.lines and (X.at == nil or S.clock - X.at >= G.every) then
    X.lines, X.at = X.lines + 1, S.clock
    log(string.format("a sound from its side: %s comes from %s for the view (side %+.2f, %.0f m away%s) - the row %s", name,
      (i < 0) and "the left" or ((i > 0) and "the right" or "ahead or behind"), side, far or 0.0, at and "; the place it happens at" or "", row))
  end
  return row
end

function FPF.tfAt(name, x, y, z)
  PS.soundAt = { x = x, y = y, z = z }
  local ok, a, b = pcall(FPF.tf, name)
  PS.soundAt = nil
  if not ok then error(a, 0) end
  return a, b
end

function FPF.sideStop(axl, name, fade)
  axl:Stop(name, fade)
  local row = PS.sideLast and PS.sideLast[name]
  if row then
    PS.sideLast[name] = nil
    axl:Stop(row, fade)
  end
end

FPF.tf76 = FPF.tf
function FPF.tf(name, line)
  if not line then name = FPF.sideName(name) end
  return FPF.tf76(name, line)
end

FPF.on76 = FPF.on
function FPF.on(axl, name, gain)
  return FPF.on76(axl, FPF.sideName(name), gain)
end

FPF.buddyEnd76 = FPF.buddyEnd
function FPF.buddyEnd(why)
  local X = PS.sideAllSeen
  if PS.buddy and X and X.n > 0 then
    log(string.format("BT on its own, where its other sounds were heard from (footsteps further off, missiles, fist, shield, smoke, dash, jump): %d played - %d from the left of the view, %d from ahead or behind, %d from the right",
      X.n, X.left, X.mid, X.right))
    PS.sideAllSeen = nil
  end
  return FPF.buddyEnd76(why)
end

