function FPF.nat()
  local N = PS.nat
  if not N then
    N = { labels = {}, asked = {}, ready = false, broken = nil, lines = 0 }
    PS.nat = N
  end
  return N
end

function FPF.nativeFont()
  local K, N = FPC.native, FPF.nat()
  if N.fontAt == nil or S.clock >= N.fontAt then
    N.fontAt = S.clock + K.lang.every
    local code = nil
    pcall(function()
      local v = Game.GetSettingsSystem():GetVar(K.lang.group, K.lang.name):GetValue()
      local t = nil
      pcall(function() t = v.value end)
      if type(t) ~= "string" then t = tostring(v) end
      code = t:match("%a%a%-%a%a")
    end)
    N.lang, N.font = code, K.fonts[code or ""] or K.fonts.latin
  end
  local lh = FPF.lineH()
  return N.font, math.floor(K.cap * lh / N.font.cap + N.font.less + 0.5), lh
end

function FPF.nativeW(text)
  local F, size = FPF.nativeFont()
  local w = 0.0
  for i = 1, #text do w = w + (F.w[text:byte(i)] or 0.55) end
  return w * (size - F.less)
end

function FPF.rgba(col)
  if type(col) ~= "number" or col ~= col then return 1.0, 1.0, 1.0, 1.0 end
  if col < 0 then col = col + 4294967296 end
  col = math.floor(col)
  return (col % 256) / 255.0, (math.floor(col / 256) % 256) / 255.0, (math.floor(col / 65536) % 256) / 255.0, (math.floor(col / 16777216) % 256) / 255.0
end

function FPF.nativeRoot(N)
  local K = FPC.native
  if N.root then
    local alive = false
    pcall(function() alive = IsDefined(N.root) end)
    if alive then return N.root end
    N.root, N.labels = nil, {}
  end
  if N.rootAt and S.clock < N.rootAt then return nil end
  N.rootAt = S.clock + 1.0
  local root, err = nil, nil
  local ok, why = pcall(function()
    local ink = nil
    pcall(function() ink = GameInstance.GetInkSystem() end)
    if not ink then ink = Game.GetInkSystem() end
    root = ink:GetLayer(K.layer):GetVirtualWindow()
  end)
  if not ok then err = tostring(why) end
  if not root or not IsDefined(root) then
    if N.rootSaid ~= false then
      N.rootSaid = false
      log("BT's HUD letters: the game's HUD layer (" .. K.layer .. ") cannot be had (" .. tostring(err or "it is not there") .. ") - Codeware gives it; the overlay's font is used, as before")
    end
    return nil
  end
  local old = 0
  N.root, N.labels = root, {}
  local sw, sh = render.size()
  local ww, wh = nil, nil
  pcall(function()
    local v = root:GetSize()
    ww, wh = v.x, v.y
  end)
  N.scale = 1.0
  if type(ww) == "number" and type(wh) == "number" and ww >= 640.0 and wh >= 360.0 and math.abs(ww / wh - sw / sh) < 0.02 * sw / sh then N.scale = ww / sw end
  if old > 0 and N.lines < K.lines then
    N.lines = N.lines + 1
    log(string.format("BT's HUD letters: %d widgets of an earlier run taken off the HUD layer", old))
  end
  if N.rootSaid ~= true then
    N.rootSaid = true
    local F, size, lh = FPF.nativeFont()
    log(string.format("BT's HUD letters are the game's own text: widgets on its HUD layer (%s; the layer says it is %s for a picture of %d x %d - %s), the font family Raj / %s as the game has it for its texts' language (%s), size %d for a line of %.0f px",
      K.layer, (type(ww) == "number" and type(wh) == "number") and string.format("%.0f x %.0f", ww, wh) or "nothing about its size", sw, sh,
      (N.scale == 1.0) and "its units are taken as the picture's pixels" or string.format("places and sizes are scaled by %.3f", N.scale),
      K.style, tostring(N.lang or "not read: taken as a Latin one"), math.floor(size * N.scale + 0.5), lh))
  end
  return root
end

function FPF.nativeMake(root, i)
  local K = FPC.native
  local t = inkText.new()
  t:SetName(CName.new(K.name .. i))
  t:SetFontFamily(K.family)
  t:SetFontStyle(CName.new(K.style))
  t:SetFitToContent(true)
  pcall(function() t:SetLetterCase(textLetterCase.OriginalCase) end)
  pcall(function() t:SetAnchor(inkEAnchor.TopLeft) end)
  pcall(function() t:SetHorizontalAlignment(textHorizontalAlignment.Left) end)
  pcall(function() t:SetVerticalAlignment(textVerticalAlignment.Center) end)
  t:SetText("")
  t:SetVisible(false)
  t:Reparent(root)
  return { w = t, text = "", shown = false }
end

function FPF.nativeHide(N, from)
  for i = from + 1, #N.labels do
    local L = N.labels[i]
    if L.shown then
      L.w:SetVisible(false)
      L.shown = false
    end
  end
end

function FPF.nativeApply(N, root, asked)
  local K = FPC.native
  local F, size, lh = FPF.nativeFont()
  local k = N.scale or 1.0
  size = math.floor(size * k + 0.5)
  local n = math.min(#asked, K.most)
  for i = 1, n do
    local A, L = asked[i], N.labels[i]
    if not L then
      L = FPF.nativeMake(root, i)
      N.labels[i] = L
      N.made = (N.made or 0) + 1
    end
    local t = L.w
    if L.size ~= size then
      t:SetFontSize(size)
      L.size = size
    end
    if L.text ~= A.text then
      t:SetText(A.text)
      L.text = A.text
    end
    local ax = (A.align == "c") and 0.5 or ((A.align == "r") and 1.0 or 0.0)
    if L.ax ~= ax then
      t:SetAnchorPoint(ax, 0.5)
      L.ax = ax
    end
    local x, y = A.x * k, (A.y + K.mid * lh) * k
    if L.x ~= x or L.y ~= y then
      t:SetTranslation(x, y)
      L.x, L.y = x, y
    end
    if L.col ~= A.col then
      local r, g, b, a = FPF.rgba(A.col)
      t:SetTintColor(HDRColor.new({ Red = r, Green = g, Blue = b, Alpha = 1.0 }))
      t:SetOpacity(a)
      L.col = A.col
    end
    if not L.shown then
      t:SetVisible(true)
      L.shown = true
    end
  end
  FPF.nativeHide(N, n)
  N.count = n
  if n > 0 and N.measure == nil then
    N.measure = { at = S.clock, text = asked[1].text }
  elseif N.measure and N.measure ~= true and S.clock > N.measure.at and N.labels[1] and N.labels[1].text == N.measure.text then
    local M = N.measure
    N.measure = true
    local w, h = nil, nil
    pcall(function()
      local v = N.labels[1].w:GetDesiredSize()
      w, h = v.x, v.y
    end)
    log(string.format("BT's HUD letters: \"%s\" measures %s as the game lays it out (this script takes it for %.0f px wide; a line of the overlay's font is %.0f px)",
      M.text, (w and h) and string.format("%.0f x %.0f", w, h) or "nothing it can be asked", FPF.nativeW(M.text), lh))
    pcall(FPF.nativeFit, M.text, w)
  end
end

function FPF.labelsFrame()
  local N = PS.nat
  if not N then return end
  local asked = N.asked
  N.asked = {}
  if S.gone then
    N.root, N.labels, N.ready, N.rootAt, N.count = nil, {}, false, nil, 0
    return
  end
  if not P.hudNative or N.broken then
    if N.ready then pcall(FPF.nativeHide, N, 0) end
    N.ready, N.count = false, 0
    return
  end
  local root = FPF.nativeRoot(N)
  if not root then
    N.ready, N.count = false, 0
    return
  end
  local ok, err = pcall(FPF.nativeApply, N, root, asked)
  if not ok and OP77.cutByTimeLimit(err) then return end
  if not ok then
    N.broken, N.ready, N.count = tostring(err), false, 0
    log("BT's HUD letters could NOT be written with the game's own text (" .. N.broken .. ") - the overlay's font is used, as before")
    pcall(FPF.nativeHide, N, 0)
    return
  end
  N.ready = true
end

function FPF.label(dl, x, y, col, text, align, ax)
  if P.hudNative then
    local N = FPF.nat()
    if N.ready and not N.broken and #N.asked < FPC.native.most then
      N.asked[#N.asked + 1] = { x = align and ax or x, y = y, col = col, text = text, align = align }
      return
    end
  end
  render.text(x, y, col, text)
end

function FPF.nativeSay()
  local N = PS.nat
  if not P.hudNative then return "switched off: the overlay's font" end
  if not N then return "not asked for yet (no HUD drawn)" end
  if N.broken then return "the game did not take it (" .. N.broken .. "): the overlay's font" end
  if not N.ready then return "the game's HUD layer is not there: the overlay's font" end
  return string.format("the game's own text: %d labels made, %d on the picture, language %s, size %d", N.made or 0, N.count or 0, tostring(N.lang or "?"),
    select(2, FPF.nativeFont()))
end

FPF.textW77 = FPF.textW
function FPF.textW(text)
  local N = PS.nat
  if P.hudNative and N and N.ready and not N.broken then return FPF.nativeW(text) end
  return FPF.textW77(text)
end

FPC.gone = { every = 0.25, forSeconds = 4.0, later = 2.0, most = 40, paths = 8 }

function FPF.letGo()
  local n = { people = 0, devices = 0, vehicles = 0, labels = 0 }
  for _ in pairs(PS.npcKeep or {}) do n.people = n.people + 1 end
  n.devices = PS.devs and #PS.devs or 0
  for _ in pairs(PS.doomed or {}) do n.vehicles = n.vehicles + 1 end
  PS.npcKeep, PS.npcShape, PS.devs, PS.devKeys, PS.doomed = nil, {}, nil, nil, nil
  local N = PS.nat
  if N then
    n.labels = #N.labels
    N.root, N.labels, N.asked, N.ready, N.rootAt, N.count = nil, {}, {}, false, nil, 0
  end
  return n
end

function FPF.sweepHeld()
  local found, seen = {}, {}
  local function walk(t, path, depth)
    if seen[t] or depth > 5 then return end
    seen[t] = true
    local drop = nil
    for k, v in pairs(t) do
      local kind = type(v)
      if kind == "userdata" then
        if pcall(IsDefined, v) then
          drop = drop or {}
          drop[#drop + 1] = k
        end
      elseif kind == "table" then
        walk(v, path .. "." .. tostring(k), depth + 1)
      end
    end
    for _, k in ipairs(drop or {}) do
      t[k] = nil
      found[#found + 1] = path .. "." .. tostring(k)
    end
  end
  walk(PS, "PS", 1)
  walk(PF, "PF", 1)
  walk(S, "S", 1)
  return found
end

FPF.sessionEnd78 = FPF.sessionEnd
function FPF.sessionEnd(why)
  if S.gone then return end
  local n = FPF.letGo()
  FPF.sessionEnd78(why)
  local left = FPF.sweepHeld()
  S.goneRuns, S.goneRunAt, S.goneHooks, S.goneHooksSeen = 0, S.clock, 0, 0
  if n.people + n.devices + n.vehicles + n.labels + #left > 0 then
    local named = {}
    for i = 1, math.min(#left, FPC.gone.paths) do named[i] = left[i] end
    log(string.format("SESSION END: let go of %d people kept for BT's rounds, %d turrets or cameras, %d vehicles that were to blow up, %d HUD labels%s",
      n.people, n.devices, n.vehicles, n.labels,
      (#left > 0) and string.format("; %d more handles of the game's were still in the script's tables and are dropped: %s%s", #left, table.concat(named, ", "),
        (#left > #named) and " ..." or "") or ""))
  end
end

function FPF.goneFrame(last)
  local K = FPC.gone
  if not S.gone then return end
  local due = last == true or (S.goneHooks or 0) ~= (S.goneHooksSeen or 0)
  if not due and (S.goneRuns or 0) < K.most then
    local every = (S.clock - (S.goneAt or S.clock) < K.forSeconds) and K.every or K.later
    due = S.clock - (S.goneRunAt or -1e9) >= every
  end
  if not due then return end
  S.goneHooksSeen, S.goneRunAt, S.goneRuns = S.goneHooks or 0, S.clock, (S.goneRuns or 0) + 1
end

FPC.native.fit = { least = 40.0, from = 0.80, to = 1.30 }

function FPF.nativeW(text)
  local F, size = FPF.nativeFont()
  local w = 0.0
  for i = 1, #text do w = w + (F.w[text:byte(i)] or 0.55) end
  return w * size
end

FPF.nativeFont79 = FPF.nativeFont
function FPF.nativeFont()
  local F, size, lh = FPF.nativeFont79()
  local N = PS.nat
  local sig = tostring(N.lang) .. "/" .. tostring(size)
  if N.fitSig ~= sig then
    if N.fitSig ~= nil then
      N.wk = nil
      if N.measure == true then N.measure = nil end
    end
    N.fitSig = sig
  end
  return F, size, lh
end

function FPF.nativeFit(text, w)
  local N, K = PS.nat, FPC.native.fit
  if not N or type(w) ~= "number" or type(text) ~= "string" then return end
  local mine = FPF.nativeW(text) * (N.scale or 1.0)
  if mine < K.least then return end
  local k = w / mine
  if k >= K.from and k <= K.to then
    N.wk = k
    log(string.format("BT's HUD letters: the game's own measure of \"%s\" is %.3f of this script's table - every width is counted with that from now on", text, k))
  else
    log(string.format("BT's HUD letters: the game's own measure of \"%s\" is %.2f of this script's table - that is not believed, the table is used as it is", text, k))
  end
end

FPF.textW79 = FPF.textW
function FPF.textW(text)
  local w = FPF.textW79(text)
  local N = PS.nat
  if P.hudNative and N and N.ready and not N.broken and N.wk then w = w * N.wk end
  return w
end

