function FPF.slotUi()
  local U = PS.slotUi
  if not U then
    U = { ready = false, shown = false, lines = 0 }
    PS.slotUi = U
  end
  return U
end

function FPF.keyPart(raw)
  local K = FPC.slots
  if type(raw) ~= "string" or raw == "" or raw == "?" or raw == "None" or raw:find("^Unknown") then return nil end
  local part = K.keyNames[raw]
  if not part then
    local c, d, f = raw:match("^(%a)$"), raw:match("^(%d)$"), raw:match("^F(%d%d?)$")
    local n, m = raw:match("^NumPad(%d)$"), raw:match("^Mouse(%d)$")
    part = (c and ("kb_" .. c:lower())) or (d and ("kb_" .. d)) or (f and ("kb_f" .. f)) or (n and ("kb_numpad_" .. n)) or (m and ("mouse_" .. m)) or nil
  end
  if part and K.keys[part] then return part end
  return nil
end

function FPF.slotStates(M, V, Q)
  local out = {}
  if M then
    local K = FPC.mtms
    out.missiles = { fill = 1.0 - M.frac, count = math.floor((1.0 - M.frac) * FPF.mtmsSalvo() + 1e-6),
      state = (M.held or (M.queue and #M.queue > 0)) and "active" or (FPF.mtmsDry(M) and "empty" or "ready") }
  end
  if V then
    out.vortex = { fill = 1.0 - V.frac, color = (V.frac < 0.75) and "blue" or ((V.frac < 0.95) and "yellow" or "red"),
      state = V.on and "active" or ((V.frac + FPF.vortexCost() >= 1.0) and "empty" or "ready") }
  end
  if Q then
    local most = FPF.smokeMax()
    out.smoke = { fill = (most > 1) and ((Q.charge >= most) and 1.0 or (Q.charge - math.floor(Q.charge))) or Q.charge,
      count = (most > 1) and math.floor(Q.charge + 1e-6) or nil, state = (Q.charge >= 1.0) and "ready" or "empty" }
  end
  return out
end

function FPF.ink2(W, fn, x, y)
  if not pcall(function() W[fn](W, x, y) end) then W[fn](W, Vector2.new({ X = x, Y = y })) end
end

function FPF.slotsMake(U, root)
  local K = FPC.slots
  local C = K.colors
  local function ref(path)
    local r = path
    pcall(function() r = ResRef.FromName(path) end)
    return r
  end
  local function tint(name)
    local c = C[name]
    return HDRColor.new({ Red = c[1], Green = c[2], Blue = c[3], Alpha = 1.0 })
  end
  local box = inkCanvas.new()
  U.box = box
  box:SetName(CName.new(K.name))
  box:SetAnchor(inkEAnchor.TopLeft)
  FPF.ink2(box, "SetRenderTransformPivot", 0.0, 0.0)
  box:SetVisible(false)
  box:Reparent(root)
  local made = 1
  local function image(name, atlas, part, w, h, x, y, color, opacity)
    local I = inkImage.new()
    I:SetName(CName.new(name))
    I:SetAtlasResource(ref(atlas))
    I:SetTexturePart(CName.new(part))
    I:SetAnchor(inkEAnchor.TopLeft)
    FPF.ink2(I, "SetAnchorPoint", 0.5, 0.5)
    FPF.ink2(I, "SetSize", w, h)
    FPF.ink2(I, "SetTranslation", x, y)
    I:SetTintColor(tint(color))
    I:SetOpacity(opacity)
    I:Reparent(box)
    made = made + 1
    return { w = I, last = { tint = color, opacity = opacity, part = part } }
  end
  local function text(name, size, x, y, color)
    local T = inkText.new()
    T:SetName(CName.new(name))
    T:SetFontFamily(FPC.native.family)
    T:SetFontStyle(CName.new(FPC.native.style))
    T:SetFontSize(size)
    T:SetFitToContent(true)
    pcall(function() T:SetLetterCase(textLetterCase.OriginalCase) end)
    T:SetAnchor(inkEAnchor.TopLeft)
    FPF.ink2(T, "SetAnchorPoint", 0.5, 0.5)
    FPF.ink2(T, "SetTranslation", x, y)
    T:SetTintColor(tint(color))
    T:SetText("")
    T:SetVisible(false)
    T:Reparent(box)
    made = made + 1
    return { w = T, last = { tint = color, visible = false, text = "" } }
  end
  local slots = {}
  for i, name in ipairs(K.order) do
    local I = K.items[name]
    local cx, cy = K.slot[1] * 0.5 + (i - 1) * K.pitch, K.slot[2] * 0.5
    local by, ky = K.slot[2] - K.counterUp, K.slot[2] + K.keyGap + K.key * 0.5
    local Z = {}
    Z.glow = image(name .. "_glow", K.frames, "itemSlot_outerglow", K.glow[1], K.glow[2], cx, cy, "active", 0.0)
    Z.bg = image(name .. "_bg", K.frames, "itemSlot_bg", K.bg[1], K.bg[2], cx, cy, "ground", K.groundOpacity)
    Z.fill = image(name .. "_fill", K.frames, "itemSlot_bg", K.bg[1], K.bg[2], cx, cy, "blue", 0.0)
    FPF.ink2(Z.fill.w, "SetRenderTransformPivot", 0.5, 1.0)
    Z.dec = image(name .. "_dec", K.frames, "itemSlot_dec", K.dec[1], K.dec[2], cx, cy, "blue", K.decOpacity)
    Z.fg = image(name .. "_fg", K.frames, "itemSlot_fg", K.slot[1], K.slot[2], cx, cy, "blue", K.lineOpacity)
    Z.icon = image(name .. "_icon", K.icons, I.part, I.size[1], I.size[2], cx, cy, "white", 1.0)
    Z.badge = image(name .. "_badge", K.frames, "counterLabel", K.counter[1], K.counter[2], cx, by, "blue", 0.0)
    Z.badge.last.wide = K.counter[1]
    Z.count = text(name .. "_count", K.counterFont, cx, by, "black")
    Z.key = image(name .. "_key", K.keysAtlas, "kb_button_square", K.key, K.key, cx, ky, "blue", 0.0)
    Z.keyText = text(name .. "_keytext", K.keyFont, cx, ky, "blue")
    slots[name] = Z
  end
  U.box, U.slots, U.made, U.place, U.keySig = box, slots, made, nil, nil
end

function FPF.slotsPlace(U)
  local K = FPC.slots
  local sw, sh = render.size()
  local layer = (PS.nat and PS.nat.scale) or 1.0
  local k = math.min(sh / 2160.0, sw / 3840.0)
  local wide, high = K.slot[1] + (#K.order - 1) * K.pitch, K.slot[2] + K.keyGap + K.key
  local x = sw - FPF.hudEdge(sw, sh) - (K.right + wide) * k
  local y = sh - (K.bottom + high) * k
  local sig = string.format("%.1f/%.1f/%.4f", x * layer, y * layer, k * layer)
  if U.place == sig then return end
  FPF.ink2(U.box, "SetTranslation", x * layer, y * layer)
  U.box:SetScale(Vector2.new({ X = k * layer, Y = k * layer }))
  U.place, U.at = sig, { x = x, y = y, k = k, wide = wide * k, high = high * k }
  if U.lines < K.lines then
    U.lines = U.lines + 1
    log(string.format("BT's skill slots: their row is %.0f x %.0f px at the lower right - its right end %.0f px from the picture's right edge, the keys' lower edge %.0f px from its bottom (the picture is %d x %d: a unit of the HUD is %.3f px%s)",
      wide * k, high * k, sw - (x + wide * k), K.bottom * k, sw, sh, k, (layer ~= 1.0) and string.format("; the layer counts %.3f units a pixel", layer) or ""))
  end
end

function FPF.slotsApply(U, want)
  local K = FPC.slots
  local C = K.colors
  local function color(Z, name)
    if Z.last.tint ~= name then
      local c = C[name]
      Z.w:SetTintColor(HDRColor.new({ Red = c[1], Green = c[2], Blue = c[3], Alpha = 1.0 }))
      Z.last.tint = name
    end
  end
  local function opacity(Z, v)
    if Z.last.opacity ~= v then
      Z.w:SetOpacity(v)
      Z.last.opacity = v
    end
  end
  local function shown(Z, on)
    if Z.last.visible ~= on then
      Z.w:SetVisible(on)
      Z.last.visible = on
    end
  end
  local function said(Z, s)
    if Z.last.text ~= s then
      Z.w:SetText(s)
      Z.last.text = s
    end
  end
  local keys = {}
  for _, name in ipairs(K.order) do
    local Z, W = U.slots[name], want[name]
    if W then
      local st = W.state or "ready"
      local line = (st == "active") and "active" or ((st == "empty") and "mildRed" or "blue")
      opacity(Z.glow, (st == "active") and 1.0 or 0.0)
      opacity(Z.bg, (st == "empty") and K.emptyOpacity or K.groundOpacity)
      color(Z.dec, line)
      color(Z.fg, line)
      opacity(Z.fg, (st == "ready") and K.lineOpacity or 1.0)
      local f = W.fill
      if f ~= nil and f < K.full then
        local q = math.max(K.fillLeast, math.floor(f * K.fillSteps + 0.5) / K.fillSteps)
        if Z.fill.last.scale ~= q then
          Z.fill.w:SetScale(Vector2.new({ X = 1.0, Y = q }))
          Z.fill.last.scale = q
        end
        color(Z.fill, (st == "empty") and "red" or (W.color or "blue"))
        opacity(Z.fill, K.fillOpacity)
      else
        opacity(Z.fill, 0.0)
      end
      opacity(Z.icon, (st == "empty") and K.iconEmpty or 1.0)
      local n = (st ~= "empty") and W.count or nil
      if n then
        local wide = (n >= 10) and K.counter[1] or K.counterOne
        if Z.badge.last.wide ~= wide then
          FPF.ink2(Z.badge.w, "SetSize", wide, K.counter[2])
          Z.badge.last.wide = wide
        end
        color(Z.badge, line)
        opacity(Z.badge, 1.0)
        said(Z.count, tostring(n))
        shown(Z.count, true)
      else
        opacity(Z.badge, 0.0)
        shown(Z.count, false)
      end
      local raw = (P.keyHints and S.keysOk) and FPF.keyFor(K.items[name].key) or nil
      local part = FPF.keyPart(raw)
      local word = (not part) and FPF.keyShown(raw) or nil
      if part then
        if Z.key.last.part ~= part then
          Z.key.w:SetTexturePart(CName.new(part))
          Z.key.last.part = part
        end
        color(Z.key, line)
        opacity(Z.key, 1.0)
      else
        opacity(Z.key, 0.0)
      end
      if word then
        said(Z.keyText, word)
        color(Z.keyText, line)
        shown(Z.keyText, true)
      else
        shown(Z.keyText, false)
      end
      keys[#keys + 1] = K.items[name].said .. " " .. (part and (tostring(FPF.keyShown(raw)) .. " (the game's picture " .. part .. ")") or (word and (word .. " (as text: the game has no picture of it)") or "no key"))
    end
  end
  local sig = table.concat(keys, ", ")
  if sig ~= U.keySig then
    U.keySig, U.keyLines = sig, (U.keyLines or 0) + 1
    if U.keyLines <= K.lines then log("BT's skill slots, the keys under them (as bound in Mod Settings, Standby for > Keys): " .. sig) end
  end
end

function FPF.slotsAsk(M, V, Q)
  if not P.hudSlots then return false end
  local U = FPF.slotUi()
  if U.broken then return false end
  U.want = FPF.slotStates(M, V, Q)
  if U.ready then return true end
  U.askedAt = U.askedAt or S.clock
  return S.clock - U.askedAt < FPC.slots.wait
end

function FPF.slotsFrame()
  local U = PS.slotUi
  if not U then return end
  local K = FPC.slots
  local want = U.want
  U.want = nil
  if S.gone then
    U.box, U.slots, U.root, U.ready, U.shown, U.place, U.askedAt, U.swept = nil, nil, nil, false, false, nil, nil, nil
    return
  end
  if not P.hudSlots or U.broken then
    if U.box and U.shown then
      pcall(function() U.box:SetVisible(false) end)
      U.shown = false
    end
    return
  end
  local root = FPF.nativeRoot(FPF.nat())
  if U.box then
    local alive = false
    pcall(function() alive = IsDefined(U.box) end)
    if not alive or root ~= U.root then U.box, U.slots, U.root, U.ready, U.shown, U.place = nil, nil, nil, false, false, nil end
  end
  if not U.box then
    if not root then return end
    if not want then return end
    local there = nil
    pcall(function() there = Game.GetResourceDepot():ResourceExists(K.icons) end)
    if there == false then
      U.broken = "the icons' file is not in the game"
      log("BT's skill slots: their icons (" .. K.icons .. ") are NOT in the game - this mod's archive bt7274_ui.archive is not installed. The three rows are drawn, as up to t79")
      return
    end
    local ok, why = pcall(FPF.slotsMake, U, root)
    if not ok then
      local cut = OP77.cutByTimeLimit(why)
      if not cut then U.broken = tostring(why) end
      local half = U.box
      U.box, U.slots, U.ready = nil, nil, false
      if half then pcall(function() root:RemoveChild(half) end) end
      if not cut then log("BT's skill slots could NOT be made as the game's own widgets (" .. U.broken .. ") - the three rows are drawn, as up to t79") end
      return
    end
    U.root, U.ready = root, true
    if U.lines < K.lines then
      U.lines = U.lines + 1
      log(string.format("BT's skill slots are the game's own widgets: %d made on its HUD layer - the frames and the keys' pictures are the game's (new_phone_assets, icons_keyboard), the icons Titanfall's (%s; the game's depot %s)%s",
        U.made, K.icons, (there == true) and "has the file" or "could not be asked", ""))
    end
  end
  local ok, err = pcall(function()
    if want then
      FPF.slotsPlace(U)
      FPF.slotsApply(U, want)
      if not U.shown then
        U.box:SetVisible(true)
        U.shown = true
      end
    elseif U.shown then
      U.box:SetVisible(false)
      U.shown = false
    end
  end)
  if not ok and not OP77.cutByTimeLimit(err) then
    U.broken = tostring(err)
    log("BT's skill slots: the game did not take a call (" .. U.broken .. ") - the three rows are drawn from here on, as up to t79")
    pcall(function() U.box:SetVisible(false) end)
    U.shown = false
  end
end

function FPF.slotsSay()
  local U = PS.slotUi
  if not P.hudSlots then return "switched off: the three rows" end
  if not U then return "not asked for yet (no HUD drawn)" end
  if U.broken then return "not there (" .. U.broken .. "): the three rows" end
  if not U.ready then return "the game's HUD layer is not there yet: the three rows" end
  return string.format("the game's own widgets: %d made, %s", U.made or 0, U.shown and "on the picture" or "hidden")
end

