FPC.ink = { pause = 0.5, lines = 6 }
FPC.native.wait = 0.5
FPF.inkKept = {}

function FPF.inkHeld()
  local N, U = PS.nat, PS.slotUi
  return ((N ~= nil) and (N.root ~= nil or #N.labels > 0)) or ((U ~= nil) and (U.box ~= nil or U.root ~= nil))
end

function FPF.inkDrop(why)
  local N, U = PS.nat, PS.slotUi
  local root = (N and N.root) or (U and U.root)
  local n = 0
  if N then
    for _, L in ipairs(N.labels) do
      if L.w then
        n = n + 1
        if root then pcall(function() root:RemoveChild(L.w) end) end
      end
    end
    N.root, N.labels, N.asked, N.ready, N.rootAt, N.count, N.wantAt = nil, {}, {}, false, nil, 0, nil
  end
  if U then
    if U.box then
      n = n + (U.made or 1)
      if root then pcall(function() root:RemoveChild(U.box) end) end
    end
    U.box, U.slots, U.root, U.ready, U.shown, U.place, U.want, U.askedAt = nil, nil, nil, false, false, nil, nil, nil
  end
  root = nil
  PS.inkDrops = (PS.inkDrops or 0) + 1
  PS.inkGc = { n = 0, cycles = 0, ms = 0.0, widgets = n, why = tostring(why), drop = PS.inkDrops }
  return n
end

function FPF.inkPauseFrame()
  if (S.pauseFor or 0.0) < FPC.ink.pause or not FPF.inkHeld() then return end
  FPF.inkDrop("the game is paused")
end

function FPF.inkKeep()
  local N, U = PS.nat, PS.slotUi
  local kept, n = FPF.inkKept, 0
  local function keep(v)
    if v ~= nil then
      kept[#kept + 1] = v
      n = n + 1
    end
  end
  if N then
    keep(N.root)
    for _, L in ipairs(N.labels) do keep(L.w) end
    N.root, N.labels, N.asked, N.ready, N.rootAt, N.count, N.wantAt = nil, {}, {}, false, nil, 0, nil
  end
  if U then
    keep(U.root)
    keep(U.box)
    for _, Z in pairs(U.slots or {}) do
      for _, W in pairs(Z) do keep(W.w) end
    end
    U.box, U.slots, U.root, U.ready, U.shown, U.place, U.want, U.askedAt, U.swept = nil, nil, nil, false, false, nil, nil, nil, nil
  end
  return n
end

FPF.letGo80 = FPF.letGo
function FPF.letGo()
  local n = FPF.inkKeep()
  if n > 0 then
    PS.inkKeeps = (PS.inkKeeps or 0) + 1
    if PS.inkKeeps <= FPC.ink.lines then
      log(string.format("SESSION END: %d handles of the HUD layer's (its window, this script's widgets on it) were still held - the game was not paused before the session ended. They are kept as they are, for good (%d in all); nothing is asked of them",
        n, #FPF.inkKept))
    end
  end
  return FPF.letGo80()
end

function FPF.label(dl, x, y, col, text, align, ax)
  if P.hudNative then
    local N = FPF.nat()
    if not N.broken then
      if N.ready then
        if #N.asked < FPC.native.most then
          N.asked[#N.asked + 1] = { x = align and ax or x, y = y, col = col, text = text, align = align }
          return
        end
      else
        N.wantAt = N.wantAt or S.clock
        if S.clock - N.wantAt < FPC.native.wait then return end
      end
    end
  end
  render.text(x, y, col, text)
end

FPC.sceneSwitch = { before = 2, after = 6, lines = 16, each = 2 }
function FPF.switchWatch()
  local K = FPC.sceneSwitch
  if (PS.swLines or 0) >= K.lines and not PS.swWatch then return end
  if PS.swAt == S.clock then return end
  PS.swAt = S.clock
  local now = { clip = PS.sceneClip, t = PS.sceneTime, w = PS.sceneW or 0.0 }
  local H = PS.swHist or {}
  local last = H[#H]
  local W = PS.swWatch
  local key = nil
  if not W and last and now.w >= 0.99 and last.w >= 0.99 and last.clip ~= now.clip and (PS.swLines or 0) < K.lines then
    key = tostring(last.clip) .. ">" .. tostring(now.clip)
    PS.swSeen = PS.swSeen or {}
    if (PS.swSeen[key] or 0) >= K.each then key = nil end
  end
  if (W or key) and PS.ent and not PS.warm then
    pcall(function()
      local p = slotWorld("hip")
      if p then now.hip = p.z - PS.z end
    end)
  end
  if W then
    W.rows[#W.rows + 1] = now
    if #W.rows >= K.after then
      PS.swWatch = nil
      local function row(r) return string.format("%d@%.3f%s", r.clip or 0, r.t or 0.0, r.hip and string.format(" %.2f m", r.hip) or "") end
      local a, b = {}, {}
      for i, r in ipairs(W.before) do a[i] = row(r) end
      for i, r in ipairs(W.rows) do b[i] = row(r) end
      log(string.format("SCENE SWITCH %d (clip@time as sent, and from the change on the hip's height read back in that frame): before %s | from the change on %s",
        W.n, table.concat(a, ", "), table.concat(b, ", ")))
    end
  elseif key then
    PS.swSeen[key] = (PS.swSeen[key] or 0) + 1
    PS.swLines = (PS.swLines or 0) + 1
    local before = {}
    for i, r in ipairs(H) do before[i] = r end
    PS.swWatch = { n = PS.swLines, before = before, rows = { now } }
  end
  H[#H + 1] = now
  if #H > K.before then table.remove(H, 1) end
  PS.swHist = H
end

FPF.labelsFrame80 = FPF.labelsFrame
