      return
    end
    local wanted = ((N ~= nil) and (#N.asked > 0 or N.wantAt ~= nil)) or ((U ~= nil) and U.want ~= nil)
    if not wanted and not FPF.inkHeld() then return end
  end
  FPF.labelsFrame80()
  N = PS.nat
  if N and N.ready then N.wantAt = nil end
end

