  S.endMenuSeen = (S.endMenuSeen or 0) + 1
  if S.endMenuSeen <= FPC.ink.lines then
    log(string.format("%s is open (a session can end from it): %s", what,
      FPF.inkHeld() and "this script's widgets on the HUD layer are taken off it in half a second" or "nothing of the HUD layer's is held"))
  end
