FPC.aiDash = { first = { 2.5, 5.0 }, every = { 7.0, 12.0 }, hit = { 4.0, 6.5 }, hitShare = 0.006, hitIn = 1.0, seen = 0.6,
  far = 40.0, farAt = 0.6, reach = 9.0, vGap = 5.0, drop = 1.2, again = 1.0, lines = 12 }
P.aiDash = true

function FPF.aiDashGap(pair)
  return pair[1] + math.random() * (pair[2] - pair[1])
end

function FPF.aiDashFree(B, dx, dy)
  local K = FPC.aiDash
  if wallAhead(PS.x, PS.y, PS.z, dx, dy, K.reach) then return false, "the world's fixed parts" end
  local straight = P.fightStraight
  P.fightStraight = false
  local ok, blocked = pcall(FPF.pathBlocked, PS.x, PS.y, PS.z, dx, dy, K.reach)
  P.fightStraight = straight
  if not ok then error(blocked, 0) end
  if blocked then return false, "a vehicle, or somebody who is no foe" end
  local vx, vy = (B.vx or PS.x) - PS.x, (B.vy or PS.y) - PS.y
  local along = clamp(vx * dx + vy * dy, 0.0, K.reach)
  if math.sqrt((vx - dx * along) ^ 2 + (vy - dy * along) ^ 2) < K.vGap and math.abs((B.vz or PS.z) - PS.z) < 8.0 then return false, "V" end
  for _, d in ipairs({ K.reach * 0.5, K.reach }) do
    local g = groundZ(PS.x + dx * d, PS.y + dy * d, PS.z + 1.0)
    if g == nil then return false, "no ground" end
    if math.abs(g - PS.z) > K.drop then return false, string.format("the ground %+.1f m against where it stands", g - PS.z) end
  end
  return true
end

function FPF.aiDash(B, dt, T)
  local K = FPC.aiDash
  local D = B.dash
  if not D then
    D = { n = 0, side = 0, ahead = 0, hit = 0, none = 0, refused = 0, heat = 0.0, lines = 0 }
    B.dash = D
  end
  local H = PS.hp
  if H and H.taken then
    D.heat = D.heat * math.exp(-dt / K.hitIn) + math.max(H.taken - (D.taken or H.taken), 0.0)
    D.taken = H.taken
  end
  if D.from and (PS.dashT == nil or PS.dashT >= TF.dodgeTime) then
    if D.n <= K.lines then
      log(string.format("BT on its own: its dash carried it %.1f m%s", math.sqrt((PS.x - D.from.x) ^ 2 + (PS.y - D.from.y) ^ 2),
        (PS.blocked > D.from.blocked) and " - the world's fixed parts stopped it" or ""))
    end
    D.from = nil
  end
  if not P.aiDash then return nil end
  if not T then
    if D.at and not FPF.fightOn() then D.at, D.hitAt = nil, nil end
    return nil
  end
  if D.at == nil then D.at, D.hitAt = S.clock + FPF.aiDashGap(K.first), S.clock + K.first[1] * 0.5 end
  local hot = H ~= nil and D.heat >= K.hitShare * (FPC.health.segment * FPC.health.segments + FPC.health.shield)
  if not (S.clock >= D.at or (hot and S.clock >= D.hitAt)) or S.clock < (D.lookAt or 0.0) then return nil end
  if P.hold or B.off or P.peace or B.board or B.leap or B.leapOn or PS.jump or PS.dashT ~= nil or PS.punch or PS.lunge or FPF.aiBusy()
      or FPF.questHeld() ~= nil or S.clock - (T.seenAt or -10.0) > K.seen or PS.power < TF.dodgeDrain
      or PS.sinceDash < TF.dodgeTime + TF.dodgeInterval then
    return nil
  end
  local tx, ty = T.x - PS.x, T.y - PS.y
  local tn = math.sqrt(tx * tx + ty * ty)
  if tn < 0.5 then return nil end
  tx, ty = tx / tn, ty / tn
  local lx, ly = -ty, tx
  local first = (math.random() < 0.5) and 1.0 or -1.0
  local name = { [1.0] = "left", [-1.0] = "right" }
  local ways = {}
  if tn > K.far and math.random() < K.farAt then
    ways[#ways + 1] = { (tx + lx * first) * 0.7071, (ty + ly * first) * 0.7071, "at its foe, half to its " .. name[first], "ahead" }
    ways[#ways + 1] = { tx, ty, "straight at its foe", "ahead" }
  end
  ways[#ways + 1] = { lx * first, ly * first, "to its " .. name[first], "side" }
  ways[#ways + 1] = { -lx * first, -ly * first, "to its " .. name[-first], "side" }
  local why = {}
  for _, w in ipairs(ways) do
    local free, what = FPF.aiDashFree(B, w[1], w[2])
    if free then
      local r = math.rad(B.yaw)
      local cfx, cfy = -math.sin(r), math.cos(r)
      D.want = { x = w[1], y = w[2], name = w[3], kind = w[4], hot = hot and S.clock < D.at, dist = tn }
      return w[1] * cfx + w[2] * cfy, w[1] * cfy - w[2] * cfx
    end
    why[#why + 1] = w[3] .. ": " .. tostring(what)
  end
  D.none, D.lookAt = D.none + 1, S.clock + K.again
  if D.none <= 4 then
    log(string.format("BT on its own: a dash is due and no way is free (%s) - it looks again in %.0f s", table.concat(why, "; "), K.again))
  end
  return nil
end

function FPF.aiDashBegun(B, begun)
  local K, D = FPC.aiDash, B.dash
  local W = D.want or {}
  D.want = nil
  if not begun then
    D.refused, D.lookAt = D.refused + 1, S.clock + K.again
    return
  end
  D.n = D.n + 1
  if W.kind == "ahead" then D.ahead = D.ahead + 1 else D.side = D.side + 1 end
  if W.hot then D.hit = D.hit + 1 end
  D.at, D.hitAt, D.heat = S.clock + FPF.aiDashGap(K.every), S.clock + FPF.aiDashGap(K.hit), 0.0
  D.from = { x = PS.dashFrom and PS.dashFrom.x or PS.x, y = PS.dashFrom and PS.dashFrom.y or PS.y, blocked = PS.blocked }
  guard("effects of a dash", FPF.fxDash)
  PS.aiGain = clamp(FPC.ai.loud * (1.0 - (B.dist or 0.0) / FPC.ai.far), FPC.ai.quiet, FPC.ai.loud)
  local ok, err = pcall(FPF.dashSound)
  PS.aiGain = nil
  if not ok then once("aidashsound" .. tostring(err), "BT on its own: its dash's sound could NOT be played (" .. tostring(err) .. ")") end
  if D.n <= K.lines then
    log(string.format("BT on its own: it dashes %s (%s; its foe is %.0f m away, V %.0f m; its power is at %.0f) - its next in %.1f s, or from %.1f s on while it is being hit",
      tostring(W.name), W.hot and "it is being hit" or "it was time", W.dist or -1.0, B.dist or -1.0, PS.power, D.at - S.clock, D.hitAt - S.clock))
  end
end

function FPF.dashDrop()
  if PS.dashT ~= nil or (PS.dash or 0.0) > 0.0 then PS.dashT, PS.dash, PS.dashClock = nil, 0.0, 0.0 end
end
