  FPF.dashDrop()
  return FPF.actFrame82(dt)
end
function FPF.kneelFrame(dt)
  FPF.dashDrop()
  return FPF.kneelFrame82(dt)
end

FPF.buddyBoard82 = FPF.buddyBoard
function FPF.buddyBoard(key, demo)
  local B = PS.buddy
  if B and B.state == "active" and PS.dashT ~= nil then
    if not B.board then
      B.board = { key = key, demo = demo }
      log("EMBARK asked while BT is in a dash: it starts when the dash is over")
    end
    return false
  end
  return FPF.buddyBoard82(key, demo)
end

FPF.buddyEnd82 = FPF.buddyEnd
function FPF.buddyEnd(why)
  local B = PS.buddy
  local D = B and B.dash
  if D and (D.n > 0 or D.none > 0 or D.refused > 0) then
    log(string.format("BT on its own, its dashes: %d (%d to a side, %d at its foe; %d of them while it was being hit); due with no way free %d times, refused by its power %d times",
      D.n, D.side, D.ahead, D.hit, D.none, D.refused))
  end
  if B then FPF.dashDrop() end
  return FPF.buddyEnd82(why)
end

FPC.ai.punchClose, FPC.ai.punchFirst, FPC.ai.punchEvery, FPC.ai.punchForget = 5.5, { 2.0, 5.0 }, { 8.0, 14.0 }, 5.0
P.aiPunchSome = true

function FPF.aiPunchZone()
  return P.aiPunchSome and FPC.ai.punchClose or FPC.ai.punchReach
end

function FPF.aiPunchDue(A, T)
  local K = FPC.ai
  if not P.aiPunchSome then
    A.punchWhy = "within its reach"
    return true
  end
  local N = A.punchNear
  if N == nil or S.clock - N.seen > K.punchForget then
    N = { due = S.clock + FPF.aiDashGap(K.punchFirst), n = 0 }
    A.punchNear = N
  end
  N.seen = S.clock
  if T.dist <= K.punchClose then
    A.punchWhy = "at its feet"
    return true
  end
  if S.clock < N.due then return false end
  A.punchWhy = "within its reach - now and then"
  return true
end

function FPF.aiPunched(A)
  local K = FPC.ai
  local N = A.punchNear or { n = 0 }
  N.due, N.seen, N.n = S.clock + FPF.aiDashGap(K.punchEvery), S.clock, (N.n or 0) + 1
  A.punchNear = N
  if A.punchWhy == "at its feet" then A.punchFeet = (A.punchFeet or 0) + 1 elseif P.aiPunchSome then A.punchSome = (A.punchSome or 0) + 1 end
end

function FPF.bodyAway()
  PF.bodyHold = nil
  local off = FPF.body(false)
  PS.sunk = P.sink or off < #FPC.body
  FPF.lower(not PS.sunk)
  if PF.sunkSaid ~= PS.sunk then
    PF.sunkSaid = PS.sunk
    log(string.format("FIRST PERSON: %d of BT's %d outside meshes say they are switched off%s", off, #FPC.body,
      PS.sunk and (P.sink and "; the outside body is put under the ground (chosen in the overlay)"
        or " - the outside body is put under the ground instead") or ""))
  end
end

function FPF.revealCut(sc)
  FPF.bodyAway()
  if PS.ent and IsDefined(PS.ent) then pcall(FPF.placeBt) end
  if sc.reveal and PF.wallOn then PF.wallT = FPC.reveal.hold - FPC.reveal.holdPre end
  FPF.raise(sc.reveal and (FPC.reveal.holdPre + FP.wall.first + 0.25) or 0.0)
  PF.cuts = (PF.cuts or 0) + 1
  if PF.cuts <= 4 then
    log(string.format("FIRST PERSON: the %.2f s behind BT's shut hatch are over - its outside body goes, the camera is in its eye%s", FPC.reveal.pre,
      sc.reveal and string.format("; the screens' tiles turn over %.2f s from now", FPC.reveal.holdPre + FP.wall.first) or ""))
  end
end

FPF.show88 = FPF.show
function FPF.show(on)
  if not on then PF.bodyHold = nil end
  return FPF.show88(on)
end

