function FPF.dashMul()
  return (S.driving and S.pilot) and P.dashScale or 1.0
end

function FPF.jumpUp()
  local K = FPC.jump
  local k = (S.driving and S.pilot) and P.jumpScale or 1.0
  if k == 1.0 then return K.speed end
  local a = 0.5 * K.ramp * K.gravity
  return -a + math.sqrt(a * a + 2.0 * K.gravity * K.top * k)
end

function FPF.magSize()
  return math.max(1, math.floor(XO16.clip * P.magScale + 0.5))
end

function FPF.damageFlats()
  local k, n, all, bad = P.damageScale, 0, 0, nil
  for _, R in ipairs(FPC.tune.damage) do
    for i, kind in ipairs(FPC.tune.kinds) do
      local v = R[2][i] * k * ((kind == "boss") and P.bossMul or 1.0)
      local ok, err = pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end)
      all = all + 1
      if ok then n = n + 1 else bad = tostring(err) end
    end
    local ok, err = pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * k) end)
    all = all + 1
    if ok then n = n + 1 else bad = tostring(err) end
    pcall(function() TweakDB:Update(R[1]) end)
  end
  log(string.format("damage of BT's weapons: %.2f times the tweak file's - %d of %d values written%s (an XO-16 round now takes %.0f %% of an ordinary foe's health, a missile %.0f %%)",
    k, n, all, bad and (" (" .. bad .. ")") or "", FPC.tune.damage[1][2][3] * k * 100.0, FPC.tune.damage[4][2][3] * k * 100.0))
end

function FPF.tuneFrame()
  if S.clock < (S.tuneAt or 0.0) then return end
  S.tuneAt = S.clock + FPC.tune.every
  local sys = nil
  pcall(function() sys = FPF.keysSystem() end)
  if not sys then return end
  S.tuneSeen = S.tuneSeen or {}
  local first, read = false, 0
  for _, R in ipairs(FPC.tune.fields) do
    local k, v = R[1], nil
    pcall(function() v = sys[k] end)
    if type(v) == "number" and v == v then
      read = read + 1
      if v ~= S.tuneSeen[k] then
        if S.tuneSeen[k] == nil then first = true else log(string.format("Mod Settings: %s = %.2f (moved there)", k, clamp(v, R[2], R[3]))) end
        S.tuneSeen[k] = v
        local was = P[k]
        P[k] = clamp(v, R[2], R[3])
        if k == "damageScale" and P[k] ~= was then guard("the damage of BT's weapons", FPF.damageFlats) end
      end
    end
  end
  if first then
    log(string.format("Mod Settings, tuning (%d of %d values read): dash x %.2f, jump x %.2f, damage x %.2f, magazine x %.2f (%d rounds); a controller's right stick turns the view %.0f degrees a second",
      read, #FPC.tune.fields, P.dashScale, P.jumpScale, P.damageScale, P.magScale, FPF.magSize(), P.padLook))
  end
  local pad = nil
  pcall(function() pad = sys.lastPad end)
  if type(pad) == "boolean" and pad ~= S.padLast then
    S.padLast, S.padNames = pad, nil
    S.padSaid = (S.padSaid or 0) + 1
    if S.padSaid <= 4 then log(pad and "the last key came from a controller: its buttons are named on the picture" or "the last key came from the keyboard or the mouse: their keys are named on the picture") end
  end
end

FPC.pad = { pitch = 0.65, soft = 0.35, home = 0.8,
  fields = { embarkKey = "embarkPad", missileKey = "missilePad", vortexKey = "vortexPad", smokeKey = "smokePad", jumpKey = "jumpPad", dashKey = "dashPad",
    punchKey = "punchPad", viewKey = "viewPad", shoulderKey = "shoulderPad", coreKey = "corePad" } }

function FPF.padFrame(dt)
  local at = S.padCmd
  if at and S.clock - at >= FPC.pad.home then
    S.padCmd = false
    if not S.driving and not S.gone then
      log(string.format("the controller's command buttons kept down %.1f s: BT is sent home", FPC.pad.home))
      guard("BT is sent home", FPF.homeStart, "the controller")
    end
  end
  if not S.driving or S.overlay then
    S.padX, S.padY = 0.0, 0.0
    return
  end
  local x, y = S.padX or 0.0, S.padY or 0.0
  if x == 0.0 and y == 0.0 then return end
  local K = FPC.pad
  local zoom = 1.0 - (1.0 - ZOOM.fov) * (S.pilot and PS.zoomW or 0.0)
  local rate = P.padLook * (dt or 0.0) * zoom
  S.yaw = S.yaw - x * (K.soft + (1.0 - K.soft) * math.abs(x)) * rate
  S.pitch = clamp(S.pitch + y * (K.soft + (1.0 - K.soft) * math.abs(y)) * rate * K.pitch, -PITCH_MAX, PITCH_MAX)
  once("padlook", string.format("a controller's right stick turns the view (the game's actions CameraX / CameraY): %.0f degrees a second at full tilt", P.padLook))
end

function FPF.padCmdTap()
  if S.gone or S.driving then return end
  if PS.ent or PS.asked or PS.act then
    FPF.orderSet(FPF.orderNext(), "the controller")
  else
    guard("the call", FPF.callBt, "the controller")
  end
end

function FPF.keyFor(field)
  local name = FPF.keyName(field)
  if not S.keysOk or not S.padLast then return name end
  local N = S.padNames
  if not N or S.clock - N.at > 4.0 then
    N = { at = S.clock }
    pcall(function()
      local sys = Game.GetScriptableSystemsContainer():Get(CName.new("BT7274.BT7274Keys"))
      for _, k in pairs(FPC.pad.fields) do N[k] = EnumName("EInputKey", sys[k]):match("IK_([%w_]+)") end
    end)
    S.padNames = N
  end
  local pad = N[FPC.pad.fields[field] or ""]
  if pad and pad ~= "None" then return pad end
  return name
end

function FPF.keyWord(field)
  local raw = FPF.keyFor(field)
  return FPF.keyShown(raw) or raw
end

function FPF.promptKey()
  if not S.keysOk then return true end
  if S.padLast then return FPF.keyFor("embarkKey") == "Pad_X_SQUARE" end
  return FPF.keyName("embarkKey") == "F"
end

