function FPF.perk(id)
  if not P.perks then return FPC.perk.legacy[id] or 0 end
  return (S.perk and S.perk[id]) or 0
end

function FPF.perkValue(id)
  local V = FPC.perk.values[id]
  return V[math.min(FPF.perk(id), #V - 1) + 1]
end

function FPF.perkFrame()
  if not P.perks or S.clock < (S.perkAt or 0.0) then return end
  local K = FPC.perk
  S.perkAt = S.clock + K.every
  local was, now, said = S.perk, {}, {}
  for _, id in ipairs(K.order) do
    local v = math.max(0, math.min(math.floor(FPF.factGet(K.fact .. id) + 0.5), K.max[id]))
    now[id] = v
    if v > 0 or (was and was[id] ~= v) then said[#said + 1] = string.format("%s %d/%d", K.names[id], v, K.max[id]) end
  end
  local changed = was == nil
  for _, id in ipairs(K.order) do
    if was and was[id] ~= now[id] then changed = true end
  end
  if not changed then return end
  S.perk = now
  S.perkLines = (S.perkLines or 0) + 1
  if S.perkLines <= K.lines then
    log(string.format("the Titan loadout (the server's policy)%s: %s - BT has %.0f dash power (%.1f dashes)%s, %d missiles (one back in %.2f s), a shield of %.1f s that %s, %d charge%s of smoke, %d rounds in the XO-16 (%.2f s to reload, its rounds x %.2f)%s",
      was and " changed" or "", (#said > 0) and table.concat(said, ", ") or "nothing enabled", FPF.dashMax(), FPF.dashMax() / TF.dodgeDrain,
      (FPF.perk("airdash") > 0) and " - in the air too" or " - not in the air", FPF.mtmsSalvo(), FPF.mtmsRecharge() / FPF.mtmsSalvo(), FPF.vortexTime(),
      (FPF.perk("vortexthrow") > 0) and "throws back" or "only catches", FPF.smokeMax(), (FPF.smokeMax() > 1) and "s" or "", FPF.magSize(), FPF.reloadTime(),
      FPF.perkValue("xodamage"), ((FPF.perk("jumpgauge") > 0) and string.format("; the jump's key held keeps the jets on (a gauge of %.1f s)", FPF.gaugeMax()) or "")
      .. ((FPF.perk("skate") > 0) and "; it skates out of a dash" or "") .. ((FPF.perk("dashregen") > 0) and string.format("; its dash power comes back %.1f times as fast", FPF.perkValue("dashregen")) or "")
      .. ((FPF.perk("incendiary") > 0) and string.format("; INCENDIARY MISSILES %d", FPF.perk("incendiary")) or "") .. ((FPF.perk("gas") > 0) and string.format("; GAS MISSILES %d", FPF.perk("gas")) or "")
      .. string.format("; the gun equipped: %s", FPF.gunNamed())))
  end
  if PS.power and PS.power > FPF.dashMax() then PS.power = FPF.dashMax() end
  local Q = PS.esmoke
  if Q and Q.charge > FPF.smokeMax() then Q.charge = FPF.smokeMax() end
  local G = PS.gun
  if G and G.ammo and G.ammo > FPF.magSize() then G.ammo = FPF.magSize() end
  if PS.jet and PS.jet.fuel > FPF.gaugeMax() then PS.jet.fuel = FPF.gaugeMax() end
  if (was and was.xodamage or 0) ~= now.xodamage then guard("the damage of BT's weapons", FPF.damageFlats) end
end

function FPF.dashMax()
  return FPF.perkValue("dashcap")
end

FPF.dashMul91 = FPF.dashMul
function FPF.dashMul()
  return FPF.dashMul91() * FPF.perkValue("dashdist")
end

function FPF.gaugeMax()
  return FPC.perk.gauge.time * FPF.perkValue("jumpcap")
end

function FPF.jumpHeld()
  if S.keyHeld and S.keyHeld.jump then return true end
  local at = S.jumpAct
  if not at or S.clock - at > 10.0 then return false end
  return P.spaceJump and (not S.keysOk or FPF.keyName("jumpKey") == "Space")
end

function FPF.jetThrust(J, vz, dt)
  if J.pound then return -FPC.perk.pound.speed end
  local T = PS.jet
  if not T then return vz end
  local K = FPC.perk.gauge
  if T.dry and not FPF.jumpHeld() then T.dry = nil end
  local on = J.pushed and T.fuel > 0.0 and not T.dry and S.driving and S.pilot and not PS.auto and FPF.jumpHeld()
  if not on then
    if T.on then
      T.on = false
      if T.burns <= FPC.jump.lines then
        log(string.format("JUMP %d: the jets were held on for %.2f s (VTOL JETS, the jump's key down) - %+.1f m meanwhile; the gauge has %.2f of %.2f s left",
          J.n or 0, S.clock - T.burnAt, PS.z - T.burnZ, T.fuel, FPF.gaugeMax()))
      end
    end
    return vz
  end
  if not T.on then
    T.on, T.burns, T.burnAt, T.burnZ = true, T.burns + 1, S.clock, PS.z
    if J.air > 0.4 then
      pcall(FPF.thruster, true, "the jump's jets, held on")
      pcall(FPF.jumpSound, "start")
      T.fxAt = S.clock
    else
      T.fxAt = S.clock + FPC.jump.jetFor * 0.8
    end
  end
  T.fuel = math.max(0.0, T.fuel - dt)
  if T.fuel <= 0.0 then T.dry = true end
  if vz < K.climb then vz = math.min(K.climb, (J.vz or vz) + K.lift * dt) end
  if S.clock >= T.fxAt then
    T.fxAt = S.clock + FPC.jump.jetFor
    pcall(FPF.jetBurst)
  end
  return vz
end

function FPF.jetBurst()
  local path = FPF.fxPath("dash")
  if path and not PF.shown and slotWorld(FPC.ports.ahead[1]) ~= nil then
    local T, K = FPC.jet, FPC.jump
    FPF.fxTrain(path, FPC.ports.ahead, K.jetFor, T.every, T.life, PS.yaw + 180.0, K.jetPitch, true, T.gap)
  end
end

function FPF.jetFrame(dt)
  if FPF.perk("jumpgauge") < 1 then
    PS.jet = nil
    return
  end
  local K, full = FPC.perk.gauge, FPF.gaugeMax()
  PS.jetCap = full
  local T = PS.jet
  if not T then
    T = { fuel = full, since = 10.0, on = false, burns = 0 }
    PS.jet = T
  end
  if T.on and not (PS.jump and PS.jump.stage == "air" and S.driving) then T.on = false end
  if T.dry and not FPF.jumpHeld() then T.dry = nil end
  if T.on then
    T.since = 0.0
    return
  end
  T.since = T.since + (dt or 0.0)
  if T.fuel > full then
    T.fuel = full
  elseif T.since >= K.delay and T.fuel < full then
    T.fuel = math.min(full, T.fuel + (dt or 0.0) * K.time / (K.recharge * FPF.perkValue("jumpcharge")))
  end
end

function FPF.gaugeHud(dl, cx, cy, white, amber)
  local T = PS.jet
  if not T then return end
  local full = FPF.gaugeMax()
  if T.fuel < full - 0.001 or T.on then T.hud = S.clock + 0.6 end
  if not (P.dashAlways or S.clock < (T.hud or 0.0)) then return end
  local barW = 94.0 * full / FPC.perk.gauge.time
  local y = cy + math.max(86, 38 + 2 * FPF.lineH()) + math.max(16, FPF.lineH() + 4)
  local x0 = cx - barW * 0.5
  local fill = clamp(T.fuel / full, 0.0, 1.0)
  render.line(x0, y, x0 + barW, y, GetColorU32(0.0, 0.0, 0.0, 0.5), 7)
  if fill > 0 then render.line(x0, y, x0 + barW * fill, y, (fill >= 1.0) and white or amber, 5) end
  local text = "JETS" .. FPF.keyHint("jumpKey")
  FPF.label(dl, math.min(x0 - 44, x0 - FPC.keyHints.dash - FPF.textW(text)), y - 8, white, text, "r", x0 - FPC.keyHints.dash)
end

function FPF.mtmsSalvo()
  return FPF.perkValue("rocketcap")
end

function FPF.mtmsRecharge()
  return FPF.mtmsSalvo() * FPC.perk.rocketEach * FPF.perkValue("rocketcd")
end

function FPF.vortexTime()
  return FPC.vortex.time * FPF.perkValue("vortexcap")
end

function FPF.vortexRecharge()
  return FPC.vortex.recharge * FPF.perkValue("vortexcap") * FPF.perkValue("vortexcd")
end

function FPF.vortexCost()
  return FPC.vortex.cost / FPF.perkValue("vortexcap")
end

function FPF.smokeMax()
  return FPF.perkValue("smokestack")
end

function FPF.smokeRecharge()
  return FPC.esmoke.recharge * FPF.perkValue("smokecd")
end

function FPF.magSize()
  return math.max(1, math.floor(FPF.perkValue("xoammo") * P.magScale + 0.5))
end

function FPF.reloadTime()
  return XO16.reload * FPF.perkValue("xoreload")
end

function FPF.reloadRate()
  return 1.0 / FPF.perkValue("xoreload")
end

function FPF.damageFlats()
  local k, xo, n, all, bad = P.damageScale, FPF.perkValue("xodamage"), 0, 0, nil
  for _, R in ipairs(FPC.tune.damage) do
    local m = k * ((R[1] == "Attacks.BT7274_XO16_Hit") and xo or 1.0)
    for i, kind in ipairs(FPC.tune.kinds) do
      local v = R[2][i] * m * ((kind == "boss") and P.bossMul or 1.0)
      local ok, err = pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end)
      all = all + 1
      if ok then n = n + 1 else bad = tostring(err) end
    end
    local ok, err = pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * m) end)
    all = all + 1
    if ok then n = n + 1 else bad = tostring(err) end
    pcall(function() TweakDB:Update(R[1]) end)
  end
  log(string.format("damage of BT's weapons: %.2f times the tweak file's - %d of %d values written%s (an XO-16 round now takes %.0f %% of an ordinary foe's health, a missile %.0f %%)%s",
    k, n, all, bad and (" (" .. bad .. ")") or "", FPC.tune.damage[1][2][3] * k * xo * 100.0, FPC.tune.damage[4][2][3] * k * 100.0,
    (xo ~= 1.0) and string.format("; the XO-16's rounds x %.2f of that (the Titan loadout's HEAVY ROUNDS)", xo) or ""))
end

function FPF.mtmsDry(M)
  if not P.perks then return M.frac > 1.0 - FPC.mtms.least + 1e-6 end
  return (1.0 - M.frac) * FPF.mtmsSalvo() < 1.0 - 1e-6
end

function FPF.mtmsCanGuard(M)
  if not P.perks then return M.frac <= 1.0 - FPC.mtms.least - 0.01 end
  return not FPF.mtmsDry(M)
end

function FPF.vortexSiphon(V, n)
  if n <= 0 or FPF.perk("vortexthrow") < 2 then return end
  local H = PS.hp
  if not H or H.doomed or H.gone then return end
  local was = H.shield
  H.shield = math.min(FPC.health.shield, H.shield + n * FPC.perk.siphon)
  V.siphoned = (V.siphoned or 0) + (H.shield - was)
  if H.shield > was and (V.siphonLines or 0) < 3 then
    V.siphonLines = (V.siphonLines or 0) + 1
    log(string.format("VORTEX ENERGY SIPHON: %d rounds caught - BT's shield %.0f -> %.0f of %.0f", n, was, H.shield, FPC.health.shield))
  end
end

function FPF.poundStart()
  local J = PS.jump
  if not J or J.pound or J.stage ~= "air" or FPF.perk("jump") < 1 then return false end
  if PS.z - (J.floor or PS.z) < FPC.perk.pound.least then return false end
  J.pound, J.pushed, J.poundAt = true, true, S.clock
  if PS.jet then PS.jet.on = false end
  if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then PS.dashT = TF.dodgeTime end
  pcall(FPF.dashSound)
  PS.pounds = (PS.pounds or 0) + 1
  if PS.pounds <= 8 then
    log(string.format("GROUND POUND %d: the punch key in the air - BT comes down from %.1f m over the ground at %.0f m/s", PS.pounds,
      PS.z - (J.floor or PS.z), FPC.perk.pound.speed))
  end
  return true
end

FPF.slam92 = FPF.slam
function FPF.slam(J)
  if not (J and J.pound) then return FPF.slam92(J) end
  local K, G = FPC.slam, FPC.perk.pound
  local was = { K.from, K.least, K.down, K.reach, K.power, K.ring, K.puffs }
  K.from, K.least, K.down, K.reach, K.power, K.ring = 0.0, 0.0, K.down * G.wide, K.reach * G.wide, K.power * G.push, K.ring * G.wide
  K.puffs = math.floor(was[7] * G.wide + 0.5)
  local ok, r = pcall(FPF.slam92, J)
  K.from, K.least, K.down, K.reach, K.power, K.ring, K.puffs = was[1], was[2], was[3], was[4], was[5], was[6], was[7]
  if not ok then error(r, 0) end
  if (PS.pounds or 0) <= 8 then
    log(string.format("GROUND POUND %d: the landing's shock %.1f times as wide (%.1f m) and %.1f times as hard", PS.pounds or 0, G.wide, K.reach * G.wide, G.push))
  end
  return r
end

FPF.health92 = FPF.health
function FPF.health(dt, alone)
  local H = PS.hp
  if H and FPF.perk("dash") > 0 and PS.dashT ~= nil and PS.dashT < TF.dodgeTime + FPC.perk.phase.grace then
    local n = math.max(H.pend.a, H.pend.b)
    if n > 0 then
      PS.phased = (PS.phased or 0) + 1
      if PS.phased <= 6 then log(string.format("PHASE DASH: a hit of %.0f points goes through BT in its dash - nothing is taken", n)) end
    end
    H.pend.a, H.pend.b, H.bigV = 0.0, 0.0, nil
  end
  return FPF.health92(dt, alone)
end

function FPF.gunSpin(G, dt, firing)
  local A = FPC.perk.accel
  if firing and G.ammo > 0 and G.reloadT == nil then
    G.spin = math.min(1.0, (G.spin or 0.0) + dt / A.spin)
  else
    G.spin = math.max(0.0, (G.spin or 0.0) - dt / A.fall)
  end
end

function FPF.gunRate()
  local r = XO16.rate
  if FPF.perk("xo16") > 0 then r = r * (1.0 + (FPC.perk.accel.most - 1.0) * ((PS.gun and PS.gun.spin) or 0.0)) end
  if FPF.coreOn() then r = r * FPC.perk.core.rate end
  return r
end

function FPF.coreMax()
  local lv = FPF.perk("burstcore")
  if lv < 1 then return 0.0 end
  return FPC.perk.core.full * ((lv >= 3) and FPC.perk.core.big or 1.0)
end

function FPF.coreShot()
  local K = FPC.perk.core
  if FPF.perk("burstcore") >= 3 then return K.full * K.big * 0.5, K.time * K.big * 0.5 end
  return K.full, K.time
end

function FPF.coreOn()
  local C = PS.core
  return C ~= nil and C.left ~= nil
end

function FPF.coreGain(points, what, name)
  local C = PS.core
  if not C or C.left or FPF.perk("burstcore") < 1 or not points or points <= 0 then return false end
  C.charge = math.min(FPF.coreMax(), C.charge + points)
  C.gains = (C.gains or 0) + 1
  if C.gains <= 16 then
    log(string.format("BURST CORE +%.0f: %s%s - %.0f of %.0f", points, what, name and (" (" .. name .. ")") or "", C.charge, FPF.coreMax()))
  end
  return true
end

function FPF.coreFire(by)
  local C = PS.core
  local need, time = FPF.coreShot()
  if not C or C.left or C.charge < need - 1e-6 then return false end
  C.charge, C.left, C.time, C.fired = C.charge - need, time, time, (C.fired or 0) + 1
  local G = PS.gun
  if G and G.reloadT then G.reloadT, G.ammo, G.cool = nil, FPF.magSize(), 0.0 end
  pcall(FPF.tf, FPC.vortex.sounds.start)
  if C.fired <= 12 then
    log(string.format("BURST CORE %d fires (%s): %.1f s of the XO-16 using no rounds, %.2f times as fast; %.0f of %.0f left in the core", C.fired, by, time,
      FPC.perk.core.rate, C.charge, FPF.coreMax()))
  end
  return true
end

function FPF.coreFrame(dt)
  local lv = FPF.perk("burstcore")
  if lv < 1 then
    PS.core = nil
    return
  end
  local C = PS.core
  if not C then
    C = { charge = 0.0, seenN = PS.keyN.core or 0 }
    PS.core = C
  end
  dt = dt or 0.0
  if C.left then
    C.left = C.left - dt
    if C.left <= 0.0 then
      C.left = nil
      if (C.fired or 0) <= 12 then log(string.format("BURST CORE %d is over: %.0f of %.0f in the core", C.fired or 0, C.charge, FPF.coreMax())) end
    end
  end
  if C.charge > FPF.coreMax() then C.charge = FPF.coreMax() end
  local need = FPF.coreShot()
  local ready = not C.left and C.charge >= need - 1e-6
  if ready and not C.readySaid then
    C.readySaid = true
    pcall(FPF.tf, FPC.mtms.sounds.ready)
    if (C.fired or 0) <= 12 then log(string.format("BURST CORE ready (%.0f of %.0f)%s", C.charge, FPF.coreMax(), (lv >= 2) and " - it waits for the core key" or "")) end
  elseif not ready then
    C.readySaid = nil
  end
  local n = PS.keyN.core or 0
  if n ~= C.seenN then
    C.seenN = n
    if lv >= 2 and S.driving and S.pilot then
      if not FPF.coreFire("the core key") and (C.refused or 0) < 6 then
        C.refused = (C.refused or 0) + 1
        log(string.format("BURST CORE key: %s (%.0f of the %.0f a firing takes)", C.left and "it burns already" or "not full yet", C.charge, need))
      end
    end
  end
  if ready then
    if lv == 1 then
      FPF.coreFire("full: it fires by itself")
    elseif not S.driving and PS.ent and FPF.aiCoreNow() then
      FPF.coreFire("BT on its own, a foe in its sights")
    end
  end
end

FPC.perk.coreLine = { red = { 1.0, 0.25, 0.2, 0.95 }, hot = { 1.0, 0.62, 0.45, 1.0 }, beat = 5.0 }
function FPF.coreLine(dl, x0, top, total, gap, thick)
  local C = PS.core
  local most = FPF.coreMax()
  if not C or most <= 0 then return 0 end
  local L = FPC.perk.coreLine
  local y = top + gap
  local need = FPF.coreShot()
  render.line(x0, y, x0 + total, y, GetColorU32(0.0, 0.0, 0.0, 0.45), thick + 2)
  local share, col = clamp(C.charge / most, 0.0, 1.0), nil
  local r, h = L.red, L.hot
  if C.left then
    share = clamp((C.charge + need * clamp(C.left / math.max(C.time or 1.0, 0.1), 0.0, 1.0)) / most, 0.0, 1.0)
    render.line(x0, y, x0 + total * share, y, GetColorU32(h[1], h[2] * 0.6, h[3] * 0.5, 0.35), thick + 6)
    col = GetColorU32(h[1], h[2], h[3], h[4])
  elseif C.charge >= need - 1e-6 then
    local k = 0.5 + 0.5 * math.sin(S.clock * L.beat)
    col = GetColorU32(r[1], r[2] + (h[2] - r[2]) * k, r[3] + (h[3] - r[3]) * k, r[4])
  else
    col = GetColorU32(r[1], r[2], r[3], r[4])
  end
  if share > 0 then render.line(x0, y, x0 + total * share, y, col, thick) end
  if FPF.perk("burstcore") >= 3 then
    local mx = x0 + total * (need / most)
    render.line(mx, y - thick, mx, y + thick, GetColorU32(1.0, 1.0, 1.0, 0.85), 2)
  end
  return math.max(0, math.ceil(gap + thick * 0.5 + 3 - 10))
end

function FPF.coreOnce(key)
  local seen = PS.coreSeen
  if not seen then
    seen = { n = 0 }
    PS.coreSeen = seen
  end
  if seen[key] then return true end
  seen[key], seen.n = S.clock, seen.n + 1
  if seen.n > 300 then
    for k, at in pairs(seen) do
      if k ~= "n" and S.clock - at > 120.0 then seen[k], seen.n = nil, seen.n - 1 end
    end
  end
  return false
end

function FPF.coreWorth(ent)
  local K = FPC.perk.core.kill
  local no = false
  pcall(function() no = ent:IsPlayer() == true end)
  local D = PS.decoy
  if not no and D and D.hash then pcall(function() no = tostring(ent:GetEntityID()) == D.hash end) end
  if not no then pcall(function() no = ent:IsCharacterCivilian() == true end) end
  if not no then pcall(function() no = ent:IsCharacterChildren() == true end) end
  if not no then pcall(function() no = GameObject.IsFriendlyTowardsPlayer(ent) == true end) end
  if no then return nil end
  local rank, kind, built, psycho = "", "", "", false
  pcall(function() rank = EnumName("gamedataNPCRarity", ent:GetNPCRarity()) end)
  pcall(function() kind = EnumName("gamedataNPCType", ent:GetNPCType()) end)
  pcall(function() built = EnumName("gamedataArchetypeType", TweakDBInterface.GetCharacterRecord(ent:GetRecordID()):ArchetypeData():Type():Type()) end)
  pcall(function() psycho = ent:IsCharacterCyberpsycho() == true end)
  local function has(text, word) return text:find(word, 1, true) ~= nil end
  if has(rank, "Boss") or has(rank, "MaxTac") or has(kind, "Mech") or FPF.isMech(ent) or psycho or FPF.bigTarget(ent) then return K.boss, "a boss" end
  if has(built, "Heavy") or has(rank, "Elite") then return K.heavy, "a heavy" end
  if has(rank, "Rare") or has(rank, "Officer") then return K.rare, "a rare foe" end
  return K.grunt, "a foe"
end

function FPF.coreKill(evt, tag)
  if tag ~= "b" or not evt or not PS.ent or not PS.core or FPF.perk("burstcore") < 1 then return end
  local A, target = evt.attackData, evt.target
  if not A or not target then return end
  local killing = nil
  pcall(function() killing = A:HasFlag(hitFlag.WasKillingBlow) == true end)
  if killing == nil then
    local hp = healthOf(target)
    killing = type(hp) == "number" and hp <= 0.0
    once("corekillflag", "BURST CORE: the game's mark of a killing blow could NOT be read - a kill is told by the health left")
  end
  if not killing then return end
  local mine = false
  pcall(function() mine = tostring(A:GetSource():GetEntityID()) == tostring(PS.ent:GetEntityID()) end)
  if not mine and S.driving then pcall(function() mine = A:GetInstigator():IsPlayer() == true end) end
  if not mine then return end
  local key = nil
  pcall(function() key = tostring(target:GetEntityID()) end)
  if not key or FPF.coreOnce(key) then return end
  local points, what = FPF.coreWorth(target)
  if not points then return end
  local name = nil
  pcall(function() name = TDBID.ToStringDEBUG(target:GetRecordID()) end)
  FPF.coreGain(points, what, name)
end

FPF.hitSeen95 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local ok, err = pcall(FPF.coreKill, evt, tag)
  if not ok then once("corekill" .. tostring(err), "BURST CORE: a kill could NOT be counted: " .. tostring(err)) end
  return FPF.hitSeen95(evt, tag)
end

function FPF.coreVehicle(veh)
  if not PS.core or FPF.perk("burstcore") < 1 then return end
  if FPF.coreOnce("v" .. FPF.vehKey(veh)) then return end
  local big = false
  pcall(function() big = veh:IsA("vehicleAVBaseObject") == true end)
  if not big then pcall(function() big = veh:IsA("vehicleTankBaseObject") == true end) end
  local K = FPC.perk.core.kill
  FPF.coreGain(big and K.av or K.vehicle, big and "an AV or a tank blown up" or "a vehicle blown up", FPF.vehicleText(veh))
end

FPF.explode95 = FPF.explode
function FPF.explode(veh, why)
  local done = FPF.explode95(veh, why)
  if done then
    local ok, err = pcall(FPF.coreVehicle, veh)
    if not ok then once("corevehicle" .. tostring(err), "BURST CORE: a vehicle blown up could NOT be counted: " .. tostring(err)) end
  end
  return done
end

function FPF.coreDevice(dev)
  if not PS.core or FPF.perk("burstcore") < 1 then return end
  local turret = false
  pcall(function() turret = dev:IsTurret() == true end)
  if not turret then return end
  local key = nil
  pcall(function() key = "d" .. tostring(dev:GetEntityID()) end)
  if not key or FPF.coreOnce(key) then return end
  FPF.coreGain(FPC.perk.core.kill.turret, "a turret broken", nil)
end

FPF.devHit95 = FPF.devHit
function FPF.devHit(dev, record, x, y, z, dx, dy, dz, share, dist, by)
  local before = healthOf(dev)
  FPF.devHit95(dev, record, x, y, z, dx, dy, dz, share, dist, by)
  if type(before) == "number" and before > 0.5 and before - (share or 0.0) <= 0.5 then
    local ok, err = pcall(FPF.coreDevice, dev)
    if not ok then once("coredevice" .. tostring(err), "BURST CORE: a turret broken could NOT be counted: " .. tostring(err)) end
  end
end

function FPF.aiCoreNow()
  local B = PS.buddy
  if not B or B.off or B.state ~= "active" or not B.target or not FPF.fightOn() then return false end
  local okG, guard = pcall(FPF.guardPlain)
  if okG and guard then return false end
  return S.clock - (B.target.seenAt or -100.0) < 1.0
end

FPF.dashMul96 = FPF.dashMul
function FPF.dashMul()
  local k = FPF.dashMul96()
  if P.perks and S.driving and S.pilot then k = k * FPC.perk.dashBase end
  return k
end

FPC.skateFx = { sparks = [[ep1\fx\quest\q301\stadium_elevator\q301_elevator_break_friction_sparks.effect]], sparkEvery = 0.15,
  sparkLife = 0.35, sparkLinger = 1.0, flameFor = 0.3, sounds = { "bt7274_jet_2", "bt7274_jet_3" }, soundEvery = 1.3 }

function FPF.skateStep(dt, amount, dashing, dashBefore, air)
  local K = FPC.perk.skate
  local Sk = PS.skate
  if PS.dashT == 0.0 and dashBefore == nil and not Sk then PS.skateArm = FPF.dashHeld() and { at = S.clock } or nil end
  if FPF.perk("skate") < 1 or not S.driving or not S.pilot then
    Sk = nil
  elseif Sk then
    if amount <= 0 or air or PS.power <= 0.0 then
      PS.skateEnds = (PS.skateEnds or 0) + 1
      if PS.skateEnds <= 8 then
        log(string.format("SKATE %d is over (%s): %.1f s, %.0f m%s", Sk.n, (amount <= 0) and "the keys let go" or (air and "in the air" or "no dash power left"),
          S.clock - Sk.from, Sk.way, (Sk.dashes > 0) and string.format(", %d dash%s in it", Sk.dashes, (Sk.dashes > 1) and "es" or "") or ""))
      end
      Sk = nil
    end
  elseif FPF.skateBegins(dashing, dashBefore, amount, air) then
    PS.skates = (PS.skates or 0) + 1
    Sk = { n = PS.skates, from = S.clock, way = 0.0, dashes = 0, dashN = PS.dashes, x = PS.x, y = PS.y }
    PS.skateW = 1.0
    if PS.skates <= 8 then
      log(string.format("SKATE %d: %s - %.0f m/s, %.0f dash power a second (%.0f left)", Sk.n,
        P.skateHold and "the dash key and a move key held as the dash's push ended" or "out of a dash with a move key held", K.speed,
        K.drain * FPF.perkValue("skate"), PS.power))
    end
  end
  PS.skate = Sk
  if Sk then
    if PS.dashes ~= Sk.dashN then Sk.dashes, Sk.dashN = Sk.dashes + (PS.dashes - Sk.dashN), PS.dashes end
    if not dashing then PS.power = math.max(0.0, PS.power - K.drain * FPF.perkValue("skate") * dt) end
    Sk.way = Sk.way + math.sqrt((PS.x - Sk.x) ^ 2 + (PS.y - Sk.y) ^ 2)
    Sk.x, Sk.y = PS.x, PS.y
    PS.skateW = math.min(1.0, (PS.skateW or 0.0) + dt / K.fadeIn)
    pcall(FPF.skateFx, Sk)
  else
    PS.skateW = math.max(0.0, (PS.skateW or 0.0) - dt / K.fadeOut)
  end
  return Sk ~= nil and not dashing
end

function FPF.skateMove(dt, dirx, diry, amount)
  local K = FPC.perk.skate
  local sp = K.speed * clamp(amount, 0.6, 1.0)
  local dvx, dvy = dirx * sp - PS.vx, diry * sp - PS.vy
  local dv = math.sqrt(dvx * dvx + dvy * dvy)
  local step = K.accel * dt
  if dv <= step then
    PS.vx, PS.vy = dirx * sp, diry * sp
  else
    PS.vx, PS.vy = PS.vx + dvx / dv * step, PS.vy + dvy / dv * step
  end
end

function FPF.skateFx(Sk)
  local E = FPC.skateFx
  if S.clock >= (Sk.soundAt or 0.0) then
    Sk.soundAt = S.clock + E.soundEvery
    Sk.soundN = (Sk.soundN or 0) % #E.sounds + 1
    pcall(FPF.tf, E.sounds[Sk.soundN])
  end
  if not P.fxOn or not PS.ent then return end
  local sp = math.sqrt(PS.vx * PS.vx + PS.vy * PS.vy)
  local back = (sp > 0.5) and (math.deg(math.atan2(-PS.vx, PS.vy)) + 180.0) or (PS.yaw + 180.0)
  if S.clock >= (Sk.flameAt or 0.0) then
    Sk.flameAt = S.clock + E.flameFor
    local path = FPF.fxPath("dash")
    if path and not PF.shown and slotWorld(FPC.ports.ahead[1]) ~= nil then
      FPF.fxTrain(path, FPC.ports.ahead, E.flameFor, FPC.jet.every, FPC.jet.life, back, 0.0, true, FPC.jet.gap)
    end
  end
  if S.clock >= (Sk.sparkAt or 0.0) then
    Sk.sparkAt = S.clock + E.sparkEvery
    local r = math.rad(PS.yaw)
    PS.skateSparks = PS.skateSparks or {}
    for _, side in ipairs({ -1.0, 1.0 }) do
      local inst = FPF.fxAt(E.sparks, PS.x + math.cos(r) * 0.9 * side, PS.y + math.sin(r) * 0.9 * side, PS.z + 0.05, back, 0.0)
      if inst then PS.skateSparks[#PS.skateSparks + 1] = { inst = inst, breakAt = S.clock + E.sparkLife, killAt = S.clock + E.sparkLife + E.sparkLinger } end
    end
  end
end

function FPF.skateFrame()
  if PS.skate and not (S.driving and S.pilot) then PS.skate = nil end
  local L = PS.skateSparks
  if not L then return end
  for i = #L, 1, -1 do
    local e = L[i]
    if S.clock >= e.killAt or not PS.ent then
      FPF.fxKill152(e.inst)
      table.remove(L, i)
    elseif not e.broken and S.clock >= e.breakAt then
      e.broken = true
      FPF.fxBreak152(e.inst)
    end
  end
end

FPC.hazard = { fire = [[base\fx\weapons\explosives\incendiary_grenade\w_explosives_001_incendiary_ground_grenade_01.effect]],
  gas = [[base\fx\gameplay\poison_gas\poison_gas_5x5.effect]], gasSize = 6.0, linger = 4.0, high = 4.0, below = 4.0 }

function FPF.ordnance(x, y, z)
  local fire, gas = FPF.perk("incendiary"), FPF.perk("gas")
  if fire < 1 and gas < 1 then return end
  local g = groundZ(x, y, z + 1.0)
  local onGround = g ~= nil and z - g <= FPC.hazard.below
  if fire >= 1 then
    local K = FPC.perk.incendiary
    PS.npcsAt = -10
    refreshNpcs()
    local n = 0
    for _, ent in ipairs(PS.npcs) do
      if IsDefined(ent) then
        pcall(function()
          if not OP77.targetActive(ent) then return end
          local p = ent:GetWorldPosition()
          if math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z + 1.0 - z) ^ 2) <= FPC.mtms.reach then
            if not OP77.statusObserved(ent, K.status) then
              StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(K.status))
            end
            n = n + 1
          end
        end)
      end
    end
    PS.burnt = (PS.burnt or 0) + n
    if onGround and K.life[fire + 1] > 0.0 then FPF.hazardNew("fire", x, y, g, K.life[fire + 1], K.wide[fire + 1], false) end
  end
  if gas >= 1 and onGround then
    local G = FPC.perk.gas
    FPF.hazardNew("gas", x, y, g, G.life[gas + 1], G.wide[gas + 1], G.blinds[gas + 1])
  end
end

function FPF.hazardNew(kind, x, y, z, life, wide, blinds)
  local H = FPC.hazard
  PS.hazards = PS.hazards or {}
  local Z = { kind = kind, x = x, y = y, z = z, at = S.clock, life = life, wide = wide, blinds = blinds == true, fx = {}, seen = {},
    tickAt = S.clock, hits = 0 }
  local spots = { { 0.0, 0.0 } }
  if kind == "fire" then
    local R = wide * 0.5
    local ring = 1.6
    while ring <= R + 0.01 do
      local k = math.max(4, math.floor(2.0 * math.pi * ring / 1.8 + 0.5))
      for i = 1, k do
        local a = (i + 0.5 * (ring % 2.0)) / k * 2.0 * math.pi
        spots[#spots + 1] = { math.cos(a) * ring, math.sin(a) * ring }
      end
      ring = ring + 1.6
    end
  elseif wide > H.gasSize + 0.5 then
    local o = (wide - H.gasSize) * 0.5 + 1.0
    spots = { { 0.0, 0.0 }, { o, 0.0 }, { -o, 0.0 }, { 0.0, o }, { 0.0, -o } }
  end
  if P.fxOn then
    local path = (kind == "fire") and H.fire or H.gas
    local quiet = kind == "fire" and H.fireQuiet ~= nil
    if quiet then Z.loud = FPF.fireLoud(x, y) end
    for i, q in ipairs(spots) do
      local gz = (kind == "fire") and (groundZ(x + q[1], y + q[2], z + 1.0) or z) or z
      local one = (quiet and not (Z.loud and i == 1)) and H.fireQuiet or path
      local inst = FPF.fxAt(one, x + q[1], y + q[2], gz + 0.05, math.random() * 360.0, 0.0)
      if inst then Z.fx[#Z.fx + 1] = inst end
    end
  end
  PS.hazards[#PS.hazards + 1] = Z
  PS.hazardN = (PS.hazardN or 0) + 1
  if PS.hazardN <= 8 then
    log(string.format("MISSILES %s: %.0f m across for %.0f s (%d of the game's effects)%s", (kind == "fire") and "INCENDIARY - a fire on the ground" or "GAS - a toxic cloud",
      wide, life, #Z.fx, Z.blinds and ", it blinds" or "") .. ((Z.loud == nil) and "" or (Z.loud and "; its middle one with the game's sound and light"
        or "; all of them quiet - a fire near it is heard")))
  end
  return Z
end

function FPF.hazardsFrame()
  local L = PS.hazards
  if not L or #L == 0 then return end
  for i = #L, 1, -1 do
    local Z = L[i]
    local age = S.clock - Z.at
    if age >= Z.life + FPC.hazard.linger or not PS.ent then
      for _, inst in ipairs(Z.fx) do FPF.fxKill152(inst) end
      table.remove(L, i)
    elseif age >= Z.life then
      if not Z.ended then
        Z.ended = true
        for _, inst in ipairs(Z.fx) do FPF.fxBreak152(inst) end
      end
    elseif S.clock >= Z.tickAt then
      local K = (Z.kind == "fire") and FPC.perk.incendiary or FPC.perk.gas
      Z.tickAt = S.clock + K.tick
      PS.npcsAt = -10
      refreshNpcs()
      for _, ent in ipairs(PS.npcs) do
        if IsDefined(ent) then
          pcall(function()
            if not ScriptedPuppet.IsActive(ent) then return end
            local p = ent:GetWorldPosition()
            if math.sqrt((p.x - Z.x) ^ 2 + (p.y - Z.y) ^ 2) > Z.wide * 0.5 or p.z < Z.z - 2.0 or p.z > Z.z + FPC.hazard.high then return end
            local key = tostring(ent:GetEntityID())
            if Z.seen[key] and S.clock - Z.seen[key] < K.again then return end
            Z.seen[key] = S.clock
            StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(K.status))
            if Z.blinds then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(K.blind)) end
            Z.hits = Z.hits + 1
          end)
        end
      end
    end
  end
end

FPC.esmoke.emp = { path = [[base\fx\devices\_damage\emp\big\d_emp_status_big.effect]], every = 0.6, life = 1.0, linger = 2.5, low = 0.5, high = 3.0 }

function FPF.empFrame()
  local E, K = FPC.esmoke.emp, FPC.esmoke
  local L = PS.empFx
  if not L then
    L = {}
    PS.empFx = L
  end
  for i = #L, 1, -1 do
    local e = L[i]
    if S.clock >= e.killAt or not PS.ent then
      FPF.fxKill152(e.inst)
      table.remove(L, i)
    elseif not e.broken and S.clock >= e.breakAt then
      e.broken = true
      FPF.fxBreak152(e.inst)
    end
  end
  if not P.fxOn then return end
  for _, C in ipairs(PS.clouds) do
    local age = S.clock - C.at
    if age >= 0.0 and age < K.life and not C.ended and S.clock >= (C.empAt or 0.0) then
      C.empAt = S.clock + E.every
      local q = C.puffs[math.random(#C.puffs)]
      local a, r = math.random() * 2.0 * math.pi, math.random() * (C.inner or K.inner) * 0.6
      local inst = FPF.fxAt(E.path, q[1] + math.cos(a) * r, q[2] + math.sin(a) * r, C.z + E.low + math.random() * (E.high - E.low), math.random() * 360.0, 0.0)
      if inst then
        L[#L + 1] = { inst = inst, breakAt = S.clock + E.life, killAt = S.clock + E.life + E.linger }
        C.emps = (C.emps or 0) + 1
      end
    end
  end
end

P.skateHold = true

function FPF.dashHeld()
  if S.keyHeld and S.keyHeld.dash then return true end
  local at = S.dodgeAct
  if not at or S.clock - at > 10.0 then return false end
  return not S.keysOk or FPF.keyName("dashKey") == "LControl"
end

function FPF.skateBegins(dashing, dashBefore, amount, air)
  if amount <= 0 or air or PS.power <= 0.0 then
    PS.skateArm = nil
    return false
  end
  if not P.skateHold then
    return not dashing and dashBefore ~= nil and dashBefore < TF.dodgeTime
  end
  local A = PS.skateArm
  if A and not FPF.dashHeld() then
    PS.skateArm, A = nil, nil
  end
  if not A or S.clock - A.at < TF.dodgeTime + FPC.perk.skate.hold then return false end
  PS.skateArm = nil
  return true
end

FPF.tuneFrame97 = FPF.tuneFrame
function FPF.tuneFrame()
  FPF.tuneFrame97()
  if S.clock < (S.skateAt or 0.0) then return end
  S.skateAt = S.clock + FPC.tune.every
  local sys = nil
  pcall(function() sys = FPF.keysSystem() end)
  if not sys then return end
  local v = nil
  pcall(function() v = sys.skateStart end)
  if v == nil then return end
  local n = nil
  pcall(function() n = EnumInt(v) end)
  local hold
  if type(n) == "number" then hold = n ~= 1 else hold = not tostring(v):find("MoveKeys", 1, true) end
  if hold ~= P.skateHold or not S.skateSaid then
    S.skateSaid = true
    P.skateHold = hold
    log(string.format("Mod Settings: SKATE begins %s", hold and "with the dash key and a move key held past the dash (the key may be let go then)"
      or "with a move key held as the dash ends (as in t97)"))
  end
end

FPF.poundStart97 = FPF.poundStart
function FPF.poundStart()
  local ok = FPF.poundStart97()
  if ok then PS.pound = { t = 0.0, ft = 0.0, age = 0.0, w = 0.0, n = PS.pounds or 0 } end
  return ok
end

function FPF.poundClock(dt)
  local Q = PS.pound
  local C, F = PUNCH_CLIP.pound, FP.pound
  local J = PS.jump
  Q.age = Q.age + dt
  if J and J.pound and J.stage == "air" and not Q.landed then
    local ground = FPF.below(PS.x, PS.y, PS.z + 0.5, 400.0) or J.floor or PS.z
    local left = math.max(0.0, PS.z - ground) / FPC.perk.pound.speed
    Q.t = math.max(math.min(Q.t + dt, C.top), C.hit - left)
    if F then Q.ft = math.max(math.min(Q.ft + dt, F.top), F.hit - left) end
  else
    if not Q.landed then
      Q.landed = true
      Q.t, Q.ft = math.max(Q.t, C.hit), math.max(Q.ft, F and F.hit or 0.0)
      if Q.n <= 8 then
        log(string.format("GROUND POUND %d: the firewall's slam meets the ground (its clip at %.2f s, the fist down at %.2f s; in view %.2f / %.2f s)",
          Q.n, Q.t, C.hit, Q.ft, F and F.hit or 0.0))
      end
    end
    Q.t, Q.ft = Q.t + dt, Q.ft + dt
  end
  Q.w = clamp(math.min(Q.age / 0.1, (C.time - Q.t) / C.fade), 0.0, 1.0)
  if Q.t >= C.time and (not F or Q.ft >= F.time) then PS.pound = nil end
end

FPF.punch97 = FPF.punch
function FPF.punch(dt, ent, key)
  local r = FPF.punch97(dt, ent, key)
  local Q = PS.pound
  if Q then
    local ok, err = pcall(FPF.poundClock, dt)
    if not ok then
      PS.pound = nil
      once("poundclip" .. tostring(err), "GROUND POUND: the firewall's slam could NOT be played: " .. tostring(err))
    elseif PS.pound then
      PS.punchW, PS.punchT, PS.punchClip = Q.w, math.min(Q.t, PUNCH_CLIP.pound.time), (PS.weapon == "fist") and PUNCH_CLIP.fist.clips.pound or 2.0
    end
  end
  return r
end

FPF.drive97 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive97(dt, steps, sprinting)
  if not PF.shown or not PF.ent or not IsDefined(PF.ent) then return end
  local Q = PS.pound
  if Q and FP.pound then
    FPF.var("fp_melee_clip", 2.0)
    FPF.var("fp_melee", Q.w)
    FPF.var("fp_time_melee", math.min(Q.ft, FP.pound.time))
    if Q.ft >= FP.pound.time - 0.1 and not Q.raised then
      Q.raised = true
      PF.raiseT = 0.0
    end
  end
  local ok, err = pcall(FPF.fpGun, dt)
  if not ok then once("fpgun" .. tostring(err), "FIRST PERSON: the gun's own clips could NOT be set: " .. tostring(err)) end
end

