PS.weapon = "xo16"

function FPF.gunPick(why)
  local w = "xo16"
  if P.perks then
    local k = math.floor(FPF.factGet(FPC.perk.gunFact) + 0.5)
    if k == 1 then w = "rail" elseif k == 2 then w = "pred" end
  end
  PS.weapon = w
  local W = FPC.guns[w]
  FPC.ent = W.fpEnt
  FPC.body[3] = W.mesh
  FPC.shade.twins[2] = W.shadow
  FPC.shade.meshes[2] = "titan\\bt7274\\meshes\\" .. W.shadow .. ".mesh"
  for i = 1, 3 do MUZZLE_REST[i] = W.rest[i] end
  ZOOM.fov, ZOOM.speed = W.zoom.fov, W.zoom.speed
  for k in pairs(FP) do FP[k] = nil end
  for k, v in pairs(FPC.fpGuns.xo16) do FP[k] = v end
  if w ~= "xo16" then
    for k, v in pairs(FPC.fpGuns[w]) do FP[k] = v end
  end
  if PS.gun then
    PS.gun.ammo, PS.gun.reloadT, PS.gun.anim = FPF.magSize(), nil, nil
  end
  PS.gunPicks = (PS.gunPicks or 0) + 1
  if PS.gunPicks <= 8 or PS.gunWas ~= w then
    log(string.format("BT's gun: %s (%s; the selected weapon, %s = %d) - its own mesh and muzzle, its first-person view %s, %d rounds",
      FPF.gunNamed(), tostring(why), FPC.perk.gunFact, math.floor(FPF.factGet(FPC.perk.gunFact) + 0.5), W.fpEnt, FPF.magSize()))
  end
  PS.gunWas = w
end

function FPF.gunNamed()
  return ({ xo16 = "the XO-16", rail = "the RAILGUN", pred = "the PREDATOR CANNON" })[PS.weapon or "xo16"] or "the XO-16"
end

function FPF.gunName()
  return FPC.guns[PS.weapon or "xo16"].name
end

function FPF.gunNote()
  local G = PS.gun
  if not G then return "" end
  if PS.weapon == "rail" and (G.charge or 0.0) > 0.0 then
    return string.format("   CHARGE %d", G.level or 1)
  elseif PS.weapon == "pred" and (G.barrels or 0.0) > 0.0 and G.barrels < 1.0 then
    return string.format("   SPIN %d %%", math.floor(G.barrels * 100.0 + 0.5))
  end
  return ""
end

function FPF.gunMeshes()
  local ent = PS.ent
  if not ent or not IsDefined(ent) then return end
  local W, done = FPC.guns[PS.weapon or "xo16"], 0
  for _, G in pairs(FPC.guns) do
    local mine = G == W
    pcall(function()
      ent:FindComponentByName(G.mesh):Toggle(mine and not PF.shown)
      done = done + 1
    end)
    pcall(function() ent:FindComponentByName(G.shadow):Toggle(mine) end)
  end
  if done < 3 then once("gunmeshes", string.format("BT's gun: only %d of the three guns' meshes are on BT's object (the archive loaded is older than t98)", done)) end
end

function FPF.gunSpread()
  local w = PS.weapon
  if w == "rail" then
    if not S.driving then return FPC.guns.rail.aiSpread end
    return (PS.zoomW or 0.0) > 0.5 and 0.0 or FPC.perk.rail.hip
  elseif w == "pred" then
    local K = FPC.perk.pred
    if FPF.perk("predator") > 0 and S.driving and (PS.zoomW or 0.0) > 0.5 then return K.tight end
    return K.spread
  end
  return XO16.spread
end

function FPF.gunRange()
  local w = PS.weapon
  if w == "rail" then return FPC.perk.rail.range end
  if w == "pred" then return FPC.perk.pred.range end
  return XO16.range
end

FPF.magSize97 = FPF.magSize
function FPF.magSize()
  local w = PS.weapon
  if w == "rail" then return math.max(1, math.floor(FPF.perkValue("railcap") * P.magScale + 0.5)) end
  if w == "pred" then return math.max(1, math.floor(FPF.perkValue("predcap") * P.magScale + 0.5)) end
  return FPF.magSize97()
end

FPF.reloadTime97 = FPF.reloadTime
function FPF.reloadTime()
  local w = PS.weapon
  if w == "rail" then return FPC.perk.rail.reload end
  if w == "pred" then return FPC.perk.pred.reload end
  return FPF.reloadTime97()
end

FPF.reloadRate97 = FPF.reloadRate
function FPF.reloadRate()
  if PS.weapon == "rail" or PS.weapon == "pred" then return 1.0 end
  return FPF.reloadRate97()
end

FPF.gunRate97 = FPF.gunRate
function FPF.gunRate()
  if PS.weapon == "pred" then
    return FPC.perk.pred.rate * (FPF.coreOn() and FPC.perk.core.rate or 1.0)
  end
  return FPF.gunRate97()
end

FPF.damageFlats97 = FPF.damageFlats
function FPF.damageFlats()
  FPF.damageFlats97()
  local k, n = P.damageScale, 0
  for _, R in ipairs(FPC.tune.damage) do
    local m = (R[1]:find("BT7274_Rail_", 1, true) and FPF.perkValue("raildamage")) or ((R[1] == "Attacks.BT7274_Pred_Hit") and FPF.perkValue("preddamage")) or nil
    if m and m ~= 1.0 then
      for i, kind in ipairs(FPC.tune.kinds) do
        local v = R[2][i] * k * m * ((kind == "boss") and P.bossMul or 1.0)
        if pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end) then n = n + 1 end
      end
      pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * k * m) end)
      pcall(function() TweakDB:Update(R[1]) end)
    end
  end
  if n > 0 then
    log(string.format("damage of BT's weapons: the railgun's shots x %.2f (OVERCHARGED BOLTS), the predator cannon's rounds x %.2f (HEAVY SLUGS)",
      FPF.perkValue("raildamage"), FPF.perkValue("preddamage")))
  end
end

FPF.perkFrame97 = FPF.perkFrame
function FPF.perkFrame()
  local was = S.perk
  FPF.perkFrame97()
  local now = S.perk
  if was and now and (was.raildamage ~= now.raildamage or was.preddamage ~= now.preddamage) then
    guard("the damage of BT's weapons", FPF.damageFlats)
  end
end

FPF.gunFrame97 = gunFrame
gunFrame = function(dt, ent, firing)
  if PS.weapon == "rail" or PS.weapon == "pred" then return FPF.gunFrame98(dt, ent, firing) end
  local G = PS.gun
  if G and G.record and G.record ~= XO16.attack and G.record ~= XO16.fallback then G.record = nil end
  return FPF.gunFrame97(dt, ent, firing)
end

for _, R in ipairs({ { "Attacks.BT7274_Rail_1", 0.12 }, { "Attacks.BT7274_Rail_2", 0.25 }, { "Attacks.BT7274_Rail_3", 0.45 },
  { "Attacks.BT7274_Rail_4", 0.8 }, { "Attacks.BT7274_Pred_Hit", 0.024 } }) do FPC.boss[#FPC.boss + 1] = R end

function FPF.gunRecord(name)
  S.gunRecords = S.gunRecords or {}
  local known = S.gunRecords[name]
  if known == nil then
    known = false
    pcall(function() known = TweakDB:GetRecord(name) ~= nil end)
    S.gunRecords[name] = known
    if not known then
      log("record " .. name .. " does not exist (TweakXL did not load r6/tweaks/bt7274/bt7274_weapon.yaml of t98) - using " .. XO16.fallback)
    end
  end
  return known and name or XO16.fallback
end

function FPF.aiHolds()
  return PS.weapon == "rail" or PS.weapon == "pred"
end

function FPF.gunChecks()
  local due = nil
  for i, c in ipairs(PS.checks) do
    if S.clock >= c.at then
      due = i
      break
    end
  end
  if not due then return end
  local c = table.remove(PS.checks, due)
  local now = IsDefined(c.ent) and healthOf(c.ent) or nil
  log(string.format("%s hit a %s %.0f m from %s (%s): health %s before, %s %.1f s later", c.by or FPF.gunName(), c.kind or "person", c.dist,
    c.by and "BT" or "the muzzle", c.what or "?",
    c.before and string.format("%.0f %%", c.before) or "?", now and string.format("%.0f %%", now) or "? (gone)", c.later or 0.4))
end

function FPF.gunFrame98(dt, ent, firing)
  local G, W = PS.gun, FPC.guns[PS.weapon]
  FPF.gunChecks()
  FPF.reload98(dt, ent, firing)
  if G.reloadT then
    G.reloadT = G.reloadT - dt
    if G.reloadT <= 0 then G.reloadT, G.ammo, G.cool = nil, FPF.magSize(), 0.0 end
    firing = false
  end
  if PS.weapon == "rail" then FPF.railFrame(G, W, dt, ent, firing) else FPF.predFrame(G, W, dt, ent, firing) end
  if not G.reloadT and (G.ammo <= 0 or (PS.reloadKey and G.ammo < FPF.magSize() and not FPF.coreOn())) then
    G.reloadT, G.mags = FPF.reloadTime(), G.mags + 1
    G.reloadFull = G.reloadT
    G.anim, G.cut = 0.0, nil
    if G.mags <= 3 then
      log(string.format("%s reloads (%s; %d rounds fired so far, %.1f s)", FPF.gunName(), G.ammo <= 0 and "by itself: it is empty" or "reload key", G.shots, G.reloadT))
    end
  end
  PS.reloadKey = false
end

function FPF.reload98(dt, ent, firing)
  local G = PS.gun
  local R, W = RELOAD[PS.weapon], FPC.guns[PS.weapon]
  if G.anim == nil then
    PS.reloadW = 0.0
    return
  end
  local was = G.anim
  G.anim = G.anim + dt
  if P.gunSound > 0 then
    if S.driving then
      local rows = (PS.weapon == "rail") and W.sounds.reloadFp or W.sounds.reload
      for i, e in ipairs(FP.reloadSounds or {}) do
        if was <= e[2] and G.anim > e[2] and rows[i] then FPF.gunSound98(rows[i]) end
      end
    elseif PS.weapon == "rail" then
      for i, at in ipairs(R.sounds) do
        if was <= at and G.anim > at and W.sounds.reloadTp[i] then FPF.gunSound98(W.sounds.reloadTp[i]) end
      end
    else
      for i, e in ipairs(FPC.fpGuns.pred.reloadSounds) do
        if was <= e[2] and G.anim > e[2] and W.sounds.reload[i] then FPF.gunSound98(W.sounds.reload[i]) end
      end
    end
  end
  if G.cut == nil and firing and G.reloadT == nil and G.ammo > 0 then G.cut = G.anim end
  local long = math.max(R.time, (FPC.fpGuns[PS.weapon] or {}).reload or R.time)
  if G.anim >= long or (G.cut and G.anim - G.cut >= RELOAD_CUT) then
    G.anim, G.cut, PS.reloadW = nil, nil, 0.0
    return
  end
  local w = math.min(1.0, G.anim / R.fade, (R.time - G.anim) / R.fade)
  if G.cut then w = math.min(w, 1.0 - (G.anim - G.cut) / RELOAD_CUT) end
  PS.reloadW, PS.reloadTime = ease(math.max(0.0, w)), math.min(G.anim, R.time)
end

function FPF.gunSound98(name)
  if not name or not P.sounds then return false end
  local g = nil
  if not S.driving then
    local d = 0.0
    pcall(function()
      local p = Game.GetPlayer():GetWorldPosition()
      d = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2 + (p.z - PS.z) ^ 2)
    end)
    g = clamp(FPC.ai.loud * (1.0 - d / FPC.ai.far), FPC.ai.quiet, FPC.ai.loud)
  end
  local was = PS.aiGain
  PS.aiGain = g or was
  local ok, played = pcall(FPF.tf, name)
  PS.aiGain = was
  if ok and played then PS.gunSounds = (PS.gunSounds or 0) + 1 end
  return ok and played
end

function FPF.gunStop98(name, fade)
  local axl = FPF.axl()
  if axl and name then pcall(FPF.sideStop, axl, name, fade or 0.2) end
end

function FPF.gunHeard()
  local d = 0.0
  pcall(function()
    local p = Game.GetPlayer():GetWorldPosition()
    d = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2 + (p.z - PS.z) ^ 2)
  end)
  return d
end

function FPF.railFrame(G, W, dt, ent, firing)
  local K = FPC.perk.rail
  local ai = not S.driving
  local full = K.charge * FPF.perkValue("railcharge") / (FPF.coreOn() and FPC.perk.core.rate or 1.0)
  local charging = (ai and firing or (PS.zoom and not PS.auto)) and G.ammo > 0 and not G.reloadT
  local was = G.charge or 0.0
  if charging then
    G.charge = math.min(1.0, was + dt / full)
  else
    G.charge = math.max(0.0, was - dt / W.drain)
  end
  local level = 1 + math.floor(G.charge * (K.levels - 1) + 1e-6)
  if charging and was <= 0.0 then
    FPF.gunSound98(W.sounds.charge)
    G.charging = true
    G.charges = (G.charges or 0) + 1
  end
  if level > (G.level or 1) then FPF.gunSound98((level >= K.levels) and W.sounds.full or W.sounds.tick) end
  if not charging and G.charging then
    G.charging = false
    FPF.gunStop98(W.sounds.charge, 0.3)
    if was > 0.0 then FPF.gunSound98(W.sounds.chargeEnd) end
  end
  G.level = level
  if charging and P.fxOn and S.clock >= (G.fxAt or 0.0) then
    G.fxAt = S.clock + W.fx.chargeEvery
    local m = PF.shown and FPF.slot("muzzle") or slotWorld(W.slot)
    if m then
      FPF.fxAt(PF.shown and W.fx.chargeFp or W.fx.charge, m.x, m.y, m.z, S.yaw, 0.0)
      PS.railChargeFx = (PS.railChargeFx or 0) + 1
    end
  elseif not charging then
    G.fxAt = 0.0
  end
  G.cool = math.max(0.0, (G.cool or 0.0) - dt)
  local pull
  if ai then
    pull = firing and G.charge >= math.min(1.0, K.aiCharge / full)
  else
    pull = firing and not G.fired
    if not firing then G.fired = false end
  end
  if pull and G.cool <= 0.0 and G.ammo > 0 and not G.reloadT then
    G.fired = true
    FPF.railShot(G, W, ent, level)
    G.cool = K.every
  end
end

function FPF.railShot(G, W, ent, level)
  local tier = math.max(1, math.min(4, level - 1))
  G.record, G.tier = FPF.gunRecord(W.records[tier]), tier
  local share = FPC.wreck.gun
  FPC.wreck.gun = share * W.wreck[tier]
  local ok, err = pcall(fireRound, ent)
  FPC.wreck.gun = share
  if not ok then error(err, 0) end
  if P.gunSound > 0 then
    if S.driving then
      FPF.gunSound98(W.sounds.fire[tier])
    else
      FPF.gunSound98((FPF.gunHeard() >= W.sounds.farFrom) and W.sounds.far or W.sounds.tp[tier])
    end
  end
  FPF.gunStop98(W.sounds.charge, 0.1)
  G.charging, G.charge, G.level = false, 0.0, 1
  PF.aimDip = W.dip
  PS.railShots = (PS.railShots or 0) + 1
  if PS.railShots <= 6 then
    log(string.format("RAILGUN shot %d: charge level %d of %d (%s), %d rounds left", PS.railShots, level, FPC.perk.rail.levels, G.record, G.ammo))
  end
end

function FPF.railPierce(m, dx, dy, dz, t, first)
  if FPF.perk("railgun") < 1 then return end
  local K, G = FPC.perk.rail, PS.gun
  local range = FPF.gunRange()
  local met = {}
  if first then met[first] = true end
  local from, n, tries = t + 0.5, 0, 0
  while n < K.pierce - 1 and from < range and tries < 64 do
    tries = tries + 1
    local t2, kind, who = rayWorld(m.x + dx * from, m.y + dy * from, m.z + dz * from, dx, dy, dz, range - from)
    if kind ~= "person" or who == nil then break end
    if not met[who] then
      met[who] = true
      local hx, hy, hz = m.x + dx * (from + t2), m.y + dy * (from + t2), m.z + dz * (from + t2)
      FPF.railHit(who, hx, hy, hz, dx, dy, dz)
      if P.fxOn then FPF.fxAt(FPF.fxPath("impact"), hx - dx * 0.05, hy - dy * 0.05, hz - dz * 0.05, wrap180(math.deg(math.atan2(-dx, dy)) + 180.0), 0.0) end
      n = n + 1
    end
    from = from + t2 + 0.5
  end
  if n > 0 then
    PS.pierced = (PS.pierced or 0) + n
    once("pierce", string.format("RAILGUN: PIERCING SHOT - a shot went on through %d more", n))
  end
  G.pierced = n
end

function FPF.railHit(who, hx, hy, hz, dx, dy, dz)
  local G = PS.gun
  local drone = P.droneFull and FPF.isDrone(who)
  local mech = not drone and P.mechFull and FPF.isMech(who)
  if drone or mech or (P.fullHits and FPF.bigTarget(who)) then
    FPF.hitFull(who, G.record, hx, hy, hz, dx, dy, dz)
  else
    startAttack(hx, hy, hz)
    hitPerson(who, hx, hy, hz, dx, dy, dz)
  end
end

function FPF.predFrame(G, W, dt, ent, firing)
  local K = FPC.perk.pred
  local spinUp = K.spin * FPF.perkValue("predspin")
  local want = (firing or (S.driving and PS.zoom and not PS.auto)) and not G.reloadT
  if not S.driving then firing = FPF.predBurst(G, firing) end
  local was = G.barrels or 0.0
  if want then
    G.barrels = math.min(1.0, was + dt / spinUp)
  else
    G.barrels = math.max(0.0, was - dt / K.down)
  end
  G.turn = ((G.turn or 0.0) + dt * G.barrels * W.turns) % 1.0
  local S_ = W.sounds
  if want and not G.wanted then
    if was <= 0.05 then FPF.gunSound98(S_.spin) end
    G.motorAt = S.clock + S_.motorAfter
    G.spins = (G.spins or 0) + 1
  end
  if want and S.clock >= (G.motorAt or 0.0) then
    FPF.gunSound98(S_.motor)
    G.motorAt = S.clock + S_.motorEvery
  end
  if not want and G.wanted then
    FPF.gunStop98(S_.spin, 0.3)
    FPF.gunStop98(S_.motor, 0.3)
    FPF.gunSound98(S_.spinEnd)
  end
  G.wanted = want
  G.cool = (G.cool or 0.0) - dt
  local shooting = firing and want and G.barrels >= 1.0 and G.ammo > 0
  if shooting then
    G.record = FPF.gunRecord(W.record)
    local share = FPC.wreck.gun
    FPC.wreck.gun = share * W.wreck
    local n = 0
    while G.cool <= 0 and G.ammo > 0 and n < 3 do
      local ok, err = pcall(fireRound, ent)
      if not ok then
        FPC.wreck.gun = share
        error(err, 0)
      end
      G.cool = G.cool + 1.0 / FPF.gunRate()
      PF.aimDip = W.dip
      n = n + 1
    end
    FPC.wreck.gun = share
    if G.cool < 0 then G.cool = 0.0 end
    if P.gunSound > 0 and S.clock >= (G.loopAt or 0.0) then
      local d = S.driving and 0.0 or FPF.gunHeard()
      G.loopRow = (d >= S_.farFrom) and S_.loopFar or ((d >= S_.midFrom) and S_.loopMid or S_.loop)
      FPF.gunSound98(G.loopRow)
      G.loopAt = S.clock + S_.loopEvery
    end
    if P.gunSound > 0 and S.clock >= (G.shellsAt or 0.0) then
      FPF.gunSound98(S_.shells)
      G.shellsAt = S.clock + S_.shellsEvery
    end
    if not G.shooting then
      G.bursts = (G.bursts or 0) + 1
      if G.bursts <= 4 then log(string.format("PREDATOR CANNON: firing (burst %d; the barrels turned up after %.2f s)", G.bursts, spinUp)) end
    end
  else
    if G.cool < 0 then G.cool = 0.0 end
    if G.shooting and G.loopRow then FPF.gunStop98(G.loopRow, 0.15) end
    G.loopAt, G.shellsAt = 0.0, 0.0
  end
  G.shooting = shooting
end

function FPF.predBurst(G, engaged)
  local K = FPC.perk.pred
  if not engaged then
    G.aiTill, G.aiRest = nil, nil
    return false
  end
  if G.aiRest then
    if S.clock < G.aiRest then return false end
    G.aiRest = nil
  end
  if not G.aiTill then G.aiTill = G.shots + math.random(K.burst[1], K.burst[2]) end
  if G.shots >= G.aiTill then
    G.aiTill, G.aiRest = nil, S.clock + K.rest[1] + math.random() * (K.rest[2] - K.rest[1])
    return false
  end
  return true
end

FPF.fxRound97 = FPF.fxRound
function FPF.fxRound(m, dx, dy, dz, hx, hy, hz, kind)
  if PS.weapon ~= "rail" then return FPF.fxRound97(m, dx, dy, dz, hx, hy, hz, kind) end
  local E = FPC.guns.rail.fx
  local yaw, pitch = math.deg(math.atan2(-dx, dy)), math.deg(math.asin(clamp(dz, -1.0, 1.0)))
  FPF.fxAt(PF.shown and E.muzzleFp or E.muzzle, m.x, m.y, m.z, yaw, pitch)
  FPF.fxAt(E.trail, m.x, m.y, m.z, yaw, pitch, hx, hy, hz)
  if kind ~= "nothing" then
    FPF.fxAt(FPF.fxPath("impact"), hx - dx * 0.05, hy - dy * 0.05, hz - dz * 0.05, wrap180(yaw + 180.0), -pitch)
  end
end

function FPF.fpGun(dt)
  local w = PS.weapon
  if w ~= "rail" and w ~= "pred" or not FP.aim then return end
  local G, W = PS.gun, FPC.guns[w]
  if not G then return end
  local free = not G.anim and not PS.punch and not PS.pound and not (PS.vortex and PS.vortex.on) and (PF.sprintW or 0.0) < 0.35
  local aim = free and S.driving and ((PS.zoom and not PS.auto) or (w == "pred" and PS.fire))
  local t = PF.aimT or 0.0
  if aim then
    t = math.min(FP.aim, t + dt * ((w == "pred" and PS.fire and not PS.zoom) and W.into or 1.0))
  else
    t = math.max(0.0, t - dt * FP.aim / ((w == "pred") and W.out or 0.2))
  end
  if aim and (PF.aimT or 0.0) <= 0.0 and w == "pred" then FPF.gunSound98(W.sounds.aim) end
  if not aim and (PF.aimT or 0.0) > 0.0 and t <= 0.0 and w == "pred" then FPF.gunSound98(W.sounds.unaim) end
  PF.aimT = t
  local dip = PF.aimDip or 0.0
  if dip > 0.0 then PF.aimDip = math.max(0.0, dip - dt * 0.6) end
  FPF.var("fp_aim", (t > 0.0) and 1.0 or 0.0)
  FPF.var("fp_time_aim", math.max(0.0, t - dip))
  if w == "pred" then
    FPF.var("fp_spin", 1.0)
    FPF.var("fp_time_spin", G.turn or 0.0)
  end
end

FPF.rest97 = FPF.rest
function FPF.rest()
  FPF.rest97()
  if FP.aim then
    FPF.var("fp_aim", 0.0)
    FPF.var("fp_time_aim", 0.0)
    PF.aimT, PF.aimDip = 0.0, 0.0
  end
  if FP.spin then FPF.var("fp_spin", 1.0) end
end

function FPF.gunsFrame(dt)
  if PS.weapon == "pred" then
    local Z = FPC.guns.pred.zoom
    ZOOM.fov = (FPF.perk("predator") > 0) and Z.tight or Z.fov
  end
  if not PS.ent and PS.gun and (PS.gun.shooting or PS.gun.wanted or PS.gun.charging) then
    local G = PS.gun
    for _, W in pairs(FPC.guns) do
      if W.sounds then
        for _, k in ipairs({ "loop", "loopMid", "loopFar", "spin", "motor", "charge" }) do FPF.gunStop98(W.sounds[k], 0.2) end
      end
    end
    G.shooting, G.wanted, G.charging = false, false, false
  end
end

for _, name in ipairs({ "bt7274_rail_tp_low", "bt7274_rail_tp_high", "bt7274_rail_tp_far" }) do FPC.side.rows[name] = { k = 2, at = "body" } end
for _, name in ipairs({ "bt7274_pred_loop", "bt7274_pred_loop_mid", "bt7274_pred_loop_far" }) do FPC.side.rows[name] = { k = 1, at = "body" } end

function FPF.skateBegins(dashing, dashBefore, amount, air)
  if amount <= 0 or air or PS.power <= 0.0 then
    PS.skateArm = nil
    return false
  end
  local pushEnd = not dashing and dashBefore ~= nil and dashBefore < TF.dodgeTime
  if not P.skateHold then return pushEnd end
  local A = PS.skateArm
  if A and not FPF.dashHeld() then
    PS.skateArm, A = nil, nil
  end
  if not A or not pushEnd then return false end
  PS.skateArm = nil
  PS.skateSure = S.clock + FPC.perk.skate.hold
  return true
end

FPF.skateStep98 = FPF.skateStep
function FPF.skateStep(dt, amount, dashing, dashBefore, air)
  local Sk = PS.skate
  if Sk and Sk.sure then
    if S.clock >= Sk.sure then
      Sk.sure = nil
    elseif not FPF.dashHeld() then
      PS.skateEnds = (PS.skateEnds or 0) + 1
      if PS.skateEnds <= 8 then
        log(string.format("SKATE %d is over: the dash key let go %.2f s into it, before it held - a dash after all", Sk.n, S.clock - Sk.from))
      end
      PS.skate = nil
      if PS.dashT ~= nil then PS.dashT = TF.dodgeTime end
      PS.skateW = 0.0
      PS.skateEarly = (PS.skateEarly or 0) + 1
    end
  end
  local before = PS.skate
  PS.skateSure = nil
  local r = FPF.skateStep98(dt, amount, dashing, dashBefore, air)
  if PS.skate and PS.skateSure and PS.skate ~= before then PS.skate.sure = PS.skateSure end
  PS.skateSure = nil
  if Sk and PS.skate ~= Sk then pcall(FPF.skateQuiet, Sk) end
  return r
end

FPC.skateFx.loop = { "bt7274_skate_loop_1", "bt7274_skate_loop_2", "bt7274_skate_loop_3" }
FPC.skateFx.loopEvery = 5.4
FPC.skateFx.scrape = { start = "v_military_dst_truck_scrape_start", stop = "v_military_dst_truck_scrape_stop" }
for _, name in ipairs(FPC.skateFx.loop) do FPC.placedRows[name] = true end

FPF.skateFx98 = FPF.skateFx
function FPF.skateFx(Sk)
  FPF.skateFx98(Sk)
  local E = FPC.skateFx
  if S.clock >= (Sk.loopAt or 0.0) then
    Sk.loopAt = S.clock + E.loopEvery
    Sk.loopN = (Sk.loopN or 0) % #E.loop + 1
    local ok, played = pcall(FPF.tf, E.loop[Sk.loopN])
    if ok and played then PS.skateLoops = (PS.skateLoops or 0) + 1 end
  end
  if not Sk.scraping and P.sounds and PS.ent and IsDefined(PS.ent) then
    local ent = PS.ent
    Sk.scraping = pcall(function() OP77.nativeSound("titan", nil, E.scrape.start) GameObject.PlaySoundEvent(ent, E.scrape.start) end)
    Sk.scrapeOn = Sk.scraping and ent or nil
    if Sk.scraping then PS.skateScrapes = (PS.skateScrapes or 0) + 1 end
  end
end

