  S.phoneAsk = nil
  if S.clock - at > 5.0 then return end
  S.phoneCalls = (S.phoneCalls or 0) + 1
  if S.phoneCalls <= 8 then log(string.format("the phone: BT's contact called (%d) - the call key's call", S.phoneCalls)) end
  if S.driving then return end
  guard("the call", FPF.callBt, "the phone")
end

P.eyeLight = true
FPC.eyeLight = { lights = { "bt7274_eye_light", "bt7274_eye_glow" }, every = 0.25 }

function FPF.eyeFrame()
  local ent = PS.ent
  if not ent or not IsDefined(ent) then
    PS.eyeOn, PS.eyeFor = nil, nil
    return
  end
  if S.clock < (PS.eyeAt or 0.0) and PS.eyeFor == PS.id then return end
  PS.eyeAt = S.clock + FPC.eyeLight.every
  local H = PS.hp
  local dark = (not P.eyeLight) or PS.kneel ~= nil or (PS.act ~= nil and PS.act.kind == "death")
    or (H ~= nil and (H.health <= 0.0 or H.gone == true))
  local want = not dark
  if PS.eyeOn == want and PS.eyeFor == PS.id then return end
  local n = 0
  for _, name in ipairs(FPC.eyeLight.lights) do
    local ok = pcall(function()
      local comp = ent:FindComponentByName(name)
      if not pcall(function() comp:ToggleLight(want) end) then comp:Toggle(want) end
    end)
    if ok then n = n + 1 end
  end
  PS.eyeOn, PS.eyeFor = want, PS.id
  PS.eyeSaid = (PS.eyeSaid or 0) + 1
  if PS.eyeSaid <= 8 then
    log(string.format("BT's eye: its light %s (%d of its %d lights%s)", want and "on" or "off", n, #FPC.eyeLight.lights,
      (n < #FPC.eyeLight.lights) and " - the archive loaded is older than t99" or ""))
  end
end

FPC.railFx = { muzzle = "bt7274_rail_muzzle", charge = "bt7274_rail_charge", muzzleFp = "bt7274_rail_muzzle_fp", chargeFp = "bt7274_rail_charge_fp" }

function FPF.entFx(ent, name, on)
  if not ent or not IsDefined(ent) or not P.fxOn then return false end
  local ok = pcall(function()
    if on == false then
      OP77.effectEvent(ent, name, "stop")
      GameObjectEffectHelper.StopEffectEvent(ent, CName.new(name))
    else
      OP77.effectEvent(ent, name, "start")
      GameObjectEffectHelper.StartEffectEvent(ent, CName.new(name), false)
    end
  end)
  if ok and on ~= false then PS.entFxN = (PS.entFxN or 0) + 1 end
  return ok
end

function FPF.railChargeOff()
  FPF.entFx(PS.ent, FPC.railFx.charge, false)
  FPF.entFx(PF.ent, FPC.railFx.chargeFp, false)
end

function FPF.railFrame(G, W, dt, ent, firing)
  local K = FPC.perk.rail
  local ai = not S.driving
  local full = K.charge * FPF.perkValue("railcharge") / (FPF.coreOn() and FPC.perk.core.rate or 1.0)
  G.cool = math.max(0.0, (G.cool or 0.0) - dt)
  local ready = G.ammo > 0 and not G.reloadT and G.cool <= 0.0
  local hold = firing and ready
  local was = G.charge or 0.0
  local level = 1 + math.floor(was * (K.levels - 1) + 1e-6)
  if ai then
    G.trig = false
    if firing and ready and was >= math.min(1.0, K.aiCharge / full) then
      FPF.railShot(G, W, ent, level)
      G.cool = K.every
      return
    end
  elseif not hold and G.trig then
    G.trig = false
    if not PS.fire and ready then
      G.fired = true
      FPF.railShot(G, W, ent, level)
      G.cool = K.every
      return
    end
  end
  if hold then
    if not ai then G.trig = true end
    G.charge = math.min(1.0, was + dt / full)
  else
    G.charge = math.max(0.0, was - dt / W.drain)
  end
  local now = 1 + math.floor(G.charge * (K.levels - 1) + 1e-6)
  if hold and was <= 0.0 then
    FPF.gunSound98(W.sounds.charge)
    G.charging = true
    G.charges = (G.charges or 0) + 1
  end
  if now > (G.level or 1) then FPF.gunSound98((now >= K.levels) and W.sounds.full or W.sounds.tick) end
  if not hold and G.charging then
    G.charging = false
    FPF.gunStop98(W.sounds.charge, 0.3)
    if was > 0.0 then FPF.gunSound98(W.sounds.chargeEnd) end
    FPF.railChargeOff()
  end
  G.level = now
  if hold and S.clock >= (G.fxAt or 0.0) then
    G.fxAt = S.clock + W.fx.chargeEvery
    if FPF.entFx(PF.shown and PF.ent or PS.ent, PF.shown and FPC.railFx.chargeFp or FPC.railFx.charge) then
      PS.railChargeFx = (PS.railChargeFx or 0) + 1
    end
  elseif not hold then
    G.fxAt = 0.0
  end
end

FPC.railWreck = { car = 30.0, big = { 8.0, 12.0, 18.0, 25.0 } }
function FPF.railShot(G, W, ent, level)
  local tier = math.max(1, math.min(4, level - 1))
  G.record, G.tier = FPF.gunRecord(W.records[tier]), tier
  local tf = 0.55 + 0.15 * tier
  local up = FPC.kick.up
  FPC.kick.up = up * tf
  PS.railWreckTier = tier
  local ok, err = pcall(fireRound, ent)
  PS.railWreckTier = nil
  FPC.kick.up = up
  if not ok then error(err, 0) end
  if P.gunSound > 0 then
    if S.driving then
      FPF.gunSound98(W.sounds.fire[tier])
    else
      FPF.gunSound98((FPF.gunHeard() >= W.sounds.farFrom) and W.sounds.far or W.sounds.tp[tier])
    end
  end
  FPF.gunStop98(W.sounds.charge, 0.1)
  FPF.railChargeOff()
  if PF.shown then FPF.entFx(PF.ent, FPC.railFx.muzzleFp) else FPF.entFx(PS.ent, FPC.railFx.muzzle) end
  G.charging, G.charge, G.level = false, 0.0, 1
  PF.aimDip = W.dip
  FPF.recoilKick("rail", tf)
  PS.railShots = (PS.railShots or 0) + 1
  if PS.railShots <= 6 then
    log(string.format("RAILGUN shot %d: charge level %d of %d (%s), %d rounds left", PS.railShots, level, FPC.perk.rail.levels, G.record, G.ammo))
  end
end

FPF.wreck98 = FPF.wreck
function FPF.wreck(veh, share)
  local tier = PS.railWreckTier
  if tier then
    local big = false
    pcall(function() big = veh:IsA("vehicleAVBaseObject") == true or veh:IsA("vehicleTankBaseObject") == true end)
    share = FPC.wreck.gun * (big and FPC.railWreck.big[tier] or FPC.railWreck.car)
    PS.railWrecks = (PS.railWrecks or 0) + 1
    if PS.railWrecks <= 6 then
      log(string.format("RAILGUN on a vehicle (%s%s): %.0f %% of its health taken off", FPF.vehicleText(veh), big and ", an AV or a tank" or "", share))
    end
  end
  return FPF.wreck98(veh, share)
end

FPF.fxRound98 = FPF.fxRound
function FPF.fxRound(m, dx, dy, dz, hx, hy, hz, kind)
  if PS.weapon ~= "rail" then return FPF.fxRound98(m, dx, dy, dz, hx, hy, hz, kind) end
  local E = FPC.guns.rail.fx
