end

FPC.poundSounds = { slam = "bt7274_pound_slam", land = { "bt7274_pound_land_1", "bt7274_pound_land_2", "bt7274_pound_land_3", "bt7274_pound_land_4" } }

FPF.slam98 = FPF.slam
function FPF.slam(J)
  if not (J and J.pound) then return FPF.slam98(J) end
  local K = FPC.slam
  local rec, wreck = PS.slamRec, K.wreck
  PS.slamRec, K.wreck = FPF.gunRecord(PUNCH.attack), FPC.wreck.punch
  local ok, r = pcall(FPF.slam98, J)
  PS.slamRec, K.wreck = rec, wreck
  if not ok then error(r, 0) end
  if P.sounds then
    local L = FPC.poundSounds
    PS.poundSoundN = (PS.poundSoundN or 0) % #L.land + 1
    local a1, a2 = pcall(FPF.tf, L.slam)
    local b1, b2 = pcall(FPF.tf, L.land[PS.poundSoundN])
    if (a1 and a2) or (b1 and b2) then PS.poundHeard = (PS.poundHeard or 0) + 1 end
  end
  if (PS.pounds or 0) <= 8 then
    log(string.format("GROUND POUND %d: its shock hits as the punch does (%s; a vehicle %.0f %%), with its slam to hear", PS.pounds or 0,
      FPF.gunRecord(PUNCH.attack), FPC.wreck.punch))
  end
  return r
end

