FPC.hazard.fireQuiet = [[titan\bt7274\fx\bt_fire_quiet.effect]]
FPC.hazard.quietNear = 8.0

function FPF.fireLoud(x, y)
  for _, Z in ipairs(PS.hazards or {}) do
    if Z.kind == "fire" and Z.loud and not Z.ended and (x - Z.x) ^ 2 + (y - Z.y) ^ 2 <= FPC.hazard.quietNear ^ 2 then return false end
  end
  return true
end

function FPF.fpParts(on)
  if not on then
    if PF.partsTook then return end
    local took = {}
    for _, h in ipairs({ { PF.ent, FPC.parts }, { PF.cock, { FPC.cockpitPart } } }) do
      local ent, names = h[1], h[2]
      if ent and IsDefined(ent) then
        for _, name in ipairs(names) do
          pcall(function()
            local comp = ent:FindComponentByName(name)
            if comp and comp:IsEnabled() then
              comp:Toggle(false)
              took[#took + 1] = { ent = ent, name = name }
            end
          end)
        end
      end
    end
    PF.partsTook = took
    PF.partSets = (PF.partSets or 0) + 1
    if PF.partSets <= 3 then log(string.format("FIRST PERSON: on the camera's way to the eye its objects ride along with %d meshes switched off", #took)) end
    return
  end
  local took = PF.partsTook
  if not took then return end
  PF.partsTook = nil
  local n = 0
  for _, t in ipairs(took) do
    local want = true
    if t.name == "bt7274_fp_mag" then want = PF.magOn ~= false end
    if t.name == FPC.pod.part then want = PF.pod ~= nil and PF.pod.on == true end
    if want and t.ent and IsDefined(t.ent) and pcall(function() t.ent:FindComponentByName(t.name):Toggle(true) end) then n = n + 1 end
  end
  PF.partBacks = (PF.partBacks or 0) + 1
  if PF.partBacks <= 3 then log(string.format("FIRST PERSON: %d meshes of its objects on again", n)) end
end

function FPF.preRide(x, y, z, yaw, pitch, roll)
  if not PF.ent or not IsDefined(PF.ent) then return end
  FPF.fpParts(false)
  local port = Game.GetTeleportationFacility()
  local at, turn = Vector4.new(x, y, z, 1.0), EulerAngles.new(roll or 0, pitch, yaw)
  port:Teleport(PF.ent, at, turn)
  if PF.cock and IsDefined(PF.cock) then port:Teleport(PF.cock, at, turn) end
  PF.preRiding, PF.preRideAt = true, S.clock
  PF.preRides = (PF.preRides or 0) + 1
end

function FPF.preRideFrame()
  if not PF.preRiding or PF.shown or S.clock - (PF.preRideAt or 0.0) < 0.1 then return end
  PF.preRiding = nil
  for _, h in ipairs({ PF.ent, PF.cock }) do
    if h and IsDefined(h) then
      pcall(function() Game.GetTeleportationFacility():Teleport(h, Vector4.new(PS.x, PS.y, PS.z - FPC.sink, 1.0), EulerAngles.new(0, 0, 0)) end)
    end
  end
  FPF.fpParts(true)
end

