P.restWatch = 0
FPC.restHands = { hand_l = { -3.24, -0.26, 4.71 }, hand_r = { 3.24, -0.26, 4.71 } }

function FPF.restParts()
  local legs = restPose() == true
  local arms = true
  local r = math.rad(PS.yaw)
  for name, want in pairs(FPC.restHands) do
    local h = slotWorld(name)
    if not h then
      arms = false
      break
    end
    local dx, dy = h.x - PS.x, h.y - PS.y
    local right, ahead = dx * math.cos(r) + dy * math.sin(r), dx * -math.sin(r) + dy * math.cos(r)
    if math.abs(right - want[1]) > 0.15 or math.abs(ahead - want[2]) > 0.15 or math.abs(h.z - PS.z - want[3]) > 0.15 then
      arms = false
      break
    end
  end
  return legs, arms
end

function FPF.restWatch()
  if not PS.ent or PS.warm or (PS.restN or 0) >= P.restWatch then return end
  local legs, arms = FPF.restParts()
  if not legs and not arms then
    PS.restRun = nil
    return
  end
  PS.restRun = (PS.restRun or 0) + 1
  if PS.restRun > 1 then
    if PS.restRun == 30 then log(string.format("REST POSE %d (T-pose) still there after 30 frames", PS.restN or 0)) end
    return
  end
  PS.restN = (PS.restN or 0) + 1
  local v = PS.sentVal or {}
  local function g(k) return v[k] or 0.0 end
  log(string.format("REST POSE %d (T-pose): %s in the rig's rest pose - %s, mode %s%s%s; the graph was told: pilot %.2f, scene %.2f (clip %.1f at %.2f s), move %.2f, sprint %.2f, dash %.2f (%.2f s), jump %.2f, land %.2f, melee %.2f (clip %.1f at %.2f s), reload %.2f (clip %.1f at %.2f s), vortex %.2f, pods %.2f, turn %.2f (clip %.1f), stance %.2f, settled %.2f; the gun %s; view %s",
    PS.restN, (legs and arms) and "BT's whole skeleton" or (legs and "BT's legs (its left foot)" or "BT's arms (both hands spread out)"),
    S.driving and "piloted" or (PS.buddy and "on its own" or "waiting"), tostring(PS.mode),
    PS.act and (", act " .. tostring(PS.act.kind)) or "", PS.jump and (", jump " .. tostring(PS.jump.stage)) or "",
    g("bt_pilot"), g("bt_scene"), g("bt_scene_clip"), g("bt_time_scene"), g("bt_move"), g("bt_sprint"), g("bt_dash"), g("bt_time_dash"),
    g("bt_jump"), g("bt_land"), g("bt_melee"), g("bt_melee_clip"), g("bt_time_melee"), g("bt_reload"), g("bt_reload_clip"), g("bt_time_reload"),
    g("bt_vortex"), g("bt_pods"), g("bt_turn"), g("bt_turn_clip"), g("bt_stance"), g("bt_settled"), FPF.gunNamed(), PF.shown and "first person" or "third person"))
end

