FPC.vGuard = { every = 0.1, godEvery = 0.5, margin = 1.0, reach = 4.0,
  types = { "Electrocuted", "EMP", "Burning", "Poisoned", "Bleeding", "Stunned", "Blind", "Knockdown", "Stagger", "CPOShocked" } }

function FPF.vGuardFrame()
  if not S.driving or not PS.godOn then return end
  if S.clock < (S.vGuardAt or 0.0) then return end
  S.vGuardAt = S.clock + FPC.vGuard.every
  local player = Game.GetPlayer()
  if not player then return end
  if S.clock >= (S.vGodAt or 0.0) then
    S.vGodAt = S.clock + FPC.vGuard.godEvery
    local has = true
    pcall(function() has = Game.GetGodModeSystem():HasGodMode(player:GetEntityID(), gameGodModeType.Invulnerable) == true end)
    if not has then
      PS.godOn = false
      FPF.god(true)
      S.vGodBack = (S.vGodBack or 0) + 1
      if S.vGodBack <= 6 then
        log(string.format("V aboard: V's protection from harm was gone (%d) - something else took the god mode away; put back", S.vGodBack))
      end
    end
  end
  for _, name in ipairs(FPC.vGuard.types) do
    local kind = nil
    pcall(function() kind = gamedataStatusEffectType[name] end)
    if kind ~= nil then
      local on = false
      pcall(function() on = StatusEffectSystem.ObjectHasStatusEffectOfType(player, kind) == true end)
      if on then
        pcall(function() StatusEffectHelper["StatusEffectHelper::RemoveAllStatusEffectsByType;GameObjectgamedataStatusEffectType"](player, kind) end)
        S.vStrips = (S.vStrips or 0) + 1
        if S.vStrips <= 12 then log(string.format("V aboard: the game put %s on V - taken off again (V is out of harm's way in BT)", name)) end
      end
    end
  end
end

function FPF.attackReach(record)
  S.attackReach = S.attackReach or {}
  local r = S.attackReach[record]
  if r == nil then
    r = FPC.vGuard.reach
    pcall(function()
      local v = TweakDB:GetFlat(record .. ".range")
      if type(v) == "number" and v > 0.0 then r = v end
    end)
    S.attackReach[record] = r
  end
  return r
end

function FPF.vNear(record, x, y, z)
  if not S.driving or not PS.under or not record or PS.mode ~= "pilot" then return false end
  local near, d = false, 0.0
  pcall(function()
    local v = Game.GetPlayer():GetWorldPosition()
    d = math.sqrt((v.x - x) ^ 2 + (v.y - y) ^ 2 + (v.z + 0.9 - z) ^ 2)
    near = d < FPF.attackReach(record) + FPC.vGuard.margin
  end)
  if near then
    S.vSkips = (S.vSkips or 0) + 1
    if S.vSkips <= 6 then
      log(string.format("V aboard: an area attack of %s %.1f m from V's body (its reach %.1f m) is not started - the hit on whom it was for still goes out",
        record, d, FPF.attackReach(record)))
    end
  end
  return near
end

FPF.attack99 = FPF.attack
function FPF.attack(record, x, y, z)
  if FPF.vNear(record, x, y, z) then return false end
  return FPF.attack99(record, x, y, z)
end

FPC.pierce = { radius = 1.2, vehicle = 2.5 }

function FPF.railWall(m, dx, dy, dz, range)
  local best = range
  for _, group in ipairs({ "Static", "Terrain" }) do
    pcall(function()
      local from = Vector4.new(m.x, m.y, m.z, 1.0)
      local to = Vector4.new(m.x + dx * range, m.y + dy * range, m.z + dz * range, 1.0)
      local hit, res = FPF.sqs():SyncRaycastByCollisionGroup(from, to, group, nil, false, false)
      if hit and res and res.position then
        local d = math.sqrt((res.position.x - m.x) ^ 2 + (res.position.y - m.y) ^ 2 + (res.position.z - m.z) ^ 2)
        if d < best then best = d end
      end
    end)
  end
  return best
end

function FPF.entKey(ent)
  local k = nil
  pcall(function() k = tostring(ent:GetEntityID()) end)
  return k
end

function FPF.railPierce(m, dx, dy, dz, t, first, kind)
  if FPF.perk("railgun") < 1 then return end
  local K, G = FPC.perk.rail, PS.gun
  local firstKey = first and FPF.entKey(first) or nil
  local stop = FPF.railWall(m, dx, dy, dz, FPF.gunRange())
  PS.npcsAt = -10
  refreshNpcs()
  local along = {}
  local function near(cx, cy, cz, r)
    local s = (cx - m.x) * dx + (cy - m.y) * dy + (cz - m.z) * dz
    if s < 0.5 or s > stop + r then return nil end
    local px, py, pz = m.x + dx * s, m.y + dy * s, m.z + dz * s
    if (cx - px) ^ 2 + (cy - py) ^ 2 + (cz - pz) ^ 2 > r * r then return nil end
    return s, px, py, pz
  end
  for i, ent in ipairs(PS.npcs) do
    if IsDefined(ent) and (firstKey == nil or FPF.entKey(ent) ~= firstKey) then
      pcall(function()
        local p = ent:GetWorldPosition()
        local shape = PS.npcShape[i]
        local up = shape and ((shape[3] or 0.0) + shape[2] * 0.55) or 1.0
        local s, px, py, pz = near(p.x, p.y, p.z + up, FPC.pierce.radius + (shape and shape[1] * 0.5 or 0.0))
        if s then along[#along + 1] = { ent = ent, s = s, x = px, y = py, z = pz, kind = "person" } end
      end)
    end
  end
  for _, veh in ipairs(FPF.vehicles()) do
    if IsDefined(veh) and (firstKey == nil or FPF.entKey(veh) ~= firstKey) then
      pcall(function()
        local p = veh:GetWorldPosition()
        local s, px, py, pz = near(p.x, p.y, p.z + 0.7, FPC.pierce.vehicle)
        if s then along[#along + 1] = { ent = veh, s = s, x = px, y = py, z = pz, kind = "vehicle" } end
      end)
    end
  end
  table.sort(along, function(a, b) return a.s < b.s end)
  local n, people, cars = 0, 0, 0
  for _, T in ipairs(along) do
    if n >= K.pierce - 1 then break end
    n = n + 1
    if T.kind == "person" then
      FPF.railHit(T.ent, T.x, T.y, T.z, dx, dy, dz)
      people = people + 1
    else
      FPF.wreck(T.ent, FPC.wreck.gun)
      cars = cars + 1
    end
    if P.fxOn then FPF.fxAt(FPF.fxPath("impact"), T.x - dx * 0.05, T.y - dy * 0.05, T.z - dz * 0.05, wrap180(math.deg(math.atan2(-dx, dy)) + 180.0), 0.0) end
  end
  G.pierced = n
  if n > 0 then
    PS.pierced = (PS.pierced or 0) + n
    PS.pierceLines = (PS.pierceLines or 0) + 1
    if PS.pierceLines <= 6 then
      log(string.format("RAILGUN: PIERCING SHOT - the bolt flew %.0f m (%s first) and went through %d more: %d people, %d vehicles",
        stop, tostring(kind or "?"), n, people, cars))
    end
  end
end

FPC.hazard.gasHurt = "Attacks.BT7274_Gas"

function FPF.statusBy(ent, status, by)
  local id = TweakDBID.new(status)
  if by ~= nil and pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDEntityID"](ent, id, by) end) then return end
  StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, id)
end

function FPF.hazardsFrame()
  local L = PS.hazards
  if not L or #L == 0 then return end
  local by = nil
  pcall(function() by = Game.GetPlayer():GetEntityID() end)
  for i = #L, 1, -1 do
    local Z = L[i]
    local age = S.clock - Z.at
    if age >= Z.life + FPC.hazard.linger or not PS.ent then
      for _, inst in ipairs(Z.fx) do FPF.fxKill152(inst) end
      table.remove(L, i)
    elseif age >= Z.life then
      if not Z.ended then
        Z.ended = true
        for _, inst in ipairs(Z.fx) do FPF.fxBreak152(inst) end
      end
    elseif S.clock >= Z.tickAt then
      local K = (Z.kind == "fire") and FPC.perk.incendiary or FPC.perk.gas
      Z.tickAt = S.clock + K.tick
      PS.npcsAt = -10
      refreshNpcs()
      local rec = nil
      if Z.kind == "gas" and P.damage and FPF.gunRecord(FPC.hazard.gasHurt) == FPC.hazard.gasHurt then rec = FPC.hazard.gasHurt end
      for _, ent in ipairs(PS.npcs) do
        if IsDefined(ent) then
          pcall(function()
            if not ScriptedPuppet.IsActive(ent) then return end
            local p = ent:GetWorldPosition()
            if math.sqrt((p.x - Z.x) ^ 2 + (p.y - Z.y) ^ 2) > Z.wide * 0.5 or p.z < Z.z - 2.0 or p.z > Z.z + FPC.hazard.high then return end
            if rec then
              local send = P.fullHits and FPF.hitFull or FPF.hit
              if send(ent, rec, p.x, p.y, p.z + 1.0, 0.0, 0.0, -1.0) == true then Z.hurts = (Z.hurts or 0) + 1 end
            end
            local key = tostring(ent:GetEntityID())
            if Z.seen[key] and S.clock - Z.seen[key] < K.again then return end
            Z.seen[key] = S.clock
            FPF.statusBy(ent, K.status, by)
            if Z.blinds then FPF.statusBy(ent, K.blind, by) end
            Z.hits = Z.hits + 1
          end)
        end
      end
      if rec and (Z.hurts or 0) > 0 and not Z.hurtSaid then
        Z.hurtSaid = true
        PS.gasLines = (PS.gasLines or 0) + 1
        if PS.gasLines <= 6 then log(string.format("GAS: the cloud hurts whoever is in it every %.1f s (%s)", K.tick, rec)) end
      end
    end
  end
end

do
  local n, list = #SCENE_HIP, {}
  for i = 1, n - 1, 2 do list[#list + 1] = i + 0.5 end
  if n % 2 == 1 then list[#list + 1] = n - 0.5 end
  FPC.warmScenes = list
end

function FPF.getupClip(A, t)
  local D = SCENES.drop
  if A.dropped and D.getupFrom and not A.fromKneel then return D.clip, D.getupFrom + t end
  return SCENES.getup.clip, t
end

FPC.fpReloadFade = 0.3

function FPF.fpHot()
  local G = PS.gun
  if not S.driving or PS.auto or not FP.aim then return false end
  if PS.zoom then return true end
  return PS.weapon == "pred" and (PS.fire or (G ~= nil and (G.barrels or 0.0) > 0.3))
end

FPF.fpGun99 = FPF.fpGun
function FPF.fpGun(dt)
  local G = PS.gun
  if FP.aim and G and G.anim and G.anim < FPC.fpReloadFade and (PS.weapon == "rail" or PS.weapon == "pred") then
    local t = PF.aimT or 0.0
    FPF.var("fp_aim", (t > 0.0) and 1.0 or 0.0)
    FPF.var("fp_time_aim", math.max(0.0, t - (PF.aimDip or 0.0)))
    return
  end
  return FPF.fpGun99(dt)
end

FPF.view99 = FPF.view
function FPF.view(dt)
  local was = PF.shown
  FPF.view99(dt)
  if PF.shown and not was and FPF.fpHot() then
    PF.raiseT = nil
    PF.aimT = FP.aim
    FPF.var("fp_raise", 0.0)
    FPF.var("fp_aim", 1.0)
    FPF.var("fp_time_aim", FP.aim)
    PF.hot = (PF.hot or 0) + 1
    if PF.hot <= 4 then log(string.format("FIRST PERSON while %s: the view model comes on in its aimed pose (no raise from below)", FPF.gunNamed())) end
  end
end

FPC.poundRadial = { zones = { 1.0 / 3.0, 2.0 / 3.0, 1.0 }, records = { false, "Attacks.BT7274_Pound_Mid", "Attacks.BT7274_Pound_Edge" },
  wreck = { 1.0, 0.6, 0.3 } }

function FPF.poundZone(dist, reach)
  local Z = FPC.poundRadial.zones
  if dist <= reach * Z[1] then return 1 end
  if dist <= reach * Z[2] then return 2 end
  return 3
end

function FPF.poundSlam(J)
  local K, JK, G, R = FPC.slam, FPC.jump, FPC.perk.pound, FPC.poundRadial
  local reach, down, power = K.reach * G.wide, K.down * G.wide, K.power * G.push
  local ring, puffs = K.ring * G.wide, math.floor(K.puffs * G.wide + 0.5)
  local fell = (J.z0 + J.top) - PS.z
  local x, y, z = PS.x, PS.y, PS.z
  local shown = 0
  if P.fxOn then
    local path = FPF.fxPath("land")
    if path and FPF.fxAt(path, x, y, z + 0.05, PS.yaw, 0.0) then shown = shown + 1 end
    local dust = FPF.fxPath("step")
    if dust then
      for i = 1, puffs do
        local a = (i - 1) / puffs * 2.0 * math.pi
        if FPF.fxAt(dust, x + math.cos(a) * ring, y + math.sin(a) * ring, z + 0.05, math.deg(a), 0.0) then shown = shown + 1 end
      end
    end
  end
  local punch = FPF.gunRecord(PUNCH.attack)
  local function own(name)
    local r = FPF.gunRecord(name)
    return (r == name) and r or punch
  end
  local recs = { punch, own(R.records[2]), own(R.records[3]) }
  local thrown, hit, shaken, zones = 0, 0, 0, { 0, 0, 0 }
  PS.npcsAt = -10
  refreshNpcs()
  for i, ent in ipairs(PS.npcs) do
    if IsDefined(ent) then
      pcall(function()
        local p = ent:GetWorldPosition()
        local rx, ry = p.x - x, p.y - y
        local dist = math.sqrt(rx * rx + ry * ry)
        if dist >= reach or math.abs(p.z - z) >= 3.5 then return end
        local n = math.max(dist, 0.1)
        local ux, uy = rx / n, ry / n
        local big = PS.npcShape[i] and true or false
        if dist >= JK.stomp and dist < down and not big and P.solid then
          pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(FPC.solid.knock)) end)
          FPF.ragdoll(ent, p.x - ux * 0.5, p.y - uy * 0.5, p.z + 0.6, ux, uy, power * (1.0 - 0.5 * dist / down))
          PS.bumped[tostring(ent:GetEntityID())] = S.clock
          thrown = thrown + 1
        end
        if P.damage then
          local zi = FPF.poundZone(dist, reach)
          local send = P.fullHits and FPF.hitFull or FPF.hit
          if send(ent, recs[zi], p.x, p.y, p.z + 0.9, ux, uy, 0.0) == true then
            hit = hit + 1
            zones[zi] = zones[zi] + 1
          end
        end
      end)
    end
  end
  if P.solid then
    PS.vehiclesAt = -10
    for _, veh in ipairs(FPF.vehicles()) do
      pcall(function()
        local p = veh:GetWorldPosition()
        local dist = math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2)
        if dist >= JK.crush and dist < reach and math.abs(p.z - z) < 3.0 then
          FPF.dent(veh, 0.5, false)
          FPF.wreck(veh, FPC.wreck.punch * R.wreck[FPF.poundZone(dist, reach)])
          shaken = shaken + 1
        end
      end)
    end
  end
  guard("people told", FPF.stim, "Explosion", K.fear, 1.0)
  J.slam = { fell = fell, down = thrown, hit = hit, shaken = shaken, zones = zones }
  PS.slams = (PS.slams or 0) + 1
  PS.poundShocks = (PS.poundShocks or 0) + 1
  if PS.poundShocks <= 8 then
    log(string.format("GROUND POUND %d: its shock all round it, %.1f m - %d people hit (%d / %d / %d in its inner / middle / outer third: the punch's record, 0.6 and 0.3 of it), %d thrown off their feet within %.1f m, %d vehicles (%.0f / %.0f / %.0f %% of their health); its effects started: %d",
      PS.pounds or 0, reach, hit, zones[1], zones[2], zones[3], thrown, down, shaken, FPC.wreck.punch * R.wreck[1], FPC.wreck.punch * R.wreck[2],
      FPC.wreck.punch * R.wreck[3], shown))
  end
  return true
end

function FPF.poundSounds()
  if not P.sounds then return end
  local L = FPC.poundSounds
  PS.poundSoundN = (PS.poundSoundN or 0) % #L.land + 1
  local a1, a2 = pcall(FPF.tf, L.slam)
  local b1, b2 = pcall(FPF.tf, L.land[PS.poundSoundN])
  if (a1 and a2) or (b1 and b2) then PS.poundHeard = (PS.poundHeard or 0) + 1 end
end

FPF.slam99 = FPF.slam
function FPF.slam(J)
  if not (J and J.pound) then return FPF.slam99(J) end
  local r = FPF.poundSlam(J)
  FPF.poundSounds()
  return r
end

FPC.boom.gap = 0.5
FPC.boom.lines = 300

function FPF.doomFrame()
  if not PS.doomed then return end
  local now = S.clock
  local last = PS.boomLast
  if last and last <= now and now - last < FPC.boom.gap then return end
  local pick, pickKey, waiting = nil, nil, 0
  for key, D in pairs(PS.doomed) do
    waiting = waiting + 1
    if now >= D.at and (not pick or D.at < pick.at) then pick, pickKey = D, key end
  end
  if not pick then return end
  PS.doomed[pickKey] = nil
  local veh = pick.veh
  if not IsDefined(veh) then return end
  if FPF.isWreck(veh) then
    PS.boomSkips = (PS.boomSkips or 0) + 1
    once("boomself", "a vehicle whose health this script took to nothing had blown up by the game's own hand a moment later - no second death event for it (since t48)")
    return
  end
  PS.exploded[pickKey] = now
  local speed, big = -1.0, false
  pcall(function() speed = veh:GetCurrentSpeed() end)
  pcall(function() big = veh:IsA("vehicleAVBaseObject") == true or veh:IsA("vehicleTankBaseObject") == true end)
  local ok, err = pcall(function()
    local evt = gameDeathEvent.new()
    evt.instigator = Game.GetPlayer()
    veh:QueueEvent(evt)
  end)
  PS.boomLast = now
  PS.explosions = (PS.explosions or 0) + 1
  if PS.explosions <= FPC.boom.lines then
    log(string.format("a vehicle blows up (%s%s; %s; moving at %.1f m/s; %.2f s after its health was gone; %d more waiting): %s - the script's death event %d this session",
      FPF.vehicleText(veh), big and ", an AV or a tank" or "", tostring(pick.why), speed, now - (pick.at - FPC.boom.wait), waiting - 1,
      ok and "the game took its death event" or ("its death event could NOT be sent: " .. tostring(err)), PS.explosions))
  end
end

FPC.railTrail = { every = 0.06, repeats = { 2, 3, 4, 6 }, bigFrom = 3,
  linger = [[base\fx\weapons\trails\tech\electric_thermal_chemical\w_tech_revolver_trail_electric.effect]],
  boom = [[base\fx\weapons\firearms\special\militech_hmg\w_special_hmg_explosive_bullet.effect]],
  boomBig = [[base\fx\weapons\cyberware\microgenerator_emp_explosion.effect]] }

FPF.railShot100 = FPF.railShot
function FPF.railShot(G, W, ent, level)
  G.shotLevel = level
  local ok, err = pcall(FPF.railShot100, G, W, ent, level)
  G.shotLevel = nil
  if not ok then error(err, 0) end
end

function FPF.railPierces()
  local G = PS.gun
  return FPF.perk("railgun") >= 1 and ((G and G.shotLevel) or FPC.perk.rail.levels) >= FPC.perk.rail.pierceFrom
end

FPF.railPierce100 = FPF.railPierce
function FPF.railPierce(m, dx, dy, dz, t, first, kind)
  if not FPF.railPierces() then
    local G = PS.gun
    if G and FPF.perk("railgun") >= 1 then
      G.pierced = 0
      PS.pierceLow = (PS.pierceLow or 0) + 1
      if PS.pierceLow <= 4 then
        log(string.format("RAILGUN: PIERCING SHOT not for this one - charged to step %d of %d, it pierces from step %d on",
          G.shotLevel or 0, FPC.perk.rail.levels, FPC.perk.rail.pierceFrom))
      end
    end
    return
  end
  return FPF.railPierce100(m, dx, dy, dz, t, first, kind)
end

function FPF.railBoltEnd(m, dx, dy, dz, hx, hy, hz, kind)
  if not FPF.railPierces() then return hx, hy, hz, kind end
  local range = FPF.gunRange()
  local d = FPF.railWall(m, dx, dy, dz, range)
  return m.x + dx * d, m.y + dy * d, m.z + dz * d, (d < range - 0.5) and "wall" or "nothing"
end

FPF.fxRound100 = FPF.fxRound
function FPF.fxRound(m, dx, dy, dz, hx, hy, hz, kind)
  if PS.weapon ~= "rail" then return FPF.fxRound100(m, dx, dy, dz, hx, hy, hz, kind) end
  local E, R = FPC.guns.rail.fx, FPC.railTrail
  local yaw, pitch = math.deg(math.atan2(-dx, dy)), math.deg(math.asin(clamp(dz, -1.0, 1.0)))
  local ex, ey, ez, endKind = FPF.railBoltEnd(m, dx, dy, dz, hx, hy, hz, kind)
  FPF.fxAt(E.trail, m.x, m.y, m.z, yaw, pitch, ex, ey, ez)
  if kind ~= "nothing" then
    FPF.fxAt(FPF.fxPath("impact"), hx - dx * 0.05, hy - dy * 0.05, hz - dz * 0.05, wrap180(yaw + 180.0), -pitch)
  end
  if not P.fxOn then return end
  local G = PS.gun
  local tier = clamp(math.floor((G and G.tier) or 1), 1, #R.repeats)
  PS.railTrails = PS.railTrails or {}
  for i = 1, R.repeats[tier] do
    PS.railTrails[#PS.railTrails + 1] = { at = S.clock + i * R.every, m = { x = m.x, y = m.y, z = m.z }, yaw = yaw, pitch = pitch,
      e = { ex, ey, ez } }
  end
  FPF.fxAt(R.linger, m.x, m.y, m.z, yaw, pitch, ex, ey, ez)
  local boom = nil
  if endKind ~= "nothing" then
    if tier >= R.bigFrom then
      boom = R.boomBig
    elseif (ex - hx) ^ 2 + (ey - hy) ^ 2 + (ez - hz) ^ 2 > 1.0 then
      boom = R.boom
    end
    if boom then FPF.fxAt(boom, ex - dx * 0.3, ey - dy * 0.3, ez - dz * 0.3, wrap180(yaw + 180.0), -pitch) end
  end
  PS.railFxLines = (PS.railFxLines or 0) + 1
  if PS.railFxLines <= 6 then
    log(string.format("RAILGUN's trail (step %d of %d): started %d times more %.2f s apart and its thin line once, %.0f m to where the bolt ends (%s)%s",
      (G and G.shotLevel) or 0, FPC.perk.rail.levels, R.repeats[tier], R.every,
      math.sqrt((ex - m.x) ^ 2 + (ey - m.y) ^ 2 + (ez - m.z) ^ 2), tostring(endKind),
      boom and ("; there the explosion " .. (boom == R.boomBig and "of an EMP blast" or "of an explosive round"))
        or ((endKind == "nothing") and "; no explosion (it met nothing)" or "; its impact is the explosion there (an explosive round's)")))
  end
end

function FPF.railTrailFrame()
  local L = PS.railTrails
  if not L or #L == 0 then return end
  local path = FPC.guns.rail.fx.trail
  for i = #L, 1, -1 do
    local T = L[i]
    if S.clock >= T.at then
      table.remove(L, i)
      if P.fxOn and PS.ent then FPF.fxAt(path, T.m.x, T.m.y, T.m.z, T.yaw, T.pitch, T.e[1], T.e[2], T.e[3]) end
    end
  end
end

function FPF.coreGunWords()
  local rate = FPC.perk.core.rate
  if PS.weapon == "rail" then return string.format("the RAILGUN using no rounds, charging %.2f times as fast", rate) end
  if PS.weapon == "pred" then return string.format("the PREDATOR CANNON using no rounds, firing %.2f times as fast", rate) end
  return string.format("the XO-16 using no rounds, firing %.2f times as fast", rate)
end

function FPF.coreFire(by)
  local C = PS.core
  local need, time = FPF.coreShot()
  if not C or C.left or C.charge < need - 1e-6 then return false end
  C.charge, C.left, C.time, C.fired = C.charge - need, time, time, (C.fired or 0) + 1
  local G = PS.gun
  if G and G.reloadT then G.reloadT, G.ammo, G.cool = nil, FPF.magSize(), 0.0 end
  pcall(FPF.tf, FPC.vortex.sounds.start)
  if C.fired <= 12 then
    log(string.format("BURST CORE %d fires (%s): %.1f s of %s; %.0f of %.0f left in the core", C.fired, by, time, FPF.coreGunWords(),
      C.charge, FPF.coreMax()))
  end
  return true
end

FPC.bring = { carryFor = 30.0 }

function FPF.btFar()
  if not PS.ent then return nil end
  local d = nil
  pcall(function()
    local p = Game.GetPlayer():GetWorldPosition()
    d = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2 + (p.z - PS.z) ^ 2)
  end)
  return d
end

function FPF.bringBt(by)
  local why = nil
  if S.driving then
    why = "V is in BT"
  elseif PS.act then
    why = (PS.act.kind == "leave") and "BT is leaving" or "BT is on its way already"
  elseif PS.hp and PS.hp.down and S.clock < PS.hp.down then
    why = "BT is down"
  elseif PS.kneel or PS.questBt then
    why = "the quest holds BT"
  end
  if why then
    log(string.format("BRING BT (%s): not now - %s", tostring(by), why))
    FPF.callNote({ key = "bt7274_bring_refused", note = "BT-7274 cannot be brought now - " .. why })
    return false
  end
  if not (PS.ent or PS.asked) then
    log(string.format("BRING BT (%s): none is out - an ordinary call", tostring(by)))
    return FPF.callBt(by)
  end
  local H, far = PS.hp, FPF.btFar()
  PS.hpCarry = H and { health = H.health, shield = H.shield, doomed = H.doomed, at = S.clock } or nil
  local anew = P.callAnew
  P.callAnew = true
  local ok, r = pcall(FPF.callBt, by)
  P.callAnew = anew
  if not ok or not r then
    PS.hpCarry = nil
    log(string.format("BRING BT (%s): the call was refused%s - BT stays where it is", tostring(by), ok and "" or (": " .. tostring(r))))
    return false
  end
  PS.brought = (PS.brought or 0) + 1
  log(string.format("BRING BT %d (%s): the BT %s away is taken away and called down at V; its health (%s) and shield come along",
    PS.brought, tostring(by), far and string.format("%.0f m", far) or "?", H and string.format("%.0f", H.health) or "-"))
  return true
end

FPF.hpNew100 = FPF.hpNew
function FPF.hpNew()
  local H = FPF.hpNew100()
  local C = PS.hpCarry
  if C then
    PS.hpCarry = nil
    if S.clock - (C.at or 0.0) <= FPC.bring.carryFor then H.health, H.shield, H.doomed = C.health, C.shield, C.doomed end
  end
  return H
end

P.crumbs = true
FPC.crumbs = { every = 1.0 }

function FPF.crumb(kind, what)
  if not P.crumbs then return end
  local C = PS.crumbs
  if not C then
    C = { n = 0, items = {} }
    PS.crumbs = C
  end
  local key = kind .. " " .. tostring(what)
  C.items[key] = (C.items[key] or 0) + 1
  C.n = C.n + 1
end

function FPF.crumbsFrame()
  local C = PS.crumbs
  if not C or C.n == 0 or S.clock < (C.at or 0.0) then return end
  C.at = S.clock + FPC.crumbs.every
  local parts = {}
  for k, n in pairs(C.items) do parts[#parts + 1] = (n > 1) and string.format("%s x%d", k, n) or k end
  table.sort(parts)
  log("CRUMBS (the last second): " .. table.concat(parts, ", "))
  C.items, C.n = {}, 0
end

