FPF.skateFx101 = FPF.skateFx
function FPF.skateFx(Sk)
  local E = FPC.skateFx
  if not Sk.soundFrom then
    Sk.soundFrom = S.clock + E.soundDelay
    Sk.scrapeFrom = S.clock + E.scrapeDelay
    Sk.soundAt = math.max(Sk.soundAt or 0.0, Sk.soundFrom)
    Sk.loopAt = math.max(Sk.loopAt or 0.0, Sk.soundFrom)
  end
  if S.clock < Sk.scrapeFrom and not Sk.scraping then
    Sk.scraping = true
    Sk.scrapeHeld = true
    local ok, err = pcall(FPF.skateFx101, Sk)
    Sk.scraping, Sk.scrapeHeld = nil, nil
    if not ok then error(err, 0) end
    return
  end
  return FPF.skateFx101(Sk)
end

