FPC.perk.core.bossHit = 0.3
FPC.perk.core.bossMost = 12.0

function FPF.coreBossShare(record)
  if not record then return nil end
  local M = FPC.bossShare
  if not M then
    M = {}
    for _, R in ipairs(FPC.boss) do M[R[1]] = R[2] end
    FPC.bossShare = M
  end
  return M[record]
end

function FPF.coreBossHit(evt, tag)
  if tag ~= "b" or not evt or not PS.ent or not PS.core or FPF.perk("burstcore") < 1 or FPF.coreOn() then return end
  local A, target = evt.attackData, evt.target
  if not A or not target then return end
  local killing = false
  pcall(function() killing = A:HasFlag(hitFlag.WasKillingBlow) == true end)
  if killing then return end
  local mine = false
  pcall(function() mine = tostring(A:GetSource():GetEntityID()) == tostring(PS.ent:GetEntityID()) end)
  if not mine then return end
  local record = nil
  pcall(function() record = TDBID.ToStringDEBUG(A:GetAttackDefinition():GetRecord():GetID()) end)
  local share = FPF.coreBossShare(record)
  if not share then return end
  local _, what = FPF.coreWorth(target)
  if what ~= "a boss" then return end
  local K, C = FPC.perk.core, PS.core
  if not C.bossSec or S.clock - C.bossSec >= 1.0 then
    if (C.bossGot or 0) > 0 then FPF.coreBossLine(C) end
    C.bossSec, C.bossGot, C.bossHits = S.clock, 0.0, 0
  end
  local points = math.min(share * (P.bossMul or 1.0) * 100.0 * K.bossHit, K.bossMost - C.bossGot)
  if points <= 0 then return end
  C.bossGot, C.bossHits = C.bossGot + points, C.bossHits + 1
  C.bossName = nil
  pcall(function() C.bossName = TDBID.ToStringDEBUG(target:GetRecordID()) end)
  C.charge = math.min(FPF.coreMax(), C.charge + points)
  C.bossTotal = (C.bossTotal or 0.0) + points
end

function FPF.coreBossLine(C)
  C.bossLines = (C.bossLines or 0) + 1
  if C.bossLines <= 12 then
    log(string.format("BURST CORE +%.1f from %d hits on a boss in a second (%s) - %.0f of %.0f", C.bossGot, C.bossHits,
      tostring(C.bossName), C.charge, FPF.coreMax()))
  end
end

function FPF.coreBossFrame()
  local C = PS.core
  if C and C.bossSec and S.clock - C.bossSec >= 1.0 and (C.bossGot or 0) > 0 then
    FPF.coreBossLine(C)
    C.bossGot, C.bossHits, C.bossSec = 0.0, 0, nil
  end
end

FPF.hitSeen101 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local ok, err = pcall(FPF.coreBossHit, evt, tag)
  if not ok then once("corebosshit" .. tostring(err), "BURST CORE: a hit on a boss could NOT be counted: " .. tostring(err)) end
  return FPF.hitSeen101(evt, tag)
end
FPC.perk.core.bossBurst = 24.0

-- Open77: the share, budget, points and charge block of FPF.coreBossHit below, taken out of it unchanged. A blow the server
-- confirmed on another player's Titan (open77_titan_gameplay.creditCore) is worth what the same blow is when the game's own hit
-- event brings it, and neither has a second copy of the sums. The gates are those of FPF.coreBossHit's first line. Returns the
-- points of this blow (before P.coreScale: the late wrapper below applies it), or nil and why.
function FPF.coreBossCredit(record, name)
  if not PS.ent then return nil, "no_titan" end
  if not PS.core or FPF.perk("burstcore") < 1 then return nil, "no_core" end
  if FPF.coreOn() then return nil, "core_active" end
  local share = FPF.coreBossShare(record)
  if not share then return nil, "unknown_record" end
  local K, C = FPC.perk.core, PS.core
  if C.bossBudget == nil then
    C.bossBudget = K.bossBurst
  else
    C.bossBudget = math.min(K.bossBurst, C.bossBudget + math.max(0.0, S.clock - (C.bossClock or S.clock)) * K.bossMost)
  end
  C.bossClock = S.clock
  if not C.bossSec or S.clock - C.bossSec >= 1.0 then
    if (C.bossGot or 0) > 0 then FPF.coreBossLine(C) end
    C.bossSec, C.bossGot, C.bossHits = S.clock, 0.0, 0
  end
  local points = math.min(share * (P.bossMul or 1.0) * 100.0 * K.bossHit, C.bossBudget)
  if points <= 1e-6 then return nil, "capped" end
  C.bossBudget = C.bossBudget - points
  C.bossGot, C.bossHits = C.bossGot + points, C.bossHits + 1
  C.bossName = name
  C.charge = math.min(FPF.coreMax(), C.charge + points)
  C.bossTotal = (C.bossTotal or 0.0) + points
  return points
end

function FPF.coreBossHit(evt, tag)
  if tag ~= "b" or not evt or not PS.ent or not PS.core or FPF.perk("burstcore") < 1 or FPF.coreOn() then return end
  local A, target = evt.attackData, evt.target
  if not A or not target then return end
  local killing = false
  pcall(function() killing = A:HasFlag(hitFlag.WasKillingBlow) == true end)
  if killing then return end
  local mine = false
  pcall(function() mine = tostring(A:GetSource():GetEntityID()) == tostring(PS.ent:GetEntityID()) end)
  if not mine then return end
  local record = nil
  pcall(function() record = TDBID.ToStringDEBUG(A:GetAttackDefinition():GetRecord():GetID()) end)
  local share = FPF.coreBossShare(record)
  if not share then return end
  local _, what = FPF.coreWorth(target)
  if what ~= "a boss" then return end
  local name = nil
  pcall(function() name = TDBID.ToStringDEBUG(target:GetRecordID()) end)
  FPF.coreBossCredit(record, name)
end

FPC.punchBig = { up = 3.5 }

function FPF.punchTargets(range, angle)
  local ry = math.rad(S.yaw)
  local fx, fy = -math.sin(ry), math.cos(ry)
  local out = {}
  local function take(ent, kind, lift)
    if not IsDefined(ent) then return end
    local ok, p = pcall(function() return ent:GetWorldPosition() end)
    if not ok or not p then return end
    local r, h, name = 0.0, nil, nil
    if kind == "person" then
      pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
      if type(name) == "string" then
        local okS, shape = pcall(FPF.recordShape, name)
        if okS and shape then r, h = shape[1], shape[2] end
      end
    end
    local dx, dy = p.x - PS.x, p.y - PS.y
    local dist = math.sqrt(dx * dx + dy * dy)
    local near = math.max(0.0, dist - r)
    local wide = (r > 0.0 and dist > 0.01) and math.deg(math.atan2(r, dist)) or 0.0
    local cone = math.cos(math.rad(math.min(89.0, angle + wide)))
    if near <= range and math.abs(p.z - PS.z) < 5.0 and (dist < 1.5 + r or (dx * fx + dy * fy) / dist >= cone) then
      local key = kind .. tostring(#out)
      pcall(function() key = tostring(ent:GetEntityID()) end)
      local n = math.max(dist, 0.01)
      local ux, uy = dx / n, dy / n
      local x, y, z = p.x, p.y, p.z + lift
      if r > 0.0 then
        x, y, z = p.x - ux * r, p.y - uy * r, p.z + math.min(h * 0.5, FPC.punchBig.up)
        once("punchbig" .. tostring(name), string.format("PUNCH: %s is %.1f m wide for the fist (its record says so) - reached by its near side, %.1f m from its middle",
          tostring(name), r * 2.0, r))
      end
      out[#out + 1] = { ent = ent, kind = kind, dist = near, x = x, y = y, z = z, key = key, dx = ux, dy = uy, r = r }
    end
  end
  for _, who in ipairs(PS.npcs) do take(who, "person", 1.0) end
  for _, veh in ipairs(FPF.vehicles()) do take(veh, "vehicle", 0.6) end
  table.sort(out, function(a, b) return a.dist < b.dist end)
  return out
end

function FPF.vWould(record, x, y, z)
  if not S.driving or not PS.under or not record or PS.mode ~= "pilot" then return false end
  local near = false
  pcall(function()
    local v = Game.GetPlayer():GetWorldPosition()
    near = math.sqrt((v.x - x) ^ 2 + (v.y - y) ^ 2 + (v.z + 0.9 - z) ^ 2) < FPF.attackReach(record) + FPC.vGuard.margin
  end)
  return near
end

FPC.punchBig.records = { ["Attacks.BT7274_Punch"] = true }

FPF.hit103 = FPF.hit
function FPF.hit(who, record, x, y, z, dx, dy, dz)
  if P.fullHits and who and record then
    local vehicle = false
    pcall(function() vehicle = who:IsVehicle() == true end)
    local big = not vehicle and FPC.punchBig.records[record] and FPF.bigTarget(who)
    local close = not vehicle and not big and FPF.vWould(record, x, y, z)
    if close or big then
      local name = "?"
      pcall(function() name = TDBID.ToStringDEBUG(who:GetRecordID()) end)
      if big then
        local cx, cy, shape = x, y, nil
        pcall(function()
          local p = who:GetWorldPosition()
          cx, cy = p.x, p.y
        end)
        pcall(function() shape = FPF.recordShape(name) end)
        PS.noBlast = { x = x, y = y, z = z, at = S.clock, record = record, cx = cx, cy = cy, r = shape and shape[1] or 0.0 }
      end
      PS.vFull = (PS.vFull or 0) + 1
      if PS.vFull <= 6 then
        log(close and string.format("V aboard: the area attack beside this hit of %s on %s is left out (V's body within its reach) - the hit goes with its attack type set instead",
            tostring(record), tostring(name))
          or string.format("PUNCH on a big body (%s): its own hit with its attack type set, no blast beside it", tostring(name)))
      end
      return FPF.hitFull(who, record, x, y, z, dx, dy, dz)
    end
  end
  return FPF.hit103(who, record, x, y, z, dx, dy, dz)
end

FPF.attack103 = FPF.attack
function FPF.attack(record, x, y, z)
  local N = PS.noBlast
  if N and N.at == S.clock and record == N.record then
    if (math.abs(N.x - x) < 1e-6 and math.abs(N.y - y) < 1e-6 and math.abs(N.z - z) < 1e-6)
      or math.sqrt((x - N.cx) ^ 2 + (y - N.cy) ^ 2) < N.r + FPF.attackReach(record) then
      N.skipped = (N.skipped or 0) + 1
      return false
    end
  end
  return FPF.attack103(record, x, y, z)
end

FPC.exec = { mods = { "ronin_boss", "slone_boss" }, keys = { kickshoot = "exec_kick", flip_takedown = "exec_flip", pilot_rip = "exec_rip" },
  sounds = { kickshoot = "bt7274_exec_kickshoot", flip_takedown = "bt7274_exec_takedown", pilot_rip = "bt7274_exec_pilotrip" },
  fadeIn = 0.25, turn = 0.25, camIn = 0.35, camOut = 0.6, look = 0.2, chest = 4.0, gap = 0.4, sync = 0.1, late = 0.3,
  hint = { range = 10.5, angle = 60.0, y = 0.64 }, lines = 12 }

function FPF.execPoll()
  local E = PS.exec
  if PS.execOut and (PS.pilotW or 0.0) >= 1.0 then PS.execOut = nil end
  local piloting = S.driving and S.pilot and PS.mode == "pilot" and PS.ent ~= nil and not PS.eject
  PS.execHint = nil
  if not piloting and not E then return end
  local found, foundMod, hint = nil, nil, nil
  for _, name in ipairs(FPC.exec.mods) do
    local st = nil
    pcall(function()
      local m = nil
      if type(m) == "table" and type(m.State) == "function" then st = m.State() end
    end)
    if type(st) == "table" then
      if type(st.execution) == "table" and not found then found, foundMod = st.execution, name end
      if piloting and not E and st.executable == true and not hint then hint = FPF.execNear(st) end
    end
  end
  PS.execHint = hint or nil
  if hint and not PS.execSaid then
    PS.execSaid = true
    PS.execHints = (PS.execHints or 0) + 1
    if PS.execHints <= FPC.exec.lines then
      log(string.format("EXECUTION possible (%d): the boss is doomed and in front of BT - [%s] (the punch) executes it", PS.execHints, FPF.keyWord("punchKey")))
    end
  elseif not hint and PS.execSaid then
    PS.execSaid = nil
  end
  if E then
    if found and foundMod == E.mod and found.n == E.n then
      E.elapsed = tonumber(found.elapsed)
      return
    end
    FPF.execEnd(found and "another execution began" or "the boss's execution is over")
  end
  if found and piloting then
    PS.execSeen = PS.execSeen or {}
    local key = foundMod .. " " .. tostring(found.n)
    if not PS.execSeen[key] then
      PS.execSeen[key] = true
      FPF.execStart(found, foundMod)
    end
  end
end

function FPF.execNear(st)
  local x, y = tonumber(st.x), tonumber(st.y)
  if not x or not y then return true end
  local K = FPC.exec.hint
  local dx, dy = x - PS.x, y - PS.y
  local d = math.sqrt(dx * dx + dy * dy)
  if d > K.range then return false end
  if d < 0.5 then return true end
  local r = math.rad(S.yaw)
  return (dx * -math.sin(r) + dy * math.cos(r)) / d >= math.cos(math.rad(K.angle))
end

function FPF.execKeys()
  PS.dashKey, PS.jumpKey, PS.punchKey, PS.reloadKey, PS.useDown, PS.zoom, PS.sprintOn = false, false, false, false, false, false, false
end

function FPF.execStart(X, mod)
  local K = FPC.exec
  local key = K.keys[tostring(X.kind)]
  local d = key and SCENES[key]
  if not d or not d.move or not d.cams then
    once("execkind" .. tostring(X.kind), string.format("EXECUTION: %s asks for \"%s\" - a half this BT does not have (an archive older than t104?); the boss plays its half alone",
      mod, tostring(X.kind)))
    return
  end
  local E = { n = X.n, mod = mod, key = key, d = d, kind = tostring(X.kind), t = 0.0, elapsed = tonumber(X.elapsed),
    x = tonumber(X.x) or PS.x, y = tonumber(X.y) or PS.y, z = tonumber(X.z) or PS.z, yaw = tonumber(X.yaw) or S.yaw,
    yaw0 = PS.yaw, pitch0 = S.pitch, first = true, fp = PF.shown == true, cam = 1, lookAt = 0.0, cuts = 0, pulled = 0,
    fired = 0, pods = 0, dusts = 0, steps = 0, fx = 0 }
  if E.elapsed then E.t = E.elapsed end
  PS.punch, PS.punchW, PS.lunge, PS.dashT, PS.skateArm = nil, 0.0, nil, nil, nil
  if PS.skate then
    local Sk = PS.skate
    PS.skate, PS.skateW = nil, 0.0
    pcall(FPF.skateQuiet, Sk)
  end
  FPF.execKeys()
  if E.fp then FPF.show(false) end
  local c, L = S.camPos, S.look
  if c and L then S.blend = { t = 0.0, time = K.camIn, x = c.x, y = c.y, z = c.z, yaw = L.yaw, pitch = L.pitch } end
  E.sound = K.sounds[E.kind]
  if E.sound then E.heard = FPF.tf(E.sound) == true end
  PS.exec, PS.execOut = E, nil
  PS.execs = (PS.execs or 0) + 1
  if PS.execs <= K.lines then
    log(string.format("EXECUTION %d (%s, its number %s): BT's half %s (scene clip %d, %.2f s) from (%.1f, %.1f, %.1f) facing %.0f deg (BT's body faced %.0f); the boss's clip at %.2f s; %s%s",
      PS.execs, mod, tostring(X.n), E.kind, d.clip, d.time, E.x, E.y, E.z, E.yaw, E.yaw0, E.t,
      E.sound and ("its sound " .. E.sound .. (E.heard and "" or " NOT played")) or "no sound", E.fp and "; first person off for it" or ""))
  end
end

function FPF.execEvents(E, d, t)
  while E.fired < #d.fire and t >= d.fire[E.fired + 1] do
    E.fired = E.fired + 1
    if P.fxOn then
      local m, far = muzzleWorld()
      local dx, dy, dz = 0.0, 0.0, 0.0
      if far then dx, dy, dz = far.x - m.x, far.y - m.y, far.z - m.z end
      local n = math.sqrt(dx * dx + dy * dy + dz * dz)
      if n < 0.05 then
        local r = math.rad(PS.yaw)
        dx, dy, dz, n = -math.sin(r), math.cos(r), 0.0, 1.0
      end
      dx, dy, dz = dx / n, dy / n, dz / n
      local yaw, pitch = math.deg(math.atan2(-dx, dy)), math.deg(math.asin(clamp(dz, -1.0, 1.0)))
      if FPF.fxAt(FPF.fxPath("muzzle"), m.x, m.y, m.z, yaw, pitch) then E.fx = E.fx + 1 end
      FPF.fxAt(FPF.fxPath("trail"), m.x, m.y, m.z, yaw, pitch, m.x + dx * 30.0, m.y + dy * 30.0, m.z + dz * 30.0)
    end
  end
  while E.pods < #d.pods and t >= d.pods[E.pods + 1][1] do
    E.pods = E.pods + 1
    if P.fxOn then
      local pod = FPC.mtms.pods[(d.pods[E.pods][2] > 0) and 2 or 1]
      local m = slotWorld(pod[1])
      if not m then
        local x, y, z = btPoint(pod[3][1], pod[3][2], pod[3][3])
        m = { x = x, y = y, z = z }
      end
      if FPF.fxAt(FPF.fxPath("mlaunch"), m.x, m.y, m.z, PS.yaw, 25.0) then E.fx = E.fx + 1 end
    end
  end
  while E.dusts < #d.dust and t >= d.dust[E.dusts + 1] do
    E.dusts = E.dusts + 1
    if P.fxOn and FPF.fxAt(FPF.fxPath("land"), PS.x, PS.y, PS.z + 0.05, PS.yaw, 0.0) then E.fx = E.fx + 1 end
  end
  while E.steps < #d.steps and t >= d.steps[E.steps + 1] do
    E.steps = E.steps + 1
    guard("effects of a step", FPF.fxStep)
  end
end

function FPF.execCamera(E, d, t)
  local K = FPC.exec
  local cx, cy, cz = btPoint(0.0, 0.0, K.chest)
  if S.clock >= E.lookAt then
    E.lookAt = S.clock + K.look
    local best, bestFree = nil, -1.0
    for k = 1, #d.cams do
      local c = camAt(d.cams[k], t)
      local x, y, z = btPoint(c[1], c[2], c[3])
      local dx, dy, dz = x - cx, y - cy, z - cz
      local len = math.sqrt(dx * dx + dy * dy + dz * dz)
      local hit = (len > 0.1) and FPF.hitAlong(cx, cy, cz, dx / len, dy / len, dz / len, len) or nil
      local free = hit and (hit / len) or 1.0
      if free >= 1.0 then
        best = k
        break
      end
      if free > bestFree then best, bestFree = k, free end
    end
    if best and best ~= E.cam then E.cam, E.cuts = best, E.cuts + 1 end
  end
  local c = camAt(d.cams[E.cam], t)
  local x, y, z = btPoint(c[1], c[2], c[3])
  local dx, dy, dz = x - cx, y - cy, z - cz
  local len = math.sqrt(dx * dx + dy * dy + dz * dz)
  if len > 0.5 then
    local hit = FPF.hitAlong(cx, cy, cz, dx / len, dy / len, dz / len, len + K.gap)
    if hit then
      local u = math.max(0.15, (hit - K.gap) / len)
      if u < 1.0 then
        x, y, z = cx + dx * u, cy + dy * u, cz + dz * u
        E.pulled = E.pulled + 1
      end
    end
  end
  local yaw = PS.yaw + c[4]
  E.camAt = { x = x, y = y, z = z, yaw = yaw, pitch = c[5] }
  placeCamera(x, y, z, yaw, c[5], c[6])
end

function FPF.execFrame(dt)
  local E = PS.exec
  if not E then return end
  local d, K = E.d, FPC.exec
  if not PS.ent or not IsDefined(PS.ent) then
    FPF.execEnd("BT is gone")
    return
  end
  FPF.execKeys()
  E.t = E.t + dt
  if E.elapsed and math.abs(E.elapsed + dt - E.t) > K.sync then E.t = E.elapsed + dt end
  local t = clamp(E.t, 0.0, d.time)
  local M = d.move
  local f = clamp(t * 30.0, 0.0, #M - 1)
  local i = math.min(math.floor(f), #M - 2)
  local u = f - i
  local a, b = M[i + 1], M[i + 2]
  local right, ahead, turn = a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u, a[3] + (b[3] - a[3]) * u
  local r = math.rad(E.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  PS.x, PS.y = E.x + fy * right + fx * ahead, E.y - fx * right + fy * ahead
  PS.yaw = wrap180(E.yaw0 + wrap180(E.yaw - E.yaw0) * ease(math.min(1.0, E.t / K.turn)) + turn)
  local g = groundZ(PS.x, PS.y, PS.z + 2.0)
  if g and math.abs(g - PS.z) < 3.0 then PS.z = PS.z + (g - PS.z) * math.min(1.0, dt * 12.0) end
  PS.speed, PS.vx, PS.vy = 0.0, 0.0, 0.0
  PS.sceneClip, PS.sceneTime, PS.sceneW = d.clip, t, 1.0
  if E.first then E.first = false else PS.pilotW = math.min(PS.pilotW, math.max(0.0, 1.0 - E.t / K.fadeIn)) end
  PS.reloadW, PS.punchW, PS.vortexW, PS.pods, PS.punch = 0.0, 0.0, 0.0, FPF.execPodsW(E, d, t), nil
  FPF.placeBt()
  sendPose()
  guard("skeleton watch", FPF.still, d.clip, t, dt)
  guard("what the execution does", FPF.execEvents, E, d, t)
  guard("the execution's camera", FPF.execCamera, E, d, t)
  guard("tether", tetherBehind, { x = PS.x, y = PS.y, z = PS.z })
  guard("V's body", FPF.watchV)
  guard("BT's health", FPF.health, dt)
  if PS.eject then
    FPF.execEnd("BT ejects")
  elseif E.t >= d.time then
    FPF.execEnd("its clip is over")
  end
end

function FPF.execEnd(why)
  local E = PS.exec
  if not E then return end
  PS.exec, PS.execOut = nil, true
  local K, d = FPC.exec, E.d
  local early = E.t < d.time - K.late
  if early and E.sound and E.heard then
    local axl = FPF.axl()
    if axl then pcall(function() axl:Stop(E.sound, 0.25) end) end
  end
  S.yaw, S.pitch = PS.yaw, E.pitch0
  S.chase = nil
  local c = E.camAt
  if c and not E.fp then
    S.blend = { t = 0.0, time = K.camOut, x = c.x, y = c.y, z = c.z, yaw = c.yaw, pitch = c.pitch }
  else
    S.blend = nil
  end
  FPF.execKeys()
  PS.sceneTime = math.min(E.t, d.time)
  if (PS.execs or 0) <= K.lines then
    log(string.format("EXECUTION %d over after %.2f s of %.2f (%s): BT at (%.1f, %.1f, %.1f) facing %.0f deg, %.1f m from where it began; camera %s, changed %d times, pulled in %d frames; flashes, launches and dust %d%s; piloted again",
      PS.execs or 0, E.t, d.time, why, PS.x, PS.y, PS.z, PS.yaw, math.sqrt((PS.x - E.x) ^ 2 + (PS.y - E.y) ^ 2),
      (E.cam == 1) and "CAMERA_2" or "CAMERA_3", E.cuts, E.pulled, E.fx, (early and E.heard) and "; its sound stopped" or ""))
  end
end

function FPF.execHintDraw(dl, cx, cy, red)
  if not PS.execHint or PS.exec then return end
  local _, h = render.size()
  local text = "[" .. FPF.keyWord("punchKey") .. "]  EXECUTE"
  FPF.label(dl, cx - FPF.textW(text) * 0.5, h * FPC.exec.hint.y, red, text, "c", cx)
end

