end

FPF.stepSound104 = FPF.stepSound
function FPF.stepSound(ent)
  local r = FPF.stepSound104(ent)
  if P.sounds and S.driving and PF.shown and FPF.fpFiring() then
    local axl = FPF.axl()
    if axl and PS.stepHas ~= false then
      local K, Q, n = FPC.steps, FPC.fpFireSteps, PS.stepN or 0
      local a = FPF.on(axl, K.closeFlat[(n * 5) % #K.closeFlat + 1], math.min(1.0, K.gain * P.fpVolume * Q.step)) ~= false
      local b = FPF.on(axl, K.servoFlat[(n * 3) % #K.servoFlat + 1], math.min(1.0, K.servoGain * P.fpVolume * Q.servo)) ~= false
      PS.fpFireSteps = (PS.fpFireSteps or 0) + 1
      if PS.fpFireSteps == 1 then
        log(string.format("FIRST PERSON, the gun firing: a footfall plays the outside step take and a servo take besides the cockpit's (%s, %s)",
          a and "played" or "NOT played", b and "played" or "NOT played"))
      end
    end
  end
  return r
end

