function FPF.subLang()
  local B = FPC.board
  if PS.subLang and S.clock - (PS.subLangAt or -1000.0) < B.langEvery then return PS.subLang end
  local code = nil
  for _, name in ipairs({ "Subtitles", "OnScreen" }) do
    if not code then
      pcall(function()
        local v = Game.GetSettingsSystem():GetVar("/language", name):GetValue()
        local t = nil
        pcall(function() t = v.value end)
        if type(t) ~= "string" then t = tostring(v) end
        code = t:match("%a%a%-%a%a")
      end)
    end
  end
  PS.subLang, PS.subLangAt = code or "en-us", S.clock
  return PS.subLang
end

function FPF.subText(name)
  local loc = FPF.subLang()
  local text = nil
  pcall(function() text = AudioXLNative.Subtitle(CName.new(name), loc) end)
  if (type(text) ~= "string" or text == "") and loc ~= "en-us" then
    pcall(function() text = AudioXLNative.Subtitle(CName.new(name), "en-us") end)
  end
  return (type(text) == "string" and text ~= "") and text or nil
end

function FPF.boardShow(name, text)
  local B = FPC.board
  local seconds = (B.seconds[name] or 3.0) + B.pad
  PS.boardN = (PS.boardN or 0) % 90000 + 1
  local id = tostring(B.base + PS.boardN)
  local who = B.speakers[name] or "BT-7274"
  local ok, r = pcall(function() return BT7274Voice.Subtitle(Game.GetPlayer(), id, who, text, seconds) end)
  ok = ok and r ~= false
  if not ok then
    PS.boardOff = true
    log("BT's subtitles: BT7274Voice.reds is not in the game (" .. tostring(r) .. ") - AudioXL's subtitle system from the next line on, as up to t105")
    return false
  end
  local before = PS.boardLine
  PS.boardLine = { id = id, till = S.clock + seconds, name = name }
  if before then pcall(function() BT7274Voice.SubtitleOff(before.id) end) end
  PS.boardShown = (PS.boardShown or 0) + 1
  if PS.boardShown <= B.lines then
    log(string.format("BT's subtitle on the game's board (%d): %s - \"%s\" (%s, %.1f s, id %s, language %s)", PS.boardShown, who, text, name, seconds, id, FPF.subLang()))
  end
  return true
end

function FPF.boardFrame()
  local L = PS.boardLine
  if L and (S.clock >= L.till or S.gone) then
    PS.boardLine = nil
    pcall(function() BT7274Voice.SubtitleOff(L.id) end)
  end
end

FPF.tf105 = FPF.tf
function FPF.tf(name, line)
  if not line or not P.boardSubs or PS.boardOff or not name then return FPF.tf105(name, line) end
  if not P.sounds then return false end
  local axl = FPF.axl()
  if not axl then return FPF.tf105(name, line) end
  if PS.tfHas == nil then
    local known = nil
    local okH, err = pcall(function() known = axl:Has(name) end)
    PS.tfHas = not (okH and known == false)
    log(okH and (known == false and ("Titanfall's own sounds are NOT there: AudioXL does not know " .. name .. " (its folder sounds/BT7274 was not read) - the game's sounds are used where there are any") or
      ("Titanfall's own sounds are there (AudioXL knows " .. name .. ")")) or
      ("Titanfall's own sounds: AudioXL cannot be asked whether it knows them (" .. tostring(err) .. ") - they are played all the same"))
  end
  if not PS.tfHas then return false end
  local text = FPF.subText(name)
  if not text then
    once("boardnotext" .. name, "BT's subtitles: AudioXL holds no subtitle for " .. name .. " - played its own way (PlayLine)")
    return FPF.tf105(name, line)
  end
  local ok = pcall(function() axl:Play(name) end)
  if not ok then return FPF.tf105(name, line) end
  PS.tfPlayed = PS.tfPlayed + 1
  PS.lineNow = { name = name, from = S.clock, till = S.clock + (FPC.board.seconds[name] or 3.0), cut = nil }
  return true, FPF.boardShow(name, text)
end

FPF.pauseBegin105 = FPF.pauseBegin
function FPF.pauseBegin()
  local r = FPF.pauseBegin105()
  local N, L = PS.lineNow, PS.boardLine
  if N and N.cut and L and L.name == N.name then
    PS.boardLine = nil
    pcall(function() BT7274Voice.SubtitleOff(L.id) end)
  end
  return r
end

