function FPF.gunHushFrame()
  local R = PS.gunRun
  if not R or S.clock - R.at < FPC.gunHush.after then return end
  PS.gunRun = nil
  local G, W = R.G, R.W
  local S_ = W and W.sounds
  if not G or not S_ then return end
  local rows = {}
  if R.kind == "pred" then
    if not (G.shooting or G.wanted or (G.barrels or 0.0) > 0.0) then return end
    for _, row in ipairs({ S_.loop, S_.loopMid, S_.loopFar, S_.motor, S_.spin, S_.shells }) do
      if row then
        FPF.gunStop98(row, FPC.gunHush.fade)
        rows[#rows + 1] = row
      end
    end
    G.shooting, G.wanted, G.barrels, G.loopAt, G.shellsAt, G.motorAt = false, false, 0.0, 0.0, 0.0, nil
  else
    if not G.charging then return end
    if S_.charge then
      FPF.gunStop98(S_.charge, FPC.gunHush.fade)
      rows[#rows + 1] = S_.charge
    end
    G.charging, G.charge, G.trig = false, 0.0, false
    pcall(FPF.railChargeOff)
  end
  PS.gunHushes = (PS.gunHushes or 0) + 1
  if PS.gunHushes <= FPC.gunHush.lines then
    log(string.format("the %s's own sounds stop: nothing has run the gun for %.2f s (BT's health gone, an execution, BT taken away...) - %s",
      (R.kind == "pred") and "PREDATOR CANNON" or "RAILGUN", S.clock - R.at, table.concat(rows, ", ")))
  end
end
FPC.pauseAsk = { timeEvery = 2.0, timeRuns = 3, lines = 6 }

function FPF.gamePaused()
  local ok, p = pcall(function()
    return inkMenuScenario.GetSystemRequestsHandler():IsGamePaused()
  end)
  if not ok then
    if not PS.gamePausedSaid then
      PS.gamePausedSaid = true
      log("the game's pause cannot be read from its menu system (" .. tostring(p) .. "): a pause is seen by its menus and by its own time standing still")
    end
    return false
  end
  return p == true
end

function FPF.timePausedNote(paused)
  if PS.timePausedSaid then return end
  if paused then
    PS.timePausedRun = 0
    return
  end
  if S.clock < (PS.timePausedAt or 0.0) then return end
  PS.timePausedAt = S.clock + FPC.pauseAsk.timeEvery
  local t = false
  pcall(function() t = Game.GetTimeSystem():IsPausedState() == true end)
  PS.timePausedRun = t and (PS.timePausedRun or 0) + 1 or 0
  if PS.timePausedRun >= FPC.pauseAsk.timeRuns then
    PS.timePausedSaid = true
    log(string.format("the game's time system says PAUSED while the game runs (for %.0f s; its menu system and its menus say not - another mod may have left that state set): this script does not go by it",
      FPC.pauseAsk.timeEvery * (FPC.pauseAsk.timeRuns - 1)))
  end
end

function FPF.pausedPress(key)
  PS.pausedPresses = (PS.pausedPresses or 0) + 1
  if PS.pausedPresses <= FPC.pauseAsk.lines then
    log(string.format("Mod Settings key: %s pressed while %s - not for BT", tostring(key), tostring(PS.pauseBy or "the game is paused")))
  end
end

FPF.sessionEnd108 = FPF.sessionEnd
function FPF.sessionEnd(why)
  if not S.gone then
    local N = PS.lineNow
    if N and N.cut then
      log(string.format("SESSION END: the line cut by the pause (%s) is not said again in another session", tostring(N.name)))
    end
    PS.lineNow, PS.boardLine, PS.gunRun = nil, nil, nil
  end
  return FPF.sessionEnd108(why)
end

