function FPF.execPrompt(on)
  local K = FPC.exec.ui
  if PS.execUiOk == false then return end
  local shown = false
  local ok, err = pcall(function()
    local defs = Game.GetAllBlackboardDefs().UIInteractions
    local bb = Game.GetBlackboardSystem():Get(defs)
    local now = nil
    pcall(function() now = FromVariant(bb:GetVariant(defs.InteractionChoiceHub)) end)
    if on then
      if now and now.active and now.id ~= K.id then return end
      local sys = Game.GetScriptableSystemsContainer():Get(CName.new("BT7274.BT7274Keys"))
      local choice = sys:ExecChoice(S.padLast == true)
      local title = ""
      for _, name in ipairs(FPC.exec.mods) do
        local st = nil
        pcall(function()
          local m = nil
          if type(m) == "table" and type(m.State) == "function" then st = m.State() end
        end)
        if type(st) == "table" and st.executable == true then
          title = K.titles[name] or ""
          break
        end
      end
      local hub = gameinteractionsvisInteractionChoiceHubData.new()
      hub.id, hub.active, hub.title = K.id, true, title
      hub.choices = { choice }
      bb:SetVariant(defs.InteractionChoiceHub, Variant("gameinteractionsvisInteractionChoiceHubData", hub), true)
      local info = gameinteractionsvisVisualizersInfo.new()
      info.activeVisId = K.id
      info.visIds = { K.id }
      bb:SetVariant(defs.VisualizersInfo, Variant("gameinteractionsvisVisualizersInfo", info), true)
      shown = true
    elseif now and now.id == K.id then
      local hub = gameinteractionsvisInteractionChoiceHubData.new()
      hub.id, hub.active = K.id, false
      bb:SetVariant(defs.InteractionChoiceHub, Variant("gameinteractionsvisInteractionChoiceHubData", hub), true)
      local info = gameinteractionsvisVisualizersInfo.new()
      info.activeVisId = -1
      bb:SetVariant(defs.VisualizersInfo, Variant("gameinteractionsvisVisualizersInfo", info), true)
    end
  end)
  if not ok then
    PS.execUiOk, PS.execUiOn, PS.execUiShown = false, false, false
    log("the execution hint cannot be the game's own prompt (" .. tostring(err) .. ") - this script draws its own line, as before t111")
    return
  end
  PS.execUiOn, PS.execUiShown, PS.execUiAt = on, shown, S.clock + K.every
  if shown then once("execuishown", "the execution hint is the game's own interaction prompt (the finisher's caption; the punch key bound in Mod Settings executes)") end
end

function FPF.execPromptFrame()
  local want = P.execUi and PS.execUiOk ~= false and S.keysOk and S.driving and PS.execHint and not PS.exec
  if want then
    if not PS.execUiOn or S.clock >= (PS.execUiAt or 0.0) then FPF.execPrompt(true) end
  elseif PS.execUiOn then
    FPF.execPrompt(false)
  end
  if not want then PS.execUiShown = false end
end

