P.execMissiles = true
FPC.execMissiles = { lead = 0.35, hold = 0.6, fold = 0.5, ahead = 8.8, up = 4.0, aimEvery = 0.1, life = 4.0, soundGap = 0.15,
  boomGap = 0.05, lines = 6 }

function FPF.execPodsW(E, d, t)
  local L = d.pods
  if not P.execMissiles or not L or #L == 0 then return 0.0 end
  local K = FPC.execMissiles
  local from, to, up = L[1][1] - K.lead, L[#L][1] + K.hold, FPC.mtms.podUp
  local w = 0.0
  if t >= from and t < from + up then
    w = (t - from) / up
  elseif t >= from + up and t <= to then
    w = 1.0
  elseif t > to then
    w = 1.0 - (t - to) / K.fold
  end
  return ease(clamp(w, 0.0, 1.0))
end

function FPF.execAim(E)
  local K = FPC.execMissiles
  if not E.aimAt or S.clock >= E.aimAt then
    E.aimAt = S.clock + K.aimEvery
    local a = nil
    pcall(function()
      local st = nil
      local X = st and st.execution
      if type(X) == "table" and X.n == E.n and type(X.aim) == "table" then
        local x, y, z = tonumber(X.aim.x), tonumber(X.aim.y), tonumber(X.aim.z)
        if x and y and z then a = { x = x, y = y, z = z } end
      end
    end)
    if a then
      E.aim, E.aimFrom = a, "the boss's own aim point"
    elseif not E.aim then
      local r = math.rad(E.yaw)
      E.aim = { x = E.x - math.sin(r) * K.ahead, y = E.y + math.cos(r) * K.ahead, z = E.z + K.up }
      E.aimFrom = string.format("%.1f m in front of where BT began, %.0f m up", K.ahead, K.up)
    end
  end
  return E.aim
end

function FPF.execMissile(E, d, i)
  local K, Km = FPC.execMissiles, FPC.mtms
  local side = (d.pods[i][2] > 0) and 1.0 or -1.0
  local pod = Km.pods[(side > 0) and 2 or 1]
  local m = slotWorld(pod[1])
  if not m then
    local x, y, z = btPoint(pod[3][1], pod[3][2], pod[3][3])
    m = { x = x, y = y, z = z }
  end
  local a = FPF.execAim(E)
  local ax, ay, az = a.x - m.x, a.y - m.y, a.z - m.z
  local an = math.sqrt(ax * ax + ay * ay + az * az)
  if an < 0.5 then
    ax, ay, az = 0.0, 0.0, 1.0
  else
    ax, ay, az = ax / an, ay / an, az / an
  end
  local ux, uy = ay, -ax
  local un = math.sqrt(ux * ux + uy * uy)
  if un < 1e-4 then ux, uy, un = 1.0, 0.0, 1.0 end
  ux, uy = ux / un, uy / un
  local tip = math.tan(math.rad(Km.outAngle))
  local dx, dy, dz = ax + ux * side * tip, ay + uy * side * tip, az + tip
  local dn = math.sqrt(dx * dx + dy * dy + dz * dz)
  dx, dy, dz = dx / dn, dy / dn, dz / dn
  local M = { x = m.x, y = m.y, z = m.z, dx = dx, dy = dy, dz = dz, t = 0.0, speed = Km.speed * clamp(P.mtmsSpeed, 0.3, 4.0) }
  if P.fxOn and not PS.noTrail then
    M.trail = FPF.fxAt(FPF.fxPath("mtrail"), m.x, m.y, m.z, math.deg(math.atan2(-dx, dy)), math.deg(math.asin(clamp(dz, -1.0, 1.0))))
  end
  E.missiles = E.missiles or {}
  E.missiles[#E.missiles + 1] = M
  E.launched = (E.launched or 0) + 1
  if S.clock - (E.launchSoundAt or -10.0) >= K.soundGap then
    E.launchSoundAt = S.clock
    FPF.tf(Km.sounds.fire[(E.launched - 1) % #Km.sounds.fire + 1])
  end
end

function FPF.execMissilesFrame(E, t)
  local L = E.missiles
  local dt = math.max(0.0, t - (E.missileT or t))
  E.missileT = t
  if not L or #L == 0 or dt <= 0.0 then return end
  local K, Km = FPC.execMissiles, FPC.mtms
  local a = FPF.execAim(E)
  for i = #L, 1, -1 do
    local m = L[i]
    m.t = m.t + dt
    local tx, ty, tz = a.x - m.x, a.y - m.y, a.z - m.z
    local dist = math.sqrt(tx * tx + ty * ty + tz * tz)
    local step = m.speed * dt
    if dist <= math.max(step, Km.fuse) or m.t > K.life then
      local bx, by, bz = a.x, a.y, a.z
      if dist > math.max(step, Km.fuse) then bx, by, bz = m.x, m.y, m.z end
      FPF.missileTrailEnd(m)
      if P.fxOn then FPF.fxAt(FPF.fxPath("mboom"), bx, by, bz, 0.0, 0.0) end
      E.booms = (E.booms or 0) + 1
      if S.clock - (E.boomSoundAt or -10.0) >= K.boomGap then
        E.boomSoundAt = S.clock
        local c, far = S.camPos, 0.0
        if c then far = math.sqrt((bx - c.x) ^ 2 + (by - c.y) ^ 2 + (bz - c.z) ^ 2) end
        local Ks = Km.sounds
        local list = (far >= Ks.farFrom and Ks.far) or (far >= Ks.midFrom and Ks.mid) or Ks.near
        FPF.tf(list[(E.booms - 1) % #list + 1])
      end
      table.remove(L, i)
    else
      if m.t > Km.outTime then
        local wx, wy, wz = tx / dist, ty / dist, tz / dist
        local ang = math.acos(clamp(m.dx * wx + m.dy * wy + m.dz * wz, -1.0, 1.0))
        local most = math.rad(Km.homing) * dt
        if ang <= most or ang < 1e-3 then
          m.dx, m.dy, m.dz = wx, wy, wz
        else
          local sn = math.sin(ang)
          local a0, a1 = math.sin(ang - most) / sn, math.sin(most) / sn
          local nx, ny, nz = m.dx * a0 + wx * a1, m.dy * a0 + wy * a1, m.dz * a0 + wz * a1
          local nn = math.sqrt(nx * nx + ny * ny + nz * nz)
          m.dx, m.dy, m.dz = nx / nn, ny / nn, nz / nn
        end
      end
      m.x, m.y, m.z = m.x + m.dx * step, m.y + m.dy * step, m.z + m.dz * step
      FPF.missileTrailMove(m)
    end
  end
end

