function FPF.airFrame()
  local K = FPC.air
  local A = PS.air
  if not A then
    A = { on = false }
    PS.air = A
  end
  local lift = nil
  local D = PS.decoy
  if P.airAim and S.driving and S.pilot and PS.mode == "pilot" and D and D.ent then
    pcall(function() lift = PS.z - D.ent:GetWorldPosition().z end)
  end
  local on = false
  if lift then
    if A.on then on = lift > K.drop else on = lift > K.lift end
  end
  local ax, ay, az = nil, nil, nil
  if on then
    pcall(function()
      local v = Game.GetPlayer():GetWorldPosition()
      ax, ay, az = v.x, v.y, v.z + K.aimUp
    end)
    if not ax then on = false end
  end
  if on or A.told ~= false then
    local ok, err = pcall(function()
      local sys = Game.GetScriptableSystemsContainer():Get(CName.new("BT7274.BT7274Keys"))
      sys.airLift = on
      if on then sys.airX, sys.airY, sys.airZ = ax, ay, az end
      A.shotsNow = tonumber(sys.airShots) or A.shotsNow
    end)
    if not ok and not A.unsaid then
      A.unsaid = true
      log("BT in the air: the key script cannot be told (" .. tostring(err) .. " - BT7274Keys.reds older than t113?) - the foes go on shooting at the stand-in; its hits below do not count")
    end
    A.told = on
  end
  if on and not A.on then
    A.on, A.from, A.most, A.hitsV, A.ground, A.shots0 = true, S.clock, lift, 0, 0, A.shotsNow or 0
  elseif on then
    A.most = math.max(A.most or 0.0, lift)
  elseif A.on then
    A.on = false
    A.n = (A.n or 0) + 1
    if A.n <= K.lines then
      log(string.format("BT IN THE AIR %d: %.1f s, up to %.1f m over its stand-in; the foes' shots at the stand-in aimed at BT: %d; hits on V in BT meanwhile: %d; hits on the stand-in below, not counted: %d",
        A.n, S.clock - (A.from or S.clock), A.most or 0.0, math.max(0, (A.shotsNow or 0) - (A.shots0 or 0)), A.hitsV or 0, A.ground or 0))
    end
  end
end

