    local onBt, onV = false, false
    pcall(function() onBt = D ~= nil and D.hash ~= nil and tostring(evt.target:GetEntityID()) == D.hash end)
    if onBt then
      if tag == "a" then A.ground = (A.ground or 0) + 1 end
      return
    end
