FPC.bossHit = { lines = 8 }

local BOSS_SHARE, BOSS_MELEE = {}, {}

function FPF.bossShare(record)
  local v = BOSS_SHARE[record]
  if v ~= nil then return v or nil end
  v = false
  local how = nil
  pcall(function()
    local mods = TweakDB:GetFlat(record .. ".statModifiers")
    local first = nil
    for i = 1, #(mods or {}) do
      local ref, val = nil, nil
      pcall(function() ref = TDBID.ToStringDEBUG(TweakDB:GetFlat(TweakDBID.new(mods[i], ".refStat"))) end)
      pcall(function() val = TweakDB:GetFlat(TweakDBID.new(mods[i], ".value")) end)
      if type(val) == "number" and val > 0.0 then
        if ref == "BaseStats.Health" then
          v, how = val, "its modifier on BaseStats.Health"
          return
        end
        if first == nil and ref == nil then first = val end
      end
    end
    if first then v, how = first, "its first modifier's value - what it refers to could not be read" end
  end)
  BOSS_SHARE[record] = v
  if v then
    log(string.format("fpf.bossHit: %s takes a share of %.2f of the target's health (%s) - %.0f of BT's %.0f", record, v, how,
      v * (FPC.health.segment * FPC.health.segments + FPC.health.shield) / math.max(P.toughness, 1.0),
      FPC.health.segment * FPC.health.segments + FPC.health.shield))
  else
    log("fpf.bossHit: " .. tostring(record) .. " has no share of the target's health (no modifier on BaseStats.Health): its blows are not taken")
  end
  return v or nil
end

function FPF.bossMelee(record)
  local v = BOSS_MELEE[record]
  if v == nil then
    v = false
    pcall(function() v = TDBID.ToStringDEBUG(TweakDB:GetFlat(record .. ".attackType")):find("Melee", 1, true) ~= nil end)
    BOSS_MELEE[record] = v
  end
  return v
end

function FPF.bossOpen()
  if S.gone then return false, "no session" end
  local H = PS.hp
  local there = false
  pcall(function() there = PS.ent ~= nil and IsDefined(PS.ent) end)
  if not there or not H then return false, "no BT" end
  if H.gone then return false, "its health is gone" end
  if S.driving then
    if S.pilot and H.on and PS.mode == "pilot" then return true, "piloted" end
    return false, "V is getting in or out"
  end
  if PS.warm or PS.asked then return false, "it is coming" end
  if PS.act then return false, (PS.act.kind == "leave") and "it is leaving" or ("it is busy (" .. tostring(PS.act.kind) .. ")") end
  if PS.kneel then return false, "it kneels for a quest" end
  if FPF.questSafe() then return false, "a quest keeps it safe" end
  return true, "nobody in it"
end

function FPF.bossTarget()
  local ok, why = FPF.bossOpen()
  if not ok then return nil, why end
  local H, K = PS.hp, FPC.health
  local piloted = why == "piloted"
  return { piloted = piloted, x = PS.x, y = PS.y, z = PS.z, yaw = PS.yaw,
    look = piloted and S.yaw or ((PS.buddy and PS.buddy.yaw) or PS.yaw), aimZ = PS.z + FPC.notice.chest,
    health = H.health + H.shield + (H.doomed or 0.0), healthMax = K.segment * K.segments + K.shield }
end

local function bossWho(who)
  if type(who) == "string" then return who end
  local n = nil
  if who ~= nil then pcall(function() n = TDBID.ToStringDEBUG(who:GetRecordID()) end) end
  return n or "a boss of another mod"
end

local function bossBook()
  local B = PS.boss
  if not B then
    B = { n = 0, taken = 0.0, caught = 0, phased = 0, refused = 0, why = {}, lines = 0 }
    PS.boss = B
  end
  return B
end

local function bossLine(B, text)
  B.lines = B.lines + 1
  if B.lines <= FPC.bossHit.lines then log(string.format("BOSS HIT %d (another mod's, fpf.bossHit): %s", B.lines, text)) end
end

function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local ok, why = FPF.bossOpen()
  if ok and type(record) ~= "string" then ok, why = false, "no record" end
  local share = ok and FPF.bossShare(record) or nil
  if ok and not share then ok, why = false, "no share of the target's health in " .. record end
  if not ok then
    if why ~= "no session" then
      local B = bossBook()
      B.refused = B.refused + 1
      B.why[why] = (B.why[why] or 0) + 1
    end
    return false, why
  end
  local B = bossBook()
  local H, K = PS.hp, FPC.health
  local piloted = why == "piloted"
  local name = bossWho(who)
  local value = share * H.vMax
  local whole = K.segment * K.segments + K.shield
  local pts = value * whole / (math.max(P.toughness, 1.0) * H.vMax)
  local fx, fy, hx, hy = nil, nil, nil, nil
  if type(x) == "number" and type(y) == "number" then fx, fy = x - PS.x, y - PS.y end
  if type(dx) == "number" and type(dy) == "number" then
    local n = math.sqrt(dx * dx + dy * dy)
    if n > 0.1 then hx, hy = -dx / n, -dy / n end
  end
  if fx == nil or fx * fx + fy * fy < 0.25 then fx, fy = hx, hy end
  local text = string.format("%s from %s - a share of %.2f of V's health (%.0f) -> %.0f of BT's %.0f%s", record, name, share, H.vMax,
    pts, whole, piloted and "" or ", nobody in it")
  local proof = FPF.vortexProof(record)
  local melee = proof or kind == "melee" or kind == "blast" or (kind == nil and FPF.bossMelee(record))
  local V = PS.vortex
  if proof and V and V.on then FPF.vortexProofSaid(V, record, "fpf.bossHit") end
  if V and V.on and not melee then
    local front = true
    if fx then
      local d = math.sqrt(fx * fx + fy * fy)
      if d >= 0.5 then
        local r = math.rad((not S.driving and PS.buddy and PS.buddy.yaw) or S.yaw)
        front = (fx * -math.sin(r) + fy * math.cos(r)) / d >= math.cos(math.rad(FPC.vortex.arc))
      end
    end
    if front then
      V.pend.a, V.pend.b = V.pend.a + 1, V.pend.b + 1
      B.n, B.caught = B.n + 1, B.caught + 1
      bossLine(B, text .. "; the vortex shield catches it")
      return true, "caught", 0.0
    end
    V.missed = V.missed + 1
  end
  H.pend.a, H.pend.b = H.pend.a + value, H.pend.b + value
  if value > (H.bigV or 0.0) then
    H.bigV, H.bigWho, H.bigRec, H.bigX, H.bigY, H.bigDX, H.bigDY = value, name, record, fx, fy, hx, hy
  end
  if not piloted and PS.questBt and type(FPF.q.harm) == "number" and FPF.q.harm >= 0.0 then pts = pts * FPF.q.harm end
  B.n = B.n + 1
  if FPF.perk("dash") > 0 and PS.dashT ~= nil and PS.dashT < TF.dodgeTime + FPC.perk.phase.grace then
    B.phased = B.phased + 1
    bossLine(B, text .. "; it goes through BT in its PHASE DASH")
    return true, "phased", 0.0
  end
  B.taken = B.taken + pts
  bossLine(B, text)
  return true, "taken", pts
end

