local VORTEX_PROOF = {}

function FPF.vortexProof(record)
  if type(record) ~= "string" then return false end
  local v = VORTEX_PROOF[record]
  if v == nil then
    v = FPC.vortex.proof[record] == true
    if not v then pcall(function() v = TweakDB:GetFlat(record .. ".vortexProof") == true end) end
    VORTEX_PROOF[record] = v
  end
  return v
end

function FPF.vortexProofSaid(V, record, how)
  V.proofs = (V.proofs or 0) + 1
  if V.proofs <= 3 then log(string.format("VORTEX a laser goes through the shield (%s, %s): lasers are not caught", record, how)) end
end

FPF.vortexCatch114 = FPF.vortexCatch
function FPF.vortexCatch(who, evt, tag)
  local V = PS.vortex
  if V and V.on and evt then
    local record = nil
    pcall(function() record = TDBID.ToStringDEBUG(evt.attackData:GetAttackDefinition():GetRecord():GetID()) end)
    if FPF.vortexProof(record) then
      if tag == "a" then FPF.vortexProofSaid(V, record, "a hit") end
      return false
    end
  end
  return FPF.vortexCatch114(who, evt, tag)
end
