FPF.gunPick115 = FPF.gunPick
function FPF.gunPick(why)
  local k = P.perks and math.floor(FPF.factGet(FPC.perk.gunFact) + 0.5) or 0
  PS.slash, PS.slashAsk, PS.wave, PS.swordBlock = nil, nil, nil, nil
  if k ~= 3 then return FPF.gunPick115(why) end
  PS.weapon = "sword"
  local W = FPC.guns.sword
  FPC.ent = W.fpEnt
  FPC.body[3] = W.mesh
  FPC.shade.twins[2] = W.shadow
  FPC.shade.meshes[2] = "titan\\bt7274\\meshes\\" .. W.shadow .. ".mesh"
  for i = 1, 3 do MUZZLE_REST[i] = W.rest[i] end
  ZOOM.fov, ZOOM.speed = W.zoom.fov, W.zoom.speed
  for key in pairs(FP) do FP[key] = nil end
  for key, v in pairs(FPC.fpGuns.xo16) do FP[key] = v end
  for key, v in pairs(FPC.fpGuns.sword) do FP[key] = v end
  if PS.gun then PS.gun.ammo, PS.gun.reloadT, PS.gun.anim = 0, nil, nil end
  local B = FPC.kickXo
  FPC.kick.up, FPC.kick.side, FPC.kick.most, FPC.kick.back = B.up, B.side, B.most, B.back
  PS.gunPicks = (PS.gunPicks or 0) + 1
  if PS.gunPicks <= 8 or PS.gunWas ~= "sword" then
    log(string.format("BT's weapon: the BROADSWORD (%s; the selected weapon, %s = 3) - Titanfall's sword in its hand, its first-person view %s; ARC WAVE %s",
      tostring(why), FPC.perk.gunFact, W.fpEnt, (FPF.perk("sword") > 0) and "enabled (the fire key while blocking)" or "disabled by the server loadout"))
  end
  PS.gunWas = "sword"
end

FPF.gunNamed115 = FPF.gunNamed
