function FPF.swordReach()
  local r = FPC.sword.reach + FPF.perkValue("swordreach")
  if FPF.coreOn() then r = r + FPC.sword.core.reach end
  return r
end

function FPF.swordRate()
  local r = FPF.perkValue("swordspeed")
  if FPF.coreOn() then r = r * FPC.sword.core.rate end
  return r
end

function FPF.swordSound(list, level)
  if not P.sounds or not list then return false end
  local name = list
  if type(list) == "table" then
    PS.swordSoundN = PS.swordSoundN or {}
    local n = (PS.swordSoundN[list[1]] or 0) % #list + 1
    PS.swordSoundN[list[1]] = n
    name = list[n]
  end
  local ok = false
  pcall(function() ok = FPF.ownSound(name, level or FPF.jarLevel(S.driving and S.pilot)) end)
  return ok
end

function FPF.slashStart(by, wave)
  local K = FPC.sword
  local M = { t = 0.0, wave = wave == true, hit = {}, done = false, by = by, rate = FPF.swordRate(), sent = 0, attacks = 0, people = 0,
    titans = 0, vehicles = 0, fx = 0, seen = S.clock }
  if M.wave then
    local C = PUNCH_CLIP.sword.wave
    M.tp, M.tpClip, M.fpClip, M.view = C, K.tpWave, K.fpWave, "wave"
    M.fpTime = (FP.wave and FP.wave.time) or C.time
    M.from = C.hit
  else
    PS.slashN = (PS.slashN or 0) % 3 + 1
    M.n = PS.slashN
    local C = (M.n == 2) and PUNCH_CLIP.sword.dash or PUNCH_CLIP.sword
    local F = (M.n == 1) and { time = FP.melee, hit = FP.meleeHit } or ((M.n == 2) and FP.dash or FP.slash3)
    M.tp, M.tpClip, M.fpClip, M.view = C, K.tpClips[M.n], K.fpClips[M.n], K.views[M.n]
    M.fpTime = (F and F.time) or C.time
    M.from = (PF.shown and F and F.hit) or C.hit
  end
  M.len = math.max(M.fpTime, M.tp.time)
  PS.slash, PS.sprintOn = M, false
  PS.slashes = (PS.slashes or 0) + 1
  local how = ""
  if not M.wave and P.lunge then
    PS.npcsAt = -10
    refreshNpcs()
    local T = FPF.punchTargets(K.lungeRange, PUNCH.lungeAngle)[1]
    local due = M.from / M.rate
    if T and T.dist > K.lungeStop and due > 0.05 then
      local go = math.min(T.dist - K.lungeStop, TF.dodgeSpeed * due)
      PS.lunge = { x = T.dx, y = T.dy, speed = go / due, t = 0.0, time = due }
      how = string.format("; it lunges %.1f m at a %s %.1f m away", go, T.kind, T.dist)
    end
  end
  if M.wave then
    FPF.swordSound(K.sounds.waveFire)
  elseif PF.shown then
    FPF.swordSound(K.sounds.fp, FPF.viewVolume())
  else
    FPF.swordSound(K.sounds.tp)
  end
  if PS.slashes <= K.lines then
    log(string.format("%s %d (%s): %s; it meets what is in front after %.2f s (x %.2f: SWIFT STRIKES%s); reach %.1f m, %.0f deg%s",
      M.wave and "ARC WAVE's slam" or "SLASH", PS.slashes, tostring(by), M.wave and "the wave leaves at the slam" or ("swing " .. M.n .. " of three"),
      M.from / M.rate, M.rate, FPF.coreOn() and ", Sword Core" or "", FPF.swordReach(), K.angle, how))
  end
  return M
end

function FPF.slashHit(ent, M)
  local K = FPC.sword
  local rec = FPF.gunRecord(FPF.coreOn() and K.records.core or K.records.slash)
  if S.clock - PS.npcsAt > 0.08 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  for _, T in ipairs(FPF.punchTargets(FPF.swordReach(), K.angle)) do
    if not M.hit[T.key] then
      M.hit[T.key] = true
      if T.kind == "vehicle" then
        M.vehicles = M.vehicles + 1
      elseif (T.r or 0.0) > 0.0 then
        M.titans = M.titans + 1
      else
        M.people = M.people + 1
      end
      if (PS.punchChecked or 0) < 12 then
        PS.punchChecked = (PS.punchChecked or 0) + 1
        PS.checks[#PS.checks + 1] = { ent = T.ent, before = healthOf(T.ent), at = S.clock + 0.4, dist = T.dist, kind = T.kind,
          by = "the broadsword", what = (T.kind == "person") and personText(T.ent) or FPF.vehicleText(T.ent) }
      end
      if FPF.hit(T.ent, rec, T.x, T.y, T.z, fx, fy, 0.0) then M.sent = M.sent + 1 end
      if FPF.attack(rec, T.x, T.y, T.z) then M.attacks = M.attacks + 1 end
      if T.kind == "vehicle" then FPF.wreck(T.ent, FPC.wreck.punch * K.wreck) end
      if P.fxOn and M.fx < 3 then
        M.fx = M.fx + 1
        FPF.fxAt(FPF.fxPath("punch"), T.x, T.y, T.z, S.yaw, 0.0)
      end
    end
  end
  local met = M.people + M.titans + M.vehicles
  if met > 0 then
    FPF.stim("Explosion", FPC.stims.punch, 0.2)
    FPF.swordSound((M.titans > 0 and K.sounds.armor) or (M.vehicles > 0 and K.sounds.metal) or K.sounds.flesh)
  elseif P.punchWall then
    local best = nil
    for _, h in ipairs(FPC.punchWall.heights) do
      local t, k = rayWorld(PS.x, PS.y, PS.z + h, fx, fy, 0.0, FPF.swordReach())
      if k ~= "nothing" and k ~= "person" and (best == nil or t < best) then best = t end
    end
    if best then
      M.wall = best
      FPF.swordSound(K.sounds.ground)
    end
  end
  PS.slashMet = (PS.slashMet or 0) + met
  if PS.slashes <= K.lines then
    log(string.format("SLASH %d meets %d people, %d titans or mechs and %d vehicles within %.1f m and %.0f deg (%s; hit events taken for %d, area attacks %d)%s",
      PS.slashes, M.people, M.titans, M.vehicles, FPF.swordReach(), K.angle, rec, M.sent, M.attacks,
      (met == 0) and (M.wall and string.format(" - the blade meets the world %.1f m ahead", M.wall) or " - nothing") or ""))
  end
end

function FPF.waveStart(M)
  local K = FPC.sword.wave
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  PS.wave = { t = 0.0, step = 0, fx = fx, fy = fy, x0 = PS.x + fx * K.from, y0 = PS.y + fy * K.from, z = PS.z, hit = {}, people = 0,
    vehicles = 0, sent = 0, attacks = 0, n = (PS.waves or 0) + 1, by = M.by }
  PS.waves = PS.wave.n
  PS.waveReadyAt = S.clock + K.every
  FPF.swordSound(FPC.sword.sounds.waveTravel)
end

function FPF.waveMeet(W, ent, kind, x, y, z, rec)
  if not ent or not IsDefined(ent) then return end
  local K = FPC.sword.wave
  local ok, p = pcall(function() return ent:GetWorldPosition() end)
  if not ok or not p then return end
  local rad = 0.0
  if kind == "person" then
    local name = nil
    pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
    if type(name) == "string" then
      local okS, shape = pcall(FPF.recordShape, name)
      if okS and shape then rad = shape[1] end
    end
  end
  local dx, dy = p.x - x, p.y - y
  local d = math.sqrt(dx * dx + dy * dy)
  if d - rad > K.wide or math.abs(p.z - z) > K.high + ((rad > 0.0) and 2.0 or 0.0) then return end
  local key = nil
  pcall(function() key = tostring(ent:GetEntityID()) end)
  if not key or W.hit[key] then return end
  W.hit[key] = true
  if kind == "vehicle" then W.vehicles = W.vehicles + 1 else W.people = W.people + 1 end
  local hx, hy = p.x, p.y
  if rad > 0.0 and d > 0.01 then hx, hy = p.x - dx / d * rad, p.y - dy / d * rad end
  if FPF.hit(ent, rec, hx, hy, p.z + 1.0, W.fx, W.fy, 0.0) then W.sent = W.sent + 1 end
  if FPF.attack(rec, hx, hy, p.z + 0.5) then W.attacks = W.attacks + 1 end
  if kind == "vehicle" then FPF.wreck(ent, FPC.wreck.punch) end
end

function FPF.waveFrame(dt)
  local W = PS.wave
  if not W then return end
  local K = FPC.sword.wave
  local rec = FPF.gunRecord(FPC.sword.records.wave)
  W.t = W.t + dt
  if S.clock - PS.npcsAt > 0.25 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  while W.step < K.steps and W.t >= W.step * K.stepTime do
    W.step = W.step + 1
    local d = (W.step - 1) * K.step
    local x, y = W.x0 + W.fx * d, W.y0 + W.fy * d
    local gz = groundZ(x, y, W.z)
    if gz and math.abs(gz - W.z) <= K.rise then W.z = gz end
    for _, who in ipairs(PS.npcs) do FPF.waveMeet(W, who, "person", x, y, W.z, rec) end
    for _, veh in ipairs(FPF.vehicles()) do FPF.waveMeet(W, veh, "vehicle", x, y, W.z, rec) end
    if P.fxOn then
      local inst = FPF.fxAt(K.fx, x, y, W.z + K.up, nil, nil)
      if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.life } end
    end
  end
  if W.step >= K.steps then
    if W.n <= FPC.sword.lines then
      log(string.format("ARC WAVE %d (%s): %d steps along the ground, %.0f m; it met %d people and %d vehicles (hit events taken for %d, area attacks %d) - ready again in %.0f s",
        W.n, tostring(W.by), K.steps, (K.steps - 1) * K.step + K.from, W.people, W.vehicles, W.sent, W.attacks, K.every))
    end
    PS.wave = nil
  end
end

function FPF.swordBlockFrame(dt)
  local K = FPC.sword.block
  local B = PS.swordBlock
  if not B then
    B = { energy = K.max, on = false, idle = K.delay, ups = 0, blocked = 0, saved = 0.0, soundAt = -10.0 }
    PS.swordBlock = B
  end
  local want = S.driving and S.pilot and PS.mode == "pilot" and PS.zoom and not PS.auto and not (PS.vortex and PS.vortex.on)
    and not PS.slash and not PS.punch and not PS.pound
  if B.on then
    B.energy = math.max(0.0, B.energy - K.drain * dt)
    if not want or B.energy <= 0.0 then
      B.on, B.idle = false, 0.0
      if B.ups <= FPC.sword.lines then
        log(string.format("BLOCK %d down (%s): %d hits blocked so far, %.0f of V's health points kept off BT", B.ups,
          (B.energy <= 0.0) and "its energy is gone" or (PS.zoom and "a slash, a punch or the shield" or "the aim key let go"), B.blocked, B.saved))
      end
    end
  elseif want and B.energy >= K.least then
    B.on, B.ups = true, B.ups + 1
    FPF.swordSound(FPC.sword.sounds.raise, FPF.viewVolume())
    if B.ups <= FPC.sword.lines then
      log(string.format("BLOCK %d up: hits from within %.0f deg of the view, no blast, are taken at x %.2f (energy %.0f)", B.ups, K.arc,
        FPF.coreOn() and FPC.sword.core.block or K.take, B.energy))
    end
  end
  if not B.on then
    B.idle = B.idle + dt
    if B.idle >= K.delay then B.energy = math.min(K.max, B.energy + K.regen * dt) end
  end
  return B
end

function FPF.swordTake(fx, fy, blast)
  local B = PS.swordBlock
  if PS.weapon ~= "sword" or not B or not B.on or blast then return 1.0 end
  if fx and fy then
    local d = math.sqrt(fx * fx + fy * fy)
    if d >= 0.5 then
      local r = math.rad(S.yaw)
      if (fx * -math.sin(r) + fy * math.cos(r)) / d < math.cos(math.rad(FPC.sword.block.arc)) then return 1.0 end
    end
  end
  return FPF.coreOn() and FPC.sword.core.block or FPC.sword.block.take
end

function FPF.swordBlocked(kept, k)
  local B, K = PS.swordBlock, FPC.sword.block
  B.blocked, B.saved = B.blocked + 1, B.saved + kept
  if S.clock - B.soundAt >= K.gap then
    B.soundAt = S.clock
    FPF.swordSound(FPC.sword.sounds.block, FPF.viewVolume())
  end
  if B.blocked <= 4 then log(string.format("BLOCK: a hit from in front taken at x %.2f - %.0f of V's health points kept off BT", k, kept)) end
end

FPF.hitSeen115 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H, B = PS.hp, PS.swordBlock
  if not H or PS.weapon ~= "sword" or not B or not B.on or not evt or type(H.pend[tag]) ~= "number" then return FPF.hitSeen115(evt, tag) end
  local before, big = H.pend[tag], H.bigV
  local r = FPF.hitSeen115(evt, tag)
  local added = H.pend[tag] - before
  if added > 0.0 then
    local fx, fy, blast = nil, nil, false
    pcall(function()
      local p = evt.attackData:GetInstigator():GetWorldPosition()
      fx, fy = p.x - PS.x, p.y - PS.y
    end)
    pcall(function() blast = EnumName("gamedataAttackType", evt.attackData:GetAttackType()):find("Explosion", 1, true) ~= nil end)
    local k = FPF.swordTake(fx, fy, blast)
    if k < 1.0 then
      H.pend[tag] = before + added * k
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
      if tag == "a" then FPF.swordBlocked(added * (1.0 - k), k) end
    end
  end
  return r
end

FPF.bossHit115 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local H, B = PS.hp, PS.swordBlock
  if not H or PS.weapon ~= "sword" or not B or not B.on then return FPF.bossHit115(record, x, y, z, dx, dy, who, kind) end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit115(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" then
    local fx = (type(x) == "number") and (x - PS.x) or nil
    local fy = (type(y) == "number") and (y - PS.y) or nil
    local k = FPF.swordTake(fx, fy, kind == "blast")
    if k < 1.0 then
      local added = H.pend.a - a0
      H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
      if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - pts * (1.0 - k) end
      FPF.swordBlocked(added * (1.0 - k), k)
      pts = pts * k
    end
  end
  return ok, what, pts
end

function FPF.swordFrame(dt, ent)
  local K = FPC.sword
  local fire = PS.swordFire == true
  local edge = fire and not PS.swordFireWas
  PS.swordFireWas = fire
  local M = PS.slash
  if M and S.clock - M.seen > K.stale then
    PS.slash, M = nil, nil
  end
  local B = FPF.swordBlockFrame(dt)
  FPF.waveFrame(dt)
  local free = not PS.punch and not PS.pound
  local ready = free and (not M or M.t >= M.len - K.chain)
  local wave = false
  if fire and B.on then
    if edge then
      if FPF.perk("sword") < 1 then
        once("wavenot", "ARC WAVE is disabled by the server loadout: the fire key while blocking does nothing")
      elseif S.clock < (PS.waveReadyAt or 0.0) then
        PS.waveEarly = (PS.waveEarly or 0) + 1
        if PS.waveEarly <= 3 then log(string.format("ARC WAVE asked %.1f s too soon", PS.waveReadyAt - S.clock)) end
      else
        wave = true
      end
    end
  elseif edge and not ready and free then
    PS.slashAsk = PS.slashAsk or { by = "the fire key" }
  end
  local ask = PS.slashAsk or ((fire and not B.on) and { by = "the fire key" } or nil)
  if not free then
    PS.slashAsk = nil
  elseif ready and (wave or ask) then
    PS.slashAsk = nil
    if wave then B.on, B.idle = false, 0.0 end
    M = FPF.slashStart(wave and "the fire key, blocking" or ask.by, wave)
  end
  if not M then return end
  M.seen = S.clock
  M.t = M.t + dt * M.rate
  PS.punchT = math.min(M.t, M.tp.time)
  PS.punchW = clamp(math.min(M.w0 and (M.w0 + (1.0 - M.w0) * math.min(1.0, M.t / M.tp.fade)) or (M.t / M.tp.fade),
    (P.slashCarry and PS.slashAsk ~= nil and not M.wave) and 1.0 or ((M.tp.time - M.t) / M.tp.fade)), 0.0, 1.0)
  PS.punchClip = M.tpClip
  if not M.done and M.t >= M.from then
    M.done = true
    if M.wave then guard("ARC WAVE", FPF.waveStart, M) else guard("the sword's hit", FPF.slashHit, ent, M) end
  end
  if M.t >= M.len then PS.slash = nil end
end

FPF.punch115 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "sword" then return FPF.punch115(dt, ent, key) end
  if key and S.driving and S.pilot and PS.execHint then
    PS.slash, PS.slashAsk = nil, nil
  elseif key then
    PS.slashAsk = { by = PS.punchBy or "the melee key" }
    PS.punchBy = nil
    key = false
  end
  local r = FPF.punch115(dt, ent, key)
  guard("the sword", FPF.swordFrame, dt, ent)
  return r
end

FPF.gunFrame115 = gunFrame
gunFrame = function(dt, ent, firing)
  if PS.weapon ~= "sword" then
    PS.swordFire = false
    return FPF.gunFrame115(dt, ent, firing)
  end
  FPF.gunChecks()
  PS.swordFire = (S.driving and S.pilot and firing) and true or false
  PS.reloadKey, PS.reloadW = false, 0.0
  local G = PS.gun
  if G then G.reloadT, G.anim = nil, nil end
end

FPF.drive115 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive115(dt, steps, sprinting)
  if PS.weapon ~= "sword" or not PF.shown or not PF.ent or not IsDefined(PF.ent) then return end
  local M = PS.slash
  if M then
    local t = math.min(M.t, M.fpTime)
    FPF.var("fp_melee_clip", M.fpClip)
    FPF.var("fp_melee", 1.0)
    FPF.var("fp_time_melee", t)
    local V = FP.view and FP.view[M.view]
    if V and #V >= 2 then
      local p, y, r = FPF.sway(V, t)
      PF.sway[1], PF.sway[2], PF.sway[3] = p, y, r
    end
  end
end

FPF.fpGun115 = FPF.fpGun
function FPF.fpGun(dt)
  if PS.weapon ~= "sword" then return FPF.fpGun115(dt) end
  if not FP.aim then return end
  local B = PS.swordBlock
  local on = B and B.on and not PS.slash and not PS.punch and not PS.pound and not (PS.vortex and PS.vortex.on)
  local t = PF.aimT or 0.0
  if on then t = math.min(FP.aim, t + dt) else t = math.max(0.0, t - dt) end
  PF.aimT = t
  FPF.var("fp_aim", (t > 0.0) and 1.0 or 0.0)
  FPF.var("fp_time_aim", t)
end

