FPF.damageFlats115 = FPF.damageFlats
function FPF.damageFlats()
  FPF.damageFlats115()
  local k, m, n = P.damageScale, FPF.perkValue("sworddamage"), 0
  if m == 1.0 then return end
  for _, R in ipairs(FPC.tune.damage) do
    if R[1] == FPC.sword.records.slash or R[1] == FPC.sword.records.core or R[1] == FPC.sword.records.wave then
      for i, kind in ipairs(FPC.tune.kinds) do
        local v = R[2][i] * k * m * ((kind == "boss") and P.bossMul or 1.0)
        if pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end) then n = n + 1 end
      end
      pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * k * m) end)
      pcall(function() TweakDB:Update(R[1]) end)
    end
  end
  if n > 0 then log(string.format("damage of BT's weapons: the BROADSWORD's records x %.2f (KEEN EDGE)", m)) end
end

