    out = out .. string.format("   BLOCK %d %%%s", math.floor(B.energy / FPC.sword.block.max * 100.0 + 0.5), B.on and " ON" or "")
  end
  if FPF.coreOn() then out = out .. "   SWORD CORE" end
  return out
end

