FPF.slashStart116 = FPF.slashStart
function FPF.slashStart(by, wave)
  local M = FPF.slashStart116(by, wave)
  if not M.wave then
    local K = FPC.sword
    local C = (M.n == 2) and PUNCH_CLIP.sword.dash or ((M.n == 3) and (PUNCH_CLIP.sword.s3 or PUNCH_CLIP.sword) or PUNCH_CLIP.sword)
    local F = (M.n == 1) and { time = FP.melee, hit = FP.meleeHitEnd or FP.meleeHit }
      or ((M.n == 2) and { time = FP.dash.time, hit = FP.dash.hitEnd or FP.dash.hit }
        or { time = FP.slash3 and FP.slash3.time, hit = FP.slash3 and (FP.slash3.hitEnd or FP.slash3.hit) })
    M.tp, M.tpClip = C, K.tpClips[M.n]
    M.fpTime = F.time or C.time
    M.from = (PF.shown and F.hit) or C.hit
    M.len = math.max(M.fpTime, M.tp.time)
  end
  return M
end

FPF.swordSound116 = FPF.swordSound
