  if list == S2.waveFire or list == S2.waveTravel then
    level = math.max(level or FPF.jarLevel(S.driving and S.pilot), FPC.sword.wave.soundLevel)
  end
  return FPF.swordSound116(list, level)
end

function FPF.waveCharge(dt)
  local K = FPC.sword.wave
  local c = PS.waveCharges or K.charges
  c = math.min(K.charges, c + (dt or 0.0) / K.every)
  PS.waveCharges = c
  PS.waveReadyAt = (c >= 1.0) and 0.0 or (S.clock + (1.0 - c) * K.every)
  return c
end

FPF.swordFrame116 = FPF.swordFrame
function FPF.swordFrame(dt, ent)
  FPF.waveCharge(dt)
  local waves = PS.waves or 0
  FPF.swordFrame116(dt, ent)
  if (PS.waves or 0) > waves then
    PS.waveCharges = math.max(0.0, (PS.waveCharges or FPC.sword.wave.charges) - 1.0)
    FPF.waveCharge(0.0)
    if (PS.waves or 0) <= FPC.sword.lines then
      log(string.format("ARC WAVE %d: %.1f of its %d charges left", PS.waves, PS.waveCharges, FPC.sword.wave.charges))
    end
  end
end

FPF.waveFrame116 = FPF.waveFrame
function FPF.waveFrame(dt)
  local W = PS.wave
  local before = W and W.step or 0
  FPF.waveFrame116(dt)
  if not W or not P.fxOn then return end
  local K = FPC.sword.wave
  for k = math.max(before, 1) + 1, W.step do
    local d = (k - 1.5) * K.step
    local x, y = W.x0 + W.fx * d, W.y0 + W.fy * d
    local inst = FPF.fxAt(K.fx2, x, y, W.z + K.up, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.life2 } end
  end
end

FPF.swordBlockFrame116 = FPF.swordBlockFrame
function FPF.swordBlockFrame(dt)
