  local B = FPF.swordBlockFrame116(dt)
  if B.on and not was then B.upAt = S.clock end
  return B
end

function FPF.swordHoldW()
  if PS.weapon ~= "sword" or PS.exec or PS.eject then return 0.0 end
  return clamp(1.0 - (PS.sceneW or 0.0), 0.0, 1.0)
end

function FPF.swordBlockW()
  local B, K = PS.swordBlock, FPC.sword
  local want = PS.weapon == "sword" and B ~= nil and B.on and not PS.slash and not PS.punch and not PS.pound
  local dt = clamp(S.clock - (PS.swordBlockWAt or S.clock), 0.0, 0.1)
  PS.swordBlockWAt = S.clock
  local w = PS.swordBlockW or 0.0
  if want then w = math.min(1.0, w + dt / K.blockIn) else w = math.max(0.0, w - dt / K.blockOut) end
  PS.swordBlockW = w
  return ease(w) * FPF.swordHoldW()
end

function FPF.coreSlashTake()
  if PS.weapon ~= "sword" or not FPF.coreOn() then return 1.0 end
  local M = PS.slash
  if not M or M.wave then return 1.0 end
  return FPC.sword.core.slashTake
end

function FPF.coreSlashSaid(kept)
  PS.coreSlashKept = (PS.coreSlashKept or 0.0) + kept
  PS.coreSlashHits = (PS.coreSlashHits or 0) + 1
  if PS.coreSlashHits <= 4 then
    log(string.format("Sword Core: a hit while a slash is under way taken at x %.2f - %.0f of V's health points kept off BT", FPC.sword.core.slashTake, kept))
  end
end

FPF.hitSeen116 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H = PS.hp
  local k = FPF.coreSlashTake()
  if not H or k >= 1.0 or type(H.pend[tag]) ~= "number" then return FPF.hitSeen116(evt, tag) end
  local before, big = H.pend[tag], H.bigV
  local r = FPF.hitSeen116(evt, tag)
  local added = H.pend[tag] - before
  if added > 0.0 then
    H.pend[tag] = before + added * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if tag == "a" then FPF.coreSlashSaid(added * (1.0 - k)) end
  end
  return r
end

function FPF.bossParry()
  local L = PS.lastParry
  if not L then return nil end
  return { at = L.at, ago = S.clock - L.at, n = PS.parries or 0, record = L.record, who = L.who }
end

FPF.bossHit116 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local B, K = PS.swordBlock, FPC.sword.parry
  if PS.weapon == "sword" and B and B.on and B.upAt and S.clock - B.upAt <= K.window and type(record) == "string" then
    local open = FPF.bossOpen()
    local melee = kind == "melee" or (kind == nil and FPF.bossMelee(record))
    local fx = (type(x) == "number") and (x - PS.x) or nil
    local fy = (type(y) == "number") and (y - PS.y) or nil
    if open and melee and FPF.swordTake(fx, fy, false) < 1.0 then
      PS.parries = (PS.parries or 0) + 1
      PS.lastParry = { at = S.clock, record = record, who = tostring(who) }
      FPF.swordSound(FPC.sword.sounds.armor, math.max(FPF.viewVolume(), 0.9))
      FPF.swordSound(FPC.sword.sounds.block, math.max(FPF.viewVolume(), 0.9))
      if PS.parries <= K.lines then
        log(string.format("PARRY %d: %s's blow (%s) met the block %.2f s after it went up (within %.2f s) - nothing taken; fpf.bossHit says \"parried\"",
          PS.parries, tostring(who), record, S.clock - B.upAt, K.window))
      end
      return true, "parried", 0.0
    end
  end
  local H = PS.hp
  local k = FPF.coreSlashTake()
  if not H or k >= 1.0 then return FPF.bossHit116(record, x, y, z, dx, dy, who, kind) end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit116(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" then
    local added = H.pend.a - a0
    H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - pts * (1.0 - k) end
    FPF.coreSlashSaid(added * (1.0 - k))
    pts = pts * k
  end
  return ok, what, pts
end

function FPF.swordNote()
  local out = ""
  local K = FPC.sword
  if FPF.perk("sword") > 0 then
    local c = PS.waveCharges or K.wave.charges
    local n = math.floor(c + 1e-6)
    if n >= K.wave.charges then
      out = string.format("   ARC WAVE x%d", n)
    elseif n >= 1 then
      out = string.format("   ARC WAVE x%d  %d", n, math.ceil((1.0 - (c - n)) * K.wave.every))
    else
      out = string.format("   ARC WAVE %d", math.ceil((1.0 - c) * K.wave.every))
    end
  end
  local B = PS.swordBlock
  if B and (B.on or B.energy < K.block.max - 0.5) then
    out = out .. string.format("   BLOCK %d %%%s", math.floor(B.energy / K.block.max * 100.0 + 0.5), B.on and " ON" or "")
  end
  if FPF.coreOn() then out = out .. "   SWORD CORE" end
  return out
end

