FPF.bind117 = FPF.bind
function FPF.bind(name, down)
  if name ~= "sentry" and name ~= "designate" and name ~= "flight" then return FPF.bind117(name, down) end
  PS.binds = PS.binds + 1
  if PS.binds <= 16 then log(string.format("Mod Settings key: %s %s", name, down and "pressed" or "released")) end
  S.keyHeld = S.keyHeld or {}
  if not down then
    S.keyHeld[name] = nil
    return
  end
  if S.keyHeld[name] and S.clock - S.keyHeld[name] < 5.0 then return end
  S.keyHeld[name] = S.clock
  if S.gone then return end
  if name == "designate" then
    if not S.driving then guard("TARGET DESIGNATOR", FPF.designate) end
  elseif S.driving and S.pilot and PS.mode == "pilot" then
    PS.keyN[name] = (PS.keyN[name] or 0) + 1
  end
end

function FPF.tacticsKeys(dt, f, s, sprint, dash, jump, held)
  FPF.flightFrame(dt, held)
  return FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
end

function FPF.sentryOn()
  local Q = PS.sentry
  return Q ~= nil and Q.stage ~= "out"
end

function FPF.sentryCan()
  if FPF.perk("sentry") < 1 then return false, "SENTRY MODE is disabled by the server loadout" end
  if PS.weapon == "sword" then return false, "the broadsword is equipped - no fist and no slash would be left to it" end
  local left = (PS.sentryReadyAt or 0.0) - S.clock
  if left > 0.0 then return false, string.format("its wait - %.1f s more", left) end
  if PS.jump then return false, "BT is in a jump" end
  if PS.punch or PS.lunge then return false, "its fist is out" end
  if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then return false, "it is in a dash" end
  if PS.skate then return false, "it skates" end
  if PS.flight then return false, "FLIGHT STRIKE is on" end
  if PS.exec then return false, "an execution" end
  return true
end

function FPF.sentryStart()
  local K = FPC.perk.sentryMode
  PS.sentry = { stage = "in", t = 0.0, at = S.clock }
  PS.sentries = (PS.sentries or 0) + 1
  PS.vx, PS.vy, PS.speed, PS.turn = 0.0, 0.0, 0.0, nil
  if PS.sentries <= K.lines then
    log(string.format("SENTRY MODE %d: BT drops into its crouch (%.2f s) - %.0f s at most; from in front (within %.0f deg of the view) a hit takes %.0f %%; the missiles come back %.1f times as fast; no punch",
      PS.sentries, FPC.sentryClip.into, K.time, K.front, K.take * 100.0, K.missiles))
  end
end

function FPF.sentryOutAt(share)
  local v = 1.0 - clamp(share, 0.0, 1.0)
  local lo, hi = 0.0, 1.0
  for _ = 1, 24 do
    local u = (lo + hi) * 0.5
    if u * u * (3.0 - 2.0 * u) < v then lo = u else hi = u end
  end
  return (lo + hi) * 0.5 * FPC.sentryClip.outof
end

function FPF.sentryEnd(why, free)
  local Q = PS.sentry
  if not Q or Q.stage == "out" then return end
  local K, C = FPC.perk.sentryMode, FPC.sentryClip
  local t = 0.0
  if Q.stage == "in" then t = FPF.sentryOutAt(1.0 - (1.0 - clamp(Q.t / C.into, 0.0, 1.0)) ^ 2.2) end
  Q.stage, Q.t, Q.free, Q.why = "out", t, free == true, why
  PS.sentryReadyAt = S.clock + K.wait
  if (PS.sentries or 0) <= K.lines then
    log(string.format("SENTRY MODE %d ends (%s) after %.1f s - it stands up; again in %.0f s", PS.sentries or 0, tostring(why), S.clock - Q.at, K.wait))
  end
end

function FPF.sentryYaw(dt)
  local K = FPC.perk.sentryMode
  local Q = PS.sentry
  if not Q or Q.free then return S.yaw end
  local lim = math.min(K.turn, P.twist - 1.0)
  local off = wrap180(S.yaw - PS.yaw)
  if math.abs(off) > lim then
    local step = math.min(math.abs(off) - lim, K.turnRate * dt)
    PS.yaw = wrap180(PS.yaw + ((off > 0) and step or -step))
    Q.turned = (Q.turned or 0.0) + step
    off = wrap180(S.yaw - PS.yaw)
  end
  return PS.yaw + clamp(off, -lim, lim)
end

function FPF.sentryTake(fx, fy)
  local Q = PS.sentry
  if not Q or Q.stage == "out" or (PS.sentryW or 0.0) < 0.5 or not fx or not fy then return 1.0 end
  local d = math.sqrt(fx * fx + fy * fy)
  if d < 0.5 then return 1.0 end
  local K = FPC.perk.sentryMode
  local r = math.rad(S.yaw)
  if (fx * -math.sin(r) + fy * math.cos(r)) / d < math.cos(math.rad(K.front)) then return 1.0 end
  return K.take
end

function FPF.sentryKept(kept)
  local Q = PS.sentry
  if not Q then return end
  Q.kept, Q.hits = (Q.kept or 0.0) + kept, (Q.hits or 0) + 1
  if Q.hits <= 4 then
    log(string.format("SENTRY MODE: a hit from in front taken at x %.2f - %.0f of V's health points kept off BT", FPC.perk.sentryMode.take, kept))
  end
end

function FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
  local K, C = FPC.perk.sentryMode, FPC.sentryClip
  local n = PS.keyN.sentry or 0
  local pressed = n ~= (PS.sentrySeen or 0)
  PS.sentrySeen = n
  local Q = PS.sentry
  if pressed then
    if Q and Q.stage ~= "out" then
      FPF.sentryEnd("its key")
    elseif not Q and not held then
      local ok, why = FPF.sentryCan()
      if ok then
        FPF.sentryStart()
      else
        PS.sentryRefused = (PS.sentryRefused or 0) + 1
        if PS.sentryRefused <= K.lines then log("SENTRY MODE's key: not now - " .. tostring(why)) end
      end
    end
  end
  Q = PS.sentry
  if not Q then
    PS.sentryW, PS.sentryEye, PS.sentryOut, PS.sentryT = 0.0, nil, 0.0, 0.0
    return f, s, sprint, dash, jump
  end
  if Q.stage ~= "out" then
    if held then
      FPF.sentryEnd("the keys are taken")
    elseif dash or jump then
      FPF.sentryEnd(dash and "a dash" or "a jump", true)
    elseif PS.useDown and S.clock - (PS.useDownAt or S.clock) > USE_HOLD then
      PS.sentryClimb = true
      FPF.sentryEnd("V climbs out")
    elseif S.clock - Q.at >= K.time then
      FPF.sentryEnd(string.format("its %.0f s are up", K.time))
    end
  end
  Q.t = Q.t + dt
  if Q.stage == "in" and Q.t >= C.into then
    Q.stage, Q.t = "hold", 0.0
    pcall(FPF.jumpSound, "land")
  end
  if Q.stage == "out" and Q.t >= C.outof then Q.done = true end
  if Q.done then
    PS.sentryW = math.max(0.0, (PS.sentryW or 0.0) - dt / K.fadeOut)
    if PS.sentryW <= 0.0 then
      PS.sentry, PS.sentryW, PS.sentryEye, PS.sentryOut, PS.sentryT = nil, 0.0, nil, 0.0, 0.0
      if PS.sentryClimb then
        PS.sentryClimb = nil
        PS.useDown, PS.useDownAt = true, S.clock - USE_HOLD - 0.01
      end
      return f, s, sprint, dash, jump
    end
  else
    PS.sentryW = math.min(1.0, (PS.sentryW or 0.0) + dt / K.fadeIn)
    if PS.sentryW >= 1.0 and not Q.settled then
      Q.settled = true
      PS.stand, PS.standT, PS.settleT, PS.stanceW, PS.settledW, PS.turn, PS.turnW = "settled", 10.0, SETTLE.time, 1.0, 1.0, nil, 0.0
    end
  end
  local list, t
  if Q.stage == "out" then
    PS.sentryOut, t, list = 1.0, math.min(Q.t, C.outof), C.carriedOut
  else
    PS.sentryOut, t, list = 0.0, (Q.stage == "in") and math.min(Q.t, C.into) or C.into, C.carriedIn
  end
  PS.sentryT = t
  local x = clamp(t * C.fps, 0.0, #list - 1)
  local i = math.floor(x)
  local a, b = list[i + 1], list[math.min(i + 2, #list)]
  local u, w = x - i, PS.sentryW
  local cr, ca, cu = a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u, a[3] + (b[3] - a[3]) * u
  local r = math.rad(PS.yaw)
  PS.sentryEye = { x = (cr * math.cos(r) - ca * math.sin(r)) * w, y = (cr * math.sin(r) + ca * math.cos(r)) * w, z = cu * w }
  if not Q.free then f, s, sprint = 0, 0, false end
  return f, s, sprint, dash, jump
end

FPF.mtmsRecharge117 = FPF.mtmsRecharge
function FPF.mtmsRecharge()
  local t = FPF.mtmsRecharge117()
  if FPF.sentryOn() then t = t / FPC.perk.sentryMode.missiles end
  return t
end

function FPF.flightImmune()
  local F = PS.flight
  return F ~= nil and F.on == true
end

function FPF.flightCan()
  if FPF.perk("flight") < 1 then return false, "FLIGHT STRIKE is disabled by the server loadout" end
  if FPF.perk("burstcore") < 2 then return false, "BURST CORE needs its level 2 for it" end
  local C = PS.core
  if not C then return false, "no core" end
  if C.left then return false, "a burst of the core burns" end
  local need = FPF.coreShot()
  if C.charge < need - 1e-6 then return false, string.format("the core is not full - %.0f of the %.0f it takes", C.charge, need), "charge" end
  if PS.exec then return false, "an execution" end
  return true
end

function FPF.flightStart()
  local K, C = FPC.perk.flightStrike, PS.core
  local need = FPF.coreShot()
  C.charge, C.readySaid = C.charge - need, nil
  if FPF.sentryOn() then FPF.sentryEnd("FLIGHT STRIKE", true) end
  local J = PS.jump
  if J and (J.stage == "land" or J.out) then
    FPF.jumpEnd("FLIGHT STRIKE")
    J = nil
  end
  if not J then
    FPF.jumpStart()
    J = PS.jump
  end
  J.flight = true
  PS.flights = (PS.flights or 0) + 1
  PS.flight = { t = 0.0, on = true, n = 0, aim = 0, auto = 0, nextAt = 0.0, picks = {}, pickAt = -10.0, pick = 0, kept = 0.0, boss = 0,
    z0 = PS.z, top = 0.0 }
  FPF.say("flightCore", true)
  if PS.flights <= K.lines then
    log(string.format("FLIGHT STRIKE %d: a burst of the core spent (%.0f of %.0f left) - BT rises %.0f m and hovers %.0f s, hits taken at x%.2f; %.0f rockets a second, every other one at the crosshair, the rest at foes it picks (within %.0f m, %.0f deg of the view)",
      PS.flights, C.charge, FPF.coreMax(), K.height, K.time, K.take or 0.0, K.rate, K.reach, K.cone))
  end
end

function FPF.flightStop(why)
  local F = PS.flight
  if not F then return end
  PS.flight = nil
  local J = PS.jump
  if J then J.flight = nil end
  if (PS.flights or 0) <= FPC.perk.flightStrike.lines then
    log(string.format("FLIGHT STRIKE %d over (%s) after %.1f s: %d rockets (%d at the crosshair, %d at foes BT picked), %.1f m up at the most; %.0f of V's health points kept off BT (%d bosses' blows among the hits)",
      PS.flights or 0, tostring(why), F.t, F.n, F.aim, F.auto, F.top, F.kept, F.boss))
  end
end

function FPF.flightAimPoint()
  local K = FPC.perk.flightStrike
  local ex, ey, ez = PS.x, PS.y, PS.z + FPC.mtms.eye
  local A = PS.aim
  local ax, ay, az
  if A then
    ax, ay, az = A.x, A.y, A.z
  else
    local dx, dy, dz = FPF.viewDir(ex, ey, ez)
    ax, ay, az = ex + dx * FPC.mtms.range, ey + dy * FPC.mtms.range, ez + dz * FPC.mtms.range
  end
  local far = math.sqrt((ax - ex) ^ 2 + (ay - ey) ^ 2 + (az - ez) ^ 2)
  local spread = 0.5 + far * K.spread
  return { x = ax + (math.random() * 2.0 - 1.0) * spread, y = ay + (math.random() * 2.0 - 1.0) * spread, z = az + math.random() * spread * 0.5, loose = true }
end

function FPF.sameEnt(a, b)
  if a == nil or b == nil then return false end
  local same = false
  pcall(function() same = tostring(a:GetEntityID()) == tostring(b:GetEntityID()) end)
  return same
end

function FPF.flightTargets()
  local K = FPC.perk.flightStrike
  refreshNpcs()
  local ex, ey, ez = PS.x, PS.y, PS.z + FPC.mtms.eye
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local cone = math.cos(math.rad(K.cone))
  local D = PS.designated
  local out = {}
  for i, ent in ipairs(PS.npcs) do
    if IsDefined(ent) then
      pcall(function()
        if not OP77.targetActive(ent) or OP77.targetHostile(ent) ~= true or (OP77.playerTarget(ent) and not OP77.titanPvp()) then return end
        local p = ent:GetWorldPosition()
        local dx, dy = p.x - PS.x, p.y - PS.y
        local d = math.sqrt(dx * dx + dy * dy)
        if d < 3.0 or d > K.reach or (dx * fx + dy * fy) / d < cone then return end
        local shape = PS.npcShape[i]
        local up = shape and ((shape[3] or 0.0) + shape[2] * 0.55) or FPC.buddy.chest
        if not FPF.buddyClear(ex, ey, ez, p.x, p.y, p.z + up) then return end
        out[#out + 1] = { ent = ent, d = d, up = up, first = D ~= nil and FPF.sameEnt(D.ent, ent) }
      end)
    end
  end
  table.sort(out, function(a, b)
    if a.first ~= b.first then return a.first end
    return a.d < b.d
  end)
  while #out > K.picks do table.remove(out) end
  return out
end

function FPF.flightPick(F)
  local K = FPC.perk.flightStrike
  if S.clock - F.pickAt >= K.every then
    F.pickAt = S.clock
    F.picks = FPF.flightTargets()
  end
  local list = F.picks
  for _ = 1, #list do
    F.pick = F.pick % #list + 1
    local T = list[F.pick]
    local p = nil
    pcall(function() if IsDefined(T.ent) and OP77.targetActive(T.ent) and not (OP77.playerTarget(T.ent) and not OP77.titanPvp()) then p = T.ent:GetWorldPosition() end end)
    if p then return { ent = T.ent, x = p.x, y = p.y, z = p.z + T.up, up = T.up } end
  end
  return nil
end

function FPF.flightRocket(F)
  local K = FPC.perk.flightStrike
  PS.mtms = PS.mtms or FPF.mtmsNew()
  local M = PS.mtms
  F.n = F.n + 1
  local q = (F.n % 2 == 0) and FPF.flightPick(F) or nil
  if q then F.auto = F.auto + 1 else F.aim, q = F.aim + 1, FPF.flightAimPoint() end
  local frac, lastUse, before = M.frac, M.lastUse, #PS.missiles
  FPF.mtmsFire(M, q)
  M.frac, M.lastUse = frac, lastUse
  if #PS.missiles > before then
    local m = PS.missiles[#PS.missiles]
    m.flight, m.speed = true, m.speed * K.speed
  end
end

function FPF.flightFrame(dt, held)
  local K = FPC.perk.flightStrike
  local n = PS.keyN.flight or 0
  if n ~= (PS.flightSeen or 0) then
    PS.flightSeen = n
    if not PS.flight and not PS.flightAsk then
      local ok, why, what = FPF.flightCan()
      if ok and not held then
        PS.flightAsk = S.clock
      else
        PS.flightRefused = (PS.flightRefused or 0) + 1
        if PS.flightRefused <= K.lines then log("FLIGHT STRIKE's key: not now - " .. tostring(held and "the keys are taken" or why)) end
        if what == "charge" and S.clock - (PS.flightNoCoreAt or -10.0) > 4.0 then
          PS.flightNoCoreAt = S.clock
          FPF.say("away", true, 2)
        end
      end
    end
  end
  if PS.flightAsk and not PS.flight then
    if held or S.clock - PS.flightAsk > K.ask then
      PS.flightAsk = nil
      log("FLIGHT STRIKE: it could not begin within " .. K.ask .. " s - not begun, the core kept")
    elseif not (PS.dashT ~= nil and PS.dashT < TF.dodgeTime) and not PS.punch and not PS.lunge then
      PS.flightAsk = nil
      local ok, why = FPF.flightCan()
      if ok then FPF.flightStart() else log("FLIGHT STRIKE: not begun - " .. tostring(why)) end
    end
  end
  local F = PS.flight
  if not F then return end
  F.t = F.t + dt
  local J = PS.jump
  if J and PS.z - F.z0 > F.top then F.top = PS.z - F.z0 end
  if held then
    FPF.flightStop("the keys are taken")
  elseif not J or J.stage == "land" then
    FPF.flightStop("BT is down")
  elseif J.pound then
    FPF.flightStop("GROUND POUND")
  elseif F.t >= K.time then
    FPF.flightStop(string.format("its %.0f s are up", K.time))
  end
  if not PS.flight or J.stage ~= "air" then return end
  F.nextAt = F.nextAt - dt
  local fired = 0
  while F.nextAt <= 0.0 and fired < 3 do
    FPF.flightRocket(F)
    F.nextAt, fired = F.nextAt + 1.0 / K.rate, fired + 1
  end
  if F.nextAt < 0.0 then F.nextAt = 0.0 end
end

FPF.jetThrust117 = FPF.jetThrust
function FPF.jetThrust(J, vz, dt)
  local F = PS.flight
  if J.pound or not (F and F.on and J.flight) then return FPF.jetThrust117(J, vz, dt) end
  local K = FPC.perk.flightStrike
  return clamp((J.floor + K.height - PS.z) * K.gain, -K.sink, K.climb)
end

FPF.jumpRate117 = FPF.jumpRate
function FPF.jumpRate(rate)
  local r = FPF.jumpRate117(rate)
  local F, J = PS.flight, PS.jump
  if F and F.on and J and J.stage == "air" then r = r * FPC.perk.flightStrike.steer end
  return r
end

FPF.coreGain117 = FPF.coreGain
function FPF.coreGain(points, what, name)
  if FPF.flightImmune() then return false end
  return FPF.coreGain117(points, what, name)
end

FPF.health117 = FPF.health

FPF.hitSeen117 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H = PS.hp
  if not H or not FPF.sentryOn() or not evt or type(H.pend[tag]) ~= "number" then return FPF.hitSeen117(evt, tag) end
  local before, big = H.pend[tag], H.bigV
  local r = FPF.hitSeen117(evt, tag)
  local added = H.pend[tag] - before
  if added > 0.0 then
    local fx, fy = nil, nil
    pcall(function()
      local p = evt.attackData:GetInstigator():GetWorldPosition()
      fx, fy = p.x - PS.x, p.y - PS.y
    end)
    local k = FPF.sentryTake(fx, fy)
    if k < 1.0 then
      H.pend[tag] = before + added * k
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
      if tag == "a" then FPF.sentryKept(added * (1.0 - k)) end
    end
  end
  return r
end

FPF.bossHit117 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local fx = (type(x) == "number") and (x - PS.x) or nil
  local fy = (type(y) == "number") and (y - PS.y) or nil
  local k = FPF.sentryTake(fx, fy)
  local H = PS.hp
  if k >= 1.0 or not H then return FPF.bossHit117(record, x, y, z, dx, dy, who, kind) end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit117(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" then
    local added = H.pend.a - a0
    H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - pts * (1.0 - k) end
    FPF.sentryKept(added * (1.0 - k))
    pts = pts * k
  end
  return ok, what, pts
end

function FPF.designable(ent)
  local ok = false
  pcall(function() ok = IsDefined(ent) and ent:IsNPC() == true and ScriptedPuppet.IsActive(ent) == true end)
  return ok and FPF.coreWorth(ent) ~= nil
end

function FPF.designated()
  local D = PS.designated
  if not D then return nil end
  local alive = false
  pcall(function() alive = IsDefined(D.ent) and OP77.targetActive(D.ent) == true end)
  if not alive then
    FPF.designateClear("it is down")
    return nil
  end
  if S.clock - D.at > FPC.perk.designate.keep then
    FPF.designateClear(string.format("its %.0f s are up", FPC.perk.designate.keep))
    return nil
  end
  return D
end

function FPF.designateClear(why)
  local D = PS.designated
  if not D then return end
  PS.designated = nil
  if D.ourTag then pcall(function() if IsDefined(D.ent) then GameObject.UntagObject(D.ent) end end) end
  if (PS.designations or 0) <= FPC.perk.designate.lines then
    log(string.format("TARGET DESIGNATOR: the mark on %s goes (%s) after %.1f s", D.what or "?", tostring(why), S.clock - D.at))
  end
end

function FPF.designateSearch(e, fx, fy, fz)
  local K = FPC.perk.designate
  refreshNpcs()
  local best, bestC = nil, math.cos(math.rad(K.cone))
  for i, ent in ipairs(PS.npcs) do
    if IsDefined(ent) then
      pcall(function()
        local p = ent:GetWorldPosition()
        local shape = PS.npcShape[i]
        local up = shape and ((shape[3] or 0.0) + shape[2] * 0.55) or FPC.buddy.chest
        local dx, dy, dz = p.x - e.x, p.y - e.y, p.z + up - e.z
        local d = math.sqrt(dx * dx + dy * dy + dz * dz)
        if d < 1.0 or d > K.range then return end
        local c = (dx * fx + dy * fy + dz * fz) / d
        if c > bestC and FPF.designable(ent) and FPF.buddyClear(e.x, e.y, e.z, p.x, p.y, p.z + up) then best, bestC = ent, c end
      end)
    end
  end
  return best
end

function FPF.designate()
  local K = FPC.perk.designate
  if FPF.perk("designator") < 1 then
    PS.designateRefused = (PS.designateRefused or 0) + 1
    if PS.designateRefused <= 4 then log("TARGET DESIGNATOR's key: disabled by the server loadout") end
    return
  end
  if not PS.ent then
    PS.designateRefused = (PS.designateRefused or 0) + 1
    if PS.designateRefused <= 4 then log("TARGET DESIGNATOR's key: no BT out") end
    return
  end
  local player = Game.GetPlayer()
  if not player then return end
  local e = viewOfV()
  local rp, ry = math.rad(e.pitch or 0.0), math.rad(e.yaw or 0.0)
  local fx, fy, fz = -math.sin(ry) * math.cos(rp), math.cos(ry) * math.cos(rp), math.sin(rp)
  local ent, how = nil, "under the crosshair"
  pcall(function() ent = Game.GetTargetingSystem():GetLookAtObject(player, false, false) end)
  if ent ~= nil and not FPF.designable(ent) then ent = nil end
  if ent ~= nil then
    local far = 0.0
    pcall(function()
      local p = ent:GetWorldPosition()
      far = math.sqrt((p.x - e.x) ^ 2 + (p.y - e.y) ^ 2 + (p.z - e.z) ^ 2)
    end)
    if far > K.range then ent = nil end
  end
  if ent == nil then
    ent, how = FPF.designateSearch(e, fx, fy, fz), string.format("within %.0f deg of the crosshair", K.cone)
  end
  if ent == nil then
    if PS.designated then
      FPF.designateClear("the key at nobody")
    else
      log("TARGET DESIGNATOR: nobody to mark under the crosshair")
    end
    return
  end
  local D = PS.designated
  if D and FPF.sameEnt(D.ent, ent) then
    D.at = S.clock
    return
  end
  FPF.designateClear("another foe marked")
  local tagged = false
  pcall(function() tagged = ent:IsTaggedinFocusMode() == true end)
  local done = false
  if not tagged then done = pcall(function() GameObject.TagObject(ent) end) end
  local up = FPC.buddy.chest
  for i, other in ipairs(PS.npcs or {}) do
    if FPF.sameEnt(other, ent) then
      local shape = PS.npcShape[i]
      if shape then up = (shape[3] or 0.0) + shape[2] * 0.55 end
    end
  end
  PS.designations = (PS.designations or 0) + 1
  PS.designated = { ent = ent, at = S.clock, seenAt = S.clock, up = up, ourTag = not tagged and done, what = personText(ent), n = PS.designations }
  pcall(FPF.tf, FPC.mtms.sounds.lock)
  if PS.designations <= K.lines then
    log(string.format("TARGET DESIGNATOR %d: %s marked (%s)%s - BT deals with it first", PS.designations, PS.designated.what, how,
      tagged and ", tagged already" or (done and ", the game's tag on it" or ", the game's tag could NOT be put on")))
  end
end

FPF.buddyLook117 = FPF.buddyLook
function FPF.buddyLook(B)
  FPF.buddyLook117(B)
  if not PS.designated or S.driving or not B or B.off or FPF.guardPlain() then return end
  local D = FPF.designated()
  if not D then return end
  local K = FPC.perk.designate
  local p = nil
  pcall(function() p = D.ent:GetWorldPosition() end)
  if not p then return end
  local d = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2)
  if d > K.range * 1.5 then
    FPF.designateClear("too far from BT")
    return
  end
  if FPF.buddyClear(PS.x, PS.y, PS.z + FPC.buddy.eye, p.x, p.y, p.z + D.up) then D.seenAt = S.clock end
  if S.clock - D.seenAt > K.seen then return end
  local T = B.target
  if T and T.ent and FPF.sameEnt(T.ent, D.ent) then
    T.x, T.y, T.z, T.up, T.dist, T.seenAt, T.designated = p.x, p.y, p.z + D.up, D.up, d, D.seenAt, true
    return
  end
  D.since = D.since or S.clock
  B.target = { ent = D.ent, x = p.x, y = p.y, z = p.z + D.up, up = D.up, dist = d, at = D.since, seenAt = D.seenAt,
    shots0 = (B.gun and B.gun.shots) or 0, designated = true }
  B.foeAt = S.clock
  D.taken = (D.taken or 0) + 1
  if D.taken <= 4 then log(string.format("TARGET DESIGNATOR: BT turns to the marked foe (%s, %.0f m)", D.what or "?", d)) end
end

FPF.aiSkillsRun117 = FPF.aiSkillsRun
function FPF.aiSkillsRun(B, A, dt, T)
  if not (T and T.designated and type(T.at) == "number") then return FPF.aiSkillsRun117(B, A, dt, T) end
  local at = T.at
  T.at = math.min(at, S.clock - FPC.ai.salvoLong - 0.01)
  local ok, err = pcall(FPF.aiSkillsRun117, B, A, dt, T)
  T.at = at
  if not ok then error(err, 0) end
end

FPF.mtmsRelease117 = FPF.mtmsRelease
function FPF.mtmsRelease(M, why)
  if not S.driving and PS.designated and M.locks > 0 and #M.targets > 1 then
    local D = FPF.designated()
    for _, T in ipairs(D and M.targets or {}) do
      if FPF.sameEnt(T.ent, D.ent) then
        local room = math.floor((1.0 - M.frac) * FPF.mtmsSalvo() + 0.001)
        T.n = math.max(T.n or 1, room)
        M.targets, M.locks = { T }, T.n
        D.salvos = (D.salvos or 0) + 1
        if D.salvos <= 4 then log(string.format("TARGET DESIGNATOR: BT's salvo all at the marked foe (%d missiles)", T.n)) end
        break
      end
    end
  end
  return FPF.mtmsRelease117(M, why)
end

FPF.slotStates117 = FPF.slotStates
function FPF.slotStates(M, V, Q)
  local out = FPF.slotStates117(M, V, Q)
  if FPF.perk("sentry") > 0 then
    local K = FPC.perk.sentryMode
    local R = PS.sentry
    local left = (PS.sentryReadyAt or 0.0) - S.clock
    if R and R.stage ~= "out" then
      out.sentry = { fill = clamp(1.0 - (S.clock - R.at) / K.time, 0.0, 1.0), state = "active" }
    elseif left > 0.0 then
      out.sentry = { fill = clamp(1.0 - left / K.wait, 0.0, 1.0), state = "empty" }
    else
      out.sentry = { state = (PS.weapon == "sword") and "empty" or "ready" }
    end
  end
  return out
end

FPF.slotsApply117 = FPF.slotsApply
function FPF.slotsApply(U, want)
  FPF.slotsApply117(U, want)
  local Z = U.slots and U.slots.sentry
  if not Z or not Z.glow then return end
  local on = want ~= nil and want.sentry ~= nil
  if Z.glow.last.shown118 == on then return end
  Z.glow.last.shown118 = on
  for _, part in pairs(Z) do
    if type(part) == "table" and part.w then
      pcall(function() part.w:SetVisible(on and part.last.visible ~= false) end)
    end
  end
end

