function FPF.poundScale(k)
  local names = { [PUNCH.attack] = true, ["Attacks.BT7274_Pound_Mid"] = true, ["Attacks.BT7274_Pound_Edge"] = true }
  local n = 0
  for _, R in ipairs(FPC.tune.damage) do
    if names[R[1]] then
      for i, kind in ipairs(FPC.tune.kinds) do
        local v = R[2][i] * P.damageScale * ((kind == "boss") and P.bossMul or 1.0) * k
        if pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end) then n = n + 1 end
      end
      pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * P.damageScale * k) end)
      pcall(function() TweakDB:Update(R[1]) end)
    end
  end
  return n
end

FPF.poundSlam118 = FPF.poundSlam
function FPF.poundSlam(J)
  local K = FPC.perk.poundHeight
  local fell = (J.z0 + J.top) - PS.z
  local k = clamp(fell / K.ref, K.least, K.most)
  local n = FPF.poundScale(k)
  local wreck = FPC.wreck.punch
  FPC.wreck.punch = wreck * k
  local ok, r = pcall(FPF.poundSlam118, J)
  FPC.wreck.punch = wreck
  PS.poundBackAt = S.clock + K.back
  PS.poundHeights = (PS.poundHeights or 0) + 1
  if PS.poundHeights <= K.lines then
    log(string.format("GROUND POUND %d: it came down from %.1f m - its shock hits x %.2f (%.0f m is x 1; %d values written)", PS.pounds or 0, fell, k, K.ref, n))
  end
  if not ok then error(r, 0) end
  return r
end

function FPF.poundBackFrame()
  if PS.poundBackAt and S.clock >= PS.poundBackAt then
    PS.poundBackAt = nil
    FPF.poundScale(1.0)
  end
end

function FPF.designatePick()
  local K = FPC.perk.designate
  local player = Game.GetPlayer()
  if not player then return nil end
  local e = viewOfV()
  local rp, ry = math.rad(e.pitch or 0.0), math.rad(e.yaw or 0.0)
  local fx, fy, fz = -math.sin(ry) * math.cos(rp), math.cos(ry) * math.cos(rp), math.sin(rp)
  local ent, how = nil, "under the crosshair"
  pcall(function() ent = Game.GetTargetingSystem():GetLookAtObject(player, false, false) end)
  if ent ~= nil and not FPF.designable(ent) then ent = nil end
  if ent ~= nil then
    local far = 0.0
    pcall(function()
      local p = ent:GetWorldPosition()
      far = math.sqrt((p.x - e.x) ^ 2 + (p.y - e.y) ^ 2 + (p.z - e.z) ^ 2)
    end)
    if far > K.range then ent = nil end
  end
  if ent == nil then
    ent, how = FPF.designateSearch(e, fx, fy, fz), string.format("within %.0f deg of the crosshair", K.cone)
  end
  return ent, how
end

FPF.designate118 = FPF.designate
function FPF.designate()
