  if FPF.perk("designator") >= 1 and PS.ent and D then
    local ent = FPF.designatePick()
    if ent ~= nil and FPF.sameEnt(D.ent, ent) then
      FPF.designateClear("the key at the marked foe again")
      pcall(FPF.tf, FPC.mtms.sounds.dry)
      return
    end
  end
  return FPF.designate118()
end

function FPF.flightRecords()
