FPC.swordAI = { near = 7.0, reach = 11.0, slashGap = 1.8, seen = 1.0, leash = 45.0, rise = 6.0, dashFar = 14.0, dashGap = { 1.0, 2.0 },
  dashFirst = { 0.2, 0.6 }, backRoom = 6.0, vGap = 4.0,
  back = { slashes = { 2, 4 }, every = { 7.0, 11.0 }, time = { 0.9, 1.4 }, dash = 0.6, gap = 3.0 },
  parry = { chance = 0.3, gap = 6.0, hold = 0.6, louder = 0.15, lines = 8 }, lines = 12 }
P.aiSword = true

function FPF.swordChase(B, dt)
  local K = FPC.swordAI
  local T = B.target
  local open = P.aiSword and PS.weapon == "sword" and T ~= nil and T.ent ~= nil and not P.hold and not B.off
    and (not P.peace or T.designated == true) and not B.board and not FPF.guardPlain() and FPF.questHeld() == nil
    and S.clock - (T.seenAt or -10.0) <= K.seen
  local vd = 0.0
  if open then
    vd = math.sqrt(((B.vx or PS.x) - T.x) ^ 2 + ((B.vy or PS.y) - T.y) ^ 2)
    open = vd <= K.leash and math.abs(T.z - (T.up or 0.0) - PS.z) <= K.rise
  end
  local C = B.chase
  if not open then
    if C then B.chase, B.path, B.pathGoal, B.detour, B.prog = nil, nil, nil, nil, nil end
    return nil
  end
  local Z = B.sword
  if not Z then
    Z = { chases = 0, dashes = 0, backs = 0, backDashes = 0 }
    B.sword = Z
  end
  local KB = K.back
  if not C or not FPF.sameEnt(C.ent, T.ent) then
    C = { ent = T.ent, mode = "close", dashAt = S.clock + FPF.aiDashGap(K.dashFirst), nearT = 0.0, nearNeed = FPF.aiDashGap(KB.every),
      slashes = PS.slashes or 0, need = math.random(KB.slashes[1], KB.slashes[2]), backEnd = -100.0 }
    B.chase, B.detour = C, nil
    Z.chases = Z.chases + 1
    if Z.chases <= K.lines then
      log(string.format("BT on its own, the broadsword: it goes for its foe (%.0f m away, %.0f m from V)", T.dist or -1.0, vd))
    end
  end
  if C.mode == "back" then
    if C.till == nil and PS.slash == nil then C.till = S.clock + FPF.aiDashGap(KB.time) end
    if C.till and S.clock >= C.till then
      C.mode, C.till, C.backEnd, B.detour = "close", nil, S.clock, nil
      C.nearT, C.nearNeed = 0.0, FPF.aiDashGap(KB.every)
      C.slashes, C.need = PS.slashes or 0, math.random(KB.slashes[1], KB.slashes[2])
    end
  else
    if (T.dist or 1000.0) <= K.reach then C.nearT = C.nearT + dt end
    local did = (PS.slashes or 0) - C.slashes
    local why = nil
    if did >= C.need then
      why = string.format("after %d slashes", did)
    elseif C.nearT >= C.nearNeed then
      why = string.format("%.0f s at its foe", C.nearT)
    end
    local M = PS.slash
    if why and S.clock - C.backEnd >= KB.gap and (M == nil or M.done) and PS.dashT == nil and PS.lunge == nil then
      C.mode, C.till, C.backDash, C.backDashed, B.detour = "back", nil, math.random() < KB.dash, false, nil
      PS.slashAsk = nil
      Z.backs = Z.backs + 1
      if Z.backs <= K.lines then
        log(string.format("BT on its own, the broadsword: it backs off (%s; its foe %.1f m away)%s", why, T.dist or -1.0, C.backDash and " - a dash back" or ""))
      end
    end
  end
  return C
end

FPF.buddyHeading118 = FPF.buddyHeading
function FPF.buddyHeading(B)
  local C, T = B.chase, B.target
  if not C or not T then return FPF.buddyHeading118(B) end
  local K = FPC.swordAI
  local dx, dy = T.x - PS.x, T.y - PS.y
  local n = math.sqrt(dx * dx + dy * dy)
  if n < 0.5 then return nil end
  local back = C.mode == "back"
  if not back and n <= K.near then return nil end
  local hx, hy = dx / n, dy / n
  if back then hx, hy = -hx, -hy end
  local room = back and K.backRoom or (n - K.near)
  local vx, vy = (B.vx or PS.x) - PS.x, (B.vy or PS.y) - PS.y
  local along = vx * hx + vy * hy
  if along > 0.0 and along < math.min(room, 2.0 * K.backRoom) + K.vGap and math.abs(vy * hx - vx * hy) < K.vGap then
    local sx, sy = -hy, hx
    if sx * vx + sy * vy > 0.0 then sx, sy = -sx, -sy end
    if back then hx, hy = sx, sy else hx, hy = (hx + sx) * 0.7071, (hy + sy) * 0.7071 end
    C.roundV = (C.roundV or 0) + 1
  end
  return hx, hy, room
end

FPF.buddyPath118 = FPF.buddyPath
function FPF.buddyPath(B)
  if B.chase then
    B.pathAt = S.clock
    return
  end
  return FPF.buddyPath118(B)
end

FPF.buddyActive118 = FPF.buddyActive
function FPF.buddyActive(B, dt)
  pcall(FPF.swordShowFrame)
  local ok, C = pcall(FPF.swordChase, B, dt)
  if not ok then
    once("aisword" .. tostring(C), "BT on its own: its way with the sword could NOT be run (" .. tostring(C) .. ") - it keeps to V as before")
    P.aiSword, B.chase, C = false, nil, nil
  end
  if not C then return FPF.buddyActive118(B, dt) end
  local K, Q = FPC.buddy, FPC.pace
  local stop, keep, U = K.stop, Q.keep, B.gaveUp
  K.stop, Q.keep, B.go, B.prog, B.gaveUp = -1.0, -100.0, true, nil, nil
  local ok2, err = pcall(FPF.buddyActive118, B, dt)
  K.stop, Q.keep = stop, keep
  if B.gaveUp == nil then B.gaveUp = U end
  B.prog = nil
  if not ok2 then error(err, 0) end
end

FPF.aiSkills118 = FPF.aiSkills
function FPF.aiSkills(B, dt, T)
  local C = B.chase
  if not C or PS.weapon ~= "sword" then return FPF.aiSkills118(B, dt, T) end
  local K = FPC.ai
  local reach, gap, cone = K.punchReach, K.punchGap, K.punchCone
  K.punchReach = (C.mode == "back") and -1.0 or math.max(FPF.swordReach(), FPC.swordAI.reach)
  K.punchGap, K.punchCone = FPC.swordAI.slashGap, FPC.sword.ai.cone
  local ok, err = pcall(FPF.aiSkills115, B, dt, T)
  K.punchReach, K.punchGap, K.punchCone = reach, gap, cone
  if not ok then error(err, 0) end
end

function FPF.chaseDash(B, C, T)
  local K = FPC.swordAI
  local want = nil
  if C.mode == "back" then
    if C.backDash and not C.backDashed and C.till ~= nil then want = "back" end
  elseif (T.dist or 0.0) > K.dashFar and S.clock >= C.dashAt then
    want = "at"
  end
  if not want then return nil end
  if B.board or B.leap or B.leapOn or PS.jump or PS.dashT ~= nil or PS.punch or PS.lunge or PS.slash or (PS.punchW or 0.0) > 0.001
      or (PS.vortex and PS.vortex.on) or PS.power < TF.dodgeDrain or PS.sinceDash < TF.dodgeTime + TF.dodgeInterval then
    return nil
  end
  local tx, ty = T.x - PS.x, T.y - PS.y
  local tn = math.sqrt(tx * tx + ty * ty)
  if tn < 0.5 then return nil end
  tx, ty = tx / tn, ty / tn
  local side = (math.random() < 0.5) and 1.0 or -1.0
  local lx, ly = -ty * side, tx * side
  local ways
  if want == "at" then
    ways = { { tx, ty, "straight at its foe" }, { (tx + lx) * 0.7071, (ty + ly) * 0.7071, "at its foe, half to a side" },
      { (tx - lx) * 0.7071, (ty - ly) * 0.7071, "at its foe, half to the other side" } }
    if math.random() < 0.4 then ways[1], ways[2] = ways[2], ways[1] end
  else
    ways = { { -tx, -ty, "back from its foe" }, { (-tx + lx) * 0.7071, (-ty + ly) * 0.7071, "back from its foe, half to a side" },
      { (-tx - lx) * 0.7071, (-ty - ly) * 0.7071, "back from its foe, half to the other side" } }
  end
  for _, w in ipairs(ways) do
    if FPF.aiDashFree(B, w[1], w[2]) then
      local r = math.rad(B.yaw)
      local cfx, cfy = -math.sin(r), math.cos(r)
      B.dash.want = { x = w[1], y = w[2], name = w[3], kind = (want == "at") and "ahead" or "side", hot = false, dist = tn, chase = want }
      return w[1] * cfx + w[2] * cfy, w[1] * cfy - w[2] * cfx
    end
  end
  if want == "back" then C.backDashed = true else C.dashAt = S.clock + FPC.aiDash.again end
  return nil
end

FPF.aiDash118 = FPF.aiDash
function FPF.aiDash(B, dt, T)
  local C = B.chase
  if not C or not T then return FPF.aiDash118(B, dt, T) end
  local on = P.aiDash
  P.aiDash = false
  local ok, err = pcall(FPF.aiDash118, B, dt, T)
  P.aiDash = on
  if not ok then error(err, 0) end
  if not on or P.hold or B.off or P.peace or FPF.questHeld() ~= nil then return nil end
  local f, s = FPF.chaseDash(B, C, T)
  if f then return f, s end
  if C.mode == "close" and (T.dist or 1000.0) <= FPC.swordAI.near + 3.0 then return FPF.aiDash118(B, dt, T) end
  return nil
end

FPF.aiDashBegun118 = FPF.aiDashBegun
function FPF.aiDashBegun(B, begun)
  local W = B.dash and B.dash.want
  local chase = W and W.chase
  FPF.aiDashBegun118(B, begun)
  local C, Z = B.chase, B.sword
  if not chase or not C or not Z then return end
  if not begun then
    C.dashAt = S.clock + FPC.aiDash.again
  elseif chase == "back" then
    C.backDashed, Z.backDashes = true, Z.backDashes + 1
  else
    C.dashAt, Z.dashes = S.clock + FPF.aiDashGap(FPC.swordAI.dashGap), Z.dashes + 1
  end
end

FPF.swordBlockFrame118 = FPF.swordBlockFrame
function FPF.swordBlockFrame(dt)
  local B = PS.swordBlock
  if B and B.aiTill then
    if S.clock < B.aiTill and not S.driving and PS.weapon == "sword" then return B end
    B.aiTill, B.on, B.idle = nil, false, 0.0
  end
  return FPF.swordBlockFrame118(dt)
end

function FPF.aiParry(record, x, y, dx, dy, who, kind)
  local K = FPC.swordAI.parry
  local Bd = PS.buddy
  if not P.aiSword or PS.weapon ~= "sword" or S.driving or type(record) ~= "string" or not Bd or Bd.state ~= "active" then return false end
  if PS.flight and PS.flight.on then return false end
  local open, why = FPF.bossOpen()
  if not open or why ~= "nobody in it" then return false end
  local melee = kind == "melee" or (kind == nil and FPF.bossMelee(record))
  if not melee or PS.slash or PS.punch or PS.pound or PS.dashT ~= nil or PS.jump or (PS.hp and PS.hp.doomed) then return false end
  local fx = (type(x) == "number") and (x - PS.x) or nil
  local fy = (type(y) == "number") and (y - PS.y) or nil
  if (fx == nil or fx * fx + fy * fy < 0.25) and type(dx) == "number" and type(dy) == "number" then fx, fy = -dx, -dy end
  if fx and fy then
    local d = math.sqrt(fx * fx + fy * fy)
    if d >= 0.1 then
      local r = math.rad(Bd.yaw or PS.yaw)
      if (fx * -math.sin(r) + fy * math.cos(r)) / d < math.cos(math.rad(FPC.sword.block.arc)) then return false end
    end
  end
  local Z = PS.aiParry
  if not Z then
    Z = { asked = 0, n = 0, nextAt = 0.0 }
    PS.aiParry = Z
  end
  if S.clock < Z.nextAt then return false end
  Z.asked = Z.asked + 1
  if math.random() >= K.chance then return false end
  Z.n, Z.nextAt = Z.n + 1, S.clock + K.gap
  local Bk = PS.swordBlock or FPF.swordBlockFrame(0.0)
  Bk.on, Bk.upAt, Bk.aiTill = true, S.clock, S.clock + K.hold
  PS.parries = (PS.parries or 0) + 1
  PS.lastParry = { at = S.clock, record = record, who = tostring(who), ai = true }
  local level = math.min(0.9, FPF.jarLevel(false) + K.louder)
  FPF.swordSound(FPC.sword.sounds.armor, level)
  FPF.swordSound(FPC.sword.sounds.block, level)
  if Z.n <= K.lines then
    log(string.format("PARRY %d (BT on its own, %d of the %d blows it could have parried): %s's blow (%s) met its block - nothing taken; fpf.bossHit says \"parried\"",
      PS.parries, Z.n, Z.asked, tostring(who), record))
  end
  return true
end

FPF.bossHit118 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local ok, parried = pcall(FPF.aiParry, record, x, y, dx, dy, who, kind)
  if not ok then
    once("aiparry" .. tostring(parried), "BT on its own: its parry could NOT be run (" .. tostring(parried) .. ")")
  elseif parried then
    return true, "parried", 0.0
  end
  local Bk = PS.swordBlock
  if not S.driving and Bk and Bk.aiTill then
    local up = Bk.upAt
    Bk.upAt = nil
    local ok2, a, b, c = pcall(FPF.bossHit118, record, x, y, z, dx, dy, who, kind)
    Bk.upAt = up
    if not ok2 then error(a, 0) end
    return a, b, c
  end
  return FPF.bossHit118(record, x, y, z, dx, dy, who, kind)
end

