function FPF.execSwordFrame(E)
  local d, K = E.d, FPC.sword.exec
  local t = clamp(E.t or 0.0, 0.0, d.time)
  E.imps = E.imps or 0
  while d.imp and E.imps < #d.imp and t >= d.imp[E.imps + 1][1] do
    E.imps = E.imps + 1
    local v = d.imp[E.imps]
    if P.fxOn then
      local x, y, z = btPoint(v[2], v[3], v[4])
      if FPF.fxAt(FPF.fxPath("punch"), x, y, z, PS.yaw, 0.0) then E.fx = (E.fx or 0) + 1 end
    end
  end
  local g = d.glow
  if g and g[1] and P.fxOn and t >= g[1] and t < g[2] and S.clock >= (E.glowAt or 0.0) then
    E.glowAt = S.clock + K.glowEvery
    local m = slotWorld(FPC.guns.sword.slot)
    local h = m and slotWorld("hand_r")
    if h then m = { x = (m.x + h.x) * 0.5, y = (m.y + h.y) * 0.5, z = (m.z + h.z) * 0.5 } end
    if m then
      local inst = FPF.fxAt(FPC.sword.wave.fx2, m.x, m.y, m.z, nil, nil)
      if inst then
        PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.glowLife }
        E.glows = (E.glows or 0) + 1
      end
    end
  end
end

