function FPF.swordHideNow()
  if PS.eject then return true, "eject" end
  local E = PS.exec
  if E and E.kind == "sword" and E.d and E.d.hide then
    local t = E.t or 0.0
    for _, h in ipairs(E.d.hide) do
      if t >= h[1] and t < h[2] then return true, "back" end
    end
    return false
  end
  if PS.execSwordOut then
    if PS.execOut and (PS.pilotW or 0.0) < 0.95 then return true, "back" end
    PS.execSwordOut = nil
  end
  return false
end

function FPF.swordShowFrame()
  if PS.weapon ~= "sword" or not PS.ent then
    PS.swordHidden = nil
    return
  end
  local hide, why = FPF.swordHideNow()
  if hide == (PS.swordHidden == true) then return end
  PS.swordHidden = hide
  local G = FPC.guns.sword
  pcall(function() PS.ent:FindComponentByName(G.mesh):Toggle(not hide and not PF.shown) end)
  pcall(function() PS.ent:FindComponentByName(G.shadow):Toggle(not hide) end)
  PS.swordHides = (PS.swordHides or 0) + (hide and 1 or 0)
  if hide and why == "eject" then
    log("the broadsword is put away while BT throws V out (the scene's clip holds the gun in the middle)")
  elseif PS.swordHides <= 8 then
    log(hide and "the broadsword is not shown while it hangs on BT's back (the execution's start or end)" or "the broadsword is shown again")
  end
end

