function FPF.aiSentryWant(B, T)
  local K = FPC.aiTactics.sentry
  if not P.aiTactics or not T or B.off or P.peace or P.hold or B.chase or B.go or B.board or (B.dist or 0.0) > K.vNear then return false end
  if S.clock < (B.sentryLookAt or 0.0) then return false end
  B.sentryLookAt = S.clock + K.look
  if FPF.guardPlain() or FPF.questHeld() ~= nil or S.clock - (T.seenAt or -10.0) > 1.0 then return false end
  local ok = FPF.sentryCan()
  if not ok then return false end
  local seen = FPF.aiView(FPF.mtmsSeen) or {}
  local A = B.ai
  local hot = A ~= nil and (A.heat or 0.0) >= K.heat * (FPC.health.segment * FPC.health.segments + FPC.health.shield)
  local why = (hot and "it is being hit hard") or ((#seen >= K.foes) and string.format("%d foes in view", #seen))
    or (((T.dist or 0.0) >= K.range) and string.format("its foe %.0f m away", T.dist)) or nil
  return why ~= nil, why
end

function FPF.aiSentryFrame(B, dt)
  local K = FPC.aiTactics.sentry
  local T = B.target
  local Q = PS.sentry
  if not Q then
    local want, why = FPF.aiSentryWant(B, T)
    if want then
      FPF.sentryStart()
      PS.sentry.ai = true
      B.sentries = (B.sentries or 0) + 1
      if B.sentries <= FPC.aiTactics.lines then log("BT on its own crouches into SENTRY MODE (" .. tostring(why) .. ")") end
    end
  elseif Q.stage ~= "out" then
    if T then B.sentrySeen = S.clock end
    local why = nil
    if S.clock - Q.at >= K.most then
      why = string.format("%.0f s on its own", K.most)
    elseif S.clock - (B.sentrySeen or Q.at) > K.lostFor then
      why = string.format("no foe for %.0f s", K.lostFor)
    elseif B.go or B.chase or B.off or P.hold or (B.dist or 0.0) > K.vNear then
      why = "it is to go"
    end
    if why then FPF.sentryEnd(why) end
  end
  if PS.sentry then
    local ud = PS.useDown
    PS.useDown = false
    local ok, err = pcall(FPF.sentryFrame, dt, 0.0, 0.0, false, false, false, false)
    PS.useDown = ud
    if not ok then error(err, 0) end
  end
end

