      boss = what == "a boss"
    end)
    local seen = FPF.aiView(FPF.mtmsSeen) or {}
    local why = (boss and "its foe is a boss") or ((#seen >= K.foes) and string.format("%d foes in view", #seen))
      or ((math.random() < K.chance) and "now and then") or nil
    if why then
      FPF.flightStart()
      if PS.flight then PS.flight.ai = true end
      B.flights = (B.flights or 0) + 1
      if B.flights <= FPC.aiTactics.lines then log("BT on its own spends its core on FLIGHT STRIKE (" .. why .. ")") end
      return true
    end
  end
  return FPF.coreFire119(by)
end

