FPC.perk.flightStrike.take = 0.5

function FPF.flightKept(n, who, record)
  local F = PS.flight
  if not F or n <= 0.0 then return end
  F.kept = F.kept + n
  PS.flightHits = (PS.flightHits or 0) + 1
  if PS.flightHits > 6 then return end
  if who then
    log(string.format("FLIGHT STRIKE: %s's blow (%s) taken at x%.2f - %.0f of V's health points kept off BT; fpf.bossHit says \"taken\"",
      tostring(who), tostring(record), FPC.perk.flightStrike.take, n))
  else
    log(string.format("FLIGHT STRIKE: a hit taken at x%.2f - %.0f of V's health points kept off BT", FPC.perk.flightStrike.take, n))
  end
end

FPF.hitSeen120 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H, F = PS.hp, PS.flight
  if not H or not (F and F.on) or not evt or type(H.pend[tag]) ~= "number" then return FPF.hitSeen120(evt, tag) end
  local before, big = H.pend[tag], H.bigV
  local r = FPF.hitSeen120(evt, tag)
  local added = H.pend[tag] - before
  if added > 0.0 then
    local k = FPC.perk.flightStrike.take
    H.pend[tag] = before + added * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if tag == "a" then FPF.flightKept(added * (1.0 - k)) end
  end
  return r
end

FPF.bossHit120 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  local H, F = PS.hp, PS.flight
  if not H or not (F and F.on) then return FPF.bossHit120(record, x, y, z, dx, dy, who, kind) end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit120(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" then
    local k = FPC.perk.flightStrike.take
    local added = H.pend.a - a0
    H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - pts * (1.0 - k) end
    F.boss = F.boss + 1
    FPF.flightKept(added * (1.0 - k), who or "a boss", record)
    pts = pts * k
  end
  return ok, what, pts
end

