FPF.slashStart124 = FPF.slashStart
function FPF.slashStart(by, wave)
  local M = FPF.slashStart124(by, wave)
  local K = FPC.sword.charge
  if M and not M.wave and K.on and PS.meleeHeld and S.driving and S.pilot and by ~= "the fire key" then
