FPF.swordFrame124 = FPF.swordFrame
function FPF.swordFrame(dt, ent)
  local M = PS.slash
  local C = M and M.charge
  local rate = nil
  if C and C.holding then rate, M.rate = M.rate, 0.0 end
  local ok, err = pcall(FPF.swordFrame124, dt, ent)
  if rate then M.rate = rate end
  if not ok then error(err, 0) end
  local ok2, err2 = pcall(FPF.chargeFrame)
  if not ok2 then once("charge" .. tostring(err2), "the charged slash could NOT be run (" .. tostring(err2) .. ")") end
end

function FPF.chargeFrame()
  local M = PS.slash
  local C = M and M.charge
  if not C or C.over then return end
  local K = FPC.sword.charge
  local held = PS.meleeHeld == true and S.driving and S.pilot
  if not C.from then
    if not held then
      C.over = true
      return
    end
    if M.t < C.hold then return end
    C.from, C.holding, M.t = S.clock, true, C.hold
    PS.charges = (PS.charges or 0) + 1
    C.n = PS.charges
    if C.n <= K.lines then
      log(string.format("CHARGE %d: the melee key held - swing %d of three stops where its wind-up ends (%.2f s of its clip, %s), full in %.1f s",
        C.n, M.n or 0, C.hold, C.fp and "in view" or "outside", FPF.chargeFull(K)))
    end
  end
  if C.holding then
    C.level = clamp((S.clock - C.from) / FPF.chargeFull(K), 0.0, 1.0)
    if held and S.clock - C.from < K.most then
      FPF.chargeShake(M, C)
      pcall(FPF.chargeFx, C)
      return
    end
    C.holding, C.shake = false, nil
    C.held = S.clock - C.from
    if C.level >= K.least then
      M.charged = C.level
      FPF.swordSound(FPC.sword.sounds.waveFire, FPF.viewVolume())
    end
    if C.n <= K.lines then
      log(string.format("CHARGE %d let go after %.2f s%s: %s", C.n, C.held, held and " (held its longest)" or "",
        M.charged and string.format("charged %.0f %% - x %.2f, %.1f m further, %.0f deg wider, the game's electrocution on whoever it meets",
          M.charged * 100.0, 1.0 + (K.damage - 1.0) * M.charged, K.reach * M.charged, K.angle * M.charged) or "too little - a plain slash"))
    end
  end
  if M.charged and not M.done then pcall(FPF.chargeFx, C) end
  if M.done then C.over = true end
end

function FPF.chargeShake(M, C)
  local K = FPC.sword.charge.tremble
  local t = S.clock - C.from
  local wave = 0.6 * math.sin(t * K.hz[1] * 2.0 * math.pi) + 0.4 * math.sin(t * K.hz[2] * 2.0 * math.pi + 1.3)
  C.shake = (0.4 + 0.6 * C.level) * (0.5 + 0.5 * wave)
  PS.punchW = math.min(PS.punchW or 1.0, 1.0 - K.tp * C.shake)
end

FPF.drive124 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive124(dt, steps, sprinting)
  local M = PS.slash
  local C = M and M.charge
  if C and C.holding and C.shake and PS.weapon == "sword" and PF.shown and PF.ent and IsDefined(PF.ent) then
    FPF.var("fp_melee", 1.0 - FPC.sword.charge.tremble.fp * C.shake)
  end
end

function FPF.chargeFx(C)
  local K = FPC.sword.charge
  if not P.fxOn or S.clock < (C.fxAt or 0.0) then return end
  C.fxAt = S.clock + K.fxEvery
  local a, b, list, at
  if PF.shown then
    a, b, list, at = FPF.slot("sword_edge"), FPF.slot("sword_tip"), K.fx.fp, K.blade.fp
  else
    a, b, list, at = slotWorld("blade_sword"), slotWorld(FPC.guns.sword.slot), K.fx.tp, K.blade.tp
  end
  if not a or not b then
    once("chargefx" .. (PF.shown and "fp" or "tp"), "CHARGE: the blade's points are not there (" .. (PF.shown and "sword_edge / sword_tip in view" or "blade_sword / muzzle_sword") .. " - an archive older than t125?) - no sparks")
    return
  end
  for i, f in ipairs(at) do
    local inst = FPF.fxAt((i == #at) and list[1] or list[2], a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f, a.z + (b.z - a.z) * f, nil, nil)
    if inst then
      PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fxLife }
      C.fx = (C.fx or 0) + 1
    end
  end
end

function FPF.chargeFlats(c)
  local K, Kc = FPC.sword, FPC.sword.charge
  local base = FPF.coreOn() and K.records.core or K.records.slash
  local row = nil
  for _, R in ipairs(FPC.tune.damage) do if R[1] == base then row = R end end
  if not row then return 1.0 end
  local mul = 1.0 + (Kc.damage - 1.0) * c
  local k, m = P.damageScale, FPF.perkValue("sworddamage")
  for i, kind in ipairs(FPC.tune.kinds) do
    local v = row[2][i] * k * m * mul * ((kind == "boss") and P.bossMul or 1.0)
    pcall(function() TweakDB:SetFlat(Kc.record .. "." .. kind .. "NPCMaxHPDamage", v) end)
  end
  pcall(function() TweakDB:SetFlat(Kc.record .. ".explosionDamageVSVehicles", row[3] * k * m * mul) end)
  pcall(function() TweakDB:Update(Kc.record) end)
  PS.chargeOf, PS.chargeMul = base, mul
  return mul
end

FPF.coreBossShare124 = FPF.coreBossShare
function FPF.coreBossShare(record)
  if record ~= nil and record == FPC.sword.charge.record then
    local share = FPF.coreBossShare124(PS.chargeOf or FPC.sword.records.slash)
    return share and share * (PS.chargeMul or 1.0) or nil
  end
  return FPF.coreBossShare124(record)
end

FPF.slashHit124 = FPF.slashHit
function FPF.slashHit(ent, M)
  local c = M and M.charged
  if not c then return FPF.slashHit124(ent, M) end
  local K, Kc = FPC.sword, FPC.sword.charge
  local reach0, angle0, targets0 = FPF.swordReach, K.angle, FPF.punchTargets
  local slash0, core0 = K.records.slash, K.records.core
  local own = FPF.gunRecord(Kc.record) == Kc.record
  local mul = own and FPF.chargeFlats(c) or 1.0
  local met = nil
  local more = Kc.reach * c
  FPF.swordReach = function() return reach0() + more end
  K.angle = angle0 + Kc.angle * c
  if own then K.records.slash, K.records.core = Kc.record, Kc.record end
  FPF.punchTargets = function(range, angle)
    local list = targets0(range, angle)
    met = list
    return list
  end
  local ok, err = pcall(FPF.slashHit124, ent, M)
  FPF.swordReach, K.angle, FPF.punchTargets = reach0, angle0, targets0
  K.records.slash, K.records.core = slash0, core0
  if not ok then error(err, 0) end
  local shocked = 0
  for _, T in ipairs(met or {}) do
    if T.kind ~= "vehicle" and M.hit[T.key] then
      local okS = pcall(function() if not OP77.statusObserved(T.ent, Kc.shock) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](T.ent, TweakDBID.new(Kc.shock)) end end)
      if okS then shocked = shocked + 1 end
    end
  end
  PS.chargedHits = (PS.chargedHits or 0) + 1
  if PS.chargedHits <= Kc.lines then
    log(string.format("CHARGED SLASH %d (%.0f %%): %s x %.2f, reach %.1f m, %.0f deg; it met %d people, %d titans or mechs and %d vehicles - %d electrocuted (%s)",
      PS.chargedHits, c * 100.0, own and Kc.record or (K.records.slash .. " (" .. Kc.record .. " is not there: TweakXL did not load t125's bt7274_weapon.yaml)"),
      mul, reach0() + more, angle0 + Kc.angle * c, M.people, M.titans, M.vehicles, shocked, Kc.shock))
  end
end

FPC.exec.immune = true

FPF.health124 = FPF.health
function FPF.health(dt, alone)
  local H = PS.hp
  if H and PS.exec and FPC.exec.immune then
    local n = math.max(H.pend.a, H.pend.b)
    if n > 0 then
      PS.execKept = (PS.execKept or 0) + 1
      if PS.execKept <= 6 then log(string.format("EXECUTION: a hit of %.0f points while BT executes - nothing is taken", n)) end
    end
    H.pend.a, H.pend.b, H.bigV = 0.0, 0.0, nil
    if H.doomed then dt = 0.0 end
  end
  return FPF.health124(dt, alone)
end

FPF.bossHit124 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  if PS.exec and FPC.exec.immune and PS.hp and type(record) == "string" then
    local open = FPF.bossOpen()
    if open then
      local B = bossBook()
      B.n, B.phased = B.n + 1, B.phased + 1
      bossLine(B, string.format("%s from %s; it goes through BT while BT executes", record, bossWho(who)))
      return true, "phased", 0.0
    end
  end
  return FPF.bossHit124(record, x, y, z, dx, dy, who, kind)
end

