FPF.slashStart125 = FPF.slashStart
function FPF.slashStart(by, wave)
  local M = FPF.slashStart125(by, wave)
  local K = FPC.sword.charge
  if M and not M.wave and K.on and S.driving and S.pilot then
    if by == "the fire key" and PS.swordFire == true and not M.charge then
      local list = PF.shown and K.holdFp or K.holdTp
      M.charge = { hold = list[M.n] or list[1], fp = PF.shown == true }
    end
    if M.charge then M.charge.key = (by == "the fire key") and "fire" or "melee" end
  end
  return M
