function FPF.chargeHeld(C)
  if not (S.driving and S.pilot) then return false end
  if C.key == "fire" then return PS.swordFire == true end
  return PS.meleeHeld == true
end

function FPF.chargeFxOn(on)
  local K = FPC.sword.charge
  local cur = PS.chargeFx
  local want = on and (PF.shown and "fp" or "tp") or nil
  if cur and cur.view == want then return end
  if cur then
    for _, name in ipairs(cur.names) do FPF.entFx(cur.ent, name, false) end
    PS.chargeFx = nil
  end
  if not want then return end
  local ent = (want == "fp") and PF.ent or PS.ent
  local names = (want == "fp") and K.fxFp or K.fxTp
  local n = 0
  for _, name in ipairs(names) do if FPF.entFx(ent, name, true) then n = n + 1 end end
  PS.chargeFx = { view = want, ent = ent, names = names }
  PS.chargeFxN = (PS.chargeFxN or 0) + 1
  if PS.chargeFxN <= 3 then
    log(string.format("CHARGE: the blade's sparks on (%s: %s) - %d of %d started", want == "fp" and "in view" or "outside", table.concat(names, ", "), n, #names))
  end
end

function FPF.chargeFrame()
  local M = PS.slash
  local C = M and M.charge
  local K = FPC.sword.charge
  local dt = clamp(S.clock - (PS.chargeAt or S.clock), 0.0, 0.1)
  PS.chargeAt = S.clock
  if not C or C.over then
    PS.chargeW = math.max(0.0, (PS.chargeW or 0.0) - dt / K.relFade)
    if PS.chargeFx then FPF.chargeFxOn(false) end
    return
  end
  local held = FPF.chargeHeld(C)
  if not C.from then
    if not held then
      C.over = true
      return
    end
    if M.t < C.hold then return end
    C.from, C.holding, M.t, C.moving = S.clock, true, C.hold, 0.0
    PS.charges = (PS.charges or 0) + 1
    C.n = PS.charges
    if C.n <= K.lines then
      log(string.format("CHARGE %d: the %s key held - swing %d of three stops where its wind-up ends (%.2f s of its clip, %s), full in %.1f s",
        C.n, C.key == "fire" and "fire" or "melee", M.n or 0, C.hold, C.fp and "in view" or "outside", FPF.chargeFull(K)))
    end
  end
  PS.chargeClip = (M.n == 2) and 1.0 or 0.0
  if C.holding then
    C.level = clamp((S.clock - C.from) / FPF.chargeFull(K), 0.0, 1.0)
    local moving = clamp((PS.move or 0.0) * 3.0, 0.0, 1.0)
    C.moving = C.moving + clamp(moving - C.moving, -dt / K.moveFade, dt / K.moveFade)
    if held and S.clock - C.from < K.most then
      FPF.chargeShake(M, C)
      local w = PS.punchW or 1.0
      PS.chargeW = w
      PS.punchW = w * (1.0 - C.moving)
      FPF.chargeFxOn(true)
      return
    end
    C.holding, C.shake = false, nil
    C.held = S.clock - C.from
    C.relAt, C.relW, C.relC = S.clock, PS.punchW or 1.0, PS.chargeW or 0.0
    if C.level >= K.least then
      M.charged = C.level
      FPF.swordSound(FPC.sword.sounds.waveFire, FPF.viewVolume())
    end
    if C.n <= K.lines then
      log(string.format("CHARGE %d let go after %.2f s%s: %s", C.n, C.held, held and " (held its longest)" or "",
        M.charged and string.format("charged %.0f %% - x %.2f, %.1f m further, %.0f deg wider, the game's electrocution on whoever it meets",
          M.charged * 100.0, 1.0 + (K.damage - 1.0) * M.charged, K.reach * M.charged, K.angle * M.charged) or "too little - a plain slash"))
    end
  end
  if C.relAt then
    local k = ease(clamp((S.clock - C.relAt) / K.relFade, 0.0, 1.0))
    PS.punchW = C.relW + ((PS.punchW or 1.0) - C.relW) * k
    PS.chargeW = C.relC * (1.0 - k)
    if k >= 1.0 then C.relAt = nil end
  else
    PS.chargeW = 0.0
  end
  if M.charged and not M.done then FPF.chargeFxOn(true) else FPF.chargeFxOn(false) end
  if M.done and not C.relAt then C.over = true end
end

function FPF.chargeFx(C) end

function FPF.chargeWeights()
  return clamp(PS.chargeW or 0.0, 0.0, 1.0), PS.chargeClip or 0.0
end

function FPF.swordPoseBusy()
  if PS.weapon ~= "sword" then return false end
  local B = PS.swordBlock
  local w = PS.swordBlockW or 0.0
  return (B ~= nil and B.on) or (w > 0.0) or PS.slash ~= nil or (PS.chargeW or 0.0) > 0.0
end

FPF.placeBt125 = FPF.placeBt
function FPF.placeBt()
  local W = PS.awake
  if P.awake and W and FPF.swordPoseBusy() then
    W.at = math.min(W.at, S.clock)
    if not PS.awakeBusySaid then
      PS.awakeBusySaid = true
      log("BT kept awake every frame while the sword blocks, slashes or charges (its fiftieth of a degree turns every frame, not four times a second)")
    end
  end
  return FPF.placeBt125()
end

function FPF.blockLook(dt)
  local K = FPC.sword.blockLook
  local B = PS.swordBlock
  local w = PS.swordBlockW or 0.0
  if PS.weapon ~= "sword" or PF.shown or not B or not B.on or w < 0.99 then
    PS.blockLookT, PS.blockLookDone = 0.0, nil
    return
  end
  PS.blockLookT = (PS.blockLookT or 0.0) + dt
  if PS.blockLookDone or PS.blockLookT < K.after then return end
  PS.blockLookDone = true
  local standing = (PS.move or 0.0) < 0.05
  PS.blockLooks = PS.blockLooks or { standing = 0, moving = 0 }
  local L = PS.blockLooks
  local kind = standing and "standing" or "moving"
  if L[kind] >= (standing and K.lines or K.moving) then return end
  local a, b, hl, hr = slotWorld("blade_sword"), slotWorld(FPC.guns.sword.slot), slotWorld("hand_l"), slotWorld("hand_r")
  if not (a and b and hl and hr) then return end
  L[kind] = L[kind] + 1
  local ux, uy, uz = b.x - a.x, b.y - a.y, b.z - a.z
  local n = math.sqrt(ux * ux + uy * uy + uz * uz)
  if n < 1e-6 then return end
  ux, uy, uz = ux / n, uy / n, uz / n
  local function off(h)
    local vx, vy, vz = h.x - a.x, h.y - a.y, h.z - a.z
    local t = vx * ux + vy * uy + vz * uz
    local px, py, pz = vx - t * ux, vy - t * uy, vz - t * uz
    return math.sqrt(px * px + py * py + pz * pz)
  end
  local l, r = off(hl), off(hr)
  local good = math.abs(l - K.left) <= K.tol and math.abs(r - K.right) <= K.tol
  log(string.format("BLOCK pose read back (%s, %d): the wrists %.2f (left) / %.2f (right) m off the blade's line - %s (the block pose: %.2f / %.2f; the hold: 0.35 / 0.54; caught half way into the block: the left 0.1 - 0.2)",
    kind, L[kind], l, r, good and "the block's grip" or "NOT the block's grip (a skeleton the game did not bring up to date?)", K.left, K.right))
end

FPF.swordFrame125 = FPF.swordFrame
function FPF.swordFrame(dt, ent)
  FPF.swordFrame125(dt, ent)
  if S.driving and S.pilot then
    local ok, err = pcall(FPF.blockLook, dt)
    if not ok then once("blocklook" .. tostring(err), "the block's pose could NOT be read back (" .. tostring(err) .. ")") end
  end
end

P.swordChargeFire = true

FPF.tuneFrame126 = FPF.tuneFrame
function FPF.tuneFrame()
  FPF.tuneFrame126()
  if S.clock < (S.swordChargeAt or 0.0) then return end
  S.swordChargeAt = S.clock + FPC.tune.every
  local sys = nil
  pcall(function() sys = FPF.keysSystem() end)
  if not sys then return end
  local v = nil
  pcall(function() v = sys.swordCharge end)
  if v == nil then return end
  local n = nil
  pcall(function() n = EnumInt(v) end)
  local fire
  if type(n) == "number" then fire = n ~= 1 else fire = not tostring(v):find("MeleeOnly", 1, true) end
  if fire ~= P.swordChargeFire or not S.swordChargeSaid then
    S.swordChargeSaid = true
    P.swordChargeFire = fire
    log(string.format("Mod Settings: the BROADSWORD's slash charges %s", fire and "with the fire key or the melee key held (a tap slashes)"
      or "with the melee key held only - the fire key held slashes on and on"))
  end
end

FPF.slashStart126 = FPF.slashStart
function FPF.slashStart(by, wave)
  local M = FPF.slashStart126(by, wave)
  if M and M.charge and M.charge.key == "fire" and P.swordChargeFire == false then M.charge = nil end
  return M
end

