function FPF.stepYaw(dt)
  local Sp = PS.spin
  if Sp and PS.mode == "pilot" then return FPF.spinYaw(Sp) end
  return PS.sentry and FPF.sentryYaw(dt) or S.yaw
end

function FPF.spinRefill()
