end

function FPF.spinCharge(dt)
  local most = FPC.sword.spin.charges
  local c = PS.spinCharge
  if c == nil then c = most end
  if c < most then c = math.min(most, c + dt * most / FPF.spinRefill()) end
  PS.spinCharge = c
  return c
end

function FPF.spinCan()
  if FPF.perk("sentry") < 1 then return false, "SENTRY MODE is disabled by the server loadout - the BROADSWORD's spin comes with it" end
  local c = PS.spinCharge or FPC.sword.spin.charges
  if c < 1.0 then
    return false, string.format("no charge left - the next in %.1f s", (1.0 - c) * FPF.spinRefill() / FPC.sword.spin.charges)
  end
  if PS.jump then return false, "BT is in a jump" end
  if PS.punch or PS.lunge or PS.pound then return false, "its fist is out" end
  if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then return false, "it is in a dash" end
  if PS.skate then return false, "it skates" end
  if PS.flight then return false, "FLIGHT STRIKE is on" end
  if PS.exec then return false, "an execution" end
  if PS.vortex and PS.vortex.on then return false, "the vortex shield is up" end
  if PS.slash then return false, "busy" end
  return true
end

function FPF.spinStart()
  local K = FPC.sword.spin
  local rate = math.max(FPF.swordRate(), 0.1)
  PS.spinCharge = (PS.spinCharge or K.charges) - 1.0
  PS.spins = (PS.spins or 0) + 1
  local aim = clamp(wrap180(S.yaw - PS.yaw), -(P.twist - 1.0), P.twist - 1.0)
  local Sp = { t = 0.0, n = PS.spins, from = PS.yaw, yaw0 = wrap180(PS.yaw + aim), aim = aim, rate = rate, windup = K.windup / rate,
    spin = K.spin / rate, recover = K.recover / rate, hit = {}, people = 0, titans = 0, vehicles = 0, sent = 0, attacks = 0, fx = 0,
    rings = 0, swept = 0.0, sounds = 0, at = S.clock }
  Sp.total = Sp.windup + Sp.spin + Sp.recover
  PS.spin, PS.spinAsk = Sp, nil
  PS.vx, PS.vy, PS.speed, PS.turn, PS.sprintOn = 0.0, 0.0, 0.0, nil, false
  local B = PS.swordBlock
  if B and B.on then B.on, B.idle = false, 0.0 end
  FPF.spinSwing(Sp)
  if Sp.n <= K.lines then
    log(string.format("SPIN SLASH %d: SENTRY MODE's key with the BROADSWORD - BT faces the view (%.0f deg) in %.2f s, turns round %.0f deg in %.2f s and swings through in %.2f s (x %.2f%s); reach %.1f m all round; charges left %.2f of %d (all back in %.0f s)",
      Sp.n, aim, Sp.windup, K.turn, Sp.spin, Sp.recover, rate, FPF.coreOn() and ", Sword Core" or "", (FPF.spinReach or FPF.swordReach)(), PS.spinCharge,
      K.charges, FPF.spinRefill()))
  end
end

function FPF.spinSwing(Sp)
  if PF.shown then FPF.swordSound(FPC.sword.sounds.fp, FPF.viewVolume()) else FPF.swordSound(FPC.sword.sounds.tp) end
  Sp.sounds = Sp.sounds + 1
end

function FPF.spinEnd(why)
  local Sp = PS.spin
  if not Sp then return end
  PS.spin = nil
  local K = FPC.sword.spin
  if Sp.n <= K.lines then
    log(string.format("SPIN SLASH %d over (%s) after %.2f s: it met %d people, %d titans or mechs and %d vehicles (hit events taken for %d, area attacks %d); sparks round it %d; charges left %.2f",
      Sp.n, tostring(why), S.clock - Sp.at, Sp.people, Sp.titans, Sp.vehicles, Sp.sent, Sp.attacks, Sp.sparks or 0, PS.spinCharge or 0.0))
  end
end

function FPF.spinYaw(Sp)
  local K = FPC.sword.spin
  local t = Sp.t
  if t < Sp.windup then
    local u = ease(t / Sp.windup)
    PS.yaw = wrap180(Sp.from + Sp.aim * u)
    Sp.swept = 0.0
    return wrap180(PS.yaw + Sp.aim * (1.0 - u))
  end
  if t < Sp.windup + Sp.spin then
    Sp.swept = K.turn * ease((t - Sp.windup) / Sp.spin)
  else
    Sp.swept = K.turn
  end
  PS.yaw = wrap180(Sp.yaw0 + K.dir * Sp.swept)
  return PS.yaw
end

function FPF.spinPose(Sp)
  local K, C = FPC.sword.spin, PUNCH_CLIP.sword
  local t, ct = Sp.t, 0.0
  if t < Sp.windup then
    ct = C.hit * (t / Sp.windup)
  elseif t < Sp.windup + Sp.spin then
    ct = C.hit + K.hold * ((t - Sp.windup) / Sp.spin)
  else
    ct = C.hit + K.hold + (C.time - C.hit - K.hold) * math.min(1.0, (t - Sp.windup - Sp.spin) / Sp.recover)
  end
  PS.punchT = clamp(ct, 0.0, C.time)
  PS.punchW = clamp(math.min(t / K.fadeIn, (Sp.total - t) / K.fadeOut), 0.0, 1.0)
  PS.punchClip = FPC.sword.tpClips[1]
end

function FPF.spinFpTime(Sp)
  local hitT, len = FP.meleeHit or 0.3, FP.melee or 1.0
  local t = Sp.t
  if t < Sp.windup then return hitT * t / Sp.windup end
  if t < Sp.windup + Sp.spin then return hitT + (len - hitT) * 0.5 * ((t - Sp.windup) / Sp.spin) end
  return math.min(len, hitT + (len - hitT) * (0.5 + 0.5 * (t - Sp.windup - Sp.spin) / Sp.recover))
end

function FPF.spinTargets(reach)
  local K = FPC.sword.spin
  local out = {}
  local function take(ent, kind, lift)
    if not IsDefined(ent) then return end
    local ok, p = pcall(function() return ent:GetWorldPosition() end)
    if not ok or not p then return end
    local r, h, name = 0.0, nil, nil
    if kind == "person" then
      pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
      if type(name) == "string" then
        local okS, shape = pcall(FPF.recordShape, name)
        if okS and shape then r, h = shape[1], shape[2] end
      end
    end
    local dx, dy = p.x - PS.x, p.y - PS.y
    local dist = math.sqrt(dx * dx + dy * dy)
    local near = math.max(0.0, dist - r)
    if near > reach or math.abs(p.z - PS.z) >= K.high then return end
    local key = kind .. tostring(#out)
    pcall(function() key = tostring(ent:GetEntityID()) end)
    local n = math.max(dist, 0.01)
    local ux, uy = dx / n, dy / n
    local x, y, z = p.x, p.y, p.z + lift
    if r > 0.0 then x, y, z = p.x - ux * r, p.y - uy * r, p.z + math.min((h or 2.0) * 0.5, FPC.punchBig.up) end
    out[#out + 1] = { ent = ent, kind = kind, dist = near, x = x, y = y, z = z, key = key, dx = ux, dy = uy, r = r,
      close = dist < K.near + r }
  end
  for _, who in ipairs(PS.npcs) do take(who, "person", 1.0) end
  for _, veh in ipairs(FPF.vehicles()) do take(veh, "vehicle", 0.6) end
  return out
end

function FPF.spinHits(Sp)
  if Sp.t < Sp.windup or Sp.hitsDone then return end
  local K, Ks = FPC.sword, FPC.sword.spin
  if S.clock - PS.npcsAt > 0.08 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  local rec = FPF.gunRecord(FPF.coreOn() and K.records.core or K.records.slash)
  local met = 0
  local titans, vehicles = 0, 0
  for _, T in ipairs(FPF.spinTargets(FPF.swordReach())) do
    if not Sp.hit[T.key] then
      local bearing = math.deg(math.atan2(-T.dx, T.dy))
      local rel = (Ks.dir * wrap180(bearing - Sp.yaw0)) % 360.0
      if T.close or rel <= Sp.swept + 0.01 or Sp.swept >= Ks.turn - 0.01 then
        Sp.hit[T.key] = true
        if T.kind == "vehicle" then
          Sp.vehicles, vehicles = Sp.vehicles + 1, vehicles + 1
        elseif (T.r or 0.0) > 0.0 then
          Sp.titans, titans = Sp.titans + 1, titans + 1
        else
          Sp.people = Sp.people + 1
        end
        if (PS.punchChecked or 0) < 12 then
          PS.punchChecked = (PS.punchChecked or 0) + 1
          PS.checks[#PS.checks + 1] = { ent = T.ent, before = healthOf(T.ent), at = S.clock + 0.4, dist = T.dist, kind = T.kind,
            by = "the spin slash", what = (T.kind == "person") and personText(T.ent) or FPF.vehicleText(T.ent) }
        end
        if FPF.hit(T.ent, rec, T.x, T.y, T.z, T.dx, T.dy, 0.0) then Sp.sent = Sp.sent + 1 end
        if FPF.attack(rec, T.x, T.y, T.z) then Sp.attacks = Sp.attacks + 1 end
        if T.kind == "vehicle" then FPF.wreck(T.ent, FPC.wreck.punch * K.wreck) end
        if P.fxOn and Sp.fx < 4 then
          Sp.fx = Sp.fx + 1
          FPF.fxAt(FPF.fxPath("punch"), T.x, T.y, T.z, S.yaw, 0.0)
        end
        met = met + 1
      end
    end
  end
  if met > 0 then
    FPF.stim("Explosion", FPC.stims.punch, 0.2)
    if S.clock - (Sp.hitSoundAt or -10.0) > 0.1 then
      Sp.hitSoundAt = S.clock
      FPF.swordSound((titans > 0 and K.sounds.armor) or (vehicles > 0 and K.sounds.metal) or K.sounds.flesh)
    end
  end
  if Sp.swept >= Ks.turn - 0.01 then Sp.hitsDone = true end
end

function FPF.spinRing(Sp)
  local K = FPC.sword.spin
  if Sp.t < Sp.windup then return end
  while Sp.rings * K.ring <= Sp.swept + 0.01 and Sp.rings * K.ring < K.turn - 0.01 do
    if P.fxOn then
      local a = math.rad(Sp.yaw0 + K.dir * Sp.rings * K.ring)
      local inst = FPF.fxAt(K.fx, PS.x - math.sin(a) * K.radius, PS.y + math.cos(a) * K.radius, PS.z + K.height, nil, nil)
      if inst then
        PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fxLife }
        Sp.sparks = (Sp.sparks or 0) + 1
      end
    end
    Sp.rings = Sp.rings + 1
  end
  if Sp.sounds < 2 and Sp.swept >= K.turn * 0.5 then FPF.spinSwing(Sp) end
end

FPF.sentryFrame127 = FPF.sentryFrame
function FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
  if PS.weapon ~= "sword" then
    if PS.spin then FPF.spinEnd("the weapon changed") end
    return FPF.sentryFrame127(dt, f, s, sprint, dash, jump, held)
  end
  local K = FPC.sword.spin
  local n = PS.keyN.sentry or 0
  local pressed = n ~= (PS.sentrySeen or 0)
  PS.sentrySeen = n
  FPF.spinCharge(dt)
  if pressed and not PS.spin then
    if held then
      PS.spinRefused = (PS.spinRefused or 0) + 1
      if PS.spinRefused <= K.lines then log("SPIN SLASH: not now - the keys are taken") end
    else
      local ok, why = FPF.spinCan()
      if ok then
        FPF.spinStart()
      elseif why == "busy" then
        PS.spinAsk = S.clock
      else
        PS.spinRefused = (PS.spinRefused or 0) + 1
        if PS.spinRefused <= K.lines then log("SPIN SLASH: not now - " .. tostring(why)) end
      end
    end
  end
  if not PS.spin and PS.spinAsk then
    if S.clock - PS.spinAsk > 1.5 then
      PS.spinAsk = nil
    elseif not held and FPF.spinCan() then
      FPF.spinStart()
    end
  end
  f, s, sprint, dash, jump = FPF.sentryFrame127(dt, f, s, sprint, dash, jump, held)
  local Sp = PS.spin
  if not Sp then return f, s, sprint, dash, jump end
  if held then
    FPF.spinEnd("the keys are taken")
    return f, s, sprint, dash, jump
  end
  Sp.t = Sp.t + dt
  if Sp.t >= Sp.total then
    FPF.spinEnd("swung through")
    return f, s, sprint, dash, jump
  end
  return 0, 0, false, false, false
end

FPF.swordFrame127 = FPF.swordFrame
function FPF.swordFrame(dt, ent)
  local Sp = PS.spin
  if not Sp or PS.weapon ~= "sword" then return FPF.swordFrame127(dt, ent) end
  local ask, fire = PS.slashAsk, PS.swordFire
  PS.slashAsk, PS.swordFire = nil, false
  local ok, err = pcall(FPF.swordFrame127, dt, ent)
  PS.slashAsk = ask or PS.slashAsk
  PS.swordFire = fire
  if not ok then error(err, 0) end
  FPF.spinPose(Sp)
  FPF.spinHits(Sp)
  FPF.spinRing(Sp)
end

FPF.swordBlockFrame127 = FPF.swordBlockFrame
function FPF.swordBlockFrame(dt)
  if not PS.spin then return FPF.swordBlockFrame127(dt) end
  local zoom = PS.zoom
  PS.zoom = false
  local ok, B = pcall(FPF.swordBlockFrame127, dt)
  PS.zoom = zoom
  if not ok then error(B, 0) end
  return B
end

FPF.swordPoseBusy127 = FPF.swordPoseBusy
function FPF.swordPoseBusy()
  if PS.spin and PS.weapon == "sword" then return true end
  return FPF.swordPoseBusy127()
end

FPF.drive127 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive127(dt, steps, sprinting)
  local Sp = PS.spin
  if not Sp or PS.weapon ~= "sword" or not PF.shown or not PF.ent or not IsDefined(PF.ent) then return end
  local t = FPF.spinFpTime(Sp)
  FPF.var("fp_melee_clip", FPC.sword.fpClips[1])
  FPF.var("fp_melee", 1.0)
  FPF.var("fp_time_melee", t)
  local V = FP.view and FP.view[FPC.sword.views[1]]
  if V and #V >= 2 then
    local p, y, r = FPF.sway(V, t)
    PF.sway[1], PF.sway[2], PF.sway[3] = p, y, r
  end
end

FPF.slotStates127 = FPF.slotStates
function FPF.slotStates(M, V, Q)
  local out = FPF.slotStates127(M, V, Q)
  if PS.weapon == "sword" and FPF.perk("sentry") > 0 then
    local most = FPC.sword.spin.charges
    local c = PS.spinCharge or most
    out.sentry = { fill = (c >= most) and 1.0 or (c - math.floor(c)), count = math.floor(c + 1e-6),
      state = PS.spin and "active" or ((c >= 1.0) and "ready" or "empty") }
  end
  return out
end

FPF.swordNote127 = FPF.swordNote
function FPF.swordNote()
  local out = FPF.swordNote127()
  if FPF.perk("sentry") > 0 then out = out .. string.format("   SPIN %d", math.floor((PS.spinCharge or FPC.sword.spin.charges) + 1e-6)) end
  return out
end

FPF.hpBegin127 = FPF.hpBegin
function FPF.hpBegin()
