function FPF.vEffects(player)
  local out = {}
  pcall(function()
    for _, e in ipairs(StatusEffectHelper.GetAppliedEffects(player) or {}) do
      local name = "?"
      pcall(function() name = TDBID.ToStringDEBUG(e:GetRecord():GetID()) end)
      out[#out + 1] = tostring(name)
    end
  end)
  return out
end

function FPF.vWatchHit(evt, tag)
  local W = PS.vWatch
  if not W or not evt or not S.driving then return end
  local onV = false
  pcall(function() onV = evt.target ~= nil and evt.target:IsPlayer() == true end)
  if not onV then return end
  local value, who, rec = 0.0, "?", "?"
  pcall(function() value = evt.attackComputed:GetTotalAttackValue(gamedataStatPoolType.Health) or 0.0 end)
  pcall(function() who = TDBID.ToStringDEBUG(evt.attackData:GetInstigator():GetRecordID()) end)
  pcall(function() rec = TDBID.ToStringDEBUG(evt.attackData:GetAttackDefinition():GetRecord():GetID()) end)
  W.hits[#W.hits + 1] = { t = S.clock, value = value, who = tostring(who), rec = tostring(rec), tag = tag }
  while #W.hits > FPC.vWatch.hits do table.remove(W.hits, 1) end
end

FPF.hitSeen127 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  pcall(FPF.vWatchHit, evt, tag)
  return FPF.hitSeen127(evt, tag)
end

function FPF.vWatchFrame()
  local K = FPC.vWatch
  if not S.driving or PS.mode ~= "pilot" then
    PS.vWatch = nil
    return
  end
  local W = PS.vWatch
  if not W then
    W = { ring = {}, hits = {}, refills = 0, drops = 0, dead = false, at = 0.0, since = S.clock, seen = {} }
    PS.vWatch = W
  end
  if W.dead or S.clock < W.at then return end
  W.at = S.clock + K.every
  local player = Game.GetPlayer()
  if not player then return end
  local id = player:GetEntityID()
  local hp, god, dead = nil, nil, false
  pcall(function() hp = Game.GetStatPoolsSystem():GetStatPoolValue(id, gamedataStatPoolType.Health, true) end)
  pcall(function() god = Game.GetGodModeSystem():HasGodMode(id, gameGodModeType.Invulnerable) == true end)
  pcall(function() dead = player:IsDead() == true end)
  local v = player:GetWorldPosition()
  local over = dead or (type(hp) == "number" and hp <= 0.0)
  if over or S.clock >= (W.fxAt or 0.0) then
    W.fxAt = S.clock + K.fxEvery
    W.fxNow = FPF.vEffects(player)
    for _, name in ipairs(W.fxNow) do
      if not W.seen[name] then W.seen[name] = S.clock end
    end
  end
  local row = { t = S.clock, hp = hp, god = god, dz = v.z - PS.z, dxy = math.sqrt((v.x - PS.x) ^ 2 + (v.y - PS.y) ^ 2),
    state = FPF.fallState(), fx = W.fxNow or {}, bt = PS.hp and string.format("%.0f + %.0f", PS.hp.health or 0, PS.hp.shield or 0) or "?" }
  W.ring[#W.ring + 1] = row
  while #W.ring > 0 and S.clock - W.ring[1].t > K.keep do table.remove(W.ring, 1) end
  if type(hp) == "number" then
    if W.base == nil or hp > W.base then W.base = hp end
    if W.last and hp < W.last - 0.5 then
      W.drops = W.drops + 1
      if W.drops <= K.lines then
        log(string.format("V aboard: V's own health fell from %.0f %% to %.0f %% (god mode %s)", W.last, hp, tostring(god)))
      end
    end
    W.last = hp
  end
  if over then
    W.dead = true
    FPF.vWatchDump(W, dead and "the game says V is dead" or "V's own health is gone")
    return
  end
  if type(hp) == "number" and hp <= K.floor and W.base and hp < W.base - 0.5 then
    local to = W.base
    local ok = pcall(function() Game.GetStatPoolsSystem():RequestSettingStatPoolValue(id, gamedataStatPoolType.Health, to, player, true) end)
    W.refills = W.refills + 1
    if ok then W.last = to end
    if W.refills <= K.lines then
      log(string.format("V aboard: V's own health at %.0f %% (god mode %s) - %s %.0f %%, the most it had aboard (%d this drive)", hp, tostring(god),
        ok and "put back to" or "could NOT be put back to", to, W.refills))
      FPF.vWatchDump(W, string.format("V's own health at %.0f %%", hp))
    end
  end
end

function FPF.vWatchDump(W, why)
  local K = FPC.vWatch
  local now = W.ring[#W.ring]
  if not now then return end
  local new = {}
  for name, at in pairs(W.seen) do
    if at >= S.clock - K.keep and at > W.since + 0.05 then new[#new + 1] = name end
  end
  table.sort(new)
  log(string.format("V ABOARD - %s, %.1f s into the drive: V's health %s %%, god mode %s, V %.1f m above BT's place and %.1f m from it, the game's own state for V: %s; BT %s",
    why, S.clock - W.since, tostring(now.hp and math.floor(now.hp + 0.5)), tostring(now.god), now.dz, now.dxy, tostring(now.state), now.bt))
  log("V ABOARD - status effects on V now: " .. ((#now.fx > 0) and table.concat(now.fx, ", ") or "none") ..
    "; new in the last " .. string.format("%.0f", K.keep) .. " s: " .. ((#new > 0) and table.concat(new, ", ") or "none"))
  local hits = {}
  for _, h in ipairs(W.hits) do
    hits[#hits + 1] = string.format("%.2f s ago %.0f points from %s (%s, %s)", S.clock - h.t, h.value, h.who, h.rec, h.tag)
  end
  log("V ABOARD - the last hits on V: " .. ((#hits > 0) and table.concat(hits, "; ") or "none this drive"))
  local step = math.max(1, math.floor(#W.ring / K.rows))
  for i = 1, #W.ring, step do
    local r = W.ring[i]
    log(string.format("V ABOARD - %.1f s before: health %s %%, god mode %s, %.1f m above BT's place, %.1f m from it, %s, %d status effects",
      S.clock - r.t, tostring(r.hp and math.floor(r.hp + 0.5)), tostring(r.god), r.dz, r.dxy, tostring(r.state), #r.fx))
  end
end

FPF.vGuardFrame127 = FPF.vGuardFrame
function FPF.vGuardFrame()
  guard("V aboard: the watch", FPF.vWatchFrame)
  return FPF.vGuardFrame127()
end

FPC.sword.spin.reach, FPC.sword.spin.edgeRing, FPC.sword.spin.edgeIn, FPC.sword.spin.edgeHeight = 15.0, 15.0, 1.5, 1.0
FPC.sword.spin.edgeFx = [[base\fx\devices\_damage\emp\big\d_emp_status_big.effect]]
FPC.sword.siphon = { lines = 8 }
FPC.sword.core.rate, FPC.sword.core.damage = 1.0, 1.3

function FPF.t129Setup()
  local K = FPC.perk
  K.names.swordspeed = "BLADE SIPHON"
  K.values.swordspeed = { 0.0, 10.0, 20.0 }
  local more = FPC.sword.core.damage
  for _, R in ipairs(FPC.tune.damage) do
    if R[1] == FPC.sword.records.core then
      local row = {}
      for i, v in ipairs(R[2]) do row[i] = v * more end
      R[2], R[3] = row, R[3] * more
      for _, B in ipairs(FPC.boss) do
        if B[1] == R[1] then B[2] = row[6] end
      end
    end
  end
  FPC.bossShare = nil
end
