function FPF.bladeSiphon(S_, by, met)
  if FPF.perk("swordspeed") < 1 or S_.siphoned or met <= 0 then return end
  S_.siphoned = true
  local H = PS.hp
  if not H or H.doomed or H.gone then return end
  local was = H.shield
  H.shield = math.min(FPC.health.shield, H.shield + FPF.perkValue("swordspeed"))
  if H.shield <= was then return end
  PS.siphons = (PS.siphons or 0) + 1
  if PS.siphons <= FPC.sword.siphon.lines then
    log(string.format("BLADE SIPHON: %s met %d - BT's shield %.0f -> %.0f of %.0f (+%.0f a swing, however many it meets)",
      by, met, was, H.shield, FPC.health.shield, FPF.perkValue("swordspeed")))
  end
end

