FPF.spinRing128 = FPF.spinRing
function FPF.spinRing(Sp)
  FPF.spinRing128(Sp)
  local K = FPC.sword.spin
  if Sp.t < Sp.windup then return end
  Sp.edges = Sp.edges or 0
  local r = FPF.spinReach() - K.edgeIn
  while Sp.edges * K.edgeRing <= Sp.swept + 0.01 and Sp.edges * K.edgeRing < K.turn - 0.01 do
    if P.fxOn then
      local a = math.rad(Sp.yaw0 + K.dir * Sp.edges * K.edgeRing)
      local inst = FPF.fxAt(K.edgeFx, PS.x - math.sin(a) * r, PS.y + math.cos(a) * r, PS.z + K.edgeHeight, nil, nil)
      if inst then
        PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fxLife }
        Sp.sparks = (Sp.sparks or 0) + 1
      end
    end
    Sp.edges = Sp.edges + 1
  end
end

FPC.swordAI.charge = { gap = 6.0, chance = 0.35, foes = 2, hold = 1.25 }
FPC.swordAI.wave = { from = 10.0, to = 38.0, cone = 15.0, look = 1.0, chance = 0.5, gap = 4.0, by = "BT on its own: ARC WAVE" }
FPC.swordAI.spin = { gap = 3.0, near = 9.0, nearFoes = 2, foes = 3 }
P.aiSwordMore = true

function FPF.aiFoesNear(r)
  local n = 0
  for _, ent in ipairs(PS.npcs) do
    if IsDefined(ent) then
      pcall(function()
        if not ScriptedPuppet.IsActive(ent) or ent:IsHostile() ~= true then return end
        local p = ent:GetWorldPosition()
        if (p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2 <= r * r and math.abs(p.z - PS.z) < FPC.sword.spin.high then n = n + 1 end
      end)
    end
  end
  return n
end

function FPF.aiSwordOpen()
  if S.driving or not P.aiSword or not P.aiSwordMore or PS.weapon ~= "sword" then return nil end
  local B = PS.buddy
  local C, T = B and B.chase, B and B.target
  if not C or not T or C.mode == "back" then return nil end
  return C, T, B
end

function FPF.aiChargeMaybe(M)
  local K, Kc = FPC.swordAI.charge, FPC.sword.charge
  if not Kc.on or M.charge then return end
  local C, T = FPF.aiSwordOpen()
  if not C or S.clock - (PS.aiChargeAt or -100.0) < K.gap then return end
  local why = nil
  local big = false
  pcall(function() big = T.ent ~= nil and FPF.bigTarget(T.ent) == true end)
  if big then
    why = "its foe is a big body"
  else
    local reach = FPF.swordReach() + Kc.reach
    local n = FPF.aiFoesNear(reach)
    if n >= K.foes then
      why = string.format("%d foes within %.0f m", n, reach)
    elseif math.random() < K.chance then
      why = "now and then"
    end
  end
  if not why then return end
  local hold = Kc.holdTp[M.n] or Kc.holdTp[1]
  M.charge = { hold = hold, fp = false, key = "ai", till = S.clock + hold / math.max(M.rate or 1.0, 0.1) + K.hold }
  PS.aiChargeAt = S.clock
  PS.aiCharges = (PS.aiCharges or 0) + 1
  if PS.aiCharges <= FPC.swordAI.lines then
    log(string.format("BT on its own, the broadsword: a charged slash (%s) - held %.2f s at the wind-up's end", why, K.hold))
  end
end

FPF.slashStart129 = FPF.slashStart
