function FPF.aiSwordMoves(B, T)
  if PS.slash or PS.spin or PS.punch or PS.lunge or PS.jump or PS.dashT ~= nil or PS.skate then return end
  local A = B.ai
  local Ks = FPC.swordAI.spin
  if FPF.perk("sentry") >= 1 and (PS.spinCharge or FPC.sword.spin.charges) >= 1.0 and S.clock - (PS.aiSpinAt or -100.0) >= Ks.gap then
    local near, all = FPF.aiFoesNear(Ks.near), FPF.aiFoesNear(FPF.spinReach())
    if near >= Ks.nearFoes or all >= Ks.foes then
      local ok = FPF.aiView(FPF.spinCan)
      if ok then
        FPF.aiView(FPF.spinStart)
        if PS.spin then
          PS.spin.ai = true
          PS.aiSpinAt = S.clock
          PS.aiSpins = (PS.aiSpins or 0) + 1
          if A then A.punchAt = S.clock end
          if PS.aiSpins <= FPC.swordAI.lines then
            log(string.format("BT on its own, the broadsword: the spin - %d foes within %.0f m, %d within %.0f m", near, Ks.near, all, FPF.spinReach()))
          end
          return
        end
      end
    end
  end
  local Kw = FPC.swordAI.wave
  if FPF.perk("sword") < 1 or (PS.waveCharges or FPC.sword.wave.charges) < 1.0 or S.clock - (PS.aiWaveAt or -100.0) < Kw.gap
      or S.clock < (B.waveLookAt or 0.0) then
    return
  end
  B.waveLookAt = S.clock + Kw.look
  local d = T.dist or 0.0
  local off = math.abs(wrap180(math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)) - B.yaw))
  if d < Kw.from or d > Kw.to or off > Kw.cone or math.random() >= Kw.chance then return end
  PS.slashAsk = { by = Kw.by }
  PS.aiWaveAt = S.clock
  PS.aiWaves = (PS.aiWaves or 0) + 1
  if A then A.punchAt = S.clock end
  if PS.aiWaves <= FPC.swordAI.lines then
    log(string.format("BT on its own, the broadsword: ARC WAVE at its foe %.0f m ahead (%.0f deg off its way)", d, off))
  end
end

