function FPF.spinFromCharge(M, C)
  local Kc = FPC.sword.charge
  local level = C.level or 0.0
  PS.slash, PS.slashAsk = nil, nil
  C.over, C.holding = true, false
  FPF.spinStart()
  local Sp = PS.spin
  if not Sp then return end
  Sp.clip, Sp.tp = M.tpClip, M.tp
  Sp.poseFrom = C.fp and 0.0 or clamp(C.hold, 0.0, M.tp.hit)
  Sp.fpClip, Sp.fpHit, Sp.fpLen = M.fpClip, M.from, M.fpTime
  Sp.fpFrom = C.fp and clamp(C.hold, 0.0, M.from) or 0.0
  if level < Kc.least then
    log(string.format("SPIN SLASH %d: out of a charge of %.0f %% - too little for the electric spin: a plain one", Sp.n, level * 100.0))
    return
  end
  Sp.charged, Sp.shocked = level, 0
  local own = FPF.gunRecord(Kc.record) == Kc.record
  Sp.mul = own and FPF.chargeFlats(level) or 1.0
  Sp.own = own
  FPF.swordSound(FPC.sword.sounds.waveFire, FPF.viewVolume())
  PS.electricSpins = (PS.electricSpins or 0) + 1
  if PS.electricSpins <= FPC.sword.spin.lines then
    log(string.format("ELECTRIC SPIN %d: the charge (%.0f %%) goes into the spin - %s x %.2f, reach %.1f m, the game's electrocution on whoever it meets",
      PS.electricSpins, level * 100.0, own and Kc.record or "the slash's record (the charged one is not there)", Sp.mul, FPF.spinReach()))
  end
end

FPF.sentryFrame130 = FPF.sentryFrame
function FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
  if PS.weapon == "sword" and not held and not PS.spin then
    local n = PS.keyN.sentry or 0
    local M = PS.slash
    local C = M and M.charge
    if n ~= (PS.sentrySeen or 0) and C and not C.over and C.holding and not M.wave then
      local slash = PS.slash
      PS.slash = nil
      local ok = FPF.spinCan()
      PS.slash = slash
      if ok then
        PS.sentrySeen = n
        FPF.spinFromCharge(M, C)
      end
    end
  end
  return FPF.sentryFrame130(dt, f, s, sprint, dash, jump, held)
end

FPF.spinPose130 = FPF.spinPose
function FPF.spinPose(Sp)
  if not Sp.tp then return FPF.spinPose130(Sp) end
  local K, C = FPC.sword.spin, Sp.tp
  local t, ct = Sp.t, 0.0
  local from = Sp.poseFrom or 0.0
  if t < Sp.windup then
    ct = from + (C.hit - from) * (t / Sp.windup)
  elseif t < Sp.windup + Sp.spin then
    ct = C.hit + K.hold * ((t - Sp.windup) / Sp.spin)
  else
    ct = C.hit + K.hold + (C.time - C.hit - K.hold) * math.min(1.0, (t - Sp.windup - Sp.spin) / Sp.recover)
  end
  PS.punchT = clamp(ct, 0.0, C.time)
  PS.punchW = clamp((Sp.total - t) / K.fadeOut, 0.0, 1.0)
  PS.punchClip = Sp.clip
end

FPF.spinFpTime130 = FPF.spinFpTime
function FPF.spinFpTime(Sp)
  if not Sp.fpHit then return FPF.spinFpTime130(Sp) end
  local hitT, len, from = Sp.fpHit, Sp.fpLen or Sp.fpHit, Sp.fpFrom or 0.0
  local t = Sp.t
  if t < Sp.windup then return from + (hitT - from) * t / Sp.windup end
  if t < Sp.windup + Sp.spin then return hitT + (len - hitT) * 0.5 * ((t - Sp.windup) / Sp.spin) end
  return math.min(len, hitT + (len - hitT) * (0.5 + 0.5 * (t - Sp.windup - Sp.spin) / Sp.recover))
end

FPF.drive130 = FPF.drive
function FPF.drive(dt, steps, sprinting)
