end

FPF.spinReach130 = FPF.spinReach
function FPF.spinReach()
  local r = FPF.spinReach130()
  local Sp = PS.spin
  if Sp and Sp.charged then r = r + FPC.sword.charge.reach * Sp.charged end
  return r
end

FPF.spinHits130 = FPF.spinHits
function FPF.spinHits(Sp)
  if not Sp.charged then return FPF.spinHits130(Sp) end
  local K, Kc = FPC.sword, FPC.sword.charge
  local slash0, core0, hit0 = K.records.slash, K.records.core, FPF.hit
  local met = {}
  if Sp.own then K.records.slash, K.records.core = Kc.record, Kc.record end
  FPF.hit = function(who, record, ...)
    local r = hit0(who, record, ...)
    met[#met + 1] = who
    return r
  end
  local ok, err = pcall(FPF.spinHits130, Sp)
  K.records.slash, K.records.core, FPF.hit = slash0, core0, hit0
  if not ok then error(err, 0) end
  for _, who in ipairs(met) do
    local vehicle = false
    pcall(function() vehicle = who:IsVehicle() == true end)
    if not vehicle and pcall(function() if not OP77.statusObserved(who, Kc.shock) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](who, TweakDBID.new(Kc.shock)) end end) then
      Sp.shocked = Sp.shocked + 1
    end
  end
end

