  local Sp = PS.spin
  if Sp and Sp.charged and PS.weapon == "sword" then
    PS.chargeAt, PS.chargeW = S.clock, 0.0
    FPF.chargeFxOn(true)
    return
  end
  return FPF.chargeFrame130()
end

