function FPF.shellsOut(n)
  local K = FPC.shells[PS.weapon]
  if not K or n <= 0 then return end
  for _ = 1, n do
    PS.shellRounds = (PS.shellRounds or 0) + 1
    if PS.shellRounds % K.every == 0 then
      local fp = PF.shown == true and PF.ent ~= nil and IsDefined(PF.ent)
      local name = fp and FPC.shells.fp or K.name
      local ok = FPF.entFx(fp and PF.ent or PS.ent, name)
      PS.shells = (PS.shells or 0) + 1
      if PS.shells <= FPC.shells.lines then
        log(string.format("SPENT CASE %d: %s (%s, %s)", PS.shells, name, fp and "in view" or "outside", ok and "started" or "NOT started"))
      end
