function FPF.spinStun(Sp, who)
  local K = FPC.sword.spin.stun
  local level = Sp.charged or 0.0
  if level < K.from then return false, "too little" end
  local _, kind = nil, nil
  pcall(function() _, kind = FPF.coreWorth(who) end)
  local boss = kind == "a boss"
  local chance = 1.0
  if boss then
    local u = clamp((level - K.from) / math.max(1.0 - K.from, 1e-6), 0.0, 1.0)
    chance = K.boss[1] + (K.boss[2] - K.boss[1]) * u
    if math.random() >= chance then return false, string.format("a boss-class one, %.0f %% missed", chance * 100.0) end
  end
  local ok = pcall(function() if not OP77.statusObserved(who, K.effect) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](who, TweakDBID.new(K.effect)) end end)
  return ok, boss and string.format("a boss-class one, %.0f %% hit", chance * 100.0) or "stunned"
end

FPF.spinHits132 = FPF.spinHits
function FPF.spinHits(Sp)
  if not Sp.charged or (Sp.charged or 0.0) < FPC.sword.spin.stun.from then return FPF.spinHits132(Sp) end
  local hit0 = FPF.hit
  local met = {}
  FPF.hit = function(who, record, ...)
    met[#met + 1] = who
    return hit0(who, record, ...)
  end
  local ok, err = pcall(FPF.spinHits132, Sp)
  FPF.hit = hit0
  if not ok then error(err, 0) end
  local K = FPC.sword.spin.stun
  Sp.stunned, Sp.stunMissed = Sp.stunned or 0, Sp.stunMissed or 0
  for _, who in ipairs(met) do
    local vehicle = false
    pcall(function() vehicle = who:IsVehicle() == true end)
    if not vehicle then
      local done, how = FPF.spinStun(Sp, who)
      if done then Sp.stunned = Sp.stunned + 1 else Sp.stunMissed = Sp.stunMissed + 1 end
      PS.spinStuns = (PS.spinStuns or 0) + 1
      if PS.spinStuns <= K.lines then
        local name = "?"
        pcall(function() name = TDBID.ToStringDEBUG(who:GetRecordID()) end)
        log(string.format("ELECTRIC SPIN (%.0f %%): %s - %s", Sp.charged * 100.0, tostring(name), tostring(how)))
      end
    end
  end
end

