function FPF.fistStagger(who, kind, level)
  if not who or not IsDefined(who) then return 0 end
  local vehicle = false
  pcall(function() vehicle = who:IsVehicle() == true end)
  if vehicle then return 0 end
  local K = FPC.fist.stagger
  local worth = nil
  pcall(function() local _, w = FPF.coreWorth(who); worth = w end)
  local list, how = {}, ""
  if worth == "a boss" then
    local c, chance = K.boss[kind], 0.0
    if type(c) == "table" then chance = c[1] + (c[2] - c[1]) * clamp(level or 0.0, 0.0, 1.0) elseif type(c) == "number" then chance = c end
    if chance > 0.0 then chance = chance + FPF.perkValue("fiststun") end
    if chance > 0.0 and math.random() < chance then
      list, how = { K.jab }, string.format("a boss-class one, staggered (%.0f %%)", chance * 100.0)
    else
      how = (chance > 0.0) and string.format("a boss-class one, %.0f %% missed", chance * 100.0) or "a boss-class one - nothing"
    end
  elseif kind == "jab" then
    list, how = { K.jab }, "staggered"
  elseif kind == "charged" then
    if (level or 0.0) >= FPC.fist.charge.stunFrom then list, how = { K.stun, K.shock }, "stunned, electrocuted" else list, how = { K.down, K.shock }, "knocked down, electrocuted" end
  elseif kind == "berserk" then
    list, how = { K.down, K.shock }, "knocked down, electrocuted"
  else
    list, how = { K.down }, "knocked down"
  end
  local done = 0
  for _, eff in ipairs(list) do
    if pcall(function() if not OP77.statusObserved(who, eff) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](who, TweakDBID.new(eff)) end end) then done = done + 1 end
  end
  PS.fistStaggers = (PS.fistStaggers or 0) + 1
  if PS.fistStaggers <= FPC.fist.lines * 2 then
    local name = "?"
    pcall(function() name = TDBID.ToStringDEBUG(who:GetRecordID()) end)
    log(string.format("FISTS %s: %s - %s (%d of %d of the game's effects took)", kind, tostring(name), how, done, #list))
  end
  return done
end

function FPF.fistRound(x, y, z, reach, high)
  if S.clock - PS.npcsAt > 0.08 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  local out = {}
  local function take(ent, kind)
    if not ent or not IsDefined(ent) then return end
    local ok, p = pcall(function() return ent:GetWorldPosition() end)
    if not ok or not p then return end
    local dx, dy = p.x - x, p.y - y
    local d = math.sqrt(dx * dx + dy * dy)
    if d <= reach and math.abs(p.z - z) <= high then
      local key = nil
      pcall(function() key = tostring(ent:GetEntityID()) end)
      out[#out + 1] = { ent = ent, kind = kind, d = d, x = p.x, y = p.y, z = p.z, key = key or (kind .. #out) }
    end
  end
  for _, who in ipairs(PS.npcs) do take(who, "person") end
  for _, veh in ipairs(FPF.vehicles()) do take(veh, "vehicle") end
  return out
end

function FPF.fistBlast(x, y, z, skip, why)
  local K = FPC.fist
  local rec = FPF.gunRecord(K.records.blast)
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local n, cars = 0, 0
  for _, T in ipairs(FPF.fistRound(x, y, z, K.core.blast, K.core.high)) do
    if not (skip and skip[T.key]) then
      if T.kind == "vehicle" then
        cars = cars + 1
        FPF.wreck(T.ent, FPC.wreck.punch * 0.3)
      else
        n = n + 1
        FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, fx, fy, 0.0)
        FPF.fistStagger(T.ent, "blast")
      end
    end
  end
  if P.fxOn then
    local inst = FPF.fxAt(K.fx.big, x, y, z, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fx.life } end
  end
  FPF.stim("Explosion", FPC.stims.punch, 0.2)
  PS.fistBlasts = (PS.fistBlasts or 0) + 1
  if PS.fistBlasts <= K.lines then
    log(string.format("BERSERKER shock %d (%s): %.0f m round where it landed - %d people knocked down, %d vehicles", PS.fistBlasts, tostring(why), K.core.blast, n, cars))
  end
end

function FPF.hammerStart(M)
  local K = FPC.fist
  local H = K.hammer
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local x, y = PS.x + fx * H.ahead, PS.y + fy * H.ahead
  local z = PS.z
  local gz = groundZ(x, y, PS.z)
  if gz and math.abs(gz - PS.z) <= 3.0 then z = gz end
  local rec = FPF.gunRecord(K.records.blast)
  local n, cars = 0, 0
  for _, T in ipairs(FPF.fistRound(x, y, z, H.reach, H.high)) do
    if not (M and M.hit and M.hit[T.key]) then
      if T.kind == "vehicle" then
        cars = cars + 1
        FPF.wreck(T.ent, FPC.wreck.punch * 0.5)
      else
        n = n + 1
        FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, T.x - x, T.y - y, 0.0)
        FPF.attack(rec, T.x, T.y, T.z + 0.5)
        FPF.fistStagger(T.ent, "hammer")
      end
    end
  end
  if P.fxOn then
    local inst = FPF.fxAt(K.fx.big, x, y, z + 0.3, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fx.life } end
    for _, ring in ipairs(H.rings) do
      for i = 1, H.each do
        local a = (i - 0.5) / H.each * 2.0 * math.pi
        local px, py = x + math.cos(a) * ring, y + math.sin(a) * ring
        local pz = groundZ(px, py, z + 2.0) or z
        if math.abs(pz - z) > 3.0 then pz = z end
        local inst2 = FPF.fxAt(K.fx.mid, px, py, pz + 0.2, nil, nil)
        if inst2 then PS.fxLive[#PS.fxLive + 1] = { inst = inst2, till = S.clock + K.fx.life } end
      end
    end
  end
  FPF.swordSound(FPC.sword.sounds.waveFire, math.max(FPF.viewVolume(), 0.6))
  FPF.stim("Explosion", FPC.stims.punch * 2.0, 0.2)
  PS.hammerReadyAt = S.clock + H.every
  PS.hammers = (PS.hammers or 0) + 1
  if PS.hammers <= K.lines then
    log(string.format("SEISMIC HAMMER %d: the heavy blow shakes the ground %.0f m ahead - %d people within %.0f m knocked down, %d vehicles; again in %.0f s",
      PS.hammers, H.ahead, n, H.reach, cars, H.every))
  end
end

function FPF.jabStart(by)
  local K = FPC.fist
  PS.jabN = (PS.jabN or 0) % 4 + 1
  local n = PS.jabN
  local C = PUNCH_CLIP.fist.jabs[n]
  local F = FP.jabs and FP.jabs[n]
  local J = { t = 0.0, n = n, rate = K.jab.rate, tp = C, fpTime = (F and F.time) or C.time, side = C.side, done = false, by = by,
    seen = S.clock, sent = 0 }
  J.from = (PF.shown and F and F.hit) or C.hit
  J.len = math.max(J.fpTime, C.time)
  PS.jab, PS.sprintOn = J, false
  PS.jabs = (PS.jabs or 0) + 1
  PS.fistBlows = (PS.fistBlows or 0) + 1
  local how = ""
  if P.lunge then
    PS.npcsAt = -10
    refreshNpcs()
    local T = FPF.punchTargets(K.reach + K.jab.lungeFrom, K.angle)[1]
    local due = J.from / J.rate
    if T and T.dist > K.jab.lungeStop and due > 0.05 then
      local go = math.min(T.dist - K.jab.lungeStop, TF.dodgeSpeed * due)
      PS.lunge = { x = T.dx, y = T.dy, speed = go / due, t = 0.0, time = due }
      how = string.format("; it steps %.1f m at a %s %.1f m away", go, T.kind, T.dist)
    end
  end
  FPF.punchSound("swing")
  if PS.jabs <= K.lines then
    log(string.format("JAB %d (%s): the %s fist (%d of four), it lands after %.2f s; reach %.1f m, %.0f deg%s", PS.jabs, tostring(by),
      J.side == "r" and "right" or "left", n, J.from / J.rate, K.reach, K.angle, how))
  end
  return J
end

function FPF.jabHit(ent, J)
  local K = FPC.fist
  local rec = FPF.gunRecord(FPF.coreOn() and K.records.core or K.records.jab)
  if S.clock - PS.npcsAt > 0.08 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local T = nil
  for _, X in ipairs(FPF.punchTargets(K.reach, K.angle)) do
    if S.driving or X.kind ~= "person" or FPF.aiHostilePerson(X.ent) then
      T = X
      break
    end
  end
  if not T then
    J.met = 0
    local best = nil
    if P.punchWall then
      for _, h in ipairs(FPC.punchWall.heights) do
        local t, k = rayWorld(PS.x, PS.y, PS.z + h, fx, fy, 0.0, K.reach)
        if k ~= "nothing" and k ~= "person" and (best == nil or t < best) then best = t end
      end
      if best then FPF.punchSound("hit") end
    end
    if PS.jabs <= K.lines then log(string.format("JAB %d meets nobody within %.1f m%s", PS.jabs, K.reach, best and string.format(" - the world %.1f m ahead", best) or "")) end
    return
  end
  J.met, J.key = 1, T.key
  if (PS.punchChecked or 0) < 12 then
    PS.punchChecked = (PS.punchChecked or 0) + 1
    PS.checks[#PS.checks + 1] = { ent = T.ent, before = healthOf(T.ent), at = S.clock + 0.4, dist = T.dist, kind = T.kind, by = "the fists' jab",
      what = (T.kind == "person") and personText(T.ent) or FPF.vehicleText(T.ent) }
  end
  if FPF.hit(T.ent, rec, T.x, T.y, T.z, fx, fy, 0.0) then J.sent = 1 end
  FPF.attack(rec, T.x, T.y, T.z)
  if T.kind == "vehicle" then
    FPF.wreck(T.ent, FPC.wreck.punch * K.jab.wreck)
  else
    FPF.fistStagger(T.ent, "jab")
  end
  FPF.stim("Explosion", FPC.stims.punch, 0.2)
  FPF.punchSound("hit")
  if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), T.x, T.y, T.z, S.yaw, 0.0) end
  if FPF.coreOn() then FPF.fistBlast(T.x, T.y, T.z, { [T.key] = true }, "a jab") end
  if PS.jabs <= K.lines then
    log(string.format("JAB %d lands on a %s %.1f m away (%s; hit event %s)", PS.jabs, T.kind, T.dist, rec, J.sent > 0 and "taken" or "NOT taken"))
  end
end

function FPF.fistGuardFrame(dt)
  local K = FPC.fist.guard
  local B = PS.fistGuard
  if not B then
    B = { energy = K.max, on = false, idle = K.delay, ups = 0, blocked = 0, saved = 0.0, soundAt = -10.0 }
    PS.fistGuard = B
  end
  if B.aiTill then
    if S.clock < B.aiTill and not S.driving then return B end
    B.aiTill, B.on, B.idle = nil, false, 0.0
  end
  local want = S.driving and S.pilot and PS.mode == "pilot" and PS.zoom and not PS.auto and not (PS.vortex and PS.vortex.on)
    and not PS.jab and not PS.punch and not PS.pound and not PS.fistCharge and not PS.fistPress
  if B.on then
    B.energy = math.max(0.0, B.energy - K.drain * dt)
    if not want or B.energy <= 0.0 then
      B.on, B.idle = false, 0.0
      if B.ups <= FPC.fist.lines then
        log(string.format("GUARD %d down (%s): %d hits guarded so far, %.0f of V's health points kept off BT", B.ups,
          (B.energy <= 0.0) and "its energy is gone" or (PS.zoom and "a blow, the charge or the shield" or "the aim key let go"), B.blocked, B.saved))
      end
    end
  elseif want and B.energy >= K.least then
    B.on, B.ups, B.upAt = true, B.ups + 1, S.clock
    FPF.swordSound(FPC.sword.sounds.raise, FPF.viewVolume())
    if B.ups <= FPC.fist.lines then
      log(string.format("GUARD %d up: hits from within %.0f deg of the view, no blast, take x %.2f more (energy %.0f); a boss's blow within %.2f s is parried",
        B.ups, K.arc, K.take, B.energy, K.window))
    end
  end
  if not B.on then
    B.idle = B.idle + dt
    if B.idle >= K.delay then B.energy = math.min(K.max, B.energy + K.regen * dt) end
  end
  return B
end

function FPF.fistTake(fx, fy, blast)
  return FPF.aiView(FPF.fistTakeNow, fx, fy, blast)
end

function FPF.fistTakeNow(fx, fy, blast)
  local k = FPF.perkValue("fistarmor")
  local B, guarded = PS.fistGuard, false
  if B and B.on and not blast then
    local front = true
    if fx and fy then
      local d = math.sqrt(fx * fx + fy * fy)
      if d >= 0.5 then
        local r = math.rad(S.yaw)
        front = (fx * -math.sin(r) + fy * math.cos(r)) / d >= math.cos(math.rad(FPC.fist.guard.arc))
      end
    end
    if front then k, guarded = k * FPC.fist.guard.take, true end
  end
  if FPF.coreOn() then k = k * FPC.fist.core.take end
  return k, guarded
end

function FPF.fistTook(kept, k, guarded)
  PS.fistKept = (PS.fistKept or 0.0) + kept
  PS.fistTakes = (PS.fistTakes or 0) + 1
  local B, K = PS.fistGuard, FPC.fist.guard
  if guarded and B then
    B.blocked, B.saved = B.blocked + 1, B.saved + kept
    if S.clock - B.soundAt >= K.gap then
      B.soundAt = S.clock
      FPF.swordSound(FPC.sword.sounds.block, FPF.viewVolume())
    end
  end
  if PS.fistTakes <= 6 then
    log(string.format("FISTS: a hit taken at x %.2f (%s%s) - %.0f of V's health points kept off BT", k, guarded and "guarded" or "the frame",
      FPF.coreOn() and ", BERSERKER CORE" or "", kept))
  end
end

FPF.hitSeen133 = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H = PS.hp
  if not H or PS.weapon ~= "fist" or not evt or type(H.pend[tag]) ~= "number" then return FPF.hitSeen133(evt, tag) end
  local before, big = H.pend[tag], H.bigV
  local r = FPF.hitSeen133(evt, tag)
  local added = H.pend[tag] - before
  if added > 0.0 then
    local fx, fy, blast = nil, nil, false
    pcall(function()
      local p = evt.attackData:GetInstigator():GetWorldPosition()
      fx, fy = p.x - PS.x, p.y - PS.y
    end)
    pcall(function() blast = EnumName("gamedataAttackType", evt.attackData:GetAttackType()):find("Explosion", 1, true) ~= nil end)
    local k, guarded = FPF.fistTake(fx, fy, blast)
    if k < 1.0 then
      H.pend[tag] = before + added * k
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
      if tag == "a" then FPF.fistTook(added * (1.0 - k), k, guarded) end
    end
  end
  return r
end

FPF.bossHit133 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  if PS.weapon ~= "fist" then return FPF.bossHit133(record, x, y, z, dx, dy, who, kind) end
  local fx = (type(x) == "number") and (x - PS.x) or nil
  local fy = (type(y) == "number") and (y - PS.y) or nil
  local B, K = PS.fistGuard, FPC.fist.guard
  if B and B.on and B.upAt and S.clock - B.upAt <= K.window and type(record) == "string" then
    local open = FPF.bossOpen()
    local melee = kind == "melee" or (kind == nil and FPF.bossMelee(record))
    local _, guarded = FPF.fistTake(fx, fy, false)
    if open and melee and guarded then
      PS.parries = (PS.parries or 0) + 1
      PS.lastParry = { at = S.clock, record = record, who = tostring(who) }
      FPF.punchSound("hit")
      FPF.swordSound(FPC.sword.sounds.block, math.max(FPF.viewVolume(), 0.9))
      if PS.parries <= FPC.fist.lines then
        log(string.format("PARRY %d (the fists): %s's blow (%s) met the guard %.2f s after it went up (within %.2f s) - nothing taken; fpf.bossHit says \"parried\"",
          PS.parries, tostring(who), record, S.clock - B.upAt, K.window))
      end
      return true, "parried", 0.0
    end
  end
  local okP, parried = pcall(FPF.fistAiParry, record, x, y, dx, dy, who, kind)
  if okP and parried then return true, "parried", 0.0 end
  local H = PS.hp
  if not H then return FPF.bossHit133(record, x, y, z, dx, dy, who, kind) end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit133(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" then
    local k, guarded = FPF.fistTake(fx, fy, kind == "blast")
    if k < 1.0 then
      local added = H.pend.a - a0
      H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
      if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - pts * (1.0 - k) end
      FPF.fistTook(added * (1.0 - k), k, guarded)
      pts = pts * k
    end
  end
  return ok, what, pts
end

function FPF.fistChargeStart(by, ai)
  local K = FPC.fist.charge
  local C = { from = S.clock, level = 0.0, by = by, ai = ai == true, n = (PS.fistCharges or 0) + 1 }
  if ai then
    local H = FPC.fistAI.charge.hold
    C.till = S.clock + H[1] + math.random() * (H[2] - H[1])
  end
  PS.fistCharge, PS.fistCharges = C, C.n
  PS.jab = nil
  FPF.swordSound(FPC.sword.sounds.raise, FPF.viewVolume())
  if C.n <= FPC.fist.lines then
    log(string.format("FIST CHARGE %d (%s): the wind-up held, full in %.1f s; let go: the charged straight (from %.0f %% the game's stun)",
      C.n, tostring(by), K.full, K.stunFrom * 100.0))
  end
  return C
end

function FPF.fistChargeFrame(dt)
  local K = FPC.fist.charge
  local C = PS.fistCharge
  if not C then
    PS.fistChargeW = math.max(0.0, (PS.fistChargeW or 0.0) - dt / K.fadeOut)
    return nil
  end
  PS.fistChargeW = math.min(1.0, (PS.fistChargeW or 0.0) + dt / K.fadeIn)
  local t = S.clock - C.from
  C.level = clamp(t / FPF.chargeFull(K), 0.0, 1.0)
  local held
  if C.ai then held = not S.driving and S.clock < (C.till or 0.0) else held = S.driving and S.pilot and PS.meleeHeld == true end
  if held and t < K.most and not PS.exec and not FPF.flightImmune() then
    local wave = 0.6 * math.sin(t * K.tremble.hz[1] * 2.0 * math.pi) + 0.4 * math.sin(t * K.tremble.hz[2] * 2.0 * math.pi + 1.3)
    C.shake = (0.4 + 0.6 * C.level) * (0.5 + 0.5 * wave)
    return nil
  end
  PS.fistCharge = nil
  if C.n <= FPC.fist.lines then
    log(string.format("FIST CHARGE %d let go after %.2f s: %s", C.n, t, (C.level >= K.least) and string.format("charged %.0f %%", C.level * 100.0) or "too little - the heavy blow"))
  end
  return "release", C.level, C.by
end

function FPF.fistChargeFlats(c)
  local K, Kc = FPC.fist, FPC.fist.charge
  local base = FPF.coreOn() and K.records.core or K.records.heavy
  local row = nil
  for _, R in ipairs(FPC.tune.damage) do if R[1] == base then row = R end end
  if not row then return 1.0 end
  local mul = 1.0 + (Kc.damage - 1.0) * c
  local k, m = P.damageScale, FPF.perkValue("fistdamage")
  for i, kind in ipairs(FPC.tune.kinds) do
    local v = row[2][i] * k * m * mul * ((kind == "boss") and P.bossMul or 1.0)
    pcall(function() TweakDB:SetFlat(K.records.charged .. "." .. kind .. "NPCMaxHPDamage", v) end)
  end
  pcall(function() TweakDB:SetFlat(K.records.charged .. ".explosionDamageVSVehicles", row[3] * k * m * mul) end)
  pcall(function() TweakDB:Update(K.records.charged) end)
  PS.fistChargeOf, PS.fistChargeMul = base, mul
  return mul
end

FPF.coreBossShare133 = FPF.coreBossShare
function FPF.coreBossShare(record)
  if record ~= nil and record == FPC.fist.records.charged then
    local share = FPF.coreBossShare133(PS.fistChargeOf or FPC.fist.records.heavy)
    return share and share * (PS.fistChargeMul or 1.0) or nil
  end
  return FPF.coreBossShare133(record)
end

function FPF.fistBlowStart(kind, level, by)
  local K = FPC.fist
  local C = (kind == "berserk") and PUNCH_CLIP.fist.berserk or PUNCH_CLIP.fist.charged
  local F = FP.chargeHit
  local M = { t = 0.0, dash = kind == "berserk", hit = {}, done = false, sent = 0, attacks = 0, lunge = 0.0, x0 = PS.x, y0 = PS.y,
    clip = C, view = FP.view and FP.view.charge_hit, fistKind = kind, level = level, by = by }
  if kind == "berserk" then
    local Kb = K.berserk
    M.from, M.to = Kb.pre, Kb.pre + Kb.time
    M.fpAt = C.hit - ((F and F.hit) or 0.17)
    M.fp = math.max(C.time, M.fpAt + ((F and F.time) or C.time))
  else
    M.from = (PF.shown and F and F.hit) or C.hit
    M.to = M.from + 0.15
    M.fp = math.max(C.time, (F and F.time) or C.time)
    if P.lunge then
      PS.npcsAt = -10
      refreshNpcs()
      local T = FPF.punchTargets(PUNCH.lungeRange, PUNCH.lungeAngle)[1]
      if T and T.dist > PUNCH.lungeStop and M.from > 0.05 then
        local go = math.min(T.dist - PUNCH.lungeStop, TF.dodgeSpeed * M.from)
        PS.lunge = { x = T.dx, y = T.dy, speed = go / M.from, t = 0.0, time = M.from }
        M.lunge = go
      end
    end
  end
  PS.punch, PS.punches, PS.sprintOn, PS.punchClip = M, PS.punches + 1, false, K.tpClips[kind]
  PS.fistBlows = (PS.fistBlows or 0) + 1
  PS.jab = nil
  if kind == "charged" then
    FPF.swordSound(FPC.sword.sounds.waveFire, FPF.viewVolume())
  else
    FPF.punchSound("swing")
    pcall(FPF.dashSound)
  end
  PS.fistBlowLines = (PS.fistBlowLines or 0) + 1
  if PS.fistBlowLines <= K.lines then
    log(string.format("%s (%s)%s: it meets what is in front from %.2f s%s", (kind == "berserk") and "BERSERKER PUNCH" or "CHARGED STRAIGHT", tostring(by),
      level and string.format(" %.0f %%", level * 100.0) or "", M.from,
      (kind == "berserk") and string.format(" - %.1f m/s for %.1f s after %.1f s", K.berserk.speed, K.berserk.time, K.berserk.pre)
        or ((M.lunge > 0) and string.format("; it lunges %.1f m", M.lunge) or "")))
  end
  return M
end

FPF.punchHit133 = FPF.punchHit
function FPF.punchHit(ent, M, last)
  if PS.weapon ~= "fist" or not M or not M.fistKind then return FPF.punchHit133(ent, M, last) end
  local K = FPC.fist
  local kind = M.fistKind
  local rec
  if kind == "charged" then
    rec = FPF.gunRecord(K.records.charged)
    if rec == K.records.charged and not M.flats then
      M.flats = true
      FPF.fistChargeFlats(M.level or 1.0)
    end
  elseif kind == "berserk" or FPF.coreOn() then
    rec = FPF.gunRecord(K.records.core)
  else
    rec = FPF.gunRecord(K.records.heavy)
  end
  local range0, angle0, rec0 = PUNCH.range, PUNCH.angle, PS.punchRecord
  PUNCH.range = K.blowReach + ((kind == "charged") and K.charge.reach * (M.level or 0.0) or 0.0)
  PUNCH.angle = K.blowAngle
  PS.punchRecord = rec
  local hit0, met = FPF.hit, {}
  FPF.hit = function(who, record, ...)
    met[#met + 1] = who
    return hit0(who, record, ...)
  end
  local ok, err = pcall(FPF.punchHit133, ent, M, last)
  FPF.hit, PUNCH.range, PUNCH.angle, PS.punchRecord = hit0, range0, angle0, rec0
  if not ok then error(err, 0) end
  for _, who in ipairs(met) do FPF.fistStagger(who, kind, M.level) end
  M.fistMet = (M.fistMet or 0) + #met
  if M.done and not M.fistAfter then
    M.fistAfter = true
    if kind == "heavy" and FPF.perk("fist") > 0 and S.clock >= (PS.hammerReadyAt or 0.0)
      and (not P.hammerTwice or M.hammerAsk or not (S.driving and S.pilot)) then guard("SEISMIC HAMMER", FPF.hammerStart, M) end
    if (FPF.coreOn() or kind == "berserk") and (M.fistMet > 0 or kind == "berserk") then
      local r = math.rad(S.yaw)
      local reach = K.blowReach * 0.6
      guard("BERSERKER shock", FPF.fistBlast, PS.x - math.sin(r) * reach, PS.y + math.cos(r) * reach, PS.z, M.hit, kind)
    end
  end
end

function FPF.fistFrame(dt, ent)
  local K = FPC.fist
  local J = PS.jab
  if J and S.clock - J.seen > K.stale then
    PS.jab, J = nil, nil
  end
  FPF.fistGuardFrame(dt)
  local due = nil
  local Pp = PS.fistPress
  if Pp then
    if not (S.driving and S.pilot and PS.meleeHeld == true) then
      PS.fistPress, due = nil, "heavy"
    elseif S.clock - Pp.at >= K.charge.hold then
      PS.fistPress = nil
      FPF.fistChargeStart(Pp.by, false)
    end
  end
  local rel, level, by = FPF.fistChargeFrame(dt)
  if rel then
    if level >= K.charge.least and not PS.punch and not PS.exec then
      FPF.fistBlowStart("charged", level, by)
    else
      due = "heavy"
    end
  end
  local fire = PS.fistFire == true
  if not S.driving then fire = fire and FPF.fistAiJab() end
  if FPF.flightImmune() then
    if fire and not PS.fistFireWas then FPF.flightNoMelee("the jabs") end
    fire = false
  end
  PS.fistFireWas = PS.fistFire == true
  local free = not PS.punch and not PS.pound and not PS.fistCharge and not PS.fistPress and not (PS.vortex and PS.vortex.on) and not PS.exec
    and not (PS.fistGuard and PS.fistGuard.on)
  if fire and free and (not J or J.t >= J.len - K.jab.chain) then
    J = FPF.jabStart(S.driving and "the fire key" or "BT on its own")
  end
  if J then
    J.seen = S.clock
    J.t = J.t + dt * J.rate
    if not J.done and J.t >= J.from then
      J.done = true
      guard("the jab's hit", FPF.jabHit, ent, J)
    end
    if J.t >= J.len then PS.jab = nil end
  end
  return due
end

FPF.aiHolds133 = FPF.aiHolds
function FPF.aiHolds()
  if PS.weapon == "fist" then return true end
  return FPF.aiHolds133()
end

function FPF.fistAiJab()
  local Bd = PS.buddy
  local T = Bd and Bd.target
  if not T or not T.ent then return false end
  local C = Bd.chase
  if C and C.mode == "back" then return false end
  return (T.dist or 1000.0) <= FPC.fistAI.jabReach
end

FPF.punch133 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" then return FPF.punch133(dt, ent, key) end
  local driving = S.driving and S.pilot
  if key and driving and PS.execHint then
    PS.jab, PS.fistPress, PS.fistCharge = nil, nil, nil
    return FPF.punch133(dt, ent, key)
  end
  local blow = nil
  if key then
    if FPF.flightImmune() then
      return FPF.punch133(dt, ent, key)
    end
    local dash = PS.dashT ~= nil and PS.dashT < TF.dodgeTime + PUNCH.dashGrace
    if PS.punch or PS.fistCharge or PS.fistPress then
      blow = nil
    elseif FPF.coreOn() and not PS.jump then
      blow = "berserk"
    elseif dash then
      blow = "dash"
    elseif driving and PS.meleeHeld == true then
      PS.fistPress = { at = S.clock, by = PS.punchBy or "the melee key" }
    else
      blow = "heavy"
    end
    if blow ~= "heavy" and blow ~= "dash" then key = false end
  end
  local ok, due = pcall(FPF.fistFrame, dt, ent)
  if not ok then
    once("fistframe" .. tostring(due), "the fists could NOT be run (" .. tostring(due) .. ")")
    due = nil
  end
  if due == "heavy" and not PS.punch then key, blow = true, "heavy" end
  if blow == "berserk" then
    FPF.fistBlowStart("berserk", nil, PS.punchBy or "the melee key")
    PS.punchBy = nil
    key = false
  end
  local before = PS.punch
  local r = FPF.punch133(dt, ent, key)
  local M = PS.punch
  if M and M ~= before and key and (blow == "heavy" or blow == "dash") and not M.fistKind then
    M.fistKind = blow
    M.clip = (blow == "dash") and PUNCH_CLIP.fist.dash or PUNCH_CLIP.fist.heavy
    PS.punchClip = FPC.fist.tpClips[blow]
    PS.fistBlows = (PS.fistBlows or 0) + 1
    PS.jab = nil
  end
  M = PS.punch
  if M and M.fistKind == "berserk" and not M.ran and M.t >= FPC.fist.berserk.pre then
    M.ran = true
    local rr = math.rad(S.yaw)
    PS.lunge = { x = -math.sin(rr), y = math.cos(rr), speed = FPC.fist.berserk.speed, t = 0.0, time = FPC.fist.berserk.time }
    M.lunge = FPC.fist.berserk.speed * FPC.fist.berserk.time
  end
  return r
end

FPF.gunFrame133 = gunFrame
gunFrame = function(dt, ent, firing)
  if PS.weapon ~= "fist" then
    PS.fistFire = false
    return FPF.gunFrame133(dt, ent, firing)
  end
  FPF.gunChecks()
  PS.fistFire = firing and true or false
  PS.reloadKey, PS.reloadW = false, 0.0
  local G = PS.gun
  if G then G.reloadT, G.anim = nil, nil end
end

function FPF.fistWeights()
  local K = FPC.fist
  local fist = PS.weapon == "fist" and not PS.exec and not PS.eject
  local gw = fist and clamp(1.0 - (PS.sceneW or 0.0), 0.0, 1.0) or 0.0
  local B = PS.fistGuard
  local want = fist and B ~= nil and B.on and not PS.jab and not PS.punch and not PS.pound
  local dt = clamp(S.clock - (PS.fistBlockWAt or S.clock), 0.0, 0.1)
  PS.fistBlockWAt = S.clock
  local w = PS.fistBlockW or 0.0
  if want then w = math.min(1.0, w + dt / K.guard.blockIn) else w = math.max(0.0, w - dt / K.guard.blockOut) end
  PS.fistBlockW = w
  local J = PS.jab
  local jw, jt = 0.0, 0.0
  if J and fist then
    jt = math.min(J.t, J.tp.time)
    jw = clamp(math.min(J.t / K.jab.fadeIn, (J.tp.time - J.t) / K.jab.fadeOut), 0.0, 1.0)
    PS.jabClip = J.n - 1
  end
  return gw, ease(w) * gw, jw * gw, PS.jabClip or 0.0, jt
end

FPF.chargeWeights133 = FPF.chargeWeights
function FPF.chargeWeights()
  if PS.weapon == "fist" then
    local w = clamp(PS.fistChargeW or 0.0, 0.0, 1.0)
    if PS.exec or PS.eject then w = 0.0 end
    return w, FPC.fist.chargeClip
  end
  return FPF.chargeWeights133()
end

function FPF.fistPoseBusy()
  if PS.weapon ~= "fist" then return false end
  local B = PS.fistGuard
  return (B ~= nil and B.on) or (PS.fistBlockW or 0.0) > 0.0 or PS.jab ~= nil or PS.fistCharge ~= nil or (PS.fistChargeW or 0.0) > 0.0
end

FPF.placeBt133 = FPF.placeBt
function FPF.placeBt()
  local W = PS.awake
  if P.awake and W and FPF.fistPoseBusy() then
    W.at = math.min(W.at, S.clock)
    if not PS.awakeFistSaid then
      PS.awakeFistSaid = true
      log("BT kept awake every frame while the fists guard, jab or charge")
    end
  end
  return FPF.placeBt133()
end

function FPF.fistFxFrame()
  local K = FPC.fist
  local on = PS.weapon == "fist" and (PS.fistCharge ~= nil or FPF.coreOn()) and not PS.exec and not PS.eject
  local want = on and (PF.shown and "fp" or "tp") or nil
  local cur = PS.fistFx
  if cur and cur.view == want then return end
  if cur then
    for _, name in ipairs(cur.names) do FPF.entFx(cur.ent, name, false) end
    PS.fistFx = nil
  end
  if not want then return end
  local ent = (want == "fp") and PF.ent or PS.ent
  local names = (want == "fp") and K.fxFp or K.fxTp
  local n = 0
  for _, name in ipairs(names) do if FPF.entFx(ent, name, true) then n = n + 1 end end
  PS.fistFx = { view = want, ent = ent, names = names }
  PS.fistFxN = (PS.fistFxN or 0) + 1
  if PS.fistFxN <= 3 then
    log(string.format("FISTS: the hands' sparks on (%s: %s) - %d of %d started", want == "fp" and "in view" or "outside", table.concat(names, ", "), n, #names))
  end
end

FPF.drive133 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive133(dt, steps, sprinting)
  pcall(FPF.fistFxFrame)
  if PS.weapon ~= "fist" or not PF.shown or not PF.ent or not IsDefined(PF.ent) then return end
  local K = FPC.fist
  local J, C, M = PS.jab, PS.fistCharge, PS.punch
  local clip, t, name = nil, 0.0, nil
  if J then
    clip, t, name = K.fpJab + J.n - 1, math.min(J.t, J.fpTime), "jab" .. J.n
  elseif C and FP.charge then
    clip, t, name = K.fpCharge, math.min(S.clock - C.from, FP.charge.time), "charge"
  elseif M and M.fistKind == "charged" and FP.chargeHit then
    clip, t, name = K.fpChargeHit, math.min(M.t, FP.chargeHit.time), "charge_hit"
  elseif M and M.fistKind == "berserk" and FP.chargeHit and FP.charge then
    if M.t < (M.fpAt or 0.0) then
      clip, t = K.fpCharge, math.min(M.t / math.max(M.fpAt, 0.05) * FP.charge.time, FP.charge.time)
    else
      clip, t, name = K.fpChargeHit, math.min(M.t - (M.fpAt or 0.0), FP.chargeHit.time), "charge_hit"
    end
  end
  if not clip then return end
  FPF.var("fp_melee_clip", clip)
  FPF.var("fp_melee", (C and C.shake) and (1.0 - K.charge.tremble.fp * C.shake) or 1.0)
  FPF.var("fp_time_melee", t)
  local V = name and FP.view and FP.view[name]
  if V and #V >= 2 then
    local p, y, r = FPF.sway(V, t)
    local k = J and K.jab.sway or 1.0
    PF.sway[1], PF.sway[2], PF.sway[3] = p * k, y * k, r * k
  end
end

FPF.fpGun133 = FPF.fpGun
function FPF.fpGun(dt)
  if PS.weapon ~= "fist" then return FPF.fpGun133(dt) end
  if not FP.aim then return end
  local B = PS.fistGuard
  local on = B and B.on and not PS.jab and not PS.punch and not PS.pound and not PS.fistCharge and not (PS.vortex and PS.vortex.on)
  local t = PF.aimT or 0.0
  if on then t = math.min(FP.aim, t + dt) else t = math.max(0.0, t - dt) end
  PF.aimT = t
  FPF.var("fp_aim", (t > 0.0) and 1.0 or 0.0)
  FPF.var("fp_time_aim", t)
end

FPF.damageFlats133 = FPF.damageFlats
function FPF.damageFlats()
  FPF.damageFlats133()
  local k, m, n = P.damageScale, FPF.perkValue("fistdamage"), 0
  if m == 1.0 then return end
  local mine = {}
  for _, rec in pairs(FPC.fist.records) do mine[rec] = true end
  for _, R in ipairs(FPC.tune.damage) do
    if mine[R[1]] then
      for i, kind in ipairs(FPC.tune.kinds) do
        local v = R[2][i] * k * m * ((kind == "boss") and P.bossMul or 1.0)
        if pcall(function() TweakDB:SetFlat(R[1] .. "." .. kind .. "NPCMaxHPDamage", v) end) then n = n + 1 end
      end
      pcall(function() TweakDB:SetFlat(R[1] .. ".explosionDamageVSVehicles", R[3] * k * m) end)
      pcall(function() TweakDB:Update(R[1]) end)
    end
  end
  if n > 0 then log(string.format("damage of BT's weapons: the FISTS' records x %.2f (IRON FISTS)", m)) end
end

