function FPF.fistNote()
  local out = ""
  if FPF.perk("fist") > 0 then
    local left = (PS.hammerReadyAt or 0.0) - S.clock
    out = (left > 0.0) and string.format("   HAMMER %d", math.ceil(left)) or "   HAMMER READY"
  end
  local B = PS.fistGuard
  if B and (B.on or B.energy < FPC.fist.guard.max - 0.5) then
    out = out .. string.format("   GUARD %d %%%s", math.floor(B.energy / FPC.fist.guard.max * 100.0 + 0.5), B.on and " ON" or "")
  end
  local C = PS.fistCharge
  if C then out = out .. string.format("   CHARGE %d %%", math.floor(C.level * 100.0 + 0.5)) end
  if FPF.coreOn() then out = out .. "   BERSERKER" end
  return out
end

