function FPF.fistChase(B, dt)
  local K = FPC.fistAI
  local T = B.target
  local open = P.aiFist and PS.weapon == "fist" and T ~= nil and T.ent ~= nil and not P.hold and not B.off
    and (not P.peace or T.designated == true) and not B.board and not FPF.guardPlain() and FPF.questHeld() == nil
    and S.clock - (T.seenAt or -10.0) <= K.seen
  local vd = 0.0
  if open then
    vd = math.sqrt(((B.vx or PS.x) - T.x) ^ 2 + ((B.vy or PS.y) - T.y) ^ 2)
    open = vd <= K.leash and math.abs(T.z - (T.up or 0.0) - PS.z) <= K.rise
  end
  local C = B.chase
  if not open then
    if C then B.chase, B.path, B.pathGoal, B.detour, B.prog = nil, nil, nil, nil, nil end
    return nil
  end
  local Z = B.sword
  if not Z then
    Z = { chases = 0, dashes = 0, backs = 0, backDashes = 0 }
    B.sword = Z
  end
  local KB = K.back
  if not C or not FPF.sameEnt(C.ent, T.ent) then
    C = { ent = T.ent, mode = "close", dashAt = S.clock + FPF.aiDashGap(FPC.swordAI.dashFirst), nearT = 0.0, nearNeed = FPF.aiDashGap(KB.every),
      blows = PS.fistBlows or 0, need = math.random(KB.blows[1], KB.blows[2]), backEnd = -100.0 }
    B.chase, B.detour = C, nil
    Z.chases = Z.chases + 1
    if Z.chases <= K.lines then
      log(string.format("BT on its own, the fists: it goes for its foe (%.0f m away, %.0f m from V)", T.dist or -1.0, vd))
    end
  end
  if C.mode == "back" then
    if C.till == nil and PS.jab == nil and PS.punch == nil then C.till = S.clock + FPF.aiDashGap(KB.time) end
    if C.till and S.clock >= C.till then
      C.mode, C.till, C.backEnd, B.detour = "close", nil, S.clock, nil
      C.nearT, C.nearNeed = 0.0, FPF.aiDashGap(KB.every)
      C.blows, C.need = PS.fistBlows or 0, math.random(KB.blows[1], KB.blows[2])
    end
  else
    if (T.dist or 1000.0) <= K.jabReach then C.nearT = C.nearT + dt end
    local did = (PS.fistBlows or 0) - (C.blows or 0)
    local why = nil
    if did >= C.need then
      why = string.format("after %d blows", did)
    elseif C.nearT >= C.nearNeed then
      why = string.format("%.0f s at its foe", C.nearT)
    end
    if why and S.clock - C.backEnd >= KB.gap and PS.jab == nil and PS.punch == nil and PS.fistCharge == nil and PS.dashT == nil and PS.lunge == nil then
      C.mode, C.till, C.backDash, C.backDashed, B.detour = "back", nil, math.random() < KB.dash, false, nil
      Z.backs = Z.backs + 1
      if Z.backs <= K.lines then
        log(string.format("BT on its own, the fists: it backs off (%s; its foe %.1f m away)%s", why, T.dist or -1.0, C.backDash and " - a dash back" or ""))
      end
    end
  end
  return C
end

