FPF.aiSkills133 = FPF.aiSkills
function FPF.aiSkills(B, dt, T)
  if PS.weapon ~= "fist" then return FPF.aiSkills133(B, dt, T) end
  local K, Kf = FPC.ai, FPC.fist
  local C = B.chase
  local Kc = FPC.fistAI.charge
  if T and T.ent and not S.driving and not PS.punch and not PS.fistCharge and not PS.jab and not (C and C.mode == "back")
      and (T.dist or 1000.0) <= Kf.blowReach and S.clock - (PS.aiFistChargeAt or -100.0) >= Kc.gap then
    PS.aiFistChargeAt = S.clock
    local big = false
    pcall(function() local _, w = FPF.coreWorth(T.ent); big = (w == "a boss" or w == "a heavy") end)
    if big or FPF.aiFoesNear(Kf.blowReach) >= Kc.foes or math.random() < Kc.chance then
      FPF.aiView(function() FPF.fistChargeStart("BT on its own", true) end)
    end
  end
  local reach, gap, cone = K.punchReach, K.punchGap, K.punchCone
  K.punchReach = (C and C.mode == "back") and -1.0 or Kf.blowReach
  K.punchGap, K.punchCone = Kf.ai.heavyGap, Kf.ai.cone
  local ok, err = pcall(FPF.aiSkills133, B, dt, T)
  K.punchReach, K.punchGap, K.punchCone = reach, gap, cone
  if not ok then error(err, 0) end
end

function FPF.fistAiParry(record, x, y, dx, dy, who, kind)
  local K = FPC.fistAI.parry
  local Bd = PS.buddy
  if not P.aiFist or PS.weapon ~= "fist" or S.driving or type(record) ~= "string" or not Bd or Bd.state ~= "active" then return false end
  if PS.flight and PS.flight.on then return false end
  local open, why = FPF.bossOpen()
  if not open or why ~= "nobody in it" then return false end
  local melee = kind == "melee" or (kind == nil and FPF.bossMelee(record))
  if not melee or PS.jab or PS.punch or PS.pound or PS.fistCharge or PS.dashT ~= nil or PS.jump or (PS.hp and PS.hp.doomed) then return false end
  local fx = (type(x) == "number") and (x - PS.x) or nil
  local fy = (type(y) == "number") and (y - PS.y) or nil
  if (fx == nil or fx * fx + fy * fy < 0.25) and type(dx) == "number" and type(dy) == "number" then fx, fy = -dx, -dy end
  if fx and fy then
    local d = math.sqrt(fx * fx + fy * fy)
    if d >= 0.1 then
      local r = math.rad(Bd.yaw or PS.yaw)
      if (fx * -math.sin(r) + fy * math.cos(r)) / d < math.cos(math.rad(FPC.fist.guard.arc)) then return false end
    end
  end
  local Z = PS.aiFistParry
  if not Z then
    Z = { asked = 0, n = 0, nextAt = 0.0 }
    PS.aiFistParry = Z
  end
  if S.clock < Z.nextAt then return false end
  Z.asked = Z.asked + 1
  if math.random() >= K.chance then return false end
  Z.n, Z.nextAt = Z.n + 1, S.clock + K.gap
  local Bk = PS.fistGuard or FPF.fistGuardFrame(0.0)
  Bk.on, Bk.upAt, Bk.aiTill = true, S.clock, S.clock + K.hold
  PS.parries = (PS.parries or 0) + 1
  PS.lastParry = { at = S.clock, record = record, who = tostring(who), ai = true }
  local level = math.min(0.9, FPF.jarLevel(false) + K.louder)
  FPF.punchSound("hit")
  FPF.swordSound(FPC.sword.sounds.block, level)
  if Z.n <= K.lines then
    log(string.format("PARRY %d (BT on its own, the fists; %d of the %d blows it could have parried): %s's blow (%s) met its guard - nothing taken; fpf.bossHit says \"parried\"",
      PS.parries, Z.n, Z.asked, tostring(who), record))
  end
  return true
end

