function FPF.t135Setup()
  local shares = { ["Attacks.BT7274_Fist"] = { 0.78, 0.78, 0.6, 0.4, 0.24, 0.08 },
    ["Attacks.BT7274_Fist_Heavy"] = { 1.2, 1.2, 1.1, 0.72, 0.45, 0.17 },
    ["Attacks.BT7274_Fist_Charged"] = { 2.4, 2.4, 2.2, 1.44, 0.9, 0.34 },
    ["Attacks.BT7274_Fist_Core"] = { 1.6, 1.6, 1.3, 0.9, 0.6, 0.2 },
    ["Attacks.BT7274_Fist_Blast"] = { 0.65, 0.65, 0.45, 0.29, 0.18, 0.05 } }
  local plain = nil
  for _, R in ipairs(FPC.tune.damage) do
    if R[1] == FPC.sword.records.slash then plain = R end
  end
  FPC.rows134, FPC.rows135 = {}, {}
  for _, R in ipairs(FPC.tune.damage) do
    local s, v = shares[R[1]], R[3]
    if R[1] == FPC.sword.records.core and plain then
      s, v = {}, plain[3]
      for i, x in ipairs(plain[2]) do s[i] = x end
    end
    if s then
      local was = {}
      for i, x in ipairs(R[2]) do was[i] = x end
      FPC.rows134[R[1]], FPC.rows135[R[1]] = { was, R[3] }, { s, v }
    end
  end
  FPF.rowsSet(FPC.rows135)
  PS.npcInfo = PS.npcInfo or {}
end

function FPF.rowsSet(rows)
  for _, R in ipairs(FPC.tune.damage) do
    local v = rows[R[1]]
    if v then
      local row = {}
      for i, x in ipairs(v[1]) do row[i] = x end
      R[2], R[3] = row, v[2]
      for _, B in ipairs(FPC.boss) do
        if B[1] == R[1] then B[2] = row[6] end
      end
    end
  end
  FPC.bossShare = nil
end
