function FPF.sqs()
  if S.sqsAt ~= S.clock or not S.sqsH then
    S.sqsH, S.sqsAt = Game.GetSpatialQueriesSystem(), S.clock
  end
  return S.sqsH
end

function FPF.npcCache()
  local C = PS.npcAtC
  if not C or C.list ~= PS.npcs or C.at ~= S.clock then
    C = { list = PS.npcs, at = S.clock, p = {}, k = (C and C.list == PS.npcs) and C.k or {} }
    PS.npcAtC = C
  end
  return C
end

function FPF.npcAt(i)
  local C = FPF.npcCache()
  local p = C.p[i]
  if p == nil then
    p = false
    local ent = C.list[i]
    if ent and IsDefined(ent) then
      local ok, w = pcall(function() return ent:GetWorldPosition() end)
      if ok and w then p = w end
    end
    C.p[i] = p
  end
  return p or nil
end

function FPF.npcKeyAt(i)
  local C = FPF.npcCache()
  local k = C.k[i]
  if k == nil then
    local ent = C.list[i]
    pcall(function() k = tostring(ent:GetEntityID()) end)
    C.k[i] = k or false
  end
  return k or nil
end

FPC.npcRayMargin, FPC.npcStale = 8.0, 0.5
function FPF.npcRayAt(i, ox, oy, oz, dx, dy, dz, len)
  local C = FPF.npcCache()
  local L = PS.npcLast
  if not L or L.list ~= PS.npcs then
    L = { list = PS.npcs, p = {}, at = {} }
    PS.npcLast = L
  end
  local q = L.p[i]
  if q and C.p[i] == nil and S.clock - L.at[i] < FPC.npcStale then
    local hx, hy, hz = q[1] - ox, q[2] - oy, q[3] - oz
    local t = clamp(hx * dx + hy * dy + hz * dz, 0.0, len)
    local ex, ey, ez = hx - dx * t, hy - dy * t, hz - dz * t
    if ex * ex + ey * ey + ez * ez > FPC.npcRayMargin * FPC.npcRayMargin then return nil end
  end
  local p = FPF.npcAt(i)
  if p and L.at[i] ~= S.clock then L.p[i], L.at[i] = { p.x, p.y, p.z }, S.clock end
  return p
end

function FPF.pushFrame58()
  if not P.solid or not PS.ent then return end
  local K = FPC.push
  if S.clock >= PS.pushListAt and (S.clock - PS.vehiclesAt < (FPC.vehEvery or 0.4) or FPF.heavyTurn("q.vehicles")) then
    PS.pushListAt = S.clock + K.list
    pcall(FPF.vehicles)
  end
  local near, any, close, at = {}, false, false, {}
  for i, veh in ipairs(PS.vehicles or {}) do
    if IsDefined(veh) then
      local ok, p = pcall(veh.GetWorldPosition, veh)
      if ok and p then
        at[i] = p
        local dx, dy = p.x - PS.x, p.y - PS.y
        if dx * dx + dy * dy < (K.reach + FPC.pushNear) ^ 2 and math.abs(p.z - PS.z) < 6.0 then close = true end
      end
    end
  end
  if close then
    local z = PS.z + K.height
    local q = FPF.sqs()
    for i = 1, K.rays do
      local a = (i - 1) / K.rays * 2.0 * math.pi
      local ux, uy = math.cos(a), math.sin(a)
      local res = nil
      pcall(function()
        local hit, r = q:SyncRaycastByCollisionGroup(Vector4.new(PS.x, PS.y, z, 1.0), Vector4.new(PS.x + ux * K.reach, PS.y + uy * K.reach, z, 1.0), "Vehicle", nil, false, false)
        if hit and r and r.position then res = r end
      end)
      if res then
        PS.vehicleRes = res
        local veh = FPF.vehicleAt(res.position.x, res.position.y, res.position.z)
        if veh then
          local key = FPF.vehKey(veh)
          local d = math.sqrt((res.position.x - PS.x) ^ 2 + (res.position.y - PS.y) ^ 2)
          local N = near[key]
          if not N or d < N.d then
            near[key], any = { veh = veh, d = d, ux = ux, uy = uy, x = res.position.x, y = res.position.y }, true
          end
        end
      end
    end
  end
  for i, veh in ipairs(PS.vehicles or {}) do
    local p = at[i]
    if p then
      local rx, ry = p.x - PS.x, p.y - PS.y
      local dist = math.sqrt(rx * rx + ry * ry)
      if dist < 1.2 and math.abs(p.z - PS.z) < 2.5 then
        pcall(function()
          local key = FPF.vehKey(veh)
          if not near[key] then
            local ux, uy = rx, ry
            if dist < 0.2 then ux, uy, dist = (PS.speed > 0.2) and PS.vx or 1.0, (PS.speed > 0.2) and PS.vy or 0.0, 1.0 end
            local n = math.sqrt(ux * ux + uy * uy)
            near[key], any = { veh = veh, d = 0.0, ux = ux / n, uy = uy / n, x = p.x, y = p.y }, true
          end
        end)
      end
    end
  end
  if not any then return end
  for key, N in pairs(near) do FPF.push(key, N) end
end

function FPF.fistRound(x, y, z, reach, high)
  if S.clock - PS.npcsAt > FPC.fist.roundFresh then
    PS.npcsAt = -10
    refreshNpcs()
  end
  local out = {}
  for i, ent in ipairs(PS.npcs) do
    local p = FPF.npcAt(i)
    if p then
      local dx, dy = p.x - x, p.y - y
      local d = math.sqrt(dx * dx + dy * dy)
      if d <= reach and math.abs(p.z - z) <= high then
        out[#out + 1] = { ent = ent, kind = "person", d = d, x = p.x, y = p.y, z = p.z, key = FPF.npcKeyAt(i) or ("person" .. #out) }
      end
    end
  end
  for _, veh in ipairs(FPF.vehicles()) do
    if veh and IsDefined(veh) then
      local ok, p = pcall(function() return veh:GetWorldPosition() end)
      if ok and p then
        local dx, dy = p.x - x, p.y - y
        local d = math.sqrt(dx * dx + dy * dy)
        if d <= reach and math.abs(p.z - z) <= high then
          local key = nil
          pcall(function() key = tostring(veh:GetEntityID()) end)
          out[#out + 1] = { ent = veh, kind = "vehicle", d = d, x = p.x, y = p.y, z = p.z, key = key or ("vehicle" .. #out) }
        end
      end
    end
  end
  return out
end

