function FPF.coreWatch()
  local on = FPF.coreOn()
  if on == (PS.coreWas == true) then return end
  PS.coreWas = on
  if PS.weapon == "sword" then
    if on then
      PS.power = math.min(FPF.dashMax(), (PS.power or 0.0) + TF.dodgeDrain * FPC.sword.core.dash)
    elseif PS.power and PS.power > FPF.dashMax() then
      PS.power = FPF.dashMax()
    end
  end
end

function FPF.swordRate()
  return FPF.coreOn() and FPC.sword.core.rate or 1.0
end

FPF.dashMax134 = FPF.dashMax
function FPF.dashMax()
  local m = FPF.dashMax134()
  if PS.weapon == "sword" and FPF.coreOn() then m = m + TF.dodgeDrain * FPC.sword.core.dash end
  return m
end

function FPF.waveCharge(dt)
  local K = FPC.sword.wave
  local c = PS.waveCharges or K.charges
  local k = FPF.coreOn() and FPC.sword.core.wave or 1.0
  c = math.min(K.charges, c + (dt or 0.0) * k / K.every)
  PS.waveCharges = c
  PS.waveReadyAt = (c >= 1.0) and 0.0 or (S.clock + (1.0 - c) * K.every / k)
  return c
end

function FPF.chargeFull(K)
  return K.full * (FPF.coreOn() and FPC.coreCharge or 1.0)
end

FPF.coreGunWords134 = FPF.coreGunWords
function FPF.coreGunWords()
  if PS.weapon == "sword" then
    local K = FPC.sword.core
    return string.format("Sword Core - the BROADSWORD's slashes %.1f times as fast, %.1f m further; ARC WAVE back %.0f times as fast, the charge full in %.0f %% of the time, %d dash more",
      K.rate, K.reach, K.wave, FPC.coreCharge * 100.0, K.dash)
  elseif PS.weapon == "fist" then
    local K = FPC.fist
    return string.format("BERSERKER CORE - the FISTS: %.1f times as fast, the blows take %s and shake %.0f m round them, every blow that lands gives BT health back, hits take x %.2f more, the charge full in %.0f %% of the time; the melee key is the BERSERKER PUNCH",
      K.core.speed, K.records.core, K.core.blast, K.core.take, FPC.coreCharge * 100.0)
  end
  return FPF.coreGunWords134()
end

function FPF.fistLeech(kind, n)
  if PS.weapon ~= "fist" or not FPF.coreOn() or (n or 1) <= 0 then return end
  local K = FPC.fist.core.leech
  local H = PS.hp
  if not H or H.doomed or H.gone then return end
  local full = FPC.health.segment * FPC.health.segments
  local was = H.health
  H.health = math.min(full, H.health + (K[kind] or K.blow) * math.min(n or 1, K.most))
  if H.health <= was then return end
  PS.leeched, PS.leeches = (PS.leeched or 0.0) + (H.health - was), (PS.leeches or 0) + 1
  if PS.leeches <= FPC.fist.lines then
    log(string.format("BERSERKER CORE: a blow landed (%s, %d met) - BT's health %.0f -> %.0f of %.0f", tostring(kind), n or 1, was, H.health, full))
  end
end

FPF.jabHit134 = FPF.jabHit
function FPF.jabHit(ent, J)
  FPF.jabHit134(ent, J)
  if J and (J.met or 0) > 0 then pcall(FPF.fistLeech, "jab", 1) end
end

FPF.punchHit134 = FPF.punchHit
function FPF.punchHit(ent, M, last)
  local met0 = M and M.fistMet or 0
  FPF.punchHit134(ent, M, last)
  if PS.weapon == "fist" and M and M.fistKind then
    local n = (M.fistMet or 0) - met0
    if n > 0 then
      local left = FPC.fist.core.leech.most - (M.leeched or 0)
      if left > 0 then
        M.leeched = (M.leeched or 0) + math.min(n, left)
        pcall(FPF.fistLeech, (M.fistKind == "berserk") and "berserk" or "blow", math.min(n, left))
      end
    end
  end
end

function FPF.trackAt(C, t)
  local n = #C.ahead
  local i = clamp(t * C.fps, 0.0, n - 1)
  local a = math.floor(i)
  local u = i - a
  local b = math.min(a + 2, n)
  return C.ahead[a + 1] + (C.ahead[b] - C.ahead[a + 1]) * u, C.side[a + 1] + (C.side[b] - C.side[a + 1]) * u
end

function FPF.fistNativeStart(kind, level, by)
  local K = FPC.fist
  local N = K.native[kind]
  local C = PUNCH_CLIP.fist[kind]
  local M = { t = 0.0, dash = false, hit = {}, done = false, sent = 0, attacks = 0, lunge = 0.0, x0 = PS.x, y0 = PS.y, clip = C,
    fistKind = kind, level = level, by = by, native = true, met = 0, cars = 0 }
  M.fp = C.time
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local scale, how = 1.0, ""
  local T = nil
  if kind ~= "shoulder" then
    PS.npcsAt = -10
    refreshNpcs()
    T = FPF.punchTargets(N.look, K.blowAngle)[1]
  end
  if kind == "finisher" then
    M.from, M.to = C.hit - 0.02, C.hit + N.window
    if T then
      scale = clamp((T.dist - N.gap) / math.max(FPF.trackAt(C, C.time), 0.1), N.least, N.most)
      fx, fy = T.dx, T.dy
      how = string.format("; it closes on a %s %.1f m away", T.kind, T.dist)
    end
  else
    M.from, M.to = 1.0e9, 1.0e9
    M.sweepFrom, M.sweepTo = N.from, N.to
    if kind == "spin" then
      scale = N.least + (1.0 - N.least) * clamp(level or 0.0, 0.0, 1.0)
      if T then
        fx, fy = T.dx, T.dy
        how = string.format("; toward a %s %.1f m away", T.kind, T.dist)
      end
    else
      scale = N.rush
    end
  end
  M.scale = scale
  PS.lunge = { x = fx, y = fy, track = C, punch = M, scale = scale, last = 0.0, t = 0.0, time = C.time + 0.5 }
  M.lunge = FPF.trackAt(C, C.time) * scale
  PS.punch, PS.punches, PS.sprintOn, PS.punchClip = M, PS.punches + 1, false, K.tpClips[kind]
  PS.fistBlows = (PS.fistBlows or 0) + 1
  PS.jab = nil
  if kind == "spin" then
    FPF.swordSound(FPC.sword.sounds.waveFire, FPF.viewVolume())
    pcall(FPF.dashSound)
  elseif kind == "shoulder" then
    pcall(FPF.dashSound)
    FPF.punchSound("swing")
  else
    FPF.punchSound("swing")
  end
  PS.fistNatives = (PS.fistNatives or 0) + 1
  if PS.fistNatives <= K.lines * 2 then
    log(string.format("%s (%s)%s: BT's own blow, %.2f s - it meets what is in front at %.2f s; Titanfall's track x %.2f = %.1f m%s",
      (kind == "finisher") and "HIGH PUNCH (the jabs' fourth)" or ((kind == "spin") and "SPIN PUNCH (the charge let go)" or "SHOULDER CHARGE"),
      tostring(by), level and string.format(" %.0f %%", level * 100.0) or "", C.time, C.hit, scale, M.lunge, how))
  end
  return M
end

function FPF.fistSweep(M)
  local K = FPC.fist
  local N = K.native[M.fistKind]
  if not N or M.t < M.sweepFrom or M.t > M.sweepTo then
    if M.t > (M.sweepTo or 0.0) and not M.swept then
      M.swept = true
      if (PS.fistNatives or 0) <= K.lines * 2 then
        log(string.format("%s over: it met %d people and %d vehicles on its way", (M.fistKind == "spin") and "SPIN PUNCH" or "SHOULDER CHARGE", M.met, M.cars))
      end
    end
    return
  end
  if M.fistKind == "spin" and not M.flats then
    M.flats = true
    FPF.fistChargeFlats(M.level or 1.0)
  end
  local L = PS.lunge
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  if L and L.track then fx, fy = L.x, L.y end
  local x, y = PS.x + fx * N.ahead, PS.y + fy * N.ahead
  local rec
  if M.fistKind == "spin" then
    rec = FPF.gunRecord(K.records.charged)
  else
    rec = FPF.gunRecord(FPF.coreOn() and K.records.core or K.records.heavy)
  end
  local n = 0
  for _, T in ipairs(FPF.fistRound(x, y, PS.z, N.reach, N.high)) do
    if not M.hit[T.key] then
      M.hit[T.key] = true
      if T.kind == "vehicle" then
        M.cars = M.cars + 1
        FPF.wreck(T.ent, FPC.wreck.punch * N.wreck)
      else
        M.met, n = M.met + 1, n + 1
        FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, fx, fy, 0.0)
        FPF.attack(rec, T.x, T.y, T.z + 0.5)
        FPF.fistStagger(T.ent, (M.fistKind == "spin") and "charged" or "shoulder", M.level)
        if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), T.x, T.y, T.z + 1.5, S.yaw, 0.0) end
        if FPF.coreOn() then FPF.fistBlast(T.x, T.y, T.z, M.hit, M.fistKind) end
      end
    end
  end
  if n > 0 then
    FPF.punchSound("hit")
    FPF.stim("Explosion", FPC.stims.punch, 0.2)
    local left = K.core.leech.most - (M.leeched or 0)
    if left > 0 then
      M.leeched = (M.leeched or 0) + math.min(n, left)
      pcall(FPF.fistLeech, "rush", math.min(n, left))
    end
  end
end

FPC.fist.jab.chainGap = 1.2
FPF.jabStart134 = FPF.jabStart
function FPF.jabStart(by)
  if S.clock - (PS.jabLastAt or -100.0) > FPC.fist.jab.chainGap then PS.jabN = 0 end
  PS.jabLastAt = S.clock
  local n = (PS.jabN or 0) % 4 + 1
  if n == 4 and P.fistFinisher and not PS.punch then
    PS.jabN = 4
    FPF.fistNativeStart("finisher", nil, by)
    return nil
  end
  return FPF.jabStart134(by)
end

FPF.fistBlowStart134 = FPF.fistBlowStart
function FPF.fistBlowStart(kind, level, by)
  if kind == "charged" and P.fistSpin then return FPF.fistNativeStart("spin", level, by) end
  return FPF.fistBlowStart134(kind, level, by)
end

FPF.punch134 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" then return FPF.punch134(dt, ent, key) end
  local B = PS.fistGuard
  local held = PS.meleeHeld
  local guarded = key and B ~= nil and B.on and S.driving and S.pilot and not PS.punch
  if guarded then PS.meleeHeld = false end
  local step = FPF.coreOn() and dt * FPC.fist.core.speed or dt
  local ok, r = pcall(FPF.punch134, step, ent, key)
  if guarded then
    PS.meleeHeld = held
    if PS.punch and PS.punch.fistKind == "heavy" and (PS.guardBlows or 0) < FPC.fist.lines then
      PS.guardBlows = (PS.guardBlows or 0) + 1
      log("GUARD -> the heavy blow at once (the melee key while guarding)" .. ((FPF.perk("fist") > 0 and S.clock >= (PS.hammerReadyAt or 0.0)) and (P.hammerTwice and " - SEISMIC HAMMER is ready (the melee key again)" or " - SEISMIC HAMMER is ready") or ""))
    end
  end
  if not ok then error(r, 0) end
  local M = PS.punch
  if M and M.native and M.sweepFrom then guard("the fists' rush", FPF.fistSweep, M) end
  if PS.hammerWave then guard("SEISMIC HAMMER's shock", FPF.hammerWaveFrame, step) end
  return r
end

function FPF.hammerStart(M)
  local K = FPC.fist
  local H = K.hammer
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local x, y = PS.x + fx * H.ahead, PS.y + fy * H.ahead
  local z = PS.z
  local gz = groundZ(x, y, PS.z)
  if gz and math.abs(gz - PS.z) <= 3.0 then z = gz end
  PS.hammers = (PS.hammers or 0) + 1
  PS.hammerWave = { x = x, y = y, z = z, r = 0.0, hit = {}, skip = (M and M.hit) or {}, rings = 0, people = 0, cars = 0, n = PS.hammers, at = S.clock }
  if P.fxOn then
    local inst = FPF.fxAt(K.fx.big, x, y, z + 0.3, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fx.life } end
  end
  FPF.swordSound(FPC.sword.sounds.waveFire, math.max(FPF.viewVolume(), 0.6))
  FPF.stim("Explosion", FPC.stims.punch * 2.0, 0.2)
  PS.hammerReadyAt = S.clock + H.every
  FPF.hammerWaveFrame(0.0)
end

function FPF.hammerWaveFrame(dt)
  local W = PS.hammerWave
  if not W then return end
  local K = FPC.fist
  local H = K.hammer
  W.r = math.min(H.reach, W.r + (dt or 0.0) * H.speed)
  while W.rings < #H.rings and W.r >= H.rings[W.rings + 1] - 1e-6 do
    W.rings = W.rings + 1
    if P.fxOn then
      local ring = H.rings[W.rings]
      for i = 1, H.each do
        local a = (i - 0.5) / H.each * 2.0 * math.pi
        local px, py = W.x + math.cos(a) * ring, W.y + math.sin(a) * ring
        local pz = groundZ(px, py, W.z + 2.0) or W.z
        if math.abs(pz - W.z) > 3.0 then pz = W.z end
        local inst = FPF.fxAt(K.fx.mid, px, py, pz + 0.2, nil, nil)
        if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fx.life } end
      end
    end
  end
  for _, T in ipairs(FPF.fistRound(W.x, W.y, W.z, W.r, H.high)) do
    if not W.hit[T.key] and not W.skip[T.key] then
      W.hit[T.key] = true
      local inner = T.d <= H.rings[1]
      if T.kind == "vehicle" then
        W.cars = W.cars + 1
        FPF.wreck(T.ent, FPC.wreck.punch * (inner and 0.8 or 0.4))
      else
        W.people = W.people + 1
        local rec = FPF.gunRecord(inner and K.records.heavy or K.records.blast)
        FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, T.x - W.x, T.y - W.y, 0.0)
        FPF.attack(rec, T.x, T.y, T.z + 0.5)
        FPF.fistStagger(T.ent, "hammer")
      end
    end
  end
  if W.r >= H.reach then
    PS.hammerWave = nil
    if W.n <= K.lines then
      log(string.format("SEISMIC HAMMER %d: the heavy blow's shock ran out %.0f m from %.0f m ahead of BT in %.2f s (%.0f m/s) - %d people knocked down (the inner %.0f m with the heavy blow's record, beyond with the blast's), %d vehicles; again in %.0f s",
        W.n, H.reach, H.ahead, S.clock - W.at, H.speed, W.people, H.rings[1], W.cars, math.max(0.0, (PS.hammerReadyAt or 0.0) - S.clock)))
    end
  end
end

function FPF.shoulderCharge(dt)
  local most = FPC.fist.native.shoulder.charges
  local c = PS.shoulderCharge
  if c == nil then c = most end
  if c < most then c = math.min(most, c + (dt or 0.0) * most / FPF.spinRefill()) end
  PS.shoulderCharge = c
  return c
end

function FPF.shoulderCan()
  if not P.fistShoulder then return false, "off" end
  if FPF.perk("sentry") < 1 then return false, "SENTRY MODE is disabled by the server loadout - the FISTS' shoulder charge comes with it" end
  local c = PS.shoulderCharge or FPC.fist.native.shoulder.charges
  if c < 1.0 then
    return false, string.format("no charge left - the next in %.1f s", (1.0 - c) * FPF.spinRefill() / FPC.fist.native.shoulder.charges)
  end
  if PS.mode ~= "pilot" then return false, "nobody pilots BT" end
  if PS.jump then return false, "BT is in a jump" end
  if PS.punch or PS.lunge or PS.pound then return false, "its fist is out" end
  if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then return false, "it is in a dash" end
  if PS.skate then return false, "it skates" end
  if PS.flight then return false, "FLIGHT STRIKE is on" end
  if PS.exec then return false, "an execution" end
  if PS.vortex and PS.vortex.on then return false, "the vortex shield is up" end
  return true
end

FPF.sentryFrame134 = FPF.sentryFrame
function FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
  if PS.weapon ~= "fist" or not P.fistShoulder then return FPF.sentryFrame134(dt, f, s, sprint, dash, jump, held) end
  local K = FPC.fist.native.shoulder
  local n = PS.keyN.sentry or 0
  local pressed = n ~= (PS.sentrySeen or 0)
  PS.sentrySeen = n
  FPF.shoulderCharge(dt)
  if pressed then
    local ok, why = false, "the keys are taken"
    if not held then ok, why = FPF.shoulderCan() end
    if ok then
      PS.shoulderCharge = (PS.shoulderCharge or K.charges) - 1.0
      PS.jab, PS.fistPress = nil, nil
      if PS.fistCharge then PS.fistCharge = nil end
      local B = PS.fistGuard
      if B and B.on then B.on, B.idle = false, 0.0 end
      FPF.fistNativeStart("shoulder", nil, "SENTRY MODE's key")
    else
      PS.shoulderRefused = (PS.shoulderRefused or 0) + 1
      if PS.shoulderRefused <= K.lines then log("SHOULDER CHARGE: not now - " .. tostring(why)) end
    end
  end
  f, s, sprint, dash, jump = FPF.sentryFrame134(dt, f, s, sprint, dash, jump, held)
  local M = PS.punch
  if M and M.fistKind == "shoulder" then return 0, 0, false, false, false end
  return f, s, sprint, dash, jump
end

FPF.slotStates134 = FPF.slotStates
function FPF.slotStates(M, V, Q)
  local out = FPF.slotStates134(M, V, Q)
  if PS.weapon == "fist" and FPF.perk("sentry") > 0 and P.fistShoulder then
    local most = FPC.fist.native.shoulder.charges
    local c = PS.shoulderCharge or most
    local P_ = PS.punch
    out.sentry = { fill = (c >= most) and 1.0 or (c - math.floor(c)), count = math.floor(c + 1e-6),
      state = (P_ and P_.fistKind == "shoulder") and "active" or ((c >= 1.0) and "ready" or "empty") }
  end
  return out
end

FPF.fistNote134 = FPF.fistNote
function FPF.fistNote()
  local out = FPF.fistNote134()
  if FPF.perk("sentry") > 0 and P.fistShoulder then
    out = out .. string.format("   SHOULDER %d", math.floor((PS.shoulderCharge or FPC.fist.native.shoulder.charges) + 1e-6))
  end
  return out
end

function FPF.fistSceneArms()
  local c = math.floor((PS.sceneClip or 1) + 0.5)
  local a = FPC.fist.sceneArms[c] or ""
  if a == "drop" then
    local D = SCENES.drop
    return clamp(((PS.sceneTime or 0.0) - ((D and D.getupFrom) or 0.0) + 0.3) / 0.6, 0.0, 1.0), 0.0
  end
  return a:find("l", 1, true) and 1.0 or 0.0, a:find("r", 1, true) and 1.0 or 0.0
end

FPF.fistWeights134 = FPF.fistWeights
function FPF.fistWeights()
  local gw, bw, jw, jc, jt = FPF.fistWeights134()
  local l, r = 0.0, 0.0
  if PS.weapon == "fist" and not PS.exec then
    local sw = clamp(PS.sceneW or 0.0, 0.0, 1.0)
    local al, ar = FPF.fistSceneArms()
    l, r = (1.0 - sw) + sw * al, (1.0 - sw) + sw * ar
    if PS.eject and sw < 0.5 then l, r = 0.0, 0.0 end
  end
  PS.fistGuardR = r
  return l, bw, jw, jc, jt
end

function FPF.upperOf(clip)
  if not P.upperBlows or PS.spin or not clip then return nil end
  local c = math.floor(clip + 0.5)
  if math.abs(clip - c) > 1e-3 then return nil end
  return PUNCH_CLIP.fist.upper[c]
end

FPF.drive134 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive134(dt, steps, sprinting)
  if PS.weapon ~= "fist" or not PF.shown or not PF.ent or not IsDefined(PF.ent) then return end
  local M = PS.punch
  if not M or not M.native then return end
  local K = FPC.fist
  if M.fistKind == "finisher" and FP.melee and FP.meleeHit then
    local at = math.max(0.0, M.from - FP.meleeHit)
    FPF.var("fp_melee_clip", 0.0)
    FPF.var("fp_melee", 1.0)
    FPF.var("fp_time_melee", clamp(M.t - at, 0.0, FP.melee))
  elseif M.fistKind == "spin" and FP.charge and FP.chargeHit then
    local at = math.max(0.0, M.clip.hit - (FP.chargeHit.hit or 0.17))
    if M.t < at then
      FPF.var("fp_melee_clip", K.fpCharge)
      FPF.var("fp_time_melee", FP.charge.time)
    else
      FPF.var("fp_melee_clip", K.fpChargeHit)
      FPF.var("fp_time_melee", math.min(M.t - at, FP.chargeHit.time))
    end
    FPF.var("fp_melee", 1.0)
  elseif M.fistKind == "shoulder" then
    FPF.var("fp_melee", 0.0)
  end
end

FPF.fpGun134 = FPF.fpGun
function FPF.fpGun(dt)
  local M = PS.punch
  if PS.weapon ~= "fist" or not (M and M.fistKind == "shoulder") or not FP.aim then return FPF.fpGun134(dt) end
  local t = math.min(FP.aim, (PF.aimT or 0.0) + dt)
  PF.aimT = t
  FPF.var("fp_aim", 1.0)
  FPF.var("fp_time_aim", t)
end

FPF.fistChase134 = FPF.fistChase
function FPF.fistChase(B, dt)
