FPF.jabStart135 = FPF.jabStart
function FPF.jabStart(by)
  if not P.fistCombos then return FPF.jabStart135(by) end
  local K = FPC.fist
  local C = PS.fistCombo
  if not C then
    C = { which = "B", n = 0, done = true, count = 0 }
    PS.fistCombo = C
  end
  if C.done or (C.n > 0 and S.clock - (PS.jabLastAt or -100.0) > K.jab.chainGap) then
    C.which, C.n, C.done, C.count = (C.which == "A") and "B" or "A", 0, false, C.count + 1
    if C.count <= K.combo.lines then
      log(string.format("COMBO %s: %s" .. (P.fistFinisher and ", then the high punch with the %s fist" or ""), C.which,
        (C.which == "A") and "right, left, right" or "left, right, left", (C.which == "A") and "left" or "right"))
    end
  end
  PS.jabLastAt = S.clock
  if C.n >= 3 then
    if P.fistFinisher and not PS.punch then
      C.done = true
      FPF.fistNativeStart(K.combo.finisher[C.which], nil, by)
      return nil
    end
    C.which, C.n, C.done = (C.which == "A") and "B" or "A", 0, false
  end
  C.n = C.n + 1
  PS.jabN = K.combo[C.which][C.n] - 1
  return FPF.jabStart134(by)
end

