FPF.hammerWaveFrame135 = FPF.hammerWaveFrame
function FPF.hammerWaveFrame(dt)
  local W = PS.hammerWave
  if W and P.fxOn and P.hammerDust then
    local H = FPC.fist.hammer
    if not W.mid then
      W.mid, W.dusts = true, 0
      local m = FPF.fxPath("liftoff")
      if m then
        local inst = FPF.fxAt(m, W.x, W.y, W.z + 0.05, PS.yaw, 0.0)
        if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + H.dustLife } end
      end
    end
    local ring = FPF.fxPath("land")
    local r1 = math.min(H.reach, W.r + (dt or 0.0) * H.speed)
    while ring and W.dusts < #H.dust and r1 >= H.dust[W.dusts + 1] - 1e-6 do
      W.dusts = W.dusts + 1
      local d = H.dust[W.dusts]
      local turn = math.random() * 6.283
      for i = 1, H.dustN do
        local a = turn + (i - 1) / H.dustN * 6.283
        local px, py = W.x + math.cos(a) * d, W.y + math.sin(a) * d
        local pz = groundZ(px, py, W.z + 2.0) or W.z
        if math.abs(pz - W.z) > 3.0 then pz = W.z end
        local inst = FPF.fxAt(ring, px, py, pz + 0.05, math.deg(a), 0.0)
        if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + H.dustLife } end
      end
      W.dustFx = (W.dustFx or 0) + H.dustN
    end
  end
  return FPF.hammerWaveFrame135(dt)
end

function FPF.berserkAim(M)
  local K = FPC.fist.berserk
  PS.npcsAt = -10
  refreshNpcs()
  local T = FPF.punchTargets(K.look, K.cone)[1]
  local go = T and clamp(T.dist - K.stop, 0.0, K.speed * K.time) or 0.0
  PS.fistBerserks = (PS.fistBerserks or 0) + 1
  if go < 0.5 then
    PS.lunge, M.lunge = nil, 0.0
    PS.vx, PS.vy = 0.0, 0.0
    if PS.fistBerserks <= FPC.fist.lines then
      log(T and string.format("BERSERKER PUNCH: a %s %.1f m away - close enough, it punches where it stands", T.kind, T.dist)
        or string.format("BERSERKER PUNCH: nobody within %.0f m and %.0f deg in front - it punches where it stands", K.look, K.cone))
    end
    return
  end
  PS.lunge = { x = T.dx, y = T.dy, speed = K.speed, t = 0.0, time = go / K.speed, halt = true }
  M.lunge = go
  if PS.fistBerserks <= FPC.fist.lines then
    log(string.format("BERSERKER PUNCH: at a %s %.1f m away - it runs %.1f m (%.1f m/s) and stops %.1f m short of it", T.kind, T.dist, go, K.speed, K.stop))
  end
end

