  return r
end

function FPF.upperShare(clip)
  local K = FPC.sword.legs
  if not P.swordLegs or not clip or not K.clips[math.floor(clip + 0.5)] then return 1.0 end
  local want = clamp(math.max(PS.move or 0.0, PS.dash or 0.0, PS.jumpW or 0.0) * K.gain, 0.0, 1.0)
  local u = PS.upperU
  if u == nil or S.clock - (PS.upperUAt or -10.0) > 0.25 then
    u = want
  else
    local step = (S.dt or 0.016) / K.fade
    u = u + clamp(want - u, -step, step)
  end
  PS.upperU, PS.upperUAt = u, S.clock
  return u
end

