function FPF.hitPitchNow()
  if not P.hitPitch or not S.driving or not S.pilot or PS.mode ~= "pilot" then return nil end
  local K = FPC.hitPitch
  if PF.shown then
    local up = (S.camPos and S.camPos.z) and (S.camPos.z - PS.z) or K.pivot
    return clamp(S.pitch or 0.0, -K.fpMost, K.fpMost), up
  end
  return clamp(PS.aimPitch or 0.0, K.low, K.high), K.pivot
end

FPF.punchTargets138 = FPF.punchTargets
function FPF.punchTargets(range, angle)
  local pitch, pivot = nil, nil
  if PS.hitPitchOn then pitch, pivot = FPF.hitPitchNow() end
  if not pitch or math.abs(pitch) < 0.5 then return FPF.punchTargets138(range, angle) end
  local ry = math.rad(S.yaw)
  local fx, fy = -math.sin(ry), math.cos(ry)
  local rx, rgy = fy, -fx
  local cp, sp = math.cos(math.rad(pitch)), math.sin(math.rad(pitch))
  local oz = PS.z + pivot
  local out = {}
  local function take(ent, kind, lift)
    if not IsDefined(ent) then return end
    local ok, p = pcall(function() return ent:GetWorldPosition() end)
    if not ok or not p then return end
    local r, h, name = 0.0, nil, nil
    if kind == "person" then
      pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
      if type(name) == "string" then
        local okS, shape = pcall(FPF.recordShape, name)
        if okS and shape then r, h = shape[1], shape[2] end
      end
    end
    local dx0, dy0 = p.x - PS.x, p.y - PS.y
    local a, b, c = dx0 * fx + dy0 * fy, dx0 * rx + dy0 * rgy, p.z - oz
    local a2, c2 = a * cp + c * sp, -a * sp + c * cp
    local dx, dy, z = fx * a2 + rx * b, fy * a2 + rgy * b, oz + c2
    local dist = math.sqrt(dx * dx + dy * dy)
    local near = math.max(0.0, dist - r)
    local wide = (r > 0.0 and dist > 0.01) and math.deg(math.atan2(r, dist)) or 0.0
    local cone = math.cos(math.rad(math.min(89.0, angle + wide)))
    if near <= range and math.abs(z - PS.z) < 5.0 and (dist < 1.5 + r or (dx * fx + dy * fy) / dist >= cone) then
      local key = kind .. tostring(#out)
      pcall(function() key = tostring(ent:GetEntityID()) end)
      local n0 = math.max(math.sqrt(dx0 * dx0 + dy0 * dy0), 0.01)
      local ux, uy = dx0 / n0, dy0 / n0
      local x, y, zz = p.x, p.y, p.z + lift
      if r > 0.0 then
        x, y, zz = p.x - ux * r, p.y - uy * r, p.z + math.min(h * 0.5, FPC.punchBig.up)
      end
      out[#out + 1] = { ent = ent, kind = kind, dist = near, x = x, y = y, z = zz, key = key, dx = ux, dy = uy, r = r, pitched = pitch }
    end
  end
  for _, who in ipairs(PS.npcs) do take(who, "person", 1.0) end
  for _, veh in ipairs(FPF.vehicles()) do take(veh, "vehicle", 0.6) end
  table.sort(out, function(x1, x2) return x1.dist < x2.dist end)
  return out
end

function FPF.hitPitchSaid(what)
  local pitch = FPF.hitPitchNow()
  if not pitch or math.abs(pitch) < 10.0 then return end
  PS.hitPitchLines = (PS.hitPitchLines or 0) + 1
  if PS.hitPitchLines <= FPC.hitPitch.lines then
    log(string.format("HIT PITCH: the %s found its foes in its own frame, turned %+.0f deg (%s, about %.1f m up)", what, pitch,
      PF.shown and "the camera's pitch" or "the waist's bend", select(2, FPF.hitPitchNow()) or 0.0))
  end
end

