function FPF.jabRampFlats(n)
  local K = FPC.fist
  local mul = K.comboDamage[n] or 1.0
  local base = FPF.coreOn() and K.records.core or K.records.jab
  local row = nil
  for _, R in ipairs(FPC.tune.damage) do if R[1] == base then row = R end end
  if not row then return nil end
  local k, m = P.damageScale, FPF.perkValue("fistdamage")
  for i, kind in ipairs(FPC.tune.kinds) do
    local v = row[2][i] * k * m * mul * ((kind == "boss") and P.bossMul or 1.0)
    pcall(function() TweakDB:SetFlat(K.records.jab .. "." .. kind .. "NPCMaxHPDamage", v) end)
  end
  pcall(function() TweakDB:SetFlat(K.records.jab .. ".explosionDamageVSVehicles", row[3] * k * m * mul) end)
  pcall(function() TweakDB:Update(K.records.jab) end)
  PS.jabRampOf, PS.jabRampMul = base, mul
  return mul
end

FPF.jabHit138 = FPF.jabHit
function FPF.jabHit(ent, J)
  local K = FPC.fist
  local core0 = K.records.core
  local mul = nil
  if P.jabRamp and J and J.combo then
    mul = FPF.jabRampFlats(J.combo)
    if mul then K.records.core = K.records.jab end
  end
  PS.hitPitchOn = true
  local ok, err = pcall(FPF.jabHit138, ent, J)
  PS.hitPitchOn = nil
  K.records.core = core0
  if not ok then error(err, 0) end
  if mul then
    PS.jabRampLines = (PS.jabRampLines or 0) + 1
    if PS.jabRampLines <= K.lines then
      log(string.format("JAB %d of the combo: x %.2f of %s (%s)", J.combo, mul, tostring(PS.jabRampOf),
        (J.met or 0) > 0 and "it met someone" or "it met nobody"))
    end
  end
  FPF.hitPitchSaid("jab")
end

