function FPF.hammerTwice(M)
  local H = FPC.fist.hammer
  local learned = FPF.perk("fist") > 0
  local ready = learned and S.clock >= (PS.hammerReadyAt or 0.0)
  local how
  if not learned then
    how = "SEISMIC HAMMER is disabled by the server loadout"
  elseif not ready then
    how = string.format("SEISMIC HAMMER is not ready - again in %.1f s", (PS.hammerReadyAt or 0.0) - S.clock)
  elseif M.fistAfter then
    local late = M.fistAfterAt and (S.clock - M.fistAfterAt) or 99.0
    if late <= H.twiceGrace then
      FPF.hammerStart(M)
      how = string.format("the blow landed %.2f s ago - the shock goes now", late)
    else
      how = string.format("too late (the blow landed %.2f s ago, %.2f s allowed)", late, H.twiceGrace)
    end
  else
    how = "the shock goes as the blow lands"
  end
  PS.hammerAsks = (PS.hammerAsks or 0) + 1
  if PS.hammerAsks <= FPC.fist.lines then log("SEISMIC HAMMER: the melee key again during the heavy blow - " .. how) end
end

