FPF.healthBase139 = FPF.health59
function FPF.health59(dt, alone)
  local H, K = PS.hp, FPC.health
  local hs, as = P.healthScale or 1.0, P.armorScale or 1.0
  if H and (hs ~= 1.0 or as ~= 1.0) and hs > 0.0 and as > 0.0 then
    local dmg = math.max(H.pend.a, H.pend.b)
    if dmg > 0.0 then
      local c = (K.segment * K.segments + K.shield) / (math.max(P.toughness, 1.0) * H.vMax)
      local p = dmg * c
      local want
      if H.doomed then
        want = p / hs
      elseif p / as <= H.shield then
        want = p / as
      else
        want = H.shield + (p - H.shield * as) / hs
      end
      local k = want / p
      H.pend.a, H.pend.b = H.pend.a * k, H.pend.b * k
    end
  end
  return FPF.healthBase139(dt, alone)
end

FPF.coreGain138 = FPF.coreGain
function FPF.coreGain(points, what, name)
  local k = P.coreScale or 1.0
  if points and k ~= 1.0 then points = points * k end
  return FPF.coreGain138(points, what, name)
end

-- Open77: the P.coreScale of t139 on the function that adds the boss-hit charge (it wrapped FPF.coreBossHit, whose block this now is).
-- Returns the charge it added (after the scale and the core's ceiling), or nil and why.
FPF.coreBossCredit138 = FPF.coreBossCredit
function FPF.coreBossCredit(record, name)
  local C = PS.core
  local before = C and C.charge
  local points, why = FPF.coreBossCredit138(record, name)
  if not points then return nil, why end
  local k = P.coreScale or 1.0
  if C and before and k ~= 1.0 and C.charge > before then
    C.charge = math.min(FPF.coreMax(), before + (C.charge - before) * k)
  end
  return C.charge - before
end

FPF.tuneFrame138 = FPF.tuneFrame
function FPF.tuneFrame()
  FPF.tuneFrame138()
  local seen = S.tuneSeen
  if seen and not S.tune139Said and seen.healthScale ~= nil then
    S.tune139Said = true
    log(string.format("Mod Settings, tuning (t139): BT's health x %.2f (the hull takes %.0f %% of a hit), BT's armor x %.2f, Burst Core charge x %.2f",
      P.healthScale, 100.0 / P.healthScale, P.armorScale, P.coreScale))
  end
end

P.fistCommands = true
FPC.fist.cmd = {
  burst = 7.5, burstHigh = 6.0, burstRing = 6, burstPush = 350.0, finisherGap = 1.2,
  uppercut = { reach = 4.5, high = 6.0, push = 700.0, lift = 0.3 },
  kick = { reach = 4.5, high = 6.0, push = 600.0, lift = 1.0 },
  stomps = { reach = 4.0, high = 3.5, push = 250.0, lift = 1.0, dust = true },
  sweep_r = { reach = 3.5, high = 3.0, push = 500.0, lift = 1.0, dust = true },
  sweep_l = { reach = 3.5, high = 3.0, push = 500.0, lift = 1.0, dust = true },
  leap = { reach = 6.5, high = 4.0, push = 450.0, lift = 1.0, dust = true },
  toss = { look = 7.0, cone = 55.0, hang = 1.0, throw = 800.0, landAfter = 1.1, landAhead = 9.0, land = 3.5, landPush = 300.0 },
  lines = 10 }
FPC.fist.fpNative.uppercut, FPC.fist.fpNative.kick, FPC.fist.fpNative.stomps = 13.0, 14.0, 15.0
FPC.fist.fpNative.sweep_r, FPC.fist.fpNative.sweep_l, FPC.fist.fpNative.leap, FPC.fist.fpNative.toss = 16.0, 17.0, 18.0, 19.0
for _, k in ipairs({ "uppercut", "kick", "stomps", "sweep_r", "sweep_l", "leap", "toss" }) do
  FPC.fist.tpClips[k] = PUNCH_CLIP.fist.clips[k]
  local C = PUNCH_CLIP.fist[k]
  if C and (C.fade or 0.0) < 0.1 then C.fade = 0.2 end
end
FPC.fist.stagger.boss.uppercut, FPC.fist.stagger.boss.kick, FPC.fist.stagger.boss.stomps = 0.5, 0.4, 0.3
FPC.fist.stagger.boss.sweep_r, FPC.fist.stagger.boss.sweep_l, FPC.fist.stagger.boss.leap, FPC.fist.stagger.boss.toss = 0.3, 0.3, 0.4, 0.5
FPC.fist.stagger.boss.electric = 0.2

function FPF.cmdWorld(rx, ay)
  local r = math.rad(PS.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  return PS.x + fy * rx + fx * ay, PS.y - fx * rx + fy * ay
end

function FPF.fistCmdStart(kind, by)
  local K = FPC.fist
  local C = PUNCH_CLIP.fist[kind]
  if not C then return nil end
  PS.yaw = S.yaw
  local M = { t = 0.0, dash = false, hit = {}, done = false, sent = 0, attacks = 0, lunge = 0.0, x0 = PS.x, y0 = PS.y, clip = C,
    fistKind = kind, by = by, native = true, met = 0, cars = 0, cmd = true, hitDone = {}, yaw0 = PS.yaw }
  M.fp = C.time
  M.from, M.to = 1.0e9, 1.0e9
  local r = math.rad(PS.yaw)
  PS.lunge = { x = -math.sin(r), y = math.cos(r), track = C, punch = M, scale = 1.0, last = 0.0, t = 0.0, time = C.time + 0.5 }
  M.lunge = FPF.trackAt(C, C.time)
  PS.punch, PS.punches, PS.sprintOn, PS.punchClip = M, PS.punches + 1, false, K.tpClips[kind]
  PS.fistBlows = (PS.fistBlows or 0) + 1
  PS.jab = nil
  local B = PS.fistGuard
  if B and B.on then B.on, B.idle = false, 0.0 end
  FPF.punchSound("swing")
  if kind == "leap" or kind == "kick" then pcall(FPF.dashSound) end
  PS.cmdLines = (PS.cmdLines or 0) + 1
  if PS.cmdLines <= K.cmd.lines then
    log(string.format("FIST COMMAND %s (%s): BT's own clip, %.2f s; hits at %s s; Titanfall carries BT %.1f m%s", kind, tostring(by), C.time,
      table.concat((function() local o = {} for _, h in ipairs(C.hits) do o[#o + 1] = string.format("%.2f", h.t) end return o end)(), " / "),
      M.lunge, (math.abs(C.yaw[#C.yaw] or 0.0) > 1.0 or math.abs(C.yaw[math.floor(#C.yaw / 2)] or 0.0) > 1.0) and " and turns it" or ""))
  end
  return M
end

function FPF.cmdYawAt(C, t)
  local n = #C.yaw
  if n == 0 then return 0.0 end
  local i = clamp(t * C.fps, 0.0, n - 1)
  local a = math.floor(i)
  local u = i - a
  local b = math.min(a + 2, n)
  return C.yaw[a + 1] + (C.yaw[b] - C.yaw[a + 1]) * u
end

FPF.stepYaw139 = FPF.stepYaw
function FPF.stepYaw(dt)
  local M = PS.punch
  if M and M.cmd and PS.mode == "pilot" then
    PS.yaw = wrap180(M.yaw0 + FPF.cmdYawAt(M.clip, M.t))
    return PS.yaw
  end
  return FPF.stepYaw139(dt)
end

function FPF.cmdArea(M, h)
  local K = FPC.fist
  local N = K.cmd[M.fistKind]
  local x, y = FPF.cmdWorld(h.x, h.y)
  local rec = FPF.gunRecord(FPF.coreOn() and K.records.core or K.records.heavy)
  local n, cars = 0, 0
  if N.dust and P.fxOn then FPF.fxAt(FPF.fxPath("punch"), x, y, PS.z + 0.1, PS.yaw, 0.0) end
  for _, T in ipairs(FPF.fistRound(x, y, PS.z, N.reach, N.high)) do
    if not M.hit[T.key] then
      M.hit[T.key] = true
      if T.kind == "vehicle" then
        cars = cars + 1
        FPF.wreck(T.ent, FPC.wreck.punch * 0.6)
      else
        n = n + 1
        local ux, uy = T.x - PS.x, T.y - PS.y
        local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
        ux, uy = ux / d, uy / d
        FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux, uy, 0.0)
        FPF.attack(rec, T.x, T.y, T.z + 0.5)
        FPF.fistStagger(T.ent, M.fistKind)
        local worth = nil
        pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
        if worth ~= "a boss" then FPF.ragdoll(T.ent, T.x - ux * 0.5, T.y - uy * 0.5, T.z + 0.6, ux * N.lift, uy * N.lift, N.push) end
        if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), T.x, T.y, T.z + 1.5, PS.yaw, 0.0) end
        if FPF.coreOn() then FPF.fistBlast(T.x, T.y, T.z, M.hit, M.fistKind) end
      end
    end
  end
  M.met, M.cars = M.met + n, M.cars + cars
  if n > 0 then
    FPF.punchSound("hit")
    FPF.stim("Explosion", FPC.stims.punch, 0.2)
    pcall(FPF.fistLeech, "blow", n)
  end
  if PS.cmdLines <= K.cmd.lines + 6 then
    log(string.format("FIST COMMAND %s: its hit at %.2f s round (%.1f, %.1f) - %.1f m of BT right, %.1f ahead - %d people, %d vehicles within %.1f m",
      M.fistKind, M.t, x, y, h.x, h.y, n, cars, N.reach))
  end
end

function FPF.tossGrab(M)
  local K = FPC.fist.cmd.toss
  PS.npcsAt = -10
  refreshNpcs()
  local T = nil
  for _, X in ipairs(FPF.punchTargets(K.look, K.cone)) do
    if X.kind == "person" then T = X break end
  end
  if not T then
    if PS.cmdLines <= FPC.fist.cmd.lines + 6 then log("GRAB AND TOSS: nobody within " .. K.look .. " m in front - the hand closes on nothing") end
    return
  end
  local worth = nil
  pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
  local rec = FPF.gunRecord(FPF.coreOn() and FPC.fist.records.core or FPC.fist.records.heavy)
  if worth == "a boss" or (T.r or 0.0) > 0.0 then
    M.hit[T.key] = true
    FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, T.dx, T.dy, 0.0)
    FPF.attack(rec, T.x, T.y, T.z + 0.5)
    FPF.fistStagger(T.ent, "toss")
    FPF.punchSound("hit")
    log("GRAB AND TOSS: " .. ((worth == "a boss") and "a boss-class one" or "a big one") .. " cannot be taken - a shove instead")
    return
  end
  M.carry = { ent = T.ent, key = T.key }
  M.hit[T.key] = true
  pcall(function() if not OP77.statusObserved(T.ent, FPC.fist.stagger.stun) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](T.ent, TweakDBID.new(FPC.fist.stagger.stun)) end end)
  local name = "?"
  pcall(function() name = TDBID.ToStringDEBUG(T.ent:GetRecordID()) end)
  log(string.format("GRAB AND TOSS: %s taken %.1f m in front - carried in the right hand", tostring(name), T.dist))
end

function FPF.tossHand(M)
  local C = M.clip
  local n = #C.hand
  local i = clamp(math.floor(M.t * C.fps + 0.5), 0, n - 1)
  local p = C.hand[i + 1]
  local x, y = FPF.cmdWorld(p[1], p[2])
  return x, y, PS.z + p[3]
end

function FPF.tossCarry(M)
  local Cr = M.carry
  if not Cr or Cr.thrown or not IsDefined(Cr.ent) then return end
  local x, y, z = FPF.tossHand(M)
  pcall(function()
    Game.GetTeleportationFacility():Teleport(Cr.ent, Vector4.new(x, y, z - FPC.fist.cmd.toss.hang, 1.0), EulerAngles.new(0, 0, PS.yaw))
  end)
end

function FPF.tossRelease(M)
  local Cr = M.carry
  if not Cr or Cr.thrown then return end
  Cr.thrown = true
  local K = FPC.fist.cmd.toss
  if not IsDefined(Cr.ent) then return end
  local x, y, z = FPF.tossHand(M)
  local r = math.rad(S.yaw)
  local ux, uy = -math.sin(r), math.cos(r)
  local rec = FPF.gunRecord(FPF.coreOn() and FPC.fist.records.core or FPC.fist.records.heavy)
  FPF.hit(Cr.ent, rec, x, y, z, ux, uy, 0.0)
  FPF.fistStagger(Cr.ent, "toss")
  FPF.ragdoll(Cr.ent, x, y, z - K.hang + 0.6, ux, uy, K.throw)
  FPF.punchSound("hit")
  PS.tossLand = { at = S.clock + K.landAfter, x = x + ux * K.landAhead, y = y + uy * K.landAhead, z = PS.z, skip = Cr.key }
  log(string.format("GRAB AND TOSS: thrown where the view points (%.0f deg) - it lands about %.0f m on", S.yaw, K.landAhead))
end

function FPF.tossLandFrame()
  local L = PS.tossLand
  if not L or S.clock < L.at then return end
  PS.tossLand = nil
  local K = FPC.fist.cmd.toss
  local gz = groundZ(L.x, L.y, L.z + 3.0)
  if gz and math.abs(gz - L.z) < 6.0 then L.z = gz end
  if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), L.x, L.y, L.z + 0.1, PS.yaw, 0.0) end
  local rec = FPF.gunRecord(FPC.fist.records.blast)
  local n = 0
  for _, T in ipairs(FPF.fistRound(L.x, L.y, L.z, K.land, 4.0)) do
    if T.key ~= L.skip and T.kind ~= "vehicle" then
      n = n + 1
      local ux, uy = T.x - L.x, T.y - L.y
      local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux / d, uy / d, 0.0)
      FPF.fistStagger(T.ent, "toss")
      FPF.ragdoll(T.ent, T.x, T.y, T.z + 0.6, ux / d, uy / d, K.landPush)
    end
  end
  log(string.format("GRAB AND TOSS: the thrown one lands - %d people within %.1f m knocked down", n, K.land))
end

function FPF.fistCmdFrame(M)
  local C = M.clip
  for i, h in ipairs(C.hits) do
    if not M.hitDone[i] and M.t >= h.t then
      M.hitDone[i] = true
      if M.fistKind == "toss" then
        if i == 1 then FPF.tossGrab(M) else FPF.tossRelease(M) end
      else
        FPF.cmdArea(M, h)
      end
    end
  end
  if M.fistKind == "toss" then FPF.tossCarry(M) end
end

function FPF.fistBurst(M)
  local K = FPC.fist
  local Kc = K.cmd
  local x, y, z = M.burstX, M.burstY, PS.z
  if not x then x, y = FPF.cmdWorld(M.clip.fist[1], M.clip.fist[2] + 2.0) end
  if P.fxOn then
    local inst = FPF.fxAt(K.fx.big, x, y, z + 1.0, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + K.fx.life } end
    for i = 1, Kc.burstRing do
      local a = (i - 0.5) / Kc.burstRing * 2.0 * math.pi
      local px, py = x + math.cos(a) * Kc.burst * 0.6, y + math.sin(a) * Kc.burst * 0.6
      local m = FPF.fxAt(K.fx.mid, px, py, z + 0.5, nil, nil)
      if m then PS.fxLive[#PS.fxLive + 1] = { inst = m, till = S.clock + K.fx.life } end
    end
  end
  FPF.swordSound(FPC.sword.sounds.waveFire, math.max(FPF.viewVolume(), 0.6))
  local rec = FPF.gunRecord(K.records.blast)
  local n, cars = 0, 0
  for _, T in ipairs(FPF.fistRound(x, y, z, Kc.burst, Kc.burstHigh)) do
    if T.kind == "vehicle" then
      cars = cars + 1
      FPF.wreck(T.ent, FPC.wreck.punch * 0.5)
    else
      n = n + 1
      local ux, uy = T.x - x, T.y - y
      local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
      ux, uy = ux / d, uy / d
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux, uy, 0.0)
      FPF.attack(rec, T.x, T.y, T.z + 0.5)
      FPF.fistStagger(T.ent, "electric")
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
      if worth ~= "a boss" then FPF.ragdoll(T.ent, T.x, T.y, T.z + 0.6, ux, uy, Kc.burstPush) end
    end
  end
  FPF.stim("Explosion", FPC.stims.punch * 2.0, 0.2)
  log(string.format("ELECTRIC STRAIGHT: the burst at (%.1f, %.1f) - %d people knocked down and electrocuted, %d vehicles within %.1f m", x, y, n, cars, Kc.burst))
end

FPF.fistStagger139 = FPF.fistStagger
function FPF.fistStagger(who, kind, level)
  if kind ~= "electric" then return FPF.fistStagger139(who, kind, level) end
  local worth = nil
  pcall(function() local _, w = FPF.coreWorth(who); worth = w end)
  if worth == "a boss" then return FPF.fistStagger139(who, kind, level) end
  local K = FPC.fist.stagger
  local done = 0
  for _, eff in ipairs({ K.down, K.shock }) do
    if pcall(function() if not OP77.statusObserved(who, eff) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](who, TweakDBID.new(eff)) end end) then done = done + 1 end
  end
  return done
end

FPF.punchHit139 = FPF.punchHit
function FPF.punchHit(ent, M, last)
  FPF.punchHit139(ent, M, last)
  if M and M.electric and M.done and not M.burstDone then
    M.burstDone = true
    guard("ELECTRIC STRAIGHT's burst", FPF.fistBurst, M)
  end
end

function FPF.electricStart(by)
  local K = FPC.fist
  local side = PS.lastJabSide or "r"
  local kind = (side == "r") and "finisher_l" or "finisher"
  PS.npcsAt = -10
  refreshNpcs()
  local T = FPF.punchTargets(K.native.finisher.look, K.blowAngle)[1]
  local M = FPF.fistNativeStart(kind, nil, by)
  if not M then return nil end
  M.electric = true
  if T then M.burstX, M.burstY = T.x, T.y end
  local C = PS.fistCombo
  if C then C.done = true end
  PS.electrics = (PS.electrics or 0) + 1
  if PS.electrics <= K.cmd.lines then
    log(string.format("ELECTRIC STRAIGHT (%s): three jabs and the melee key %.2f s after the last - the %s fist's high punch%s", tostring(by),
      S.clock - (PS.jabLastAt or S.clock), (kind == "finisher") and "right" or "left", T and string.format(", at a %s %.1f m away", T.kind, T.dist) or ""))
  end
  return M
end

FPF.jabStart140 = FPF.jabStart
function FPF.jabStart(by)
  local J = FPF.jabStart140(by)
  if J then PS.lastJabSide = J.side end
  return J
end

FPF.gunFrame139 = gunFrame
gunFrame = function(dt, ent, firing)
  if PS.weapon == "fist" and PS.reloadKey and P.fistCommands and S.driving and S.pilot then PS.tossAsk = S.clock end
  return FPF.gunFrame139(dt, ent, firing)
end

FPF.punch139 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" or not P.fistCommands or not (S.driving and S.pilot) or FPF.flightImmune() then
    PS.tossAsk, PS.kickWas = nil, PS.fistFire == true
    return FPF.punch139(dt, ent, key)
  end
  local B = PS.fistGuard
  local guarded = B ~= nil and B.on
  local free = not PS.punch and not PS.pound and not PS.fistCharge and not PS.fistPress and not (PS.vortex and PS.vortex.on) and not PS.exec
  local by = PS.punchBy or "the melee key"
  local C = PS.fistCombo
  local J = PS.jab
  local chained = C and C.n >= 3 and not C.done and S.clock - (PS.jabLastAt or -100.0) <= FPC.fist.cmd.finisherGap
  if key and free and chained and not guarded then
    if J and not J.done then
      PS.electricAsk = S.clock
    else
      FPF.electricStart(by)
    end
    key = false
  elseif key and free and guarded then
    local kind = "uppercut"
    local mx = S.moveX + S.kr - S.kl
    local my = S.moveY + S.kf - S.kb
    if my < -0.5 then kind = "stomps" elseif mx > 0.5 then kind = "sweep_r" elseif mx < -0.5 then kind = "sweep_l" end
    FPF.fistCmdStart(kind, "the guard and the melee key")
    key = false
  elseif key and free and PS.sprintOn then
    FPF.fistCmdStart("leap", "sprinting, the melee key")
    key = false
  end
  if PS.electricAsk and (not PS.jab or PS.jab.done) then
    PS.electricAsk = nil
    if not PS.punch and C and not C.done then FPF.electricStart(by) end
  end
  local fire = PS.fistFire == true
  if fire and not PS.kickWas and guarded and free and not PS.punch then FPF.fistCmdStart("kick", "the guard and the fire key") end
  PS.kickWas = fire
  if PS.tossAsk then
    if not PS.punch and free then FPF.fistCmdStart("toss", "the reload key") end
    PS.tossAsk = nil
  end
  local r = FPF.punch139(dt, ent, key)
  local M = PS.punch
  if M and M.cmd then guard("the fists' command", FPF.fistCmdFrame, M) end
  if PS.tossLand then guard("GRAB AND TOSS's landing", FPF.tossLandFrame) end
  return r
end

FPF.drive140 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive140(dt, steps, sprinting)
  if PS.weapon ~= "fist" or not PF.shown or not PF.ent or not IsDefined(PF.ent) or not FP.native then return end
  local M = PS.punch
  if not M or not M.cmd then return end
  local F = FP.native[M.fistKind]
  local c = FPC.fist.fpNative[M.fistKind]
  if not F or not c then return end
  FPF.var("fp_melee_clip", c)
  FPF.var("fp_melee", 1.0)
  FPF.var("fp_time_melee", math.min(M.t, F.time))
end

P.fistBinds141, P.grab141, P.cmdSounds, P.meleeDevices, P.aiFistCmds, P.stillSoft = true, true, true, true, true, true

FPC.fist.cmd.grab = { look = 9.0, cone = 50.0, hand = 3.0, high = 3.5, scaleMost = 1.6, out = 0.35, mount = "hand_r", check = 0.15, lines = 10 }

FPC.fist.cmdSounds = { uppercut = "bt7274_fist_uppercut", kick = "bt7274_fist_kick", stomps = "bt7274_fist_stomps",
  sweep_r = "bt7274_fist_sweep", sweep_l = "bt7274_fist_sweep", leap = "bt7274_fist_leap", toss = "bt7274_fist_grab",
  throw = "bt7274_fist_throw", throwLead = 0.38, finisher = "bt7274_fist_high", finisher_l = "bt7274_fist_high",
  spin = "bt7274_fist_spin", shoulder = "bt7274_fist_shoulder" }
for k, name in pairs(FPC.fist.cmdSounds) do
  if type(name) == "string" then FPC.side.rows[name] = { k = 2, at = "body" } end
end

FPC.dev.melee = { jab = 34.0, punch = 50.0, blow = 100.0, cmd = 100.0, slash = 50.0, area = 60.0, high = 6.5, lines = 6 }

FPC.fist.ai.heavyGap = 7.0
FPC.fistAI.charge.gap, FPC.fistAI.charge.chance, FPC.fistAI.charge.foes = 15.0, 0.12, 3
FPC.fistAI.cmd = { every = { 5.0, 8.0 }, retry = 1.0, electric = 0.45, front = 40.0, uppercut = 8.0, kick = 9.0, toss = 6.5, side = 5.0,
  back = 6.0, crowd = 2, crowdReach = 6.5, tossGap = 14.0, lines = 10 }

FPC.still141 = { first = { "bt7274_cockpit" }, next = 0.5, frozen = 0.25, lines = 12 }

P.aiSentryGuns = false
FPC.fistAI.cmd.shoulder, FPC.fistAI.cmd.shoulderCone, FPC.fistAI.cmd.shoulderGap = { 9.0, 16.0 }, 25.0, 16.0

FPC.aiTactics.flight.foes, FPC.aiTactics.flight.chance, FPC.aiTactics.flight.boss = 5, 0.15, false

FPF.fistFrame140 = FPF.fistFrame
function FPF.fistFrame(dt, ent)
  local due = FPF.fistFrame140(dt, ent)
  if due == "heavy" and P.fistBinds141 and P.fistCommands and S.driving and S.pilot and PS.weapon == "fist" and not PS.punch then
    FPF.fistCmdStart("uppercut", "the melee key")
    return nil
  end
  return due
end

FPF.punch140 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" or not P.fistCommands or not P.fistBinds141 then return FPF.punch140(dt, ent, key) end
  if not (S.driving and S.pilot) or FPF.flightImmune() then
    PS.tossAsk, PS.kickWas = nil, PS.fistFire == true
    local r = FPF.punch139(dt, ent, key)
    FPF.cmdFrames141()
    return r
  end
  local B = PS.fistGuard
  local guarded = B ~= nil and B.on
  local free = not PS.punch and not PS.pound and not PS.fistCharge and not PS.fistPress and not (PS.vortex and PS.vortex.on) and not PS.exec
  local by = PS.punchBy or "the melee key"
  local C = PS.fistCombo
  local J = PS.jab
  local chained = C and C.n >= 3 and not C.done and S.clock - (PS.jabLastAt or -100.0) <= FPC.fist.cmd.finisherGap
  if key and free and chained and not guarded then
    if J and not J.done then
      PS.electricAsk = S.clock
    else
      FPF.electricStart(by)
    end
    key = false
  elseif key and free and guarded then
    local mx = S.moveX + S.kr - S.kl
    local my = S.moveY + S.kf - S.kb
    local kind = nil
    if my < -0.5 then kind = "stomps" elseif mx > 0.5 then kind = "sweep_r" elseif mx < -0.5 then kind = "sweep_l" end
    if kind then
      FPF.fistCmdStart(kind, "the guard and the melee key")
      key = false
    end
  elseif key and free and PS.sprintOn then
    FPF.fistCmdStart("leap", "sprinting, the melee key")
    key = false
  end
  if PS.electricAsk and (not PS.jab or PS.jab.done) then
    PS.electricAsk = nil
    if not PS.punch and C and not C.done then FPF.electricStart(by) end
  end
  local fire = PS.fistFire == true
  if fire and not PS.kickWas and guarded and free and not PS.punch then FPF.fistCmdStart("kick", "the guard and the fire key") end
  PS.kickWas = fire
  if PS.tossAsk then
    if not PS.punch and free then FPF.grabStart("the reload key") end
    PS.tossAsk = nil
  end
  local held = PS.meleeHeld
  local plain = key and free and not guarded
  if plain then PS.meleeHeld = true end
  local ok, r = pcall(FPF.punch139, dt, ent, key)
  if plain then PS.meleeHeld = held end
  if not ok then error(r, 0) end
  FPF.cmdFrames141()
  return r
end

function FPF.cmdFrames141()
  local M = PS.punch
  if M and M.cmd then
    guard("the fists' command", FPF.fistCmdFrame, M)
    local K = FPC.fist.cmdSounds
    local C = M.clip
    if M.fistKind == "toss" and M.carry and not M.carry.thrown and not M.throwSaid and C.release and M.t >= C.release - K.throwLead then
      M.throwSaid = true
      FPF.cmdSound(K.throw)
    end
  end
  if PS.tossLand then guard("GRAB AND TOSS's landing", FPF.tossLandFrame) end
end

function FPF.cmdSound(name)
  if not P.cmdSounds or not name then return false end
  local ok, played = pcall(FPF.ownSound, name, FPF.viewVolume())
  return ok and played
end

FPF.fistCmdStart140 = FPF.fistCmdStart
function FPF.fistCmdStart(kind, by)
  local M
  if not S.driving and PS.buddy and type(PS.buddy.yaw) == "number" then
    M = FPF.aiView(FPF.fistCmdStart140, kind, by)
  else
    M = FPF.fistCmdStart140(kind, by)
  end
  if M then FPF.cmdSound(FPC.fist.cmdSounds[kind]) end
  return M
end

FPF.fistNativeStart140 = FPF.fistNativeStart
function FPF.fistNativeStart(kind, level, by)
  local M = FPF.fistNativeStart140(kind, level, by)
  if M then FPF.cmdSound(FPC.fist.cmdSounds[kind]) end
  return M
end

function FPF.grabHand(C, s)
  local a, sd = FPF.trackAt(C, C.grab)
  local n = #C.hand
  local i = clamp(math.floor(C.grab * C.fps + 0.5), 0, n - 1)
  local h = C.hand[i + 1]
  local yw = math.rad(FPF.cmdYawAt(C, C.grab))
  return sd * s + h[1] * math.cos(yw) - h[2] * math.sin(yw), a * s + h[1] * math.sin(yw) + h[2] * math.cos(yw), h[3]
end

function FPF.grabTarget(look, cone)
  for _, X in ipairs(FPF.punchTargets(look, cone)) do
    if X.kind == "person" and (X.r or 0.0) <= 0.0 then
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(X.ent); worth = w end)
      if worth ~= "a boss" then return X end
    end
  end
  return nil
end

function FPF.grabStart(by)
  local K = FPC.fist.cmd.grab
  local C = PUNCH_CLIP.fist.toss
  PS.npcsAt = -10
  refreshNpcs()
  local T = FPF.grabTarget(K.look, K.cone)
  local M = FPF.fistCmdStart("toss", by)
  if not M then return nil end
  M.grab = { asked = S.clock, scale = 1.0 }
  if T and P.grab141 and C.grab and C.hand then
    local dx, dy = T.x - PS.x, T.y - PS.y
    local d = math.sqrt(dx * dx + dy * dy)
    local _, h0 = FPF.grabHand(C, 0.0)
    local _, h1 = FPF.grabHand(C, 1.0)
    local s = clamp((d - h0) / math.max(h1 - h0, 0.1), 0.0, K.scaleMost)
    local hx, hy = FPF.grabHand(C, s)
    local yaw = wrap180(math.deg(math.atan2(-dx, dy)) + math.deg(math.atan2(hx, hy)))
    PS.yaw, M.yaw0 = yaw, yaw
    local r = math.rad(yaw)
    if PS.lunge and PS.lunge.punch == M then
      PS.lunge.x, PS.lunge.y, PS.lunge.scale = -math.sin(r), math.cos(r), s
    end
    if not S.driving and PS.buddy then PS.buddy.yaw = yaw end
    M.grab.target, M.grab.scale = T, s
  end
  PS.grabLines = (PS.grabLines or 0) + 1
  if PS.grabLines <= K.lines then
    local name = "?"
    if T then pcall(function() name = TDBID.ToStringDEBUG(T.ent:GetRecordID()) end) end
    log(T and string.format("GRAB (%s): reaching for %s %.1f m away - BT turned to it, Titanfall's track x %.2f", tostring(by), tostring(name), T.dist, M.grab.scale)
      or string.format("GRAB (%s): nobody to take within %.0f m / %.0f deg - the reach goes straight on", tostring(by), K.look, K.cone))
  end
  return M
end

function FPF.tossGrab(M)
  local K = FPC.fist.cmd.grab
  PS.npcsAt = -10
  refreshNpcs()
  local hx, hy = FPF.tossHand(M)
  local T, best = nil, K.hand
  for _, X in ipairs(FPF.fistRound(hx, hy, PS.z, K.hand, K.high)) do
    if X.kind == "person" then
      local d = math.sqrt((X.x - hx) ^ 2 + (X.y - hy) ^ 2)
      if d <= best then T, best = X, d end
    end
  end
  if not T then
    FPF.grabMiss(M, string.format("nobody within %.1f m of the hand", K.hand))
    return
  end
  local worth = nil
  pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
  local rec = FPF.gunRecord(FPF.coreOn() and FPC.fist.records.core or FPC.fist.records.heavy)
  if worth == "a boss" or (T.r or 0.0) > 0.0 then
    M.hit[T.key] = true
    FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, T.dx or 0.0, T.dy or 1.0, 0.0)
    FPF.attack(rec, T.x, T.y, T.z + 0.5)
    FPF.fistStagger(T.ent, "toss")
    FPF.punchSound("hit")
    FPF.grabMiss(M, ((worth == "a boss") and "a boss-class one" or "a big one") .. " cannot be taken - a shove")
    return
  end
  M.carry = { ent = T.ent, key = T.key, at = S.clock }
  M.hit[T.key] = true
  if PS.lunge and PS.lunge.punch == M then PS.lunge.scale = 1.0 end
  FPF.carryStart(M, best)
end

function FPF.grabMiss(M, why)
  local K = FPC.fist.cmd.grab
  M.hold = M.t
  M.fp = M.t + K.out
  M.cutEnd, M.cutFade = M.fp, K.out
  if PS.lunge and PS.lunge.punch == M then PS.lunge = nil end
  PS.grabMisses = (PS.grabMisses or 0) + 1
  if PS.grabMisses <= K.lines then log("GRAB: " .. why .. " - the reach ends there, no throw") end
end

function FPF.carryStart(M, d)
  local K = FPC.fist.cmd.grab
  local Cr = M.carry
  local ent = Cr.ent
  pcall(function() if not OP77.statusObserved(ent, FPC.fist.stagger.stun) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(FPC.fist.stagger.stun)) end end)
  Cr.disabled = pcall(function() ent:MountingStartDisableComponents() end)
  local ok, err = pcall(function()
    local info = MountingInfo.new()
    info.childId = ent:GetEntityID()
    info.parentId = PS.ent:GetEntityID()
    local slot = MountingSlotId.new()
    slot.id = CName.new(K.mount)
    info.slotId = slot
    local data = MountEventData.new()
    data.isInstant = true
    data.ignoreHLS = true
    local req = MountingRequest.new()
    req.lowLevelMountingInfo = info
    req.preservePositionAfterMounting = false
    req.mountData = data
    Game.GetMountingFacility():Mount(req)
  end)
  Cr.mountAsked, Cr.checkAt = ok, S.clock + K.check
  local name = "?"
  pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
  Cr.name = name
  log(string.format("GRAB AND TOSS: %s taken %.1f m from the hand - %s%s", tostring(name), d or 0.0,
    ok and "the game is asked to hang it on BT's right hand (mounting)" or ("its mounting could NOT be asked (" .. tostring(err) .. ")"),
    Cr.disabled and "; its collision off (the game's grappled)" or ""))
end

function FPF.tossCarry(M)
  local Cr = M.carry
  if not Cr or Cr.thrown or not IsDefined(Cr.ent) then return end
  local x, y, z = FPF.tossHand(M)
  local hang = FPC.fist.cmd.toss.hang
  local ent = Cr.ent
  if Cr.mountAsked and Cr.checkAt and S.clock < Cr.checkAt then return end
  if Cr.checkAt and S.clock >= Cr.checkAt then
    Cr.checkAt = nil
    local mounted = false
    pcall(function() mounted = Game.GetMountingFacility():IsMountedToAnything(ent:GetEntityID()) == true end)
    local off = -1.0
    pcall(function()
      local p = ent:GetWorldPosition()
      off = math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - (z - hang)) ^ 2)
    end)
    Cr.mounted = mounted and off >= 0.0 and off < 2.5
    log(string.format("GRAB AND TOSS: %.2f s later the game says it is %s; it is %.1f m from the hand%s", FPC.fist.cmd.grab.check,
      mounted and "mounted" or "NOT mounted", off, Cr.mounted and " - it stays on the hand" or " - moved to the hand by the game's teleport order every frame"))
  end
  if Cr.mounted then return end
  pcall(function()
    local cmd = NewObject("handle:AITeleportCommand")
    cmd.position = Vector4.new(x, y, z - hang, 1.0)
    cmd.rotation = PS.yaw
    cmd.doNavTest = false
    ent:GetAIControllerComponent():SendCommand(cmd)
  end)
  pcall(function() Game.GetTeleportationFacility():Teleport(ent, Vector4.new(x, y, z - hang, 1.0), EulerAngles.new(0, 0, PS.yaw)) end)
  if not Cr.followSaid and S.clock - Cr.at >= 0.6 then
    Cr.followSaid = true
    pcall(function()
      local p = ent:GetWorldPosition()
      log(string.format("GRAB AND TOSS: 0.6 s into the carry it is %.1f m from the hand (the teleport order every frame)",
        math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - (z - hang)) ^ 2)))
    end)
  end
end

function FPF.tossRelease(M)
  local Cr = M.carry
  if not Cr or Cr.thrown then return end
  Cr.thrown = true
  local K = FPC.fist.cmd.toss
  if not IsDefined(Cr.ent) then return end
  local ent = Cr.ent
  if Cr.mountAsked then
    pcall(function()
      local info = MountingInfo.new()
      info.childId = ent:GetEntityID()
      info.parentId = PS.ent:GetEntityID()
      local data = MountEventData.new()
      data.isInstant = true
      local req = UnmountingRequest.new()
      req.lowLevelMountingInfo = info
      req.mountData = data
      Game.GetMountingFacility():Unmount(req)
    end)
  end
  if Cr.disabled then pcall(function() ent:MountingEndEnableComponents() end) end
  pcall(function() StatusEffectHelper["StatusEffectHelper::RemoveStatusEffect;GameObjectTweakDBIDUint32"](ent, TweakDBID.new(FPC.fist.stagger.stun)) end)
  local hx, hy, hz = FPF.tossHand(M)
  local x, y, z = hx, hy, hz - K.hang
  local real = false
  pcall(function()
    local p = ent:GetWorldPosition()
    x, y, z, real = p.x, p.y, p.z, true
  end)
  local yaw = S.yaw
  if not S.driving then
    local Bd = PS.buddy
    local T = Bd and Bd.target
    yaw = (T and T.x) and math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)) or PS.yaw
  end
  local r = math.rad(yaw)
  local ux, uy = -math.sin(r), math.cos(r)
  local rec = FPF.gunRecord(FPF.coreOn() and FPC.fist.records.core or FPC.fist.records.heavy)
  FPF.hit(ent, rec, x, y, z + 1.0, ux, uy, 0.0)
  FPF.fistStagger(ent, "toss")
  FPF.ragdoll(ent, x, y, z + 0.6, ux, uy, K.throw)
  FPF.punchSound("hit")
  PS.tossLand = { at = S.clock + K.landAfter, x = x + ux * K.landAhead, y = y + uy * K.landAhead, z = PS.z, skip = Cr.key }
  log(string.format("GRAB AND TOSS: thrown %s (%.0f deg) from %s, %.1f m from the hand - it lands about %.0f m on", S.driving and "where the view points" or "at its foe",
    yaw, real and "where it is" or "the hand", math.sqrt((x - hx) ^ 2 + (y - hy) ^ 2), K.landAhead))
end

FPF.stepYaw140 = FPF.stepYaw
function FPF.stepYaw(dt)
  local M = PS.punch
  if M and M.cmd and M.hold and PS.mode == "pilot" then
    PS.yaw = wrap180(M.yaw0 + FPF.cmdYawAt(M.clip, M.hold))
    return PS.yaw
  end
  return FPF.stepYaw140(dt)
end

FPF.drive141 = FPF.drive
function FPF.drive(dt, steps, sprinting)
  FPF.drive141(dt, steps, sprinting)
  if PS.weapon ~= "fist" or not PF.shown or not PF.ent or not IsDefined(PF.ent) or not FP.native then return end
  local M = PS.punch
  if not M or not M.cmd or not M.hold then return end
  local F = FP.native[M.fistKind]
  if not F then return end
  FPF.var("fp_time_melee", math.min(M.hold, F.time))
  FPF.var("fp_melee", clamp(PS.punchW or 1.0, 0.0, 1.0))
end

FPF.aiSkills140 = FPF.aiSkills
function FPF.aiSkills(B, dt, T)
  FPF.aiSkills140(B, dt, T)
  if PS.weapon ~= "fist" or not P.aiFistCmds or not P.fistCommands or S.driving then return end
  local ok, err = pcall(FPF.aiFistCmd, B, T)
  if not ok then once("aifistcmd" .. tostring(err), "BT on its own: a command of the fists could NOT be picked (" .. tostring(err) .. ")") end
end

function FPF.aiFistCmd(B, T)
  local K = FPC.fistAI.cmd
  if not T or not T.ent or PS.punch or PS.pound or PS.fistCharge or PS.fistPress or (PS.jab and not PS.jab.done) or PS.spin
      or PS.dashT ~= nil or PS.jump or PS.exec or (PS.vortex and PS.vortex.on) or FPF.flightImmune() then return end
  local Ch = B.chase
  if Ch and Ch.mode == "back" then return end
  local Co = PS.fistCombo
  if Co and Co.n >= 3 and not Co.done and not Co.aiAsked and S.clock - (PS.jabLastAt or -100.0) <= FPC.fist.cmd.finisherGap then
    Co.aiAsked = true
    if math.random() < K.electric then
      local M = FPF.aiView(FPF.electricStart, "BT on its own")
      if M then
        FPF.aiCmdSaid("ELECTRIC STRAIGHT after three jabs")
        return
      end
    end
  end
  local yaw = (type(B.yaw) == "number") and B.yaw or PS.yaw
  local r = math.rad(yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local dx, dy = T.x - PS.x, T.y - PS.y
  local d = math.sqrt(dx * dx + dy * dy)
  local ang = math.deg(math.atan2(dx * fy - dy * fx, dx * fx + dy * fy))
  if P.fistShoulder and d >= K.shoulder[1] and d <= K.shoulder[2] and math.abs(ang) <= K.shoulderCone and S.clock >= (PS.aiShoulderAt or 0.0) then
    PS.aiShoulderAt = S.clock + 1.0
    local okS, can = pcall(function() return FPF.aiView(FPF.shoulderCan) end)
    if okS and can then
      PS.shoulderCharge = (PS.shoulderCharge or FPC.fist.native.shoulder.charges) - 1.0
      local M = FPF.aiView(FPF.fistNativeStart, "shoulder", nil, "BT on its own")
      if M then
        PS.aiShoulderAt = S.clock + K.shoulderGap
        FPF.aiCmdSaid(string.format("SHOULDER CHARGE (the C key) - its foe %.1f m ahead", d))
        return
      end
    end
  end
  if S.clock < (PS.aiCmdAt or 0.0) then return end
  local list, sum = {}, 0.0
  local function add(kind, w) list[#list + 1] = { kind = kind, w = w }; sum = sum + w end
  if math.abs(ang) <= K.front then
    if d <= K.uppercut then add("uppercut", 3.0) end
    if d <= K.kick then add("kick", 3.0) end
    if d <= K.toss and S.clock >= (PS.aiTossAt or 0.0) and FPF.aiView(FPF.grabTarget, K.toss + 1.0, K.front) then add("toss", 2.0) end
  elseif d <= K.side and math.abs(ang) <= 130.0 then
    add((ang > 0.0) and "sweep_r" or "sweep_l", 4.0)
  elseif d <= K.back and math.abs(ang) > 130.0 then
    add("stomps", 4.0)
  end
  if FPF.aiFoesNear(K.crowdReach) >= K.crowd then add("leap", 2.0) end
  if sum <= 0.0 then
    PS.aiCmdAt = S.clock + K.retry
    return
  end
  local pick, u = list[#list].kind, math.random() * sum
  for _, e in ipairs(list) do
    u = u - e.w
    if u <= 0.0 then pick = e.kind break end
  end
  local M
  if pick == "toss" then
    M = FPF.aiView(FPF.grabStart, "BT on its own")
    PS.aiTossAt = S.clock + K.tossGap
  else
    M = FPF.fistCmdStart(pick, "BT on its own")
  end
  PS.aiCmdAt = S.clock + K.every[1] + math.random() * (K.every[2] - K.every[1])
  if M then FPF.aiCmdSaid(string.format("%s - its foe %.1f m away, %+.0f deg", pick, d, ang)) end
end

function FPF.aiCmdSaid(what)
  PS.aiCmds = (PS.aiCmds or 0) + 1
  if PS.aiCmds <= FPC.fistAI.cmd.lines then log("BT on its own, the fists: a command - " .. what) end
end

FPF.aiDash140 = FPF.aiDash
function FPF.aiDash(B, dt, T)
  local M = PS.punch
  if S.driving or not (M and M.cmd) then return FPF.aiDash140(B, dt, T) end
  B.yaw = wrap180(M.yaw0 + FPF.cmdYawAt(M.clip, M.hold or M.t))
  return nil
end

FPF.buddyHeading140 = FPF.buddyHeading
function FPF.buddyHeading(B)
  local M = PS.punch
  if M and M.cmd and not S.driving then return nil end
  return FPF.buddyHeading140(B)
end

function FPF.meleeDevHit(D, rec, ux, uy, share, dist, by)
  FPF.devHit(D.ent, rec, D.x, D.y, D.z + (D.h or 1.4) * 0.5, ux, uy, 0.0, share, dist, by)
  PS.meleeDevs = (PS.meleeDevs or 0) + 1
  if PS.meleeDevs <= FPC.dev.melee.lines then
    log(string.format("A TURRET OR CAMERA met by %s: %s, %.1f m from BT - %.0f %% of its health", tostring(by), tostring(D.name), dist or 0.0, share))
  end
end

function FPF.meleeDevCone(range, angle, share, rec, by, hit)
  if not P.meleeDevices or not P.devices or not PS.devs then return 0 end
  local Bd = PS.buddy
  local yaw = (not S.driving and Bd and type(Bd.yaw) == "number") and Bd.yaw or S.yaw
  local r = math.rad(yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local n = 0
  for _, D in ipairs(PS.devs) do
    if not D.dead and IsDefined(D.ent) and not (hit and hit["dev" .. D.key]) then
      local dx, dy = D.x - PS.x, D.y - PS.y
      local d = math.sqrt(dx * dx + dy * dy)
      local rr = D.r or 0.7
      local wide = (d > 0.01) and math.deg(math.atan2(rr, d)) or 90.0
      local up = D.z - PS.z
      if d - rr <= range and up <= FPC.dev.melee.high and up + (D.h or 1.4) >= -0.5
          and (d < 1.5 + rr or (dx * fx + dy * fy) / d >= math.cos(math.rad(math.min(89.0, angle + wide)))) then
        if hit then hit["dev" .. D.key] = true end
        n = n + 1
        FPF.meleeDevHit(D, rec, dx / math.max(d, 0.01), dy / math.max(d, 0.01), share, d, by)
      end
    end
  end
  return n
end

function FPF.meleeDevAt(x, y, z, reach, high, share, rec, by, hit)
  if not P.meleeDevices or not P.devices or not PS.devs then return 0 end
  local n = 0
  for _, D in ipairs(PS.devs) do
    if not D.dead and IsDefined(D.ent) and not (hit and hit["dev" .. D.key]) then
      local dx, dy = D.x - x, D.y - y
      local d = math.sqrt(dx * dx + dy * dy)
      if d - (D.r or 0.7) <= reach and D.z <= z + high and D.z + (D.h or 1.4) >= z - 1.0 and D.z - PS.z <= FPC.dev.melee.high then
        if hit then hit["dev" .. D.key] = true end
        n = n + 1
        FPF.meleeDevHit(D, rec, dx / math.max(d, 0.01), dy / math.max(d, 0.01), share, math.sqrt((D.x - PS.x) ^ 2 + (D.y - PS.y) ^ 2), by)
      end
    end
  end
  return n
end

