      local comp = ent:FindComponentByName(name)
      comp:Toggle(on)
      if comp:IsEnabled() == on then done = done + 1 end
    end)
  end
  FPF.crumb("mesh", "cockpit " .. (on and "on" or "off"))
  return done
end

FPF.still140 = FPF.still
function FPF.still(clip, t, dt)
  if not P.stillSoft then return FPF.still140(clip, t, dt) end
  local W, K = PS.stillW, FPC.still
  if W.clip ~= clip then W.clip, W.t = clip, 0.0 end
  local rows = SCENE_HIP[clip]
  if not rows or #rows < 2 then return end
  local hip = slotWorld("hip")
  if not hip then return end
  local f = clamp(t / 0.1, 0.0, #rows - 1)
  local i = math.min(math.floor(f), #rows - 2)
  local want = rows[i + 1] + (rows[i + 2] - rows[i + 1]) * (f - i)
  local got = hip.z - PS.z
  if math.abs(got - want) > K.off then
    W.t = W.t + dt
    if W.t >= K.time and not W.said then
      W.said, W.n, W.since, W.kicked, W.stage = true, W.n + 1, S.clock, false, 0
      log(string.format("BT's skeleton STANDS STILL %.2f s into scene clip %d: its hip is %.2f m up where the clip has it %.2f m up - the game is asked again to animate it out of the picture%s",
        t, clip, got, want, P.awake and ", and BT is turned half a degree to and fro for a few frames" or ""))
      guard("animate always", FPF.animAll)
      PS.awake.kick = FPC.awake.kickFrames
    elseif W.said and (W.stage or 0) < 2 and not PF.shown and S.clock - W.since >= K.kick + (W.stage or 0) * FPC.still141.next then
      W.stage = (W.stage or 0) + 1
      W.kicked, W.kickAt, W.kicks = true, S.clock, (W.kicks or 0) + 1
      if W.stage == 1 then
        W.offList = FPC.still141.first
        local n = FPF.meshToggle141(W.offList, false)
        log(string.format("BT's skeleton still stands still %.1f s later: its cockpit (inside the shut hull) is switched off for a frame (%d) so that the game looks at it anew",
          S.clock - W.since, n))
      else
        W.offList = nil
        local n = FPF.body(false)
        log(string.format("BT's skeleton still stands still %.1f s later: its outside meshes are switched off for a frame (%d of %d) so that the game looks at it anew",
          S.clock - W.since, n, #FPC.body))
      end
    end
  else
    if W.said then
      log(string.format("BT's skeleton moves again (%.2f s into scene clip %d; it stood still for %.1f s%s)", t, clip, S.clock - (W.since or S.clock),
        ((W.stage or 0) == 0) and "" or (((W.stage or 0) == 1) and ", after its cockpit was switched off for a frame" or ", after its outside meshes were switched off for a frame")))
    end
    W.t, W.said, W.kicked, W.stage = 0.0, false, false, 0
  end
end

function FPF.cockpitBlink141(why)
  if PF.shown or not PS.ent or not IsDefined(PS.ent) then return false end
  local W = PS.stillW
  if not W or W.kickAt then return false end
  W.offList = FPC.still141.first
  FPF.meshToggle141(W.offList, false)
  W.kickAt = S.clock
  PS.blinks141 = (PS.blinks141 or 0) + 1
  if PS.blinks141 <= FPC.still141.lines then log("BT's cockpit (inside the shut hull) is switched off for a frame so that the game looks at BT anew: " .. why) end
  return true
end

function FPF.frozenWatch141(dt)
  if not PS.ent or PF.shown or not (PS.act or PS.scene) then
    PS.frozen141 = nil
    return
  end
  local h = slotWorld("hand_l")
  if not h then return end
  local F = PS.frozen141
  if not F then
    F = { t = 0.0 }
    PS.frozen141 = F
  elseif F.x then
    local still = math.abs(h.x - F.x) < 0.002 and math.abs(h.y - F.y) < 0.002 and math.abs(h.z - F.z) < 0.002
    local moved = math.sqrt((PS.x - F.bx) ^ 2 + (PS.y - F.by) ^ 2 + (PS.z - F.bz) ^ 2) > 0.005
    if still and moved then
      F.t = F.t + dt
    elseif not still then
      F.t, F.kicked = 0.0, false
    end
  end
  F.x, F.y, F.z, F.bx, F.by, F.bz = h.x, h.y, h.z, PS.x, PS.y, PS.z
  if F.t >= FPC.still141.frozen and not F.kicked then
    F.kicked = true
    FPF.cockpitBlink141(string.format("its left hand has stayed at one place in the world for %.2f s while BT moved (%s)",
      F.t, PS.act and tostring(PS.act.kind) or "a scene"))
  end
end

