FPF.stillFrame140 = FPF.stillFrame
function FPF.stillFrame(dt)
  if not P.stillSoft then return FPF.stillFrame140(dt) end
  local W = PS.stillW
  if W.kickAt and S.clock > W.kickAt then
    W.kickAt = nil
    if not PF.shown then
      if W.offList then FPF.meshToggle141(W.offList, true) else FPF.body(true) end
    end
  end
  if PS.scene and PS.scene ~= PS.blinkScene141 then
    PS.blinkScene141 = PS.scene
    FPF.cockpitBlink141("a scene begins")
  end
  guard("BT's skeleton seen from its hand", FPF.frozenWatch141, dt)
  local A = PS.awake
  if P.awake and A and PS.ent and IsDefined(PS.ent) and (PS.act or PS.scene) and not PS.warm and PS.mode ~= "none" and (A.placedAt or -1.0) < S.clock then
    A.at = math.min(A.at, S.clock)
    guard("BT kept awake in a scene", FPF.placeBt)
  end
  local W2 = W
  local kickAt = W2.kickAt
  W2.kickAt = nil
  FPF.stillFrame140(dt)
  if W2.kickAt == nil then W2.kickAt = kickAt end
end

