function FPF.coreFire(by)
  local B = PS.buddy
  if P.aiTactics and not S.driving and B and B.state == "active" and B.target and FPF.flightCan() then
    local K = FPC.aiTactics.flight
    local T = B.target
    local boss = false
    if K.boss then
      pcall(function()
        local _, what = FPF.coreWorth(T.ent)
        boss = what == "a boss"
      end)
    end
    local seen = FPF.aiView(FPF.mtmsSeen) or {}
    local why = (boss and "its foe is a boss") or ((#seen >= K.foes) and string.format("%d foes in view", #seen))
      or ((math.random() < K.chance) and "now and then") or nil
    if why then
      FPF.flightStart()
      if PS.flight then PS.flight.ai = true end
      B.flights = (B.flights or 0) + 1
      if B.flights <= FPC.aiTactics.lines then log("BT on its own spends its core on FLIGHT STRIKE (" .. why .. ")") end
      return true
    end
    B.coreOwn = (B.coreOwn or 0) + 1
    if B.coreOwn <= FPC.aiTactics.lines then
      log(string.format("BT on its own spends its core on its weapon's own (%d foes in view; FLIGHT STRIKE only from %d, or %.0f %% of the time)", #seen, K.foes, K.chance * 100.0))
    end
  end
  return FPF.coreFire119(by)
end

