function FPF.swordCmdClip142(kind)
  local S_ = PUNCH_CLIP.sword
  local K = FPC.sword
  if kind == "dash" then return S_, K.tpClips[1] end
  if kind == "iaido" then return S_.dash, K.tpClips[2] end
  if kind == "finisher" then return S_.wave, K.tpWave end
  return S_[kind], S_.cmds[kind]
end

function FPF.swordCmdStart(kind, by)
  local K = FPC.sword
  local Kc = K.cmd
  local C, clip = FPF.swordCmdClip142(kind)
  if not C or not clip then return nil end
  local M = { t = 0.0, wave = false, hit = {}, done = false, by = by, rate = FPF.swordRate(), sent = 0, attacks = 0, people = 0,
    titans = 0, vehicles = 0, fx = 0, seen = S.clock, cmd = kind, yaw = S.yaw }
  M.tp, M.tpClip = C, clip
  if kind == "finisher" then
    M.fpClip, M.view, M.fpTime = K.fpWave, "wave", (FP.wave and FP.wave.time) or C.time
  else
    local n = Kc.fp[kind] or 1
    local F = (n == 1) and { time = FP.melee, hit = FP.meleeHit } or ((n == 2) and FP.dash or FP.slash3)
    M.fpClip, M.view, M.fpTime = K.fpClips[n], K.views[n], (F and F.time) or C.time
  end
  M.from = C.hit
  if kind == "iaido" then
    M.rate = M.rate * Kc.iaido.rate
    M.from = 1.0e9
  end
  M.len = math.max(M.fpTime, C.time)
  PS.slash, PS.slashAsk, PS.sprintOn = M, nil, false
  PS.slashes = (PS.slashes or 0) + 1
  local B = PS.swordBlock
  if B and B.on then B.on, B.idle = false, 0.0 end
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local how = ""
  if C.ahead and C.side then
    PS.lunge = { x = fx, y = fy, track = C, punch = M, scale = 1.0, last = 0.0, t = 0.0, time = C.time + 0.5 }
  elseif kind == "dash" then
    local due = M.from / math.max(M.rate, 0.1)
    PS.lunge = { x = fx, y = fy, speed = Kc.dash.lunge / math.max(due, 0.05), t = 0.0, time = due }
    how = string.format("; it lunges %.1f m to the cut", Kc.dash.lunge)
  elseif kind == "iaido" then
    PS.lunge = { x = fx, y = fy, speed = Kc.iaido.speed, t = 0.0, time = Kc.iaido.time }
    M.path = { x = PS.x, y = PS.y, z = PS.z, met = {}, cuts = {}, n = 0 }
    how = string.format("; through %.1f m of the dash's line", Kc.iaido.speed * Kc.iaido.time)
  end
  if kind == "finisher" then
    FPF.swordSound(K.sounds.waveFire)
  elseif PF.shown then
    FPF.swordSound(K.sounds.fp, FPF.viewVolume())
  else
    FPF.swordSound(K.sounds.tp)
  end
  PS.swordCmds = (PS.swordCmds or 0) + 1
  if PS.swordCmds <= Kc.lines then
    log(string.format("SWORD COMMAND %s (%s): bt_melee_clip %d, %.2f s; %s%s", kind, tostring(by), clip, C.time,
      (M.from < 1.0e8) and string.format("it meets what is in front after %.2f s", M.from / M.rate) or "its cut runs along the dash's line", how))
  end
  return M
end

FPF.slashHit142 = FPF.slashHit
function FPF.slashHit(ent, M)
  if not M or not M.cmd then return FPF.slashHit142(ent, M) end
  if M.cmd == "finisher" then return guard("ARC FINISHER", FPF.finisherSlam142, M) end
  local mul = (M.cmd == "dash") and FPC.sword.cmd.dash.mul or nil
  local own, rec0 = false, nil
  if mul then
    local Kc = FPC.sword.charge
    own = FPF.gunRecord(Kc.record) == Kc.record
    if own then
      FPF.chargeFlats(mul - 1.0)
      rec0 = FPC.sword.records.slash
      FPC.sword.records.slash = Kc.record
    end
  end
  local ok, err = pcall(FPF.slashHit142, ent, M)
  if rec0 then FPC.sword.records.slash = rec0 end
  if not ok then error(err, 0) end
  if M.cmd == "rise" then
    local K = FPC.sword.cmd.rise
    for _, T in ipairs(FPF.punchTargets(FPF.swordReach(), K.angle)) do
      if T.kind == "person" and (T.r or 0.0) <= 0.0 then
        local worth = nil
        pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
        if worth == "a boss" then
          FPF.fistStagger(T.ent, "uppercut")
        else
          pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](T.ent, TweakDBID.new(FPC.fist.stagger.down)) end)
          FPF.ragdoll(T.ent, T.x - T.dx * 0.5, T.y - T.dy * 0.5, T.z, T.dx * 0.3, T.dy * 0.3, K.push * K.lift)
        end
      elseif (T.r or 0.0) > 0.0 then
        FPF.fistStagger(T.ent, "uppercut")
      end
    end
  end
end

function FPF.finisherSlam142(M)
  local K, Kw = FPC.sword.cmd.finisher, FPC.sword.wave
  local r0 = math.rad(M.yaw or S.yaw)
  local fx0, fy0 = -math.sin(r0), math.cos(r0)
  local rec = FPF.gunRecord(FPC.sword.records.wave)
  if FPF.perk("sword") >= 1 then
    PS.fwaves = PS.fwaves or {}
    local shared = {}
    for _, a in ipairs(K.waves) do
      local r = math.rad((M.yaw or S.yaw) + a)
      local fx, fy = -math.sin(r), math.cos(r)
      PS.fwaves[#PS.fwaves + 1] = { t = 0.0, step = 0, steps = K.steps, fx = fx, fy = fy, x0 = PS.x + fx * Kw.from, y0 = PS.y + fy * Kw.from,
        z = PS.z, hit = shared, people = 0, vehicles = 0, sent = 0, attacks = 0, n = (PS.waves or 0) + 1, by = M.by }
    end
    FPF.swordSound(FPC.sword.sounds.waveTravel)
    PS.finishers = (PS.finishers or 0) + 1
    if PS.finishers <= FPC.sword.cmd.lines then
      log(string.format("ARC FINISHER %d: the slam sends three short arc waves (%s deg, %d steps each - %.0f m)", PS.finishers,
        table.concat((function() local o = {} for _, a in ipairs(K.waves) do o[#o + 1] = string.format("%+.0f", a) end return o end)(), " / "),
        K.steps, (K.steps - 1) * Kw.step + Kw.from))
    end
    return
  end
  local x, y = PS.x + fx0 * Kw.from, PS.y + fy0 * Kw.from
  local W = { hit = {}, people = 0, vehicles = 0, sent = 0, attacks = 0, n = (PS.waves or 0) + 1, fx = fx0, fy = fy0, by = M.by }
  local wide = Kw.wide
  Kw.wide = K.shock
  for _, who in ipairs(PS.npcs) do pcall(FPF.waveMeet, W, who, "person", x, y, PS.z, rec) end
  for _, veh in ipairs(FPF.vehicles()) do pcall(FPF.waveMeet, W, veh, "vehicle", x, y, PS.z, rec) end
  Kw.wide = wide
  if P.fxOn then
    local inst = FPF.fxAt(Kw.fx, x, y, PS.z + Kw.up, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + Kw.life } end
  end
  FPF.stim("Explosion", FPC.stims.punch, 0.2)
  PS.finishers = (PS.finishers or 0) + 1
  if PS.finishers <= FPC.sword.cmd.lines then
    log(string.format("ARC FINISHER %d: ARC WAVE is disabled by the server loadout - the slam's shock only, %.1f m round where it lands: %d people, %d vehicles", PS.finishers, K.shock, W.people, W.vehicles))
  end
end

function FPF.finisherWaves142(dt)
  local L = PS.fwaves
  if not L or #L == 0 then return end
  local Kw = FPC.sword.wave
  local rec = FPF.gunRecord(FPC.sword.records.wave)
  if S.clock - PS.npcsAt > 0.25 then
    PS.npcsAt = -10
    refreshNpcs()
  end
  for i = #L, 1, -1 do
    local W = L[i]
    W.t = W.t + dt
    while W.step < W.steps and W.t >= W.step * Kw.stepTime do
      W.step = W.step + 1
      local dd = (W.step - 1) * Kw.step
      local x, y = W.x0 + W.fx * dd, W.y0 + W.fy * dd
      local gz = groundZ(x, y, W.z)
      if gz and math.abs(gz - W.z) <= Kw.rise then W.z = gz end
      for _, who in ipairs(PS.npcs) do FPF.waveMeet(W, who, "person", x, y, W.z, rec) end
      for _, veh in ipairs(FPF.vehicles()) do FPF.waveMeet(W, veh, "vehicle", x, y, W.z, rec) end
      if P.meleeDevices then
        W.devHit = W.devHit or {}
        FPF.meleeDevAt(x, y, W.z, Kw.wide, Kw.high + 2.0, FPC.dev.melee.area, rec, "ARC FINISHER", W.devHit)
      end
      if P.fxOn then
        local inst = FPF.fxAt(Kw.fx, x, y, W.z + Kw.up, nil, nil)
        if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + Kw.life } end
      end
    end
    if W.step >= W.steps then table.remove(L, i) end
  end
end

function FPF.iaidoFrame142(M)
  local Pth = M.path
  if not Pth then return end
  local K = FPC.sword.cmd.iaido
  if M.t * 1.0 <= (K.time + 0.1) * M.rate then
    if S.clock - PS.npcsAt > 0.1 then
      PS.npcsAt = -10
      refreshNpcs()
    end
    local ax, ay = Pth.x, Pth.y
    local bx, by = PS.x, PS.y
    local vx, vy = bx - ax, by - ay
    local L2 = math.max(vx * vx + vy * vy, 1e-6)
    local function near(T)
      local u = clamp(((T.x - ax) * vx + (T.y - ay) * vy) / L2, 0.0, 1.0)
      local px, py = ax + vx * u, ay + vy * u
      return math.sqrt((T.x - px) ^ 2 + (T.y - py) ^ 2) <= K.wide + (T.r or 0.0) and math.abs(T.z - PS.z) < 6.0
    end
    for _, T in ipairs(FPF.fistRound(PS.x, PS.y, PS.z, math.sqrt(L2) + K.wide + 8.0, 6.0)) do
      if not Pth.met[T.key] and near(T) then
        Pth.met[T.key] = true
        Pth.cuts[#Pth.cuts + 1] = { T = T, at = S.clock + K.delay }
      end
    end
    if P.meleeDevices then
      Pth.devHit = Pth.devHit or {}
      FPF.meleeDevAt(PS.x, PS.y, PS.z, K.wide, 6.0, FPC.dev.melee.slash, FPF.gunRecord(FPC.sword.records.slash), "IAIDO FLASH", Pth.devHit)
    end
  end
  local Kc = FPC.sword.charge
  for i = #Pth.cuts, 1, -1 do
    local c = Pth.cuts[i]
    if S.clock >= c.at then
      table.remove(Pth.cuts, i)
      local T = c.T
      if IsDefined(T.ent) then
        local own = FPF.gunRecord(Kc.record) == Kc.record
        local rec = own and Kc.record or FPF.gunRecord(FPC.sword.records.slash)
        if own then FPF.chargeFlats(K.mul - 1.0) end
        local ok, p = pcall(function() return T.ent:GetWorldPosition() end)
        local x, y, z = T.x, T.y, T.z
        if ok and p then x, y, z = p.x, p.y, p.z end
        FPF.hit(T.ent, rec, x, y, z + 1.0, T.dx or 0.0, T.dy or 1.0, 0.0)
        FPF.attack(rec, x, y, z + 0.5)
        if T.kind == "vehicle" then
          FPF.wreck(T.ent, FPC.wreck.punch * FPC.sword.wreck)
        else
          FPF.fistStagger(T.ent, "electric")
        end
        if P.fxOn then
          local inst = FPF.fxAt(FPC.fist.fx.mid, x, y, z + 1.5, nil, nil)
          if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + FPC.fist.fx.life } end
        end
        Pth.n = Pth.n + 1
        FPF.swordSound(FPC.sword.sounds.flesh)
      end
    end
  end
  if #Pth.cuts == 0 and M.t > (K.time + K.delay + 0.2) * M.rate and not Pth.said then
    Pth.said = true
    PS.iaidos = (PS.iaidos or 0) + 1
    if PS.iaidos <= FPC.sword.cmd.lines then log(string.format("IAIDO FLASH %d: %d cut along the dash's line, %.2f s after it passed", PS.iaidos, Pth.n, K.delay)) end
  end
end

function FPF.swordCmdFrames142(dt)
  guard("ARC FINISHER's waves", FPF.finisherWaves142, dt)
  local M = PS.slash
  if M and M.cmd == "iaido" then guard("IAIDO FLASH", FPF.iaidoFrame142, M) end
  local R = PS.slashRun
  if R and R.last and PS.slash ~= R.last and not R.endAt then R.endAt = S.clock end
  local A = PS.swordCmdAsk
  if A then
    local Ms = PS.slash
    if S.clock - A.at > 1.5 then
      PS.swordCmdAsk = nil
    elseif not Ms or Ms.done then
      PS.swordCmdAsk = nil
      FPF.swordCmdStart(A.kind, A.by)
      if R then R.done = true end
    end
  end
end

FPF.slashStart142 = FPF.slashStart
function FPF.slashStart(by, wave)
  local M = FPF.slashStart142(by, wave)
  if M and not wave and not M.cmd then
    local R = PS.slashRun
    local gap = FPC.sword.cmd.finisherGap
    if R and not R.done and (PS.slash == M and R.last ~= nil and (R.endAt == nil or S.clock - R.endAt <= gap)) then
      R.n, R.last, R.endAt = R.n + 1, M, nil
    else
      PS.slashRun = { n = 1, last = M }
    end
  end
  return M
end

function FPF.swordChained142()
  local R = PS.slashRun
  if not R or R.done or R.n < 3 then return false end
  if PS.slash == R.last then return true end
  return R.endAt ~= nil and S.clock - R.endAt <= FPC.sword.cmd.finisherGap
end

FPF.punch142 = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "sword" or not P.swordCmds then return FPF.punch142(dt, ent, key) end
  if S.driving and S.pilot and not FPF.flightImmune() and not PS.execHint then
    local B = PS.swordBlock
    local guarded = B ~= nil and B.on
    local M = PS.slash
    local free = not PS.punch and not PS.pound and not PS.spin and not PS.exec and not (PS.vortex and PS.vortex.on)
    local busy = M ~= nil and M.t < M.len - FPC.sword.chain
    local cell = FPF.cellOwned142()
    if key and free then
      local kind = nil
      if guarded then
        local mx, my = S.moveX + S.kr - S.kl, S.moveY + S.kf - S.kb
        local want = (my < -0.5 and "retreat") or (mx > 0.5 and "evade_r") or (mx < -0.5 and "evade_l") or nil
        if want and not cell and P.meleeUnlock then
          FPF.cellRefused142("The broadsword's EVASIVE / RETREAT SLASH")
          want = nil
        end
        kind = want or "rise"
      elseif FPF.swordChained142() then
        kind = "finisher"
      elseif PS.dashT ~= nil and PS.dashT < TF.dodgeTime + PUNCH.dashGrace then
        if cell or not P.meleeUnlock then kind = "iaido" else FPF.cellRefused142("The broadsword's IAIDO FLASH") end
      elseif PS.sprintOn then
        kind = "dash"
      end
      if kind then
        if busy and kind == "finisher" then
          PS.swordCmdAsk = { kind = kind, at = S.clock, by = "three slashes and the melee key" }
        elseif not busy then
          FPF.swordCmdStart(kind, (kind == "finisher") and "three slashes and the melee key" or ((guarded and "the guard and the melee key")
            or ((kind == "iaido") and "dashing, the melee key" or "sprinting, the melee key")))
          if kind == "finisher" and PS.slashRun then PS.slashRun.done = true end
        end
        key = false
      end
    end
  end
  local r = FPF.punch142(dt, ent, key)
  FPF.swordCmdFrames142(dt)
  return r
end

FPF.gunFrame142 = gunFrame
gunFrame = function(dt, ent, firing)
  if PS.weapon == "sword" and P.swordCmds and S.driving and S.pilot then
    local down = PS.reloadKey == true
    if down and not PS.swordRWas then PS.swordRAsk = S.clock end
    PS.swordRWas = down
  end
  return FPF.gunFrame142(dt, ent, firing)
end

FPF.spinCharge142 = FPF.spinCharge
function FPF.spinCharge(dt)
  if P.spinNoStack then
    PS.spinCharge = FPC.sword.spin.charges
    return PS.spinCharge
  end
  return FPF.spinCharge142(dt)
end

FPF.sentryFrame142 = FPF.sentryFrame
function FPF.sentryFrame(dt, f, s, sprint, dash, jump, held)
  if PS.weapon ~= "sword" or not P.swordCmds then return FPF.sentryFrame142(dt, f, s, sprint, dash, jump, held) end
  local n = PS.keyN.sentry or 0
  if PS.cSeen == nil then PS.cSeen = n end
  local pressedC = n ~= PS.cSeen
  PS.cSeen = n
  if PS.swordRAsk then
    PS.swordRAsk = nil
    if FPF.cellOwned142() or not P.meleeUnlock then
      PS.sentrySeen = n - 1
    else
      FPF.cellRefused142("The broadsword's SPIN SLASH (the reload key)")
      PS.sentrySeen = n
    end
  else
    PS.sentrySeen = n
  end
  if pressedC and not held and P.phaseDash then FPF.phaseAsk142() end
  local a, b, c, d2, e2 = FPF.sentryFrame142(dt, f, s, sprint, dash, jump, held)
  FPF.phaseFrame142()
  return a, b, c, d2, e2
end

function FPF.phaseAsk142()
  local K = FPC.sword.cmd.phase
  if P.meleeUnlock and not FPF.cellOwned142() then
    FPF.cellRefused142("The broadsword's PHASE DASH (SENTRY MODE's key)")
    return
  end
  local left = (PS.phaseReadyAt or 0.0) - S.clock
  local why = (left > 0.0 and string.format("ready again in %.1f s", left)) or (PS.phaseDash and "it is phased already") or (PS.jump and "BT is in a jump")
    or (PS.exec and "an execution") or (PS.spin and "a spin") or (FPF.flightImmune() and "FLIGHT STRIKE is on") or nil
  if why then
    PS.phaseRefused = (PS.phaseRefused or 0) + 1
    if PS.phaseRefused <= FPC.sword.cmd.lines then log("PHASE DASH: not now - " .. why) end
    return
  end
  local mx, my = S.moveX + S.kr - S.kl, S.moveY + S.kf - S.kb
  local r = math.rad(S.yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local rx, ry = fy, -fx
  local dx, dy = fx * my + rx * mx, fy * my + ry * mx
  local m = math.sqrt(dx * dx + dy * dy)
  if m < 0.2 then dx, dy = fx, fy else dx, dy = dx / m, dy / m end
  PS.slash, PS.slashAsk = nil, nil
  PS.phaseDash = { at = S.clock, till = S.clock + K.time, x = PS.x, y = PS.y, dx = dx, dy = dy, hidden = false }
  PS.lunge = { x = dx, y = dy, speed = K.speed, t = 0.0, time = K.push }
  PS.phaseReadyAt = S.clock + K.cooldown
  if not PF.shown then PS.phaseDash.hidden = FPF.body(false) > 0 end
  if P.fxOn then
    local inst = FPF.fxAt(K.fx, PS.x, PS.y, PS.z + 3.0, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + 0.8 } end
  end
  pcall(FPF.dashSound)
  PS.phases = (PS.phases or 0) + 1
  if PS.phases <= FPC.sword.cmd.lines then
    log(string.format("PHASE DASH %d: unseen and untouchable for %.1f s, %.0f m/s for %.2f s (%s) - ready again in %.1f s", PS.phases, K.time, K.speed, K.push,
      (m < 0.2) and "ahead" or "along the move keys", K.cooldown))
  end
end

function FPF.phaseFrame142()
  local Ph = PS.phaseDash
  if not Ph or S.clock < Ph.till then return end
  PS.phaseDash = nil
  if Ph.hidden and not PF.shown then FPF.body(true) end
  if P.fxOn then
    local inst = FPF.fxAt(FPC.sword.cmd.phase.fx, PS.x, PS.y, PS.z + 3.0, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + 0.8 } end
  end
  if (PS.phases or 0) <= FPC.sword.cmd.lines then
    log(string.format("PHASE DASH over: BT is back %.1f m from where it went", math.sqrt((PS.x - Ph.x) ^ 2 + (PS.y - Ph.y) ^ 2)))
  end
end

FPF.health142 = FPF.health
function FPF.health(dt, alone)
  local H = PS.hp
  if PS.phaseDash and H and H.pend then H.pend.a, H.pend.b = 0.0, 0.0 end
  return FPF.health142(dt, alone)
end

FPF.sessionEnd142 = FPF.sessionEnd
function FPF.sessionEnd(why)
  if PS.phaseDash then
    if PS.phaseDash.hidden and not PF.shown then pcall(FPF.body, true) end
    PS.phaseDash = nil
  end
  PS.fwaves, PS.swordCmdAsk, PS.slashRun = nil, nil, nil
  return FPF.sessionEnd142(why)
end

FPF.slotStates142 = FPF.slotStates
function FPF.slotStates(M, V, Q)
  local out = FPF.slotStates142(M, V, Q)
  if PS.weapon == "sword" and P.phaseDash and FPF.cellOwned142() then
    local K = FPC.sword.cmd.phase
    local left = (PS.phaseReadyAt or 0.0) - S.clock
    if PS.phaseDash then
      out.sentry = { fill = clamp((PS.phaseDash.till - S.clock) / K.time, 0.0, 1.0), state = "active" }
    elseif left > 0.0 then
      out.sentry = { fill = clamp(1.0 - left / K.cooldown, 0.0, 1.0), state = "empty" }
    else
      out.sentry = { fill = 1.0, state = "ready" }
    end
  end
  return out
end

FPF.swordNote142 = FPF.swordNote
function FPF.swordNote()
  local out = FPF.swordNote142()
  if P.phaseDash and FPF.cellOwned142() then
    out = out:gsub("   SPIN %d+", "")
    local left = (PS.phaseReadyAt or 0.0) - S.clock
    out = out .. ((left > 0.0) and string.format("   PHASE %.0f s", left) or "   PHASE ready")
  end
  return out
end

FPF.aiSwordMoves142 = FPF.aiSwordMoves
function FPF.aiSwordMoves(B, T)
  FPF.aiSwordMoves142(B, T)
  if not P.aiSwordCmds or not P.swordCmds or S.driving or PS.weapon ~= "sword" then return end
  local ok, err = pcall(FPF.aiSwordCmd142, B, T)
  if not ok then once("aiswordcmd" .. tostring(err), "BT on its own: a command of the broadsword could NOT be picked (" .. tostring(err) .. ")") end
end

function FPF.aiSwordCmd142(B, T)
  local K = FPC.swordAI.cmd
  if not T or not T.ent or PS.spin or PS.punch or PS.lunge or PS.jump or PS.dashT ~= nil or PS.skate or PS.exec then return end
  local M = PS.slash
  if M and not M.done then return end
  if FPF.swordChained142() and not (PS.slashRun and PS.slashRun.aiAsked) then
    PS.slashRun.aiAsked = true
    if math.random() < K.finisher then
      local Mf = FPF.aiView(FPF.swordCmdStart, "finisher", "BT on its own")
      if Mf then
        PS.slashRun.done = true
        FPF.aiSwordCmdSaid("ARC FINISHER after three slashes")
        return
      end
    end
  end
  if M then return end
  local yaw = (type(B.yaw) == "number") and B.yaw or PS.yaw
  local r = math.rad(yaw)
  local fx, fy = -math.sin(r), math.cos(r)
  local dx, dy = T.x - PS.x, T.y - PS.y
  local d = math.sqrt(dx * dx + dy * dy)
  local ang = math.deg(math.atan2(dx * fy - dy * fx, dx * fx + dy * fy))
  if d >= K.dash[1] and d <= K.dash[2] and math.abs(ang) <= K.front and S.clock >= (PS.aiDashSlashAt or 0.0) then
    PS.aiDashSlashAt = S.clock + K.dashGap
    if FPF.aiView(FPF.swordCmdStart, "dash", "BT on its own") then
      FPF.aiSwordCmdSaid(string.format("DASH SLASH at its foe %.0f m ahead", d))
      return
    end
  end
  if S.clock < (PS.aiSwordCmdAt or 0.0) then return end
  local kind = nil
  if d <= K.rise and math.abs(ang) <= K.front then
    kind = "rise"
  elseif d <= K.evade and math.abs(ang) > 45.0 and math.abs(ang) <= 135.0 and (FPF.cellOwned142() or not P.meleeUnlock) then
    kind = (ang > 0.0) and "evade_r" or "evade_l"
  end
  if not kind then
    PS.aiSwordCmdAt = S.clock + K.retry
    return
  end
  PS.aiSwordCmdAt = S.clock + K.every[1] + math.random() * (K.every[2] - K.every[1])
  if FPF.aiView(FPF.swordCmdStart, kind, "BT on its own") then
    FPF.aiSwordCmdSaid(string.format("%s - its foe %.1f m away, %+.0f deg", kind, d, ang))
  end
end

function FPF.aiSwordCmdSaid(what)
  PS.aiSwordCmds = (PS.aiSwordCmds or 0) + 1
  if PS.aiSwordCmds <= FPC.swordAI.cmd.lines then log("BT on its own, the broadsword: a command - " .. what) end
end

P.fistDouble143, P.slamSound143, P.grab143, P.dropArms143, P.finisherCharge143, P.phaseFx143, P.iaido143 = true, true, true, true, true, true, true
FPC.fist.double = { gap = 0.22, lines = 10 }
FPC.fist.hammer.twiceGrace = 9.0
