FPF.fistCmdStart143p = FPF.fistCmdStart
function FPF.fistCmdStart(kind, by)
  if kind == "uppercut" and by == "the melee key" and P.fistDouble143 and S.driving and S.pilot and not PS.fistTapGo then
    PS.fistTap = { at = S.clock, by = by }
    return nil
  end
  return FPF.fistCmdStart143p(kind, by)
end

FPF.punch143p = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" or not P.fistDouble143 or not (S.driving and S.pilot) or FPF.flightImmune() or PS.execHint then
    PS.fistTap = nil
    return FPF.punch143p(dt, ent, key)
  end
  local T = PS.fistTap
  if T and key and S.clock - T.at <= FPC.fist.double.gap + 0.05 then
    PS.fistTap = nil
    if not PS.punch and not PS.fistCharge and not PS.pound and not PS.exec then
      return FPF.fistDouble143(dt, ent, T)
    end
  elseif T and S.clock - T.at >= FPC.fist.double.gap then
    PS.fistTap = nil
    local J = PS.jab
    local free = not PS.punch and not PS.pound and not PS.fistCharge and not PS.fistPress and not (PS.vortex and PS.vortex.on) and not PS.exec
      and not (J and not J.done)
    if free then
      PS.fistTapGo = true
      local ok, err = pcall(FPF.fistCmdStart, "uppercut", T.by)
      PS.fistTapGo = nil
      if not ok then error(err, 0) end
    end
  end
  return FPF.punch143p(dt, ent, key)
end

function FPF.fistDouble143(dt, ent, T)
  local held = PS.meleeHeld
  PS.meleeHeld = false
  local ok, r = pcall(FPF.punch139, dt, ent, true)
  PS.meleeHeld = held
  if not ok then error(r, 0) end
  local M = PS.punch
  local how
  if M and M.fistKind == "heavy" then
    M.hammerAsk, M.double143 = S.clock, true
    local learned = FPF.perk("fist") > 0
    local left = (PS.hammerReadyAt or 0.0) - S.clock
    how = (not learned and "SEISMIC HAMMER is disabled by the server loadout - the slam alone") or (left > 0.0 and string.format("SEISMIC HAMMER is not ready (%.1f s) - the slam alone", left))
      or "SEISMIC HAMMER goes as it lands"
  else
    how = "the slam could not start (" .. tostring(M and M.fistKind or "nothing") .. ")"
  end
  PS.doubles143 = (PS.doubles143 or 0) + 1
  if PS.doubles143 <= FPC.fist.double.lines then
    log(string.format("DOUBLE PRESS (the melee key twice, %.2f s apart): the SLAM - %s", S.clock - T.at, how))
  end
  pcall(FPF.cmdFrames141)
  return r
end

FPF.punchHit143p = FPF.punchHit
function FPF.punchHit(ent, M, last)
  local r = FPF.punchHit143p(ent, M, last)
  if P.slamSound143 and PS.weapon == "fist" and M and M.fistKind == "heavy" and M.fistAfter and not M.slamHeard143 then
    M.slamHeard143 = true
    local ok, played = pcall(FPF.tf, FPC.poundSounds.slam)
    PS.slamHeard143 = (PS.slamHeard143 or 0) + 1
    if PS.slamHeard143 <= FPC.fist.double.lines then
      log(string.format("SLAM %d: it meets the ground - GROUND POUND's gun slam (%s) %s", PS.slamHeard143, FPC.poundSounds.slam, (ok and played) and "is heard" or "could NOT be played"))
    end
  end
  return r
end

FPF.hammerStart143p = FPF.hammerStart
function FPF.hammerStart(M)
  FPF.hammerStart143p(M)
  if P.slamSound143 then
    local L = FPC.poundSounds.land
    PS.poundSoundN = (PS.poundSoundN or 0) % #L + 1
    pcall(FPF.tf, L[PS.poundSoundN])
  end
end

function FPF.tossHandAt143(M, t)
  local C = M.clip
  local n = #C.hand
  local i = clamp(t * C.fps, 0.0, n - 1)
  local a = math.floor(i)
  local b = math.min(a + 1, n - 1)
  local u = i - a
  local p, q = C.hand[a + 1], C.hand[b + 1]
  local rx, ay, z = p[1] + (q[1] - p[1]) * u, p[2] + (q[2] - p[2]) * u, p[3] + (q[3] - p[3]) * u
  local x, y = FPF.cmdWorld(rx, ay)
  return x, y, PS.z + z
end

function FPF.grabVehicleOf143(X)
  local best, bd = nil, FPC.fist.grab143.near
  for _, veh in ipairs(FPF.vehicles()) do
    if veh and IsDefined(veh) then
      local ok, p = pcall(function() return veh:GetWorldPosition() end)
      if ok and p then
        local d = math.sqrt((p.x - X.x) ^ 2 + (p.y - X.y) ^ 2)
        if d < bd then
          local key = nil
          pcall(function() key = tostring(veh:GetEntityID()) end)
          local dx, dy = p.x - PS.x, p.y - PS.y
          local dd = math.max(math.sqrt(dx * dx + dy * dy), 0.01)
          best, bd = { ent = veh, kind = "vehicle", dist = dd, x = p.x, y = p.y, z = p.z + 0.6, key = key or "vehicle", dx = dx / dd, dy = dy / dd, r = 0.0, seat = X }, d
        end
      end
    end
  end
  return best
end

function FPF.grabCarOk143(veh)
  if not veh or not IsDefined(veh) then return false end
  if FPF.isWreck and FPF.isWreck(veh) then return false end
  local dead = false
  pcall(function() dead = veh:IsDestroyed() == true end)
  return not dead
end

FPF.grabTarget143p = FPF.grabTarget
function FPF.grabTarget(look, cone)
  if not P.grab143 then return FPF.grabTarget143p(look, cone) end
  for _, X in ipairs(FPF.punchTargets(look, cone)) do
    if X.kind == "person" and (X.r or 0.0) <= 0.0 then
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(X.ent); worth = w end)
      if worth ~= "a boss" then
        local seated = false
        pcall(function() seated = VehicleComponent["VehicleComponent::IsMountedToVehicle;GameInstanceGameObject"](X.ent) == true end)
        if not seated then return X end
        local V = FPF.grabVehicleOf143(X)
        if V and FPF.grabCarOk143(V.ent) then return V end
      end
    elseif X.kind == "vehicle" and FPF.grabCarOk143(X.ent) then
      return X
    end
  end
  return nil
end

FPF.tossGrab143p = FPF.tossGrab
function FPF.tossGrab(M)
  if not P.grab143 then return FPF.tossGrab143p(M) end
  local K, G = FPC.fist.cmd.grab, FPC.fist.grab143
  PS.npcsAt = -10
  refreshNpcs()
  local hx, hy = FPF.tossHand(M)
  local want = M.grab and M.grab.target
  if want and want.ent and IsDefined(want.ent) then
    local ok, p = pcall(function() return want.ent:GetWorldPosition() end)
    if ok and p then
      local d = math.sqrt((p.x - hx) ^ 2 + (p.y - hy) ^ 2)
      if want.kind == "vehicle" and d <= G.carMagnet then return FPF.carTake143(M, want, d) end
      if want.kind == "person" and d <= G.magnet then
        local hand0 = K.hand
        K.hand = math.max(K.hand, d + 0.05)
        local ok2, err = pcall(FPF.tossGrab143p, M)
        K.hand = hand0
        if not ok2 then error(err, 0) end
        return
      end
    end
  end
  for _, X in ipairs(FPF.fistRound(hx, hy, PS.z, K.hand, K.high)) do
    if X.kind == "person" then return FPF.tossGrab143p(M) end
  end
  local best, bd = nil, G.carMagnet
  for _, X in ipairs(FPF.fistRound(hx, hy, PS.z, G.carMagnet, K.high)) do
    if X.kind == "vehicle" and X.d < bd and FPF.grabCarOk143(X.ent) then best, bd = X, X.d end
  end
  if best then return FPF.carTake143(M, best, bd) end
  return FPF.tossGrab143p(M)
end

FPF.carryStart143p = FPF.carryStart
function FPF.carryStart(M, d)
  if not P.grab143 then return FPF.carryStart143p(M, d) end
  local Cr = M.carry
  local ent = Cr.ent
  pcall(function() if not OP77.statusObserved(ent, FPC.fist.stagger.stun) then StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, TweakDBID.new(FPC.fist.stagger.stun)) end end)
  Cr.disabled = pcall(function() ent:MountingStartDisableComponents() end)
  Cr.mountAsked, Cr.checkAt = false, nil
  local name = "?"
  pcall(function() name = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
  Cr.name = name
  log(string.format("GRAB AND TOSS: %s taken %.1f m from the hand - moved by the game's teleport order from this frame on, aimed %.2f s ahead on the hand's way%s",
    tostring(name), d or 0.0, FPC.fist.grab143.lead, Cr.disabled and "; its collision off (the game's grappled)" or ""))
end

FPF.tossCarry143p = FPF.tossCarry
function FPF.tossCarry(M)
  if not P.grab143 then return FPF.tossCarry143p(M) end
  local Cr = M.carry
  if not Cr or Cr.thrown or not IsDefined(Cr.ent) then return end
  if Cr.car then return FPF.carCarry143(M) end
  local G = FPC.fist.grab143
  local hang = FPC.fist.cmd.toss.hang
  local x, y, z = FPF.tossHandAt143(M, M.t + G.lead)
  local ent = Cr.ent
  pcall(function()
    local cmd = NewObject("handle:AITeleportCommand")
    cmd.position = Vector4.new(x, y, z - hang, 1.0)
    cmd.rotation = PS.yaw
    cmd.doNavTest = false
    ent:GetAIControllerComponent():SendCommand(cmd)
  end)
  pcall(function() Game.GetTeleportationFacility():Teleport(ent, Vector4.new(x, y, z - hang, 1.0), EulerAngles.new(0, 0, PS.yaw)) end)
  if not Cr.followSaid and S.clock - Cr.at >= 0.6 then
    Cr.followSaid = true
    pcall(function()
      local hx, hy, hz = FPF.tossHand(M)
      local p = ent:GetWorldPosition()
      log(string.format("GRAB AND TOSS: 0.6 s into the carry it is %.1f m from the hand (the teleport order every frame, %.2f s ahead)",
        math.sqrt((p.x - hx) ^ 2 + (p.y - hy) ^ 2 + (p.z - (hz - hang)) ^ 2), G.lead))
    end)
  end
end

FPF.knock143p = FPF.knock
function FPF.knock(ent, p, ux, uy)
  if P.grab143 then
    local M = PS.punch
    if M and M.fistKind == "toss" then
      local key = nil
      pcall(function() key = tostring(ent:GetEntityID()) end)
      local want = M.grab and M.grab.target
      if key and ((M.carry and M.carry.key == key) or (want and want.key == key)) then return end
    end
  end
  return FPF.knock143p(ent, p, ux, uy)
end

function FPF.carTake143(M, T, d)
  local G = FPC.fist.grab143
  local veh = T.ent
  local mass = 1500.0
  pcall(function()
    local m = veh:GetTotalMass()
    if m and m > 50.0 then mass = m end
  end)
  M.hit[T.key] = true
  local text = FPF.vehicleText and FPF.vehicleText(veh) or "a vehicle"
  if mass > G.carMass then
    FPF.wreck(veh, FPC.wreck.punch * 0.5)
    local dx, dy = T.x - PS.x, T.y - PS.y
    local n = math.max(math.sqrt(dx * dx + dy * dy), 0.01)
    pcall(FPF.kick, veh, dx / n, dy / n, 5.0, 1.0)
    FPF.punchSound("hit")
    FPF.grabMiss(M, string.format("%s weighs %.0f kg (more than %.0f) - a shove", text, mass, G.carMass))
    return
  end
  local yawCar = PS.yaw + 90.0
  pcall(function() yawCar = veh:GetWorldYaw() end)
  M.carry = { ent = veh, key = T.key, at = S.clock, car = true, mass = mass, yawRel = wrap180(yawCar - PS.yaw), name = text }
  if PS.lunge and PS.lunge.punch == M then PS.lunge.scale = 1.0 end
  pcall(function() veh:PhysicsWakeUp() end)
  PS.carGrabs143 = (PS.carGrabs143 or 0) + 1
  if PS.carGrabs143 <= G.lines then
    log(string.format("GRAB AND TOSS: %s (%.0f kg) taken %.1f m from the hand%s - carried by the game's teleport every frame, its speed taken off", text, mass, d or 0.0,
      T.seat and " (somebody sat in it)" or ""))
  end
end

function FPF.carStill143(Cr)
  pcall(function()
    local v = Cr.ent:GetLinearVelocity()
    if v and (math.abs(v.x) + math.abs(v.y) + math.abs(v.z)) > 0.05 then
      local p = Cr.ent:GetWorldPosition()
      local evt = PhysicalImpulseEvent.new()
      evt.radius = 3.0
      evt.worldPosition = Vector3.new(p.x, p.y, p.z + 0.6)
      evt.worldImpulse = Vector3.new(-v.x * Cr.mass, -v.y * Cr.mass, -v.z * Cr.mass)
      Cr.ent:QueueEvent(evt)
    end
  end)
end

function FPF.carCarry143(M)
  local Cr = M.carry
  local G = FPC.fist.grab143
  local x, y, z = FPF.tossHandAt143(M, M.t + G.carLead)
  local yaw = wrap180(PS.yaw + (Cr.yawRel or 90.0))
  FPF.carStill143(Cr)
  local ok = pcall(function() Game.GetTeleportationFacility():Teleport(Cr.ent, Vector4.new(x, y, z - G.carHang, 1.0), EulerAngles.new(0, 0, yaw)) end)
  Cr.moves = (Cr.moves or 0) + (ok and 1 or 0)
  if not Cr.followSaid and S.clock - Cr.at >= 0.6 then
    Cr.followSaid = true
    pcall(function()
      local hx, hy, hz = FPF.tossHand(M)
      local p = Cr.ent:GetWorldPosition()
      log(string.format("GRAB AND TOSS: 0.6 s into the carry the vehicle is %.1f m from where the hand holds it (%d teleports)",
        math.sqrt((p.x - hx) ^ 2 + (p.y - hy) ^ 2 + (p.z - (hz - G.carHang)) ^ 2), Cr.moves))
    end)
  end
end

FPF.tossRelease143p = FPF.tossRelease
function FPF.tossRelease(M)
  local Cr = M.carry
  if P.grab143 and Cr and Cr.car then return FPF.carRelease143(M) end
  return FPF.tossRelease143p(M)
end

function FPF.carRelease143(M)
  local Cr = M.carry
  if Cr.thrown then return end
  Cr.thrown = true
  if not IsDefined(Cr.ent) then return end
  local G = FPC.fist.grab143
  local yaw = S.yaw
  if not S.driving then
    local Bd = PS.buddy
    local T = Bd and Bd.target
    yaw = (T and T.x) and math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)) or PS.yaw
  end
  local r = math.rad(yaw)
  local ux, uy = -math.sin(r), math.cos(r)
  FPF.carStill143(Cr)
  local thrown = FPF.kick(Cr.ent, ux, uy, G.throw.speed, G.throw.up)
  FPF.punchSound("hit")
  PS.carLand143 = { at = S.clock + G.landAfter, ent = Cr.ent, key = Cr.key, name = Cr.name }
  log(string.format("GRAB AND TOSS: %s thrown %s (%.0f deg) at %.0f m/s, %.0f m/s up%s - wrecked where it is %.1f s from now", tostring(Cr.name),
    S.driving and "where the view points" or "at its foe", yaw, G.throw.speed, G.throw.up, thrown and "" or " (the push could NOT be given)", G.landAfter))
end

function FPF.carLandFrame143()
  local L = PS.carLand143
  if not L or S.clock < L.at then return end
  PS.carLand143 = nil
  local G = FPC.fist.grab143
  if not IsDefined(L.ent) then return end
  local x, y, z = PS.x, PS.y, PS.z
  pcall(function()
    local p = L.ent:GetWorldPosition()
    x, y, z = p.x, p.y, p.z
  end)
  local n = 0
  local rec = FPF.gunRecord(FPC.fist.records.blast)
  for _, T in ipairs(FPF.fistRound(x, y, z, G.land, G.landHigh)) do
    if T.key ~= L.key and T.kind ~= "vehicle" then
      n = n + 1
      local ux, uy = T.x - x, T.y - y
      local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux / d, uy / d, 0.0)
      FPF.fistStagger(T.ent, "toss")
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
      if worth ~= "a boss" then FPF.ragdoll(T.ent, T.x, T.y, T.z + 0.6, ux / d, uy / d, G.landPush) end
    end
  end
  local wrecked = FPF.wreck(L.ent, G.carShare)
  if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), x, y, z + 0.3, PS.yaw, 0.0) end
  log(string.format("GRAB AND TOSS: the thrown %s comes down at (%.1f, %.1f) - wrecked (%s), %d people within %.1f m knocked down", tostring(L.name), x, y,
    wrecked and "its health taken" or "its health could NOT be changed", n, G.land))
end

FPF.cmdFrames143p = FPF.cmdFrames141
function FPF.cmdFrames141()
  FPF.cmdFrames143p()
  if PS.carLand143 then guard("a thrown vehicle's landing", FPF.carLandFrame143) end
end

function FPF.inDrop143()
  local D = SCENES and SCENES.drop
  return D ~= nil and D.clip ~= nil and math.floor((PS.sceneClip or 0) + 0.5) == D.clip and (PS.sceneW or 0.0) > 0.0
end

FPF.swordHoldW143p = FPF.swordHoldW
function FPF.swordHoldW()
  if P.dropArms143 and PS.weapon == "sword" and not PS.exec and not PS.eject and FPF.inDrop143() then return 1.0 end
  return FPF.swordHoldW143p()
end

FPF.fistSceneArms143p = FPF.fistSceneArms
function FPF.fistSceneArms()
  if P.dropArms143 and FPF.inDrop143() then return 1.0, 1.0 end
  return FPF.fistSceneArms143p()
end

FPF.finisherSlam143p = FPF.finisherSlam142
function FPF.finisherSlam142(M)
  if not P.finisherCharge143 then return FPF.finisherSlam143p(M) end
  local learned = FPF.perk("sword") >= 1
  local c = learned and FPF.waveCharge(0.0) or 0.0
  if learned and c >= 1.0 then
    PS.waveCharges = math.max(0.0, c - 1.0)
    FPF.waveCharge(0.0)
    FPF.finisherSlam143p(M)
    if (PS.finishers or 0) <= FPC.sword.cmd.lines then
      log(string.format("ARC FINISHER: one of ARC WAVE's charges spent - %.1f of %d left", PS.waveCharges, FPC.sword.wave.charges))
    end
    return
  end
  return FPF.finisherShock143(M, learned and string.format("no ARC WAVE charge (%.1f of %d)", c, FPC.sword.wave.charges) or "ARC WAVE is disabled by the server loadout")
end

function FPF.finisherShock143(M, why)
  local K, Kw = FPC.sword.cmd.finisher, FPC.sword.wave
  local r0 = math.rad(M.yaw or S.yaw)
  local fx0, fy0 = -math.sin(r0), math.cos(r0)
  local rec = FPF.gunRecord(FPC.sword.records.wave)
  local x, y = PS.x + fx0 * Kw.from, PS.y + fy0 * Kw.from
  local W = { hit = {}, people = 0, vehicles = 0, sent = 0, attacks = 0, n = (PS.waves or 0) + 1, fx = fx0, fy = fy0, by = M.by }
  local wide = Kw.wide
  Kw.wide = K.shock
  for _, who in ipairs(PS.npcs) do pcall(FPF.waveMeet, W, who, "person", x, y, PS.z, rec) end
  for _, veh in ipairs(FPF.vehicles()) do pcall(FPF.waveMeet, W, veh, "vehicle", x, y, PS.z, rec) end
  Kw.wide = wide
  if P.fxOn then
    local inst = FPF.fxAt(Kw.fx, x, y, PS.z + Kw.up, nil, nil)
    if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + Kw.life } end
  end
  FPF.stim("Explosion", FPC.stims.punch, 0.2)
  PS.finishers = (PS.finishers or 0) + 1
  if PS.finishers <= FPC.sword.cmd.lines then
    log(string.format("ARC FINISHER %d: %s - the slam's shock only, %.1f m round where it lands: %d people, %d vehicles", PS.finishers, why, K.shock, W.people, W.vehicles))
  end
end

function FPF.phaseFx143(path, x, y, z, dx, dy)
  if not P.fxOn or not path then return end
  local yaw = math.deg(math.atan2(-(dx or 0.0), dy or 1.0))
  local inst = FPF.fxAt(path, x, y, z, yaw, 0.0)
  if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + FPC.sword.cmd.phase.fxLife } end
end

function FPF.phaseSound143(on)
  local K = FPC.sword.cmd.phase.sounds
  local name = PF.shown and (on and K.onFp or K.offFp) or (on and K.onTp or K.offTp)
  local ok, played = pcall(FPF.ownSound, name, math.max(FPF.viewVolume(), 0.7))
  return name, ok and played
end

FPF.phaseAsk143p = FPF.phaseAsk142
function FPF.phaseAsk142()
  local before = PS.phaseDash
  FPF.phaseAsk143p()
  local Ph = PS.phaseDash
  if P.phaseFx143 and Ph and Ph ~= before then
    FPF.phaseFx143(FPC.sword.cmd.phase.fxGo, Ph.x, Ph.y, PS.z, Ph.dx, Ph.dy)
    local name, heard = FPF.phaseSound143(true)
    PS.phaseFx143 = (PS.phaseFx143 or 0) + 1
    if PS.phaseFx143 <= FPC.sword.cmd.lines then
