      asked and "a ragdoll" or "its ragdoll could NOT be asked", FPC.fist.grab145.hang))
  end
end

FPF.tossCarry145p = FPF.tossCarry
function FPF.tossCarry(M)
  local Cr = M.carry
  if not P.grabRagdoll145 or not Cr or Cr.car or Cr.thrown or not IsDefined(Cr.ent) then return FPF.tossCarry145p(M) end
  local G = FPC.fist.grab145
  local dt = clamp(S.dt or 0.016, 0.005, 0.05)
  local hx, hy, hz = FPF.tossHandAt143(M, M.t)
  local tx, ty, tz = hx, hy, hz - G.hang
  local p = nil
  pcall(function() p = Cr.ent:GetWorldPosition() end)
  if not p then return end
  local px, py, pz = p.x, p.y, p.z + G.up
  local vx, vy, vz = 0.0, 0.0, 0.0
  if Cr.lastP then vx, vy, vz = (px - Cr.lastP[1]) / dt, (py - Cr.lastP[2]) / dt, (pz - Cr.lastP[3]) / dt end
  local hvx, hvy, hvz = 0.0, 0.0, 0.0
  if Cr.lastH then hvx, hvy, hvz = (hx - Cr.lastH[1]) / dt, (hy - Cr.lastH[2]) / dt, (hz - Cr.lastH[3]) / dt end
  Cr.lastP, Cr.lastH = { px, py, pz }, { hx, hy, hz }
  local wx, wy, wz = (tx - px) / G.tau + hvx, (ty - py) / G.tau + hvy, (tz - pz) / G.tau + hvz
  local wn = math.sqrt(wx * wx + wy * wy + wz * wz)
  if wn > G.speed then wx, wy, wz = wx * G.speed / wn, wy * G.speed / wn, wz * G.speed / wn end
  local ix, iy, iz = G.mass * (wx - vx), G.mass * (wy - vy), G.mass * (wz - vz + 9.81 * dt)
  local n = math.sqrt(ix * ix + iy * iy + iz * iz)
  if n > G.most then ix, iy, iz = ix * G.most / n, iy * G.most / n, iz * G.most / n end
  local sent = pcall(function()
    local imp = RagdollApplyImpulseEvent.new()
    imp.worldImpulsePos = Vector4.new(px, py, pz, 1.0)
    imp.worldImpulseValue = Vector4.new(ix, iy, iz, 0.0)
    imp.influenceRadius = G.radius
    Cr.ent:QueueEvent(imp)
  end)
  Cr.pushes = Cr.pushes + (sent and 1 or 0)
  local off = math.sqrt((tx - px) ^ 2 + (ty - py) ^ 2 + (tz - pz) ^ 2)
  for _, at in ipairs({ 0.3, 0.6, 1.2, 1.8 }) do
    if not Cr.err[at] and S.clock - Cr.at >= at then
      Cr.err[at] = off
      if (PS.ragGrabs145 or 0) <= G.lines then
        log(string.format("GRAB AND TOSS: %.1f s into the carry the ragdoll is %.1f m from its place under the hand (%d impulses, this one %.0f)", at, off, Cr.pushes, n))
      end
    end
  end
end

FPF.carRelease145p = FPF.carRelease143
function FPF.carRelease143(M)
  if not P.carFly145 then return FPF.carRelease145p(M) end
  local Cr = M.carry
  if Cr.thrown then return end
  Cr.thrown = true
  if not IsDefined(Cr.ent) then return end
  local G, K = FPC.fist.grab143, FPC.fist.carFly145
  local yaw = S.yaw
  if not S.driving then
    local Bd = PS.buddy
    local T = Bd and Bd.target
    yaw = (T and T.x) and math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)) or PS.yaw
  end
  local r = math.rad(yaw)
  local ux, uy = -math.sin(r), math.cos(r)
  local x, y, z = FPF.tossHandAt143(M, M.t)
  z = z - G.carHang
  pcall(function()
    local p = Cr.ent:GetWorldPosition()
    x, y, z = p.x, p.y, p.z
  end)
  PS.carFly145 = { ent = Cr.ent, key = Cr.key, name = Cr.name, x = x, y = y, z = z, vx = ux * G.throw.speed, vy = uy * G.throw.speed, vz = G.throw.up,
    yaw = wrap180(PS.yaw + (Cr.yawRel or 90.0)), pitch = 0.0, roll = 0.0, t = 0.0, moves = 0 }
  FPF.punchSound("hit")
  log(string.format("GRAB AND TOSS: %s thrown %s (%.0f deg) at %.0f m/s, %.0f m/s up - its flight moved by the teleport until it comes down", tostring(Cr.name),
    S.driving and "where the view points" or "at its foe", yaw, G.throw.speed, G.throw.up))
end

function FPF.carFlyFrame145()
  local F_ = PS.carFly145
  if not F_ then return end
  if not IsDefined(F_.ent) then PS.carFly145 = nil return end
  local K, G = FPC.fist.carFly145, FPC.fist.grab143
  local dt = clamp(S.dt or 0.016, 0.005, 0.05)
  F_.t = F_.t + dt
  local nx, ny = F_.x + F_.vx * dt, F_.y + F_.vy * dt
  local nvz = F_.vz - K.gravity * dt
  local nz = F_.z + nvz * dt
  local hit = nil
  pcall(function()
    local dx, dy, dz = nx - F_.x, ny - F_.y, nz - F_.z
    local len = math.sqrt(dx * dx + dy * dy + dz * dz)
    if len > 0.01 then
      local t, kind = rayWorld(F_.x, F_.y, F_.z + 0.8, dx / len, dy / len, dz / len, len + K.ahead * dt * 10.0)
      if kind ~= "nothing" and kind ~= "person" and kind ~= "vehicle" and t and t < len + 0.5 then hit = t end
    end
  end)
  local gz = groundZ(nx, ny, nz + 2.0)
  local down = (gz ~= nil and nz <= gz + 0.05 and nvz < 0.0) or hit ~= nil or F_.t >= K.most
  if down then
    if gz and nz < gz then nz = gz end
    if hit then nx, ny = F_.x, F_.y end
  end
  F_.x, F_.y, F_.z, F_.vz = nx, ny, nz, nvz
  F_.pitch = F_.pitch + K.spin[1] * dt
  F_.roll = F_.roll + K.spin[2] * dt
  local ok = pcall(function()
    Game.GetTeleportationFacility():Teleport(F_.ent, Vector4.new(nx, ny, nz, 1.0), EulerAngles.new(down and 0 or F_.roll, down and 0 or F_.pitch, F_.yaw))
  end)
  F_.moves = F_.moves + (ok and 1 or 0)
  if not down then return end
  PS.carFly145 = nil
  local n = 0
  local rec = FPF.gunRecord(FPC.fist.records.blast)
  for _, T in ipairs(FPF.fistRound(nx, ny, nz, G.land, G.landHigh)) do
    if T.key ~= F_.key and T.kind ~= "vehicle" then
      n = n + 1
      local ux, uy = T.x - nx, T.y - ny
      local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux / d, uy / d, 0.0)
      FPF.fistStagger(T.ent, "toss")
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
      if worth ~= "a boss" then FPF.ragdoll(T.ent, T.x, T.y, T.z + 0.6, ux / d, uy / d, G.landPush) end
    end
  end
  FPF.groundSound145(FPC.ground145.hammer, "a thrown vehicle comes down")
  local hulk = FPF.isWreck(F_.ent)
  local wrecked = (not hulk) and FPF.wreck(F_.ent, G.carShare)
  if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), nx, ny, nz + 0.3, PS.yaw, 0.0) end
  log(string.format("GRAB AND TOSS: the thrown %s comes down %s at (%.1f, %.1f) after %.2f s (%d teleports) - %s, %d people within %.1f m knocked down",
    tostring(F_.name), hit and "against a wall" or "on the ground", nx, ny, F_.t, F_.moves,
    hulk and "a wreck already (nothing more sent to it)" or (wrecked and "wrecked (its health taken)" or "wrecked (its health could NOT be changed)"), n, G.land))
end

