function FPF.panNext147(name, side, far, placed, what)
  local K = FPC.pan147
  local pan = clamp(side, -1.0, 1.0) * K.most
  PS.panNext = { name = name, pan = pan, at = S.clock }
  local X = PS.sideAllSeen or { n = 0, left = 0, mid = 0, right = 0, lines = 0 }
  PS.sideAllSeen, PS.sideAllNow = X, side
  X.n = X.n + 1
  if side < -0.125 then X.left = X.left + 1 elseif side > 0.125 then X.right = X.right + 1 else X.mid = X.mid + 1 end
  if X.lines < K.lines and (X.at == nil or S.clock - X.at >= K.every) then
    X.lines, X.at = X.lines + 1, S.clock
    log(string.format("a sound from its side: %s comes from %s for the view (side %+.2f, %.0f m away%s) - played with pan %+.2f%s", name,
      (side < -0.125) and "the left" or ((side > 0.125) and "the right" or "ahead or behind"), side, far or 0.0, placed and "; the place it happens at" or "",
      pan, what and (" (" .. what .. ")") or ""))
  end
end

FPF.sideName147 = FPF.sideName
function FPF.sideName(name)
  if not P.pan147 then return FPF.sideName147(name) end
  local G = FPC.side
  local R = (P.sideAll and name) and G.rows[name] or nil
  if not R then return name end
  local D = PS.sideMemo
  if D and D.name == name and D.at == S.clock then return name end
  local at, x, y, z = PS.soundAt, nil, nil, nil
  if at then
    x, y, z = at.x, at.y, at.z
  elseif R.at == "point" or S.driving or not PS.ent or not PS.x then
    return name
  else
    x, y, z = PS.x, PS.y, PS.z + ((R.at == "body") and G.body or 0.0)
  end
  local side, far = FPF.sideTo(x, y, z)
  if not side then return name end
  PS.sideMemo = { name = name, at = S.clock, row = name }
  FPF.panNext147(name, side, far, at ~= nil)
  return name
end

FPF.on147 = FPF.on
function FPF.on(axl, name, gain)
  if P.pan147 then
    PS.sideHas = false
    local G = FPC.gunDir
    if P.gunDir and not S.driving and G.panned[name] then
      local side = FPF.gunSide()
      if side then
        FPF.panNext147(name, side, PS.sideFar, false, "BT's own gun")
        FPF.gunSideSeen(side, name .. " with pan", nil)
      end
    end
  end
  return FPF.on147(axl, name, gain)
end

FPF.onBase147 = FPF.on75
FPF.on75 = function(axl, name, gain) return FPF.onPan147(axl, name, gain) end
function FPF.onPan147(axl, name, gain)
  local Pn = PS.panNext
  if P.pan147 and Pn and Pn.name == name and Pn.at == S.clock then
    PS.panNext = nil
    if P.plainGain and not FPC.placedRows[name] and not PS.panRefused then
      local id = FPF.noEntity()
      if id ~= nil then
        local level = (gain == nil) and 0.0 or math.max(gain, 0.01)
        local ok, took = pcall(function() return axl:Play(name, id, level, 0.0, 0.0, 0.0, Pn.pan) end)
        if ok then
          PS.panPlays = (PS.panPlays or 0) + 1
          if PS.panPlays == 1 then
            log(string.format("BT's sounds from a side: played with AudioXL's pan for each play (the first: %s at pan %+.2f) - the sound folder has no rows for a side any more", name, Pn.pan))
          end
          return took
        end
        PS.panRefused = true
        log("BT's sounds from a side: AudioXL does not take a pan with Play (" .. tostring(took) .. " - older than 0.7.0?) - they are heard from the middle of the head")
      end
    end
  end
  return FPF.onBase147(axl, name, gain)
end

FPF.tfSide147 = FPF.tf105
FPF.tf105 = function(name, line) return FPF.tfPan147(name, line) end
function FPF.tfPan147(name, line)
  if not P.pan147 or line or not name then return FPF.tfSide147(name, line) end
  local row = FPF.sideName(name)
  local Pn = PS.panNext
  if Pn and Pn.name == row and Pn.at == S.clock and P.sounds and not (S.driving and PS.mode == "pilot") and not PS.aiGain then
    local axl = FPF.axl()
    if axl and PS.tfHas ~= false then
      local took = FPF.onPan147(axl, row, nil)
      if took ~= false then
        PS.tfPlayed = PS.tfPlayed + 1
        return true, false
      end
    end
  end
  return FPF.tfSide147(name, line)
end

P.grabRagdoll145 = false
FPC.fist.grab143.lead = 0.35
FPC.fist.carFly145.wallAfter = 0.12

function FPF.carFlyFrame145()
  local F_ = PS.carFly145
  if not F_ or F_.stepAt == S.clock then return end
  F_.stepAt = S.clock
  if not IsDefined(F_.ent) then
    PS.carFly145 = nil
    return
  end
  local K, G = FPC.fist.carFly145, FPC.fist.grab143
  local dt = clamp(S.dt or 0.016, 0.005, 0.05)
  F_.t = F_.t + dt
  local nx, ny = F_.x + F_.vx * dt, F_.y + F_.vy * dt
  local nvz = F_.vz - K.gravity * dt
  local nz = F_.z + nvz * dt
  if F_.t >= K.wallAfter and (F_.vx ~= 0.0 or F_.vy ~= 0.0) then
    pcall(function()
      local dx, dy = nx - F_.x, ny - F_.y
      local len = math.sqrt(dx * dx + dy * dy)
      if len > 0.001 then
        local t, kind = rayWorld(F_.x, F_.y, F_.z + 0.8, dx / len, dy / len, 0.0, len + K.ahead)
        local k = type(kind) == "string" and string.lower(kind) or ""
        if (k == "static" or k == "terrain") and t and t < len + K.ahead then
          F_.vx, F_.vy, F_.wall = 0.0, 0.0, true
          nx, ny = F_.x, F_.y
        end
      end
    end)
  end
  if F_.vx ~= 0.0 or F_.vy ~= 0.0 then
    local known = false
    for _, group in ipairs({ "Terrain", "Static" }) do
      if not known then
        pcall(function()
          local hit = FPF.sqs():SyncRaycastByCollisionGroup(Vector4.new(nx, ny, nz + 3.0, 1.0), Vector4.new(nx, ny, nz - 1500.0, 1.0), group, nil, false, false)
          if hit then known = true end
        end)
      end
    end
    if not known then
      F_.vx, F_.vy, F_.wall = 0.0, 0.0, true
      nx, ny = F_.x, F_.y
    end
  end
  local gz = groundZ(nx, ny, math.max(nz, F_.z) + 2.0)
  local down = gz ~= nil and nz <= gz + 0.05 and nvz < 0.0
  if not down and F_.t >= 29.0 then
    local above = gz == nil and groundZ(nx, ny, nz + 60.0) or nil
    if gz == nil and above == nil then
      F_.lost, PS.carFly145 = true, nil
      return
    end
    down, gz = true, gz or above
  end
  if down and gz then nz = gz end
  F_.x, F_.y, F_.z, F_.vz = nx, ny, nz, nvz
  F_.pitch = F_.pitch + K.spin[1] * dt
  F_.roll = F_.roll + K.spin[2] * dt
  local ok = pcall(function()
    Game.GetTeleportationFacility():Teleport(F_.ent, Vector4.new(nx, ny, nz, 1.0), EulerAngles.new(down and 0 or F_.roll, down and 0 or F_.pitch, F_.yaw))
  end)
  F_.moves = F_.moves + (ok and 1 or 0)
  if not down then return end
  PS.carFly145 = nil
  pcall(function() F_.ent:PhysicsWakeUp() end)
  local n = 0
  local rec = FPF.gunRecord(FPC.fist.records.blast)
  for _, T in ipairs(FPF.fistRound(nx, ny, nz, G.land, G.landHigh)) do
    if T.key ~= F_.key and T.kind ~= "vehicle" then
      n = n + 1
      local ux, uy = T.x - nx, T.y - ny
      local d = math.max(0.01, math.sqrt(ux * ux + uy * uy))
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, ux / d, uy / d, 0.0)
      FPF.fistStagger(T.ent, "toss")
      local worth = nil
      pcall(function() local _, w = FPF.coreWorth(T.ent); worth = w end)
      if worth ~= "a boss" then FPF.ragdoll(T.ent, T.x, T.y, T.z + 0.6, ux / d, uy / d, G.landPush) end
    end
  end
  FPF.groundSound145(FPC.ground145.hammer, "a thrown vehicle comes down")
  local hulk = FPF.isWreck(F_.ent)
  local wrecked = (not hulk) and FPF.wreck(F_.ent, G.carShare)
  if P.fxOn then FPF.fxAt(FPF.fxPath("punch"), nx, ny, nz + 0.3, PS.yaw, 0.0) end
  log(string.format("GRAB AND TOSS: the thrown %s comes down on the ground at (%.1f, %.1f)%s after %.2f s (%d teleports) - %s, %d people within %.1f m knocked down",
    tostring(F_.name), nx, ny, F_.wall and " (a wall stopped its way on)" or "", F_.t, F_.moves,
    hulk and "a wreck already (nothing more sent to it)" or (wrecked and "wrecked (its health taken)" or "wrecked (its health could NOT be changed)"), n, G.land))
end

