FPC.fist.hold149 = { hang = 1.15, blend = 0.10, keep = 0.3, lines = 10 }
FPC.fist.throw149 = { speed = 30.0, lift = 22.65, most = 45.0, least = -35.0, near = 8.0, push = 1.14, lines = 10 }

FPC.fistAI.cmd.every, FPC.fistAI.cmd.electric, FPC.fistAI.cmd.tossGap, FPC.fistAI.cmd.shoulderGap = { 11.0, 16.0 }, 0.3, 22.0, 28.0
