FPF.tossGrab149p = FPF.tossGrab
function FPF.tossGrab(M)
  if not (P.grabSeat149 and P.grab143) then return FPF.tossGrab149p(M) end
  local round = FPF.fistRound
  local seated = {}
  local want = M.grab and M.grab.target
  if want and want.kind == "person" and want.ent and IsDefined(want.ent) and FPF.seated149(want.ent) then
    local V = FPF.grabVehicleOf143(want)
    if V and FPF.grabCarOk143(V.ent) then M.grab.target = V end
  end
  FPF.fistRound = function(x, y, z, reach, high)
    local out = {}
    for _, X in ipairs(round(x, y, z, reach, high)) do
      if X.kind == "person" and FPF.seated149(X.ent) then seated[#seated + 1] = X else out[#out + 1] = X end
    end
    return out
  end
  local ok, err = pcall(FPF.tossGrab149p, M)
  FPF.fistRound = round
  if not ok then error(err, 0) end
  if #seated > 0 then
    PS.seatSkips149 = (PS.seatSkips149 or 0) + 1
    if PS.seatSkips149 <= FPC.fist.carHand149.lines then
      local C = M.carry
      log(string.format("GRAB: %d seated in a vehicle round the hand not taken - %s", #seated,
        (C and C.car) and ("the vehicle taken: " .. tostring(C.name)) or ((C and C.ent) and "somebody on foot taken" or "nothing taken")))
    end
  end
end

function FPF.armR149()
  local A = PS.armR149
  if A and A.at == S.clock then return A.out end
  local h, w, e = slotWorld("hand_r"), slotWorld("wrist_r"), slotWorld("elbow_r")
  local now = { at = S.clock, h = h, w = w, e = e }
  if h and w and e then
    local out = { h = h, w = w, e = e }
    if A and A.h and A.w and A.e and S.clock - A.at > 0.0 and S.clock - A.at < 0.1 then
      local k = clamp((S.dt or 0.016) / (S.clock - A.at), 0.0, 1.5)
      local most = FPC.fist.carHand149.step
      out = {}
      for _, n in ipairs({ "h", "w", "e" }) do
        local p, q = now[n], A[n]
        local sx, sy, sz = (p.x - q.x) * k, (p.y - q.y) * k, (p.z - q.z) * k
        local len = math.sqrt(sx * sx + sy * sy + sz * sz)
        if len > most then sx, sy, sz = sx * most / len, sy * most / len, sz * most / len end
        out[n] = { x = p.x + sx, y = p.y + sy, z = p.z + sz }
      end
    end
    now.out = out
  end
  PS.armR149 = now
  return now.out
end

FPF.carCarry149p = FPF.carCarry143
function FPF.carCarry143(M)
  local Cr = M.carry
  if not P.carHand149 then return FPF.carCarry149p(M) end
  local K = FPC.fist.carHand149
  local A = FPF.armR149()
  if not A then
    if not PS.carArmSaid149 then
      PS.carArmSaid149 = true
      log("GRAB AND TOSS: BT's arm slots (hand_r, wrist_r, elbow_r) cannot be read - a vehicle is carried under the toss clip's wrist as before")
    end
    return FPF.carCarry149p(M)
  end
  local fx, fy, fz = A.w.x - A.e.x, A.w.y - A.e.y, A.w.z - A.e.z
  local n = math.sqrt(fx * fx + fy * fy + fz * fz)
  if n < 0.05 then return FPF.carCarry149p(M) end
  fx, fy, fz = fx / n, fy / n, fz / n
  local level = math.sqrt(fx * fx + fy * fy)
  local s = clamp(((Cr.mass or 1600.0) / 1600.0) ^ (1.0 / 3.0), 0.85, 1.3)
  local halfW, halfH = 0.95 * s, 0.72 * s
  local yaw = Cr.yaw149
  if level >= K.level then
    local want = wrap180(math.deg(math.atan2(-fx, fy)) + 90.0)
    if yaw == nil then
      yaw = want
    else
      local d1, d2 = wrap180(want - yaw), wrap180(want + 180.0 - yaw)
      local d = (math.abs(d1) <= math.abs(d2)) and d1 or d2
      yaw = wrap180(yaw + d * (1.0 - math.exp(-clamp(S.dt or 0.016, 0.0, 0.1) / K.yawTau)))
    end
  end
  yaw = yaw or wrap180(PS.yaw + (Cr.yawRel or 90.0))
  Cr.yaw149 = yaw
  local out = level * halfW + math.abs(fz) * halfH - K.grip
  local cx, cy, cz = A.h.x + fx * out, A.h.y + fy * out, A.h.z + fz * out - halfH * K.drop * level
  local x, y, z = cx, cy, cz - halfH
  if not Cr.from149 then
    local p, y0 = nil, yaw
    pcall(function() p = Cr.ent:GetWorldPosition() end)
    pcall(function() y0 = Cr.ent:GetWorldYaw() end)
    Cr.from149 = { x = p and p.x or x, y = p and p.y or y, z = p and p.z or z, yaw = y0, at = S.clock }
  end
  local F0 = Cr.from149
  local u = clamp((S.clock - F0.at) / K.blend, 0.0, 1.0)
  u = u * u * (3.0 - 2.0 * u)
  if u < 1.0 then
    x, y, z = F0.x + (x - F0.x) * u, F0.y + (y - F0.y) * u, F0.z + (z - F0.z) * u
    yaw = wrap180(F0.yaw + wrap180(yaw - F0.yaw) * u)
  end
  Cr.yawRel = wrap180(yaw - PS.yaw)
  FPF.carStill143(Cr)
  local ok = pcall(function() Game.GetTeleportationFacility():Teleport(Cr.ent, Vector4.new(x, y, z, 1.0), EulerAngles.new(0, 0, yaw)) end)
  Cr.moves = (Cr.moves or 0) + (ok and 1 or 0)
  if not Cr.handSaid149 and S.clock - Cr.at >= 0.6 then
    Cr.handSaid149 = true
    PS.carHands149 = (PS.carHands149 or 0) + 1
    if PS.carHands149 <= K.lines then
      local off = -1.0
      pcall(function()
        local p = Cr.ent:GetWorldPosition()
        off = math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - z) ^ 2)
      end)
      log(string.format("GRAB AND TOSS: 0.6 s into the carry %s is held out past the hand - its middle %.1f m on along the forearm (%.0f %% of it level), %.1f m from the palm, %.1f m from the elbow; it stands %.1f m from where it is put (%d teleports)",
        tostring(Cr.name), out, level * 100.0, math.sqrt((A.h.x - cx) ^ 2 + (A.h.y - cy) ^ 2 + (A.h.z - cz) ^ 2),
        math.sqrt((A.e.x - cx) ^ 2 + (A.e.y - cy) ^ 2 + (A.e.z - cz) ^ 2), off, Cr.moves))
    end
  end
end

function FPF.throwAim149(x, y, z, key, speed)
  local K = FPC.fist.throw149
  local g = FPC.fist.carFly145.gravity
  local yaw, pitch = S.yaw or PS.yaw, S.pitch or 0.0
  if PF.shown and S.look then yaw, pitch = S.look.yaw, S.look.pitch end
  local tx, ty, tz, by = nil, nil, nil, nil
  if not S.driving then
    local Bd = PS.buddy
    local T = Bd and Bd.target
    if T and T.x then
      yaw, pitch = math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)), 0.0
      tx, ty, tz, by = T.x, T.y, (T.z or PS.z) + 1.0, "its foe"
    else
      yaw, pitch = PS.yaw, 0.0
    end
  else
    local A = PS.aim
    if A and A.x and A.kind ~= "nothing" then
      local mine = false
      if key then pcall(function() mine = A.who ~= nil and tostring(A.who:GetEntityID()) == key end) end
      if mine then
        by = "the thing carried under the crosshair"
      else
        tx, ty, tz, by = A.x, A.y, A.z, "the point under the crosshair"
      end
    end
  end
  if tx then
    local hx, hy = tx - x, ty - y
    local D = math.sqrt(hx * hx + hy * hy)
    if D >= K.near then
      local v2 = speed * speed
      local disc = v2 * v2 - g * (g * D * D + 2.0 * (tz - z) * v2)
      if disc >= 0.0 then
        local th = math.atan((v2 - math.sqrt(disc)) / (g * D))
        local c = math.cos(th)
        return hx / D * c, hy / D * c, math.sin(th), math.deg(th), by, D
      end
      by = by .. string.format(" (%.0f m: out of reach)", D)
    else
      by = by .. string.format(" (%.0f m: too near)", D)
    end
  end
  local e = clamp(pitch + K.lift, K.least, K.most)
  local ry, re = math.rad(yaw), math.rad(e)
  return -math.sin(ry) * math.cos(re), math.cos(ry) * math.cos(re), math.sin(re), e, (by and (by .. " - ") or "") .. "the view lifted", nil
end

FPF.carRelease149p = FPF.carRelease143
function FPF.carRelease143(M)
  local Cr = M.carry
  if not (P.throwAim149 and P.carFly145) or not Cr or Cr.thrown then return FPF.carRelease149p(M) end
  Cr.thrown = true
  if not IsDefined(Cr.ent) then return end
  local G, K = FPC.fist.grab143, FPC.fist.throw149
  local x, y, z = FPF.tossHandAt143(M, M.t)
  z = z - G.carHang
  pcall(function()
    local p = Cr.ent:GetWorldPosition()
    x, y, z = p.x, p.y, p.z
  end)
  local ux, uy, uz, rise, by, D = FPF.throwAim149(x, y, z + 0.7, Cr.key, K.speed)
  PS.carFly145 = { ent = Cr.ent, key = Cr.key, name = Cr.name, x = x, y = y, z = z, vx = ux * K.speed, vy = uy * K.speed, vz = uz * K.speed,
    yaw = wrap180(PS.yaw + (Cr.yawRel or 90.0)), pitch = 0.0, roll = 0.0, t = 0.0, moves = 0, v0 = K.speed, rise = rise }
  FPF.punchSound("hit")
  PS.throws149 = (PS.throws149 or 0) + 1
  if PS.throws149 <= K.lines then
    log(string.format("GRAB AND TOSS: %s thrown %s - at %s, %.0f deg up at %.0f m/s (%.0f deg round)%s - its flight moved by the teleport until it comes down",
      tostring(Cr.name), S.driving and "where the view points" or "at its foe", by, rise, K.speed, math.deg(math.atan2(-ux, uy)),
      D and string.format(", the point %.0f m away", D) or ""))
  end
end

function FPF.bodyRoot149(ent)
  local comp = nil
  pcall(function() comp = ent:FindComponentByName("root") end)
  if comp and not pcall(function() return comp:GetLocalPosition() end) then comp = nil end
  if not comp then
    pcall(function()
      for _, c in ipairs(ent:GetComponents()) do
        if c:IsA("entAnimatedComponent") then
          comp = c
          break
        end
      end
    end)
  end
  return comp
end

FPF.carryStart149p = FPF.carryStart
function FPF.carryStart(M, d)
  FPF.carryStart149p(M, d)
  local Cr = M.carry
  if not P.holdBody149 or not Cr or Cr.car or Cr.ragdoll or not Cr.ent or not IsDefined(Cr.ent) then return end
  local comp, why = FPF.bodyRoot149(Cr.ent), nil
  if not comp then
    why = "its skeleton's own component was not found"
  else
    local p0, q0 = nil, nil
    local ok = pcall(function() p0, q0 = comp:GetLocalPosition(), comp:GetLocalOrientation() end)
    if not ok or not p0 then
      why = "its skeleton's component does not say where it is"
    elseif math.abs(p0.x) + math.abs(p0.y) + math.abs(p0.z) > 0.05 or (q0 and q0.r and math.abs(q0.r) < 0.999) then
      why = string.format("its skeleton's component is not on its object's place (%.2f, %.2f, %.2f)", p0.x, p0.y, p0.z)
    end
  end
  PS.holdTries149 = (PS.holdTries149 or 0) + 1
  if why then
    if PS.holdTries149 <= FPC.fist.hold149.lines then log("GRAB AND TOSS: the body cannot be put on the hand - " .. why .. " - the game's teleport order as before") end
    return
  end
  Cr.root149, Cr.hold149 = comp, { at = S.clock, n = 0 }
  PS.holds149 = PS.holds149 or {}
  PS.holds149[#PS.holds149 + 1] = { ent = Cr.ent, comp = comp, M = M, Cr = Cr }
end

function FPF.holdFrame149(M, Cr)
  local K, H = FPC.fist.hold149, Cr.hold149
  local hx, hy, hz
  local A = FPF.armR149()
  if A then hx, hy, hz = A.h.x, A.h.y, A.h.z else hx, hy, hz = FPF.tossHand(M) end
  local tx, ty, tz = hx, hy, hz - K.hang
  local p = Cr.ent:GetWorldPosition()
  local eyaw = 0.0
  pcall(function() eyaw = Cr.ent:GetWorldYaw() end)
  local u = clamp((S.clock - H.at) / K.blend, 0.0, 1.0)
  u = u * u * (3.0 - 2.0 * u)
  local dx, dy, dz = (tx - p.x) * u, (ty - p.y) * u, (tz - p.z) * u
  local r = math.rad(eyaw)
  local c, s = math.cos(r), math.sin(r)
  local lx, ly = c * dx + s * dy, -s * dx + c * dy
  local turn = wrap180(PS.yaw + 180.0 - eyaw) * u
  if H.last then
    local b0 = Cr.root149:GetLocalPosition()
    if b0 and math.abs(b0.x - H.last[1]) + math.abs(b0.y - H.last[2]) + math.abs(b0.z - H.last[3]) > 0.05 then
      H.resets = (H.resets or 0) + 1
      if H.resets >= 3 then return false end
    end
  end
  Cr.root149:SetLocalTransform(Vector4.new(lx, ly, dz, 1.0), EulerAngles.ToQuat(EulerAngles.new(0, 0, turn)))
  H.last = { lx, ly, dz }
  H.n = H.n + 1
  H.x, H.y, H.z = p.x + dx, p.y + dy, p.z + dz
  if H.n == 1 then
    local b = Cr.root149:GetLocalPosition()
    if not b or math.abs(b.x - lx) + math.abs(b.y - ly) + math.abs(b.z - dz) > 0.05 then return false end
  end
  if not H.said and S.clock - H.at >= 0.3 then
    H.said = true
    PS.holdSaid149 = (PS.holdSaid149 or 0) + 1
    if PS.holdSaid149 <= K.lines then
      local seen = nil
      pcall(function()
        local t = Cr.root149:GetLocalToWorld().W
        if t then seen = math.sqrt((t.x - tx) ^ 2 + (t.y - ty) ^ 2 + (t.z - tz) ^ 2) end
      end)
      log(string.format("GRAB AND TOSS: 0.3 s into the carry %s is held on the hand by its skeleton's own component, %.1f m from its object (which stays where it was taken)%s",
        tostring(Cr.name), math.sqrt(dx * dx + dy * dy + dz * dz),
        seen and string.format("; the component's place in the world reads %.2f m from where the hand holds it", seen) or "; the component's place in the world cannot be read"))
    end
  end
  return true
end

function FPF.holdBack149(E, why)
  local ok = pcall(function() E.comp:SetLocalTransform(Vector4.new(0.0, 0.0, 0.0, 1.0), Quaternion.new(0.0, 0.0, 0.0, 1.0)) end)
  if E.Cr then E.Cr.root149 = nil end
  PS.holdBacks149 = (PS.holdBacks149 or 0) + 1
  if PS.holdBacks149 <= FPC.fist.hold149.lines then
    local gap = nil
    if E.from then
      pcall(function()
        local p = E.ent:GetWorldPosition()
        gap = math.sqrt((p.x - E.from.x) ^ 2 + (p.y - E.from.y) ^ 2 + (p.z - E.from.z) ^ 2)
      end)
    end
    log(string.format("GRAB AND TOSS: the skeleton put back on its object (%s)%s%s", why, ok and "" or " - it could NOT be set",
      gap and string.format(" - the object is %.1f m from where the body was let go", gap) or ""))
  end
end

function FPF.holdLetGo149(Cr, why)
  local keep = {}
  for _, E in ipairs(PS.holds149 or {}) do
    if E.Cr == Cr then FPF.holdBack149(E, why) else keep[#keep + 1] = E end
  end
  PS.holds149 = keep
  Cr.root149 = nil
end

FPF.tossCarry149p = FPF.tossCarry
function FPF.tossCarry(M)
  local Cr = M.carry
  if not (Cr and Cr.root149 and not Cr.car and not Cr.thrown) then return FPF.tossCarry149p(M) end
  if not IsDefined(Cr.ent) then return end
  local ok, took = pcall(FPF.holdFrame149, M, Cr)
  if ok and took then return end
  FPF.holdLetGo149(Cr, ok and (((Cr.hold149 and (Cr.hold149.resets or 0) >= 3) and "the game puts the skeleton's component back every frame"
    or "the game did not take the skeleton's place") .. " - the teleport order from now on") or ("it went wrong: " .. tostring(took)))
  return FPF.tossCarry149p(M)
end

function FPF.holdsFrame149()
  local L = PS.holds149
  if not L or #L == 0 then return end
  local keep = {}
  for _, E in ipairs(L) do
    local Cr = E.Cr
    if IsDefined(E.ent) then
      local carrying = Cr and Cr.root149 and not Cr.thrown and PS.punch == E.M and E.M.carry == Cr
      local flying = Cr and Cr.thrown and E.till and S.clock < E.till
      if carrying or flying then
        keep[#keep + 1] = E
      else
        FPF.holdBack149(E, (Cr and Cr.thrown) and "thrown" or "the carry ended without a throw")
      end
    end
  end
  PS.holds149 = keep
end

