function FPF.ragdollPush149(ent, x, y, z, ux, uy, uz, power)
  local asked = FPF.ragdoll(ent, x, y, z, 0.0, 0.0, 0.0)
  pcall(function()
    local imp = RagdollApplyImpulseEvent.new()
    imp.worldImpulsePos = Vector4.new(x, y, z, 1.0)
    imp.worldImpulseValue = Vector4.new(ux * power, uy * power, uz * power, 0.0)
    imp.influenceRadius = 2.0
    FPF.later(ent, imp, 0.12)
  end)
  return asked
end

FPF.tossRelease149p = FPF.tossRelease
function FPF.tossRelease(M)
  local Cr = M.carry
  if not Cr or Cr.thrown or Cr.car or not (P.throwAim149 or Cr.root149) then return FPF.tossRelease149p(M) end
  Cr.thrown = true
  local K, H, Kt = FPC.fist.cmd.toss, FPC.fist.hold149, FPC.fist.throw149
  if not IsDefined(Cr.ent) then return end
  local ent = Cr.ent
  if Cr.disabled then pcall(function() ent:MountingEndEnableComponents() end) end
  pcall(function() StatusEffectHelper["StatusEffectHelper::RemoveStatusEffect;GameObjectTweakDBIDUint32"](ent, TweakDBID.new(FPC.fist.stagger.stun)) end)
  local held = Cr.root149 ~= nil and Cr.hold149 ~= nil and Cr.hold149.x ~= nil
  local x, y, z
  if held then
    x, y, z = Cr.hold149.x, Cr.hold149.y, Cr.hold149.z
  else
    local hx, hy, hz = FPF.tossHand(M)
    x, y, z = hx, hy, hz - K.hang
    pcall(function()
      local p = ent:GetWorldPosition()
      x, y, z = p.x, p.y, p.z
    end)
  end
  local ux, uy, uz, rise, by, D = FPF.throwAim149(x, y, z + 1.0, Cr.key, Kt.speed)
  local lx, ly = ux, uy
  local ln = math.sqrt(lx * lx + ly * ly)
  if ln > 0.01 then
    lx, ly = lx / ln, ly / ln
  else
    lx, ly = -math.sin(math.rad(PS.yaw)), math.cos(math.rad(PS.yaw))
  end
  local rec = FPF.gunRecord(FPF.coreOn() and FPC.fist.records.core or FPC.fist.records.heavy)
  FPF.hit(ent, rec, x, y, z + 1.0, lx, ly, 0.0)
  FPF.fistStagger(ent, "toss")
  FPF.ragdollPush149(ent, x, y, z + 0.6, ux, uy, uz, K.throw * Kt.push)
  FPF.punchSound("hit")
  local ahead = math.min(K.landAhead, D or K.landAhead)
  PS.tossLand = { at = S.clock + K.landAfter, x = x + lx * ahead, y = y + ly * ahead, z = PS.z, skip = Cr.key }
  local gap = nil
  if held then
    pcall(function()
      local p = ent:GetWorldPosition()
      gap = math.sqrt((p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - z) ^ 2)
    end)
    for _, E in ipairs(PS.holds149 or {}) do
      if E.Cr == Cr then E.till, E.from = S.clock + H.keep, { x = x, y = y, z = z } end
    end
  end
  log(string.format("GRAB AND TOSS: thrown %s - at %s, %.0f deg up (%.0f deg round) from %s - it lands about %.0f m on",
    S.driving and "where the view points" or "at its foe", by, rise, math.deg(math.atan2(-ux, uy)),
    held and string.format("the hand, where its body is held (its object %.1f m away; the skeleton back on it %.2f s from now)", gap or -1.0, H.keep) or "where it is", ahead))
end

