P.dashRush150 = true
FPC.fist.rush150 = { wind = 2.0, holdAt = 0.30, speed = 30.0, time = 0.5, together = 0.15, lines = 10 }

function FPF.rushFrame150(M, dt)
  local K = FPC.fist.rush150
  local R = M.rush150
  if not R then
    R = { stage = "in", at = S.clock }
    M.rush150 = R
  end
  if R.stage == "in" then
    if M.t < K.holdAt then M.t = math.min(K.holdAt, M.t + dt * (K.wind - 1.0)) end
    if M.t < K.holdAt then return end
    R.stage = "run"
    local ry = math.rad((S.driving and S.yaw) or PS.yaw)
    local fx, fy = -math.sin(ry), math.cos(ry)
    PS.lunge = { x = fx, y = fy, speed = K.speed, t = 0.0, time = K.time }
    R.lunge, R.x0, R.y0, R.till, R.out = PS.lunge, PS.x, PS.y, S.clock + K.time, S.clock - R.at
    if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then PS.dashT = TF.dodgeTime end
    M.t, M.hold = K.holdAt, K.holdAt
    M.lunge = K.speed * K.time
    PS.rushes150 = (PS.rushes150 or 0) + 1
    if PS.rushes150 <= K.lines then
      log(string.format("DASH RUSH %d: the fist out %.2f s after the press - BT goes on along the view at %.0f m/s for %.2f s (%.0f m), the fist held out",
        PS.rushes150, R.out, K.speed, K.time, K.speed * K.time))
    end
  elseif R.stage == "run" then
    M.t, M.hold = K.holdAt, K.holdAt
    if PS.lunge ~= R.lunge or S.clock >= R.till then
      R.stage = "out"
      M.hold = nil
      local met = 0
      for _ in pairs(M.hit or {}) do met = met + 1 end
      if PS.rushes150 <= K.lines then
        log(string.format("DASH RUSH %d: it went %.1f m in %.2f s and met %d on the way - the fist comes back", PS.rushes150,
          math.sqrt((PS.x - R.x0) ^ 2 + (PS.y - R.y0) ^ 2), S.clock - (R.till - K.time), met))
      end
    end
  end
end

FPF.punch150p = FPF.punch
function FPF.punch(dt, ent, key)
  if PS.weapon ~= "fist" or not P.dashRush150 then return FPF.punch150p(dt, ent, key) end
  local K = FPC.fist.rush150
  local U = PS.punch
  if U and U.cmd and U.fistKind == "uppercut" and not U.rushTried150 and (U.t or 0.0) <= K.together
      and PS.dashT ~= nil and PS.dashT <= (U.t or 0.0) + 0.05 and not FPF.coreOn() then
    U.rushTried150 = true
    PS.punch, PS.lunge = nil, nil
    key = true
    PS.rushSwaps150 = (PS.rushSwaps150 or 0) + 1
    if PS.rushSwaps150 <= K.lines then
      log(string.format("DASH RUSH: the dash came %.2f s after the melee key - the uppercut that had begun gives way to the rush", U.t or 0.0))
    end
  end
  local r = FPF.punch150p(dt, ent, key)
  local M = PS.punch
  if M and M.fistKind == "dash" then
    local ok, err = pcall(FPF.rushFrame150, M, dt)
    if not ok then once("rush150" .. tostring(err), "the dash rush could NOT be run (" .. tostring(err) .. ")") end
  end
  return r
end

P.grabMaxTac151 = true

function FPF.maxTac151(ent)
  local rank, kind, name = "", "", ""
  pcall(function() rank = EnumName("gamedataNPCRarity", ent:GetNPCRarity()) end)
  pcall(function() kind = EnumName("gamedataNPCType", ent:GetNPCType()) end)
  pcall(function() name = string.lower(TDBID.ToStringDEBUG(ent:GetRecordID())) end)
  if rank:find("Boss", 1, true) then return false end
  if not (rank:find("MaxTac", 1, true) or name:find("maxtac", 1, true)) then return false end
  if kind:find("Mech", 1, true) or kind:find("Android", 1, true) or kind:find("Drone", 1, true) then return false end
  local no = false
  pcall(function() no = FPF.isMech(ent) == true end)
  if not no then pcall(function() no = ent:IsCharacterCyberpsycho() == true end) end
  if not no then pcall(function() no = FPF.bigTarget(ent) and true or false end) end
  return not no
end

