P.rushAtOnce152 = true
FPC.fist.rush150.wind = 8.0

FPF.rushFrame150p152 = FPF.rushFrame150
function FPF.rushFrame150(M, dt)
  if not P.rushAtOnce152 then return FPF.rushFrame150p152(M, dt) end
  local K = FPC.fist.rush150
  local R = M.rush150
  if not R then
    R = { stage = "in", at = S.clock }
    M.rush150 = R
    local ry = math.rad((S.driving and S.yaw) or PS.yaw)
    local fx, fy = -math.sin(ry), math.cos(ry)
    PS.lunge = { x = fx, y = fy, speed = K.speed, t = 0.0, time = K.time }
    R.lunge, R.x0, R.y0, R.till = PS.lunge, PS.x, PS.y, S.clock + K.time
    R.dashLeft = (PS.dashT ~= nil and PS.dashT < TF.dodgeTime) and (TF.dodgeTime - PS.dashT) or 0.0
    if PS.dashT ~= nil and PS.dashT < TF.dodgeTime then PS.dashT = TF.dodgeTime end
    M.lunge = K.speed * K.time
  end
  if R.stage == "in" then
    if M.t < K.holdAt then M.t = math.min(K.holdAt, M.t + dt * (K.wind - 1.0)) end
    if M.t < K.holdAt then return end
    R.stage = "run"
    R.out = S.clock - R.at
    M.t, M.hold = K.holdAt, K.holdAt
    PS.rushes150 = (PS.rushes150 or 0) + 1
    if PS.rushes150 <= K.lines then
      log(string.format("DASH RUSH %d: BT went on at %.0f m/s from the key on (the dash's own push cut %.2f s short); the fist out %.2f s after the key, held out for the %.2f s of the rush (%.0f m)",
        PS.rushes150, K.speed, R.dashLeft or 0.0, R.out, K.time, K.speed * K.time))
    end
  elseif R.stage == "run" then
    M.t, M.hold = K.holdAt, K.holdAt
    if PS.lunge ~= R.lunge or S.clock >= R.till then
      R.stage = "out"
      M.hold = nil
      local met = 0
      for _ in pairs(M.hit or {}) do met = met + 1 end
      if (PS.rushes150 or 0) <= K.lines then
        log(string.format("DASH RUSH %d: it went %.1f m in %.2f s and met %d on the way - the fist comes back", PS.rushes150 or 0,
          math.sqrt((PS.x - R.x0) ^ 2 + (PS.y - R.y0) ^ 2), S.clock - R.at, met))
      end
    end
  end
end

P.eyeThrow152 = true
function FPF.eyeFrame()
  local ent = PS.ent
  if not ent or not IsDefined(ent) then
    PS.eyeOn, PS.eyeFor = nil, nil
    return
  end
  if S.clock < (PS.eyeAt or 0.0) and PS.eyeFor == PS.id then return end
  PS.eyeAt = S.clock + FPC.eyeLight.every
  local H = PS.hp
  local A = PS.act
  local busy = P.eyeThrow152 and (PS.eject ~= nil or (A ~= nil and A.kind == "leave"))
  local dark = (not P.eyeLight) or PS.kneel ~= nil or (A ~= nil and A.kind == "death")
    or (H ~= nil and (H.health <= 0.0 or H.gone == true) and not busy)
  local want = not dark
  if PS.eyeOn == want and PS.eyeFor == PS.id then return end
  local n = 0
  for _, name in ipairs(FPC.eyeLight.lights) do
    local ok = pcall(function()
      local comp = ent:FindComponentByName(name)
      if not pcall(function() comp:ToggleLight(want) end) then comp:Toggle(want) end
    end)
    if ok then n = n + 1 end
  end
  PS.eyeOn, PS.eyeFor = want, PS.id
  PS.eyeSaid = (PS.eyeSaid or 0) + 1
  if PS.eyeSaid <= 12 then
    log(string.format("BT's eye: its light %s (%d of its %d lights)%s", want and "on" or "off", n, #FPC.eyeLight.lights,
      (want and busy and H ~= nil and (H.health <= 0.0 or H.gone == true)) and " - its health is gone, but it is at work: it takes V out, throws V and leaves" or ""))
  end
end

