P.smokeCover152 = true
FPC.esmoke.cover152 = { miss = 0.5, big = 0.6, chest = 4.0, eye = 1.6, lines = 12 }

function FPF.cloudsOut152()
  local out = {}
  local K = FPC.esmoke
  for _, C in ipairs(PS.clouds or {}) do
    if S.clock - C.at < K.life then out[#out + 1] = C end
  end
  return out
end

function FPF.smokeCovered152(x, y, z)
  local K = FPC.esmoke
  local cz = PS.z + FPC.esmoke.cover152.chest
  for _, C in ipairs(FPF.cloudsOut152()) do
    local r = C.outer or K.outer
    local top, low = C.z + K.high, C.z - 1.0
    if math.sqrt((PS.x - C.x) ^ 2 + (PS.y - C.y) ^ 2) <= r and PS.z <= top then return C, "BT stands in it" end
    if x then
      local dx, dy, dz = PS.x - x, PS.y - y, cz - z
      local L2 = dx * dx + dy * dy
      local u = (L2 > 1e-6) and clamp(((C.x - x) * dx + (C.y - y) * dy) / L2, 0.0, 1.0) or 0.0
      local px, py, pz = x + dx * u, y + dy * u, z + dz * u
      if math.sqrt((px - C.x) ^ 2 + (py - C.y) ^ 2) <= r and pz >= low and pz <= top and u > 0.0 and u < 1.0 then return C, "it stands between" end
    end
  end
  return nil
end

function FPF.smokeMiss152(who, x, y, z, big, what)
  if not P.smokeCover152 or not PS.ent then return false end
  local C, why = FPF.smokeCovered152(x, y, z)
  if not C then return false end
  local K = FPC.esmoke.cover152
  local key = tostring(who or "?")
  PS.smokeRolls152 = PS.smokeRolls152 or {}
  local R = PS.smokeRolls152[key]
  if R and R.at == S.clock then return R.miss end
  local miss = math.random() < (big and K.big or K.miss)
  PS.smokeRolls152[key] = { at = S.clock, miss = miss }
  PS.smokeShots152 = (PS.smokeShots152 or 0) + 1
  if miss then PS.smokeMisses152 = (PS.smokeMisses152 or 0) + 1 end
  if PS.smokeShots152 <= K.lines then
    log(string.format("SMOKE COVER: %s at BT through the smoke (%s) - %s (%d of %d such shots missed so far; %.0f %% for %s)",
      tostring(what), why, miss and "MISSED" or "it hit", PS.smokeMisses152 or 0, PS.smokeShots152, (big and K.big or K.miss) * 100.0,
      big and "tanks, bosses, mechs" or "people"))
  end
  return miss
end

FPF.hitSeen152p = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  local H = PS.hp
  if not H or not evt or PS.act then return FPF.hitSeen152p(evt, tag) end
  local who, kind = nil, ""
  pcall(function() who = evt.attackData:GetInstigator() end)
  pcall(function() kind = EnumName("gamedataAttackType", evt.attackData:GetAttackType()) end)
  local isMelee = kind:find("Melee", 1, true) ~= nil
  local isBlast = kind:find("Explosion", 1, true) ~= nil
  if P.smokeCover152 and who and not isMelee then
    local own = false
    pcall(function() own = who:IsPlayer() == true end)
    if not own then
      local p, big, key, what = nil, false, nil, "?"
      pcall(function() p = who:GetWorldPosition() end)
      pcall(function() local _, w = FPF.coreWorth(who); big = (w == "a boss") end)
      pcall(function() key = tostring(who:GetEntityID()) end)
      pcall(function() what = TDBID.ToStringDEBUG(who:GetRecordID()) end)
      if p and FPF.smokeMiss152(key, p.x, p.y, p.z + FPC.esmoke.cover152.eye, big, what) then return end
    end
  end
  if isBlast and P.mainPerks152 then
    local r = FPF.perkValue("blastres")
    if r > 0 then
      local before = H.pend[tag] or 0.0
      local res = FPF.hitSeen152p(evt, tag)
      local after = H.pend[tag] or 0.0
      if after > before then
        H.pend[tag] = before + (after - before) * (1.0 - r)
        PS.blastSaved152 = (PS.blastSaved152 or 0.0) + (after - before) * r
        once("blastres152", string.format("BLAST PLATING: an explosion's hit on BT takes %.0f %% less", r * 100.0))
      end
      return res
    end
  end
  return FPF.hitSeen152p(evt, tag)
end

function FPF.recordBlast152(record)
  PS.recBlast152 = PS.recBlast152 or {}
  local v = PS.recBlast152[record]
  if v == nil then
    v = false
    pcall(function() v = tostring(TDBID.ToStringDEBUG(TweakDB:GetFlat(record .. ".attackType"))):find("Explosion", 1, true) ~= nil end)
    PS.recBlast152[record] = v
  end
  return v
end

FPF.bossHit152p = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind)
  if PS.ent and kind ~= "melee" and type(x) == "number" and type(y) == "number" then
    if FPF.smokeMiss152(tostring(who) .. "|" .. tostring(record), x, y, z or PS.z, true, tostring(who) .. " (" .. tostring(record) .. ")") then
      return true, "missed", 0
    end
  end
  if P.mainPerks152 and (kind == "blast" or FPF.recordBlast152(tostring(record))) then
    local r = FPF.perkValue("blastres")
    if r > 0 then
      local t0 = P.toughness
      P.toughness = (t0 or 1.0) / (1.0 - r)
      local ok, a, b, c = pcall(FPF.bossHit152p, record, x, y, z, dx, dy, who, kind)
      P.toughness = t0
      if not ok then error(a, 0) end
      once("blastres152b", string.format("BLAST PLATING: another mod's blast on BT takes %.0f %% less", r * 100.0))
      return a, b, c
    end
  end
  return FPF.bossHit152p(record, x, y, z, dx, dy, who, kind)
end

P.mainPerks152 = true
function FPF.mainPerksSetup152()
  local K = FPC.perk
  for _, id in ipairs({ "hull", "armor", "blastres" }) do
    local seen = false
    for _, o in ipairs(K.order) do if o == id then seen = true end end
    if not seen then K.order[#K.order + 1] = id end
  end
  K.max.hull, K.max.armor, K.max.blastres = 3, 3, 3
  K.names.hull, K.names.armor, K.names.blastres = "HULL PLATING", "SHIELD CYCLER", "BLAST PLATING"
  K.values.hull = { 0, 1, 2, 3 }
  K.values.armor = { 6.0, 5.5, 5.0, 4.5 }
  K.values.blastres = { 0.0, 0.1, 0.2, 0.4 }
end
FPF.mainPerksSetup152()
FPC.health152 = { segment = FPC.health.segment, segments = FPC.health.segments, shieldDelay = FPC.health.shieldDelay }

function FPF.hull152(level)
  local B = FPC.health152
  if level >= 3 then return B.segment, B.segments + 1 end
  return B.segment * (1.0 + level / (3.0 * B.segments)), B.segments
end

function FPF.mainPerksApply152(why)
  if not P.mainPerks152 then return end
  local K = FPC.health
  local seg, n = FPF.hull152(FPF.perk("hull"))
  local delay = FPF.perkValue("armor")
  if K.segment == seg and K.segments == n and K.shieldDelay == delay then return end
  local was = K.segment * K.segments
  K.segment, K.segments, K.shieldDelay = seg, n, delay
  local H = PS.hp
  local full = seg * n
  if H and H.health and H.health > full then H.health = full end
  log(string.format("TITAN MAIN (%s): BT's health %.0f (%d segments of %.0f; was %.0f), the shield back after %.1f s without a hit, explosions take %.0f %% less",
    tostring(why), full, n, seg, was, delay, FPF.perkValue("blastres") * 100.0))
end

FPF.perkFrame152p = FPF.perkFrame
function FPF.perkFrame()
  local r = FPF.perkFrame152p()
  local ok, err = pcall(FPF.mainPerksApply152, "the Titan loadout")
  if not ok then once("mainperks152" .. tostring(err), "TITAN MAIN could NOT be put on BT: " .. tostring(err)) end
  return r
end

function FPF.segW152(segW, gap, n)
  if not P.mainPerks152 then return segW end
  local base = FPC.health152.segments
  if n == base then return segW end
  return (base * segW + (base - 1) * gap - (n - 1) * gap) / n
end

