P.aiRam152 = true
FPC.ai.ram152 = { range = 140.0, up = 1.8, names = { "maxtac_ram", "police_ram", "eblc_crab" }, shieldGap = 4.0, shieldHold = 2.5,
  near = 12.0, lines = 8 }

function FPF.ramFind152()
  local K = FPC.ai.ram152
  local best, bd = nil, K.range
  local ex, ey, ez = PS.x, PS.y, PS.z + FPC.buddy.eye
  for _, veh in ipairs(FPF.vehicles()) do
    if IsDefined(veh) and not FPF.isWreck(veh) then
      local name = string.lower(FPF.vehicleText(veh))
      local ram = false
      for _, w in ipairs(K.names) do
        if name:find(w, 1, true) then ram = true end
      end
      if ram then
        local ok, p = pcall(function() return veh:GetWorldPosition() end)
        if ok and p then
          local d = math.sqrt((p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2)
          if d < bd and FPF.buddyClear(ex, ey, ez, p.x, p.y, p.z + K.up) then
            best, bd = { ent = veh, x = p.x, y = p.y, z = p.z + K.up, name = name }, d
          end
        end
      end
    end
  end
  if best then best.dist = bd end
  return best
end

FPF.buddyLook152p = FPF.buddyLook
function FPF.buddyLook(B)
  if not (P.aiRam152 and B) or S.driving then return FPF.buddyLook152p(B) end
  local had = (B.target and B.target.ram152) and B.target or nil
  if had then B.target = nil end
  FPF.buddyLook152p(B)
  local fight = P.buddyFire ~= 3 and not B.off and not P.peace
  if fight and P.buddyFire == 2 then
    fight = false
    pcall(function() fight = Game.GetPlayer():IsInCombat() == true end)
  end
  if not fight or FPF.guardPlain() or (B.target and B.target.designated) then return end
  local R = FPF.ramFind152()
  if not R then
    if had then FPF.buddySay("ramlost", 4, "the RAM is down or out of sight - back to the people") end
    return
  end
  local K = FPC.ai.ram152
  if had and FPF.sameEnt(had.ent, R.ent) then
    had.x, had.y, had.z, had.dist, had.seenAt = R.x, R.y, R.z, R.dist, S.clock
    B.target = had
  else
    B.target = { ent = R.ent, x = R.x, y = R.y, z = R.z, up = K.up, dist = R.dist, at = S.clock, seenAt = S.clock,
      shots0 = (B.gun and B.gun.shots) or 0, ram152 = true, what = R.name }
    PS.ramTargets152 = (PS.ramTargets152 or 0) + 1
    if PS.ramTargets152 <= K.lines then
      log(string.format("BT on its own takes on the RAM (%s, %.0f m) before any person: it faces it, fires at it, its vortex shield goes up at it", R.name, R.dist))
    end
  end
  B.foeAt = S.clock
end

FPF.aiSkillsRun152p = FPF.aiSkillsRun
function FPF.aiSkillsRun(B, A, dt, T)
  if P.aiRam152 and P.aiSkills and T and T.ram152 and not B.off and PS.punch == nil then
    local V, K = PS.vortex, FPC.ai.ram152
    if V and not V.on and (V.frac or 1.0) <= 0.15 and S.clock - (A.ramShieldAt or -100.0) >= K.shieldGap and (T.dist or 0.0) > K.near then
      PS.keyN.vortex, PS.keyTill.vortex = PS.keyN.vortex + 1, S.clock + K.shieldHold
      A.ramShieldAt, A.shieldAt, A.shields = S.clock, S.clock, (A.shields or 0) + 1
      PS.ramShields152 = (PS.ramShields152 or 0) + 1
      if PS.ramShields152 <= K.lines then
        FPF.aiSay(A, string.format("it raises the vortex shield at the RAM (%.0f m) - its shells are caught from the front and go back at it", T.dist or 0.0))
      end
    end
  end
  return FPF.aiSkillsRun152p(B, A, dt, T)
end

