P.socketArms153 = true

P.fxValid153 = true
-- Tables keyed by an effect instance, which the interpreter this controller was written for let its collector empty
-- (weak keys), are kept in two generations of plain tables: a key survives at least one `period` after its last write.
function FPF.gen2(period) return { cur = {}, old = {}, at = 0.0, period = period } end
function FPF.gen2get(G, key)
  local v = G.cur[key]
  if v == nil then v = G.old[key] end
  return v
end
function FPF.gen2set(G, key, value)
  if S.clock - G.at >= G.period then G.old, G.cur, G.at = G.cur, {}, S.clock end
  G.cur[key] = value
end
FPC.fxValid152.seen = FPF.gen2(60.0)

function FPF.fxLive152(inst)
  if inst == nil then return false end
  if not P.fxValid152 then return true end
  local ok, v = pcall(function() return inst:IsValid() end)
  if not ok then
    once("fxvalid152", "effects: FxInstance.IsValid could NOT be asked (" .. tostring(v) .. ") - the script's calls go out as before t152")
    return true
  end
  local seen = FPC.fxValid152.seen
  if v then
    if P.fxValid153 then pcall(function() FPF.gen2set(seen, inst, true) end) end
    return true
  end
  if P.fxValid153 then
    local was = false
    pcall(function() was = FPF.gen2get(seen, inst) == true end)
    if not was then
      PS.fxYoung153 = (PS.fxYoung153 or 0) + 1
      return true
    end
  end
  PS.fxDead152 = (PS.fxDead152 or 0) + 1
  if PS.fxDead152 <= FPC.fxValid152.lines then
    log(string.format("effects: a call to an effect the game had ended (it was there before) was not made (%d this session)", PS.fxDead152))
  end
  return false
end

P.aiRail153 = true
FPC.perk.rail.ai153 = { every = 0.5, near = 120.0, line = 3, wide = 2.5, from = 3.0, lines = 8 }
FPC.perk.rail.aiChargeBig153 = FPC.perk.rail.aiCharge

function FPF.aiRailPlan153(T)
  local K, R = FPC.perk.rail.ai153, FPC.perk.rail
  local big, why = false, nil
  for _, ent in ipairs(PS.npcs or {}) do
    if not big and IsDefined(ent) then
      pcall(function()
        if not ScriptedPuppet.IsActive(ent) or ent:IsHostile() ~= true then return end
        local p = ent:GetWorldPosition()
        if (p.x - PS.x) ^ 2 + (p.y - PS.y) ^ 2 > K.near * K.near then return end
        local _, w = FPF.coreWorth(ent)
        if w == "a boss" then
          big = true
          why = "a boss-class foe"
          pcall(function() why = TDBID.ToStringDEBUG(ent:GetRecordID()) end)
        end
      end)
    end
  end
  if not big and P.aiRam152 then
    local ok, Rm = pcall(FPF.ramFind152)
    if ok and Rm then big, why = true, Rm.name end
  end
  if big then return "charged", R.aiChargeBig153, why end
  local full = R.charge * FPF.perkValue("railcharge") / (FPF.coreOn() and FPC.perk.core.rate or 1.0)
  if T and FPF.perk("railgun") > 0 then
    local dx, dy = T.x - PS.x, T.y - PS.y
    local n = math.sqrt(dx * dx + dy * dy)
    if n > 1.0 then
      dx, dy = dx / n, dy / n
      local count = 0
      for _, ent in ipairs(PS.npcs or {}) do
        if IsDefined(ent) then
          pcall(function()
            if not ScriptedPuppet.IsActive(ent) or ent:IsHostile() ~= true then return end
            local p = ent:GetWorldPosition()
            local ax, ay = p.x - PS.x, p.y - PS.y
            local along = ax * dx + ay * dy
            if along >= K.from and along <= R.range and math.abs(ax * dy - ay * dx) <= K.wide then count = count + 1 end
          end)
        end
      end
      if count >= K.line then return "pierce", full * (R.pierceFrom - 1.0) / (R.levels - 1.0) + 0.02, count end
    end
  end
  return "rapid", 0.0, nil
end

FPF.railFrame153p = FPF.railFrame
function FPF.railFrame(G, W, dt, ent, firing)
  if not P.aiRail153 or S.driving then return FPF.railFrame153p(G, W, dt, ent, firing) end
  local R = FPC.perk.rail
  if S.clock >= (G.aiPlanAt153 or 0.0) then
    G.aiPlanAt153 = S.clock + R.ai153.every
    local T = PS.buddy and PS.buddy.target
    local ok, plan, secs, why = pcall(FPF.aiRailPlan153, T)
    if ok and plan then
      if plan ~= G.aiPlan153 then
        PS.aiRailSays153 = (PS.aiRailSays153 or 0) + 1
        if PS.aiRailSays153 <= R.ai153.lines then
          log(string.format("RAILGUN, BT on its own: %s", (plan == "charged") and ("charged shots - " .. tostring(why) .. " is near")
            or ((plan == "pierce") and string.format("charged to the piercing step - %s foes on its line of fire", tostring(why))
            or "uncharged shots as fast as the gun lets it - only small fry around")))
        end
      end
      G.aiPlan153, G.aiSecs153 = plan, secs
    end
  end
  local keep = R.aiCharge
  if G.aiSecs153 ~= nil then R.aiCharge = G.aiSecs153 end
  local ok, err = pcall(FPF.railFrame153p, G, W, dt, ent, firing)
  R.aiCharge = keep
  if not ok then error(err, 0) end
end

P.fxBorn154 = true
FPC.fxBorn154 = { young = 0.25, most = 96, lines = 6, born = FPF.gen2(5.0) }

function FPF.fxBirth154(inst)
  local K = FPC.fxBorn154
  pcall(function() FPF.gen2set(K.born, inst, S.clock) end)
  local L = PS.fxYoung154 or {}
  if #L < K.most then L[#L + 1] = inst end
  PS.fxYoung154 = L
end

function FPF.fxIsYoung154(inst)
  if PS.fxSpawning154 then return true end
  local at = nil
  pcall(function() at = FPF.gen2get(FPC.fxBorn154.born, inst) end)
  return at ~= nil and S.clock - at <= FPC.fxBorn154.young
end

FPF.fxAt154p = FPF.fxAt
function FPF.fxAt(...)
  PS.fxSpawning154 = true
  local inst = FPF.fxAt154p(...)
  PS.fxSpawning154 = false
  if inst ~= nil then FPF.fxBirth154(inst) end
  return inst
end

FPF.fxAtAxes154p = FPF.fxAtAxes
function FPF.fxAtAxes(...)
  PS.fxSpawning154 = true
  local inst = FPF.fxAtAxes154p(...)
  PS.fxSpawning154 = false
  if inst ~= nil then FPF.fxBirth154(inst) end
  return inst
end

function FPF.fxLive152(inst)
  if inst == nil then return false end
  if not P.fxValid152 then return true end
  local ok, v = pcall(function() return inst:IsValid() end)
  if not ok then
    once("fxvalid152", "effects: FxInstance.IsValid could NOT be asked (" .. tostring(v) .. ") - the script's calls go out as before t152")
    return true
  end
  local seen = FPC.fxValid152.seen
  if v then
    if P.fxValid153 then pcall(function() seen[inst] = true end) end
    return true
  end
  if P.fxValid153 then
    local was = false
    pcall(function() was = seen[inst] == true end)
    if not was then
      if not P.fxBorn154 or FPF.fxIsYoung154(inst) then
        PS.fxYoung153 = (PS.fxYoung153 or 0) + 1
        return true
      end
      PS.fxLate154 = (PS.fxLate154 or 0) + 1
      if PS.fxLate154 <= FPC.fxBorn154.lines then
        log(string.format("effects: a call to an effect never seen running, spawned more than %.2f s before, was not made (%d this session) - t153 made it",
          FPC.fxBorn154.young, PS.fxLate154))
      end
      return false
    end
  end
  PS.fxDead152 = (PS.fxDead152 or 0) + 1
  if PS.fxDead152 <= FPC.fxValid152.lines then
    log(string.format("effects: a call to an effect the game had ended (it was there before) was not made (%d this session)", PS.fxDead152))
  end
  return false
end

function FPF.fxPoll154()
  PS.fxSpawning154 = false
  local L = PS.fxYoung154
  if not L or #L == 0 then return end
  local keep, seen = {}, FPC.fxValid152.seen
  for i = 1, #L do
    local inst = L[i]
    local ok, v = pcall(function() return inst:IsValid() end)
    if ok and v then
      pcall(function() seen[inst] = true end)
