FPF.aiSentryWant155p = FPF.aiSentryWant
function FPF.aiSentryWant(B, T)
  local R = FPC.aiTactics.sentry.ram155
  if not (P.aiSentryRam155 and B and T and T.ram152 and R.guns[PS.weapon or "xo16"]) then return FPF.aiSentryWant155p(B, T) end
  local K = FPC.aiTactics.sentry
  if not P.aiTactics or B.off or P.peace or P.hold or B.chase or B.board or (B.dist or 0.0) > K.vNear then return false end
  if S.clock < (B.sentryLookAt or 0.0) then return false end
  B.sentryLookAt = S.clock + K.look
  if FPF.guardPlain() or FPF.questHeld() ~= nil or S.clock - (T.seenAt or -10.0) > 1.0 then return false end
  local ok, why = FPF.sentryCan()
  if not ok then
    PS.aiSentryNo155 = (PS.aiSentryNo155 or 0) + 1
    if PS.aiSentryNo155 <= R.lines then log("BT on its own would crouch at the RAM, not now: " .. tostring(why)) end
    return false
  end
  return true, string.format("a RAM, %s %.0f m away: behind SENTRY MODE's front shield it keeps firing", tostring(T.what or "?"), T.dist or 0.0)
end

FPF.aiSentryFrame155p = FPF.aiSentryFrame
function FPF.aiSentryFrame(B, dt)
  local Q = PS.sentry
  if not (P.aiSentryRam155 and Q and Q.ai and Q.ram155 and Q.stage ~= "out") then
    local had = PS.sentry
    FPF.aiSentryFrame155p(B, dt)
    local N = PS.sentry
    if P.aiSentryRam155 and N and N ~= had and N.ai and B.target and B.target.ram152 then
      N.ram155, N.ramSeen155 = true, S.clock
      PS.aiSentryRams155 = (PS.aiSentryRams155 or 0) + 1
    end
    return
  end
  local K, R = FPC.aiTactics.sentry, FPC.aiTactics.sentry.ram155
  local T = B.target
  if T and T.ram152 then Q.ramSeen155 = S.clock end
  local why = nil
  if S.clock - (Q.ramSeen155 or Q.at) > R.lostFor then
    why = "the RAM is down or out of sight"
  elseif B.chase or B.off or P.hold or (B.dist or 0.0) > K.vNear then
    why = "it is to go"
  end
  if why then
    FPF.sentryEnd(why)
    if (PS.aiSentryRams155 or 0) <= R.lines then log("BT on its own gets up from its crouch at the RAM: " .. why) end
  end
  local go, most = B.go, K.most
  B.go, K.most = false, math.huge
  local ok, err = pcall(FPF.aiSentryFrame155p, B, dt)
  B.go, K.most = go, most
  if not ok then error(err, 0) end
end

