function FPF.breatheWanted156()
  return S.driving == true and PS.godOn == true
end

function FPF.breatheSet156(on, why)
  local K = FPC.breathe156
  local player = Game.GetPlayer()
  K.said = K.said or 0
  if on then
    if K.state or not player then return end
    local mod, ok, err = nil, false, nil
    ok, err = pcall(function()
      mod = RPGManager.CreateStatModifier(gamedataStatType.CanBreatheUnderwater, gameStatModifierType.Additive, 1.0)
      Game.GetStatsSystem():AddModifier(player:GetEntityID(), mod)
    end)
    if not ok or not mod then
      if not K.failed then
        K.failed = true
        log("under water: V could not be given the breath of BT's cockpit (" .. tostring(err) .. ") - V's oxygen runs as the game says")
      end
      return
    end
    K.state = { mod = mod, who = player:GetEntityID() }
    local had = false
    pcall(function()
      local id = TweakDBID.new(K.oxygen)
      had = StatusEffectSystem.ObjectHasStatusEffect(player, id) == true
      if had then StatusEffectHelper["StatusEffectHelper::RemoveStatusEffect;GameObjectTweakDBIDUint32"](player, id) end
    end)
    pcall(function() ScriptedPuppet.ReevaluateOxygenConsumption(player) end)
    K.said = K.said + 1
    if K.said <= K.lines then
      log(string.format("under water: V aboard breathes - CanBreatheUnderwater on V (%s)%s", why, had and "; V's OutOfOxygen taken off" or ""))
    end
  else
    local B = K.state
    if not B then return end
    K.state = nil
    pcall(function() Game.GetStatsSystem():RemoveModifier(B.who, B.mod) end)
    if player then pcall(function() ScriptedPuppet.ReevaluateOxygenConsumption(player) end) end
    K.said = K.said + 1
    if K.said <= K.lines then log(string.format("under water: V's breath of BT's cockpit taken off again (%s) - V's oxygen is the game's", why)) end
  end
end

function FPF.breatheFrame156()
  if not P.breathe156 then return end
  if S.clock < (S.breatheAt156 or 0.0) then return end
  S.breatheAt156 = S.clock + FPC.breathe156.every
  local want = FPF.breatheWanted156()
  if want and not FPC.breathe156.state then
    FPF.breatheSet156(true, "V went aboard")
  elseif not want and FPC.breathe156.state then
    FPF.breatheSet156(false, S.driving and "V's protection is off" or "V is out of BT")
  end
end

