P.promptAnyKey157 = true

function FPF.promptRaw157()
  if not S.keysOk then return false end
  if S.padLast then return FPF.keyFor("embarkKey") ~= "Pad_X_SQUARE" end
  return FPF.keyName("embarkKey") ~= "F"
end

function FPF.promptKey()
  if not FPF.promptRaw157() then return true end
  return P.promptAnyKey157 == true and PS.embarkRawOk157 ~= false
end

function FPF.prompt(on)
  local K = FPC.prompt
  if PS.promptOk == false then return end
  local raw = on and FPF.promptRaw157()
  local shown, rawFailed = false, nil
  local ok, err = pcall(function()
    local defs = Game.GetAllBlackboardDefs().UIInteractions
    local bb = Game.GetBlackboardSystem():Get(defs)
    local now = nil
    pcall(function() now = FromVariant(bb:GetVariant(defs.InteractionChoiceHub)) end)
    if on then
      if now and now.active and now.id ~= K.id then return end
      local choice = nil
      if raw then
        local okc, c = pcall(function()
          local sys = Game.GetScriptableSystemsContainer():Get(CName.new("BT7274.BT7274Keys"))
          return sys:EmbarkChoice(S.padLast == true, K.text)
        end)
        if not okc or c == nil then
          rawFailed = tostring(c)
          return
        end
        choice = c
      else
        choice = gameinteractionsvisInteractionChoiceData.new()
        choice.inputAction = K.action
        choice.isHoldAction = true
        choice.localizedName = K.text
      end
      local hub = gameinteractionsvisInteractionChoiceHubData.new()
      hub.id, hub.active, hub.title = K.id, true, K.title
      hub.choices = { choice }
      bb:SetVariant(defs.InteractionChoiceHub, Variant("gameinteractionsvisInteractionChoiceHubData", hub), true)
      local info = gameinteractionsvisVisualizersInfo.new()
      info.activeVisId = K.id
      info.visIds = { K.id }
      bb:SetVariant(defs.VisualizersInfo, Variant("gameinteractionsvisVisualizersInfo", info), true)
      shown = true
    elseif now and now.id == K.id then
      local hub = gameinteractionsvisInteractionChoiceHubData.new()
      hub.id, hub.active = K.id, false
      bb:SetVariant(defs.InteractionChoiceHub, Variant("gameinteractionsvisInteractionChoiceHubData", hub), true)
      local info = gameinteractionsvisVisualizersInfo.new()
      info.activeVisId = -1
      bb:SetVariant(defs.VisualizersInfo, Variant("gameinteractionsvisVisualizersInfo", info), true)
    end
  end)
  if rawFailed then
    PS.embarkRawOk157 = false
    once("embarkraw157", "the embark hint with the key " .. FPF.keyWord("embarkKey") .. " cannot be the game's own prompt (the key script has no EmbarkChoice: "
      .. rawFailed .. ") - this script draws its own line for a key other than F")
  end
  if not ok then
    PS.promptOk, PS.promptOn, PS.promptShown = false, false, false
    log("the embark hint cannot be shown as the game's own prompt (" .. tostring(err) .. ") - this script draws its own line, as up to t30")
    return
  end
  PS.promptOn, PS.promptShown, PS.promptAt = on, shown, S.clock + K.every
  if shown then
    once("promptshown", "the embark hint is the game's own interaction prompt now (its use key, held; it gives way to a prompt of the game's own)")
    if raw then
      local key = FPF.keyWord("embarkKey")
      if key ~= PS.promptRawSaid157 then
        PS.promptRawSaid157 = key
        log("the embark hint is the game's own prompt with the embark key of Mod Settings: " .. key .. " (held)")
      end
    end
  end
end

