function FPF.vShieldSet158(on, why)
  local K = FPC.vShield158
  local player = Game.GetPlayer()
  K.said = K.said or 0
  if on then
    if K.state or not player then return end
    local mods, err = {}, nil
    for _, name in ipairs(K.stats) do
      local ok, e = pcall(function()
        local mod = RPGManager.CreateStatModifier(gamedataStatType[name], gameStatModifierType.Additive, 1.0)
        if Game.GetStatsSystem():AddModifier(player:GetEntityID(), mod) ~= false then mods[#mods + 1] = mod end
      end)
      if not ok then err = tostring(e) end
    end
    K.state = { mods = mods, who = player:GetEntityID() }
    K.said = K.said + 1
    if K.said <= K.lines then
      log(string.format("V aboard: %d of %d immunities on V as stats (%s)%s", #mods, #K.stats, why, err and (" - " .. err) or ""))
    end
  else
    local B = K.state
    if not B then return end
    K.state = nil
    for _, mod in ipairs(B.mods) do pcall(function() Game.GetStatsSystem():RemoveModifier(B.who, mod) end) end
    K.said = K.said + 1
    if K.said <= K.lines then log(string.format("V aboard: the immunities taken off V again (%s)", why)) end
  end
end

function FPF.godImm158(on)
