    else
      sys:RemoveGodMode(id, gameGodModeType.Immortal, CName.new("bt_pilot"))
    end
  end)
  K.imm = on and ok
  if not ok then once("godimm158" .. tostring(err), "V cannot be made immortal while piloting: " .. tostring(err)) end
end

