function FPF.vShieldFrame158()
  if not P.vShield158 then return end
  local K = FPC.vShield158
  if S.clock < (S.vShieldAt158 or 0.0) then return end
  S.vShieldAt158 = S.clock + K.every
  local want = S.driving == true and PS.godOn == true
  if want and not K.state then
    FPF.vShieldSet158(true, "V went aboard")
  elseif not want and K.state then
    FPF.vShieldSet158(false, S.driving and "V's protection is off" or "V is out of BT")
  end
  if not want or S.clock < (S.vShieldLook158 or 0.0) then return end
  S.vShieldLook158 = S.clock + K.look
  local player = Game.GetPlayer()
  if not player then return end
  local has = true
  pcall(function() has = StatusEffectSystem.ObjectHasStatusEffect(player, TweakDBID.new(K.immune)) == true end)
  if not has then
    pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](player, TweakDBID.new(K.immune)) end)
    K.immBack = (K.immBack or 0) + 1
    if K.immBack <= 6 then log("V aboard: " .. K.immune .. " was gone from V (" .. K.immBack .. ") - put back (the immunities as stats hold meanwhile)") end
  end
  if K.imm then
    local still = true
    pcall(function() still = Game.GetGodModeSystem():HasGodMode(player:GetEntityID(), gameGodModeType.Immortal) == true end)
    if not still then
      K.imm = false
      FPF.godImm158(true)
      K.immLost = (K.immLost or 0) + 1
      if K.immLost <= 6 then log("V aboard: V's god mode Immortal was gone (" .. K.immLost .. ") - put back") end
    end
  end
end

