FPF.bossHit157 = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind, scale)
  if type(scale) == "number" and scale > 0.0 and scale < 1.0 then
    local t0 = P.toughness
    P.toughness = (t0 or 1.0) / scale
    local ok, a, b, c = pcall(FPF.bossHit157, record, x, y, z, dx, dy, who, kind)
    P.toughness = t0
    if not ok then error(a, 0) end
    return a, b, c
  end
  return FPF.bossHit157(record, x, y, z, dx, dy, who, kind)
end

