  cut = 0.1, link = { chance = 0.2, cut = 0.5 }, full = { chance = 0.35, cut = 0.5, shield = 0.01 }, cap = 0.6 }
P.protocols159 = true
FPC.proto159 = {
  ids = { "proto1", "proto2", "proto3" },
  names = { "LINK TO PILOT", "UPHOLD THE MISSION", "PROTECT THE PILOT" },
  say = { every = 120.0, try = 0.5, within = 6.0, line = { "bt7274_say_engage_3", "Protocol 3: Protect The Pilot.", 2.72 } },
  pings = { "bt7274_hull_ping_1", "bt7274_hull_ping_2", "bt7274_hull_ping_3" },
  spark = [[base\fx\weapons\impacts\metal\large_cal\imp_metal_refl_lc.effect]],
