  colors = { { 0.37, 0.96, 1.0 }, { 1.0, 0.72, 0.25 }, { 0.62, 0.80, 1.0 } } }

function FPF.protoSetup159()
  local K, Q, SP = FPC.perk, FPC.proto159, FPC.proto159spec
  for i, id in ipairs(Q.ids) do
    local seen = false
    for _, o in ipairs(K.order) do if o == id then seen = true end end
    if not seen then K.order[#K.order + 1] = id end
    K.max[id] = #SP.values[id] - 1
    K.names[id] = "PROTOCOL " .. i .. " (" .. Q.names[i] .. ")"
    K.values[id] = SP.values[id]
  end
  FPC.say.kinds.protocol = { every = Q.say.every, lines = { Q.say.line } }
end
FPF.protoSetup159()

function FPF.proto159()
  local L = PS.proto159
  if not L then
    L = { till = { -1.0, -1.0, -1.0 }, lit = 0, n = { 0, 0, 0 }, rolls = {}, cued = {}, rollsAt = nil, cuts = 0, deflects = 0,
      capped = 0, shieldBack = 0.0, linkT = 0.0, fullT = 0.0, links = 0, fulls = 0, said = 0, sayTill = nil, sayTryAt = 0.0,
      empAt = -100.0, flashAt = -100.0, cueAt = -100.0, bossN = 0, lines = 0 }
    PS.proto159 = L
  end
  return L
end

function FPF.protoOn159(i)
  local L = PS.proto159
  return L ~= nil and L.till[i] > S.clock
end

function FPF.protoCount159()
  local L = PS.proto159
  if not L then return 0 end
  local n = 0
  for i = 1, 3 do
    if L.till[i] > S.clock then n = n + 1 end
  end
  return n
end

function FPF.protoLight159(i, why)
  if not P.protocols159 or not PS.ent then return false end
  local Q = FPC.proto159
  local secs = FPF.perkValue(Q.ids[i])
  if type(secs) ~= "number" or secs <= 0.0 then return false end
  local L = FPF.proto159()
  local was = L.till[i] > S.clock
  if S.clock + secs > L.till[i] then L.till[i] = S.clock + secs end
  if not was then
    L.n[i] = L.n[i] + 1
    if L.lines < Q.lines then
      L.lines = L.lines + 1
      log(string.format("PROTOCOL %d (%s) lit by %s for %.0f s - lamps lit: %d", i, Q.names[i], tostring(why), secs, FPF.protoCount159()))
    end
  end
  return true
end

function FPF.protoEmp159()
  local Q, L = FPC.proto159, FPF.proto159()
  L.empAt = S.clock
  if not P.fxOn then return end
  pcall(FPF.fxOnSlot, Q.emp, "hip", Q.empLife)
end

function FPF.protoCue159(full, fx, fy)
  local Q, SP, L, H = FPC.proto159, FPC.proto159spec, FPF.proto159(), PS.hp
  L.deflects = L.deflects + 1
  if full and H and not H.doomed and not H.gone then
    local was = H.shield
    H.shield = math.min(FPC.health.shield, H.shield + FPC.health.shield * SP.full.shield)
    L.shieldBack = L.shieldBack + (H.shield - was)
  end
  if S.clock - L.cueAt < Q.cueGap then return end
  L.cueAt = S.clock
  if P.fxOn and PS.ent then
    pcall(function()
      local p = slotWorld("hip")
      if not p then return end
      local ux, uy = fx, fy
      if not ux then
        local r = math.rad(PS.yaw or 0.0)
        ux, uy = -math.sin(r), math.cos(r)
      end
      FPF.fxAt(Q.spark, p.x + ux * Q.sparkOut, p.y + uy * Q.sparkOut, p.z + Q.sparkUp, math.deg(math.atan2(-ux, uy)), 0.0)
    end)
  end
  if S.driving and P.sounds then pcall(FPF.tf, Q.pings[math.random(#Q.pings)]) end
end

function FPF.protoCut159(other, key, fx, fy)
  local SP = FPC.proto159spec
  local n = FPF.protoCount159()
  if n <= 0 then return 1.0 end
  local L = FPF.proto159()
  if L.rollsAt ~= S.clock then L.rolls, L.cued, L.rollsAt = {}, {}, S.clock end
  local plain = (1.0 - SP.cut) ^ n
  local m = plain
  local D = (n >= 3) and SP.full or ((n >= 2) and SP.link or nil)
  local hit = false
  if D then
    local r = L.rolls[key]
    if r == nil then
      r = math.random() < D.chance
      L.rolls[key] = r
    end
    hit = r
    if hit then m = m * (1.0 - D.cut) end
  end
  local least = 1.0 - SP.cap
  local o = clamp(other or 1.0, 0.0, 1.0)
  local capped = false
  if o * m < least then
    m = (o > least) and (least / o) or 1.0
    capped = true
  end
  if not L.cued[key] then
    L.cued[key] = true
    L.cuts = L.cuts + 1
    if capped then
      L.capped = L.capped + 1
      once("protocap159", string.format("PROTOCOLS: a hit's cuts together reached %.0f %% - the lamps gave only what was left to it", SP.cap * 100.0))
    end
    if hit and m < plain - 1e-9 then FPF.protoCue159(n >= 3, fx, fy) end
  end
  return m
end

function FPF.protoKill159(evt)
  local A, target = evt.attackData, evt.target
  if not A or not target then return end
  local killing = false
  pcall(function() killing = A:HasFlag(hitFlag.WasKillingBlow) == true end)
  if not killing then return end
  local mine = false
  pcall(function() mine = tostring(A:GetSource():GetEntityID()) == tostring(PS.ent:GetEntityID()) end)
  if not mine and S.driving then pcall(function() mine = A:GetInstigator():IsPlayer() == true end) end
  if not mine then return end
  local points = nil
  pcall(function() points = FPF.coreWorth(target) end)
  if not points then return end
  FPF.protoLight159(2, "a kill")
end

function FPF.protoFrame159(dt)
  if not P.protocols159 or not PS.ent or not PS.hp then return end
  local Q = FPC.proto159
  if PS.dashT ~= nil or PS.skate ~= nil then FPF.protoLight159(1, PS.skate and "a skate" or "a dash") end
  local why3 = nil
  local R = PS.sentry
  if R and R.stage ~= "out" then
    why3 = "the crouch (SENTRY)"
  elseif PS.swordBlock and PS.swordBlock.on then
    why3 = "the sword's block"
  elseif PS.fistGuard and PS.fistGuard.on then
    why3 = "the fists' guard"
  elseif PS.clouds and #PS.clouds > 0 and FPF.perk("proto3") > 0 then
    local okC, C, w = pcall(FPF.smokeCovered152)
    if okC and C and w == "BT stands in it" then why3 = "its own smoke" end
  end
  if why3 then FPF.protoLight159(3, why3) end
  local L = PS.proto159
  if not L then return end
  local n = FPF.protoCount159()
  if n ~= L.lit then
    if n >= 2 and L.lit < 2 then
      L.links, L.flashAt = L.links + 1, S.clock
      if L.lines < Q.lines then
        L.lines = L.lines + 1
        log(string.format("PROTOCOLS: LINK (%d lamps lit) - %.0f %% of the hits cut by %.0f %% more", n, FPC.proto159spec.link.chance * 100.0, FPC.proto159spec.link.cut * 100.0))
      end
    end
    if n >= 3 and L.lit < 3 then
      L.fulls, L.flashAt, L.sayTill = L.fulls + 1, S.clock, S.clock + Q.say.within
      FPF.protoEmp159()
      if L.lines < Q.lines then
        L.lines = L.lines + 1
        log(string.format("PROTOCOLS: FULL LINK - %.0f %% of the hits cut by %.0f %% more, %.0f %% of the shield back for each",
          FPC.proto159spec.full.chance * 100.0, FPC.proto159spec.full.cut * 100.0, FPC.proto159spec.full.shield * 100.0))
      end
    end
    L.lit = n
  end
  if n >= 2 then L.linkT = L.linkT + (dt or 0.0) end
  if n >= 3 then
    L.fullT = L.fullT + (dt or 0.0)
    if S.clock - L.empAt >= Q.empEvery then FPF.protoEmp159() end
    if L.sayTill and S.clock <= L.sayTill and S.clock >= L.sayTryAt then
      L.sayTryAt = S.clock + Q.say.try
      if FPF.say("protocol") then L.sayTill, L.said = nil, L.said + 1 end
    end
  end
end

