FPF.hitSeen158p = FPF.hitSeen
function FPF.hitSeen(evt, tag)
  if not P.protocols159 or not evt then return FPF.hitSeen158p(evt, tag) end
  if tag == "b" and PS.ent and FPF.perk("proto2") > 0 then
    local ok, err = pcall(FPF.protoKill159, evt)
    if not ok then once("protokill" .. tostring(err), "PROTOCOL 2: a kill could NOT be told: " .. tostring(err)) end
  end
  local H = PS.hp
  if not H or PS.act or FPF.protoCount159() == 0 then return FPF.hitSeen158p(evt, tag) end
  local before, big = H.pend[tag] or 0.0, H.bigV
  local r = FPF.hitSeen158p(evt, tag)
  local after = H.pend[tag] or 0.0
  if after > before then
    local raw, onV, key, fx, fy = 0.0, false, "?", nil, nil
    pcall(function() raw = evt.attackComputed:GetTotalAttackValue(gamedataStatPoolType.Health) end)
    pcall(function() onV = evt.target:IsPlayer() == true end)
    raw = math.max(tonumber(raw) or 0.0, 0.0) * (onV and 1.0 or (P.decoyShare or 1.0))
    pcall(function()
      local who = evt.attackData:GetInstigator()
      key = tostring(who:GetEntityID())
      local p = who:GetWorldPosition()
      local dx, dy = p.x - PS.x, p.y - PS.y
      local d = math.sqrt(dx * dx + dy * dy)
      if d > 0.5 then fx, fy = dx / d, dy / d end
    end)
    local other = (raw > 1e-6) and ((after - before) / raw) or 1.0
    local m = FPF.protoCut159(other, "h" .. key, fx, fy)
    if m < 1.0 then
      H.pend[tag] = before + (after - before) * m
      if H.bigV and H.bigV ~= big then H.bigV = H.bigV * m end
    end
  end
  return r
end

FPF.bossHit158p = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind, scale)
  local H = PS.hp
  if not H then return FPF.bossHit158p(record, x, y, z, dx, dy, who, kind) end
  local k = (type(scale) == "number" and scale > 0.0 and scale < 1.0) and scale or 1.0
  local blast = 0.0
  if P.mainPerks152 and (kind == "blast" or FPF.recordBlast152(tostring(record))) then blast = FPF.perkValue("blastres") or 0.0 end
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local mp = P.mainPerks152
  P.mainPerks152 = false
  local okC, ok, what, pts = pcall(FPF.bossHit158p, record, x, y, z, dx, dy, who, kind)
  P.mainPerks152 = mp
  if not okC then error(ok, 0) end
  if ok and (what == "caught" or what == "parried") and P.protocols159 then
    FPF.protoLight159(3, (what == "caught") and "a blow caught by the vortex shield" or "a parry")
  end
  if not (ok and what == "taken") then return ok, what, pts end
  local added = H.pend.a - a0
  if added <= 0.0 then return ok, what, pts end
  local share = nil
  pcall(function() share = FPF.bossShare(record) end)
  local raw = (type(share) == "number" and share > 0.0) and share * H.vMax or added
  local m = 1.0
  if P.protocols159 and FPF.protoCount159() > 0 then
    local fx, fy = nil, nil
    if type(x) == "number" and type(y) == "number" then
      local ddx, ddy = x - PS.x, y - PS.y
      local d = math.sqrt(ddx * ddx + ddy * ddy)
      if d > 0.5 then fx, fy = ddx / d, ddy / d end
    end
    local L = FPF.proto159()
    L.bossN = L.bossN + 1
    m = FPF.protoCut159(clamp(added / raw, 0.0, 1.0) * (1.0 - blast), "b" .. L.bossN, fx, fy)
  end
  local f = k * (1.0 - blast) * m
  if f < 1.0 then
    H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * f, b0 + (H.pend.b - b0) * f
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * f end
    if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken - (pts or 0.0) * (1.0 - f) end
    pts = (pts or 0.0) * f
    if blast > 0.0 then once("blastres159", string.format("BLAST PLATING: another mod's blast on BT takes %.0f %% less (what BT takes, not only what is answered)", blast * 100.0)) end
    if k < 1.0 then once("bossscale159", "a blow's share from another mod (the police RAM's range) cuts what BT takes, not only what is answered") end
  end
  return ok, what, pts
end

