function FPF.protoHud159(dl)
  if not P.protocols159 then return end
  local Q = FPC.proto159
  local have, any = {}, false
  for i, id in ipairs(Q.ids) do
    have[i] = FPF.perk(id) > 0
    any = any or have[i]
  end
  if not any then return end
  local L = PS.proto159
  local sw, sh = render.size()
  local U = PS.slotUi
  local k = math.min(sh / 2160.0, sw / 3840.0)
  local right, top
  if U and U.at then
    right, top, k = U.at.x + U.at.wide, U.at.y, U.at.k
  else
    local K = FPC.slots
    right = sw - FPF.hudEdge(sw, sh) - K.right * k
    top = sh - (K.bottom + K.slot[2] + K.keyGap + K.key) * k
  end
  local Hd = Q.hud
  local s, gap = Hd.size * k, Hd.gap * k
  local y0 = top - Hd.above * k - s
  local x0 = right - (3.0 * s + 2.0 * gap)
  local mid = y0 + s * 0.5
  local n = FPF.protoCount159()
  local flash = (L and L.flashAt) and clamp(1.0 - (S.clock - L.flashAt) / Hd.flash, 0.0, 1.0) or 0.0
  local pulse = (n >= 3) and (0.75 + 0.25 * math.sin(S.clock * 7.0)) or 1.0
  local function col(c, a) return GetColorU32(c[1], c[2], c[3], a) end
  local white = { 1.0, 1.0, 1.0 }
  for i = 1, 2 do
    if have[i] and have[i + 1] and FPF.protoOn159(i) and FPF.protoOn159(i + 1) then
      render.line(x0 + (i - 1) * (s + gap) + s, mid, x0 + i * (s + gap), mid, col(white, 0.85 * pulse), math.max(2.0, Hd.line * k))
    end
  end
  local t = math.max(1.0, Hd.frame * k)
  for i = 1, 3 do
    local x = x0 + (i - 1) * (s + gap)
    local c = Q.colors[i]
    local on = have[i] and FPF.protoOn159(i)
    local a = have[i] and (on and 0.95 or 0.40) or 0.15
    render.line(x, y0, x + s, y0, col(c, a), t)
    render.line(x + s, y0, x + s, y0 + s, col(c, a), t)
    render.line(x + s, y0 + s, x, y0 + s, col(c, a), t)
    render.line(x, y0 + s, x, y0, col(c, a), t)
    if on then
      local inset = Hd.inset * k
      render.line(x + inset, mid, x + s - inset, mid, col(c, math.min(1.0, (0.55 + 0.35 * flash) * pulse)), s - 2.0 * inset)
      local secs = FPF.perkValue(Q.ids[i])
      local left = (type(secs) == "number" and secs > 0.0) and clamp((L.till[i] - S.clock) / secs, 0.0, 1.0) or 0.0
      local yb = y0 + s + Hd.bar * k
      render.line(x, yb, x + s, yb, col({ 0.0, 0.0, 0.0 }, 0.5), Hd.bar * k)
      render.line(x, yb, x + s * left, yb, col(c, 0.95), Hd.bar * k)
    end
  end
  if n >= 2 then
    local word = (n >= 3) and "FULL LINK" or "LINK"
    FPF.label(dl, x0, y0 - FPF.lineH() - 6.0 * k, col((n >= 3) and Q.colors[3] or white, 0.95), word, "r", right)
  end
end

