P.aiMelee160, P.waveShield160 = true, true
FPC.aiMelee160 = { slashGap = 0.5, finisher = 0.7, jabCone = 35.0, electricGap = 6.0,
  retreat = { window = 2.0, share = 0.10, time = { 1.2, 1.6 }, gap = 8.0, dash = true, fresh = 0.5 }, lines = 10 }
FPC.sword.waveShield160 = 0.1

function FPF.meleeBurst160()
  local H, R = PS.hp, FPC.aiMelee160.retreat
  if not H then return 0.0 end
  local taken = H.taken or 0.0
  local Z = PS.burst160
  if not Z or Z.hp ~= H or S.clock - Z.at > R.fresh or taken < Z.last then
    Z = { hp = H, last = taken, at = S.clock, list = {} }
    PS.burst160 = Z
  end
  local gain = taken - Z.last
  Z.last, Z.at = taken, S.clock
  if gain > 0.0 then Z.list[#Z.list + 1] = { at = S.clock, pts = gain } end
  local sum, keep = 0.0, {}
  for _, e in ipairs(Z.list) do
    if S.clock - e.at <= R.window then
      sum = sum + e.pts
      keep[#keep + 1] = e
    end
  end
  Z.list = keep
  return sum / (FPC.health.segment * FPC.health.segments + FPC.health.shield)
end

FPF.swordChase160p = FPF.swordChase
function FPF.swordChase(B, dt)
  if not P.aiMelee160 then return FPF.swordChase160p(B, dt) end
  local K = FPC.aiMelee160
  local R = K.retreat
  local C = B.chase
  if C then
    C.need, C.nearNeed = math.huge, math.huge
    if C.retreat160 and C.mode == "back" and C.till == nil and PS.slash == nil and PS.jab == nil and PS.punch == nil then
      C.till = S.clock + FPF.aiDashGap(R.time)
    end
  end
  local share = FPF.meleeBurst160()
  C = FPF.swordChase160p(B, dt)
  if not C then return C end
  C.need, C.nearNeed = math.huge, math.huge
  if C.mode ~= "back" then C.retreat160 = nil end
  local M, J = PS.slash, PS.jab
  if C.mode == "close" and share >= R.share and S.clock - (PS.retreatAt160 or -1000.0) >= R.gap and (M == nil or M.done)
      and (J == nil or J.done) and PS.punch == nil and PS.fistCharge == nil and PS.spin == nil and PS.dashT == nil and PS.lunge == nil then
    C.mode, C.till, C.backDash, C.backDashed, C.retreat160, B.detour = "back", nil, R.dash, false, true, nil
    PS.slashAsk = nil
    PS.retreatAt160 = S.clock
    if PS.burst160 then PS.burst160.list = {} end
    if B.sword then B.sword.backs = (B.sword.backs or 0) + 1 end
    PS.retreats160 = (PS.retreats160 or 0) + 1
    if PS.retreats160 <= K.lines then
      log(string.format("BT on its own, the %s: it steps back once - %.1f %% of its health and shield taken within %.1f s (the mark is %.0f %%; its foe %.1f m away)",
        (PS.weapon == "fist") and "fists" or "broadsword", share * 100.0, R.window, R.share * 100.0, (B.target and B.target.dist) or -1.0))
    end
  end
  return C
end

