function FPF.fistAiFire160(firing)
  local Bd = PS.buddy
  local C, T = Bd and Bd.chase, Bd and Bd.target
  if not C or not T or not T.ent then return firing end
  if C.mode == "back" or (T.dist or 1000.0) > FPC.fistAI.jabReach or S.clock - (T.seenAt or -10.0) > 0.5 then return false end
  local off = math.abs(wrap180(math.deg(math.atan2(-(T.x - PS.x), T.y - PS.y)) - (Bd.yaw or PS.yaw)))
  return off <= FPC.aiMelee160.jabCone
end

