function FPF.waveShield160(W, ent)
  if PS.weapon ~= "sword" or not FPF.coreOn() then return end
  local hostile = false
  pcall(function() hostile = OP77.targetHostile(ent) == true end)
  if not hostile then return end
  local H = PS.hp
  if not H or H.doomed or H.gone then return end
  local was = H.shield
  H.shield = math.min(FPC.health.shield, H.shield + FPC.health.shield * FPC.sword.waveShield160)
  W.shield160 = (W.shield160 or 0) + 1
  if H.shield <= was then return end
  PS.waveShields160 = (PS.waveShields160 or 0) + 1
  if PS.waveShields160 <= FPC.sword.lines then
    log(string.format("ARC WAVE in the core: it met a foe (%d in this wave) - BT's shield %.0f -> %.0f of %.0f (+%.0f %% a foe)",
      W.shield160, was, H.shield, FPC.health.shield, FPC.sword.waveShield160 * 100.0))
  end
end

