  FPF.waveMeet160p(W, ent, kind, x, y, z, rec)
  if P.waveShield160 and W and W.step ~= nil and kind == "person" and (W.people or 0) > n0 then
    local ok, err = pcall(FPF.waveShield160, W, ent)
    if not ok then once("waveshield160" .. tostring(err), "ARC WAVE in the core: the shield could NOT be given back (" .. tostring(err) .. ")") end
  end
end

P.ramGuard161 = true
FPC.ramGuard161 = { leash = 90.0, renew = 0.25, lines = 8 }

function FPF.ramCloseIn161()
  local Bd = PS.buddy
  if not P.ramGuard161 or S.driving or not Bd or Bd.state ~= "active" then return nil end
  if PS.weapon ~= "sword" and PS.weapon ~= "fist" then return nil end
  local C, T = Bd.chase, Bd.target
  if not C or not T or not T.ram152 or C.mode ~= "close" then return nil end
  local reach = (PS.weapon == "sword") and math.max(FPF.swordReach(), FPC.swordAI.reach) or FPC.fistAI.jabReach
  if (T.dist or 0.0) <= reach then return nil end
  return C, T
end

function FPF.ramGuard161(G, K, free, dt, what)
  if not G.on then G.ram161 = nil end
  local C, T = FPF.ramCloseIn161()
  if not C or not free then return end
  local Z = PS.ramGuard161
  if not Z then
    Z = { ups = 0, downs = 0 }
    PS.ramGuard161 = Z
  end
  if G.on and G.ram161 then
    G.energy = math.max(0.0, G.energy - K.drain * dt)
    if G.energy <= 0.0 then
      G.on, G.aiTill, G.ram161, G.idle = false, nil, nil, 0.0
      Z.downs = Z.downs + 1
      if Z.downs <= FPC.ramGuard161.lines then log("BT on its own: its " .. what .. " is down at the RAM - its energy is gone") end
      return
    end
    G.aiTill = S.clock + FPC.ramGuard161.renew
  elseif not G.on and G.energy >= K.least then
    G.on, G.ups, G.upAt, G.ram161 = true, (G.ups or 0) + 1, S.clock, true
    G.aiTill = S.clock + FPC.ramGuard161.renew
    FPF.swordSound(FPC.sword.sounds.raise, FPF.viewVolume())
    Z.ups = Z.ups + 1
    if Z.ups <= FPC.ramGuard161.lines then
      log(string.format("BT on its own: its %s up as it closes in on the RAM (%s, %.0f m) - its shells from in front at x %.2f (energy %.0f)",
        what, tostring(T.what), T.dist or -1.0, K.take, G.energy))
    end
  end
end

