FPF.bossHit162p = FPF.bossHit
function FPF.bossHit(record, x, y, z, dx, dy, who, kind, scale)
  local H = PS.hp
  if not (P.bossScaleUp162 and H and type(scale) == "number" and scale > 1.0) then
    return FPF.bossHit162p(record, x, y, z, dx, dy, who, kind, scale)
  end
  local k = math.min(scale, FPC.bossScaleUp162.most)
  local a0, b0, big = H.pend.a, H.pend.b, H.bigV
  local ok, what, pts = FPF.bossHit162p(record, x, y, z, dx, dy, who, kind)
  if ok and what == "taken" and H.pend.a - a0 > 0.0 then
    H.pend.a, H.pend.b = a0 + (H.pend.a - a0) * k, b0 + (H.pend.b - b0) * k
    if H.bigV and H.bigV ~= big then H.bigV = H.bigV * k end
    if PS.boss and type(PS.boss.taken) == "number" then PS.boss.taken = PS.boss.taken + (pts or 0.0) * (k - 1.0) end
    pts = (pts or 0.0) * k
    once("bossscale162", string.format("a blow's share above whole from another mod (the police RAM's damage factor): BT takes x%.2f of it", k))
  end
  return ok, what, pts
end

