function FPF.statusBy(ent, status, by)
  local id = FPC.statusIds166[status]
  if id == nil then
    id = TweakDBID.new(status)
    FPC.statusIds166[status] = id
  end
  if OP77.statusObserved(ent, status) then return end
  if by ~= nil and pcall(function() StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDEntityID"](ent, id, by) end) then return end
  StatusEffectHelper["StatusEffectHelper::ApplyStatusEffect;GameObjectTweakDBIDFloat"](ent, id)
end

function FPF.hazardHit166(Z, ent, i, p, by, rec)
  local K = (Z.kind == "fire") and FPC.perk.incendiary or FPC.perk.gas
  if rec then
    local send = P.fullHits and FPF.hitFull or FPF.hit
    if send(ent, rec, p.x, p.y, p.z + 1.0, 0.0, 0.0, -1.0) == true then Z.hurts = (Z.hurts or 0) + 1 end
  end
  local key = FPF.npcKeyAt(i)
  if not key then return end
  if Z.seen[key] and S.clock - Z.seen[key] < K.again then return end
  Z.seen[key] = S.clock
  FPF.statusBy(ent, K.status, by)
  if Z.blinds then FPF.statusBy(ent, K.blind, by) end
  Z.hits = Z.hits + 1
end

FPF.hazardsFrame165p = FPF.hazardsFrame
function FPF.hazardsFrame()
  if not P.hazards166 then return FPF.hazardsFrame165p() end
  local L = PS.hazards
  if not L or #L == 0 then return end
  local due = PS.hazDue166
  if due then
    for k = #due, 1, -1 do due[k] = nil end
  else
    due = {}
    PS.hazDue166 = due
  end
  for i = #L, 1, -1 do
    local Z = L[i]
    local age = S.clock - Z.at
    if age >= Z.life + FPC.hazard.linger or not PS.ent then
      for _, inst in ipairs(Z.fx) do FPF.fxKill152(inst) end
      table.remove(L, i)
    elseif age >= Z.life then
      if not Z.ended then
        Z.ended = true
        for _, inst in ipairs(Z.fx) do FPF.fxBreak152(inst) end
      end
    elseif S.clock >= Z.tickAt and FPF.heavyTurn("fire and gas") then
      local K = (Z.kind == "fire") and FPC.perk.incendiary or FPC.perk.gas
      Z.tickAt = (math.floor(S.clock / K.tick) + 1.0) * K.tick
      due[#due + 1] = Z
    end
  end
  if #due == 0 then return end
  local by = nil
  pcall(function() by = Game.GetPlayer():GetEntityID() end)
  PS.npcsAt = -10
  refreshNpcs()
  local gasRec = nil
  if P.damage and FPF.gunRecord(FPC.hazard.gasHurt) == FPC.hazard.gasHurt then gasRec = FPC.hazard.gasHurt end
  local high = FPC.hazard.high
  for i, ent in ipairs(PS.npcs) do
    local p = FPF.npcAt(i)
    if p then
      local active = nil
      for _, Z in ipairs(due) do
        if not (math.sqrt((p.x - Z.x) ^ 2 + (p.y - Z.y) ^ 2) > Z.wide * 0.5 or p.z < Z.z - 2.0 or p.z > Z.z + high) then
          if active == nil then
            active = false
            pcall(function() active = IsDefined(ent) and OP77.targetActive(ent) == true end)
          end
          if active then
            local ok, err = pcall(FPF.hazardHit166, Z, ent, i, p, by, (Z.kind == "gas") and gasRec or nil)
            if not ok then once("hazhit166" .. tostring(err), "a fire or a cloud could NOT reach someone: " .. tostring(err)) end
          end
        end
      end
    end
  end
  if gasRec then
    for _, Z in ipairs(due) do
      if Z.kind == "gas" and (Z.hurts or 0) > 0 and not Z.hurtSaid then
        Z.hurtSaid = true
        PS.gasLines = (PS.gasLines or 0) + 1
        if PS.gasLines <= 6 then log(string.format("GAS: the cloud hurts whoever is in it every %.1f s (%s)", FPC.perk.gas.tick, gasRec)) end
      end
    end
  end
end

