FPC.edge168 = { deep = 1500.0, below = 30.0, atV = 10.0, near = 2.0, ring = 5.0, lines = 8 }
P.pilotDeep168, P.buddyDrop168 = true, true

function FPF.groundDeep168(x, y, z)
  local best = nil
  for _, group in ipairs({ "Static", "Terrain" }) do
    pcall(function()
      local hit, res = FPF.sqs():SyncRaycastByCollisionGroup(Vector4.new(x, y, z + 3.0, 1.0),
        Vector4.new(x, y, z - FPC.edge168.deep, 1.0), group, nil, false, false)
      if hit and res and res.position then
        local hz = res.position.z
        if best == nil or hz > best then best = hz end
      end
    end)
  end
  return best
end

function FPF.deepEdge168(g, z, who)
  if PS.jump and PS.jump.stage == "air" then return end
  PS.deepEdges168 = (PS.deepEdges168 or 0) + 1
  if PS.deepEdges168 <= FPC.edge168.lines then
    log(string.format("DEEP EDGE %d (t168, %s): nothing within 30 m under the next step - %s", PS.deepEdges168, who,
      g and string.format("the long ray finds the ground %.1f m down", z - g) or "nor within the long ray"))
  end
end

function FPF.pilotDeep168(x, y, z)
  if not P.pilotDeep168 then return nil end
  local g = FPF.groundDeep168(x, y, z)
  FPF.deepEdge168(g, z, "piloted")
  return g
end

FPF.pilotProbe168 = { wall = PROBE.wall, ground = PROBE.ground, deep = FPF.pilotDeep168 }

function FPF.buddyDrop168(B)
  if not P.buddyDrop168 or S.driving or not B or B.off or P.hold or B.vz == nil then return false end
  if B.target or B.chase or PS.lunge or PS.dashT ~= nil then return false end
  if FPF.fightOn() then return false end
  return PS.z - B.vz > FPC.edge168.below
end

function FPF.aiDeep168(x, y, z)
  local B = PS.buddy
  if not (B and B.drop168 and B.vx) then return nil end
  local n0 = math.sqrt((PS.x - B.vx) ^ 2 + (PS.y - B.vy) ^ 2)
  local n1 = math.sqrt((x - B.vx) ^ 2 + (y - B.vy) ^ 2)
  if PS.jump and PS.jump.stage == "air" then
    local R0 = FPC.edge168.ring
    if math.abs(n1 - R0) > math.abs(n0 - R0) + 1e-6 then return nil end
  elseif n1 >= n0 then
    return nil
  end
  local g = FPF.groundDeep168(x, y, z)
  if g and g < B.vz - FPC.edge168.atV then
    if not (PS.jump and PS.jump.stage == "air") then
      PS.deepPast168 = (PS.deepPast168 or 0) + 1
      if PS.deepPast168 <= FPC.edge168.lines then
        log(string.format("DEEP EDGE (t168, on its own): the ground under the next step lies %.1f m under V - it does not go over there",
          B.vz - g))
      end
    end
    return nil
  end
  FPF.deepEdge168(g, z, string.format("on its own, V %.0f m under it", PS.z - B.vz))
  return g
end

FPF.aiProbe168 = { wall = PROBE.wall, ground = PROBE.ground, deep = FPF.aiDeep168 }

FPF.buddyLook167 = FPF.buddyLook
function FPF.buddyLook(B)
  FPF.buddyLook167(B)
  if B and FPF.buddyDrop168(B) then
    if not B.drop168 then
      PS.drops168 = (PS.drops168 or 0) + 1
      if PS.drops168 <= FPC.edge168.lines then
        log(string.format("BT on its own (t168): V is %.0f m under it, %.0f m off on the map - it goes after V, over an edge if one lies that way",
          PS.z - B.vz, B.dist or -1.0))
      end
    end
    B.drop168, B.go = true, true
  elseif B then
    B.drop168 = nil
  end
end

FPF.buddyActive167 = FPF.buddyActive
function FPF.buddyActive(B, dt)
  if B.drop168 and not FPF.buddyDrop168(B) then B.drop168 = nil end
  return FPF.buddyActive167(B, dt)
end

FPF.buddyHeading167 = FPF.buddyHeading
function FPF.buddyHeading(B)
  if not B.drop168 then return FPF.buddyHeading167(B) end
  local dx, dy = B.vx - PS.x, B.vy - PS.y
  local n = math.sqrt(dx * dx + dy * dy)
  if PS.jump and PS.jump.stage == "air" then
    local R0 = FPC.edge168.ring
    if math.abs(n - R0) < 0.5 then return nil end
    if n < 0.05 then return 1.0, 0.0, R0 end
    local k = (n > R0) and 1.0 or -1.0
    return k * dx / n, k * dy / n, math.abs(n - R0)
  end
  if n < FPC.edge168.near then return nil end
  return dx / n, dy / n, n
end

FPC.edge169 = { up = 6.0, ahead = { 0.0, 2.0, 4.0, 6.0 }, most = 60.0, back = 20.0, again = 30.0, lines = 8 }
P.voidFall169 = true

function FPF.voidRay169(x, y, z)
  local best = nil
  for _, group in ipairs({ "Static", "Terrain" }) do
    pcall(function()
      local hit, res = FPF.sqs():SyncRaycastByCollisionGroup(Vector4.new(x, y, z + FPC.edge169.up, 1.0),
        Vector4.new(x, y, z - 30.0, 1.0), group, nil, false, false)
      if hit and res and res.position then
        local hz = res.position.z
        if best == nil or hz > best then best = hz end
      end
    end)
  end
  return best
end

function FPF.voidAhead169(x, y, z, ux, uy)
  if not (P.voidFall169 and P.pilotDeep168 and P.falls) then return false end
  local B, K = PS.voidBack169, FPC.edge169
  if B and S.clock < B.till and (x - B.x) ^ 2 + (y - B.y) ^ 2 < K.back * K.back then return false end
  for _, d in ipairs(K.ahead) do
    local g = FPF.voidRay169(x + ux * d, y + uy * d, z)
    if g ~= nil then
      PS.voidGaps169 = (PS.voidGaps169 or 0) + 1
      if PS.voidGaps169 <= K.lines then
        log(string.format("GAP %d (t169): nothing under the next step within either ray, but something %s, %+.1f m against its feet - a rise, or a gap in the floor: it stops there",
          PS.voidGaps169, (d > 0) and string.format("%.0f m further on", d) or "at the step from higher up", g - z))
      end
      return false
    end
  end
  return true
end

function FPF.voidFloor169(air)
  local J = PS.jump
  local U = { x0 = PS.x, y0 = PS.y, z0 = (air and J and J.floor) or PS.z }
  if air and J then
    if not J.unknown169 then
      U.air0, J.unknown169 = J.air, U
      FPF.voidSay169(string.format("a jump carries it out over an edge with no ground loaded under it, %.0f m over where it left the ground",
        math.max(0.0, PS.z - U.z0)))
    end
  else
    PS.voidPending169 = U
  end
  return U.z0 - 2.0 * FPC.edge168.deep
end

function FPF.voidSay169(what)
  PS.voidFalls169 = (PS.voidFalls169 or 0) + 1
  if PS.voidFalls169 <= FPC.edge169.lines then
    log(string.format("FALL INTO THE UNKNOWN %d (t169): %s - the floor is looked for on the way down (a ray of %.0f m, every frame)",
      PS.voidFalls169, what, FPC.edge168.deep))
  end
end

FPF.fallStart168 = FPF.fallStart
function FPF.fallStart(g)
  local U = PS.voidPending169
  PS.voidPending169 = nil
  local ok = FPF.fallStart168(g)
  if ok and U and PS.jump and not PS.jump.unknown169 then
    U.air0, PS.jump.unknown169 = PS.jump.air or 0.0, U
    FPF.voidSay169(string.format("off an edge with no ground loaded under it at %.1f m/s", PS.speed or 0.0))
  end
  return ok
end

FPF.jumpFrame168 = FPF.jumpFrame
function FPF.jumpFrame(dt, f, s)
  local J = PS.jump
  local U = J and J.unknown169
  if U and J.stage == "air" then
    local g = FPF.groundDeep168(PS.x, PS.y, math.max(PS.z, U.zLast or PS.z))
    U.zLast = PS.z
    if g then
      J.floor, J.unknown169 = g, nil
      if (PS.voidFalls169 or 0) <= FPC.edge169.lines then
        log(string.format("FALL INTO THE UNKNOWN %d (t169): the ground came into reach %.1f m under it, %.0f m under where it left the ground, after %.1f s",
          PS.voidFalls169 or 0, PS.z - g, U.z0 - g, J.air - (U.air0 or 0.0)))
      end
    elseif J.air - (U.air0 or 0.0) > FPC.edge169.most or PS.z < U.z0 - FPC.edge168.deep then
      local fell, air = U.z0 - PS.z, J.air - (U.air0 or 0.0)
      J.floor = PS.z
      FPF.jumpEnd("no ground on the way down", true)
      PS.x, PS.y, PS.z = U.x0, U.y0, U.z0
      PS.vx, PS.vy, PS.speed = 0.0, 0.0, 0.0
      PS.voidLost169 = (PS.voidLost169 or 0) + 1
      PS.voidBack169 = { x = U.x0, y = U.y0, till = S.clock + FPC.edge169.again }
      log(string.format("FALL INTO THE UNKNOWN (t169): no ground on the way down for %.1f s, %.0f m: it is put back where it left the ground - that edge stops it for %.0f s",
        air, fell, FPC.edge169.again))
      return
    end
  end
  return FPF.jumpFrame168(dt, f, s)
end

FPF.pilotProbe168.void = FPF.voidAhead169

FPC.edge170 = { vNear = 30.0, lines = 8 }
P.vAir170 = true

FPF.vUnder169 = FPF.vUnder
function FPF.vUnder()
  local J = PS.jump
  if not (P.vAir170 and J and J.stage == "air" and (J.unknown169 or PS.z - J.floor > FPC.edge170.vNear)) then
    return FPF.vUnder169()
  end
  if S.vAirAt170 == S.clock then return end
  S.vAirAt170 = S.clock
  local player = Game.GetPlayer()
  if not player then return end
  Game.GetTeleportationFacility():Teleport(player, Vector4.new(PS.x, PS.y, PS.z + 0.05, 1.0), EulerAngles.new(0, 0, PS.yaw))
  S.vPlaced = { x = PS.x, y = PS.y, z = PS.z + 0.05, at = S.clock, how = "under" }
  S.vStats = S.vStats or FPF.vStats()
  S.vStats.under = S.vStats.under + 1
  S.tethers = S.tethers + 1
  if not J.vAir170 then
    J.vAir170 = true
    PS.vAirs170 = (PS.vAirs170 or 0) + 1
    if PS.vAirs170 <= FPC.edge170.lines then
      log(string.format("V'S BODY IN THE AIR %d (t170): the ground under BT is %s - V's body goes down with BT, at its feet every frame, onto the ground once BT is %.0f m over it",
        PS.vAirs170, J.unknown169 and "not loaded yet" or string.format("%.0f m down", PS.z - J.floor), FPC.edge170.vNear))
    end
  end
end

-- Open77 mission seam (op77_lightrp_titans). What a server mission asks of this controller through the bridge (the server's
-- setHold, setClass and creditKill; open77_titan_bridge.lua): a hold on every control, and a class - a label, a lock on nine
-- abilities, a walk and run speed and a damage multiple. The state is one table of FPF and the gates are wrappers over the controller's own functions,
-- laid over the last of their layers: nothing here is a main-chunk local, the chunk is at Lua's cap.
--   hold   every path a control takes - the game's actions and the Mod Settings keys of FPF.forwarded, a script's FPF.input, the
--          bridge's own presses - meets FPF.actionIn or FPF.bind below; the pilot frame reads FPF.held() again for the movement,
--          fire, reload, zoom, dash, jump and melee, and the climb out and the eject refuse it too (startDismount, FPF.ejectStart).
--          The camera look and the view and shoulder keys are never held.
--   class  the missiles, the vortex shield and the electric smoke go through their frame's `free`; the dash and the jets through
--          the pilot frame's own reading (and FPF.jumpCan, FPF.poundStart); SENTRY MODE through FPF.sentryCan, FLIGHT STRIKE through
--          FPF.flightCan, the TARGET DESIGNATOR through FPF.designate and the core through FPF.coreFire; the speed through
--          pilotStep's wish. The weapon and the loadout are the bridge's (handle_class).
FPF.mission = { held = false, className = nil, allowed = nil, speed = 1.0, harm = 1.0, regen = 1.0 }

function FPF.held()
  return FPF.mission.held == true
end

-- Whether the class lets this ability through; everything is allowed without a class. `ability` is one of the nine names of
-- the resource's shared.lua T.classAbilities (missiles, vortex, smoke, dash, jets, sentry, flight, designator, core).
function FPF.allowed(ability)
  local A = FPF.mission.allowed
  return A == nil or A[ability] == true
end

function FPF.speedMul()
  return FPF.mission.speed
end

-- The hold. Closing it lets go of everything held at that moment (movement, sprint, fire, reload, zoom, the missile and vortex keys
-- and every Mod Settings key); the camera look is left alone. Setting what is already set changes nothing.
function FPF.holdSet(on)
  on = on == true
  local M = FPF.mission
  if M.held == on then return end
  M.held = on
  log("MISSION: the Titan is " .. (on and "held" or "released"))
  if on then guard("the hold's release of the controls", FPF.releaseInput) end
end

-- A class: `class` is { label, abilities = { [name] = boolean }, speed, harm, regen } as the bridge hands it over
-- (open77_titan_schema.lua), or nil for no class: every ability allowed, speed, harm and regen 1. A name the table does not list is
-- not allowed; a speed outside 0.5 .. 1.5 is 1, a harm outside 0.1 .. 50 is 1, a regen outside 0.25 .. 10 is 1.
function FPF.classSet(class)
  local M = FPF.mission
  if type(class) ~= "table" then
    M.className, M.allowed, M.speed, M.harm, M.regen = nil, nil, 1.0, 1.0, 1.0
    return
  end
  local allowed, on = {}, {}
  for name, yes in pairs(type(class.abilities) == "table" and class.abilities or {}) do
    allowed[name] = yes == true
    if yes == true then on[#on + 1] = name end
  end
  table.sort(on)
  local speed = class.speed
  M.className, M.allowed = class.label, allowed
  M.speed = (type(speed) == "number" and speed >= 0.5 and speed <= 1.5) and speed or 1.0
  local harm, regen = class.harm, class.regen
  M.harm = (type(harm) == "number" and harm >= 0.1 and harm <= 50.0) and harm or 1.0
  M.regen = (type(regen) == "number" and regen >= 0.25 and regen <= 10.0) and regen or 1.0
  log(string.format("MISSION: class %s, walk and run x%.2f, damage taken x%.2f, shield back x%.2f slower, abilities: %s", tostring(class.label),
    M.speed, M.harm, M.regen, #on > 0 and table.concat(on, " ") or "none"))
end

-- The hold's one predicate for a control. The camera look is never held; a release, or an axis at zero, always goes through (it can
-- only clear what was pressed); the view and shoulder keys are the camera's too.
FPF.holdLook = { CameraMouseX = true, CameraMouseY = true, CameraX = true, CameraY = true }
FPF.holdKeys = { view = true, shoulder = true }

-- A game action (name, input type, value) the hold refuses.
function FPF.heldAction(name, kind, value)
  if FPF.mission.held ~= true or FPF.holdLook[name] then return false end
  if kind == gameinputActionType.BUTTON_RELEASED then return false end
  if kind == gameinputActionType.AXIS_CHANGE and value == 0 then return false end
  return true
end

-- A Mod Settings key press the hold refuses (a release always goes through).
function FPF.heldKey(name, down)
  return down == true and FPF.mission.held == true and not FPF.holdKeys[name]
end

-- A scripted control (the server's `input`: name, the kind the bridge's schema gave it, value) the hold refuses; the same verdicts as
-- heldAction and heldKey for the kinds' own terms. A control the hold refuses is one the controller never ran, so the bridge does not
-- remember it as held (FPF.input answers false, as for any gate that refused).
function FPF.heldInput(name, kind, value)
  if FPF.mission.held ~= true or FPF.holdLook[name] then return false end
  if kind == "key" then return FPF.heldKey(name, value) end
  if kind == "axis" then return value ~= 0 end
  if kind == "button" then return value == true end
  return false
end

FPF.actionInSeam = FPF.actionIn
function FPF.actionIn(name, kind, value, driveOnly)
  if FPF.heldAction(name, kind, value) then return false end
  return FPF.actionInSeam(name, kind, value, driveOnly)
end

FPF.bindSeam = FPF.bind
function FPF.bind(name, down)
  if FPF.heldKey(name, down) then return end
  return FPF.bindSeam(name, down)
end

FPF.inputSeam = FPF.input
function FPF.input(name, kind, value)
  if FPF.heldInput(name, kind, value) then return false end
  return FPF.inputSeam(name, kind, value)
end

FPF.ejectStartSeam = FPF.ejectStart
function FPF.ejectStart(why)
  if FPF.held() then return end
  return FPF.ejectStartSeam(why)
end

-- The class's lock on each ability, where its key is handled. A lock on `free` is the frame's: no new use starts and what runs is
-- let go; the others refuse the start with the controller's own refusal text.
FPF.mtmsFrameSeam = FPF.mtmsFrame
function FPF.mtmsFrame(dt, free)
  return FPF.mtmsFrameSeam(dt, free and FPF.allowed("missiles") and not FPF.held())
end

FPF.vortexFrameSeam = FPF.vortexFrame
function FPF.vortexFrame(dt, free)
  return FPF.vortexFrameSeam(dt, free and FPF.allowed("vortex") and not FPF.held())
end

-- ARC FIELD: a class whose weapon is the fists (LightRP's Brawler) turns the vortex shield into an electric field around BT. While
-- the shield is up it pulses every `pulse` seconds: a burst on BT, then a wave of effects running out over `rings` (`each` on a
-- ring, one ring every `step` seconds, each ring turned `twist` degrees further and the whole wave `turn` degrees per pulse: a
-- spiral that spins), and every person within `reach` metres (and `high` above or below) takes the fists' blast (`record`, the
-- one BERSERKER's shock blast lands) and is knocked down and electrocuted (FPF.fistStagger's "electric"; a boss is not). It
-- catches rounds from every side, not only the shield's front arc; letting go throws them back as the shield does. Without a class, or with another weapon, the vortex shield is the controller's own.
FPC.arcField = { reach = 16.0, high = 6.0, pulse = 0.4, record = "Attacks.BT7274_Fist_Blast",
  rings = { 4.0, 8.0, 12.0, 16.0 }, each = 10, step = 0.06, twist = 12.0, turn = 18.0, lines = 6,
  fx = { burst = [[ep1\fx\gameplay\player\breach_emp_explosion.effect]], burstUp = 1.5, burstLife = 1.0,
    ring = [[base\fx\devices\_damage\emp\big\d_emp_status_big.effect]], ringUp = 0.3, ringLife = 0.45 } }

function FPF.arcOn()
  return FPF.mission.className ~= nil and PS.weapon == "fist"
end

function FPF.effectFor(path, x, y, z, life)
  local inst = FPF.fxAt(path, x, y, z, nil, nil)
  if inst then PS.fxLive[#PS.fxLive + 1] = { inst = inst, till = S.clock + life } end
end

function FPF.arcPulse(A)
  local K = FPC.arcField
  A.pulses, A.turn = A.pulses + 1, (A.turn + K.turn) % 360.0
  if P.fxOn then
    FPF.effectFor(K.fx.burst, PS.x, PS.y, PS.z + K.fx.burstUp, K.fx.burstLife)
    for i = 1, #K.rings do A.wave[#A.wave + 1] = { at = S.clock + (i - 1) * K.step, i = i } end
  end
  local rec = FPF.gunRecord(K.record)
  for _, T in ipairs(FPF.fistRound(PS.x, PS.y, PS.z, K.reach, K.high)) do
    if T.kind == "person" then
      local d = math.max(T.d, 0.1)
      FPF.hit(T.ent, rec, T.x, T.y, T.z + 1.0, (T.x - PS.x) / d, (T.y - PS.y) / d, 0.0)
      FPF.fistStagger(T.ent, "electric")
      A.hits = A.hits + 1
    end
  end
end

-- The pulse's wave: each ring is laid around BT where it stands when the ring comes due.
function FPF.arcWave(A)
  local K = FPC.arcField
  local kept = {}
  for _, W in ipairs(A.wave) do
    if S.clock >= W.at then
      local r = K.rings[W.i]
      for j = 0, K.each - 1 do
        local a = math.rad(A.turn + (W.i - 1) * K.twist + j * 360.0 / K.each)
        FPF.effectFor(K.fx.ring, PS.x + math.cos(a) * r, PS.y + math.sin(a) * r, PS.z + K.fx.ringUp, K.fx.ringLife)
      end
    else
      kept[#kept + 1] = W
    end
  end
  A.wave = kept
end

function FPF.arcFrame()
  local V, A, K = PS.vortex, PS.arc, FPC.arcField
  if not (V and V.on and PS.ent and FPF.arcOn()) then
    if A then
      PS.arc = nil
      PS.arcLines = (PS.arcLines or 0) + 1
      if PS.arcLines <= K.lines then log(string.format("ARC FIELD down: %d pulse(s), %d hit(s) on people within %.0f m", A.pulses, A.hits, K.reach)) end
    end
    return
  end
  if not A then
    A = { nextAt = S.clock, pulses = 0, hits = 0, turn = 0.0, wave = {} }
    PS.arc = A
  end
  if S.clock >= A.nextAt then
    A.nextAt = S.clock + K.pulse
    FPF.arcPulse(A)
  end
  FPF.arcWave(A)
end

FPF.vortexFrameArc = FPF.vortexFrame
function FPF.vortexFrame(dt, free)
  FPF.vortexFrameArc(dt, free)
  guard("ARC FIELD", FPF.arcFrame)
end

FPF.vortexCatchArc = FPF.vortexCatch
function FPF.vortexCatch(who, evt, tag)
  if not FPF.arcOn() then return FPF.vortexCatchArc(who, evt, tag) end
  local K = FPC.vortex
  local arc = K.arc
  K.arc = 180.0
  local ok, r = pcall(FPF.vortexCatchArc, who, evt, tag)
  K.arc = arc
  if not ok then error(r, 0) end
  return r
end

FPF.smokeFrameSeam = FPF.smokeFrame
function FPF.smokeFrame(dt, free)
  return FPF.smokeFrameSeam(dt, free and FPF.allowed("smoke") and not FPF.held())
end

FPF.jumpCanSeam = FPF.jumpCan
function FPF.jumpCan()
  if not FPF.allowed("jets") then return false, "the class has no jets" end
  return FPF.jumpCanSeam()
end

FPF.poundStartSeam = FPF.poundStart
function FPF.poundStart(...)
  if not FPF.allowed("jets") then return false end
  return FPF.poundStartSeam(...)
end

FPF.sentryCanSeam = FPF.sentryCan
function FPF.sentryCan()
  if not FPF.allowed("sentry") then return false, "SENTRY MODE is not part of this class" end
  return FPF.sentryCanSeam()
end

FPF.flightCanSeam = FPF.flightCan
function FPF.flightCan()
  if not FPF.allowed("flight") then return false, "FLIGHT STRIKE is not part of this class" end
  return FPF.flightCanSeam()
end

FPF.designateSeam = FPF.designate
function FPF.designate(...)
  if not FPF.allowed("designator") then return end
  return FPF.designateSeam(...)
end

-- BARRAGE: a class that has the TARGET DESIGNATOR (LightRP's Northstar) calls rockets down with its key instead. The authored
-- designator works only on foot (FPF.bind117 drops the key while V drives); here, while V pilots, a press marks the foe under
-- the crosshair (FPF.designatePick, then the authored mark: the game's tag, FLIGHT STRIKE's first pick) or, with nobody there,
-- the point the guns aim at within the designator's range, and `delay` seconds later `rockets` come down on it, one every
-- `every` seconds, from `height` metres up and `slant` metres out round it: the first at the marked foe, the rest within `spread`
-- of where it stands then. They fly and blow up as FLIGHT STRIKE's rockets (the missile frame, m.flight: its attack records),
-- with a trail and a second, bigger explosion of their own. A new call waits `cooldown` seconds from the last one. Without a
-- class the key is the authored designator's.
FPC.barrage = { delay = 2.0, rockets = 8, every = 0.18, height = 70.0, slant = 25.0, spread = 5.0, speed = 3.0, cooldown = 16.0,
  lines = 8, fx = { trail = [[base\fx\vehicles\weapons\v_vehicle_rocket_trail.effect]],
    boom = [[ep1\fx\vehicles\chimera\v_chimera_rocket_explosion.effect]], boomLife = 3.0 } }

function FPF.barrageOn()
  return FPF.mission.className ~= nil and FPF.allowed("designator") and FPF.perk("designator") >= 1
end

-- The cell's reading: active from the call until the last rocket leaves, empty while it cools down, ready otherwise. Returns
-- state, the seconds left and the share of the wait done.
function FPF.barrageState()
  local K, B = FPC.barrage, PS.barrage
  if B then return "active", B.fireAt + (K.rockets - 1) * K.every - S.clock, nil end
  local left = (PS.barrageReadyAt or 0.0) - S.clock
  if left > 0.0 then return "empty", left, 1.0 - left / K.cooldown end
  return "ready", nil, nil
end

function FPF.barrageAsk()
  local K = FPC.barrage
  PS.barrageAsks = (PS.barrageAsks or 0) + 1
  local say = PS.barrageAsks <= K.lines
  if PS.barrage then
    if say then log("BARRAGE: one is coming down already") end
    return
  end
  local left = (PS.barrageReadyAt or 0.0) - S.clock
  if left > 0.0 then
    pcall(FPF.tf, FPC.mtms.sounds.dry)
    if say then log(string.format("BARRAGE: not ready for %.1f s", left)) end
    return
  end
  local ent, x, y, z = FPF.designatePick(), nil, nil, nil
  if ent then
    pcall(function() local p = ent:GetWorldPosition(); x, y, z = p.x, p.y, p.z end)
    if x then guard("BARRAGE's mark", FPF.designate118) else ent = nil end
  end
  local A = PS.aim
  if not x and A and A.x and math.sqrt((A.x - PS.x) ^ 2 + (A.y - PS.y) ^ 2) <= FPC.perk.designate.range then
    x, y, z = A.x, A.y, A.z
    pcall(FPF.tf, FPC.mtms.sounds.lock)
  end
  if not x then
    pcall(FPF.tf, FPC.mtms.sounds.dry)
    if say then log(string.format("BARRAGE: nobody and nothing under the crosshair within %.0f m", FPC.perk.designate.range)) end
    return
  end
  PS.barrage = { ent = ent, x = x, y = y, z = z, fireAt = S.clock + K.delay, nextAt = S.clock + K.delay, fired = 0,
    turn = math.random() * 360.0, n = PS.barrageAsks }
  PS.barrageReadyAt = S.clock + K.cooldown
  if say then
    log(string.format("BARRAGE %d: %d rockets in %.1f s on %s %.0f m away", PS.barrageAsks, K.rockets, K.delay,
      ent and "the marked foe" or "the point under the crosshair", math.sqrt((x - PS.x) ^ 2 + (y - PS.y) ^ 2)))
  end
end

function FPF.barrageRocket(B)
  local K, KM = FPC.barrage, FPC.mtms
  if #PS.missiles >= KM.most then return end
  PS.mtms = PS.mtms or FPF.mtmsNew()
  local first = B.fired == 1
  local tx, ty, tz, ent, up = B.x, B.y, B.z, nil, 0.0
  if B.ent and IsDefined(B.ent) and OP77.targetActive(B.ent) then
    pcall(function() local p = B.ent:GetWorldPosition(); tx, ty, tz = p.x, p.y, p.z end)
    B.x, B.y, B.z = tx, ty, tz
    if first then ent, up = B.ent, FPC.buddy.chest end
  end
  if not ent then
    local a, r = math.random() * 2.0 * math.pi, K.spread * math.sqrt(math.random())
    tx, ty = tx + math.cos(a) * r, ty + math.sin(a) * r
  end
  local a = math.rad(B.turn + B.fired * 360.0 / K.rockets)
  local ox, oy, oz = tx + math.cos(a) * K.slant, ty + math.sin(a) * K.slant, tz + K.height
  local dx, dy, dz = tx - ox, ty - oy, tz + up - oz
  local dn = math.sqrt(dx * dx + dy * dy + dz * dz)
  dx, dy, dz = dx / dn, dy / dn, dz / dn
  PS.barrageRockets = (PS.barrageRockets or 0) + 1
  local m = { x = ox, y = oy, z = oz, rx = ox, ry = oy, rz = oz, dx = dx, dy = dy, dz = dz, t = 0.0, gone = 0.0, ent = ent,
    tx = tx, ty = ty, tz = tz + up, up = up, loose = ent == nil, n = PS.barrageRockets, speed = KM.speed * K.speed,
    wob = math.random() * 6.283, fxAt = 0.0, sx = ox, sy = oy, sz = oz, streakAt = S.clock + KM.streak, flight = true, barrage = true }
  if P.fxOn and not PS.noTrail then
    m.trail = FPF.fxAt(K.fx.trail, ox, oy, oz, math.deg(math.atan2(-dx, dy)), math.deg(math.asin(clamp(dz, -1.0, 1.0))))
  end
  PS.missiles[#PS.missiles + 1] = m
end

function FPF.barrageFrame()
  local K = FPC.barrage
  local n = PS.keyN.designate or 0
  if n ~= (PS.barrageSeen or 0) then
    PS.barrageSeen = n
    if FPF.barrageOn() and PS.ent then FPF.barrageAsk() end
  end
  local B = PS.barrage
  if not B then return end
  if not PS.ent or S.gone then
    PS.barrage = nil
    return
  end
  while B.fired < K.rockets and S.clock >= B.nextAt do
    B.fired, B.nextAt = B.fired + 1, B.nextAt + K.every
    FPF.barrageRocket(B)
  end
  if B.fired >= K.rockets then PS.barrage = nil end
end

-- While V pilots, the key is the barrage's (counted here, run by the missile frame); everything else goes on as it did.
FPF.bindBarrage = FPF.bind
function FPF.bind(name, down)
  if name == "designate" and down == true and S.driving and S.pilot and PS.mode == "pilot" and not FPF.held() and FPF.barrageOn() then
    PS.keyN.designate = (PS.keyN.designate or 0) + 1
    return
  end
  return FPF.bindBarrage(name, down)
end

FPF.mtmsFrameBarrage = FPF.mtmsFrame
function FPF.mtmsFrame(dt, free)
  FPF.mtmsFrameBarrage(dt, free)
  guard("BARRAGE", FPF.barrageFrame)
end

FPF.missileBlastBarrage = FPF.missileBlast
function FPF.missileBlast(m, x, y, z, kind, who)
  local r = FPF.missileBlastBarrage(m, x, y, z, kind, who)
  if m and m.barrage and P.fxOn then FPF.effectFor(FPC.barrage.fx.boom, x, y, z, FPC.barrage.fx.boomLife) end
  return r
end

FPF.coreFireSeam = FPF.coreFire
function FPF.coreFire(by)
  if not FPF.allowed("core") then return false end
  return FPF.coreFireSeam(by)
end

-- The class's damage multiple (a mission's difficulty) on everything BT takes: the hits the frame gathered (H.pend, the larger of
-- the two tags) are scaled once, before the controller's own layers turn them into points (FPF.health). Its shield's regeneration
-- multiple stretches the wait after a hit and the refill (FPC.health's shieldDelay, which the armor perk sets every perk poll, and
-- shieldTime) for that one call, and puts them back after it, raised or not.
FPF.healthSeam = FPF.health
function FPF.health(dt, alone)
  local H, M = PS.hp, FPF.mission
  local k, r = M.harm, M.regen
  if H and k ~= 1.0 then
    H.pend.a, H.pend.b = H.pend.a * k, H.pend.b * k
  end
  if r == 1.0 then return FPF.healthSeam(dt, alone) end
  local K = FPC.health
  local delay, time = K.shieldDelay, K.shieldTime
  K.shieldDelay, K.shieldTime = delay * r, time * r
  local ok, err = pcall(FPF.healthSeam, dt, alone)
  K.shieldDelay, K.shieldTime = delay, time
  if not ok then error(err, 0) end
end

-- Open77: an event the author handed to the delay system (DelaySystem.DelayEvent: the ragdoll's impulse, 0.12 s after the
-- ragdoll) is queued here and sent by FPF.laterFlush, which the bridge runs after every update, once its delay has passed.
-- DelayEvent with a delay reads the script function that called it, and a call from Lua through Open77.rtti has none: the game
-- read address 0x8 and crashed (Cyberpunk2077.exe+0x9E3AA9, at every ragdoll that ran; Open77's
-- docs/research/bt7274-playable-replication.md, 2026-11-04). An event whose body is gone, or that came due more than
-- `keep` seconds ago (frames cut), is dropped; so is everything when the session ends.
FPC.later = { keep = 2.0 }
FPF.laterQueue = {}

function FPF.later(ent, evt, delay)
  local Q = FPF.laterQueue
  Q[#Q + 1] = { ent = ent, evt = evt, at = S.clock + delay }
end

function FPF.laterPending()
  return FPF.laterQueue[1] ~= nil
end

function FPF.laterFlush()
  local Q = FPF.laterQueue
  if Q[1] == nil then return end
  if S.gone then
    FPF.laterQueue = {}
    return
  end
  local kept, now = {}, S.clock
  for i = 1, #Q do
    local E = Q[i]
    if now < E.at then
      kept[#kept + 1] = E
    elseif now - E.at <= FPC.later.keep then
      pcall(function() if IsDefined(E.ent) then E.ent:QueueEvent(E.evt) end end)
    end
  end
  FPF.laterQueue = kept
end

-- LightRP's keys. Its quick items take the number keys, so Burst Core's default is Y, not the mod's 5: a core key still on the
-- mod's default is moved, checked every `every` seconds (a Mod Settings save writes the stored keys back); any other key the
-- player chose in Mod Settings is left alone. Y is also Flight Strike's default, and Flight Strike spends the core: when the
-- two share a key, a class with FLIGHT STRIKE (its lock and its perk) takes the press as the flight strike, any other as the
-- core. Only the Mod Settings keys of FPF.forwarded are sorted; a script's `input` names its control itself.
FPC.lightKeys = { core = { from = "IK_5", to = "IK_Y" }, every = 2.0 }

FPF.keysSystemSeam = FPF.keysSystem
function FPF.keysSystem()
  local sys = FPF.keysSystemSeam()
  local M, K = FPF.mission, FPC.lightKeys
  if sys and (M.keysAt == nil or S.clock - M.keysAt >= K.every) then
    M.keysAt = S.clock
    local ok, err = pcall(function()
      if sys.coreKey == Enum.new("EInputKey", K.core.from) then
        sys.coreKey = Enum.new("EInputKey", K.core.to)
        log("MISSION: Burst Core's key moved from 5 to Y (LightRP's quick items use the number keys)")
      end
    end)
    if not ok then once("lightcorekey", "MISSION: Burst Core's key could not be moved to Y: " .. tostring(err)) end
  end
  return sys
end

-- The one of "core" and "flight" a press of their shared key is not for, or nil when they do not share a key.
function FPF.sharedKeyDrop()
  local sys = FPF.keysSystem()
  local same = false
  if sys then pcall(function() same = sys.coreKey == sys.flightKey end) end
  if not same then return nil end
  if FPF.allowed("flight") and FPF.perk("flight") >= 1 then return "core" end
  return "flight"
end

FPF.forwardedSeam = FPF.forwarded
function FPF.forwarded(B)
  local names, down = B.keyNames, B.keyDown
  local drop = nil
  for i = 1, #names do
    if names[i] == "core" or names[i] == "flight" then
      drop = FPF.sharedKeyDrop()
      break
    end
  end
  if drop == nil then return FPF.forwardedSeam(B) end
  local keptNames, keptDown = {}, {}
  for i = 1, #names do
    if names[i] ~= drop then keptNames[#keptNames + 1], keptDown[#keptDown + 1] = names[i], down[i] end
  end
  return FPF.forwardedSeam({ ends = B.ends, actionNames = B.actionNames, actionKinds = B.actionKinds, actionValues = B.actionValues,
    keyNames = keptNames, keyDown = keptDown, hits = B.hits })
end

-- The ultimates of a mission class (the owner's call, 2026-11-04). While a class is set:
--   * the core holds one charge (FPF.coreMax is the shot's cost, FPF.coreShot): a burst spends all of it, where the authored
--     ceiling of two charges chained one burst into the next; kills while a core burns add nothing (FPF.coreGain's own gate on
--     C.left, and FLIGHT STRIKE's immunity);
--   * BURST CORE fires the XO-16 and the Predator `rate` times as fast (FPC.perk.core.rate; the authored 1.35) and SWORD CORE
--     swings `swordRate` times as fast (FPC.sword.core.rate; the authored 1.3); the rest of each core is the authored one;
--   * BERSERKER CORE (the fists' core): a blow that lands launches whoever it met (FPF.ragdollPush149, away from BT, `up` of the
--     push upwards, `power` of it) instead of the blow's stagger, a boss excepted; a launch whose ragdoll could not be asked
--     falls back on the stagger. The shock blast, the toss and the electric blows keep their own. The first `lines` launches
--     are written to the Open77 log whatever the controller's own log says (OP77.logLine), with whether the ragdoll was
--     asked: that it was asked is not that the body flew (Open77 decides whether it has a ragdoll). Its damage is the
--     mission's price of the core's record.
-- Without a class the authored values are back.
FPC.missionCore = { rate = 3.0, swordRate = 3.0, launch = { power = 420.0, up = 0.55, lines = 6 },
  authored = { rate = FPC.perk.core.rate, swordRate = FPC.sword.core.rate } }

FPF.classSetCore = FPF.classSet
function FPF.classSet(class)
  FPF.classSetCore(class)
  local K, on = FPC.missionCore, FPF.mission.className ~= nil
  FPC.perk.core.rate = on and K.rate or K.authored.rate
  FPC.sword.core.rate = on and K.swordRate or K.authored.swordRate
end

FPF.coreMaxMission = FPF.coreMax
function FPF.coreMax()
  if FPF.mission.className ~= nil and FPF.perk("burstcore") >= 1 then return (FPF.coreShot()) end
  return FPF.coreMaxMission()
end

-- In a mission class the core fills from the server's kill credits alone (gameplay.creditKill, one per kill the mission
-- confirms): the controller's own reading of a killing blow, a vehicle blown up or a turret broken would charge it a second
-- time for the same kill, or for what the mission does not count.
FPF.coreKillMission = FPF.coreKill
function FPF.coreKill(evt, tag)
  if FPF.mission.className ~= nil then return end
  return FPF.coreKillMission(evt, tag)
end

FPF.coreVehicleMission = FPF.coreVehicle
function FPF.coreVehicle(veh)
  if FPF.mission.className ~= nil then return end
  return FPF.coreVehicleMission(veh)
end

FPF.coreDeviceMission = FPF.coreDevice
function FPF.coreDevice(dev)
  if FPF.mission.className ~= nil then return end
  return FPF.coreDeviceMission(dev)
end

function FPF.berserkLaunch(who)
  if not who or not IsDefined(who) then return false end
  local vehicle, worth, p = false, nil, nil
  pcall(function() vehicle = who:IsVehicle() == true end)
  if vehicle then return false end
  pcall(function() local _, w = FPF.coreWorth(who); worth = w end)
  if worth == "a boss" then return false end
  pcall(function() p = who:GetWorldPosition() end)
  if not p then return false end
  local K = FPC.missionCore.launch
  local dx, dy = p.x - PS.x, p.y - PS.y
  local d = math.sqrt(dx * dx + dy * dy)
  if d < 0.1 then
    local r = math.rad(S.yaw)
    dx, dy, d = -math.sin(r), math.cos(r), 1.0
  end
  local flat = math.sqrt(1.0 - K.up * K.up)
  FPF.ragdollAsked = who   -- the bridge lets this one NPC have the controller's ragdoll (open77_titan_bridge.lua)
  local ok, pushed = pcall(FPF.ragdollPush149, who, p.x, p.y, p.z + 1.0, dx / d * flat, dy / d * flat, K.up, K.power)
  FPF.ragdollAsked = nil
  if not ok then error(pushed, 0) end
  local asked = pushed == true
  PS.berserkLaunches = (PS.berserkLaunches or 0) + 1
  if PS.berserkLaunches <= K.lines then
    OP77.logLine(string.format("BERSERKER CORE: %s %s", personText(who),
      asked and "launched (its ragdoll asked)" or "not launched: its ragdoll could NOT be asked, staggered instead"))
  end
  return asked
end

FPF.fistStaggerBerserk = FPF.fistStagger
function FPF.fistStagger(who, kind, level)
  if kind ~= "blast" and kind ~= "electric" and kind ~= "toss" and FPF.mission.className ~= nil and PS.weapon == "fist"
    and FPF.coreOn() and FPF.berserkLaunch(who) then
    return 1
  end
  return FPF.fistStaggerBerserk(who, kind, level)
end

-- LightRP: no PROTOCOLS (the owner's decision, 2026-11-04). Every part of them reads this switch at run time: no lamp is lit,
-- drawn or sent to the HUD page (open77_titan_hud.lua), no hit BT takes is cut by them, no FULL LINK EMP or voice line.
P.protocols159 = false

-- Open77 Titan integration: hands the controller's file-local entry points to the bridge module (it was part of the generated
-- controller and is kept by hand now); the table is the complete list of what the bridge touches.
do
  local attached, why = pcall(OP77.attach, {
    S = S, PS = PS, PF = PF, P = P, C = C, FPF = FPF, FPC = FPC, XO16 = XO16, UNITS = UNITS, MOD = MOD, TAG = TAG,
    VERSION = VERSION, EMBARK_RANGE = EMBARK_RANGE, AHEAD = AHEAD, BACK = BACK, SPRINT = SPRINT, PILOT_ENT = PILOT_ENT,
    TF = TF, DASH = DASH,
    log = log, guard = guard, clamp = clamp, restrict = restrict, inGame = inGame, viewOfV = viewOfV,
    spawnPilot = spawnPilot, deletePilot = deletePilot, startPilot = startPilot, startEmbark = startEmbark,
    startDismount = startDismount, stopDrive = stopDrive, findPilot = findPilot,
  })
  if not attached then print("[" .. MOD .. "] Open77 Titan integration could not attach: " .. tostring(why)) end
end

return { version = VERSION, settings = C, units = UNITS, pilot = P, state = PS,
  gait = { strideOf = strideOf, angleFor = angleFor, blendFor = blendFor, runSpeed = runSpeed, step = pilotStep,
    ahead = AHEAD, back = BACK, sprint = SPRINT, dash = DASH, tf = TF, turns = TURNS, turnAt = turnAt,
    grids = GRIDS, settle = SETTLE, scenes = SCENES, runs = PILOT_RUNS, embarkRange = EMBARK_RANGE,
    xo16 = XO16, viewLevel = VIEW_LEVEL, rayCylinder = rayCylinder, warmSteps = WARM_STEPS, warmFrames = WARM_FRAMES,
    reload = RELOAD, reloadCut = RELOAD_CUT, zoom = ZOOM, embarkBlend = EMBARK_BLEND, startBlend = START_BLEND, sprintFire = SPRINT_FIRE,
    useHold = USE_HOLD, podsUp = PODS_UP, podsDown = PODS_DOWN, sceneHip = SCENE_HIP, muzzleRest = MUZZLE_REST },
  first = PF, fp = FP, fpc = FPC, fpf = FPF, punch = PUNCH, punchClip = PUNCH_CLIP, session = S }
